// GridSim CLI
//   GridSim.Cli                 -> UK reduced model, running live (Ctrl+C / any key to stop)
//   GridSim.Cli --once          -> solve the UK model once and print it
//   GridSim.Cli --ticks N       -> run N live ticks then exit (headless)
//   GridSim.Cli case9           -> IEEE 9-bus benchmark (single solve)
//   GridSim.Cli case14|case30|case57|case118|case300|case145|case24|cigre -> built-in MATPOWER cases
//   GridSim.Cli <file>.m        -> any MATPOWER .m case (also: --mpc <file>.m)
//   GridSim.Cli bench [--runs N] [--parallel N] -> dense-vs-sparse convergence table over every case
//   GridSim.Cli nminus1-sweep <case|--all> [--parallel N] [--sample N] -> full parallel N-1 branch sweep
//   GridSim.Cli cycle <case|--dir d> [--window-ms 1000] [--workers N] [--cycles K] [--shards N]
//                               [--jobs n-1,harmonics,rocof,physics,watch] [--hold-steady] [--pipeline]
//                               -> real-time cycle: single-core NR base solve then a prioritised parallel
//                                  fan-out of every analysis; High completes each cycle, Low rotates to coverage
//   GridSim.Cli batchsolve [--count N] [--n M] [--runs K] [--gpu] -> batched dense solve of N same-sized
//                                  systems in one dispatch (GPU batched kernel, else CPU loop); verifies + times
//   GridSim.Cli stress <case|--all> [--from f --to f --step s] -> load-to-collapse (max loadability)
//   GridSim.Cli chain <case> --steps N [--mode fixed|ramp|daily] -> consecutive warm-started solves
//   GridSim.Cli transient <case|--cases suite> [--minutes 60 --dt-ms 1 --trip MW --trip-at S]
//                               -> headless demanding time-domain run: sim duration at a fine slice,
//                                  per-slice frequency + a time-series CSV + sampled --enableExport math
//   GridSim.Cli replay-event <id> [--catalog f] [--trace neso.csv] [--out dir]
//                               -> credibility gate: reproduce a RECORDED event's RoCoF/nadir with NO device
//                                  (baseline must be 'Reproduced' before any counterfactual is credible)
//   GridSim.Cli scenario --event <id> [--inertia 260,155,120,102,50] [--device f.json] [--corners best,worst]
//                               -> counterfactual sweep (inertia x device x corners) + inertia risk curve;
//                                  GATED behind a reproduced baseline (reproduce reality first)
//   GridSim.Cli h0-study --event <id> [--dir case] [--sync-inertia-scale 1,0.5,0.25,0] [--gfm-fraction 0,..,1]
//                               [--gfm-class C] [--gfl-class C] [--corners best,worst] [--out dir]
//                               -> H=0 counterfactual: scale REAL synchronous inertia toward zero x make the
//                                  converter fleet grid-forming; GFM forms a bounded RoCoF where all-GFL cannot
//                                  (fleet-routed, GATED behind a reproduced baseline)
//   GridSim.Cli fleet --event <id> [--units 1,100] [--total-inertia GVA] [--total-ffr GW] [--stagger S]
//                               -> single-vs-fleet: intrinsic inertia N-additive, FFR non-additive
//   GridSim.Cli evidence --event <id> [--device f.json] [--voll £/MWh] [--duration h] [--out dir]
//                               -> one dossier: recorded vs simulated vs counterfactual + risk curve + fleet
//                                  + avoided cost (grounded in the recorded LFDD shed, not marketing)
//   GridSim.Cli gda-replay (--series ts.json | --synth) [--case name] [--export-every N] [--out dir]
//                               -> historical grid STATE ESTIMATOR: replay a demand series through the solver,
//                                  reconstruct grid state per PAST timestamp (horizon-guarded, never nowcasting)
//   GridSim.Cli crossval <case|solve-export.json> [--tool pandapower] [--tol 9.09e-13] [--out dir]
//                               -> diff a GridSim solve against an independent pandapower solve (needs Python)
//   GridSim.Cli estimate <case> (--measurements <m.json> | --synth [--seed N] [--noise S]
//                               [--coverage-vm F] [--coverage-inj F] [--coverage-flow F])
//                               [--no-bad-data] [--tol 1e-8] [--max-iter N] [--out dir]
//                               -> WLS state estimation: fit the state to redundant measurements
//                                  (chi-square consistency + bad-data removal + observability report)
//   GridSim.Cli --dir <path>    -> a custom JSON case folder
//   GridSim.Cli trip [case] [gen] -> trip a generator, show RoCoF / nadir (case or --dir; default data/uk)
//   GridSim.Cli screen [case] [--top N] -> N-1 RoCoF screening: rank credible single losses vs the limits
//   GridSim.Cli nminus1 [case]  -> N-1 branch outage screening (case or --dir; default data/uk)
//   GridSim.Cli nminus2 [--candidates N] [--exhaustive] [--top N] -> N-2: pair the most-stressed outages
//   GridSim.Cli n-1-1  [--candidates N] [--exhaustive] [--top N] -> N-1-1: lose, redispatch, lose again
//   GridSim.Cli freq [csv]      -> NESO frequency stats + GB limit-breach scan
//   GridSim.Cli gda --fleet     -> GB fleet: inertia, secure the largest loss, RoCoF screening
//   GridSim.Cli synth           -> build + solve the synthetic GB-at-scale case, materialise as JSON
//   GridSim.Cli replay <run-dir> -> step a pre-solved run directory in the console
//   GridSim.Cli export [case] [out.json] [--dir d] -> write the solved model as a visualisation JSON
//   GridSim.Cli gpucheck        -> probe the available GPU compute backends
//   GridSim.Cli simdcheck       -> report the active CPU vector tier (AVX-512/AVX2/SSE2) the kernels dispatch to
//   GridSim.Cli physics-check <case> -> audit a solved state against the physical laws (energy/Ohm/Joule/KCL/KVL/S=VI/...)
//   GridSim.Cli conformance        -> sweep the physical-law audit across the whole case corpus -> conformance matrix (.md/.csv)
//   GridSim.Cli experimental <reciprocity|wave|trace|carbon> <case> -> opt-in experimental models
//   GridSim.Cli ptdf <case> --bus ID      -> power transfer distribution factors (which lines a bus injection flows on)
//   GridSim.Cli lodf <case> --branch IDX  -> line-outage distribution factors (how an outage redistributes)
//   GridSim.Cli dcopf <case> [--no-limits] -> DC optimal power flow: cheapest secure economic dispatch
//   GridSim.Cli dist3ph <feeder.json> [sweep|fault --bus ID|estimate --measurements m.json]
//                               -> EXPERIMENTAL unbalanced three-phase feeder (gridsim-dist3ph/1): sweep power flow,
//                                  sequence fault study, three-phase WLS estimate
//   GridSim.Cli domains [case|--dir d] -> distributed-inertia domain assignment report
//   GridSim.Cli stability [case] [--screen] [--fault-bus N] -> situational-awareness metrics (purchased time, MIF)
//   GridSim.Cli fit-frequency <trace.csv> --inertia GVA.s --demand MW --loss MW [--fit damping,responsive,governor] [--nominal-hz Hz]
//                               -> fit the swing model's nadir / recovery constants to a measured loss-of-infeed trace (R079)
//                                 (--scale F, --seed N, --out DIR, --oltc N, --iters N, --worst)

// GridSim is a data/evidence tool: every number we parse from a flag and every number we write to a
// CSV/JSON must be locale-independent. Pin the whole process to InvariantCulture up front so a
// comma-decimal machine can't (a) parse "--dt-ms 0.5" as 5.0 or (b) emit "1,2340" into a CSV that the
// invariant-culture importer then mis-columns.
System.Globalization.CultureInfo.DefaultThreadCurrentCulture = System.Globalization.CultureInfo.InvariantCulture;
System.Globalization.CultureInfo.CurrentCulture = System.Globalization.CultureInfo.InvariantCulture;

string baseDir = AppContext.BaseDirectory;
var rest = args.ToList();

// D-DOC-072: the one output policy (CliFiles, user manual ch. 19 "Output files"). Record, before anything runs, what this
// command line reads: every existing file it names (other than the value of an output flag), every case folder it names,
// and the bundled data/ folder next to the executable. No output may replace one of them.
CliFiles.Init(args, Path.Combine(baseDir, "data"));

// F02: `gridsim --version` prints the single release number (Directory.Build.props) and the git commit the binary
// was built from, then exits 0. Answered first, before the licence is resolved or any flag is checked, so a script
// or an installer can always ask which build it has. Form: "gridsim 1.95.111+<commit sha>".
if (rest.Contains("--version"))
{
    Console.WriteLine($"gridsim {GridSim.Core.BuildInfo.InformationalVersion}");
    Environment.Exit(0);
}

// F09 (October 2026): per-verb help. `gridsim help <verb>`, `gridsim <verb> --help` and `gridsim <verb> -h` print that
// verb's section of the CLI reference (user manual ch. 19, compiled into the binary: see VerbHelp.cs), with its usage,
// every flag and its default, and its exit codes, then exit 0. Answered here, before the licence and the flag gate, so
// help never needs a licence and is never refused as an unknown flag. A verb with modes takes the mode too
// (`gridsim bench --estimate --help`). Bare `gridsim help` is `gridsim --help` (the verb list below). `gridsim help
// <word>` for a word that is not a verb is a usage error (exit 2); `gridsim <anything else> --help` keeps printing the
// verb list, as it always did.
{
    bool helpToken = rest.Contains("--help") || rest.Contains("-h");
    if (rest.Count > 0 && rest[0].Equals("help", StringComparison.OrdinalIgnoreCase))
    {
        List<string> topic = rest.Skip(1).Where(t => t is not ("--help" or "-h")).ToList();
        if (topic.Count == 0)
            rest.Add("--help");   // bare `gridsim help`: answered by the verb list below
        else
        {
            string md = VerbHelp.LoadEmbedded();
            string? text = VerbHelp.Render(md, topic[0], topic.Skip(1).FirstOrDefault());
            if (text is null)
            {
                Console.Error.WriteLine($"error: no help for '{topic[0]}': it is not a gridsim verb. Run 'gridsim --help' for the verb list.");
                Environment.Exit(2);
            }
            Console.Write(text);
            Environment.Exit(0);
        }
    }
    else if (helpToken && rest.Count > 0)
    {
        string md = VerbHelp.LoadEmbedded();
        // The mode, if any: a later token that names a section of its own with the verb ("bench --estimate").
        string? mode = rest.Skip(1).FirstOrDefault(t => t.StartsWith("--", StringComparison.Ordinal) && t != "--help"
            && VerbHelp.Render(md, rest[0], t) is { } withMode && withMode.StartsWith($"gridsim {rest[0]} {t} ", StringComparison.OrdinalIgnoreCase));
        string? text = VerbHelp.Render(md, rest[0], mode);
        if (text is not null)
        {
            Console.Write(text);
            Environment.Exit(0);
        }
        // Not a verb (a case name, a flag first, a typo): fall through to the verb list.
    }
}

// Missing input file or folder = input error, exit 1 (user manual ch. 19), never a crash. A missing .m file or
// --dir folder used to escape as an unhandled FileNotFoundException / DirectoryNotFoundException: a stack trace and
// the runtime's crash code -532462766 (0xE0434352). Dozens of verbs load models (the bare <case>, <file>.m, --mpc
// and --dir forms, and every verb's own case argument), mostly through Gated.Dir / Gated.Matpower, and the batch
// verbs deliberately catch a failed load per case and carry on. So the loaders keep THROWING (a batch row still says
// LOAD FAIL and moves on), and this one process-wide net turns a missing-path exception that nothing caught into a
// clean one-line message and exit 1. It is registered first, before the --audit-log handler below, so an audited
// run that ends here is recorded through ProcessExit with exit=1. Only missing-path exceptions and CaseLoadException
// (a case that exists but whose content cannot be loaded, raised by Gated.Dir / Gated.Matpower) are converted: any
// other unhandled exception is a genuine defect and is left to crash loudly.
AppDomain.CurrentDomain.UnhandledException += (_, e) =>
{
    // GR-672: a missing ASSEMBLY (FileNotFoundException naming "Name, Version=..., Culture=...") is a broken install, a
    // GridSim defect, not the user's input error, so it is left to crash loudly like any other defect.
    bool missingAssembly = e.ExceptionObject is FileNotFoundException fnf
        && (fnf.FileName?.Contains(", Version=", StringComparison.Ordinal) == true
            || fnf.Message.StartsWith("Could not load file or assembly", StringComparison.Ordinal));
    if (!missingAssembly && e.ExceptionObject is FileNotFoundException or DirectoryNotFoundException or CaseLoadException)
    {
        Console.Out.Flush();
        Console.Error.WriteLine($"error: {((Exception)e.ExceptionObject).Message}");
        Environment.Exit(1);
    }
    // DOC-1 (D-DOC-001 / 002 class): a ForwardInferenceException is never a defect. It is the horizon guard refusing data
    // newer than 169 h, by design, and manual ch. 19 gives it one code on every verb: REJECTED and exit 2. Every known
    // site catches it itself with that message; this is the backstop, so a site that is missed (or added later) still
    // ends with the documented refusal instead of a crash. The message is the same text the sites print.
    if (e.ExceptionObject is ForwardInferenceException fie)
    {
        Console.Out.Flush();
        Console.Error.WriteLine($"REJECTED (forward inference): {fie.Message}");
        Environment.Exit(CliExit.Usage);
    }
    // D-DOC-072: the one output policy (CliFiles) refused a target: it would replace an input of the run (a case file,
    // a measurement set, a file of a case folder or of the bundled data folder) or it names a folder. Nothing was written
    // to that path. The command line named a wrong path, so it is a usage error: exit 2 with the reason, on every verb.
    if (e.ExceptionObject is OutputRefusedException ore)
    {
        Console.Out.Flush();
        Console.Error.WriteLine($"error: {ore.Message}");
        Environment.Exit(CliExit.Usage);
    }
    // F08: any other unhandled exception is a defect. It still crashes loudly (the runtime prints the stack and exits
    // non-zero; nothing here calls Exit), but first a crash log is written and its path printed, on every run, not
    // only on an --audit-log run.
    CrashReport.Write(e.ExceptionObject, args);
};

// Software licence (LICENSE.md), resolved once, fully offline - no network call, ever. Precedence:
// GRIDSIM_LICENCE env var, then the installed %LOCALAPPDATA%\GridSim\licence.gridsim file, then the free
// Personal tier. A key is installed with `gridsim --importLicence <file.gridsim>` (handled just below).
// Note: this is the SOFTWARE licence, distinct from the DNO --licence distribution-area selector.
string? importLicencePath = null;
{
    int li = rest.FindIndex(t => t == "--importLicence" || t.StartsWith("--importLicence=", StringComparison.Ordinal));
    if (li >= 0)
    {
        string t = rest[li];
        if (t.Contains('=', StringComparison.Ordinal)) { importLicencePath = t[(t.IndexOf('=', StringComparison.Ordinal) + 1)..]; rest.RemoveAt(li); }
        else { importLicencePath = li + 1 < rest.Count ? rest[li + 1] : null; rest.RemoveAt(li); if (importLicencePath is not null) rest.RemoveAt(li); }
        // D-DOC-007 / D-DOC-085: the value must be a file path. Three ways it was not, each now refused as a usage error
        // (exit 2, the shared "expected ... but got" message of every value flag, manual ch. 19 parsing rules):
        //   --importLicence=          an empty value crashed inside File.ReadAllText with an unhandled ArgumentException;
        //   --importLicence --once    the next token was taken as the file name even when it is a flag ("Could not read
        //                             licence file '--once'"), and the flag it swallowed was lost;
        //   --importLicence           as the last token, no value: the switch was dropped silently and the run went on
        //                             (into the interactive live view), as if no licence had been asked for.
        if (string.IsNullOrWhiteSpace(importLicencePath) || importLicencePath.StartsWith("--", StringComparison.Ordinal))
            FailFlag<string>("--importLicence", importLicencePath ?? "", "a licence file path (<file.gridsim>)");
    }
}
if (importLicencePath is not null)
    Environment.Exit(LicenceCli.Import(importLicencePath));

var licenceGate = GridSim.Core.Licensing.LicenceGate.Resolve();
Gated.Init(licenceGate, baseDir);

