// --help/-h must be answered, not rejected as an unknown flag: a script probing `--help` to detect a
// working install would otherwise get exit 2 from the self-referential unknown-flag message below.
if (rest.Contains("--help") || rest.Contains("-h"))
{
    Console.WriteLine("gridsim <verb> [args] - GridSim CLI. See docs/manual/0019 CLI reference.md (or the header of Program.cs) for the full flag list.");
    // R068: the complete verb list (CliHelpContractTests checks it against the dispatch and the manual).
    Console.WriteLine("run:        (none)=live UK model, <case|file.m>, --dir <path>, --mpc <file.m>, --once");
    Console.WriteLine("cases:      a built-in name, a JSON case folder, a MATPOWER .m file or a PSS/E .raw file (revisions 30, 33, 34, 35;");
    Console.WriteLine("            --allow-unmodelled reads one holding DC links, FACTS or induction machines GridSim does not model;");
    Console.WriteLine("            --psse-revision <n> for a file that does not say; --seq-data <file.seq> adds its sequence data;");
    Console.WriteLine("            --tap-control applies its automatic voltage-control taps, --shunt-control its switched shunts),");
    Console.WriteLine("            or a UCTE-DEF .uct file");
    Console.WriteLine("contingency: trip, screen, nminus1 (n-1), nminus2 (n-2), n-1-1 (nminus1minus1), nminus1-sweep, stress,");
    Console.WriteLine("            chain, cycle");
    Console.WriteLine("dynamics:   transient, freq, replay, replay-event, scenario, h0-study, fleet, evidence, domains, stability,");
    Console.WriteLine("            modal, fit-frequency, emt, impedance-stability, inertia-placement");
    Console.WriteLine("analysis:   harmonics, fault, iec60909, protection-check, physics-check, conformance, ptdf, lodf, dcpf, dcopf, acopf,");
    Console.WriteLine("            acopf-full, scuc, scopf, cpf, taps, restore, losses, grade, dist3ph, pf, qsts, hosting,");
    Console.WriteLine("            experimental, estimate, estimate-noise-floor, crossval");
    Console.WriteLine("data:       gda, gda-replay, synth, export, serve, interpose, convert, validate, zonal, pmu-ingest, pmu-estimate");
    Console.WriteLine("tools:      bench, simdcheck, gpucheck, batchsolve, licence, audit, compliance, ref, help");
    // F09: every verb has its own help (its section of the CLI reference, compiled into the binary).
    Console.WriteLine("verb help:  gridsim <verb> --help (or gridsim help <verb>) prints the verb's usage, flags, defaults and exit codes.");
    // F10: the shared result writer.
    Console.WriteLine("results:    --json <file>, --csv <file> or --out <file.json|file.csv> write a verb's result to a file (see each verb's help).");
    // F15: acopf is labelled honestly here too (a line with no group label, so it is not read as a verb list).
    Console.WriteLine("note:       acopf is a DC-OPF dispatch with an AC loss loop, not a full AC-OPF (no voltage or reactive limits);");
    Console.WriteLine("            acopf-full is the full AC optimal power flow (voltages, reactive power and branch MVA limits).");
    Console.WriteLine("global: --importLicence <file.gridsim> installs a software licence (see the licence verb).");
    Console.WriteLine("global: --version prints the release number and the git commit of this build.");
    Environment.Exit(0);
}

// Software-licence verb: status / import / path. Handled here (before flag/verb dispatch) because its
// arguments are subcommands and a file path, not flags.
if (rest.Count > 0 && rest[0] == "licence")
    Environment.Exit(LicenceCli.Run(rest, licenceGate));

// Electrical word references (2026-10-24): a subcommand and one value, handled here for the same reason as licence.
// Pure (no case, no licence, no network): encode / decode / scatter / from-id (RefCli).
if (rest.Count > 0 && rest[0] is "ref")
    Environment.Exit(RefCli.Run(rest));

// Normalise "--name=value" into "--name" "value" for ordinary flags so an '='-form flag is validated by
// the gate and parsed by FlagDouble/FlagInt/FlagString/Positionals exactly like the spaced form (otherwise
// "--ticks=500" bypassed both the gate and every parser, silently substituting the default and even making
// Positionals swallow the next token). The few flags that intentionally support the attached '=' form are
// left intact and validated by name below.
var equalsFormFlags = new HashSet<string>(StringComparer.Ordinal)
{
    "--gpu", "--inertia-model", "--asset-dynamics", "--forming",
    "--forming-inertia", "--forming-damping", "--enableExport",
};
for (int i = 0; i < rest.Count; i++)
{
    string tok = rest[i];
    if (!tok.StartsWith("--", StringComparison.Ordinal)) continue;
    int eq = tok.IndexOf('=');
    if (eq <= 0 || equalsFormFlags.Contains(tok[..eq])) continue;
    rest[i] = tok[..eq];
    rest.Insert(i + 1, tok[(eq + 1)..]);
    i++;   // skip the value we just inserted
}

foreach (string tok in rest)
{
    // GR-683 (October 2026): a single-dash word ("-bus 5", "-top") is a mistyped flag. Both flag gates look only at
    // "--" tokens, so it used to pass as a positional argument and surface, if at all, as a confusing "too many cases"
    // or an unknown-case error, or be ignored. It is refused here, naming the double-dash spelling. A negative number
    // ("-5", "-0.25", "-.5": a dash then a digit or a point) is a value and passes, as do the two documented short
    // aliases -h (help) and -d (--dir), and a lone "-"; so does anything that reads as a number ("-Infinity", which the
    // number flags then refuse with their own message).
    if (tok.Length >= 2 && tok[0] == '-' && tok[1] != '-' && char.IsAsciiLetter(tok[1]) && tok is not ("-h" or "-d")
        && !double.TryParse(tok, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out _))
    {
        Console.Error.WriteLine($"error: unknown option '{tok}': flags start with two dashes (did you mean '-{tok}'?). " +
            $"Run 'gridsim --help' for the verb list, or see {VerbHelp.ChapterPath}.");
        Environment.Exit(CliExit.Usage);
    }
    if (!tok.StartsWith("--", StringComparison.Ordinal)) continue;
    int eq = tok.IndexOf('=');
    string name = eq > 0 ? tok[..eq] : tok;   // only the intentional '='-form flags still carry '=' here
    if (!knownFlags.Contains(name))
    {
        // N055 / F09: point at the verb's own help when the first token is a verb, and at the manual chapter (the old
        // text named docs/cli-reference, a stub that only redirected to the manual and has now been removed).
        string flagHelp = rest.Count > 0 && VerbHelp.HasTopic(VerbHelp.LoadEmbedded(), rest[0])
            ? $"Run 'gridsim {rest[0]} --help' for the flags {rest[0]} takes"
            : "Run 'gridsim --help' for the verb list";
        Console.Error.WriteLine($"error: unknown flag '{tok}' (misspelled?). {flagHelp}, or see {VerbHelp.ChapterPath}.");
        Environment.Exit(2);
    }
}

// Backend switch tokens (D-DOC-048, October 2026): --cpu and --gpu[=vendor] are global switches that may come before the
// verb ("gridsim --cpu dcopf case9 --prices"). They used to be removed from the argument list only AFTER the verb-scoped
// flag checks below (--prices, --costs, --global-vlimits, --post-fault-rating, --outage-types, --audit-log), which read
// rest[0] as the verb, so with the switch first rest[0] was "--cpu" and a valid flag was refused as belonging to another
// verb. They are taken off here, before every such check; the spec is validated and the backend chosen further down,
// exactly as before.
rest.Remove("--cpu");
string? gpuSpec = null;
int gpuIdx = rest.FindIndex(t => t == "--gpu" || t.StartsWith("--gpu=", StringComparison.Ordinal));
if (gpuIdx >= 0) { string t = rest[gpuIdx]; rest.RemoveAt(gpuIdx); gpuSpec = t.Contains('=') ? t[(t.IndexOf('=') + 1)..] : "auto"; }

// N187 (D2 nominal frequency, October 2026; Ruling R1: Mark delegated EE calls 2026-10-04): --frequency-hz <Hz> declares
// the nominal frequency of every MATPOWER .m file this run loads. A .m file carries no system frequency, so without it the
// case is assumed to be 50 Hz (stated in a parse note on stderr); a 60 Hz case (the IEEE and WSCC systems) needs it for its
// dynamic studies (modal, stability and CCT, EMT, impedance scans, IEC 60909) to run at the right f0. It changes no power
// flow, OPF or estimation number (the frequency enters none of them). Global like --cpu: it may stand anywhere on the
// line, is taken off here, and is handed to the one MATPOWER loader (Gated.Matpower / MatpowerDetailed). A JSON case
// folder carries its own frequencyHz and a built-in case name its own frequency, so the flag does not touch them; when
// the run loads no .m file at all, a warning says the flag had no effect (it cannot be refused up front, because which
// files a verb loads is only known as it runs). Fail loud on the value: it must be a finite number above 0 Hz, given once.
{
    int fi = rest.IndexOf("--frequency-hz");
    if (fi >= 0)
    {
        if (fi + 1 >= rest.Count || rest[fi + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<double>("--frequency-hz", "", "a nominal frequency in Hz (for example 50 or 60)");
        string fv = rest[fi + 1];
        if (!double.TryParse(fv, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double fHz)
            || !double.IsFinite(fHz) || !(fHz > 0.0))
            FailFlag<double>("--frequency-hz", fv, "a finite nominal frequency above 0 Hz (for example 50 or 60)");
        rest.RemoveRange(fi, 2);
        if (rest.Contains("--frequency-hz"))
        {
            Console.Error.WriteLine("error: --frequency-hz given more than once; a run declares one nominal frequency.");
            Environment.Exit(2);
        }
        Gated.DeclaredFrequencyHz = fHz;
        // Say so when the declaration reached nothing (no .m file was loaded), so nobody believes a 60 Hz study ran.
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            if (!Gated.DeclaredFrequencyApplied)
                Console.Error.WriteLine($"warning: --frequency-hz {fHz.ToString("R", System.Globalization.CultureInfo.InvariantCulture)} had no effect: this run " +
                    "loaded no MATPOWER .m file (a JSON case folder carries its own frequencyHz, a built-in case name its own frequency).");
        };
    }
}

// Tranche A (October 2026): --allow-unmodelled lets a PSS/E .raw file that holds in-service devices GridSim does not model
// (capacitor-commutated two-terminal, remote-regulating VSC, two-bus multi-terminal converters, FACTS in modes 4 to 8 or
// regulating a remote bus, induction machines)
// be read: those devices are read past and counted in a note on stderr, and the power flow differs from the file's.
// Without it such a file is refused (exit 1), naming each kind and its first line. Global like --frequency-hz; it applies
// to every .raw file this run loads, and when the run loads none, a warning says the flag had no effect.
if (rest.Remove("--allow-unmodelled"))
{
    if (rest.Contains("--allow-unmodelled"))
    {
        Console.Error.WriteLine("error: --allow-unmodelled given more than once.");
        Environment.Exit(2);
    }
    Gated.AllowUnmodelled = true;
    AppDomain.CurrentDomain.ProcessExit += (_, _) =>
    {
        if (!Gated.PsseLoaded && !Gated.UcteLoaded)
            Console.Error.WriteLine("warning: --allow-unmodelled had no effect: this run loaded no PSS/E .raw file.");
    };
}

// Tranche A (October 2026): --tap-control applies a PSS/E .raw file's automatic voltage control by tap (COD 1): every
// in-service controlled winding becomes an on-load tap changer the solve's tap loop steps from the file's ratio, and a
// case that does not converge from the file's taps is solved from a ramp start (SteadyStateSolver.LoadRampStages =
// Gated.TapControlRampStages: 10 %, 20 %, ... of its demand and generation first, the taps settling at each stage).
// Without it nothing changes: the taps stay at the file's ratios, as before. Global like --allow-unmodelled; when the run
// loads no .raw file a warning says the flag had no effect.
if (rest.Remove("--tap-control"))
{
    if (rest.Contains("--tap-control"))
    {
        Console.Error.WriteLine("error: --tap-control given more than once.");
        Environment.Exit(2);
    }
    Gated.ApplyTapControl = true;
    AppDomain.CurrentDomain.ProcessExit += (_, _) =>
    {
        if (!Gated.PsseLoaded)
            Console.Error.WriteLine("warning: --tap-control had no effect: this run loaded no PSS/E .raw file.");
    };
}

// Tranche A (October 2026): --shunt-control switches a PSS/E .raw file's switched shunts with discrete local voltage
// control (MODSW 1, one block size, BINIT a whole number of blocks) in whole blocks to hold their bus in VSWLO..VSWHI:
// the case solve runs SwitchedShuntPowerFlow inside the tap loop, and pf uses the banks as it uses a --switched-shunts
// file. Every other switched shunt stays fixed at BINIT, noted. Without it nothing changes. Global, given once; when the
// run loads no .raw file a warning says the flag had no effect.
if (rest.Remove("--shunt-control"))
{
    if (rest.Contains("--shunt-control"))
    {
        Console.Error.WriteLine("error: --shunt-control given more than once.");
        Environment.Exit(2);
    }
    Gated.ApplyShuntControl = true;
    AppDomain.CurrentDomain.ProcessExit += (_, _) =>
    {
        if (!Gated.PsseLoaded)
            Console.Error.WriteLine("warning: --shunt-control had no effect: this run loaded no PSS/E .raw file.");
    };
}

// Tranche A (October 2026): --psse-revision <n> is the revision a PSS/E .raw file is read as when its first line does not
// say (no REV field and no PSS/E-NN comment; the UKGDS distribution cases are such files, in the revision 30 layout).
// A file that says a different revision is refused. --seq-data <file.seq> applies a PSS/E sequence data file (revision
// 30 layout) to every .raw file this run loads, so fault and iec60909 get its machine reactances, line and transformer
// zero-sequence impedances and winding connections. Both global, given once, value checked here (exit 2); when the run
// loads no .raw file a warning says the flag had no effect.
{
    int pr = rest.IndexOf("--psse-revision");
    if (pr >= 0)
    {
        string revisions = string.Join(", ", Gated.PsseRevisions);
        if (pr + 1 >= rest.Count || rest[pr + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<int>("--psse-revision", "", $"a PSS/E revision ({revisions})");
        string pv = rest[pr + 1];
        if (!int.TryParse(pv, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out int revision)
            || !Gated.PsseRevisions.Contains(revision))
            FailFlag<int>("--psse-revision", pv, $"a supported PSS/E revision ({revisions})");
        rest.RemoveRange(pr, 2);
        if (rest.Contains("--psse-revision"))
        {
            Console.Error.WriteLine("error: --psse-revision given more than once.");
            Environment.Exit(2);
        }
        Gated.PsseRevision = revision;
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            if (!Gated.PsseLoaded)
                Console.Error.WriteLine("warning: --psse-revision had no effect: this run loaded no PSS/E .raw file.");
        };
    }
    int sq = rest.IndexOf("--seq-data");
    if (sq >= 0)
    {
        if (sq + 1 >= rest.Count || rest[sq + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<string>("--seq-data", "", "a PSS/E sequence data (.seq) file");
        string sv = rest[sq + 1];
        if (!sv.EndsWith(".seq", StringComparison.OrdinalIgnoreCase))
            FailFlag<string>("--seq-data", sv, "a PSS/E sequence data file whose name ends in .seq");
        rest.RemoveRange(sq, 2);
        if (rest.Contains("--seq-data"))
        {
            Console.Error.WriteLine("error: --seq-data given more than once; a run applies one sequence data file.");
            Environment.Exit(2);
        }
        Gated.SeqDataPath = sv;
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            if (!Gated.PsseLoaded)
                Console.Error.WriteLine("warning: --seq-data had no effect: this run loaded no PSS/E .raw file.");
        };
    }
}

// R075: --audit-log <file> records this run in the tamper-evident audit log (gridsim-audit/1, technical ch. 10).
// Accepted only on the verbs that produce evidence (estimate, crossval, interpose); on any other verb it is refused
// (exit 2) rather than ignored, so nobody believes a run was logged when it was not. The log is opened, and verified,
// BEFORE the verb does any work: a tampered, locked or misplaced log stops the run (exit 1). One entry is written when
// the process ends, whatever the path (normal return, early return, Environment.Exit from a flag check, an unhandled
// exception), and the anchor (entry count + head hash) is printed to stderr so it can be kept outside the log.
// The verbs add their inputs (by SHA-256) and a one-line outcome through auditRun; without the flag auditRun is null
// and nothing changes.
//
// D-DOC-060 (October 2026): `serve` is audited too. It runs the real-time estimator over recorded windows and produces
// estimates, the same kind of evidence as `estimate`, but it wrote no audit entry. The web host's resident estimator is
// audited the same way through the Audit:LogPath setting (src/GridSim.Web/Program.cs).
//
// D-DOC-062 (October 2026): the log is opened WITH its anchor (gridsim-audit-anchor/1): by default the file
// `<log>.anchor`, or `--audit-anchor <file>` to keep it elsewhere. Every run rewrites the anchor after its entry and the
// next run opens the log against it, so a tail-truncated (or restored, or rewritten) log is refused, exit 1, before
// anything is appended. Before, the log was opened with no anchor and new entries buried a truncation.
GridSim.Core.Diagnostics.AuditRunRecorder? auditRun = null;
{
    // D-DOC-062: --audit-anchor <file> is taken first; it only means something with --audit-log.
    string? auditAnchorPath = null;
    int an = rest.IndexOf("--audit-anchor");
    if (an >= 0)
    {
        if (an + 1 >= rest.Count || rest[an + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<string>("--audit-anchor", "", "an audit anchor file path");
        auditAnchorPath = rest[an + 1];
        rest.RemoveRange(an, 2);
        if (rest.Contains("--audit-anchor"))
        {
            Console.Error.WriteLine("error: --audit-anchor given more than once; a log has exactly one anchor file.");
            Environment.Exit(2);
        }
        if (!rest.Contains("--audit-log"))
        {
            Console.Error.WriteLine("error: --audit-anchor needs --audit-log (it names the anchor file of that log).");
            Environment.Exit(2);
        }
    }

    // NCSC CAF C1 wiring of the audit controls (each only with --audit-log):
    //   --audit-forward <file>     every entry is also appended, as one JSON line, to <file> (a SIEM collector's input or
    //                              a write-once mount): an independent copy against a joint rewrite of log and anchor.
    //   --incident-log <file>      security events are raised as incidents (one per significant event, one per burst)
    //                              and appended to <file> as JSON lines, for the deploying operator's reporting process.
    //   --audit-sign-key <pem>     ECDSA P-256 PRIVATE key: the anchor is signed after every entry (<log>.anchor.sig).
    //   --audit-verify-key <pem>   ECDSA P-256 PUBLIC key: the anchor's signature must exist and verify before the run
    //                              starts, or exit 1 (a log and anchor rewritten together without the key are refused).
    // A failure to forward or to write an incident never stops the run (the on-disk chain is authoritative), but it is
    // reported on stderr at the end and the run exits 1.
    string? TakeAuditFlag(string flag, string what)
    {
        int at = rest.IndexOf(flag);
        if (at < 0) return null;
        if (at + 1 >= rest.Count || rest[at + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<string>(flag, "", what);
        string value = rest[at + 1];
        rest.RemoveRange(at, 2);
        if (rest.Contains(flag))
        {
            Console.Error.WriteLine($"error: {flag} given more than once.");
            Environment.Exit(2);
        }
        if (!rest.Contains("--audit-log"))
        {
            Console.Error.WriteLine($"error: {flag} needs --audit-log.");
            Environment.Exit(2);
        }
        return value;
    }
    string? auditForwardPath = TakeAuditFlag("--audit-forward", "a file to forward audit entries to");
    string? incidentLogPath = TakeAuditFlag("--incident-log", "an incident log file path");
    string? auditSignKeyPath = TakeAuditFlag("--audit-sign-key", "a PEM ECDSA P-256 private key file");
    string? auditVerifyKeyPath = TakeAuditFlag("--audit-verify-key", "a PEM ECDSA P-256 public key file");
    int ai = rest.IndexOf("--audit-log");
    if (ai >= 0)
    {
        if (ai + 1 >= rest.Count || rest[ai + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<string>("--audit-log", "", "an audit log file path");
        string auditPath = rest[ai + 1];
        rest.RemoveRange(ai, 2);
        if (rest.Contains("--audit-log"))
        {
            Console.Error.WriteLine("error: --audit-log given more than once; a run is recorded in exactly one log.");
            Environment.Exit(2);
        }
        string auditVerb = rest.Count > 0 ? rest[0].ToLowerInvariant() : "";
        if (auditVerb is not ("estimate" or "crossval" or "interpose" or "serve"))
        {
            Console.Error.WriteLine($"error: --audit-log applies to estimate, crossval, interpose and serve only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
            Environment.Exit(2);
        }
        // Provenance of what the run produces: an estimate from a recorded measurement set is derived from recorded
        // data, one from --synth is synthetic; crossval compares two solves of a model (synthetic); interpose
        // receives live telemetry (recorded); serve estimates from recorded windows (derived from recorded, D-DOC-060).
        GridSim.Core.Diagnostics.ProvenanceTag auditProvenance = auditVerb switch
        {
            "estimate" => rest.Contains("--synth") ? GridSim.Core.Diagnostics.ProvenanceTag.Synthetic : GridSim.Core.Diagnostics.ProvenanceTag.DerivedFromRecorded,
            "crossval" => GridSim.Core.Diagnostics.ProvenanceTag.Synthetic,
            "serve" => GridSim.Core.Diagnostics.ProvenanceTag.DerivedFromRecorded,
            _ => GridSim.Core.Diagnostics.ProvenanceTag.Recorded,
        };
        GridSim.Core.Diagnostics.JsonLinesAuditSink? forwardSink = null;
        GridSim.Core.Diagnostics.Incident.JsonLinesIncidentSink? incidentSink = null;
        try
        {
            var sinks = new List<GridSim.Core.Diagnostics.IAuditSink>();
            if (auditForwardPath is not null)
                sinks.Add(forwardSink = new GridSim.Core.Diagnostics.JsonLinesAuditSink(auditForwardPath));
            if (incidentLogPath is not null)
                sinks.AddRange(GridSim.Core.Diagnostics.Incident.IncidentWiring.AuditSinksFor(
                    incidentSink = new GridSim.Core.Diagnostics.Incident.JsonLinesIncidentSink(incidentLogPath)));
            var auditOptions = new GridSim.Core.Diagnostics.AuditRecorderOptions
            {
                Sinks = sinks,
                AnchorSigningKey = auditSignKeyPath is null ? null : GridSim.Core.Diagnostics.AuditRecorderOptions.LoadKey(auditSignKeyPath, requirePrivate: true),
                AnchorVerificationKey = auditVerifyKeyPath is null ? null : GridSim.Core.Diagnostics.AuditRecorderOptions.LoadKey(auditVerifyKeyPath, requirePrivate: false),
            };
            auditRun = GridSim.Core.Diagnostics.AuditRunRecorder.Start(
                auditPath, GridSim.Core.Diagnostics.AuditEvent.DefaultActor(), auditVerb, auditProvenance, auditAnchorPath, auditOptions);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidOperationException or ArgumentException)
        {
            Console.Error.WriteLine($"error: --audit-log '{auditPath}': {ex.Message}");
            Environment.Exit(1);
        }
        GridSim.Core.Diagnostics.AuditRunRecorder recorder = auditRun!;
        // D-DOC-062: a log that already held entries but had no anchor file could not be checked for truncation this
        // time. The run goes on (the hashed entry records `audit-anchor=missing`), and the operator is told.
        if (recorder.AnchorWasMissing)
            Console.Error.WriteLine($"warning: audit log '{recorder.FilePath}' has entries but no anchor file '{recorder.AnchorPath}'; " +
                "tail truncation before this run cannot be detected. Verify it against an anchor you kept (gridsim audit verify " +
                "--anchor-count N --anchor-head H). The anchor is written from this run on.");
        void FinishAudit(int exitCode)
        {
            GridSim.Core.Diagnostics.AuditAnchor? anchor = recorder.Finish(exitCode);
            if (anchor is not null)
                Console.Error.WriteLine($"audit: {recorder.FilePath} entries={anchor.Count} head={anchor.HeadHash}" +
                    (recorder.SecurityEventCount > 0 ? $" security-events={recorder.SecurityEventCount}" : "") +
                    (recorder.SignsAnchor ? $" signed={recorder.SignaturePath}" : ""));
            if (recorder.AnchorWriteError is string anchorError)
                Console.Error.WriteLine($"error: audit anchor '{recorder.AnchorPath}' could not be updated ({anchorError}); keep the line above as the anchor.");
            // Secondary channels never stop the run, but their failure is reported and is an error exit.
            bool channelFailed = false;
            if (forwardSink?.LastError is string fwdError) { Console.Error.WriteLine($"error: {fwdError}"); channelFailed = true; }
            if (incidentSink?.LastError is string incError) { Console.Error.WriteLine($"error: {incError}"); channelFailed = true; }
            if (incidentSink is not null && incidentSink.Published > 0)
                Console.Error.WriteLine($"incidents: {incidentSink.Published} raised -> {incidentSink.FilePath}");
            if (channelFailed && Environment.ExitCode == 0) Environment.ExitCode = 1;
        }
        // A normal end and Environment.Exit both raise ProcessExit, with Environment.ExitCode already final.
        AppDomain.CurrentDomain.ProcessExit += (_, _) => FinishAudit(Environment.ExitCode);
        // An unhandled exception ends the process without a reliable ProcessExit: record it here, with the code the
        // .NET runtime exits with for an unhandled managed exception: 0xE0434352 on Windows, SIGABRT (134 as a shell
        // sees it) on Linux and macOS (GR-372: the Windows code used to be recorded on every OS).
        AppDomain.CurrentDomain.UnhandledException += (_, e) =>
        {
            recorder.SetOutcome($"unhandled={e.ExceptionObject.GetType().Name}");
            FinishAudit(OperatingSystem.IsWindows() ? unchecked((int)0xE0434352) : 134);
        };
    }
}

// NCSC CAF C1: record one security event as its own audit entry at the detection site (estimate, crossval, interpose
// and serve, the audited verbs). A no-op without --audit-log. A failure to record is loud: stderr and exit 1, because a
// detection the trail does not hold is a gap in the evidence.
void AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind kind, string reason)
{
    if (auditRun is null) return;
    try { auditRun.RecordSecurityEvent(kind, reason); }
    catch (Exception ex) when (ex is InvalidOperationException or IOException or UnauthorizedAccessException)
    {
        Console.Error.WriteLine($"error: audit: the {kind} security event could not be recorded: {ex.Message}");
        if (Environment.ExitCode == 0) Environment.ExitCode = 1;
    }
}

bool once = rest.Remove("--once");

// F17 / N092 (October 2026): the contingency verbs (nminus1, nminus2, n-1-1) judge each bus against its OWN voltage
// limits (MATPOWER VMIN / VMAX, JSON vminPu / vmaxPu) where the case gives them, and the operational band (0.94-1.06 pu)
// on any side a bus leaves unset.
//
// N092 (Ruling R1, Mark delegated 2026-10-04): this is now the DEFAULT. PSS/E ACCC, PowerWorld and MATPOWER's OPF all
// judge buses against the per-bus limits carried in the data; the global statutory band is the fallback. Until then it
// was opt-in through --bus-vlimits (F17), because every MATPOWER file carries those columns and using them moves
// verdicts on 9 bundled cases (re-pinned under the ruling; table in the r1-defaults notes).
//
//   --global-vlimits  restores the old view: every bus against the one operational band, per-bus data ignored.
//   --bus-vlimits     the old opt-in, now the default; still accepted (a no-op alias) so existing scripts keep working.
//
// Both are refused on every other verb rather than silently ignored, and giving both is a contradiction (exit 2).
bool busVlimitsFlag = rest.Remove("--bus-vlimits");
bool globalVlimits = rest.Remove("--global-vlimits");
// D-DOC-118 (October 2026): nminus1-sweep joins them. It screens the same N-1 outages through the same study set but
// judged every bus against the band, so on a case with per-bus limits it disagreed with nminus1 (case9.m: the sweep
// counted outages as violating that nminus1 called secure). It now takes the N092 default and --global-vlimits too.
bool contingencyVerb = rest.Count > 0 && rest[0].ToLowerInvariant() is "nminus1" or "n-1" or "nminus2" or "n-2" or "n-1-1" or "nminus1minus1" or "nminus1-sweep";
if (busVlimitsFlag && !contingencyVerb)
{
    Console.Error.WriteLine($"error: --bus-vlimits applies to nminus1, nminus2, n-1-1 and nminus1-sweep only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
    Environment.Exit(2);
}
if (globalVlimits && !contingencyVerb)
{
    Console.Error.WriteLine($"error: --global-vlimits applies to nminus1, nminus2, n-1-1 and nminus1-sweep only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
    Environment.Exit(2);
}
if (busVlimitsFlag && globalVlimits)
{
    Console.Error.WriteLine("error: --bus-vlimits and --global-vlimits contradict each other: per-bus limits are the default (--bus-vlimits is "
        + "only kept as an alias for it); give --global-vlimits alone to judge every bus against the operational band.");
    Environment.Exit(2);
}
// True unless --global-vlimits: use each bus's own limits where the case gives them.
bool busVlimits = !globalVlimits;
// The contingency verbs below pass ContingencyAnalysis.StudyOptions with { PerBusVoltageLimits = busVlimits }. On a
// case with no per-bus limits that judges every bus against the band, exactly as before; with --global-vlimits it is a
// copy of the study set with every value unchanged, so the pre-N092 verdicts are reproduced bit for bit.

// F20 (October 2026): --post-fault-rating A|B|C makes the contingency verbs (nminus1, nminus2, n-1-1) judge each OUTAGE
// state's branch loading against rating A (the default, unchanged), B (short-term, MATPOWER RATE_B / JSON ratingBMva) or
// C (emergency, RATE_C / ratingCMva); the base case stays on rating A (NETS SQSS v2.10, docs/reference S036: pre-fault
// rating before a fault, paragraph 2.9.1; no "unacceptable overloading" beyond the time-related capability after one,
// paragraph 5.1.8). A branch with no B / C rating uses its A rating. Refused on every other verb.
PostFaultRating postFaultRating = PostFaultRating.RateA;
{
    int pfrAt = rest.IndexOf("--post-fault-rating");
    if (pfrAt >= 0)
    {
        if (!(rest.Count > 0 && rest[0].ToLowerInvariant() is "nminus1" or "n-1" or "nminus2" or "n-2" or "n-1-1" or "nminus1minus1"))
        {
            Console.Error.WriteLine($"error: --post-fault-rating applies to nminus1, nminus2 and n-1-1 only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
            Environment.Exit(2);
        }
        string pfrValue = FlagString(rest, "--post-fault-rating")!;
        postFaultRating = pfrValue.ToUpperInvariant() switch
        {
            "A" => PostFaultRating.RateA,
            "B" => PostFaultRating.RateB,
            "C" => PostFaultRating.RateC,
            _ => FailFlag<PostFaultRating>("--post-fault-rating", pfrValue, "A, B or C"),
        };
        rest.RemoveRange(pfrAt, 2);
    }
}
// F20: --outage-types branch,gen,bus belongs to nminus1 only (checked here so no other verb silently ignores it): any
// non-empty subset; the default is branch alone, the historical screen. Read by RunNMinus1 (outBranch / outGen / outBus).
if (rest.Contains("--outage-types") && !(rest.Count > 0 && rest[0].ToLowerInvariant() is "nminus1" or "n-1"))
{
    Console.Error.WriteLine($"error: --outage-types applies to nminus1 only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
    Environment.Exit(2);
}
bool outBranch = true, outGen = false, outBus = false;
int? nminus1BatchedLanes = null;   // N349 (CF5): set by nminus1 --batched-lanes (null: the sequential screen, as always)
{
    int otAt = rest.IndexOf("--outage-types");
    if (otAt >= 0)
    {
        string otValue = FlagString(rest, "--outage-types")!;
        outBranch = false;
        foreach (string part in otValue.Split(',', StringSplitOptions.TrimEntries))
        {
            switch (part.ToLowerInvariant())
            {
                case "branch": outBranch = true; break;
                case "gen": case "generator": outGen = true; break;
                case "bus": outBus = true; break;
                default: FailFlag<string>("--outage-types", otValue, "a comma list of branch, gen, bus"); break;
            }
        }
        rest.RemoveRange(otAt, 2);
    }
}
// N124 (October 2026, stream B3; Ruling R1: Mark delegated EE calls 2026-10-04): --outage-dispatch reference|droop|inertia
// chooses who picks up the power a generator or bus outage takes away: the reference bus (the default, the F20 screen
// unchanged; PSS/E ACCC dispatch "disabled", PowerFactory "as dispatched"), the remaining synchronous units by governor
// droop (MBase-weighted) or by inertia (H x MBase), within their limits. nminus1 only, and only with gen or bus outages:
// anywhere else it would change nothing, so it is refused (exit 2) rather than silently ignored.
OutageDispatch outageDispatch = OutageDispatch.ReferenceBus;
if (rest.Contains("--outage-dispatch"))
{
    if (!(rest.Count > 0 && rest[0].ToLowerInvariant() is "nminus1" or "n-1"))
    {
        Console.Error.WriteLine($"error: --outage-dispatch applies to nminus1 only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
        Environment.Exit(2);
    }
    string odValue = FlagString(rest, "--outage-dispatch")!;
    outageDispatch = odValue.ToLowerInvariant() switch
    {
        "reference" or "slack" => OutageDispatch.ReferenceBus,
        "droop" => OutageDispatch.GovernorDroop,
        "inertia" => OutageDispatch.Inertia,
        _ => FailFlag<OutageDispatch>("--outage-dispatch", odValue, "reference, droop or inertia"),
    };
    if (!outGen && !outBus)
    {
        Console.Error.WriteLine("error: --outage-dispatch shares the power a generator or bus outage takes away; add --outage-types with gen or bus.");
        Environment.Exit(2);
    }
    rest.RemoveRange(rest.IndexOf("--outage-dispatch"), 2);
}

// F19 (October 2026): --costs belongs to dcopf and acopf, --prices to dcopf and (N121, October 2026) acopf. Refused on
// every other verb rather than silently ignored (the same rule as --bus-vlimits above).
if (rest.Contains("--costs") && !(rest.Count > 0 && rest[0].ToLowerInvariant() is "dcopf" or "acopf"))
{
    Console.Error.WriteLine($"error: --costs applies to dcopf and acopf only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
    Environment.Exit(2);
}
// D-DOC-049 (October 2026, ruled by main): `chain` with storage takes --prices too (a price series, `synthetic` or a
// file: the input of the `price` and `lp` storage policies, StorageCli). The gate used to refuse it on chain, so the
// documented `--policy lp` could never run and `--policy price` idled for want of prices. dcopf / acopf keep their
// boolean --prices (LMPs). Every other verb still refuses it.
if (rest.Contains("--prices") && !(rest.Count > 0 && rest[0].ToLowerInvariant() is "dcopf" or "acopf" or "chain"))
{
    Console.Error.WriteLine($"error: --prices applies to dcopf, acopf and chain (with --bess) only (got '{(rest.Count > 0 ? rest[0] : "no verb")}').");
    Environment.Exit(2);
}
// Backend switch: --cpu (default), --gpu (AMD-first auto), or --gpu=rocm|opencl|cuda. D-DOC-048: the switch tokens are
// taken off the argument list near the top (see "Backend switch tokens" above), before any check that reads rest[0] as
// the verb; the spec is validated and the backend selected here, as before.
// R222: only the documented vendors are accepted; a typo such as --gpu=rcom used to fall into auto-detect.
if (gpuSpec is not null && !SolverBackend.IsKnownSpec(gpuSpec)) FailFlag<string>("--gpu", gpuSpec, "one of auto, cpu, rocm, opencl, cuda");
var backend = SolverBackend.Select(gpuSpec);
RunInfo.Backend = backend.Description;
// GR-671 (October 2026): an explicitly named vendor (--gpu=rocm, --gpu=opencl, --gpu=cuda) that has no usable device is
// refused with exit 2. It used to print one stderr line, run on the CPU and exit 0, so a script that asked for a GPU
// run got a CPU run reported as success. Auto-detect (--gpu, --gpu=auto) still falls back to the CPU, as documented: it
// asks for "a GPU if there is one". `bench` and `gpucheck` are exempt: they probe each vendor themselves and report an
// absent one in their output, which is their job.
string? explicitGpuVendor = gpuSpec?.Trim().ToLowerInvariant();
if (explicitGpuVendor is "rocm" or "opencl" or "cuda"
    && backend.Device == SolverBackend.Vendor.Cpu
    && !(rest.Count > 0 && rest[0].ToLowerInvariant() is "bench" or "gpucheck"))
{
    Console.Error.WriteLine($"error: --gpu={explicitGpuVendor} was asked for but no usable device of that kind was found; use --gpu (auto-detect, falls back to the CPU) or --cpu.");
    Environment.Exit(2);
}
// Inertia model switch: --inertia-model=lumped (default) | distributed (experimental multi-domain).
InertiaModel inertiaModel = InertiaModel.LumpedScalar;
int imIdx = rest.FindIndex(t => t == "--inertia-model" || t.StartsWith("--inertia-model=", StringComparison.Ordinal));
if (imIdx >= 0)
{
    string t = rest[imIdx]; rest.RemoveAt(imIdx);
    string spec;
    if (t.Contains('=')) spec = t[(t.IndexOf('=') + 1)..];
    // Only consume the next token as the value when it isn't itself a flag - otherwise a value-less
    // "--inertia-model" would silently eat the following flag (or the verb) and run lumped.
    else if (imIdx < rest.Count && !rest[imIdx].StartsWith('-')) { spec = rest[imIdx]; rest.RemoveAt(imIdx); }
    else spec = "";
    // Fail loud on a missing or unknown value rather than treating any garbage as lumped.
    inertiaModel = spec.Trim().ToLowerInvariant() switch
    {
        "lumped" or "lumped-scalar" or "scalar" => InertiaModel.LumpedScalar,
        "distributed" => InertiaModel.Distributed,
        _ => FailFlag<InertiaModel>("--inertia-model", spec, "'lumped' or 'distributed'"),
    };
}
// --asset-dynamics[=on|off]: opt into the authored per-asset dynamics fleet (inverter classes bound
// to the model). Default off, so every verb is unchanged; honored by 'trip'/'transient'. Fail loud on
// garbage rather than silently ignoring it.
bool enableAssetDynamics = false;
int adIdx = rest.FindIndex(t => t == "--asset-dynamics" || t.StartsWith("--asset-dynamics=", StringComparison.Ordinal));
if (adIdx >= 0)
{
    string t = rest[adIdx]; rest.RemoveAt(adIdx);
    string spec;
    if (t.Contains('=')) spec = t[(t.IndexOf('=') + 1)..];
    // GR-192: the next token is the flag's value only when it IS an on/off word; any other token (a case or generator
    // name) belongs to the verb, and the bare flag means "on". It used to take that token and refuse it.
    else if (adIdx < rest.Count && rest[adIdx].Trim().ToLowerInvariant() is "on" or "off" or "true" or "false" or "yes" or "no" or "1" or "0")
    { spec = rest[adIdx]; rest.RemoveAt(adIdx); }
    else spec = "on";   // bare flag = enable
    enableAssetDynamics = spec.Trim().ToLowerInvariant() switch
    {
        "on" or "true" or "yes" or "1" or "" => true,
        "off" or "false" or "no" or "0" => false,
        _ => FailFlag<bool>("--asset-dynamics", spec, "'on' or 'off'"),
    };
}

// --forming <none|vsm|droop>: opt into grid-forming frequency FORMATION. Default none = byte-identical
// classic COI path. --forming-inertia <GVA.s> sets the virtual former inertia Ev (required for vsm);
// --forming-damping <MW/Hz> sets the virtual former damping Dv. Parsed fail-loud like --inertia-model.
FormingMode formingMode = FormingMode.None;
int fmIdx = rest.FindIndex(t => t == "--forming" || t.StartsWith("--forming=", StringComparison.Ordinal));
if (fmIdx >= 0)
{
    string t = rest[fmIdx]; rest.RemoveAt(fmIdx);
    string spec;
    if (t.Contains('=')) spec = t[(t.IndexOf('=') + 1)..];
    else if (fmIdx < rest.Count && !rest[fmIdx].StartsWith('-')) { spec = rest[fmIdx]; rest.RemoveAt(fmIdx); }
    else spec = "";
    formingMode = spec.Trim().ToLowerInvariant() switch
    {
        "none" => FormingMode.None,
        "vsm" => FormingMode.Vsm,
        "droop" => FormingMode.Droop,
        _ => FailFlag<FormingMode>("--forming", spec, "'none', 'vsm' or 'droop'"),
    };
}
double formingInertiaMwS = 0.0;   // Ev, from --forming-inertia in GVA.s
int fiIdx = rest.FindIndex(t => t == "--forming-inertia" || t.StartsWith("--forming-inertia=", StringComparison.Ordinal));
if (fiIdx >= 0)
{
    string t = rest[fiIdx]; rest.RemoveAt(fiIdx);
    string spec;
    if (t.Contains('=')) spec = t[(t.IndexOf('=') + 1)..];
    else if (fiIdx < rest.Count && (!rest[fiIdx].StartsWith('-') || LooksNumeric(rest[fiIdx]))) { spec = rest[fiIdx]; rest.RemoveAt(fiIdx); }
    else spec = "";
    // Finite and not negative (ch. 19: numeric flags refuse NaN and Infinity). NaN slipped past the vsm "> 0" check
    // below and crashed deep in the forming kernel; Infinity gave a flat frequency that exited 0.
    if (!double.TryParse(spec.Trim(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double gvaS)
        || !double.IsFinite(gvaS) || gvaS < 0.0)
        FailFlag<double>("--forming-inertia", spec, "a finite number of GVA.s, 0 or more");
    formingInertiaMwS = gvaS * 1000.0;   // GVA.s -> MW.s
}
double formingDampingMwPerHz = 0.0;   // Dv, from --forming-damping in MW/Hz
int fdIdx = rest.FindIndex(t => t == "--forming-damping" || t.StartsWith("--forming-damping=", StringComparison.Ordinal));
if (fdIdx >= 0)
{
    string t = rest[fdIdx]; rest.RemoveAt(fdIdx);
    string spec;
    if (t.Contains('=')) spec = t[(t.IndexOf('=') + 1)..];
    else if (fdIdx < rest.Count && (!rest[fdIdx].StartsWith('-') || LooksNumeric(rest[fdIdx]))) { spec = rest[fdIdx]; rest.RemoveAt(fdIdx); }
    else spec = "";
    // Finite and not negative: a negative virtual damping destabilises the former, and NaN / Infinity mean nothing.
    if (!double.TryParse(spec.Trim(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out formingDampingMwPerHz)
        || !double.IsFinite(formingDampingMwPerHz) || formingDampingMwPerHz < 0.0)
        FailFlag<double>("--forming-damping", spec, "a finite number of MW/Hz, 0 or more");
}
// The two forming parameters mean something only with a former: refused without --forming (or with --forming none),
// instead of being accepted and silently ignored.
if ((fiIdx >= 0 || fdIdx >= 0) && formingMode == FormingMode.None)
{
    Console.Error.WriteLine("error: --forming-inertia and --forming-damping need --forming vsm or --forming droop; without a former they would be ignored.");
    Environment.Exit(2);
}
// A value written with a space that starts with '-' ("-50") is a value here when it is a number, not a stray flag.
static bool LooksNumeric(string s) => double.TryParse(s, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out _);
// Whether any forming flag or --asset-dynamics was given at all (the parsers above remove them from rest, so a verb
// that does not use them could not otherwise tell they were asked for). RequireVerbFlags uses these to refuse them
// on the event verbs that ignore them.
bool formingFlagsGiven = fmIdx >= 0 || fiIdx >= 0 || fdIdx >= 0;
bool assetDynamicsFlagGiven = adIdx >= 0;
// D-DOC-185: trip's --gb-services[=<scale>] (the GbResponseServices.Typical arrest layer). Declared here, with the other
// switches, so RunTrip sees it; it is parsed in the trip dispatch only (it is a trip flag, ch. 19).
double? gbServicesScale = null;
// R079 (stream F): trip's --band[=<fraction>] (FrequencySensitivitySweep, the nadir band over the unfitted swing constants).
// Parsed in the trip dispatch only, like --gb-services; null = no band, and the trip output is exactly as before.
double? tripBandFraction = null;
// R095 (stream F): trip's --envelope <spec> (AssetEnvelope.Sweep over asset-class control parameters, with --asset-dynamics).
// Set in the trip dispatch only; null = no envelope, and the trip output is exactly as before.
string? tripEnvelopeSpec = null;
// F stream: trip's --dyn-data line (the machine data file's inertia; see DynDataInertiaLine). Null without the flag.
string? tripMachineDataLine = null;
// vsm needs a virtual inertia to form the frequency; fail loud rather than throw deep in the kernel.
if (formingMode == FormingMode.Vsm && formingInertiaMwS <= 0.0)
{
    Console.Error.WriteLine("error: --forming vsm requires --forming-inertia <GVA.s> (> 0) - the virtual former inertia Ev.");
    Environment.Exit(2);
}
// N311 (LF4, Ruling R1): a droop former is a pure P-f droop with no virtual inertia, so --forming-inertia (any value,
// even 0) with --forming droop is refused by name rather than silently turning the droop run into a VSM run.
if (formingMode == FormingMode.Droop && fiIdx >= 0)
{
    Console.Error.WriteLine("error: --forming-inertia does not apply to --forming droop: a droop former is a pure P-f droop and "
        + "carries no virtual inertia. Drop --forming-inertia, or use --forming vsm for a former with virtual inertia.");
    Environment.Exit(2);
}

// --bfs routes the solve through the radial backward/forward-sweep distribution solver.
bool useBfs = rest.Remove("--bfs");
// --enableExport[=path]: dump the full math trace of one solve (Y-bus, per-unit spec, per-iteration
// mismatch/correction/Jacobian, Q-limit switching, converged state + flows) to JSON. --export-jacobian
// forces the (large) Jacobian past the size gate.
bool exportJac = rest.Remove("--export-jacobian");
// N251 (October 2026): --export-tight makes a solve export (--enableExport on a case) carry GridSim's TIGHTEST converged
// state instead of the state at the everyday 1e-8 pu stopping test, exactly as the crossval verb's own export does
// (N243): after the ordinary solve converges, the case is solved afresh with the same engine and options at 1e-9 ...
// 1e-15 pu and the tightest rung that converges is exported, with solve.tightenedTolerancePu saying which. Without the
// switch nothing changes (the same solve, the same bytes). It applies to the solve export only.
bool exportTight = rest.Remove("--export-tight");
bool doExport = false; string? exportJsonPath = null;
int exIdx = rest.FindIndex(t => t == "--enableExport" || t.StartsWith("--enableExport=", StringComparison.Ordinal));
if (exIdx >= 0) { string t = rest[exIdx]; rest.RemoveAt(exIdx); doExport = true; if (t.Contains('=')) exportJsonPath = t[(t.IndexOf('=') + 1)..]; }
if (exportTight && !doExport)
{
    Console.Error.WriteLine("error: --export-tight tightens the state a solve export writes, so it needs --enableExport (it would otherwise be silently ignored).");
    Environment.Exit(2);
}
int ticks = 0;
int ti = rest.IndexOf("--ticks");
if (ti >= 0)
{
    // Fail loud on a malformed --ticks: silently leaving ticks=0 dropped headless scripts into the interactive
    // infinite live loop on a typo (e.g. "5O") - the exact hang class the fail-loud flags eliminated.
    if (ti + 1 >= rest.Count || !int.TryParse(rest[ti + 1], System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out ticks))
        FailFlag<int>("--ticks", ti + 1 < rest.Count ? rest[ti + 1] : "", "an integer");
    // An EXPLICIT --ticks must be at least 1. Internally 0 means "interactive" (the default when the flag is absent),
    // so "--ticks 0" or a negative count used to drop a headless script into the interactive loop, where it waits for
    // a key press for ever. Interactive is what you get by leaving the flag out; asking for 0 or fewer ticks is a
    // usage error (exit 2).
    if (ticks < 1)
        FailFlag<int>("--ticks", rest[ti + 1], "a positive integer (leave --ticks out to run interactively)");
    rest.RemoveRange(ti, 2);
}

// --inertia-model distributed is only wired into 'trip' (full multi-domain integration) and 'transient'
// (reports domains, integrates lumped). Every other dynamics verb runs the lumped scalar model regardless,
// so warn rather than silently give a lumped answer under a distributed flag.
if (inertiaModel == InertiaModel.Distributed && rest.Count > 0 &&
    rest[0].ToLowerInvariant() is "evidence" or "scenario" or "h0-study" or "fleet" or "replay-event")
{
    Console.Error.WriteLine($"warning: --inertia-model distributed is not honored by '{rest[0]}' - it runs the " +
        "lumped scalar model. Only 'trip' integrates the distributed multi-domain model (and 'transient' " +
        "reports the speed-domain split but still integrates lumped).");
}
// Multi-domain forming is A2: any --forming run delegates to the lumped forming integrator, even under
// --inertia-model distributed. Warn so the combination is not mistaken for a distributed forming solve.
if (formingMode != FormingMode.None && inertiaModel == InertiaModel.Distributed)
{
    Console.Error.WriteLine("warning: --forming with --inertia-model distributed runs the LUMPED forming " +
        "integrator (multi-domain forming is a follow-up); the virtual former is not distributed as real mass.");
}

// F10 (October 2026): the shared result writer (CliResultWriter.cs). On the verbs that take it, --json <file.json>,
// --csv <file.csv> and --out <file.json|file.csv> are taken off the argument list here, before any verb parses its own
// arguments (so a flag's file name can never be mistaken for a positional case), and checked: a missing value, a wrong
// extension, the same flag twice or two flags naming one file exit 2. With no such flag CliOutput.Report stays null and
// nothing below changes. Each writer verb's dispatch calls CliOutput.Finish(args) after the verb returns, which writes
// the files when the verb completed its result. On the other verbs --json and --csv are refused (exit 2) instead of
// silently ignored, except modal's own --json and screen's own --csv.
CliOutput.TakeFlags(rest);

// N103 (October 2026): the shared per-verb flag check (VerbFlags.cs). The gate above refuses a flag no verb knows; this
// refuses a flag the verb itself does not take (one that belongs to another verb), which used to be silently ignored, so
// "trip --top 5" ran as if --top had not been given. A verb's flags are the ones its own section of the CLI reference
// (manual ch. 19, compiled in as the per-verb help) names, plus the global switches; anything else exits 2 naming the
// flag and pointing at `gridsim <verb> --help`. Runs after the global switches and the result-writer flags have been
// taken off and before any verb parses its arguments. The no-verb run (a case name or file first) is not affected.
{
    string? flagError = VerbFlags.Check(VerbHelp.LoadEmbedded(), rest,
        rest.Count > 0 && CliOutput.WriterVerbs.Contains(rest[0]));
    if (flagError is not null)
    {
        Console.Error.WriteLine(flagError);
        Environment.Exit(2);
    }
}

if (rest.Count > 0 && rest[0].Equals("freq", StringComparison.OrdinalIgnoreCase))
{
    string fp = SingleFilePositional("freq", rest) ?? Path.Combine(baseDir, "data", "neso", "frequency-sample.csv");
    PrintFrequency(fp);
    CliOutput.Finish(args);   // F10: write the result files, if asked for
    return;
}

if (rest.Count > 0 && rest[0].Equals("replay", StringComparison.OrdinalIgnoreCase))
{
    string fp = SingleFilePositional("replay", rest) ?? Path.Combine(baseDir, "data", "neso", "frequency-sample.csv");
    double sps = FlagDouble(rest, "--sps", 50);        // slices per second (50 = real time)
    // GR-698: a rate outside the controller's range used to be clamped without a word; it is refused (exit 2).
    if (!double.IsFinite(sps) || sps < GridSim.Core.Frequency.ReplayController.MinSlicesPerSecond || sps > GridSim.Core.Frequency.ReplayController.MaxSlicesPerSecond)
        FailFlag<double>("--sps", sps.ToString("R", System.Globalization.CultureInfo.InvariantCulture),
            string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"a rate of {GridSim.Core.Frequency.ReplayController.MinSlicesPerSecond} to {GridSim.Core.Frequency.ReplayController.MaxSlicesPerSecond} slices per second"));
    int seconds = FlagCount(rest, "--seconds", 600, 1);   // how many seconds of source to load (GR-698: at least 1; a negative value read nothing and reported "No data.")
    int frames = FlagCount(rest, "--frames", 0, 0);         // >0 = headless, run N slices then exit
    RunReplay(fp, sps, seconds, frames);
    return;
}

if (rest.Count > 0 && rest[0].Equals("gda", StringComparison.OrdinalIgnoreCase))
{
    RunGda(rest);
    return;
}

if (rest.Count > 0 && rest[0].Equals("synth", StringComparison.OrdinalIgnoreCase))
{
    // Build the synthetic GB-at-scale case (no licensed data), solve it, and
    // materialise it as a standard JSON case directory.
    var sopt = new GridSim.Core.Synthetic.SyntheticGb.Options
    {
        Seed = FlagInt(rest, "--seed", 20260605),
        Scale = FlagDouble(rest, "--scale", 1.0),
    };
    // N051: a scale that is not a positive finite number is a usage error (exit 2), not a quietly built smallest network.
    if (!(double.IsFinite(sopt.Scale) && sopt.Scale > 0))
        FailFlag<double>("--scale", sopt.Scale.ToString(System.Globalization.CultureInfo.InvariantCulture), "a finite number above 0");
    // N256 (October 2026): with no --out the case is written under results/ (results/synth/gb-synthetic), like every
    // other default output. It used to go to the bundled data/gb-synthetic beside the executable, so a plain `gridsim
    // synth --scale 0.5` silently replaced the shipped case in a release folder. Regenerating the shipped case is still
    // possible, but only on purpose: give --out data/gb-synthetic. A --out with no value is a usage error (exit 2); it
    // used to fall back to the bundled folder.
    string outDir = FlagString(rest, "--out") ?? DefaultResultsPath("synth", "gb-synthetic");

    GridModel synth = GridSim.Core.Synthetic.SyntheticGb.Build(sopt);
    Console.WriteLine($"GridSim  -  synthetic GB    {synth.BusCount} buses  {synth.Branches.Count} branches  " +
                      $"{synth.Generators.Count} generators  {synth.Oltcs.Count} OLTCs");
    Console.WriteLine($"  demand {synth.Buses.Sum(b => b.Pd) / 1000.0:F1} GW  inertia {synth.SystemInertiaGvaS:F0} GVAs");

    // Engine by the shared dense/sparse rule (SolverSelector via backend.Pick), like every other verb. It was always
    // sparse here, which a small --scale run did not need. The two Newton engines are bit-identical on the CPU, so
    // this changes speed and memory only, never a number.
    var ssolver = backend.Pick(synth);
    var spfOpt = new PowerFlowOptions { MaxIterations = FlagInt(rest, "--iters", 60), EnforceQLimits = rest.Contains("--qlimits") };
    PowerFlowResult sres = ssolver.Solve(synth, spfOpt, maxOltcPasses: FlagInt(rest, "--oltc", 30));
    double svMin = sres.Vm.Min(), svMax = sres.Vm.Max();
    Console.WriteLine(sres.Converged
        ? $"  converged ({sres.Iterations} NR, mismatch {sres.MaxMismatch:E1})  V {svMin:F3}-{svMax:F3} pu  losses {sres.TotalLossMw:F0} MW"
        : $"  DID NOT CONVERGE (mismatch {sres.MaxMismatch:E2})");
    if (!sres.Converged) Environment.ExitCode = 3;   // R022: a reported non-convergence is a failure, not exit 0

    if (!sres.Converged || rest.Contains("--worst"))
    {
        // name the offenders: spec vs solved injection per bus
        var pgAt = synth.Generators.GroupBy(g => g.Bus).ToDictionary(g => g.Key, g => g.Sum(x => x.Pg));
        var worst = new List<(double err, string what)>();
        for (int i = 0; i < sres.BusIds.Count; i++)
        {
            Bus bus = synth.Buses.First(b => b.Id == sres.BusIds[i]);
            if (bus.Type == BusType.Slack) continue;
            double specP = pgAt.GetValueOrDefault(bus.Id) - bus.Pd;
            double dP = Math.Abs(sres.PInjMw[i] - specP);
            worst.Add((dP, $"{bus.Name} ({bus.BaseKv:F1} kV) deltaP {dP:F1} MW  V {sres.Vm[i]:F3}"));
        }
        foreach ((double _, string what) in worst.OrderByDescending(w => w.err).Take(10))
            Console.WriteLine($"    {what}");
    }

    if (!sres.Converged)
    {
        // N051: say WHY a --scale has no solution. (Before N108 --scale thinned the 11 kV layer while every zone kept its
        // GB demand, so the demand behind each 33/11 kV transformer grew as the scale fell.) Report it against the transformers'
        // ratings (apparent demand at the secondary and any 6.6 kV pocket under it), so the failure reads as a property
        // of the generated data, not of the solver.
        var demandMva = synth.Buses.ToDictionary(b => b.Id, b => Math.Sqrt(b.Pd * b.Pd + b.Qd * b.Qd));
        var pocketUnder = new Dictionary<int, int>();
        foreach (Branch br in synth.Branches)
            if (br.Name is not null && br.Name.EndsWith(" 11/6.6", StringComparison.Ordinal)) pocketUnder.TryAdd(br.From, br.To);
        var pct = new List<double>();
        foreach (Branch br in synth.Branches)
        {
            if (br.Name is null || !br.Name.EndsWith(" 33/11", StringComparison.Ordinal) || br.RateAMva <= 0) continue;
            double d = demandMva[br.To] + (pocketUnder.TryGetValue(br.To, out int leg) ? demandMva[leg] : 0.0);
            pct.Add(d / br.RateAMva * 100.0);
        }
        if (pct.Count > 0)
        {
            pct.Sort();
            Console.WriteLine($"  {pct.Count} secondary (33/11 kV) transformers carry a median {pct[pct.Count / 2]:F0} % (max {pct[^1]:F0} %) of their rating in demand:");
            // N108: since October 2026 a scale below 1.0 shrinks each zone's demand with its 11 kV layer, so this line no
            // longer blames the scale; at 1.0 and above the scale spreads the same GB demand over more secondaries.
            Console.WriteLine("  --scale below 1.0 shrinks each zone's demand with its 11 kV layer, and above 1.0 spreads the same demand over more secondaries (1.0 gives a median near 63 %).");
        }
    }

    // N212: the writer is lossless for every field a JSON v1 case carries and returns a note for anything it cannot.
    foreach (string note in GdaModelWriter.WriteDirectory(synth, outDir, addGridInfeed: false))
        Console.Error.WriteLine("note: " + note);
    Console.WriteLine($"  written -> {Path.GetFullPath(outDir)}");
    return;
}

if (rest.Count > 0 && (rest[0].Equals("nminus1", StringComparison.OrdinalIgnoreCase) || rest[0].Equals("n-1", StringComparison.OrdinalIgnoreCase)))
{
    // Positional case or --dir (refused when they disagree); default data/uk. See SelectCase.
    // N349 (CF5): --batched-lanes N runs the branch outages through the batched sweep (R071, ScreenBranchesBatched):
    // N lanes post their Newton steps to one batched solve. Bit-identical to the sequential screen by construction (the
    // CPU batched backend is the same sparse LU per system), so every printed number is the same; only the speed and one
    // header line differ. 0 means one lane per processor. Checked before the case loads (a usage error is exit 2).
    if (FlagString(rest, "--batched-lanes") is string lanesText)
    {
        if (!int.TryParse(lanesText, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out int lanes)
            || lanes > ContingencyAnalysis.MaxBatchedLanes)
        {
            Console.Error.WriteLine($"error: nminus1 --batched-lanes must be a whole number from 0 (one lane per processor) to {ContingencyAnalysis.MaxBatchedLanes} (got '{lanesText}').");
            Environment.Exit(2);
        }
        nminus1BatchedLanes = lanes;
    }
    GridModel mm = LoadSelected("nminus1", SelectCase("nminus1", SingleCasePositional("nminus1", rest), rest, baseDir,
        "data/uk", () => LoadUkDefault(baseDir)));
    RunNMinus1(mm);
    CliOutput.Finish(args);   // F10: write the result files, if asked for
    return;
}

if (rest.Count > 0 && (rest[0].Equals("nminus2", StringComparison.OrdinalIgnoreCase) || rest[0].Equals("n-2", StringComparison.OrdinalIgnoreCase)))
{
    // The boolean flag comes off first, so Positionals cannot take the token after it for the flag's value.
    bool exhaustive = rest.Remove("--exhaustive");
    GridModel mm = LoadSelected("nminus2", SelectCase("nminus2", SingleCasePositional("nminus2", rest), rest, baseDir,
        "data/uk", () => LoadUkDefault(baseDir)));
    RunNMinus2(mm, FlagCount(rest, "--candidates", 20, 1), exhaustive, FlagCount(rest, "--top", 20, 0));
    CliOutput.Finish(args);   // F10: write the result files, if asked for
    return;
}

if (rest.Count > 0 && (rest[0].Equals("n-1-1", StringComparison.OrdinalIgnoreCase) || rest[0].Equals("nminus1minus1", StringComparison.OrdinalIgnoreCase)))
{
    bool exhaustive = rest.Remove("--exhaustive");   // boolean flag off first (see nminus2)
    GridModel mm = LoadSelected("n-1-1", SelectCase("n-1-1", SingleCasePositional("n-1-1", rest), rest, baseDir,
        "data/uk", () => LoadUkDefault(baseDir)));
    RunNMinus1Minus1(mm, FlagCount(rest, "--candidates", 20, 1), exhaustive, FlagCount(rest, "--top", 20, 0));
    CliOutput.Finish(args);   // F10: write the result files, if asked for
    return;
}

if (rest.Count > 0 && rest[0].Equals("screen", StringComparison.OrdinalIgnoreCase))
{
    GridModel ms = LoadSelected("screen", SelectCase("screen", SingleCasePositional("screen", rest), rest, baseDir,
        "data/uk", () => LoadUkDefault(baseDir)));
    string? csvPath = FlagString(rest, "--csv");   // present with no value fails loud (R219), like every other path flag
    RunScreen(ms, FlagCount(rest, "--top", 12, 0), csvPath);
    return;
}

if (rest.Count > 0 && rest[0].Equals("trip", StringComparison.OrdinalIgnoreCase))
{
    // gridsim trip [<case>] [<gen>] [--dir <folder>] [--export <csv>]
    // The free tokens are found with Positionals, which skips every flag AND the value it takes. The old code read
    // rest[1] only, so in "trip --dir data/uk Torness" the generator name (after the flag's value) was dropped and
    // the largest unit (Hinkley) was tripped instead of Torness.
    //   two free tokens: <case> <gen>;
    //   one free token:  a case when it names one (a case folder, a .m file, or a built-in name such as case14),
    //                    otherwise a generator name on the default (or --dir) model, as it always was;
    //   more than two:   refused (exit 2).
    // D-DOC-185: --gb-services, --gb-services=<scale> or --gb-services <scale> (a number). Taken off the list BEFORE
    // the positionals are found, because Positionals skips the token after every flag and a bare --gb-services would
    // otherwise swallow the generator name that follows it. The scale multiplies the EAC volumes; 1 when omitted.
    {
        int gbi = rest.FindIndex(t => t == "--gb-services" || t.StartsWith("--gb-services=", StringComparison.Ordinal));
        if (gbi >= 0)
        {
            string t = rest[gbi]; rest.RemoveAt(gbi);
            string spec = "1";
            if (t.Contains('=')) spec = t[(t.IndexOf('=') + 1)..];
            else if (gbi < rest.Count && double.TryParse(rest[gbi], System.Globalization.NumberStyles.Float,
                         System.Globalization.CultureInfo.InvariantCulture, out _)) { spec = rest[gbi]; rest.RemoveAt(gbi); }
            if (!double.TryParse(spec, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture,
                    out double gbScaleParsed) || !double.IsFinite(gbScaleParsed) || gbScaleParsed <= 0.0)
                gbScaleParsed = FailFlag<double>("--gb-services", spec, "a finite scale above 0 (1 = the EAC volumes, the default)");
            gbServicesScale = gbScaleParsed;
            if (rest.Any(x => x == "--gb-services" || x.StartsWith("--gb-services=", StringComparison.Ordinal)))
            {
                Console.Error.WriteLine("error: trip: --gb-services given more than once.");
                Environment.Exit(CliExit.Usage);
            }
        }
    }
    // R079 (October 2026, stream F front doors; Ruling R1): --band, --band=<fraction> or --band <fraction>: the nadir band
    // over the unfitted swing constants (FrequencySensitivitySweep: load damping, responsive fraction, governor time
    // constant, each +/- the fraction, one at a time and every corner). Default fraction 0.20. Taken off the list before
    // the positionals for the same reason as --gb-services (a bare --band must not swallow the generator name). The sweep
    // runs the lumped swing, so it is refused with --asset-dynamics or --inertia-model distributed (exit 2): the band would
    // describe a different model from the one whose nadir is printed above it.
    {
        int bi = rest.FindIndex(t => t == "--band" || t.StartsWith("--band=", StringComparison.Ordinal));
        if (bi >= 0)
        {
            string t = rest[bi]; rest.RemoveAt(bi);
            string spec = "0.20";
            if (t.Contains('=')) spec = t[(t.IndexOf('=') + 1)..];
            else if (bi < rest.Count && double.TryParse(rest[bi], System.Globalization.NumberStyles.Float,
                         System.Globalization.CultureInfo.InvariantCulture, out _)) { spec = rest[bi]; rest.RemoveAt(bi); }
            if (!double.TryParse(spec, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture,
                    out double bandParsed) || !(bandParsed > 0.0 && bandParsed < 1.0))
                bandParsed = FailFlag<double>("--band", spec, "a fraction strictly between 0 and 1 (0.20 = +/- 20 %, the default)");
            tripBandFraction = bandParsed;
            if (rest.Any(x => x == "--band" || x.StartsWith("--band=", StringComparison.Ordinal)))
            {
                Console.Error.WriteLine("error: trip: --band given more than once.");
                Environment.Exit(CliExit.Usage);
            }
            if (enableAssetDynamics || inertiaModel == InertiaModel.Distributed)
            {
                Console.Error.WriteLine("error: trip: --band sweeps the lumped swing model, so it cannot be combined with "
                    + (enableAssetDynamics ? "--asset-dynamics" : "--inertia-model distributed")
                    + " (the band would describe a different model from the trip it is printed under).");
                Environment.Exit(CliExit.Usage);
            }
        }
    }
    List<string> tripPos = Positionals(rest).Skip(1).ToList();
    if (tripPos.Count > 2)
    {
        Console.Error.WriteLine($"error: trip takes at most a case and a generator name but got: {string.Join(' ', tripPos)}");
        Environment.Exit(2);
    }
    string? tripCase = null, genName = null;
    if (tripPos.Count == 2) { tripCase = tripPos[0]; genName = tripPos[1]; }
    else if (tripPos.Count == 1)
    {
        if (IsCaseArgument(tripPos[0], baseDir)) tripCase = tripPos[0];
        else genName = tripPos[0];
    }
    // R095 (October 2026, stream F front doors; Ruling R1): --envelope <class>:<param>=<low>..<high>[,...] sweeps the asset
    // fleet's control parameters (AssetEnvelope.Sweep) around this trip, so it needs the asset fleet: without
    // --asset-dynamics it is refused here, before any load (exit 2). The spec itself is checked against the case's class
    // library in RunTrip, before anything is printed.
    tripEnvelopeSpec = FlagString(rest, "--envelope");
    if (tripEnvelopeSpec is not null && !enableAssetDynamics)
    {
        Console.Error.WriteLine("error: trip: --envelope sweeps the asset fleet's control parameters; add --asset-dynamics (on a case "
            + "with an asset bundle, for example --dir data/gb-synthetic).");
        Environment.Exit(CliExit.Usage);
    }
    // N238 (LF4) gave trip its own rewrite of the name gb-synthetic to the shipped folder. N316 (LF7, Ruling R1: one
    // name, one case) made that the rule for every verb, inside LoadNamed and CaseFolderOf, so trip needs no special case
    // any more: the name reaches SelectCase like any other and loads data/gb-synthetic with its asset bundle.
    GridModel m0 = LoadSelected("trip", SelectCase("trip", tripCase, rest, baseDir, "data/uk", () => LoadUkDefault(baseDir)));
    // F stream (October 2026, front doors; Ruling R1): --dyn-data <file>, the machine dynamic data file stability --rms reads
    // (gridsim-dynamics/2, F23). The trip integrates the system swing, whose per-machine input is the inertia H, so the
    // machines the file binds take the file's H (a model copy: every engine below, lumped, distributed or asset fleet, and
    // the auto-picked unit, sees the same inertia). The file's GENROU, exciter and governor data are not part of this model
    // and the "Machine data:" line says so. Without the flag m0 is the loaded model itself. Bad file: exit 1, before any run.
    string? tripDynDataPath = FlagString(rest, "--dyn-data");
    if (tripDynDataPath is not null)
    {
        MachineDynamicsSet tripDyn = LoadDynDataOrExit("trip", tripDynDataPath, m0);
        tripMachineDataLine = DynDataInertiaLine(m0, tripDyn);
        m0 = DynDataCli.WithFileInertia(m0, tripDyn);
    }
    string? exportPath = FlagString(rest, "--export");   // present with no value fails loud (R219)
    RunTrip(m0, genName, exportPath);
    return;
}

if (rest.Count > 0 && rest[0].Equals("domains", StringComparison.OrdinalIgnoreCase))
{
    GridModel md = LoadSelected("domains", SelectCase("domains", SingleCasePositional("domains", rest), rest, baseDir,
        "data/uk", () => LoadUkDefault(baseDir)));
    RunDomains(md);
    CliOutput.Finish(args);   // F10: write the result files, if asked for
    return;
}

if (rest.Count > 0 && rest[0].Equals("stability", StringComparison.OrdinalIgnoreCase))
{
    // Pull the flags (and consume their values) up front so the sole remaining positional token is
    // unambiguously the case name - '--screen case14' selects case14, and '--fault-bus 7' can't have its
    // value '7' mistaken for a case. Unknown flag values fail loud (exit 2), never a silent default.
    bool screen = rest.Remove("--screen");
    bool rms = rest.Remove("--rms");   // subtransient RMS engine instead of the classical screen
    // R061 (1.95.067): optional exciters on the RMS study's synchronous machines. --avr none (default) keeps the field
    // held exactly as before; --pss adds a PSS1A and needs an AVR.
    string avr = (FlagString(rest, "--avr") ?? "none").ToLowerInvariant() switch
    {
        "none" => "none",
        "sexs" => "sexs",
        "ieeet1" => "ieeet1",
        var bad => FailFlag<string>("--avr", bad, "none, sexs or ieeet1"),
    };
    bool pss = rest.Remove("--pss");
    if ((avr != "none" || pss) && !rms) { Console.Error.WriteLine("error: --avr and --pss apply to the RMS engine only (add --rms)."); Environment.Exit(2); }
    if (pss && avr == "none") { Console.Error.WriteLine("error: --pss needs an AVR (--avr sexs or --avr ieeet1)."); Environment.Exit(2); }
    // F23 (October 2026, stream B3): --dyn-data <file>, a gridsim-dynamics/2 machine dynamic data file for the RMS study:
    // the machines it binds take its GENROU data, exciter, stabiliser and governor instead of the synthetic defaults.
    string? dynData = null;
    int ddIdx = rest.IndexOf("--dyn-data");
    if (ddIdx >= 0)
    {
        if (ddIdx + 1 >= rest.Count || rest[ddIdx + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<string>("--dyn-data", ddIdx + 1 < rest.Count ? rest[ddIdx + 1] : "", "a gridsim-dynamics/2 file");
        else { dynData = rest[ddIdx + 1]; rest.RemoveRange(ddIdx, 2); }
    }
    // N314 (LF5, October 2026; ruled by main, Ruling R1): the classical engine (single bus and --screen) takes the file too,
    // as modal does: the classical swing is built from exactly three machine numbers, X'd, H and the damping D, and the
    // file carries all three for each machine it binds (RunStability / RunStabilityScreen). It used to exit 2 here
    // ("--dyn-data applies to the RMS engine only (add --rms)"); without the flag nothing changes.

    int? faultBus = null;
    int fbIdx = rest.IndexOf("--fault-bus");
    if (fbIdx >= 0)
    {
        if (fbIdx + 1 >= rest.Count || !int.TryParse(rest[fbIdx + 1], System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out int fbv))
            FailFlag<int>("--fault-bus", fbIdx + 1 < rest.Count ? rest[fbIdx + 1] : "", "an integer");
        else { faultBus = fbv; rest.RemoveRange(fbIdx, 2); }
    }

    double? clearMs = null;
    int cmIdx = rest.IndexOf("--clear");
    if (cmIdx >= 0)
    {
        if (cmIdx + 1 >= rest.Count || !double.TryParse(rest[cmIdx + 1], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double cmv))
            FailFlag<double>("--clear", cmIdx + 1 < rest.Count ? rest[cmIdx + 1] : "", "a number");
        // D-DOC-051 (docs-session finding, Ruling R1: Mark delegated 2026-10-04): a clearing time is a duration from the
        // fault onset, so it must be a finite number of milliseconds, 0 or more (0 = an instantaneous clear, the CCT's
        // own lower end). "--clear -50" used to be accepted: the fault window [onset, onset - 50 ms) is empty, so the run
        // studied no fault at all and printed "cleared after -50 ms -> STABLE" (classical and --rms alike, exit 0).
        // "NaN" and "Infinity" parsed too. Each is now a usage error, exit 2, before any load or solve.
        else if (!double.IsFinite(cmv) || cmv < 0.0)
            FailFlag<double>("--clear", rest[cmIdx + 1], "a finite clearing time in ms, 0 or more");
        // N266 (LF5, October 2026; Ruling R1: Mark delegated EE calls 2026-10-04): and at most CliDefaults.MaxClearMs
        // (1000 ms). Why that bound: (1) the slowest fault clearance GB plant must coordinate with is the transmission
        // back-up protection's 800 ms in England and Wales (300 ms in Scotland; main protection 80 / 100 / 120 ms at
        // 400 / 275 / 132 kV), Grid Code CC.6.2.2.2.2 as quoted in GC0023 (docs/reference/protection-tx/S160, section 2.4
        // and the legal text), so 1000 ms covers every protection-cleared fault with margin; (2) it is the window both
        // CCT searches use (ClassicalInit / RmsTransientStability.CctDefaultMaxSeconds = 1.0 s), so a fixed clearing time
        // asks a question inside the range the CCT answers ("1000 ms means nothing in the window loses synchronism");
        // (3) the RMS single study runs a fixed RmsDurationS = 3.0 s from t = 0, so a clear past about 2.9 s would end the
        // run with the fault still on and report a verdict on a fault never cleared; and a classical run lasts onset +
        // clear + 5 s at a 2 ms step, so an unbounded value grew time and memory without limit. Exit 2, before any load.
        else if (cmv > GridSim.Cli.CliDefaults.MaxClearMs)
            FailFlag<double>("--clear", rest[cmIdx + 1], $"a clearing time of at most {GridSim.Cli.CliDefaults.MaxClearMs:0} ms "
                + "(GB back-up protection clears within 800 ms, Grid Code CC.6.2.2.2.2; the CCT search window is 1000 ms)");
        else { clearMs = cmv; rest.RemoveRange(cmIdx, 2); }
    }

    string? sExport = null;
    int seIdx = rest.IndexOf("--export");
    if (seIdx >= 0)
    {
        // GR-699: a following --flag is not a file name (it used to be taken as one).
        if (FlagValueMissing(rest, seIdx)) FailFlag<string>("--export", "", "a file path");
        sExport = rest[seIdx + 1]; rest.RemoveRange(seIdx, 2);
    }
    // D-DOC-052 (docs-session finding, Ruling R1: Mark delegated 2026-10-04): --export writes the CLASSICAL single-bus
    // trajectory (gridsim-classical-export/1, the scipy cross-check's input). With --rms or --screen no such trajectory
    // is computed, and the flag used to be accepted and silently ignored: no file, exit 0, so a script that asked for the
    // file believed it had one. It is refused instead (exit 2, before any load or solve), naming the flag that rules it
    // out. Honouring it would need a new RMS / screen export format, which is not what the cross-check reads.
    if (sExport is not null && (rms || screen))
    {
        Console.Error.WriteLine($"error: stability: --export writes the classical single-bus trajectory and is not available with {(rms ? "--rms" : "--screen")} (no file would be written).");
        Environment.Exit(CliExit.Usage);
    }
    // N351 (CF5): the RMS event list (--events) and the clearing actions of the CCT search (--clear-by-trip), both
    // --rms only. --events runs one scheduled-event study (RmsTransientStability.StudyEvents) and owns the whole
    // disturbance, so it takes no --screen, --fault-bus, --clear or --clear-by-trip. --clear-by-trip clears the fault at
    // --fault-bus by also tripping the listed branches (0-based indices): with --clear a fixed-time verdict, without it
    // the CCT search (CriticalClearingBracketEvents); not with --screen. Every malformed value exits 2 before any load.
    IReadOnlyList<GridSim.Core.Dynamics.Models.RmsEvent>? rmsEvents = null;
    IReadOnlyList<int>? clearByTrip = null;
    string? eventsText = FlagString(rest, "--events");
    string? clearTripText = FlagString(rest, "--clear-by-trip");
    if (eventsText is not null || clearTripText is not null)
    {
        string which = eventsText is not null ? "--events" : "--clear-by-trip";
        if (!rms) { Console.Error.WriteLine($"error: stability: {which} applies to the RMS engine only (add --rms)."); Environment.Exit(CliExit.Usage); }
        if (screen) { Console.Error.WriteLine($"error: stability: {which} cannot be combined with --screen (it studies one disturbance)."); Environment.Exit(CliExit.Usage); }
        if (eventsText is not null && (faultBus is not null || clearMs is not null || clearTripText is not null))
        {
            Console.Error.WriteLine("error: stability: --events gives the whole disturbance, so it takes no --fault-bus, --clear or --clear-by-trip.");
            Environment.Exit(CliExit.Usage);
        }
        try
        {
            if (eventsText is not null) rmsEvents = GridSim.Core.Dynamics.Models.RmsEventSpec.Parse(eventsText);
            if (clearTripText is not null) clearByTrip = GridSim.Core.Dynamics.Models.RmsEventSpec.ParseIndices(clearTripText, "--clear-by-trip");
        }
        catch (FormatException ex) { Console.Error.WriteLine($"error: stability: {ex.Message}"); Environment.Exit(CliExit.Usage); }
        // Leave no value behind for the positional scan.
        foreach (string f in new[] { "--events", "--clear-by-trip" })
        {
            int at = rest.IndexOf(f);
            if (at >= 0) rest.RemoveRange(at, Math.Min(2, rest.Count - at));
        }
    }
    // N363 (CF6): --events-out <dir> writes the RMS event study's export (RmsEventsExport: the machine and converter
    // trajectories as CSV with the run header and a provenance line, a gridsim-rms-events-export/1 summary and
    // run-metadata.json). It qualifies --events only: every other stability run has its own outputs (or none), so the
    // flag would be silently ignored there, and is refused instead (exit 2, before any load or solve).
    string? eventsOut = FlagString(rest, "--events-out");
    if (eventsOut is not null)
    {
        if (rmsEvents is null)
        {
            Console.Error.WriteLine("error: stability: --events-out writes the export of an RMS event study, so it needs --rms --events (no file would be written).");
            Environment.Exit(CliExit.Usage);
        }
        int at = rest.IndexOf("--events-out");
        if (at >= 0) rest.RemoveRange(at, Math.Min(2, rest.Count - at));
    }
    // CF6-F5 (main's ruling): --events-every N decimates the --events-out CSVs to every N-th integration step. Default 1
    // (every step), so an export without the flag is exactly the full-resolution one. It qualifies --events-out only.
    int eventsEvery = 1;
    string? eventsEveryText = FlagString(rest, "--events-every");
    if (eventsEveryText is not null)
    {
        if (eventsOut is null)
        {
            Console.Error.WriteLine("error: stability: --events-every decimates the --events-out export, so it needs --events-out.");
            Environment.Exit(CliExit.Usage);
        }
        if (!int.TryParse(eventsEveryText, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out eventsEvery)
            || eventsEvery < 1 || eventsEvery > GridSim.Core.IO.RmsEventsExport.MaxEverySteps)
            FailFlag<int>("--events-every", eventsEveryText, $"a whole number of integration steps from 1 to {GridSim.Core.IO.RmsEventsExport.MaxEverySteps}");
        int at = rest.IndexOf("--events-every");
        if (at >= 0) rest.RemoveRange(at, Math.Min(2, rest.Count - at));
    }

    // N266 (LF5, October 2026; Ruling R1; the same class as D-DOC-052): --screen searches the critical clearing time at
    // EVERY generator bus, so it has no single fault bus and no fixed clearing time. --fault-bus and --clear used to be
    // accepted with it and silently ignored (the manual called it "takes precedence"), so a script that asked for bus 7
    // cleared at 150 ms got a whole-system CCT table and believed it had its verdict. Refused instead, on both engines
    // (classical and --rms), exit 2, before any load or solve, naming the flag(s).
    if (screen && (faultBus is not null || clearMs is not null))
    {
        string ignored = faultBus is not null && clearMs is not null ? "--fault-bus and --clear" : faultBus is not null ? "--fault-bus" : "--clear";
        Console.Error.WriteLine($"error: stability: --screen searches the critical clearing time at every generator bus, so {ignored} "
            + "would be ignored; drop --screen for one fault bus (with --clear for a STABLE / UNSTABLE verdict), or drop "
            + (faultBus is not null && clearMs is not null ? "them" : "it") + " to screen every bus.");
        Environment.Exit(CliExit.Usage);
    }

    // D-DOC-053 (one rule for every verb that takes a case, manual ch. 19 "How each verb takes its case"): stability now
    // selects its network through the shared SelectCase / LoadSelected, like trip, screen, nminus1 and the rest. Before,
    // it parsed --dir itself and let --dir silently win over a positional case ("stability case14 --dir data/uk" studied
    // data/uk under no warning), and any named case that did not load exited 2. Now:
    //   * a positional case and --dir together exit 2 unless they name the same folder; a second positional exits 2;
    //   * an unknown case NAME exits 2 (LoadSelected), a missing --dir folder exits 1 before any work (SelectCase), and a
    //     case file or folder that exists but cannot be loaded exits 1 (the process-wide handler) (D-DOC-130);
    //   * a positional case folder (one holding system.json) now loads, as on the other verbs (LoadNamed alone called it
    //     an unknown case).
    // The default (case9) and the report label are unchanged: "WSCC-9" for case9 / ieee9, the --dir path for a folder,
    // the model's own name otherwise.
    string? sPos = SingleCasePositional("stability", rest);
    bool sViaDir = rest.Contains("--dir");
    var sSel = SelectCase("stability", sPos, rest, baseDir, "case9", () => IeeeCases.Case9());
    GridModel sm = LoadSelected("stability", sSel);
    string label = sViaDir ? sSel.Label
        : ((sPos ?? "case9").ToLowerInvariant() is "case9" or "ieee9") ? "WSCC-9" : sm.Name;
    // GR-684 (October 2026): the label "WSCC-9" is what selects the Anderson-Fouad transient reactances (by bus number) in
    // the classical study, the screen and modal. It is meant only for the built-in WSCC 9-bus case (case9 / ieee9), but
    // the label falls back to the case's own name (or the --dir path), so a user case NAMED "WSCC-9" silently got the
    // built-in machine data on its own buses. Such a case keeps its name in the report with " (user case)" after it, so
    // the built-in data is chosen by the case argument alone and a user case gets its own dynamics or the stated default.
    label = UserCaseLabel(label, builtinWscc9: !sViaDir && (sPos ?? "case9").ToLowerInvariant() is "case9" or "ieee9");

    // D-DOC-003: a --fault-bus that is not a bus of the case used to reach ClassicalInit as a raw dictionary lookup and
    // crash with an unhandled KeyNotFoundException. It is a flag value that names nothing in the case: a usage error,
    // exit 2, naming the bus and the case, the same rule and wording as protection-check --fault-bus and fault --bus
    // (D-DOC-159). Checked before any solve, on every engine (classical, --rms, --screen).
    if (faultBus is int sfb && !sm.Buses.Any(b => b.Id == sfb))
    {
        Console.Error.WriteLine($"error: stability: fault bus {sfb} is not in case '{sm.Name}'.");
        Environment.Exit(CliExit.Usage);
    }

    // FromSolvedCase rejects zero-inertia cases with a clear message; surface it and exit 2
    // rather than letting it escape as an unhandled stack trace or reporting a bogus max CCT.
    // N314 (LF5): the classical engines' dynamics file is validated and bound here, before any solve (exit 1 for a missing
    // or invalid file, every problem listed, as on modal and trip). The RMS engine loads its own inside RunRmsStability.
    MachineDynamicsSet? classicalDyn = dynData is not null && !rms ? LoadDynDataOrExit("stability", dynData, sm) : null;
    try
    {
        if (rms) RunRmsStability(sm, label, screen, faultBus, clearMs, avr, pss, dynData, rmsEvents, clearByTrip, eventsOut, eventsEvery);
        else if (screen) RunStabilityScreen(sm, label, classicalDyn);
        else RunStability(sm, label, faultBus, clearMs, sExport, classicalDyn);
    }
    catch (InvalidOperationException ex)
    {
        Console.Error.WriteLine($"error: stability: {ex.Message}");
        Environment.Exit(2);
    }
    return;
}

if (rest.Count > 0 && rest[0].Equals("modal", StringComparison.OrdinalIgnoreCase))
{
    try { RunModal(rest, baseDir); }
    catch (InvalidOperationException ex) { Console.Error.WriteLine($"error: modal: {ex.Message}"); Environment.Exit(2); }
    return;
}

// R079 (October 2026, stream F front doors; Ruling R1): the frequency-constants fitter's front door. See RunFitFrequency.
if (rest.Count > 0 && rest[0].Equals("fit-frequency", StringComparison.OrdinalIgnoreCase))
{
    RunFitFrequency(rest);
    return;
}

if (rest.Count > 0 && rest[0].Equals("export", StringComparison.OrdinalIgnoreCase))
{
    // gridsim export [<case>] [<out.json>] [--dir <folder>] [--frames 72]
    // The first free token used to be taken as the output path whatever it was, so "export case14" wrote the GB
    // model to a file called "case14". Now a free token that names a case (case folder, .m file, built-in name) is
    // the case; any other free token is the output path and must end in .json (exit 2 otherwise, so a mistyped case
    // name is not silently used as a file name). At most one of each, case first.
    string? exportCase = null, exportOut = null;
    foreach (string tok in Positionals(rest).Skip(1))
    {
        // DATA LOSS fix (docs-session finding, 2026-10-04): a v2 case manifest is itself a .json file, so the old rule
        // took "export case.json" as the OUTPUT path and wrote the scene over the manifest. An existing .json file that
        // is a GridSim case manifest is now the case, never the output.
        bool isManifest = File.Exists(tok) && tok.EndsWith(".json", StringComparison.OrdinalIgnoreCase) && IsGridSimCaseManifest(tok);
        if (exportCase is null && exportOut is null && (isManifest || IsCaseArgument(tok, baseDir))) { exportCase = tok; continue; }
        if (exportOut is null && tok.EndsWith(".json", StringComparison.OrdinalIgnoreCase))
        {
            // Never write the scene over an existing file that is not a scene: a case, schema or any other JSON a
            // user keeps is refused by name (exit 2) instead of being destroyed. Re-running onto an old scene is fine.
            if (File.Exists(tok) && !IsGridVizScene(tok))
            {
                Console.Error.WriteLine($"error: export: '{tok}' already exists and is not a gridviz scene; refusing to overwrite it " +
                    "(name a new .json output path, or delete the file first).");
                Environment.Exit(2);
            }
            exportOut = tok;
            // An existing scene here is this verb's own earlier output (just checked), not an input: tell the output
            // policy, or CliFiles.Output (GR-694) refuses the re-run as "an input of this run".
            if (File.Exists(tok)) CliFiles.DeclareOutput(tok);
            continue;
        }
        Console.Error.WriteLine($"error: export: unexpected argument '{tok}': expected at most one case and one .json " +
            "output path (usage: gridsim export [<case>] [<out.json>] [--dir <folder>] [--frames N]).");
        Environment.Exit(2);
    }
    // N079 (Ruling R1): the default output goes under results/ in the current directory (it was beside the executable).
    string outPath = exportOut ?? DefaultResultsPath("gridviz.json");
    GridModel m = LoadSelected("export", SelectCase("export", exportCase, rest, baseDir, "data/uk", () => LoadUkDefault(baseDir)));
    VizScene scene = VizExport.Build(m, FlagCount(rest, "--frames", 72, 0));
    VizExport.Write(scene, CliFiles.Output(outPath, "gridviz scene"));   // GR-694: through the one output policy (an input of the run, a protected case folder or an existing folder is refused)
    Console.WriteLine($"Exported {scene.Buses.Length} buses, {scene.Branches.Length} branches, {scene.Frames.Length} frames -> {Path.GetFullPath(outPath)}");
    return;
}

if (rest.Count > 0 && rest[0].Equals("gpucheck", StringComparison.OrdinalIgnoreCase))
{
    RunGpuCheck();
    return;
}

if (rest.Count > 0 && rest[0].Equals("simdcheck", StringComparison.OrdinalIgnoreCase))
{
    // R102: --expect <tier> makes the preflight a gate (exit 3 when the active tier is narrower than expected), so a
    // CI box that should run 8-wide fails loud instead of silently running 4-wide.
    GridSim.Core.Numerics.SimdTier? expect = FlagString(rest, "--expect") is string ex
        ? (Enum.TryParse(ex, ignoreCase: true, out GridSim.Core.Numerics.SimdTier et) && Enum.IsDefined(et)
            ? et
            : FailFlag<GridSim.Core.Numerics.SimdTier>("--expect", ex, "one of Avx512, Avx256, Sse128, Scalar"))
        : null;
    RunSimdCheck(expect);
    return;
}

if (rest.Count > 0 && rest[0].Equals("physics-check", StringComparison.OrdinalIgnoreCase))
{
    RunPhysicsCheck(rest, baseDir);
    CliOutput.Finish(args);   // F10: write the result files, if asked for
    return;
}

