// A4.b runtime accessor: `gridsim compliance [verify]` prints the compliance attestation (version, commit, build
// identity hash, SBOM hash, manifest hash, whether this is a release build, and each in-scope control not recorded
// Achieved) and exits 0 only for a compliant RELEASE build, 1 otherwise (a local build always exits 1). Answered before
// the licence is resolved so a reviewer can always ask a binary to describe itself, with no network and no licence.
if (rest.Count > 0 && rest[0].Equals("compliance", StringComparison.OrdinalIgnoreCase))
{
    string sub = rest.Count > 1 ? rest[1] : "verify";
    if (!sub.Equals("verify", StringComparison.OrdinalIgnoreCase) && !sub.Equals("show", StringComparison.OrdinalIgnoreCase))
    {
        Console.Error.WriteLine($"error: unknown 'compliance' subcommand '{sub}'. Use: gridsim compliance verify");
        Environment.Exit(2);
    }
    GridSim.Core.Diagnostics.SupplyChain.ComplianceAttestation attestation =
        GridSim.Core.Diagnostics.SupplyChain.ComplianceAttestation.Current;
    Console.WriteLine(attestation.Report());
    Environment.Exit(attestation.IsCompliant ? 0 : 1);
}

if (rest.Count > 0 && rest[0].Equals("dcopf", StringComparison.OrdinalIgnoreCase))
{
    RunDcOpf(rest, baseDir);
    CliOutput.Finish(args);   // F10: write the result files, if asked for
    return;
}

// R072: finished Core analyses that had no CLI entry point.
