if (rest.Count > 0 && rest[0].Equals("chain", StringComparison.OrdinalIgnoreCase))
{
    // Storage sites (--bess, repeatable) switch chain into the storage time series: SoC, temperature and
    // ageing carried step to step, with a dispatch policy (StorageCli).
    List<string> bessSpecs;
    try { bessSpecs = GridSim.Cli.StorageCli.TakeBessSpecs(rest); }
    catch (ArgumentException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 2; return; }
    if (bessSpecs.Count > 0)
    {
        string chainMode = (FlagString(rest, "--mode") ?? "fixed").ToLowerInvariant();
        if (chainMode is not ("fixed" or "ramp" or "daily")) FailFlag<string>("--mode", chainMode, "'fixed', 'ramp' or 'daily'");
        // Positional case and/or --dir, as in plain chain (SelectCase; --dir used to be ignored here too).
        (string chainCase, Func<GridModel> chainLoad) = SelectCase("chain", SingleCasePositional("chain", rest), rest, baseDir,
            "case118", () => LoadNamed("case118", baseDir));
        // D-DOC-130: the case is loaded before the storage block, through the shared LoadSelected, so an unknown case
        // name is a usage error (exit 2) and a missing or unloadable file an input error (exit 1, through the
        // process-wide handler), as on plain chain. Inside the storage block's catch below, an unloadable case (an
        // IOException) used to come out as exit 2.
        GridModel chainModel = LoadSelected("chain", (chainCase, chainLoad));
        try
        {
            // N084 (October 2026): the storage chain joins the contingency family's one option set (D04), as plain chain
            // did: ContingencyAnalysis.StudyOptions (100 iterations, reactive limits on: the same values the storage
            // time series already defaulted to) and, new here, the OLTC loop around the shared dense/sparse engine, so
            // `chain --bess` and `chain` solve each step to the same tap-regulated steady state. With no OLTC records in
            // the model (every MATPOWER case, case118 included) the loop returns the engine's answer to the bit.
            IPowerFlowSolver chainSolver = ContingencyAnalysis.WithOltcLoop(backend.NewtonSolver(chainModel));
            Environment.ExitCode = GridSim.Cli.StorageCli.Run(rest, bessSpecs, chainModel, CaseFileTag(chainCase),
                StorageSteps(FlagInt(rest, "--steps", 48)), chainMode, FlagDouble(rest, "--ramp-pct", 0.5),
                FlagString(rest, "--out"), chainSolver, ContingencyAnalysis.StudyOptions);
        }
        catch (GridSim.Cli.PriceFileException ex)
        {
            // D-DOC-197 / D-DOC-049: a --prices file that is missing, unreadable or malformed is an input error (exit 1,
            // as a case file that cannot be loaded), named with the file and, for a bad value, the line.
            Console.Error.WriteLine($"error: chain storage: {ex.Message}");
            Environment.ExitCode = CliExit.InputError;
        }
        catch (Exception ex) when (ex is ArgumentException or FormatException or IOException)
        {
            Console.Error.WriteLine($"error: chain storage: {CliExit.UserMessage(ex)}");
            Environment.ExitCode = CliExit.Usage;
        }
        catch (InvalidOperationException ex)
        {
            // D-DOC-006: StorageCli.OptimalLpPlan throws this when the storage schedule LP of the lp policy does not
            // solve to Optimal. It used to escape this handler (only Argument, Format and IO exceptions were caught) and
            // crash. An LP with no optimal schedule is a verdict failure, the same code as an infeasible dcopf: exit 3.
            // Reachable since D-DOC-049 (chain takes --prices, so --policy lp runs its LP).
            Console.Error.WriteLine($"error: chain storage: {ex.Message}");
            Environment.ExitCode = 3;   // CliExit.Verdict, written as the literal 3 that CliExitCodeContractTests reads
        }
        return;
    }
    // D-DOC-049: the storage flags mean something only with at least one --bess site. Plain chain used to accept them
    // (they are chain's documented flags, so the per-verb check let them through) and ignore them; refused instead.
    string? storageOnly = new[] { "--prices", "--policy", "--shave-high", "--shave-low", "--buy-below", "--sell-above",
        "--degradation-gbp-per-mwh", "--step-hours" }.FirstOrDefault(rest.Contains);
    if (storageOnly is not null)
    {
        Console.Error.WriteLine($"error: chain {storageOnly} is a storage flag: it needs at least one --bess site (without one, chain runs no storage and the flag would be ignored).");
        Environment.ExitCode = 2;
        return;
    }
    RunChain(rest, FlagCount(rest, "--steps", 50, 1), FlagString(rest, "--mode") ?? "fixed",
        FlagDouble(rest, "--ramp-pct", 0.5), FlagString(rest, "--out"), baseDir);
    return;
}

