// GR-202 / GR-688 (October 2026): the bare run (a case, a .m file, --dir <folder> or --mpc <file>, with no verb) takes
// that one case and the global switches, and nothing else. The per-verb flag check does not cover it (its first token
// is not a verb), so any other known flag, a second case and any extra word used to be accepted and silently ignored:
// "case14 --dir data/uk" ran case14, "case14 --top 5" ran as if --top were not there, and "--enableExport out.json"
// (the space form) wrote to the default results/exports path with "out.json" ignored. By this point every global switch
// (--once, --ticks, --bfs, --cpu / --gpu, --enableExport, --export-*, --inertia-model, --forming*, --asset-dynamics,
// --frequency-hz, --audit-*) has been taken off the list, so anything left after the case selector is refused (exit 2),
// naming the token. An unknown first token is left to the unknown-command message below, which says more.
{
    int selector = rest.Count == 0 ? 0 : rest[0] is "--dir" or "-d" || rest[0].Equals("--mpc", StringComparison.OrdinalIgnoreCase) ? 2 : 1;
    bool knownSelector = rest.Count == 0 || selector == 2 || rest[0].EndsWith(".m", StringComparison.OrdinalIgnoreCase)
        || rest[0].EndsWith(".raw", StringComparison.OrdinalIgnoreCase)
        || rest[0].EndsWith(".uct", StringComparison.OrdinalIgnoreCase)
        || rest[0].ToLowerInvariant() is "case9" or "ieee9" or "case14" or "case30" or "case57" or "case118" or "case300"
            or "case145" or "case24" or "rts" or "cigre" or "uk";
    if (knownSelector && rest.Count > selector)
    {
        string extra = rest[selector];
        string hint = doExport && exportJsonPath is null && !extra.StartsWith("--", StringComparison.Ordinal)
            ? $" --enableExport takes its path in the '=' form only: --enableExport={extra}"
            : " A flag of a verb needs that verb first (gridsim <verb> <case> ...); run 'gridsim --help' for the verb list";
        Console.Error.WriteLine($"error: the case run (no verb) takes one case and the global switches only, so '{extra}' would be " +
            $"silently ignored.{hint}, or see {VerbHelp.ChapterPath}.");
        Environment.Exit(CliExit.Usage);
    }
}

