else if (rest.Count >= 1 && rest[0].EndsWith(".uct", StringComparison.OrdinalIgnoreCase))
    model = Gated.Ucte(rest[0]);       // Tranche A: a UCTE-DEF file
else if (rest.Count >= 2 && rest[0].Equals("--mpc", StringComparison.OrdinalIgnoreCase))
    model = Gated.Matpower(rest[1]);
else
{
    string name = rest.Count > 0 ? rest[0].ToLowerInvariant() : "uk";
    model = name switch
    {
        "case9" or "ieee9" => doExport ? IeeeCases.Case9() : PrintAndExitCase9(),
        "case14" => IeeeCases.Case14(),
        "case30" => IeeeCases.Case30(),
        "case57" => IeeeCases.Case57(),
        "case118" => IeeeCases.Case118(),
        "case300" => IeeeCases.Case300(),
        "case145" => IeeeCases.Case145(),
        "case24" or "rts" => IeeeCases.Case24Rts(),
        "cigre" => IeeeCases.CigreMv(),
        "uk" => Gated.Dir(Path.Combine(baseDir, "data", "uk")),
        // An unrecognised FIRST token (a mistyped verb like "evidnce", or a bad case name) must NOT silently
        // start the interactive UK simulator - that hangs headless scripts. Fail with usage.
        _ => UnknownVerb(name),
    };
}

GridModel UnknownVerb(string token)
{
    Console.Error.WriteLine($"error: unknown command or case '{token}'.");
    Console.Error.WriteLine("Run a case (case9|case14|case30|case57|case118|case300|case145|case24|cigre|uk), a .m file,");
    Console.Error.WriteLine("or a verb (transient, stability, modal, replay-event, scenario, fleet, evidence, gda-replay, crossval, estimate, bench, ...).");
    Environment.Exit(2);
    return null!; // unreachable
}

if (doExport)
{
    string label = rest.FirstOrDefault(a => !a.StartsWith('-')) ?? model.Name ?? "case";
    RunExport(model, label, exportJsonPath, exportJac, useBfs, exportTight);
    return;
}
if (once) { PrintDetailed(model, PickSolver(model)); return; }
RunLive(model, ticks);
return;

// D-DOC-154: the stem of the default --enableExport file name for a case argument. A path (it holds a separator, or
// names a .m / .json file, or an existing folder) gives its last segment without a trailing separator and without a
// .m / .json extension; anything else (a built-in name such as case14 or uk) is returned unchanged.
static string ExportFileStem(string caseArgument)
{
    string t = Path.TrimEndingDirectorySeparator(caseArgument.Trim());
    bool isPath = t.Contains('/') || t.Contains('\\')
        || t.EndsWith(".m", StringComparison.OrdinalIgnoreCase)
        || t.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
        || t.EndsWith(".raw", StringComparison.OrdinalIgnoreCase)
        || t.EndsWith(".uct", StringComparison.OrdinalIgnoreCase)
        || Directory.Exists(t);
    if (!isPath) return caseArgument;
    string name = Path.GetFileName(t.Replace('\\', '/').TrimEnd('/').Split('/')[^1]);
    if (name.EndsWith(".m", StringComparison.OrdinalIgnoreCase) || name.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
        || name.EndsWith(".raw", StringComparison.OrdinalIgnoreCase) || name.EndsWith(".uct", StringComparison.OrdinalIgnoreCase))
        name = Path.GetFileNameWithoutExtension(name);
    return name.Length > 0 ? name : caseArgument;
}

// One traced solve on the picked raw engine, dumped to JSON (--enableExport).
void RunExport(GridModel m, string caseLabel, string? outPath, bool jac, bool bfs, bool tight = false)
{
    var trace = new GridSim.Core.Diagnostics.SolveTrace { CaptureJacobian = jac };
    var opt = new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true, Trace = trace };
    // N057: the export keeps the engine it always used (SolverBackend.ExportSolver: radial -> sweep, dense up to the old
    // 200-bus crossover, sparse above), not the always-sparse power-flow rule, because only the dense engine records the
    // Jacobian in the trace (--export-jacobian). Bit-identical numbers either way on the CPU.
    IPowerFlowSolver raw = bfs ? new BackwardForwardSweep() : backend.ExportSolver(m);
    var sw = System.Diagnostics.Stopwatch.StartNew();
    PowerFlowResult r = raw.Solve(m, opt);
    sw.Stop();
    // The slack's reactive note of the solve whose state is exported. It is read from the engine right after that solve
    // (N251: before any --export-tight rung runs, because the engine keeps the note of its LAST solve, and a rung that
    // does not converge must not leave its note on the kept state).
    static string? SlackNoteOf(IPowerFlowSolver s) => s switch
    {
        NewtonRaphsonPowerFlow d => d.SlackQNote,
        SparseNewtonRaphsonPowerFlow sp => sp.SlackQNote,
        _ => null,
    };
    string? slack = SlackNoteOf(raw);
    // N251 (October 2026): --export-tight. The ordinary solve stops just under the 1e-8 pu test, so its state carries
    // that convergence residual (up to about 1e-9 pu in |V| on the bundled cases) and can never meet a machine-epsilon
    // comparison on its own. With the switch, and only when the ordinary solve converged, the same case is solved afresh
    // with the same engine and options (the trace's Jacobian setting included) at 1e-9, 1e-10, ... 1e-15 pu, and the
    // tightest rung that converges is the exported state: the crossval verb's rule (N243), each rung an ordinary complete
    // GridSim solve, nothing in the solver changed. The ladder stops at the first rung that does not converge (below the
    // case's rounding floor Newton cannot meet the test). meta.elapsedMs is then the kept rung's own solve time. A first
    // solve that did not converge is exported as it is, as without the switch (exit 3 below). Without the switch none of
    // this runs and tightenedTolerancePu is not written.
    double? tightened = null;
    if (tight && r.Converged)
    {
        foreach (double rung in new[] { 1e-9, 1e-10, 1e-11, 1e-12, 1e-13, 1e-14, 1e-15 })
        {
            var rungTrace = new GridSim.Core.Diagnostics.SolveTrace { CaptureJacobian = jac };
            var rungClock = System.Diagnostics.Stopwatch.StartNew();
            PowerFlowResult rr = raw.Solve(m, opt with { Tolerance = rung, Trace = rungTrace });
            rungClock.Stop();
            if (!rr.Converged) break;   // below this case's floor: keep the last converged rung
            r = rr;
            trace = rungTrace;
            tightened = rung;
            sw = rungClock;
            slack = SlackNoteOf(raw);   // the kept rung's own note
        }
        // Even the first rung (1e-9) failing leaves the ordinary state, and says so: the export is then NOT tightened.
        Console.WriteLine(tightened is double reached
            ? string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"[export] tightened: solve tolerance {reached:G3} pu (the tightest of 1e-9 ... 1e-15 that converged; final mismatch {r.MaxMismatch:E3} pu)")
            : "[export] --export-tight: no tolerance below the ordinary 1e-8 pu converged on this case; the export holds the ordinary state (no tightenedTolerancePu).");
    }
    // D-DOC-154 (October 2026): the default file name is built from the case's own name, not from the argument as typed.
    // A path argument (data/matpower/lib/case14.m, or a case folder) used to have every separator and the colon turned
    // into '_', so the export landed at results/exports/data_matpower_lib_case14.m-solve.json. A path now gives its
    // file or folder name, less a .m / .json extension (case14-solve.json); a built-in name is used as it was. The
    // export's meta block still records the argument exactly as given.
    string safe = string.Concat(ExportFileStem(caseLabel).Select(ch => Path.GetInvalidFileNameChars().Contains(ch) ? '_' : ch));
    // N079 (Ruling R1): under results/ like every other default output (it was exports/ in the current directory).
    string path = outPath ?? DefaultResultsPath("exports", $"{safe}-solve.json");
    var meta = new GridSim.Core.IO.SolveExportMeta(
        caseLabel, backend.Description, RunInfo.GitCommit, DateTime.UtcNow.ToString("o"),
        sw.Elapsed.TotalMilliseconds,
        $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}");
    GridSim.Core.IO.SolveExport.WriteJson(CliFiles.Output(path, "solve export"), m, r, trace, meta, slack, tightenedTolerancePu: tightened);
    // D-DOC-014: the line used to print an empty solver name when the solver declined before recording one (the
    // backward/forward sweep on a meshed or disconnected network returns at once, iterations 0, mismatch Infinity), and
    // the run exited 0 whatever the outcome. The name now falls back to the engine that was asked for, saying the sweep
    // declined, and a solve that did not converge is a failure: the export is still written (it is the evidence) and the
    // run exits 3, as the default solve report already did (R022).
    string solverLabel = trace.SolverName is { Length: > 0 } sn ? sn
        : raw is BackwardForwardSweep ? "BackwardForwardSweep (declined: the network is not radial or not connected)"
        : raw.GetType().Name;
    Console.WriteLine($"[export] {solverLabel}: converged={r.Converged} iters={r.Iterations} " +
                      $"maxMis={r.MaxMismatch:E2}  ->  {Path.GetFullPath(path)}");
    if (!r.Converged)
    {
        Console.Error.WriteLine($"error: the {solverLabel} solve of {caseLabel} did not converge (status {r.Status}); the export holds the " +
            "non-converged state." + (bfs ? " --bfs forces the radial sweep; leave it out to use the Newton engine." : "") + " Exit 3.");
        Environment.ExitCode = 3;   // CliExit.Verdict, written as the literal 3 that CliExitCodeContractTests reads
    }
}

// Headless demanding time-domain test: drive LiveSim (hold-steady, warm-started) for a simulated duration
// at a fine slice, integrating swing-equation frequency each slice; log a per-slice time-series + sampled
// full-math exports. `transient <case>` or `transient --cases a,b,c` (or `--cases suite`).
void RunTransientBatch(List<string> a, string root)
{
    double minutes = FlagDouble(a, "--minutes", FlagDouble(a, "--duration", 60));
    double dtMs = FlagDouble(a, "--dt-ms", 1.0);
    // R216: a zero or negative step or duration has no meaning. --dt-ms 0 made the slice count +Infinity (the run
    // never ended); a negative value or --minutes 0 ran zero slices and reported "nadir 999 Hz" with exit 0.
    if (!(dtMs > 0)) FailFlag<double>("--dt-ms", dtMs.ToString(System.Globalization.CultureInfo.InvariantCulture), "a step above 0 ms");
    if (!(minutes > 0)) FailFlag<double>("--minutes", minutes.ToString(System.Globalization.CultureInfo.InvariantCulture), "a duration above 0 minutes");
    int logEvery = FlagCount(a, "--log-every", 1, 1);   // GR-682: refused below 1, not raised to 1
    int exportEvery = FlagCount(a, "--export-every", 0, 0);
    bool exportJac = a.Remove("--export-jac");
    double tripMw = FlagDouble(a, "--trip", 0);
    // GR-675: a trip is a loss of 0 MW or more (a negative trip used to run as a gain).
    if (tripMw < 0) FailFlag<double>("--trip", tripMw.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a loss of 0 MW or more");
    double tripAt = FlagDouble(a, "--trip-at", 0);
    double tripWin = FlagDouble(a, "--trip-window", 2.0);
    // GR-701 (remaining part, October 2026): --trip-at and --trip-window place and frame the trip, so without a trip
    // above 0 MW they did nothing and the run reported no trip as if the timing had been honoured. Refused (exit 2),
    // naming the flag: a run that gives either one also gives --trip <MW>.
    if (!(tripMw > 0))
        foreach (string tf in new[] { "--trip-at", "--trip-window" })
            if (a.Contains(tf))
            {
                Console.Error.WriteLine($"error: transient: {tf} times a trip, but no trip is scheduled (give --trip <MW> above 0); it would be silently ignored.");
                Environment.Exit(CliExit.Usage);
            }
    if (!(tripWin > 0)) FailFlag<double>("--trip-window", tripWin.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a window above 0 s");
    SolverKind kind = (FlagString(a, "--solver") ?? "auto").ToLowerInvariant() switch
    {
        "auto" => SolverKind.Auto,
        "dense" => SolverKind.DenseNewton, "sparse" => SolverKind.SparseNewton,
        "bfs" or "sweep" => SolverKind.DistributionSweep,
        // fail loud: a typo used to silently run the auto-picked engine
        var other => FailFlag<SolverKind>("--solver", other, "'auto', 'dense', 'sparse' or 'bfs'"),
    };
    string[] suite = { "case9", "case14", "case30", "case57", "case118", "case300", "pegase/case1354pegase.m" };
    string? casesArg = FlagString(a, "--cases");
    // GR-701: one positional case at most (a second one used to be ignored), and not together with --cases (the
    // positional was dropped without a word); a --cases list that names no case is refused rather than "running"
    // nothing and exiting 1.
    string? positionalCase = SingleCasePositional("transient", a);
    if (casesArg is not null && positionalCase is not null)
    {
        Console.Error.WriteLine($"error: transient takes a positional case or --cases, not both (got '{positionalCase}' and --cases {casesArg}).");
        Environment.Exit(2);
    }
    List<string> cases = casesArg switch
    {
        null => new() { positionalCase ?? "case9" },   // a[1] may be a flag like --minutes
        "suite" or "all" => suite.ToList(),
        _ => casesArg.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
    };
    if (cases.Count == 0)
        FailFlag<string>("--cases", casesArg ?? "", "a comma-separated list of at least one case, or 'suite'");

    bool batch = cases.Count > 1;
    // F stream (October 2026, front doors; Ruling R1): --dyn-data <file>, the machine dynamic data file (gridsim-dynamics/2,
    // F23). The live run integrates the system swing, whose per-machine input is the inertia H, so the machines the file
    // binds take its H (a model copy); its GENROU, exciter and governor data are not part of this model, and the stderr
    // line and the run metadata say so. A file binds to ONE case's generators, so with a batch (--cases) it is refused,
    // exit 2, before anything runs. Without the flag every case runs on its loaded model, exactly as before.
    string? dynDataPath = FlagString(a, "--dyn-data");
    if (dynDataPath is not null && batch)
    {
        Console.Error.WriteLine("error: transient: --dyn-data binds to one case's generators, so it cannot be used with a batch of cases (--cases).");
        Environment.ExitCode = CliExit.Usage;
        return;
    }
    // The run-folder stamp is UTC, like every other stamp the CLI writes (it was local time, so one run folder could
    // mix a local-time name with UTC contents, and two machines in different zones named the same run differently).
    string stamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", System.Globalization.CultureInfo.InvariantCulture);
    string baseOut = FlagString(a, "--out")
        ?? DefaultResultsPath(batch ? $"transient-{stamp}" : $"transient-{San(cases[0])}-{stamp}");

    int ran = 0, failed = 0;
    foreach (string cname in cases)
    {
        GridModel m;
        try
        {
            m = cname.EndsWith(".m", StringComparison.OrdinalIgnoreCase)
                ? Gated.Matpower(cname)   // GR-702: the shared resolution (the path as given, then under data/matpower)
                : LoadNamed(cname, root);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"[transient] load fail {cname}: {ex.Message}");
            // D-DOC-130 (one rule for every verb): a single case argument that names no case at all is a usage error,
            // exit 2, before anything runs. In a batch (--cases) a failed load stays a 'load fail' line and exit 1 at
            // the end, as for the other batch verbs, so the rest of the batch still runs.
            if (!batch && ex is UnknownCaseException) { Environment.ExitCode = CliExit.Usage; return; }
            failed++;
            continue;
        }
        string? dynDataLabel = null;
        if (dynDataPath is not null)
        {
            MachineDynamicsSet dyn = LoadDynDataOrExit("transient", dynDataPath, m);   // exit 1 for a bad file, before any output
            Console.Error.WriteLine($"[transient] {cname}: {DynDataInertiaLine(m, dyn)}");
            m = DynDataCli.WithFileInertia(m, dyn);
            dynDataLabel = Path.GetFileName(dyn.Path);
        }
        RunTransient(cname, m, batch ? Path.Combine(baseOut, San(cname)) : baseOut,
            minutes, dtMs, logEvery, exportEvery, exportJac, tripMw, tripAt, tripWin, kind, dynDataLabel);
        ran++;
    }
    if (batch) Console.WriteLine($"[transient] batch of {cases.Count} done -> {Path.GetFullPath(baseOut)}");
    // Don't report success when nothing actually ran (every case failed to load).
    if (ran == 0) { Console.Error.WriteLine($"[transient] no cases ran ({failed} failed to load)."); Environment.ExitCode = 1; }
    // R215: some cases failing to load is not success either. The rest still ran; exit 1 (input error) unless a run
    // already set a code (3 for non-convergence, 2 for a refused trip), which is kept.
    else if (failed > 0)
    {
        Console.Error.WriteLine($"[transient] {failed} of {cases.Count} case(s) failed to load; see the 'load fail' lines above.");
        if (Environment.ExitCode == 0) Environment.ExitCode = 1;
    }

    static string San(string s) => string.Concat(s.Select(ch =>
        Path.GetInvalidFileNameChars().Contains(ch) || ch is '/' or '\\' ? '_' : ch));
}

void RunTransient(string caseLabel, GridModel model, string outDir, double minutes, double dtMs, int logEvery,
    int exportEvery, bool exportJac, double tripMw, double tripAt, double tripWin, SolverKind kind, string? dynDataLabel = null)
{
    // D-DOC-028: --asset-dynamics on a case with no asset bundle has nothing to enable; refused before anything is written.
    if (enableAssetDynamics && model.AssetDynamics is null && model.Protections is null)
    {
        Console.Error.WriteLine($"[transient] {caseLabel}: error: --asset-dynamics needs a case with an asset bundle (asset-classes.json " +
            "and asset-bindings.json, or protections.json), and this case has none, so the flag would do nothing. Aborting.");
        Environment.ExitCode = CliExit.InputError;
        return;
    }
    CliFiles.OutputFolder(Path.Combine(outDir, "exports"), "exports folder");   // D-DOC-072
    double dtSec = dtMs / 1000.0;
    long n = (long)Math.Round(minutes * 60000.0 / dtMs);
    // R216 backstop: the parse-time checks make n >= 1 for any sane input, but a step longer than the whole run
    // still rounds to zero slices. Refuse rather than write a summary of a run that never happened.
    if (n < 1)
    {
        Console.Error.WriteLine($"[transient] {caseLabel}: {minutes} min at {dtMs} ms is less than one slice - nothing to run. Aborting.");
        Environment.ExitCode = 2;
        return;
    }
    int tripTick = tripMw > 0 ? Math.Max(1, (int)Math.Round(tripAt / dtSec)) : -1;

    // A --trip-at past the end of the run means the contingency never fires: the run would otherwise complete
    // exit 0 with nadir ~ 50 Hz, silently answering "no event" instead of the trip that was asked for.
    if (tripMw > 0 && tripTick > n)
    {
        Console.Error.WriteLine($"[transient] {caseLabel}: --trip-at {tripAt}s is past the run end " +
                                $"({minutes} min = {n} slices @ {dtMs}ms) - the contingency never fires. Aborting.");
        Environment.ExitCode = 2;
        return;
    }

    // D-DOC-028 (October 2026, docs-session finding): transient built LiveSim without a DynamicsConfig, so --forming
    // (with --forming-inertia / --forming-damping) and --asset-dynamics were parsed, accepted and silently ignored, though
    // the comment on --asset-dynamics said 'honored by trip/transient'. They now reach the live frequency integrator
    // through LiveSim's DynamicsConfig (forming: the FrequencyIntegrator / AssetAwareFrequencyIntegrator forming kernel;
    // asset dynamics: the authored fleet, with the solved per-bus voltage and loading fed to its protections each tick).
    // With neither asked for, no config is passed, exactly as before, so every run without the flags is bit-identical.
    // --asset-dynamics on a case with no asset bundle (no asset-classes.json and no protections.json) has nothing to
    // enable: refused, exit 1, rather than a run that looks like an asset-dynamics run and is not.
    // (The --asset-dynamics bundle check is at the top of RunTransient, before any output folder is created.)
    DynamicsConfig? liveDynamics = formingMode != FormingMode.None || enableAssetDynamics
        ? new DynamicsConfig
        {
            Forming = formingMode,
            VirtualInertiaMwS = formingInertiaMwS,
            FormingDampingMwPerHz = formingDampingMwPerHz,
            EnableAssetDynamics = enableAssetDynamics,
            // N273 (October 2026, stream B2): LiveSim runs the swing at the model's nominal and refuses a config at another
            // (the case9 transient is a 60 Hz run since D2); for a 50 Hz case this is the same 50.0 as the default.
            NominalHz = model.FrequencyHz,
        }
        : null;
    var sim = new LiveSim(model, holdSteady: true, solver: kind, dynamicsConfig: liveDynamics);
    string desc = $"transient  case={caseLabel}  minutes={minutes}  dt={dtMs}ms  slices={n}  solver={sim.ActiveSolver}"
                + (tripMw > 0 ? $"  trip={tripMw}MW@{tripAt}s" : "")
                + (formingMode != FormingMode.None ? $"  forming={formingMode}  Ev={formingInertiaMwS / 1000.0}GVAs  Dv={formingDampingMwPerHz}MW/Hz" : "")
                + (enableAssetDynamics ? "  asset-dynamics=on" : "")
                + (dynDataLabel is not null ? $"  dyn-data={dynDataLabel} (inertia H only)" : "");   // F stream: --dyn-data only
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    using var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "timeseries.csv"), "timeseries.csv")) { AutoFlush = true };
    foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
    csv.WriteLine("tick,t_seconds,freq_hz,rocof_hz_s,gen_mw,demand_mw,iters,max_mismatch,vmin_pu,vmax_pu,solve_ms,converged");

    double nadir = double.NaN, nadirT = 0, maxRocof = 0, maxRocofT = 0;   // R216: no 999 Hz placeholder
    int nonConv = 0; long firstNonConv = -1, exportCount = 0;
    var wall = System.Diagnostics.Stopwatch.StartNew();
    Console.Error.WriteLine($"[transient] {caseLabel}: {n:N0} slices @ {dtMs}ms ({minutes} min) on {sim.ActiveSolver}...");
    if (inertiaModel == InertiaModel.Distributed)
    {
        (var doms, DominanceReport dm) = DomainAssignment.Assign(model);
        string dv = double.IsInfinity(dm.DeltaGVa) ? "sole" : dm.DeltaGVa.ToString("P0");
        Console.Error.WriteLine($"[transient] distributed inertia: {doms.Count} speed domains, deltaGVa {dv} " +
            "(per-tick integration remains the lumped live model; a distributed live integrator is a follow-up)");
    }

    for (long tick = 1; tick <= n; tick++)
    {
        double t = tick * dtSec;
        if (tick == tripTick) sim.TripInfeed(tripMw);
        bool inWindow = tripMw > 0 && Math.Abs(t - tripAt) <= tripWin;
        bool export = tick == 1 || inWindow || (exportEvery > 0 && tick % exportEvery == 0);
        var trace = export ? new GridSim.Core.Diagnostics.SolveTrace { CaptureJacobian = exportJac } : null;

        var sw = System.Diagnostics.Stopwatch.StartNew();
        SimFrame f = sim.Step((int)tick, dtMs / 60000.0, trace);
        sw.Stop();

        if (double.IsNaN(nadir) || f.FrequencyHz < nadir) { nadir = f.FrequencyHz; nadirT = t; }
        if (Math.Abs(f.RocofHzPerS) > Math.Abs(maxRocof)) { maxRocof = f.RocofHzPerS; maxRocofT = t; }
        if (!f.Result.Converged) { nonConv++; if (firstNonConv < 0) firstNonConv = tick; }

        if (tick == 1 || tick == n || inWindow || tick % logEvery == 0)
            csv.WriteLine($"{tick},{t:F4},{f.FrequencyHz:F5},{f.RocofHzPerS:F5},{f.GenerationMw:F2},{f.DemandMw:F2}," +
                          $"{f.Result.Iterations},{f.Result.MaxMismatch:E3},{f.Result.Vm.Min():F5},{f.Result.Vm.Max():F5}," +
                          $"{sw.Elapsed.TotalMilliseconds:F3},{f.Result.Converged}");
        if (export)
        {
            var meta = new GridSim.Core.IO.SolveExportMeta(caseLabel, RunInfo.Backend, RunInfo.GitCommit,
                DateTime.UtcNow.ToString("o"), sw.Elapsed.TotalMilliseconds,
                $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}");
            GridSim.Core.IO.SolveExport.WriteJson(CliFiles.Output(Path.Combine(outDir, "exports", $"slice-{tick:D9}.json"), "slice-N.json"), f.Model, f.Result, trace!, meta);
            exportCount++;
        }
        if (tick % GridSim.Cli.CliDefaults.TransientProgressEverySlices == 0)
            Console.Error.WriteLine($"[transient] {caseLabel}: {tick:N0}/{n:N0} ({100.0 * tick / n:F1}%), {tick / Math.Max(1, wall.Elapsed.TotalSeconds):N0} slices/s");
    }
    wall.Stop();

    var s = new System.Text.StringBuilder();
    s.AppendLine($"# Transient - {caseLabel}").AppendLine();
    foreach (string h in RunInfo.HeaderLines(desc)) s.AppendLine("    " + h);
    s.AppendLine()
     .AppendLine($"- slices: {n:N0} @ {dtMs} ms = {minutes} sim-min")
     .AppendLine($"- wall: {wall.Elapsed.TotalSeconds:F1} s ({n / Math.Max(1, wall.Elapsed.TotalSeconds):N0} slices/s)")
     .AppendLine($"- solver: {sim.ActiveSolver}")
     .AppendLine($"- frequency nadir: {nadir:F4} Hz at t={nadirT:F3} s")
     .AppendLine($"- max |RoCoF|: {maxRocof:F4} Hz/s at t={maxRocofT:F3} s")
     .AppendLine($"- non-convergence: {nonConv}" + (firstNonConv >= 0 ? $" (first at slice {firstNonConv})" : ""))
     .AppendLine($"- math exports: {exportCount}");
    File.WriteAllText(CliFiles.Output(Path.Combine(outDir, "summary.md"), "summary.md"), s.ToString());
    Console.WriteLine($"[transient] {caseLabel}: done in {wall.Elapsed.TotalSeconds:F1}s  nadir {nadir:F3}Hz  " +
                      $"maxRoCoF {maxRocof:F3}Hz/s  exports {exportCount}  -> {Path.GetFullPath(outDir)}");
    // Frequency/RoCoF computed from unconverged states are not trustworthy: exit 3 like gda-replay
    // so a CI gate (or a script) can tell a degraded run from a clean one.
    if (nonConv > 0) Environment.ExitCode = 3;
}

// replay-event <id> [--catalog file] [--trace csv] [--out dir]
//   The credibility gate: reproduce a RECORDED event's RoCoF/nadir with NO device, before any counterfactual.
// The forming switches (--forming, --forming-inertia, --forming-damping) and --asset-dynamics are parsed globally
// and removed from the argument list, so RequireVerbFlags cannot see them. Of the event verbs only scenario and fleet
// (N291, October 2026, stream B5) read the forming switches, and none reads --asset-dynamics (h0-study always runs the asset fleet). Refuse them where they
// would be ignored, with exit 2, instead of running a different study from the one asked for.
void RefuseIgnoredGlobalSwitches(string verb, bool usesForming)
{
    if (formingFlagsGiven && !usesForming)
    {
        Console.Error.WriteLine($"error: {verb} does not use --forming / --forming-inertia / --forming-damping (of the event verbs only scenario and fleet do); they would be silently ignored.");
        Environment.Exit(2);
    }
    if (assetDynamicsFlagGiven)
    {
        Console.Error.WriteLine($"error: {verb} does not use --asset-dynamics (it would be silently ignored).");
        Environment.Exit(2);
    }
}

// D-DOC-032 (October 2026, docs-session finding): scenario, fleet, evidence and h0-study take --trace <neso.csv>, exactly as
// replay-event does. Each of them runs the same credibility gate (ReplayValidator.Validate) before any counterfactual, and
// the gate scores the per-sample RMSE only when a trace is attached, so without the flag those verbs could not run the gate
// replay-event --trace runs: gb-2019-08-09 was Reproduced there and Marginal (RMSE 0.153 Hz) under replay-event --trace.
// Returns the event with the trace attached (or unchanged when the flag is absent), or null after printing the refusal
// (exit 2) when the file does not exist - a silently missing trace would score "RMSE n/a", indistinguishable from none.
// CF6 (main's ruling on N359 / CF6-F3, Ruling R1): the study verbs (scenario, fleet, evidence, h0-study) accept an event
// whose effective provenance (ReplayValidator.EffectiveProvenance, the weakest of its parts) is below DerivedFromRecorded,
// such as the SQSS design-basis screening event: a legitimate study input, but every output inherits the weaker tag. For
// such an event the run description (every CSV / markdown header and run-metadata.json) gains "  provenance=<tag>" and the
// console and summary gain the line below; for an event sourced from a record both are empty, so its output is unchanged.
static string DesignBasisDesc(GridEvent ev)
    => ReplayValidator.IsRecordedEvent(ev) ? "" : $"  provenance={ReplayValidator.EffectiveProvenance(ev)}";

static string? DesignBasisLine(GridEvent ev)
{
    if (ReplayValidator.IsRecordedEvent(ev)) return null;
    GridSim.Core.Diagnostics.ProvenanceTag eff = ReplayValidator.EffectiveProvenance(ev);
    return $"  input provenance: [{eff}]  (event '{ev.Id}' is effectively {eff}, the weakest of its parts): a design-basis study, "
        + "not a reproduction of history; every figure below inherits it and none is Recorded.";
}

static GridEvent? AttachTraceFlag(string verb, List<string> a, GridEvent ev)
{
    string? trace = FlagString(a, "--trace");
    if (trace is null) return ev;
    if (!File.Exists(trace))
    {
        Console.Error.WriteLine($"error: {verb}: --trace file not found: {Path.GetFullPath(trace)}");
        Environment.ExitCode = CliExit.Usage;
        return null;
    }
    return ev with { Outcome = ev.Outcome with { NesoTraceCsvPath = trace } };
}

// The --device file and the --device-inertia / --device-ffr pair are alternatives (scenario, evidence): with a file the
// two numbers used to be ignored without a word. Refuse the combination.
static void RefuseDeviceFileWithDeviceFlags(string verb, List<string> a)
{
    if (a.Contains("--device") && (a.Contains("--device-inertia") || a.Contains("--device-ffr")))
    {
        Console.Error.WriteLine($"error: {verb}: give either --device <file.json> or --device-inertia/--device-ffr, not both (the file would win and the numbers be ignored).");
        Environment.Exit(2);
    }
}

void RunReplayEvent(List<string> a, string root)
{
    RequireVerbFlags("replay-event", a, "--dump-catalog", "--catalog", "--trace", "--out");
    RefuseIgnoredGlobalSwitches("replay-event", usesForming: false);
    // --dump-catalog <path>: write the built-in placeholder catalog to disk so it can be edited / sourced.
    string? dump = FlagString(a, "--dump-catalog");
    if (dump is not null)
    {
        EventCatalog.Save(CliFiles.Output(dump, "event catalog"), EventCatalog.Builtin());
        Console.WriteLine($"wrote built-in catalog ({EventCatalog.Builtin().Count} events) -> {Path.GetFullPath(dump)}");
        return;
    }

    string? id = PositionalArg(a);   // not "the first non-flag token" - that grabs --catalog's value
    if (id is null)
    {
        Console.Error.WriteLine("usage: gridsim replay-event <id> [--catalog <file.json>] [--trace <neso.csv>] [--out <dir>]");
        Console.Error.WriteLine("Built-in events: " + string.Join(", ", EventCatalog.Builtin().Select(e => e.Id)));
        Console.Error.WriteLine("Reproduces the RECORDED RoCoF/nadir with NO device. A counterfactual is only credible");
        Console.Error.WriteLine("once the baseline is 'Reproduced'. Placeholder catalog figures are [VERIFY] until sourced.");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    string? catalog = FlagString(a, "--catalog");
    string? trace = FlagString(a, "--trace");
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"replay-{id}");

    GridEvent ev;
    try { ev = EventCatalog.Get(id, catalog); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 1; return; }

    // A --trace overrides the catalog's (data-gated) trace path so a real NESO CSV enables per-sample RMSE.
    // Fail loud on a missing file: TryPerSampleRmse silently returns null for it, and the run then
    // reports 'RMSE n/a (data-gated)' - indistinguishable from never passing --trace, silently
    // dropping the per-sample validation the user explicitly attached.
    if (trace is not null && !File.Exists(trace))
    {
        Console.Error.WriteLine($"error: --trace file not found: {Path.GetFullPath(trace)}");
        Environment.ExitCode = 2;
        return;
    }
    if (trace is not null) ev = ev with { Outcome = ev.Outcome with { NesoTraceCsvPath = trace } };

    // D-DOC-002: the attached trace is read inside Validate, and its reader refuses a row newer than the forward-inference
    // horizon. The catalog read above was guarded, this call was not, so a fresh trace crashed the verb. Now it is the
    // same refusal as every other event verb's: REJECTED and exit 2, before any output folder is created.
    ReplayResult res;
    // CF6 (main's ruling on N359, Ruling R1): replay-event presents its output as a reproduction of a recorded event, so
    // an event that is not Recorded or DerivedFromRecorded throughout (placeholder, Synthetic, Interpolated, or a recorded
    // event with a placeholder part) is refused here, by name, before the gate runs. The study verbs accept such events.
    try { ReplayValidator.RequireRecordedReplay(ev); res = ReplayValidator.Validate(ev); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = CliExit.Usage; return; }
    // N359 (CF6): the refusal above (and, since CF5, an output tag as input) is bad input data, reported by name, exit 1.
    // Every other event verb already reported InvalidDataException as exit 1; replay-event crashed on it.
    catch (InvalidDataException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }

    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    // CF6 (main's ruling on N359 / CF6-F3): the replay's provenance is the event's EFFECTIVE tag, the weakest of its parts
    // (the built-in recorded events carry DerivedFromRecorded loss figures, so DerivedFromRecorded, not their own Recorded).
    GridSim.Core.Diagnostics.ProvenanceTag replayProv = ReplayValidator.EffectiveProvenance(ev);
    string desc = $"replay-event  id={ev.Id}  provenance={replayProv}  verdict={res.Verdict}";
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    Console.WriteLine();
    Console.WriteLine($"=== Replay: {ev.Title} ===");
    Console.WriteLine($"  when (UTC):        {ev.WhenUtc:o}   provenance: {replayProv}" + (replayProv != ev.Provenance ? $" (event tagged {ev.Provenance}; the weakest of its parts)" : ""));
    Console.WriteLine($"  pre-event inertia: {ev.PreEventInertiaMwS / 1000:F1} GVA.s   demand: {ev.PreEventDemandMw / 1000:F1} GW   total loss: {ev.TotalLossMw:F0} MW");
    // D-DOC-035: a windowed record is corrected to an instantaneous slope before the inversion; the note says how (or
    // why no figure could be inferred, when the inferred inertia is NaN).
    string inferredText = double.IsNaN(res.InferredInertiaMwS) ? "n/a" : $"{res.InferredInertiaMwS / 1000:F1} GVA.s";
    Console.WriteLine($"  inferred inertia from recorded RoCoF: {inferredText} (cross-check vs {res.EventInertiaMwS / 1000:F1})");
    if (res.InertiaCrossCheckNote is { } inertiaNote) Console.WriteLine($"    ({inertiaNote})");
    Console.WriteLine();
    Console.WriteLine($"  RoCoF:  sim {res.SimulatedRocofHzPerS,7:+0.000;-0.000}   recorded {res.RecordedRocofHzPerS,7:+0.000;-0.000} Hz/s   ({res.RocofRelError:P0} error)");
    Console.WriteLine($"  Nadir:  sim {res.SimulatedNadirHz,7:F2}   recorded {res.RecordedNadirHz,7:F2} Hz   ({res.NadirErrorHz:F2} Hz error)");
    Console.WriteLine($"  Nadir envelope (declared-uncertainty corners): [{res.NadirWorstCornerHz:F2}, {res.NadirBestCornerHz:F2}] Hz - recorded "
        + (res.RecordedNadirInEnvelope ? "INSIDE (consistent within the model's own error bars)"
           : "OUTSIDE (a constant the corners don't cover - e.g. the inertia basis - is off)"));
    // With a trace attached, a trace that does not cover the whole scored window (or the event instant) is
    // reported on its own line rather than silently scored against the trace's last sample.
    string rmseText = res.PerSampleRmseHz is { } r ? $"{r:F3} Hz over {res.TraceSamplesScored} sample(s)"
        : res.TraceNote is not null ? "n/a"
        : "n/a (no 1-sec NESO trace attached - data-gated)";
    Console.WriteLine($"  RMSE vs trace: {rmseText}");
    if (res.TraceNote is { } traceNote) Console.WriteLine($"  WARNING: {traceNote}");
    // D-DOC-037: the back-test acceptance gate against the attached trace (nadir, RoCoF on the trace's 1 s basis, nadir
    // time), which caps Reproduced at Marginal when it fails. Printed only when a trace covering the window is attached.
    if (res.BackTest is { } bt)
        Console.WriteLine($"  back-test vs trace (gate 0.05 Hz / 0.05 Hz/s / 2.0 s): {(bt.Passed ? "PASS" : "FAIL")}  " +
            $"nadir {bt.NadirErrHz:F3} Hz, RoCoF sim {bt.SimRocofHzPerS:+0.000;-0.000} vs rec {bt.RecordedRocofHzPerS:+0.000;-0.000} Hz/s, " +
            $"nadir time sim {bt.SimNadirTimeS:F1} s vs rec {bt.RecordedNadirTimeS:F1} s ({bt.NadirTimeErrS:F1} s)");
    Console.WriteLine($"  assessment: {res.SimAssessment.Summary}");
    Console.WriteLine();
    Console.WriteLine($"  VERDICT: {res.Verdict.ToString().ToUpperInvariant()}"
        + (res.Verdict == ReplayVerdict.Reproduced ? "  - baseline reproduces the record; counterfactuals unlocked."
           : "  - NOT reproduced; do not run counterfactuals until the baseline matches (check [VERIFY] figures / tolerances)."));

    // Export the baseline swing solve so a reviewer can hand-check RoCoF/nadir the way they check the Jacobian.
    var meta = new FrequencyExportMeta(ev.Id, RunInfo.GitCommit, DateTime.UtcNow.ToString("o"), 0,
        $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}",
        // CF6 (downgrade only): the baseline is a SIMULATION of the event, so at best DerivedFromRecorded, and never more
        // than the event's effective tag. It used to carry the event's own tag (Recorded for the built-ins), which labelled
        // a model trajectory as a record.
        GridSim.Core.Diagnostics.ProvenanceTrust.Weakest(new[] { GridSim.Core.Diagnostics.ProvenanceTag.DerivedFromRecorded, replayProv }, $"event '{ev.Id}' baseline export"));
    // Declare the config the validator ACTUALLY simulated with (recorded
    // services, extended window) - a fresh default here contradicted the
    // exported trajectory.
    DynamicsConfig baselineCfg = res.EffectiveConfig ?? new DynamicsConfig();
    FrequencyExport.WriteJson(CliFiles.Output(Path.Combine(outDir, "baseline-frequency.json"), "baseline-frequency.json"),
        ev.PreEventInertiaMwS, ev.PreEventDemandMw, ev.ToFrequencyEvents(), baselineCfg, res.Simulated, meta);

    var s = new System.Text.StringBuilder();
    s.AppendLine($"# Replay - {ev.Title}").AppendLine();
    foreach (string h in RunInfo.HeaderLines(desc)) s.AppendLine("    " + h);
    s.AppendLine().AppendLine($"- provenance: **{replayProv}**" + (ev.Notes is null ? "" : $"  ({ev.Notes})"))
     .AppendLine($"- verdict: **{res.Verdict}**")
     .AppendLine($"- {res.Summary}")
     .AppendLine($"- inferred inertia from recorded RoCoF: {inferredText}" + (res.InertiaCrossCheckNote is { } n2 ? $" ({n2})" : ""))
     .AppendLine($"- baseline swing export: `baseline-frequency.json`");
    File.WriteAllText(CliFiles.Output(Path.Combine(outDir, "summary.md"), "summary.md"), s.ToString());
    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
    // Anything short of Reproduced unlocks no downstream counterfactual - a Marginal baseline is not a
    // green light. Exit non-zero for Marginal too, so a CI gate can't pass on a baseline that grounds nothing
    // (matches the evidence verb, which keys its exit code on CounterfactualUnlocked).
    if (res.Verdict != ReplayVerdict.Reproduced) Environment.ExitCode = 3;
}

// scenario --event <id> [--catalog f] [--inertia 260,155,120,102,50] [--device f.json]
//          [--device-inertia GVA] [--device-ffr GW] [--corners best,worst] [--out dir]
//   The counterfactual sweep. Gated: throws unless the no-device baseline reproduces the record.
void RunScenario(List<string> a, string root)
{
    RequireVerbFlags("scenario", a, "--event", "--catalog", "--out", "--device", "--device-inertia", "--device-ffr",
        "--inertia", "--corners", "--trace");
    RefuseIgnoredGlobalSwitches("scenario", usesForming: true);
    RefuseDeviceFileWithDeviceFlags("scenario", a);
    string? id = FlagString(a, "--event");
    if (id is null)
    {
        Console.Error.WriteLine("usage: gridsim scenario --event <id> [--catalog f] [--inertia 260,155,120,102,50]");
        Console.Error.WriteLine("                        [--device <f.json> | --device-inertia <GVA> --device-ffr <GW>]");
        Console.Error.WriteLine("                        [--corners best,worst] [--trace <neso.csv>] [--out <dir>]");
        Console.Error.WriteLine("Built-in events: " + string.Join(", ", EventCatalog.Builtin().Select(e => e.Id)));
        Console.Error.WriteLine("Sweeps inertia x device x corners. REQUIRES a reproduced baseline (reproduce reality first).");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    string? catalog = FlagString(a, "--catalog");
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"scenario-{id}");

    GridEvent ev;
    try { ev = EventCatalog.Get(id, catalog); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 1; return; }
    // D-DOC-032: the same --trace as replay-event, so the gate can score the per-sample RMSE.
    if (AttachTraceFlag("scenario", a, ev) is not { } scTraced) return;
    ev = scTraced;

    // Device: from --device JSON, else built from flags (a [VERIFY] placeholder TSGB if unspecified).
    DeviceConfig device;
    string? deviceFile = FlagString(a, "--device");
    if (deviceFile is not null)
        try { device = DeviceConfig.Load(deviceFile); }
        catch (Exception ex) { Console.Error.WriteLine($"error: --device '{deviceFile}': {ex.Message}"); Environment.Exit(2); return; }
    else device = new DeviceConfig("tsgb",
        RotationalInertiaMwS: FlagDouble(a, "--device-inertia", GridSim.Cli.CliDefaults.DefaultDeviceInertiaGvaS) * 1000.0, // GVA.s -> MW.s
        FastResponseMw: FlagDouble(a, "--device-ffr", GridSim.Cli.CliDefaults.DefaultDeviceFfrGw) * 1000.0);           // GW -> MW

    IReadOnlyList<double> inertia = ParseDoubleList(FlagString(a, "--inertia"), "--inertia", 0, minExclusive: true) ?? SweepAxes.GbInertiaTrajectoryGvaS;
    IReadOnlyList<Corner> corners = ParseCorners(FlagString(a, "--corners")) ?? new[] { Corner.Best, Corner.Worst };

    // Forming defaults to None (byte-identical base config); a --forming flag lets an H->0 counterfactual
    // carry a virtual former so the frequency is FORMED rather than floored.
    var spec = new ScenarioSpec(ev,
        new SweepAxes(inertia, new[] { DeviceConfig.None, device }, corners),
        new DynamicsConfig
        {
            Forming = formingMode,
            VirtualInertiaMwS = formingInertiaMwS,
            FormingDampingMwPerHz = formingDampingMwPerHz,
        }, ReplayTolerance.Default);

    ScenarioMatrix matrix;
    try { matrix = ScenarioEngine.Run(spec); }
    catch (BaselineNotReproducedException ex)
    {
        Console.Error.WriteLine($"GATE FAILED: {ex.Message}");
        Console.Error.WriteLine("Fix the event's [VERIFY] figures (or tolerances) until 'replay-event' reports Reproduced, then re-run.");
        Environment.ExitCode = 3;
        return;
    }
    // D-DOC-032: an attached trace is read by the gate under the forward-inference guard (a fresh row is a refusal, exit 2)
    // and (D-DOC-027) a damaged row is refused by name (exit 1).
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = CliExit.Usage; return; }
    catch (InvalidDataException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }

    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    string desc = $"scenario  event={ev.Id}  device={device.Name}  inertia=[{string.Join(",", inertia)}]  corners=[{string.Join(",", corners)}]"
        + DesignBasisDesc(ev);   // CF6: empty for a recorded event
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    // ---- console: the risk curve is the headline ----
    Console.WriteLine();
    Console.WriteLine($"=== Counterfactual scenario: {ev.Title} ===");
    if (DesignBasisLine(ev) is { } scProv) Console.WriteLine(scProv);   // CF6: only for an event below DerivedFromRecorded
    Console.WriteLine($"  baseline gate: {matrix.BaselineVerdict}   device: {device.Name} " +
                      $"({device.RotationalInertiaMwS / 1000:F1} GVA.s inertia + {device.FastResponseMw / 1000:F2} GW FFR)");
    Console.WriteLine($"  LFDD first-stage threshold: {matrix.LfddThresholdHz:F1} Hz  (nominal corner)");
    Console.WriteLine();
    Console.WriteLine($"  {"inertia",8} | {"RoCoF no-dev",12}  {"nadir",7} {"LFDD",5} | {"RoCoF +dev",11}  {"nadir",7} {"LFDD",5} | avoided");
    Console.WriteLine("  " + new string('-', 84));
    foreach (RiskPoint p in matrix.RiskCurve.Points)
        Console.WriteLine($"  {p.InertiaGvaS,6:F0}GV | {p.RocofNoDevice,10:+0.000;-0.000}Hz/s {p.NadirNoDevice,6:F2}Hz {(p.LfddNoDevice ? " YES" : "  no"),5} | " +
                          $"{p.RocofWithDevice,9:+0.000;-0.000}Hz/s {p.NadirWithDevice,6:F2}Hz {(p.LfddWithDevice ? " YES" : "  no"),5} | {(p.LfddAvoidedByDevice ? "*** YES ***" : "-")}");

    int avoided = matrix.RiskCurve.Points.Count(p => p.LfddAvoidedByDevice);
    Console.WriteLine();
    Console.WriteLine($"  device avoids LFDD at {avoided}/{matrix.RiskCurve.Points.Count} inertia levels.");

    // ---- artefacts ----
    WriteScenarioCsvs(outDir, matrix, desc);
    // Headline counterfactual export: the device at the lowest swept inertia, worst corner (the hardest case).
    // Apply the event's RECORDED response services exactly as ScenarioEngine does for every matrix
    // cell - without them the headline artifact was simulated with 0 MW of services and a 50.00 Hz
    // start, contradicting the very matrix cell it claims to headline.
    double lowInertia = inertia.Min();
    DynamicsConfig hardCfg = ScenarioCorners.Apply(device.Apply(ev.ApplyRecordedServices(spec.BaseConfig)),
        corners.Contains(Corner.Worst) ? Corner.Worst : corners[0]);
    FrequencyResponse hard = FrequencyDynamics.Simulate(lowInertia * 1000.0, ev.PreEventDemandMw, ev.ExogenousLossEvents(), hardCfg);
    var meta = new FrequencyExportMeta($"{ev.Id}+{device.Name}@{lowInertia:F0}GVAs", RunInfo.GitCommit,
        DateTime.UtcNow.ToString("o"), 0,
        $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}",
        ProvenanceTag.Counterfactual);
    FrequencyExport.WriteJson(CliFiles.Output(Path.Combine(outDir, "counterfactual-frequency.json"), "counterfactual-frequency.json"),
        lowInertia * 1000.0, ev.PreEventDemandMw, ev.ExogenousLossEvents(), hardCfg, hard, meta);

    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
}

void WriteScenarioCsvs(string outDir, ScenarioMatrix matrix, string desc)
{
    using (var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "matrix.csv"), "matrix.csv")))
    {
        foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
        csv.WriteLine("inertia_gvas,device,corner,rocof_hz_s,nadir_hz,settle_hz,lfdd_at_risk,assessment");
        foreach (ScenarioCell c in matrix.Cells)
            csv.WriteLine($"{c.InertiaGvaS:F0},{c.Device},{c.Corner},{c.RocofHzPerS:F4},{c.NadirHz:F3},{c.SettleHz:F3},{c.LfddAtRisk},\"{c.Assessment}\"");
    }
    using (var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "risk-curve.csv"), "risk-curve.csv")))
    {
        foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
        csv.WriteLine("inertia_gvas,rocof_no_device,nadir_no_device,lfdd_no_device,rocof_with_device,nadir_with_device,lfdd_with_device,lfdd_avoided_by_device");
        foreach (RiskPoint p in matrix.RiskCurve.Points)
            csv.WriteLine($"{p.InertiaGvaS:F0},{p.RocofNoDevice:F4},{p.NadirNoDevice:F3},{p.LfddNoDevice},{p.RocofWithDevice:F4},{p.NadirWithDevice:F3},{p.LfddWithDevice},{p.LfddAvoidedByDevice}");
    }
    var s = new System.Text.StringBuilder();
    s.AppendLine($"# Scenario - {matrix.EventId}").AppendLine();
    foreach (string h in RunInfo.HeaderLines(desc)) s.AppendLine("    " + h);
    s.AppendLine().AppendLine($"- baseline gate: **{matrix.BaselineVerdict}**")
     .AppendLine($"- LFDD first-stage threshold: {matrix.LfddThresholdHz:F1} Hz")
     .AppendLine($"- device ({matrix.RiskCurve.DeviceName}) avoids LFDD at " +
                 $"{matrix.RiskCurve.Points.Count(p => p.LfddAvoidedByDevice)}/{matrix.RiskCurve.Points.Count} inertia levels")
     .AppendLine().AppendLine("| inertia GVA.s | RoCoF no-dev | nadir no-dev | LFDD | RoCoF +dev | nadir +dev | LFDD | avoided |")
     .AppendLine("|---|---|---|---|---|---|---|---|");
    foreach (RiskPoint p in matrix.RiskCurve.Points)
        s.AppendLine($"| {p.InertiaGvaS:F0} | {p.RocofNoDevice:F3} | {p.NadirNoDevice:F2} | {(p.LfddNoDevice ? "YES" : "no")} | " +
                     $"{p.RocofWithDevice:F3} | {p.NadirWithDevice:F2} | {(p.LfddWithDevice ? "YES" : "no")} | {(p.LfddAvoidedByDevice ? "**YES**" : "-")} |");
    File.WriteAllText(CliFiles.Output(Path.Combine(outDir, "summary.md"), "summary.md"), s.ToString());
}

// h0-study --event <id> [--catalog f] [--dir case] [--sync-inertia-scale 1,0.5,0.25,0]
//          [--gfm-fraction 0,0.25,0.5,0.75,1] [--gfm-class C] [--gfl-class C] [--corners best,worst] [--out dir]
//   The H=0 counterfactual harness. Fleet-routed (per-asset dynamics + grid-forming formation). Gated:
//   throws unless the event's no-device baseline reproduces the record (reproduce reality first).
void RunH0Study(List<string> a, string root)
{
    RequireVerbFlags("h0-study", a, "--event", "--catalog", "--dir", "--out", "--sync-inertia-scale", "--gfm-fraction",
        "--corners", "--gfm-class", "--gfl-class", "--trace");
    RefuseIgnoredGlobalSwitches("h0-study", usesForming: false);
    string? id = FlagString(a, "--event");
    if (id is null)
    {
        Console.Error.WriteLine("usage: gridsim h0-study --event <id> [--catalog f] [--dir case]");
        Console.Error.WriteLine("                        [--sync-inertia-scale 1,0.5,0.25,0] [--gfm-fraction 0,0.25,0.5,0.75,1]");
        Console.Error.WriteLine("                        [--gfm-class gfm-vsm-study-2024] [--gfl-class gfl-wind-2024] [--corners best,worst]");
        Console.Error.WriteLine("                        [--trace <neso.csv>] [--out <dir>]");
        Console.Error.WriteLine("Built-in events: " + string.Join(", ", EventCatalog.Builtin().Select(e => e.Id)));
        Console.Error.WriteLine("Scales REAL synchronous inertia toward 0 x makes the converter fleet grid-forming. REQUIRES a reproduced baseline.");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    string? catalog = FlagString(a, "--catalog");
    string caseDir = FlagString(a, "--dir") ?? Path.Combine(root, "data", "gb-synthetic");
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"h0-study-{id}");

    GridEvent ev;
    try { ev = EventCatalog.Get(id, catalog); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 1; return; }
    // D-DOC-032: the same --trace as replay-event, so the gate can score the per-sample RMSE.
    if (AttachTraceFlag("h0-study", a, ev) is not { } h0Traced) return;
    ev = h0Traced;

    GridModel model;
    try { model = Gated.Dir(caseDir); }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{caseDir}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }
    if (model.AssetDynamics is null)
    {
        Console.Error.WriteLine($"error: case '{caseDir}' ships no asset-classes.json/asset-bindings.json - the H=0 study needs a converter fleet to transform.");
        Environment.ExitCode = 1;
        return;
    }

    IReadOnlyList<double> scales = ParseDoubleList(FlagString(a, "--sync-inertia-scale"), "--sync-inertia-scale", 0, 1) ?? new[] { 1.0, 0.5, 0.25, 0.0 };
    IReadOnlyList<double> fractions = ParseDoubleList(FlagString(a, "--gfm-fraction"), "--gfm-fraction", 0, 1) ?? new[] { 0.0, 0.25, 0.5, 0.75, 1.0 };
    IReadOnlyList<Corner> corners = ParseCorners(FlagString(a, "--corners")) ?? new[] { Corner.Best, Corner.Worst };
    string gfmClass = FlagString(a, "--gfm-class") ?? "gfm-vsm-study-2024";
    string gflClass = FlagString(a, "--gfl-class") ?? "gfl-wind-2024";

    var spec = new H0StudySpec(ev, model, scales, fractions, corners, gfmClass, gflClass,
        new DynamicsConfig { EnableAssetDynamics = true }, ReplayTolerance.Default);

    H0StudyResult result;
    try { result = H0StudyEngine.Run(spec); }
    catch (BaselineNotReproducedException ex)
    {
        Console.Error.WriteLine($"GATE FAILED: {ex.Message}");
        Console.Error.WriteLine("Fix the event's [VERIFY] figures (or tolerances) until 'replay-event' reports Reproduced, then re-run.");
        Environment.ExitCode = 3;   // the reproduced-baseline gate is the ONLY exit-3 condition
        return;
    }
    // D-DOC-032: a fresh row in an attached trace is a forward-inference refusal (exit 2), as on every event verb; it used
    // to fall into the catch-all below as exit 1.
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = CliExit.Usage; return; }
    catch (Exception ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 1; return; }

    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    string desc = $"h0-study  event={ev.Id}  case={Path.GetFileName(caseDir)}  gfm={gfmClass}  gfl={gflClass}  " +
                  $"scales=[{string.Join(",", scales)}]  fractions=[{string.Join(",", fractions)}]  corners=[{string.Join(",", corners)}]"
                  + DesignBasisDesc(ev);   // CF6: empty for a recorded event
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    // ---- console: the fraction x scale bifurcation table (per corner) ----
    Console.WriteLine();
    Console.WriteLine($"=== H=0 counterfactual: {ev.Title} ===");
    if (DesignBasisLine(ev) is { } h0Prov) Console.WriteLine(h0Prov);   // CF6: only for an event below DerivedFromRecorded
    // R287 (B4, October 2026): dP is the RoCoF-setting loss (the steps in the first 5 s, the analytic RoCoF's dP); the
    // whole staged total is printed beside it. Before: "dP=<total> MW", the sum of every staged loss.
    Console.WriteLine($"  baseline gate: {result.BaselineVerdict}   dP={result.RocofSettingLossMw:F0} MW (first {GridSim.Core.Events.GridEvent.RocofSettingWindowSeconds:0} s; " +
                      $"{result.TotalExogenousLossMw:F0} MW over the whole event)   LFDD stage: {result.LfddThresholdHz:F1} Hz");
    Console.WriteLine($"  GFM class: {gfmClass}   GFL class: {gflClass}   (Ev is virtual control inertia, NEVER in real E)");
    // R289 (B4, October 2026): converter units are tagged whole, so a requested fraction can be overshot by one unit's
    // MW; say so (once per requested fraction) whenever the realised share differs from the axis value.
    var overshoots = result.Cells.GroupBy(c => c.GfmFraction).Select(g => g.First())
        .Where(c => c.RealisedGfmFraction != c.GfmFraction).ToList();
    if (overshoots.Count > 0)
        Console.WriteLine("  GFM fraction realised by whole units: " +
            string.Join(", ", overshoots.Select(c => $"{c.GfmFraction:F2} -> {c.RealisedGfmFraction:F3}")));
    foreach (Corner corner in corners)
    {
        Console.WriteLine();
        Console.WriteLine($"  corner {corner}: cell = nadir Hz / verdict  (HELD=formed & clear of LFDD, LFDD=below stage, CASC=Loss-of-Mains cascade, NaN=un-formable)");
        Console.Write($"  {"scale\\gfm",10} |");
        foreach (double f in fractions) Console.Write($" {f,10:F2}");
        Console.WriteLine();
        Console.WriteLine("  " + new string('-', 12 + 11 * fractions.Count));
        foreach (double s in scales)
        {
            Console.Write($"  {s,10:F2} |");
            foreach (double f in fractions)
            {
                H0StudyCell c = result.Cells.First(x =>
                    x.SyncInertiaScale == s && x.GfmFraction == f && x.Corner == corner);
                string verdict = c.FormingDependent ? "NaN"
                    : c.CascadeLossOfMains ? "CASC"
                    : c.LfddAtRisk ? "LFDD"
                    : "HELD";
                string nadir = double.IsNaN(c.NadirHz) ? "  -  " : $"{c.NadirHz,5:F2}";
                Console.Write($" {nadir}{verdict,5}");
            }
            Console.WriteLine();
        }
    }
    int formingDep = result.Cells.Count(c => c.FormingDependent);
    int held = result.Cells.Count(c => !c.FormingDependent && !c.CascadeLossOfMains && !c.LfddAtRisk);
    Console.WriteLine();
    Console.WriteLine($"  {held}/{result.Cells.Count} cells HELD (formed, clear of LFDD); {formingDep} forming-dependent (H=0, no grid-forming source).");
    Console.WriteLine("  Note: forming-dependent cells are expected DATA, not an error - the run still exits 0.");

    // ---- artefacts ----
    var meta = new H0StudyMeta(ev.Id, RunInfo.GitCommit, DateTime.UtcNow.ToString("o"),
        $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}",
        gfmClass, gflClass, ProvenanceTag.Counterfactual);
    H0StudyExport.WriteJson(CliFiles.Output(Path.Combine(outDir, "h0-study.json"), "h0-study.json"), result, meta);
    WriteH0StudyCsv(outDir, result, desc);

    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
}

void WriteH0StudyCsv(string outDir, H0StudyResult result, string desc)
{
    using (var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "matrix.csv"), "matrix.csv")))
    {
        foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
        // R289 (B4, October 2026): realised_gfm_fraction (the share whole converter units actually realised) follows the
        // requested gfm_fraction; a fill can overshoot the request by up to one unit's MW.
        csv.WriteLine("sync_inertia_scale,gfm_fraction,realised_gfm_fraction,corner,system_inertia_gvas,virtual_inertia_mws,effective_forming_inertia_mws," +
                      "bare_inertia_rocof,rocof_hz_s,nadir_hz,settle_hz,tripped_count,total_tripped_mw,forming_dependent,formed_by,lfdd_at_risk,cascade_lom");
        static string N(double v) => double.IsNaN(v) ? "NaN" : v.ToString("F4", System.Globalization.CultureInfo.InvariantCulture);
        foreach (H0StudyCell c in result.Cells)
            csv.WriteLine($"{c.SyncInertiaScale:F4},{c.GfmFraction:F4},{c.RealisedGfmFraction:F4},{c.Corner},{c.SystemInertiaGvaS:F4},{c.VirtualInertiaMwS:F2}," +
                          $"{c.EffectiveFormingInertiaMwS:F2},{N(c.BareInertiaRocofHzPerS)},{N(c.RocofHzPerS)},{N(c.NadirHz)},{N(c.SettleHz)}," +
                          $"{c.TrippedCount},{c.TotalTrippedMw:F1},{c.FormingDependent},{c.FormedBy},{c.LfddAtRisk},{c.CascadeLossOfMains}");
    }
    var s = new System.Text.StringBuilder();
    s.AppendLine($"# H=0 study - {result.EventId}").AppendLine();
    foreach (string h in RunInfo.HeaderLines(desc)) s.AppendLine("    " + h);
    s.AppendLine().AppendLine($"- baseline gate: **{result.BaselineVerdict}**")
     .AppendLine($"- dP (RoCoF-setting loss, first {GridSim.Core.Events.GridEvent.RocofSettingWindowSeconds:0} s): {result.RocofSettingLossMw:F0} MW; " +
                 $"total exogenous loss {result.TotalExogenousLossMw:F0} MW; largest single loss {result.LargestSingleLossMw:F0} MW; " +
                 $"LFDD first stage {result.LfddThresholdHz:F1} Hz")
     .AppendLine($"- cells: {result.Cells.Count}; forming-dependent (H=0, no grid-forming source): {result.Cells.Count(c => c.FormingDependent)}")
     .AppendLine().AppendLine("| scale | gfm | corner | E_real GVA.s | Ev MW.s | RoCoF Hz/s | nadir Hz | tripped MW | verdict |")
     .AppendLine("|---|---|---|---|---|---|---|---|---|");
    foreach (H0StudyCell c in result.Cells)
    {
        string verdict = c.FormingDependent ? "un-formable (NaN)" : c.CascadeLossOfMains ? "CASCADE" : c.LfddAtRisk ? "LFDD" : "HELD";
        string rocof = double.IsNaN(c.RocofHzPerS) ? "-" : c.RocofHzPerS.ToString("F3", System.Globalization.CultureInfo.InvariantCulture);
        string nadir = double.IsNaN(c.NadirHz) ? "-" : c.NadirHz.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
        // R289: the gfm column shows the realised share in brackets when whole units could not hit the request.
        string gfmText = c.RealisedGfmFraction == c.GfmFraction ? $"{c.GfmFraction:F2}" : $"{c.GfmFraction:F2} ({c.RealisedGfmFraction:F2} realised)";
        s.AppendLine($"| {c.SyncInertiaScale:F2} | {gfmText} | {c.Corner} | {c.SystemInertiaGvaS:F1} | {c.VirtualInertiaMwS:F0} | {rocof} | {nadir} | {c.TotalTrippedMw:F0} | {verdict} |");
    }
    File.WriteAllText(CliFiles.Output(Path.Combine(outDir, "summary.md"), "summary.md"), s.ToString());
}

// List/enum flag parsers FAIL LOUD like the scalar ones: a typo in a --inertia/--units/--corners value
// exits 2 with a clear one-line message instead of throwing a raw FormatException/ArgumentException stack
// trace out of Main.
// GR-197: each list names the flag it came from (every error used to say "--inertia/list"), and its values must be
// finite and inside [min, max]: NaN, Infinity and impossible fractions used to run as sweep cells.
static IReadOnlyList<double>? ParseDoubleList(string? csv, string flag, double min = double.NegativeInfinity, double max = double.PositiveInfinity,
    bool minExclusive = false) =>
    string.IsNullOrWhiteSpace(csv) ? null
    : csv.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
         .Select(t => double.TryParse(t, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double v)
                      && double.IsFinite(v) && (minExclusive ? v > min : v >= min) && v <= max
                      ? v
                      : FailFlag<double>(flag, t, $"a comma-separated list of finite numbers {(minExclusive ? "above" : "from")} " +
                          $"{min.ToString(System.Globalization.CultureInfo.InvariantCulture)}" +
                          (double.IsPositiveInfinity(max) ? "" : $" to {max.ToString(System.Globalization.CultureInfo.InvariantCulture)}"))).ToList();

static IReadOnlyList<Corner>? ParseCorners(string? csv) =>
    string.IsNullOrWhiteSpace(csv) ? null
    : csv.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
         .Select(t => Enum.TryParse<Corner>(t, ignoreCase: true, out Corner c)
                      ? c : FailFlag<Corner>("--corners", t, "one of: " + string.Join(", ", Enum.GetNames<Corner>()))).ToList();

static IReadOnlyList<int>? ParseIntList(string? csv, string flag) =>
    string.IsNullOrWhiteSpace(csv) ? null
    : csv.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
         .Select(t => int.TryParse(t, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out int v) && v >= 1
                      ? v : FailFlag<int>(flag, t, "a comma-separated list of whole numbers, 1 or more")).ToList();

// evidence --event <id> [--catalog f] [--device f.json | --device-inertia GVA --device-ffr GW]
//          [--inertia 260,155,120,102,50] [--cf-inertia GVA] [--units N] [--stagger S]
//          [--voll £/MWh] [--duration h] [--out dir]
//   The umbrella dossier: recorded vs simulated vs counterfactual + risk curve + fleet + avoided cost. Gated.
void RunEvidence(List<string> a, string root)
{
    RequireVerbFlags("evidence", a, "--event", "--catalog", "--out", "--device", "--device-inertia", "--device-ffr",
        "--inertia", "--cf-inertia", "--units", "--stagger", "--voll", "--voll-source", "--duration", "--trace");
    RefuseIgnoredGlobalSwitches("evidence", usesForming: false);
    RefuseDeviceFileWithDeviceFlags("evidence", a);
    string? id = FlagString(a, "--event");
    if (id is null)
    {
        Console.Error.WriteLine("usage: gridsim evidence --event <id> [--catalog f] [--device <f.json> | --device-inertia <GVA> --device-ffr <GW>]");
        Console.Error.WriteLine("                        [--inertia 260,155,120,102,50] [--cf-inertia <GVA>] [--units N] [--stagger S]");
        Console.Error.WriteLine("                        [--voll <GBP/MWh>] [--voll-source <S322|S323|S324>] [--duration <h>] [--trace <neso.csv>] [--out <dir>]");
        Console.Error.WriteLine("Built-in events: " + string.Join(", ", EventCatalog.Builtin().Select(e => e.Id)));
        Console.Error.WriteLine("Assembles the one-dossier case (reproduce -> counterfactual -> risk curve -> fleet -> avoided cost). Gated.");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    string? catalog = FlagString(a, "--catalog");
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"evidence-{id}");

    GridEvent ev;
    try { ev = EventCatalog.Get(id, catalog); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 1; return; }
    // D-DOC-032: the same --trace as replay-event, so the gate below can score the per-sample RMSE.
    if (AttachTraceFlag("evidence", a, ev) is not { } evTraced) return;
    ev = evTraced;

    DeviceConfig device;
    string? deviceFile = FlagString(a, "--device");
    if (deviceFile is not null)
        try { device = DeviceConfig.Load(deviceFile); }
        catch (Exception ex) { Console.Error.WriteLine($"error: --device '{deviceFile}': {ex.Message}"); Environment.Exit(2); return; }
    else device = new DeviceConfig("tsgb", FlagDouble(a, "--device-inertia", GridSim.Cli.CliDefaults.DefaultDeviceInertiaGvaS) * 1000.0, FlagDouble(a, "--device-ffr", GridSim.Cli.CliDefaults.DefaultDeviceFfrGw) * 1000.0);

    // D-DOC-033 (October 2026, docs-session finding): --voll-source used to accept ANY text and tag the VoLL Recorded on the
    // word of the flag. It must now name a reference in docs/reference/voll that states a GB VoLL (S322, S323, S324), and
    // --voll must equal a figure that reference states; anything else is a usage error (exit 2) naming what the reference
    // does state. (Before N359 the VoLL input was then tagged Recorded; since N359 (CF6) the citation is recorded but the
    // tag stays CuratedPlaceholder: see below.) The outage duration has no source flag and stays a
    // CuratedPlaceholder, and the avoided cost takes the weaker of the two tags, so it stays CuratedPlaceholder: citing a
    // VoLL no longer promotes a cost whose other factor is still a placeholder.
    double vollPerMwh = FlagDouble(a, "--voll", GridSim.Cli.CliDefaults.DefaultVollGbpPerMwh);
    string? vollSource = FlagString(a, "--voll-source");
    GridSim.Core.Evidence.VollSource? citedVoll = null;
    if (vollSource is not null)
    {
        citedVoll = GridSim.Core.Evidence.VollSources.Find(vollSource, vollPerMwh);
        if (citedVoll is null)
        {
            IReadOnlyList<double> figures = GridSim.Core.Evidence.VollSources.FiguresOf(vollSource);
            string ids = string.Join(", ", GridSim.Core.Evidence.VollSources.Ids);
            Console.Error.WriteLine(figures.Count == 0
                ? $"error: evidence: --voll-source '{vollSource}' is not a reference that states a GB value of lost load. " +
                  $"Name one of {ids} (docs/reference/voll), with --voll set to a figure it states."
                : $"error: evidence: --voll {vollPerMwh.ToString(System.Globalization.CultureInfo.InvariantCulture)} is not a figure {vollSource.Trim().ToUpperInvariant()} states; " +
                  $"it states {string.Join(" and ", figures.Select(v => v.ToString("0", System.Globalization.CultureInfo.InvariantCulture)))} GBP/MWh.");
            Environment.ExitCode = CliExit.Usage;
            return;
        }
    }

    IReadOnlyList<double> inertia = ParseDoubleList(FlagString(a, "--inertia"), "--inertia", 0, minExclusive: true) ?? SweepAxes.GbInertiaTrajectoryGvaS;
    var spec = new EvidenceSpec(ev, device, inertia,
        CounterfactualInertiaGvaS: FlagDouble(a, "--cf-inertia", ev.PreEventInertiaMwS / 1000.0),
        FleetUnits: FlagInt(a, "--units", 100),
        FleetStaggerSeconds: FlagDouble(a, "--stagger", GridSim.Cli.CliDefaults.DefaultFleetStaggerS),
        AvoidedCost: new AvoidedCostInputs(vollPerMwh, FlagDouble(a, "--duration", GridSim.Cli.CliDefaults.DefaultLfddDurationH),
            // N359 (CF6, technical ch. 8 downgrade-only): a cited VoLL keeps the policy figure's tag. The citation is
            // checked above and carried as VollSourceId (printed as "VoLL source: ..."), but it does not re-source the
            // figure from a record of the event, so it no longer raises the tag to Recorded on the word of the flag
            // (AvoidedCost.FromLfddAvoided now refuses a raised VoLL tag).
            VollProvenance: GridSim.Core.Evidence.AvoidedCost.VollBaseProvenance,
            DurationProvenance: GridSim.Core.Diagnostics.ProvenanceTag.CuratedPlaceholder,
            VollSourceId: citedVoll?.Id));

    // D-DOC-032 / D-DOC-002 class: the gate reads an attached trace under the forward-inference guard and (D-DOC-027) refuses
    // a damaged row; both are refusals with their own exit codes, never a crash.
    EvidenceReport report;
    try { report = EvidenceReport.Build(spec); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = CliExit.Usage; return; }
    catch (InvalidDataException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }

    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    string desc = $"evidence  event={ev.Id}  device={device.Name}  baseline={report.BaselineVerdict}" + DesignBasisDesc(ev);   // CF6
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);
    report.WriteJson(CliFiles.Output(Path.Combine(outDir, "evidence.json"), "evidence.json"));

    Console.WriteLine();
    Console.WriteLine($"=== Evidence dossier: {report.EventTitle} ===");
    Console.WriteLine($"  when: {report.WhenUtc:o}   event provenance: {report.EventProvenance}   baseline gate: {report.BaselineVerdict}");
    if (DesignBasisLine(ev) is { } evProv) Console.WriteLine(evProv);   // CF6: only for an event below DerivedFromRecorded
    Console.WriteLine();
    Console.WriteLine($"  {"column",-42} {"RoCoF",10} {"nadir",8} {"LFDD",5}  {"dev inertia",12} {"dev FFR",8}");
    Console.WriteLine("  " + new string('-', 92));
    foreach (EvidenceColumn c in report.Columns)
        Console.WriteLine($"  {c.Label,-42} {c.RocofHzPerS,7:+0.000;-0.000}Hz/s {c.NadirHz,6:F2}Hz {(c.LfddAtRisk ? "YES" : "no"),5}  " +
                          $"{c.DeviceRotationalInertiaGvaS,9:F1}GVAs {c.DeviceFfrGw,5:F2}GW   [{c.Provenance}]");

    if (report.Fleet is { } f)
    {
        Console.WriteLine();
        Console.WriteLine($"  single-vs-fleet @ {f.InertiaGvaS:F0} GVA.s: aggregate nadir {f.AggregateNadirHz:F2} Hz vs {f.Units}-unit fleet {f.FleetNadirHz:F2} Hz " +
                          $"(FFR@nadir {f.AggregateFfrAtNadirMw:F0} vs {f.FleetFfrAtNadirMw:F0} MW).");
    }
    if (report.AvoidedCost is { } ac)
    {
        Console.WriteLine();
        // D-DOC-135 (DOC-17): plain ASCII "GBP" in place of the pound sign, which the Windows console printed as '?'.
        Console.WriteLine($"  AVOIDED COST: {ac.LfddMwShedAvoided:F0} MW shed x {ac.DurationHours:F2} h x GBP {ac.VollPerMwh:N0}/MWh = GBP {ac.AvoidedCostGbp:N0}  [{ac.Provenance}]");
        Console.WriteLine($"                ({ac.Basis})");
        // D-DOC-033: each input's own tag, so a reader sees which factor holds the cost at its tag.
        Console.WriteLine($"                VoLL [{ac.VollProvenance}]   duration [{ac.DurationProvenance}]");
        if (citedVoll is not null) Console.WriteLine($"                VoLL source: {citedVoll.Id}, {citedVoll.Title}: {citedVoll.Where}");
    }
    Console.WriteLine();
    Console.WriteLine($"  {report.Summary}");

    WriteEvidenceMd(outDir, report, desc);
    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
    if (!report.CounterfactualUnlocked) Environment.ExitCode = 3;
}

void WriteEvidenceMd(string outDir, EvidenceReport report, string desc)
{
    var s = new System.Text.StringBuilder();
    s.AppendLine($"# Evidence - {report.EventTitle}").AppendLine();
    foreach (string h in RunInfo.HeaderLines(desc)) s.AppendLine("    " + h);
    s.AppendLine().AppendLine($"- when: {report.WhenUtc:o}")
     .AppendLine($"- event provenance: **{report.EventProvenance}**")
     .AppendLine($"- baseline gate: **{report.BaselineVerdict}**  (counterfactual {(report.CounterfactualUnlocked ? "unlocked" : "WITHHELD")})")
     .AppendLine().AppendLine("| column | RoCoF Hz/s | nadir Hz | LFDD | device inertia GVA.s | device FFR GW | provenance |")
     .AppendLine("|---|---|---|---|---|---|---|");
    foreach (EvidenceColumn c in report.Columns)
        s.AppendLine($"| {c.Label} | {c.RocofHzPerS:F3} | {c.NadirHz:F2} | {(c.LfddAtRisk ? "YES" : "no")} | " +
                     $"{c.DeviceRotationalInertiaGvaS:F1} | {c.DeviceFfrGw:F2} | {c.Provenance} |");
    // D-DOC-135 (DOC-17): "GBP" rather than the pound sign, so the summary is plain ASCII like the console line.
    if (report.AvoidedCost is { } ac)
        s.AppendLine().AppendLine($"**Avoided cost:** {ac.LfddMwShedAvoided:F0} MW x {ac.DurationHours:F2} h x GBP {ac.VollPerMwh:N0}/MWh = " +
                                  $"**GBP {ac.AvoidedCostGbp:N0}** ({ac.Provenance} - {ac.Basis})");
    s.AppendLine().AppendLine($"> {report.Summary}");
    File.WriteAllText(CliFiles.Output(Path.Combine(outDir, "summary.md"), "summary.md"), s.ToString());
}

// gda-replay (--series <ts.json> | --synth [--start yyyy-MM-dd] [--steps N] [--step-min M])
//            [--case <name>] [--export-every N] [--out dir]
//   The historical state estimator: replay a demand time-series through the validated solver, reconstructing
//   the grid state at each PAST timestamp. Horizon-guarded - it can only ever reconstruct history.
void RunGdaReplay(List<string> a, string root)
{
    // Hypothetical storage on recorded history (--bess, repeatable): the result is COUNTERFACTUAL.
    List<string> replayBess;
    try { replayBess = GridSim.Cli.StorageCli.TakeBessSpecs(a); }
    catch (ArgumentException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 2; return; }
    // GR-695: the storage flags mean something only with at least one --bess site; refused without one, as chain refuses
    // them (D-DOC-049), instead of being ignored.
    if (replayBess.Count == 0 && new[] { "--policy", "--shave-high", "--shave-low" }.FirstOrDefault(a.Contains) is string storageOnly)
    {
        Console.Error.WriteLine($"error: gda-replay {storageOnly} is a storage flag: it needs at least one --bess site (without one, the replay runs no storage and the flag would be ignored).");
        Environment.ExitCode = 2;
        return;
    }
    bool synth = a.Contains("--synth");
    // R058: run the case's bound passive plant (delayed OLTC taps, line/transformer thermal derate). Opt-in.
    bool replayPassive = a.Contains("--passive-plant");
    string? seriesPath = FlagString(a, "--series");
    if (!synth && seriesPath is null)
    {
        Console.Error.WriteLine("usage: gridsim gda-replay (--series <ts.json> | --synth [--start yyyy-MM-dd] [--steps N] [--step-min M])");
        Console.Error.WriteLine("                          [--case <name>] [--export-every N] [--out <dir>] [--passive-plant]");
        Console.Error.WriteLine("                          [--bess chem:bus:MW:MWh[:soc] ... [--policy idle|peak-shave|hold] [--shave-high MW] [--shave-low MW]]  (COUNTERFACTUAL)");
        Console.Error.WriteLine("Reconstructs the grid state at each historical timestamp (offline state estimation).");
        Console.Error.WriteLine("Real per-timestamp GDA demand is data-gated; --synth uses a daily load shape so the estimator runs today.");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    string caseName = FlagString(a, "--case") ?? "case118";
    GridModel model;
    try
    {
        // --case takes a bundled case name / .m file, or a JSON case directory such as one written by `gda --out`
        // (a folder holding system.json). Before October 2026 only LoadNamed was tried, so a materialised GDA network
        // could not be replayed at all.
        bool isCaseDir = Directory.Exists(caseName) && File.Exists(Path.Combine(caseName, "system.json"));
        model = isCaseDir ? Gated.Dir(caseName) : LoadNamed(caseName, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{caseName}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }
    // A label safe for a folder name: a case directory path becomes its last folder name.
    string caseLabel = Directory.Exists(caseName)
        ? Path.GetFileName(Path.TrimEndingDirectorySeparator(Path.GetFullPath(caseName)))
        : caseName;

    GdaTimeSeries series;
    try
    {
        if (synth)
        {
            // ISO 8601 only, read as UTC whatever the machine's time zone. DateTime.Parse turned "...Z" or an offset into
            // LOCAL time, which SpecifyKind then relabelled UTC, so the synthetic load shape (a function of the time of
            // day) and every solved state moved with the host's UTC offset; it also took culture shapes like 01/02/2024.
            string startStr = FlagString(a, "--start") ?? "2024-01-01";
            DateTime start = GridSim.Core.Diagnostics.UtcTime.TryParseIso8601(startStr, out DateTime parsedStart)
                ? parsedStart
                : FailFlag<DateTime>("--start", startStr, "an ISO 8601 UTC instant (for example 2024-01-01 or 2024-01-01T00:00:00Z)");
            int steps = FlagInt(a, "--steps", 48);
            double stepMin = FlagDouble(a, "--step-min", 30.0);
            series = GdaTimeSeries.Synthetic($"synthetic-{caseLabel}", start, steps, stepMin);
        }
        else series = GdaTimeSeries.Load(seriesPath!);
    }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) { Console.Error.WriteLine($"error loading series: {ex.Message}"); Environment.ExitCode = 1; return; }

    // Default output: results/gda-replay-<case> under the CURRENT directory, as ch. 19 documents. It used to be under
    // the executable's folder (root = AppContext.BaseDirectory), so a run from the repository wrote into bin/.
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"gda-replay-{caseLabel}");
    CliFiles.OutputFolder(Path.Combine(outDir, "exports"), "exports folder");   // D-DOC-072
    int exportEvery = FlagCount(a, "--export-every", 0, 0);
    string desc = $"gda-replay  case={caseName}  series={series.Name}  steps={series.Steps.Count}";
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    using var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "state-estimate.csv"), "state-estimate.csv")) { AutoFlush = true };
    foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
    csv.WriteLine("index,time_utc,load_factor,converged,iterations,max_mismatch,total_loss_mw,vmin_pu,vmax_pu");

    string host = $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}";
    GridSim.Core.Storage.StorageFleet? replayFleet = null;
    if (replayBess.Count > 0)
    {
        try
        {
            double peak = model.Buses.Sum(b => b.Pd) * (series.Steps.Count > 0 ? series.Steps.Max(s => s.SystemLoadFactor) : 1.0);
            string pol = (FlagString(a, "--policy") ?? "peak-shave").ToLowerInvariant();
            // D-DOC-050 (October 2026): gda-replay takes no price series, so the two price-driven policies cannot act:
            // refused by name here (they used to reach "--policy lp needs --prices", a flag this verb does not have, or,
            // for price, idle the batteries all run). The peak-shave thresholds --shave-high / --shave-low ARE read
            // (BuildSites) and are now documented for this verb, so the per-verb flag check accepts them.
            if (pol is "price" or "lp")
                throw new ArgumentException($"--policy {pol} needs a price series, and gda-replay takes none; use idle, peak-shave or hold.");
            replayFleet = new GridSim.Core.Storage.StorageFleet(
                GridSim.Cli.StorageCli.BuildSites(a, replayBess, pol, peak, null, GridSim.Cli.StorageCli.DefaultStepHours));
            // D-DOC-005: check every site's bus here, inside this handler. The fleet used to be checked only when the
            // replay loop bound it to the model, outside any handler, so a --bess site on a bus the case does not have
            // crashed with an unhandled ArgumentException. A site on an unknown bus is a bad flag value: exit 2, with
            // the message chain gives for the same site ("storage site '...' is at unknown bus N.").
            replayFleet.Validate(model);
        }
        catch (Exception ex) when (ex is ArgumentException or FormatException)
        { Console.Error.WriteLine($"error: gda-replay storage: {CliExit.UserMessage(ex)}"); Environment.ExitCode = CliExit.Usage; return; }
        csv.WriteLine("# COUNTERFACTUAL: hypothetical storage added to recorded history (ProvenanceTag.Counterfactual) - never an input to another replay");
    }
    GdaReplayResult result;
    // D-DOC-140: a step export's meta.elapsedMs is the wall time GridSim spent producing that step's state: from the end
    // of the previous step's callback (or the start of the replay, for step 0, which so includes setting up the solver)
    // to this step's callback, which covers deriving the step's case, storage / passive plant, the warm-started solve
    // and its OLTC passes. It used to be a hard-coded 0. The replay loop reports no per-solve time of its own, so it is
    // measured here, between the loop's callbacks, and this callback's own writing is left out.
    var stepClock = System.Diagnostics.Stopwatch.StartNew();
    try
    {
        result = GdaReplayLoop.Replay(model, series, warmStart: true,
            onSolved: (i, step, solved, r, trace) =>
            {
                double stepMs = stepClock.Elapsed.TotalMilliseconds;
                csv.WriteLine($"{i},{step.TimeUtc:o},{step.SystemLoadFactor:F4},{r.Converged},{r.Iterations},{r.MaxMismatch:E3}," +
                              $"{r.TotalLossMw:F3},{(r.Vm.Length > 0 ? r.Vm.Min() : double.NaN):F5},{(r.Vm.Length > 0 ? r.Vm.Max() : double.NaN):F5}");
                if (trace is not null && (i == 0 || (exportEvery > 0 && i % exportEvery == 0)))
                {
                    var meta = new SolveExportMeta(caseName, RunInfo.Backend, RunInfo.GitCommit, step.TimeUtc.ToString("o"), stepMs, host);
                    SolveExport.WriteJson(CliFiles.Output(Path.Combine(outDir, "exports", $"state-{i:D6}.json"), "state-N.json"), solved, r, trace, meta);
                }
                stepClock.Restart();   // the next step's time starts after this callback's writing
            }, storage: replayFleet, passivePlant: replayPassive);
    }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }

    Console.WriteLine();
    Console.WriteLine($"=== Historical state estimate: {caseName} over {series.Name} ===");
    Console.WriteLine($"  reconstructed {result.Steps} timestamps  ({result.StepResults.FirstOrDefault()?.TimeUtc:o} .. {result.StepResults.LastOrDefault()?.TimeUtc:o})");
    Console.WriteLine($"  non-converged: {result.NonConverged}");
    double peakLoss = result.StepResults.Count > 0 ? result.StepResults.Max(s => s.TotalLossMw) : 0;
    double minLoss = result.StepResults.Count > 0 ? result.StepResults.Min(s => s.TotalLossMw) : 0;
    Console.WriteLine($"  system loss over the series: {minLoss:F1} .. {peakLoss:F1} MW");
    if (result.StorageSummaries is { } storSum)
    {
        Console.WriteLine($"  COUNTERFACTUAL ({result.Provenance}): hypothetical storage on recorded history - not a reconstruction.");
        foreach (string line in GridSim.Cli.StorageCli.SummaryLines(storSum, withRevenue: false)) Console.WriteLine("  " + line);
        using var scsv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "storage-counterfactual.csv"), "storage-counterfactual.csv"));
        scsv.WriteLine("# COUNTERFACTUAL: hypothetical storage on recorded history (ProvenanceTag.Counterfactual)");
        scsv.WriteLine("index,site,request_mw,delivered_mw,aux_mw,soc,temp_c,limited");
        for (int i = 0; i < result.StorageSteps!.Count; i++)
            foreach (GridSim.Core.Storage.SiteStepRecord sr in result.StorageSteps[i])
                scsv.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                    $"{i},{sr.Name},{sr.RequestedMw:F3},{sr.DeliveredMw:F3},{sr.AuxiliaryMw:F4},{sr.Soc:F5},{sr.TemperatureC:F2},{(sr.Limited ? 1 : 0)}"));
    }
    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
    if (result.NonConverged > 0) Environment.ExitCode = 3;
}

// estimate <case> (--measurements <m.json> | --synth [--seed N] [--noise S] [--coverage-* F]) [--out dir]
//   The measurement-based WLS state estimator: fit the network state to redundant telemetry, test the fit
//   (chi-square), identify and remove gross errors, and report observability. --synth solves the case as
//   ground truth, samples a deterministic noisy measurement set from it, and reports estimate-vs-truth error -
//   the full estimator pipeline exercised end to end with no external data.
void RunServe(List<string> a, string root)
{
    string? caseName = PositionalArg(a);
    string? measDir = FlagString(a, "--measurements-dir");
    if (caseName is null || measDir is null)
    {
        Console.Error.WriteLine("usage: gridsim serve <case> --measurements-dir <dir> [--method wls|ekf|ukf|enkf]");
        Console.Error.WriteLine("                  [--utc-now <iso8601>] [--max-windows N]");
        Console.Error.WriteLine("Runs the real-time estimator as a resident stream over a directory of gridsim-measurements/1");
        Console.Error.WriteLine("files (sorted by name). Real-time ENGINEERING on permitted-age/replay data: every window's");
        Console.Error.WriteLine($"timestamp passes the horizon guard - a window newer than now-{GridSim.Core.Diagnostics.ForwardInferenceGuard.HorizonHours}h is skipped, never estimated.");
        Console.Error.WriteLine("--utc-now (ISO 8601) may only be earlier than the real clock (a stricter, reproducible run); a later one is refused.");
        Environment.ExitCode = 2;
        return;
    }

    GridModel model;
    try
    {
        bool isCaseDir = Directory.Exists(caseName) && File.Exists(Path.Combine(caseName, "system.json"));
        model = isCaseDir ? Gated.Dir(caseName) : LoadNamed(caseName, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{caseName}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    // D-DOC-060: an audited serve run records the case and the window directory (hashed: every file's name and bytes)
    // as `estimate` records its case and measurement set, before any refusal below, so a refused run names its inputs
    // too. The outcome line is set after the summary.
    auditRun?.AddInput(GridSim.Core.Diagnostics.AuditRunRecorder.InputForArgument("case", caseName));
    if (Directory.Exists(measDir))
        auditRun?.AddInput(GridSim.Core.Diagnostics.AuditRunRecorder.InputForArgument("measurements-dir", measDir));

    string method = (FlagString(a, "--method") ?? "wls").Trim().ToLowerInvariant();
    // R062: ukf (unscented) and enkf (ensemble) are recursive trackers like ekf and run in the same DSE engine.
    if (method is not ("wls" or "ekf" or "ukf" or "enkf"))
    {
        Console.Error.WriteLine($"error: --method '{method}' must be 'wls' (static), or 'ekf', 'ukf' or 'enkf' (recursive tracking).");
        Environment.ExitCode = 2;
        return;
    }

    // D-DOC-063: --utc-now parses strictly (ISO 8601 / round-trip shapes only, invariant culture), so an ambiguous
    // date such as 01/02/2100 is refused instead of being read as 2 January. A stamp with no zone is UTC.
    DateTime? requestedNow = FlagString(a, "--utc-now") is string isoNow
        ? (GridSim.Core.Diagnostics.UtcTime.TryParseIso8601(isoNow, out DateTime parsedNow)
             ? parsedNow
             : FailFlag<DateTime>("--utc-now", isoNow, "an ISO 8601 UTC instant (for example 2024-03-01T12:00:00Z)"))
        : null;
    // D-DOC-018 (HORIZON): --utc-now may only move the horizon BACK (a stricter, reproducible run), never forward past
    // the real clock. Before, `serve --utc-now 2100-01-01T00:00:00Z` estimated a window stamped 2099 and exited 0: the
    // command line could switch the guard off. A later 'now' is a refusal of the horizon rule: REJECTED, exit 2, before
    // any window is read.
    DateTime now;
    try { now = ForwardInferenceGuard.RequireNotAfterRealClock(requestedNow, "--utc-now"); }
    catch (ForwardInferenceException ex)
    {
        Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}");
        AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.HorizonViolation, $"serve --utc-now refused: {ex.Message}");
        auditRun?.SetOutcome($"rejected=ForwardInferenceException reason={ex.Reason}");   // D-DOC-060
        Environment.ExitCode = CliExit.Usage;
        return;
    }
    int maxWindows = FlagInt(a, "--max-windows", int.MaxValue);
    // D-DOC-181 (October 2026): --max-windows 0 (or a negative count) took no files and then reported "no *.json
    // measurement windows in '<dir>'", exit 1, blaming a folder that may be full of windows. A count below 1 asks for
    // nothing to be served, so it is a usage error naming the flag (exit 2), before the folder is read.
    if (maxWindows < 1) FailFlag<int>("--max-windows", maxWindows.ToString(System.Globalization.CultureInfo.InvariantCulture), "a window count of at least 1");

    List<string> files;
    try
    {
        files = Directory.EnumerateFiles(measDir, "*.json")
            .OrderBy(f => f, StringComparer.Ordinal).Take(maxWindows).ToList();
    }
    catch (Exception ex) { Console.Error.WriteLine($"error reading '{measDir}': {ex.Message}"); Environment.ExitCode = 1; return; }
    if (files.Count == 0) { Console.Error.WriteLine($"error: no *.json measurement windows in '{measDir}'."); Environment.ExitCode = 1; return; }

    // D-DOC-018 (HORIZON): each window is loaded with the REAL horizon (the effective 'now' above, which is never later
    // than the real clock), so MeasurementSet.Load's own guard seam is on. Before, serve loaded every window with
    // DateTime.MaxValue, switching that seam off and leaving only the engine's check. A window newer than the horizon is
    // still skipped, never estimated, exactly as the engine skips one (a resident loop must not crash on a briefly-fresh
    // window): it is counted here and added to the engine's rejected-fresh figure, so the summary line reads as before.
    // An UNDATED window (D-DOC-061) is not skipped: Load refuses it and serve stops with REJECTED, exit 2, as the engine
    // did when it met one.
    //
    // D-DOC-009: a window file that cannot be loaded (not JSON, not a measurement set, unreadable) used to throw out of
    // this lazy iterator, through the engine, and crash serve with an unhandled exception (a JsonReaderException), while
    // the web feed skips and records the same file. Now serve does what the web feed does: it names the file on stderr,
    // skips it, and carries on with the other windows. Because a file the user supplied could not be read, the run is an
    // input error: exit 1 at the end (the batch verbs' rule: exit 1 after a partial load failure), which takes precedence
    // over a verdict code (3) the windows that did load may give. The count is reported after the summary line.
    int unloadableWindows = 0;
    int freshWindowsAtLoad = 0;
    IEnumerable<MeasurementSet> Windows()
    {
        foreach (string f in files)
        {
            MeasurementSet? window = null;
            try { window = MeasurementSet.Load(f, now); }
            catch (ForwardInferenceException fresh) when (fresh.Reason == ForwardInferenceReason.NewerThanHorizon)
            {
                freshWindowsAtLoad++;   // skipped, never estimated (the engine's rule for a fresh window)
                // One security entry per refused window (CAF C1): the monitor escalates a burst of them.
                AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.HorizonViolation,
                    $"serve window '{Path.GetFileName(f)}' refused: {fresh.Message}");
            }
            catch (Exception ex) when (ex is System.Text.Json.JsonException or InvalidDataException or IOException or UnauthorizedAccessException)
            {
                unloadableWindows++;
                Console.Error.WriteLine($"error: serve: window '{Path.GetFileName(f)}' cannot be loaded and is skipped: {ex.Message}");
            }
            if (window is not null) yield return window;
        }
    }

    Console.WriteLine($"serving {method} estimator over {files.Count} window(s) from {measDir}");
    Console.WriteLine($"horizon guard: now={now:o}, newest processable={ForwardInferenceGuard.Horizon(now):o}");
    var opt = new GridSim.Core.Simulation.RealtimeEstimatorOptions
    {
        UtcNow = now,
        Estimation = new EstimationOptions { ComputeStateCovariance = true },
    };

    // D-DOC-163 (October 2026): serve printed only a status per window (OK / J / chi2, or OK / non-finite), never the
    // state it had estimated nor how sure it was. Now each window line ends with the largest 1-sigma bound of the window
    // (|V| in pu, angle in degrees: the filter covariance for ekf / ukf / enkf, the WLS state covariance for wls when it
    // was computed), and after the summary the last usable window's state is printed bus by bus with its sigmas: the
    // filtered present state a resident estimator exists to report. Lines and exit codes that were there are unchanged.
    var invServe = System.Globalization.CultureInfo.InvariantCulture;
    string SigmaText(double[]? vmSigma, double[]? vaSigmaDeg) => vmSigma is null || vaSigmaDeg is null || vmSigma.Length == 0
        ? " sigma=n/a"
        : $" max-sigma |V|={vmSigma.Max().ToString("E3", invServe)} pu angle={vaSigmaDeg.Max().ToString("E3", invServe)} deg";
    // The last estimate worth showing: converged (wls) or finite (a recursive filter). Kept as plain arrays so both
    // engines share the printer below.
    (int Seq, DateTime Time, IReadOnlyList<int> Bus, double[] Vm, double[] VaDeg, double[]? VmSigma, double[]? VaSigmaDeg)? lastState = null;

    GridSim.Core.Simulation.RealtimeRunSummary summary;
    try
    {
        if (method == "wls")
        {
            var engine = new GridSim.Core.Simulation.RealtimeEstimatorEngine(model);
            summary = engine.Run(Windows(), opt, f =>
            {
                Console.WriteLine(
                    $"  #{f.Sequence} {f.StateTimeUtc:o} {(f.Result.Converged ? "OK" : f.Result.Status.ToString())} " +
                    $"J={f.Result.ObjectiveJ:F2} chi2={ChiText(f.Result.ChiSquareTest)}" +
                    (f.Result.Converged ? SigmaText(f.Result.StateVmSigma, f.Result.StateVaSigmaDeg) : ""));
                if (f.Result.Converged)
                    lastState = (f.Sequence, f.StateTimeUtc, f.Result.BusIds, f.Result.Vm, f.Result.VaDeg, f.Result.StateVmSigma, f.Result.StateVaSigmaDeg);
                if (f.Result.Status == EstimationStatus.Infeasible)
                    AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.InfeasibleState,
                        $"serve window #{f.Sequence} converged to a physically infeasible state and was rejected");
            });
        }
        else
        {
            // The three recursive filters share one streaming engine (horizon guard, time order, frame stamping);
            // ukf and enkf are bound through factories that also enforce their dense size limits (R062).
            GridSim.Core.Simulation.RealtimeDseEngine engine = method switch
            {
                "ukf" => GridSim.Core.Simulation.RealtimeDseEngine.Unscented(model),
                "enkf" => GridSim.Core.Simulation.RealtimeDseEngine.Ensemble(model),
                _ => new GridSim.Core.Simulation.RealtimeDseEngine(model),
            };
            summary = engine.Run(Windows(), opt, f =>
            {
                Console.WriteLine($"  #{f.Sequence} {f.StateTimeUtc:o} {(f.Estimate.Converged ? "OK" : "non-finite")}" +
                    (f.Estimate.Converged ? SigmaText(f.Estimate.StateVmSigma, f.Estimate.StateVaSigmaDeg) : ""));
                if (f.Estimate.Converged)
                    lastState = (f.Sequence, f.StateTimeUtc, f.Estimate.BusIds, f.Estimate.Vm, f.Estimate.VaDeg, f.Estimate.StateVmSigma, f.Estimate.StateVaSigmaDeg);
            });
        }
    }
    catch (ForwardInferenceException ex)
    {
        Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}");
        AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.HorizonViolation, $"serve stopped: {ex.Message}");
        auditRun?.SetOutcome($"rejected=ForwardInferenceException reason={ex.Reason}");   // D-DOC-060
        Environment.ExitCode = 2;
        return;
    }
    catch (NotSupportedException ex)
    {
        // The dense EKF fails loud above its state-size cap (1.95.050, R107), and the UKF/EnKF above their state and
        // per-window measurement caps (R062); report it as a clean usage error instead of an unhandled exception.
        Console.Error.WriteLine($"error: serve --method {method}: {ex.Message}");
        Environment.ExitCode = 2;
        return;
    }
    catch (RestrictionViolationException ex)
    {
        // D-DOC-009: the engines' mechanical output guard (RestrictionReview.AssertOutputHistorical) refuses an estimate
        // stamped newer than the horizon. It was not caught here, so it would have crashed serve. It is the horizon rule
        // refusing an output, the same family as a forward-inference rejection: REJECTED and exit 2.
        Console.Error.WriteLine($"REJECTED (output guard): {ex.Message}");
        AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.RestrictionRefused, $"serve output refused by the output guard: {ex.Message}");
        Environment.ExitCode = CliExit.Usage;
        return;
    }

    // A window the ENGINE refused as too fresh (it cannot happen today, both use the same 'now') is still one entry.
    if (summary.WindowsRejectedFresh > 0)
        AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.HorizonViolation,
            $"{summary.WindowsRejectedFresh} serve window(s) refused by the engine as newer than the horizon");
    // CAF B5: a breached service-level objective is a security event (the incident wiring raises it), as on the web host.
    if (auditRun is not null)
    {
        GridSim.Core.Simulation.Health.HealthReport health = new GridSim.Core.Simulation.Health.HealthProbe().Check(summary);
        if (!health.Healthy)
            AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.AvailabilityDegraded,
                "serve breached its service-level objective: " + string.Join("; ", health.BreachedObjectives));
    }

    // D-DOC-018: a fresh window is now refused at load (counted in freshWindowsAtLoad) instead of inside the engine, so
    // the rejected-fresh figure is the sum of both; the engine's count stays for a window that ages into the horizon
    // between load and estimate (it cannot today: both use the same 'now').
    int rejectedFresh = summary.WindowsRejectedFresh + freshWindowsAtLoad;
    Console.WriteLine($"done: processed {summary.WindowsProcessed}, converged {summary.WindowsConverged}, " +
        $"rejected-fresh {rejectedFresh}, failed {summary.WindowsFailed}");
    // D-DOC-163: the last usable window's state, one row per bus (sigma columns "n/a" when the WLS covariance was not
    // computed, which happens above the dense covariance limit).
    if (lastState is { } shown)
    {
        Console.WriteLine($"{(method == "wls" ? "estimated" : "filtered")} state at window #{shown.Seq} ({shown.Time:o}), {method}:");
        Console.WriteLine("  | bus | |V| pu | sigma |V| pu | angle deg | sigma angle deg |");
        Console.WriteLine("  |-----|--------|--------------|-----------|-----------------|");
        for (int i = 0; i < shown.Bus.Count; i++)
            Console.WriteLine($"  | {shown.Bus[i]} | {shown.Vm[i].ToString("F6", invServe)} | " +
                $"{(shown.VmSigma is null ? "n/a" : shown.VmSigma[i].ToString("E3", invServe))} | {shown.VaDeg[i].ToString("F4", invServe)} | " +
                $"{(shown.VaSigmaDeg is null ? "n/a" : shown.VaSigmaDeg[i].ToString("E3", invServe))} |");
    }
    // D-DOC-060: the audited outcome is the same summary, plus the unloadable count and the effective 'now'; the state
    // time is the newest window estimated. (The exit code is added by the recorder.)
    if (auditRun is not null)
    {
        auditRun.SetOutcome(string.Create(System.Globalization.CultureInfo.InvariantCulture,
            $"method={method} processed={summary.WindowsProcessed} converged={summary.WindowsConverged} rejected-fresh={rejectedFresh} failed={summary.WindowsFailed} unloadable={unloadableWindows} now={now:o}"));
        auditRun.StateTimeUtc = summary.LastStateTimeUtc;
    }
    if (summary.WindowsFailed > 0) Environment.ExitCode = 3;   // R022: failed windows are a failure, not exit 0

    // Fail loud when the whole run produced nothing usable. Before October 2026 a directory whose every window was
    // Unobservable (too few measurements to determine the state) printed "converged 0" and exited 0, so a script
    // took it as success. A run with at least one converged window is a success for the windows it estimated (the
    // per-window lines show the rest); a run with none is a validation failure, exit 3, whatever the reason: every
    // window unobservable / not converged, every window still inside the horizon, or every window failed.
    if (summary.WindowsConverged == 0)
    {
        string why = summary.WindowsProcessed > 0 ? $"none of the {summary.WindowsProcessed} estimated window(s) converged (see the status on each line)"
            : rejectedFresh > 0 ? $"all {rejectedFresh} window(s) are newer than the {ForwardInferenceGuard.HorizonHours} h horizon"
            : "every window failed to load or estimate";
        Console.Error.WriteLine($"error: no window produced a usable estimate: {why}.");
        Environment.ExitCode = 3;
    }
    // D-DOC-009: windows that could not be loaded (named above as they were skipped) make the run an input error, exit 1,
    // ahead of any verdict code, so a script never reads a partly unreadable directory as a clean or merely failed run.
    if (unloadableWindows > 0)
    {
        Console.Error.WriteLine($"error: serve: {unloadableWindows} of {files.Count} window file(s) could not be loaded (skipped; named above). Exit 1.");
        Environment.ExitCode = CliExit.InputError;
    }
}

// interpose [case] --protocol <name> (--listen host:port | --port N) --crosswalk <map.json>
//           [--measurements-dir <dir>] [--out-store <dir>] [--source-id <id>] [--window-ms N] [--monitor] [--ticks N]
//           [--live-seconds S] [--tolerate-malformed]
//   (There is no --utc-now here: every window is judged against the real clock. serve reads --utc-now; interpose
//   does not.)
//   The RTU/SCADA interposer: receives live protocol frames (--protocol selects the stack), validates and
//   corrects each frame, decodes its object model to typed points, maps them through the crosswalk, and emits
//   gridsim-measurements/1 windows.
//   D-DOC-018 (HORIZON): each window is judged against the REAL horizon when it is flushed (the RTU guard seam is on;
//   it used to be switched off with DateTime.MaxValue). Only a window older than the horizon (a replayed, recorded
//   capture) becomes a gridsim-measurements/1 window in --measurements-dir. A window newer than the horizon (live
//   telemetry) is never written there: it is held, counted (held-fresh), and kept only as a quarantine capture in the
//   firewalled --out-store when one is given. A run with --measurements-dir that held any window ends REJECTED, exit 2.
void RunInterpose(List<string> a, string root)
{
    if (a.Remove("--list-protocols")) { Console.Write(RtuProtocolRegistry.Describe()); return; }
    bool monitor = a.Remove("--monitor");
    // N230 (main's ruling on question 1): a malformed frame (rejected by frame correction, or framed but undecodable)
    // makes the run exit 1 at its end unless the operator opts in to line noise with --tolerate-malformed (then the
    // warning and the counts still say so, and the exit stays 0).
    bool tolerateMalformed = a.Remove("--tolerate-malformed");
    _ = a.Remove("--no-parquet"); // reserved for the Phase-2 quarantine sink; consume so it isn't read as a value

    string? protoName = FlagString(a, "--protocol");
    if (protoName is null || !RtuProtocolRegistry.TryGet(protoName, out IRtuProtocol protocol))
    {
        Console.Error.WriteLine("usage: gridsim interpose [case] --protocol <name> (--listen host:port | --port N) --crosswalk <map.json>");
        Console.Error.WriteLine("                         [--measurements-dir <dir>] [--out-store <dir>] [--source-id <id>] [--window-ms N]");
        Console.Error.WriteLine("                         [--monitor] [--ticks N] [--live-seconds S] [--tolerate-malformed]");
        Console.Error.WriteLine("       gridsim interpose --list-protocols");
        Console.Error.WriteLine("Receives live RTU/SCADA frames, corrects & decodes them, and writes gridsim-measurements/1 windows.");
        Console.Error.WriteLine($"Live frames feed the estimator only after ageing past the {GridSim.Core.Diagnostics.ForwardInferenceGuard.HorizonHours} h horizon (monitor-only until then).");
        if (protoName is not null) Console.Error.WriteLine($"error: unknown protocol '{protoName}'. Try --list-protocols.");
        Environment.ExitCode = 2;
        return;
    }

    string? crosswalkPath = FlagString(a, "--crosswalk");
    if (crosswalkPath is null) { Console.Error.WriteLine("error: --crosswalk <map.json> is required."); Environment.ExitCode = 2; return; }
    RtuPointMap crosswalk;
    auditRun?.AddInput(GridSim.Core.Diagnostics.AuditInput.OfFile("crosswalk", crosswalkPath));   // R075
    try { crosswalk = RtuPointMap.Load(crosswalkPath); }
    catch (Exception ex) { Console.Error.WriteLine($"error loading crosswalk '{crosswalkPath}': {ex.Message}"); Environment.ExitCode = 1; return; }

    // Endpoint: --listen host:port wins; else --port (default per protocol) on all interfaces.
    string host = "0.0.0.0";
    int port = protocol.DefaultPort;
    // GR-706: the port is checked against 0..65535 here (a usage error, exit 2; it used to reach TcpListener and exit 1
    // as a transport failure), and an IPv6 address is given in brackets, [::1]:2404 (the value used to be split on
    // every ':', so no IPv6 address could be given). An unbracketed value with several ':' is refused as ambiguous.
    if (FlagString(a, "--listen") is string listen)
    {
        if (TryParseListen(listen, protocol.DefaultPort, out string lh, out int lport)) { host = lh; port = lport; }
        else { _ = FailFlag<int>("--listen", listen, "host:port, [IPv6]:port or a bare port, with the port 0 to 65535"); }
    }
    else
    {
        port = FlagInt(a, "--port", protocol.DefaultPort);
        if (port is < 0 or > 65535)
            FailFlag<int>("--port", port.ToString(System.Globalization.CultureInfo.InvariantCulture), "a TCP port, 0 to 65535");
    }

    string caseName = PositionalArg(a) ?? (crosswalk.Case.Length > 0 ? crosswalk.Case : "rtu");
    int windowMs = FlagCount(a, "--window-ms", 1000, 1);   // GR-682: refused below 1, not raised to 1
    int maxTicks = ticks; // --ticks is parsed and removed up front (shared with the live loop); 0 = interactive
    string? measDir = FlagString(a, "--measurements-dir");
    string? outStoreFlag = FlagString(a, "--out-store");
    string sourceId = FlagString(a, "--source-id") ?? "rtu_live";

    // N230 (October 2026): --live-seconds S, the longest the listener runs (wall clock), the same flag and the same
    // bounds as pmu-ingest --live (above 0, at most 86400). Before it, the only ways to stop were a key press or
    // --ticks N frames, so a listener that received fewer than N frames (or none: no client ever connected) waited for
    // ever under a script or a test with no console. That made a process-level test of the stop path impossible (the
    // loopback tests in InterposeLoopbackProcessTests.cs need it). Absent means no time limit, exactly as before.
    // A malformed or out-of-range value is a usage error (exit 2) before the transport is opened.
    long? liveDeadline = null;
    double liveSeconds = 0;
    if (FlagString(a, "--live-seconds") is string liveSecondsText)
    {
        if (!double.TryParse(liveSecondsText, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out liveSeconds)
            || !double.IsFinite(liveSeconds) || !(liveSeconds > 0) || liveSeconds > 86400)
        {
            Console.Error.WriteLine($"error: interpose --live-seconds must be a number above 0 and at most 86400 (got '{liveSecondsText}').");
            Environment.ExitCode = 2;
            return;
        }
    }
    // GR-196: the interactive run stops only on a key (or --live-seconds); with no console to read a key from it never
    // ended. Refused here, before the transport is opened.
    if (maxTicks <= 0 && liveSeconds <= 0 && InteractiveWithoutConsole("interpose", "--ticks N or --live-seconds S")) return;

    // --monitor decodes to the console and writes nothing. A sink flag alongside it used to be dropped silently, so
    // the user believed windows were being kept when none were: refuse the combination instead (usage error).
    if (monitor && (measDir is not null || outStoreFlag is not null))
    {
        Console.Error.WriteLine("error: --monitor writes no windows, so it cannot be combined with " +
            (measDir is not null ? "--measurements-dir" : "--out-store") + ". Drop --monitor to persist windows.");
        Environment.ExitCode = 2;
        return;
    }

    // The quarantine GDA-shaped Parquet sink is firewalled from the public lake (it refuses to open inside it).
    QuarantineLiveStore? store = null;
    if (outStoreFlag is string outStore)
    {
        try { store = new QuarantineLiveStore(outStore, sourceId); }
        catch (Exception ex) { Console.Error.WriteLine($"error opening quarantine store '{outStore}': {ex.Message}"); Environment.ExitCode = 1; return; }
    }

    var pipeline = new InterposePipeline(protocol, crosswalk, QualityFold.Default, caseName);

    IRtuTransport transport;
    try { transport = TransportFactory.Open(protocol, host, port); }
    catch (Exception ex) { Console.Error.WriteLine($"error opening {protocol.Name} transport on {host}:{port}: {ex.Message}"); Environment.ExitCode = 1; return; }

    Console.WriteLine($"interpose {protocol.DisplayName}: listening {host}:{port}, case '{caseName}', {crosswalk.Bindings.Count} binding(s)");
    // R075: a start entry now (a listener can run for days), the stop entry at exit. Frame contents are never logged.
    auditRun?.RecordNow(string.Create(System.Globalization.CultureInfo.InvariantCulture,
        $"started protocol={protocol.Name} listen={host}:{port} monitor={monitor}"));
    if (monitor) Console.WriteLine("monitor mode: decoding to console only, no windows written.");
    else if (measDir is not null) Console.WriteLine($"windows -> {measDir} (horizon guard on: only windows older than {GridSim.Core.Diagnostics.ForwardInferenceGuard.HorizonHours} h are written; newer ones are held)");
    else if (store is null) Console.WriteLine("no --measurements-dir/--out-store: decoding only (add a sink to persist).");
    if (store is not null) Console.WriteLine($"quarantine store -> {sourceId} (source_class=telemetry; firewalled from the GDA public lake)");
    Console.WriteLine(maxTicks > 0 ? $"headless: stops after {maxTicks} frame(s)." : "press any key to stop.");
    // N230: the time limit starts when the listener is up (after the transport opened), so a slow start-up does not
    // eat into it. The deadline is on the monotonic tick clock, as the window flush is.
    if (liveSeconds > 0)
    {
        liveDeadline = Environment.TickCount64 + (long)Math.Ceiling(liveSeconds * 1000.0);
        Console.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
            $"time limit: stops after {liveSeconds:R} s whatever has arrived (--live-seconds)."));
    }
    bool stoppedOnTime = false;   // N230: true when --live-seconds, not a key or --ticks, ended the run
    bool malformedWarned = false; // N230: the first malformed frame is named on stderr, the rest are counted

    bool interactive = maxTicks <= 0;
    long tick = 0, windowsWritten = 0, seq = 0, windowsDuplicateNamed = 0;
    // N346: every decoded point, plus the step positions and bitstrings among them (never estimator inputs), for the stop line.
    var pointTally = new GridSim.Core.Interpose.RtuPointTally();
    long windowsQuarantined = 0;   // D-DOC-018: held (fresh) windows kept as quarantine captures only
    bool heldWarned = false;       // D-DOC-018: the first held window is named on stderr, the rest are counted
    long nextFlush = Environment.TickCount64 + windowMs;

    // Persist one flushed window to whichever sink(s) are configured (estimator JSON and/or quarantine Parquet).
    void Emit(MeasurementSet set)
    {
        if (set.Measurements.Count == 0) return;
        string label = "";
        if (measDir is not null)
        {
            // Never overwrite: two windows can share an instant and sequence number (a restarted listener writing
            // into the same folder starts its sequence at 0 again; a device clock can stand still). The second is
            // kept under a "-dupN" name and the console says so; before October 2026 it replaced the first.
            string file = Path.Combine(measDir, $"{set.TakenUtc:yyyyMMddTHHmmssfffZ}-{seq:D6}.json");
            string written = set.SaveWithoutOverwrite(file);
            if (!string.Equals(Path.GetFullPath(file), written, StringComparison.Ordinal))
            {
                windowsDuplicateNamed++;
                Console.Error.WriteLine($"warning: window file '{Path.GetFileName(file)}' already exists; kept this " +
                    $"window as '{Path.GetFileName(written)}' (never overwrite).");
            }
            label = " -> " + Path.GetFileName(written);
        }
        store?.WriteWindow(set, protocol.Name, windowMs / 60000.0);
        seq++;
        windowsWritten++;
        Console.WriteLine($"  window {set.TakenUtc:o}: {set.Measurements.Count} measurement(s){label}{(store is not null ? " [+quarantine]" : "")}");
    }

    try { Console.CursorVisible = false; } catch { }
    try
    {
        long sessionResetsSeen = transport.ClientResets;   // GR-329
        using (transport)
            while (true)
            {
                if (interactive && KeyPressed()) break;
                if (!interactive && tick >= maxTicks) break;
                // N230: the wall-clock limit. Checked after the frame cap, so a run that reached its --ticks count
                // exactly as time ran out counts as complete, not as short.
                if (liveDeadline is long deadline && Environment.TickCount64 >= deadline) { stoppedOnTime = true; break; }

                bool gotFrame = transport.TryReadFrame(out byte[] frame, TimeSpan.FromMilliseconds(200));
                // GR-329: a client went away since the last pass (the transport counts it before it accepts the next one):
                // a stateful decoder forgets that connection, so the next client's frames never pair with the old ones.
                if (transport.ClientResets != sessionResetsSeen)
                {
                    sessionResetsSeen = transport.ClientResets;
                    if (protocol is GridSim.Core.Interpose.IRtuSessionState session) session.ResetSession();
                }
                if (gotFrame)
                {
                    long rejectedBefore = pipeline.Correction.Rejected;
                    long malformedBefore = rejectedBefore + pipeline.DecodeErrors;
                    IReadOnlyList<RtuPoint> pts = pipeline.Ingest(frame);
                    // N230: name the FIRST malformed frame on stderr when it happens (a noisy line would otherwise flood
                    // it); later ones are counted on the stop line (rejected, decode-errors) and in the audit outcome.
                    if (!malformedWarned && pipeline.Correction.Rejected + pipeline.DecodeErrors > malformedBefore)
                    {
                        malformedWarned = true;
                        string what = pipeline.Correction.Rejected > rejectedBefore ? "rejected by frame correction" : "framed but undecodable";
                        Console.Error.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                            $"WARNING: interpose: malformed {protocol.Name} frame ({what}, {frame.Length} octet(s)) at frame {tick + 1}; later malformed frames are counted, not named."));
                    }
                    pointTally.Add(pts);
                    if (monitor)
                        foreach (RtuPoint p in pts)
                            Console.WriteLine($"  {p.Address,-16} {p.Value,14:G6}  {p.Quality,-12} {(p.StampUtc?.ToString("o") ?? "-")}");
                    tick++;
                }

                if (Environment.TickCount64 >= nextFlush)
                {
                    nextFlush += windowMs;
                    FlushAndEmit();
                }
            }
    }
    finally { try { Console.CursorVisible = true; } catch { } }

    // Flush any points still buffered when the stream stops, so a short run doesn't silently drop its last window.
    FlushAndEmit();

    // Flush the pipeline's current window and persist it. A window whose points do not fit their crosswalk bindings
    // (InvalidDataException from the mapper, e.g. a 32-bit Modbus binding whose second register was not polled in
    // the same response) used to escape as an unhandled exception: the verb died (exit -532462766) and the window
    // was lost. Now that window alone is discarded, the reason is printed, the pipeline counts it (map-errors in the
    // stop summary, which also sets exit code 3) and the listener keeps running.
    //
    // D-DOC-018 (HORIZON): the flush judges each window against the REAL horizon (it used to pass DateTime.MaxValue, so
    // the RTU guard seam was off). A window older than the horizon is an estimator input and goes to every sink as
    // before. A window newer than the horizon (live telemetry) is held: never written to --measurements-dir; kept only as
    // a quarantine capture when --out-store is given (the firewalled, non-evidential store); counted as held-fresh.
    void FlushAndEmit()
    {
        GridSim.Core.Interpose.InterposeFlush? flush;
        GridSim.Core.Interpose.InterposeFreshPolicy freshPolicy = store is not null && !monitor
            ? GridSim.Core.Interpose.InterposeFreshPolicy.QuarantineCapture
            : GridSim.Core.Interpose.InterposeFreshPolicy.Refuse;
        try { flush = pipeline.FlushWindow(DateTime.UtcNow, freshPolicy); }
        catch (InvalidDataException ex)
        {
            Console.Error.WriteLine($"  window discarded (crosswalk mismatch): {ex.Message}");
            return;
        }
        if (monitor || flush is null) return;
        if (flush.Estimable is MeasurementSet set) { Emit(set); return; }
        // Held: newer than the horizon. Say so once on stderr (a 1 s window would otherwise flood it); the stop line
        // carries the count.
        if (measDir is not null && !heldWarned)
        {
            heldWarned = true;
            Console.Error.WriteLine($"warning: window {flush.WindowUtc:o} is newer than the {ForwardInferenceGuard.HorizonHours} h horizon; " +
                "it is not written to --measurements-dir (live telemetry is never an estimator input). Later held windows are counted, not named.");
        }
        if (flush.QuarantineCapture is MeasurementSet capture && capture.Measurements.Count > 0)
        {
            store!.WriteWindow(capture, protocol.Name, windowMs / 60000.0);
            windowsQuarantined++;
            // CAF C1: each quarantined window is one security entry (routine on its own; the stamp is in the reason,
            // never as the entry's grid instant).
            AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.LiveDataQuarantined,
                $"interpose window held newer than the horizon and kept as a quarantine capture only ({capture.Measurements.Count} measurement(s))");
            Console.WriteLine($"  window {capture.TakenUtc:o}: {capture.Measurements.Count} measurement(s) held (newer than the horizon) [quarantine capture only]");
        }
    }

    // IEC-104 counts I-format ASDUs of a type it does not decode (R089); print them so they are not lost unseen.
    string unsupported = protocol is GridSim.Core.Interpose.Protocols.Iec104Protocol iec && iec.UnsupportedTypeIds.Count > 0
        ? string.Join(",", iec.UnsupportedTypeIds.OrderBy(kv => kv.Key).Select(kv =>
            string.Create(System.Globalization.CultureInfo.InvariantCulture, $"{kv.Key}x{kv.Value}")))
        : "none";
    Console.WriteLine($"stopped: accepted {pipeline.Correction.Accepted}, rejected {pipeline.Correction.Rejected}, " +
        $"decode-errors {pipeline.DecodeErrors}, map-errors {pipeline.MapErrors}, {pointTally.ConsoleFields()}, " +
        $"windows-written {windowsWritten}, duplicate-names {windowsDuplicateNamed}, client-resets {transport.ClientResets}, " +
        $"unsupported-type-ids {unsupported}, held-fresh {pipeline.HeldFresh}, quarantined {windowsQuarantined}, " +
        $"discarded-bytes {transport.DiscardedBytes}");
    auditRun?.SetOutcome(string.Create(System.Globalization.CultureInfo.InvariantCulture,
        $"stopped accepted={pipeline.Correction.Accepted} rejected={pipeline.Correction.Rejected} decode-errors={pipeline.DecodeErrors} map-errors={pipeline.MapErrors} {pointTally.AuditFields()} windows-written={windowsWritten} duplicate-names={windowsDuplicateNamed} client-resets={transport.ClientResets} unsupported-type-ids={unsupported} held-fresh={pipeline.HeldFresh} quarantined={windowsQuarantined} discarded-bytes={transport.DiscardedBytes}"));
    // A discarded window is lost evidence caused by a configuration fault: the run did not do everything it was
    // asked to, so it must not exit 0 (validation failure, exit 3).
    if (pipeline.MapErrors > 0) Environment.ExitCode = 3;
    // D-DOC-018: --measurements-dir asked for estimator windows, and a held window is one the horizon refused to write
    // there. That is the forward-inference refusal (REJECTED, exit 2, the convention of every guarded verb), reported
    // after the summary so the counts are still printed. A map error (exit 3) keeps precedence: it is the configuration
    // fault the operator must fix first. Monitor mode and a store-only run hold windows by design, so they do not set it.
    else if (measDir is not null && pipeline.HeldFresh > 0)
    {
        Console.Error.WriteLine($"REJECTED (forward inference): {pipeline.HeldFresh} window(s) newer than the {ForwardInferenceGuard.HorizonHours} h " +
            $"horizon were not written to --measurements-dir{(store is not null ? $" ({windowsQuarantined} kept as quarantine captures in --out-store)" : "")}.");
        Environment.ExitCode = CliExit.Usage;
    }

    // N230 (main's ruling on question 1): any malformed frame fails the run, exit 1, unless --tolerate-malformed. Map
    // errors (3) and the forward-inference refusal (2) above keep precedence.
    long malformed = pipeline.Correction.Rejected + pipeline.DecodeErrors;
    if (malformed > 0)
    {
        if (tolerateMalformed)
            Console.Error.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"WARNING: interpose: {malformed} malformed frame(s) ({pipeline.Correction.Rejected} rejected, {pipeline.DecodeErrors} undecodable) tolerated (--tolerate-malformed)."));
        else
        {
            Console.Error.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"error: interpose: {malformed} malformed frame(s) ({pipeline.Correction.Rejected} rejected, {pipeline.DecodeErrors} undecodable); pass --tolerate-malformed to accept a noisy line."));
            if (Environment.ExitCode == 0) Environment.ExitCode = CliExit.InputError;
        }
    }

    // N230: a run ended by --live-seconds says so, loudly, when it fell short. With --ticks N it was asked for N frames
    // and received fewer: that is missing input, exit 1 (after the summary, so the counts are still printed). The
    // configuration fault (map errors, exit 3) and the forward-inference refusal (exit 2) above keep precedence: they
    // are what the operator must fix first. Without --ticks the time limit IS the requested end, so exit 0 stands, but
    // a listener that received nothing at all is named on stderr (a wrong port or a dead device looks exactly like that).
    if (stoppedOnTime)
    {
        string limit = liveSeconds.ToString("R", System.Globalization.CultureInfo.InvariantCulture);
        if (maxTicks > 0 && tick < maxTicks)
        {
            Console.Error.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"error: interpose: --live-seconds {limit} elapsed after {tick} of the {maxTicks} frame(s) asked for by --ticks."));
            if (Environment.ExitCode == 0) Environment.ExitCode = CliExit.InputError;
        }
        else if (tick == 0)
        {
            Console.Error.WriteLine($"warning: interpose: no frames received in {limit} s (--live-seconds); check the device and the port.");
        }
    }
}

// emt [case] [--dir <dir>] [--dt-us N] [--duration S] [--source <bus>] [--amp pu] [--freq Hz] [--probe v:<bus>,i:<f>-><t>]
//     [--event <spec> ...] [--rule trap|be] [--no-cda] [--lines] [--no-loads] [--allow-non-passive] [--out <dir>]
//   Electromagnetic-transient (EMT) time-domain solve: a Dommel nodal companion-model engine steps the
//   instantaneous network (L di/dt, C dv/dt) at a fixed microsecond timestep. FORWARD SIMULATION about the
//   MODEL (not forward inference about the grid); output is a model trajectory. Passives are grounded from the
//   per-unit R/X/B; DC source (--freq 0) settles to the resistive DC solution, AC drives a steady sinusoid.
//   DOC-6 (stream 6 of the docs-session findings): every part of the command line that names nothing, or a time,
//   resistance or duration the run cannot honour, is refused with exit 2 and a message naming it, before any step.
void RunEmt(List<string> a, string root)
{
    bool noCda = a.Remove("--no-cda");
    bool useLines = a.Remove("--lines");
    bool noLoads = a.Remove("--no-loads");
    bool allowNonPassive = a.Remove("--allow-non-passive");   // D-DOC-024: run a network-reduction equivalent anyway

    string? caseName = SingleCasePositional("emt", a);   // a second positional case is refused (exit 2), as for every verb of the group
    GridModel model;
    // Positional case and/or --dir through the shared SelectCase: the positional used to win silently over --dir.
    // A disagreeing pair exits 2 and a missing --dir folder exits 1, both before any work.
    var emtSel = SelectCase("emt", caseName, a, root, "data/uk", () => LoadUkDefault(root));
    try
    {
        model = emtSel.Load();
    }
    catch (Exception ex) { Console.Error.WriteLine($"emt: error loading case '{caseName}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string Num(double x) => x.ToString("R", inv);
    // One way to refuse a command-line value: the reason on stderr, exit 2 (usage error), nothing written.
    void Refuse(string message) { Console.Error.WriteLine($"error: emt: {message}"); Environment.ExitCode = CliExit.Usage; }

    double dtUs = FlagDouble(a, "--dt-us", 20.0);
    if (dtUs <= 0) { _ = FailFlag<double>("--dt-us", dtUs.ToString(System.Globalization.CultureInfo.InvariantCulture), "a positive step (microseconds)"); }
    double dt = dtUs * 1e-6;
    double duration = FlagDouble(a, "--duration", 0.1);
    // D-DOC-022: a negative or zero --duration used to reach the engine. A larger negative one failed with the raw .NET
    // list message "(Parameter 'capacity')"; a small negative one, zero, or any duration shorter than half a step
    // rounded to 0 (or -1) steps and the run "succeeded" with only the t = 0 sample, exit 0. Both are refused here
    // with the reason (the engine refuses them too, as a last line of defence).
    if (!(duration > 0)) { Refuse($"--duration expected a positive number of seconds but got {Num(duration)}."); return; }
    double stepsExact = Math.Round(duration / dt);   // the step count exactly as the engine computes it
    if (stepsExact < 1)
    {
        Refuse($"--duration {Num(duration)} s is less than half of one timestep (--dt-us {Num(dtUs)}), so the run would take no step; " +
               "use a longer --duration or a smaller --dt-us.");
        return;
    }
    if (stepsExact > int.MaxValue - 1)
    {
        Refuse($"--duration {Num(duration)} s at --dt-us {Num(dtUs)} is {Num(stepsExact)} steps, more than one run can record ({int.MaxValue - 1}).");
        return;
    }
    // The latest event time the engine's step loop still applies: the last step's time plus the event tolerance,
    // computed exactly as the engine compares it (EmtEngine.Simulate). Used by the D-DOC-019 check below.
    double lastFiringTime = (int)stepsExact * dt + dt * EmtConstants.EventTimeToleranceFraction;

    double amp = FlagDouble(a, "--amp", 1.0);
    double freq = FlagDouble(a, "--freq", 0.0); // 0 = DC
    // DOC-6 (new, same class as D-DOC-019): a negative --freq used to mean DC without a word (the source is a
    // cosine only for freq > 0). 0 is the documented DC; anything below it is refused.
    if (freq < 0) { Refuse($"--freq expected 0 (DC) or a positive frequency in Hz but got {Num(freq)}."); return; }
    // R217: an enum flag accepts only its documented values; anything else (a typo) fails loud instead of
    // silently meaning trapezoidal.
    IntegrationRule rule = (FlagString(a, "--rule") ?? "trap").ToLowerInvariant() switch
    {
        "trap" => IntegrationRule.Trapezoidal,
        "be" => IntegrationRule.BackwardEuler,
        var bad => FailFlag<IntegrationRule>("--rule", bad, "trap or be"),
    };
    // D-DOC-123: the Critical Damping Adjustment only ever runs under the trapezoidal rule (EmtEngine.Simulate applies
    // it only when the base rule is trapezoidal: backward Euler has no Nyquist ringing to damp). summary.md used to
    // print "CDA: True" under --rule be, a damping step that never ran. This is what the run really does.
    bool cdaApplied = !noCda && rule == IntegrationRule.Trapezoidal;

    int defaultSrc = model.Generators.Count > 0 ? model.Generators[0].Bus : model.Buses[0].Id;
    int sourceBus = FlagInt(a, "--source", defaultSrc);

    EmtNetwork net;
    try { net = EmtNetwork.FromGridModel(model, new EmtBuildOptions(new[] { new EmtSourceSpec(sourceBus, Rs: 0, AmplitudePu: amp, FrequencyHz: freq) }, IncludeLoads: !noLoads, UseTravellingWaveLines: useLines)); }
    catch (Exception ex) { Console.Error.WriteLine($"emt: {ex.Message}"); Environment.ExitCode = 2; return; }

    // Events: repeated --event tokens. fault:<bus>@<t>:<Rpu> and clear:<bus>@<t> (a fault is a bus->ground
    // switch), or switch:<id>@<t>:close|open. A fault auto-adds a bus->ground SwitchElement to the network.
    var eventTokens = new List<string>();
    for (int ix; (ix = a.IndexOf("--event")) >= 0;)
    {
        // GR-208: a trailing --event (an empty shell variable) used to stop this loop and be ignored, so the run went
        // ahead with no fault; an --event with no value is refused like any other flag.
        if (FlagValueMissing(a, ix)) { FailFlag<string>("--event", "", "an event (fault:<bus>@<t>:<Rpu>, clear:<bus>@<t> or switch:<id>@<t>:close|open)"); return; }
        eventTokens.Add(a[ix + 1]); a.RemoveRange(ix, 2);
    }
    var emtEvents = new List<EmtEvent>();
    // For run-metadata.json (D-DOC-121): each event as given, and what it became.
    var eventRecords = new List<object>();
    if (eventTokens.Count > 0)
    {
        bool ParseAt(string s, out int key, out double t)
        {
            key = 0; t = 0;
            string[] at = s.Split('@');
            return at.Length == 2 && int.TryParse(at[0], System.Globalization.NumberStyles.Integer, inv, out key)
                && double.TryParse(at[1], System.Globalization.NumberStyles.Float, inv, out t);
        }
        string Usage(string tok) =>
            $"bad --event '{tok}' (use fault:<bus>@<t>:<Rpu>, clear:<bus>@<t>, or switch:<id>@<t>:close|open).";

        // D-DOC-019: an event time must be a finite number of seconds in [0, end of run]. A negative time used to be
        // applied at the first step (the docs-session run then diverged and exited 0) and a time after the end was
        // silently never applied.
        string? TimeProblem(double t) =>
            !double.IsFinite(t) || t < 0 ? $"time {Num(t)} s is not a number of seconds 0 or later"
            : !(t <= lastFiringTime) ? $"time {Num(t)} s is after the end of the run (--duration {Num(duration)} s), so it would never be applied"
            : null;

        // Pass 1: parse and check every token, keeping them in the order given (all problems are reported, then the
        // run is refused). Kind is "fault", "clear" or "switch"; Key is the bus (fault, clear) or the switch id.
        var parsed = new List<(string Kind, string Tok, int Key, double T, double R, bool Close)>();
        var problems = new List<string>();
        foreach (string tok in eventTokens)
        {
            string[] parts = tok.Split(':');
            string kind = parts[0].ToLowerInvariant();
            if (kind == "fault" && parts.Length == 3 && ParseAt(parts[1], out int fb, out double ft)
                && double.TryParse(parts[2], System.Globalization.NumberStyles.Float, inv, out double rf))
            {
                // D-DOC-122: a fault resistance of 0 is an infinite conductance; it used to fail inside the engine with
                // a message that quoted the Critical Damping Adjustment's HALF-step dt, and a negative one generated
                // energy. Refused here, naming the resistance.
                if (!net.BusToNode.ContainsKey(fb)) problems.Add($"'{tok}': bus {fb} is not in case '{model.Name}'");
                else if (!(rf > 0) || !double.IsFinite(rf)) problems.Add($"'{tok}': fault resistance {Num(rf)} pu must be a positive number (a bolted fault is a small one, for example 1e-4)");
                else if (TimeProblem(ft) is string tp) problems.Add($"'{tok}': {tp}");
                else parsed.Add(("fault", tok, fb, ft, rf, true));
            }
            else if (kind == "clear" && parts.Length == 2 && ParseAt(parts[1], out int cb, out double ct))
            {
                if (TimeProblem(ct) is string tp) problems.Add($"'{tok}': {tp}");
                else parsed.Add(("clear", tok, cb, ct, 0.0, false));
            }
            else if (kind == "switch" && parts.Length == 3 && ParseAt(parts[1], out int swId, out double swT))
            {
                // D-DOC-023: only close and open are actions. Any other word (a typo such as "clsoe") used to OPEN the
                // switch without a word.
                bool? close = parts[2].ToLowerInvariant() switch { "close" => true, "open" => false, _ => null };
                if (close is null) problems.Add($"'{tok}': switch action '{parts[2]}' is not close or open");
                else if (TimeProblem(swT) is string tp) problems.Add($"'{tok}': {tp}");
                else parsed.Add(("switch", tok, swId, swT, 0.0, close.Value));
            }
            else problems.Add(Usage(tok));
        }

        // D-DOC-020: a second fault at a bus that is already faulted used to reuse the FIRST fault's switch, and so its
        // resistance, whatever the second token said. Each distinct (bus, resistance) now has its own fault switch, in
        // the order the tokens first name them (so a run with one resistance per bus builds exactly the network it
        // always did). Applying a fault at a bus opens that bus's other fault switches at the same instant (the fault
        // at the bus BECOMES the new resistance), and clear:<bus> opens all of them. Two faults at one bus at the same
        // instant would contradict each other and are refused.
        var faultSwitches = new Dictionary<int, List<(double R, int Id)>>();   // bus -> its fault switches
        var elems = new List<EmtElement>(net.Elements);
        int nextId = GridSim.Cli.CliDefaults.EmtFaultSwitchIdBase;
        foreach (var f in parsed.Where(e => e.Kind == "fault"))
        {
            if (!faultSwitches.TryGetValue(f.Key, out var list)) faultSwitches[f.Key] = list = new List<(double R, int Id)>();
            if (list.Any(s => s.R.Equals(f.R))) continue;   // the same resistance again: the same switch (a re-fault)
            int sid = nextId++;
            list.Add((f.R, sid));
            elems.Add(new SwitchElement(sid, net.BusToNode[f.Key], EmtNetwork.Ground, Ron: f.R, Roff: GridSim.Cli.CliDefaults.EmtSwitchOffResistance, InitiallyClosed: false));
        }
        foreach (var same in parsed.Where(e => e.Kind == "fault").GroupBy(f => (f.Key, f.T)).Where(grp => grp.Count() > 1))
            problems.Add($"{same.Count()} faults at bus {same.Key.Key} at the same time {Num(same.Key.T)} s ({string.Join(", ", same.Select(f => "'" + f.Tok + "'"))}); give one");
        foreach (var c in parsed.Where(e => e.Kind == "clear"))
            if (!faultSwitches.ContainsKey(c.Key)) problems.Add($"'{c.Tok}': bus {c.Key} has no fault: event to clear");

        if (problems.Count > 0)
        {
            foreach (string p in problems) Console.Error.WriteLine($"error: emt: {p}");
            Environment.ExitCode = CliExit.Usage;
            return;
        }

        // Pass 2: the switch events, in token order (the engine sorts them by time, keeping this order at one instant).
        foreach (var e in parsed)
        {
            if (e.Kind == "fault")
            {
                var list = faultSwitches[e.Key];
                int own = list.First(s => s.R.Equals(e.R)).Id;
                foreach (var other in list.Where(s => s.Id != own)) emtEvents.Add(new SwitchEvent(e.T, other.Id, Close: false));
                emtEvents.Add(new SwitchEvent(e.T, own, Close: true));
                eventRecords.Add(new { token = e.Tok, kind = "fault", bus = e.Key, atSeconds = e.T, resistancePu = e.R, switchId = own });
            }
            else if (e.Kind == "clear")
            {
                foreach (var s in faultSwitches[e.Key]) emtEvents.Add(new SwitchEvent(e.T, s.Id, Close: false));
                eventRecords.Add(new { token = e.Tok, kind = "clear", bus = e.Key, atSeconds = e.T, switchIds = faultSwitches[e.Key].Select(s => s.Id).ToArray() });
            }
            else
            {
                emtEvents.Add(new SwitchEvent(e.T, e.Key, e.Close));
                eventRecords.Add(new { token = e.Tok, kind = "switch", switchId = e.Key, atSeconds = e.T, action = e.Close ? "close" : "open" });
            }
        }
        net = new EmtNetwork(net.NodeCount, elems, net.BusToNode, net.SeriesBranchIds);
    }

    // Probes: default = source-bus voltage + first branch current; else parse v:<bus> / i:<from>-<to>.
    var probes = new List<EmtProbe>();
    string? probeSpec = FlagString(a, "--probe");
    if (probeSpec is null)
    {
        probes.Add(new EmtProbe($"v:{sourceBus}", EmtProbeKind.NodeVoltage, net.BusToNode[sourceBus]));
        if (net.SeriesBranchIds.Count > 0)
        {
            var b0 = net.SeriesBranchIds[0];
            // N241: when the first branch has parallel twins, its label says which one it is (#1, case order).
            bool parallel = net.SeriesBranchIds.Count(s => s.From == b0.From && s.To == b0.To) > 1;
            probes.Add(new EmtProbe($"i:{b0.From}->{b0.To}{(parallel ? "#1" : "")}", EmtProbeKind.BranchCurrent, b0.ElementId));
        }
    }
    else
    {
        // D-DOC-021: every probe token must name something. A non-numeric i: probe (i:a-b) used to be dropped with no
        // message at all, and an unknown bus or branch, or a token that is neither v: nor i:, was skipped with a
        // stderr line while the run went on with fewer columns than asked and exit 0. All are now refused (exit 2).
        var problems = new List<string>();
        foreach (string tokRaw in probeSpec.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            if (tokRaw.StartsWith("v:", StringComparison.OrdinalIgnoreCase))
            {
                if (!int.TryParse(tokRaw.AsSpan(2), System.Globalization.NumberStyles.Integer, inv, out int vb))
                    problems.Add($"probe '{tokRaw}': '{tokRaw[2..]}' is not a bus number");
                else if (!net.BusToNode.TryGetValue(vb, out int vn))
                    problems.Add($"probe '{tokRaw}': bus {vb} is not in case '{model.Name}'");
                else probes.Add(new EmtProbe(tokRaw, EmtProbeKind.NodeVoltage, vn));
            }
            else if (tokRaw.StartsWith("i:", StringComparison.OrdinalIgnoreCase))
            {
                string body = tokRaw[2..].Replace("->", "-", StringComparison.Ordinal);
                // N241 (October 2026): an optional '#k' picks the k-th (1-based, in case order) of several in-service
                // series branches that join the same two buses. A plain i:<from>-<to> on parallel branches used to read
                // the FIRST of them without a word; it is now refused as ambiguous, naming how many there are and how
                // to choose one. A single branch needs no '#k' (and '#1' on it is accepted).
                int pick = 0;   // 0 = no '#k' given
                int hash = body.IndexOf('#');
                if (hash >= 0)
                {
                    if (!int.TryParse(body.AsSpan(hash + 1), System.Globalization.NumberStyles.None, inv, out pick) || pick < 1)
                    {
                        problems.Add($"probe '{tokRaw}': '#{body[(hash + 1)..]}' is not a parallel-branch number (expected #1, #2, ...)");
                        continue;
                    }
                    body = body[..hash];
                }
                string[] ft = body.Split('-', 2);
                if (ft.Length != 2 || !int.TryParse(ft[0], System.Globalization.NumberStyles.Integer, inv, out int fb)
                    || !int.TryParse(ft[1], System.Globalization.NumberStyles.Integer, inv, out int tb))
                {
                    problems.Add($"probe '{tokRaw}': expected i:<from>-<to> with two bus numbers (or i:<from>-<to>#<k> for the k-th parallel branch)");
                    continue;
                }
                var matches = new List<int>();
                foreach (var s in net.SeriesBranchIds) if (s.From == fb && s.To == tb) matches.Add(s.ElementId);
                if (matches.Count == 0)
                    problems.Add($"probe '{tokRaw}': case '{model.Name}' has no in-service series branch {fb}->{tb} (the direction is the case's from -> to)");
                else if (pick == 0 && matches.Count > 1)
                    problems.Add($"probe '{tokRaw}': case '{model.Name}' has {matches.Count} in-service series branches {fb}->{tb} in parallel, so the probe is ambiguous; " +
                        $"name one as i:{fb}-{tb}#1 .. i:{fb}-{tb}#{matches.Count} (case order)");
                else if (pick > matches.Count)
                    problems.Add($"probe '{tokRaw}': case '{model.Name}' has {matches.Count} in-service series branch(es) {fb}->{tb}, so there is no #{pick}");
                else probes.Add(new EmtProbe(tokRaw, EmtProbeKind.BranchCurrent, matches[pick == 0 ? 0 : pick - 1]));
            }
            else problems.Add($"probe '{tokRaw}' is not v:<bus> or i:<from>-<to>");
        }
        if (problems.Count > 0)
        {
            foreach (string p in problems) Console.Error.WriteLine($"error: emt: {p}");
            Environment.ExitCode = CliExit.Usage;
            return;
        }
    }
    if (probes.Count == 0) { Console.Error.WriteLine("emt: no valid probes."); Environment.ExitCode = 2; return; }

    EmtResult res;
    EmtEngine engine;
    try
    {
        // D-DOC-024: the engine refuses a non-passive network (a negative series resistance or shunt conductance, which
        // network-reduction equivalents such as IEEE 145 carry) unless --allow-non-passive asks for it.
        engine = new EmtEngine(net, dt, new EmtOptions { Rule = rule, UseCda = !noCda, RefuseNonPassive = !allowNonPassive });
        if (engine.NonPassiveElements.Count > 0)
            Console.Error.WriteLine($"emt: warning: --allow-non-passive: running {engine.NonPassiveElements.Count} non-passive element(s) " +
                $"(first: {engine.NonPassiveElements[0]}); the trajectory may grow without bound.");
        res = engine.Simulate(new EmtCase(net, dt, duration, probes, emtEvents));
    }
    catch (InvalidOperationException ex) { Console.Error.WriteLine($"emt: {ex.Message}"); Environment.ExitCode = 3; return; }
    catch (EmtNonPassiveNetworkException ex)
    {
        Console.Error.WriteLine($"error: emt: {CliExit.UserMessage(ex)}");
        Console.Error.WriteLine("error: emt: pass --allow-non-passive to run this network anyway.");
        Environment.ExitCode = CliExit.Usage;
        return;
    }
    // A bad --event (for example switch:<id> naming an element that is not a switch) throws ArgumentException from the
    // engine; it used to escape unhandled. It is a usage error: exit 2 with the reason (1.95.060). D-DOC-024 / 025:
    // the engine's network and probe refusals arrive here too; the C# parameter-name suffix is dropped.
    catch (ArgumentException ex) { Console.Error.WriteLine($"emt: {CliExit.UserMessage(ex)}"); Environment.ExitCode = 2; return; }
    // R026: nodes with no resistive path to a reference are pinned at 0 V in the starting-state solve; say how many.
    if (engine.InitialConditionFloatingNodes > 0)
        Console.Error.WriteLine($"emt: {engine.InitialConditionFloatingNodes} floating node(s) pinned at 0 V in the initial-condition solve.");

    foreach (EmtPoint pt in res.Points)
        foreach (double x in pt.Probe)
            if (!double.IsFinite(x)) { Console.Error.WriteLine("emt: non-finite value in trajectory (numerical failure)."); Environment.ExitCode = 3; return; }

    string caseLabel = caseName ?? "uk";
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath("emt-out");   // N079: was emt-out in the current directory
    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    string desc = $"emt {caseLabel} dt={dtUs}us dur={duration}s src=bus{sourceBus} amp={amp} freq={freq}Hz rule={rule}";
    // D-DOC-121: the sidecar now records everything that shaped the run, not only the one-line description: the
    // probes (name, kind and what each reads), the events (as given and as applied), and the model switches.
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc, new
    {
        verb = "emt",
        @case = caseLabel,
        modelName = model.Name,
        dtMicroseconds = dtUs,
        durationSeconds = duration,
        steps = res.Stats.Steps,
        sourceBus,
        amplitudePu = amp,
        frequencyHz = freq,
        rule = rule == IntegrationRule.Trapezoidal ? "trap" : "be",
        criticalDampingAdjustment = cdaApplied,
        noCdaFlag = noCda,
        travellingWaveLines = useLines,
        loads = !noLoads,
        allowNonPassive,
        nonPassiveElements = engine.NonPassiveElements.Count,
        probes = probes.Select(p => new { name = p.Name, kind = p.Kind == EmtProbeKind.NodeVoltage ? "nodeVoltage" : "branchCurrent", target = p.Target }).ToArray(),
        events = eventRecords.ToArray(),
    });

    using (var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "timeseries.csv"), "timeseries.csv")))
    {
        foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
        csv.WriteLine("t_seconds," + string.Join(",", res.ProbeNames));
        foreach (EmtPoint pt in res.Points)
            csv.WriteLine(pt.TSeconds.ToString("G9", inv) + "," + string.Join(",", pt.Probe.Select(x => x.ToString("G9", inv))));
    }

    EmtRunStats st = res.Stats;
    double sps = st.WallMs > 0 ? st.Steps / (st.WallMs / 1000.0) : 0;
    string srcKind = freq > 0 ? $"{freq} Hz" : "DC";
    // D-DOC-123: "CDA" reports what ran. Under --rule be it is off whatever --no-cda says, and the line says why.
    string cdaText = cdaApplied ? "on" : noCda ? "off (--no-cda)" : "off (not used under backward Euler)";
    File.WriteAllText(CliFiles.Output(Path.Combine(outDir, "summary.md"), "summary.md"),
        $"# EMT run: {caseLabel}\n\n- steps: {st.Steps:N0} @ {dtUs} us (dur {duration}s)\n- source: bus {sourceBus}, amp {amp} pu, {srcKind}\n" +
        $"- refactorizations: {st.Refactorizations}\n- peak |probe|: {st.MaxProbeAbs:G6}\n- wall: {st.WallMs:F1} ms ({sps:N0} steps/s)\n- rule: {rule}, CDA: {cdaText}\n\n" +
        "A forward model trajectory, not a claim about the real grid.\n");

    Console.WriteLine($"emt {caseLabel}: {st.Steps:N0} steps @ {dtUs}us, {st.Refactorizations} factorization(s), peak |probe| {st.MaxProbeAbs:G4}, {st.WallMs:F0} ms -> {outDir}");
}

// harmonics <case> [--dir <dir>] [--spectra <gridsim-harmonics/1.json> | --synth-sources | --converter-sources rated|dispatched]
//           [--bus <id>] [--enableExport[=path]]
//   Frequency-domain harmonic study: penetration (Y(h) V = I), the driving-point resonance scan, voltage-THD
//   indices and an IEEE-519 compliance verdict. Sources come from a gridsim-harmonics/1 file (the schema lives
//   in GDA) or the synthetic default library. Grounded engine; the source spectra are the only assumed input.
void RunHarmonics(List<string> a, string root, bool export, string? exportPath)
{
    // Case: positional or --dir through the shared SelectCase (default case9). The old code read the case from a[1]
    // only, so "harmonics --spectra f.json case14" silently studied case9, and --dir silently won over a positional
    // case. The boolean --synth-sources is left out of the scan, so Positionals cannot take the next token as its
    // value. An unknown case name exits 2 (LoadSelected); a missing file or folder exits 1.
    for (int i = 1; i < a.Count; i++) if (a[i] == "-d") a[i] = "--dir";   // the short alias this verb always accepted
    var harmonicsSel = SelectCase("harmonics",
        SingleCasePositional("harmonics", a.Where(t => t != "--synth-sources").ToList()), a, root,
        "case9", () => LoadNamed("case9", root));
    GridModel m = LoadSelected("harmonics", harmonicsSel);

    // Sources: a gridsim-harmonics/1 file, else a synthetic 6-pulse load at the largest-demand bus.
    HarmonicSourceSet sources;
    int sp = a.FindIndex(t => t == "--spectra");
    // R069: --synth-sources selects the synthetic default explicitly; with --spectra as well the request is
    // contradictory (it used to let --spectra win silently), so refuse it.
    if (sp >= 0 && a.Contains("--synth-sources"))
    {
        Console.Error.WriteLine("error: --spectra and --synth-sources are mutually exclusive (a measured source file, or the synthetic default).");
        Environment.ExitCode = 2;
        return;
    }
    // N036 (October 2026): --converter-sources builds one source per converter-interfaced unit from the Core rule
    // (ConverterHarmonicSources: G5 Issue 5 Table B.3 profiles, scaled by each unit's rated or dispatched current). It
    // is a third choice of source, so it is refused with either of the other two (exit 2), like those two together.
    // Without the flag nothing below changes: the default study is exactly what it was.
    string? converterLevelText = FlagString(a, "--converter-sources");   // null when absent; no value -> exit 2
    if (converterLevelText is not null && (sp >= 0 || a.Contains("--synth-sources")))
    {
        Console.Error.WriteLine("error: --converter-sources, --spectra and --synth-sources are mutually exclusive (one choice of harmonic sources).");
        Environment.ExitCode = 2;
        return;
    }
    // N131 (Ruling R1, Mark delegated 2026-10-04): the synthetic default source is the cited G5 Issue 5 Table B.3
    // six-pulse profile (HarmonicSourceLibrary.DefaultSyntheticSourceType, "6-pulse-g5"); before, it was the idealised
    // 1/h six-pulse spectrum, which understates the G5 profile (5th 20 % vs 31.4 %). --synth-spectrum ideal keeps the 1/h
    // spectrum available; --synth-spectrum g5 names the default. It shapes the synthetic source only, so with --spectra or
    // --converter-sources (which bring their own spectra) it is refused (exit 2) rather than silently ignored.
    string? synthSpectrumText = FlagString(a, "--synth-spectrum");   // null when absent; no value -> exit 2
    if (synthSpectrumText is not null && (sp >= 0 || converterLevelText is not null))
    {
        Console.Error.WriteLine("error: --synth-spectrum shapes the synthetic default source only; --spectra and --converter-sources bring their own spectra.");
        Environment.ExitCode = 2;
        return;
    }
    string synthSourceType = (synthSpectrumText ?? "g5").ToLowerInvariant() switch
    {
        "g5" => HarmonicSourceLibrary.DefaultSyntheticSourceType,
        "ideal" => HarmonicSourceLibrary.IdealSixPulseType,
        var bad => FailFlag<string>("--synth-spectrum", bad, "g5 or ideal"),
    };
    ConverterHarmonicSourceSet? converterSet = null;
    if (converterLevelText is not null)
    {
        ConverterHarmonicLevel converterLevel = converterLevelText.ToLowerInvariant() switch
        {
            "rated" => ConverterHarmonicLevel.Rated,
            "dispatched" => ConverterHarmonicLevel.Dispatched,
            var bad => FailFlag<ConverterHarmonicLevel>("--converter-sources", bad, "rated or dispatched"),
        };
        // N150 (1.95.243): the dispatched level is the operating point, so each unit's output is read from the solved
        // fundamental (the slack's P and every PV unit's Q come from the solve), not from the case's schedule. The
        // solve is the same deterministic one the study makes below; one that does not converge stops the study
        // (exit 3), as the fundamental does.
        PowerFlowResult? operatingPoint = null;
        if (converterLevel == ConverterHarmonicLevel.Dispatched)
        {
            operatingPoint = PickSolver(m).Solve(m);
            if (!operatingPoint.Converged)
            {
                Console.Error.WriteLine($"harmonics: FAILED - --converter-sources dispatched needs the solved operating point, and the fundamental power flow of {m.Name} did not converge (status {operatingPoint.Status}, max mismatch {operatingPoint.MaxMismatch.ToString("G6", System.Globalization.CultureInfo.InvariantCulture)}).");
                Environment.ExitCode = 3;
                return;
            }
        }
        // A unit whose rating (rated) or output (dispatched) is not a usable number is an input error (exit 1), as
        // is a case with no converter-interfaced unit at all: a study with no source is not a result.
        try { converterSet = ConverterHarmonicSources.FromModel(m, converterLevel, balanced: true, operatingPoint: operatingPoint); }
        catch (ArgumentException ex) { Console.Error.WriteLine($"error: harmonics: {ex.Message}"); Environment.ExitCode = 1; return; }
        if (converterSet.Sources.Count == 0)
        {
            Console.Error.WriteLine($"error: harmonics: --converter-sources: {m.Name} has no converter-interfaced unit that injects " +
                $"({converterSet.UnitsNotModelled.Count} converter unit(s) not modelled{(converterSet.UnitsNotModelled.Count > 0 ? ": " + string.Join("; ", converterSet.UnitsNotModelled) : "")}).");
            Environment.ExitCode = 1;
            return;
        }
        sources = new HarmonicSourceSet { Case = m.Name, Sources = converterSet.Sources };
    }
    else if (sp >= 0)
    {
        // --spectra with no path used to silently fall through to the synthetic 6-pulse default (a study
        // for sources the user never asked for); a bad path threw an unhandled FileNotFoundException.
        if (sp + 1 >= a.Count || a[sp + 1].StartsWith("--", StringComparison.Ordinal))
        {
            Console.Error.WriteLine("error: --spectra expected a gridsim-harmonics/1 file path");
            Environment.ExitCode = 2; return;
        }
        try { sources = HarmonicSourceSet.Load(a[sp + 1]); sources.Validate(m); }
        catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
        catch (Exception ex) { Console.Error.WriteLine($"error: failed to load --spectra '{a[sp + 1]}': {ex.Message}"); Environment.ExitCode = 2; return; }
    }
    else
    {
        int bus = m.Buses.OrderByDescending(b => b.Pd).FirstOrDefault()?.Id ?? m.Buses[0].Id;
        sources = new HarmonicSourceSet
        {
            Case = m.Name,
            // N131: the G5 six-pulse profile by default, the 1/h spectrum with --synth-spectrum ideal.
            Sources = new[] { HarmonicSourceLibrary.Make(synthSourceType, bus, fundamentalCurrentPu: GridSim.Cli.CliDefaults.DefaultHarmonicSourcePu) },
        };
    }

    // The physical study model: network + machine source impedance + loads as damping shunts (R001). The bare
    // network-only default left radial cases singular (reported as 0% THD, "Compliant"). N036: the per-converter study
    // is the same model over orders 2 to 50 (G5 Table B.3's range: the active-front-end profile has even orders).
    HarmonicModelOptions opt = converterSet is null ? HarmonicModelOptions.Study : ConverterHarmonicSources.StudyOptions;

    // N149 (Ruling R1; ENA EREC G5 Issue 5 s.3.29 p.17): --afe-reactance X [--afe-resistance R] stamps every
    // active-front-end converter (the self-commutated class; line-commutated units are untouched) as resonant plant, a
    // shunt R + jhX on its rating, so the study sees it as a Norton equivalent instead of an ideal current source. No
    // default value exists on disk ([VERIFY]: the converter's own reactor or filter), so without the flag nothing changes.
    string? afeXText = FlagString(a, "--afe-reactance");    // null when absent; no value -> exit 2
    string? afeRText = FlagString(a, "--afe-resistance");
    int afeUnits = 0;
    if (afeRText is not null && afeXText is null)
    {
        Console.Error.WriteLine("error: --afe-resistance is the resistance in series with --afe-reactance; give --afe-reactance too.");
        Environment.ExitCode = 2;
        return;
    }
    if (afeXText is not null)
    {
        double afeX = FlagDouble(a, "--afe-reactance", double.NaN);
        double afeR = afeRText is null ? 0.0 : FlagDouble(a, "--afe-resistance", double.NaN);
        if (!double.IsFinite(afeX) || !(afeX > 0.0) || !double.IsFinite(afeR) || afeR < 0.0)
        {
            Console.Error.WriteLine("error: --afe-reactance expected a finite reactance above 0 pu and --afe-resistance a finite resistance of 0 pu or more (both on each converter's rating).");
            Environment.ExitCode = 2;
            return;
        }
        afeUnits = m.Generators.Count(GridSim.Core.Harmonics.FrequencyDependentYBus.IsActiveFrontEndPlant);
        if (afeUnits == 0)
        {
            Console.Error.WriteLine($"error: harmonics: --afe-reactance: {m.Name} has no active-front-end converter unit (in service, converter-interfaced, not power-flow-only, not line-commutated) to stamp.");
            Environment.ExitCode = 1;
            return;
        }
        // The impedance is on each unit's rating: a unit without a usable rating is an input error (exit 1), named here
        // before the study, not left to surface from inside it.
        foreach (Generator afeUnit in m.Generators.Where(GridSim.Core.Harmonics.FrequencyDependentYBus.IsActiveFrontEndPlant))
        {
            try { GridSim.Core.Harmonics.FrequencyDependentYBus.ActiveFrontEndImpedanceSystemPu(afeUnit, m.BaseMva, afeR, afeX); }
            catch (InvalidOperationException ex) { Console.Error.WriteLine($"error: harmonics: --afe-reactance: {ex.Message}"); Environment.ExitCode = 1; return; }
        }
        opt = opt with { ActiveFrontEndReactancePu = afeX, ActiveFrontEndResistancePu = afeR };
    }

    // A spectrum component at an order outside the analysed set (odd orders 3 to 49) was dropped without a word, so a
    // file holding only such orders (for example an even 2nd or a 51st harmonic) reported 0.00 % THD, fully compliant,
    // exit 0. Decision (docs-programme finding): REFUSE, exit 1, naming every such component. Including the order would
    // silently change the analysed set, the impedance scan and the compliance table under the user; refusing keeps the
    // study exactly the one documented and makes the user drop or confirm the component.
    IReadOnlyList<string> outside = HarmonicPenetration.ComponentsOutsideOrders(sources.Sources, opt);
    if (outside.Count > 0)
    {
        Console.Error.WriteLine($"error: harmonics: {outside.Count} source component(s) are at orders this study does not analyse " +
            $"(it analyses orders {string.Join(",", opt.Orders)}): {string.Join("; ", outside)}. They would be ignored and the THD " +
            "understated; remove them from the spectra file.");
        Environment.ExitCode = 1;
        return;
    }

    // R217: an unparseable --bus fails loud (FlagInt). An id that is not in the model used to escape as an unhandled
    // ArgumentException from the impedance scan, after the whole penetration study had run; check it up front (exit 2).
    int busFlag = FlagInt(a, "--bus", int.MinValue);
    if (busFlag != int.MinValue && !m.Buses.Any(b => b.Id == busFlag))
    {
        Console.Error.WriteLine($"error: harmonics: --bus {busFlag} is not a bus of {m.Name}.");
        Environment.ExitCode = 2;
        return;
    }

    // THD and IHD are ratios to the SOLVED fundamental voltage at each bus, the same denominator the web HARMONICS tab
    // uses, through the one Core function HarmonicIndices.SolvedFundamentalVm (docs-programme finding: the CLI used a
    // nominal 1.0 pu, so the two front ends printed different THD for one network). The fundamental is the same solve
    // "gridsim <case> --once" reports; a fundamental that does not converge stops the study (exit 3), because a ratio
    // over a non-converged voltage is not a result.
    // D-DOC-140: the export's meta.elapsedMs is the wall time of the study (the fundamental solve, the penetration,
    // the indices, the compliance, the scan and the fine sweep), measured here; it used to be a hard-coded 0.
    var harmonicClock = System.Diagnostics.Stopwatch.StartNew();
    PowerFlowResult fundamental = PickSolver(m).Solve(m);

    HarmonicPenetrationResult pen;
    HarmonicIndicesResult idx;
    IReadOnlyList<BusComplianceResult> compliance;
    ImpedanceScanResult scan;
    FrequencySweepResult sweep;
    int scanBus;
    double[] v1;   // N244: kept for the export, which now records the THD denominator
    try
    {
        pen = HarmonicPenetration.Solve(m, sources.Sources, opt);
        v1 = HarmonicIndices.SolvedFundamentalVm(pen, fundamental);
        idx = HarmonicIndices.FromPenetration(pen, v1);
        compliance = HarmonicCompliance.AssessIeee519(m, pen, v1);

        scanBus = busFlag == int.MinValue ? idx.WorstBusId : busFlag;
        scan = HarmonicImpedanceScan.DrivingPoint(m, scanBus, opt);
        // R063: the order-by-order scan only samples integer orders; the fine sweep finds the true peak between them.
        sweep = HarmonicFrequencySweep.DrivingPoint(m, scanBus, opt);
        harmonicClock.Stop();
    }
    catch (SingularHarmonicNetworkException ex)
    {
        // Fail loud: no THD, no compliance verdict, non-zero exit.
        Console.Error.WriteLine($"harmonics: FAILED - {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }
    catch (InvalidOperationException ex)
    {
        // SolvedFundamentalVm: the fundamental did not converge (or a bus has no usable |V_1|).
        Console.Error.WriteLine($"harmonics: FAILED - {ex.Message}");
        Environment.ExitCode = 3;
        return;
    }
    catch (ArgumentException ex)
    {
        // The balanced positive-sequence study refuses a triplen (zero-sequence) source (R029). That used to escape
        // as an unhandled exception; it is a property of the input spectra, so exit 1 with the engine's message.
        Console.Error.WriteLine($"error: harmonics: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }

    int compliant = compliance.Count(c => c.Compliant);
    Console.WriteLine($"harmonics: case {m.Name}, {sources.Sources.Count} source(s), orders {opt.Orders.Count}");
    // N131: the synthetic default source names its spectrum, since the default changed (G5 Table B.3 six-pulse).
    if (converterSet is null && sp < 0)
        Console.WriteLine($"  synthetic source : {synthSourceType} at bus {sources.Sources[0].Bus}, {GridSim.Cli.CliDefaults.DefaultHarmonicSourcePu} pu fundamental ("
            + (synthSourceType == HarmonicSourceLibrary.IdealSixPulseType
                ? "the idealised 1/h six-pulse spectrum, --synth-spectrum ideal)"
                : "G5 Issue 5 Table B.3 six-pulse profile, the default; --synth-spectrum ideal for the idealised 1/h)"));
    if (converterSet is not null)
    {
        // N036: what the sources are and what the rule left out, so nothing is dropped without a word.
        int afe = converterSet.Sources.Count(s => s.SourceType == ConverterHarmonicSources.SelfCommutatedProfile);
        int lcc = converterSet.Sources.Count - afe;
        Console.WriteLine($"  converter sources: {afe} self-commutated ({ConverterHarmonicSources.SelfCommutatedProfile}), {lcc} line-commutated " +
            $"({ConverterHarmonicSources.LineCommutatedProfile}), level {converterLevelText!.ToLowerInvariant()} (G5 Issue 5 Table B.3, linear addition)");
        if (converterSet.OmittedComponents.Count > 0)
            Console.WriteLine($"  omitted          : {converterSet.OmittedComponents.Count} triplen component(s) (zero sequence; the balanced study cannot carry them), first: {converterSet.OmittedComponents[0]}");
        foreach (string u in converterSet.UnitsNotModelled)
            Console.WriteLine($"  not modelled     : {u}");
    }
    if (afeUnits > 0)   // N149: only with --afe-reactance; without it the output is exactly as before
        Console.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
            $"  AFE impedance    : {afeUnits} active-front-end unit(s) stamped as resonant plant (G5 Issue 5 s.3.29), R + jhX = {opt.ActiveFrontEndResistancePu} + j{opt.ActiveFrontEndReactancePu} pu on each unit's rating [VERIFY value]"));
    Console.WriteLine($"  worst voltage THD : {idx.WorstThdPct:F2}% at bus {idx.WorstBusId} (relative to the solved fundamental voltage)");
    Console.WriteLine($"  resonance (bus {scanBus}): order {scan.ResonanceOrder}, |Z|={scan.PeakMagnitude:F3} pu, sharpness {HarmonicIndices.DampingSharpness(scan):F1}");
    Console.WriteLine($"  fine sweep peak  : h={sweep.PeakOrder:F4} ({sweep.PeakHz:F2} Hz), |Z|={sweep.PeakMagnitude:F3} pu, {sweep.PeakSequence.ToString().ToLowerInvariant()} sequence");
    Console.WriteLine($"  IEEE-519         : {compliant}/{compliance.Count} buses compliant");
    int unknownKv = compliance.Count(c => !c.VoltageLevelKnown);
    if (unknownKv > 0)   // R265: say so, rather than let them hide inside the non-compliant count
        Console.WriteLine($"  WARNING          : {unknownKv} bus(es) have no base kV - judged at the strictest tier and NOT certified");

    if (export)
    {
        var meta = new SolveExportMeta(m.Name, "harmonics", RunInfo.GitCommit, DateTime.UtcNow.ToString("o"),
            harmonicClock.Elapsed.TotalMilliseconds, Environment.MachineName);   // D-DOC-140: was a hard-coded 0
        string path = exportPath ?? DefaultResultsPath("harmonic-export.json");   // N079: was harmonic-export.json in the current directory
        // N244: with the solved |V_1| per bus, so crossval_harmonics.py forms THD over the same denominator.
        HarmonicExport.WriteJson(CliFiles.Output(path, "harmonic export"), m, sources, pen, idx, meta, scan, compliance, opt, sweep, v1);
        Console.WriteLine($"  export -> {Path.GetFullPath(path)}");
    }
}

// impedance-stability <case|--dir DIR> [--bus ID] [--converter gfl|gfm] [--criterion siso|mimo]
//   [--fmin 0.1] [--fmax 250] [--ppd 50] [--scr 3] [--scr-min 1] [--scr-max 10] [--scr-steps 37]
//   [--pll-bw HZ] [--pll-damping Z] [--current-bw HZ] [--enableExport[=path]]
// The impedance-based (generalised-Nyquist) inverter-grid stability screen: forms L = Z_grid * Y_conv over
// frequency, counts encirclements of (-1,0), and sweeps SCR to find the weak-grid instability boundary.
void RunImpedanceStability(List<string> a, string root, bool export, string? exportPath)
{
    // N074 (October 2026): the case is a positional argument or --dir through the shared SelectCase (default case9), as
    // harmonics and the contingency verbs already do. The old code read the case only from the token right after the
    // verb, so "impedance-stability --bus 3 case14" silently studied case9, a .m file or a case folder given positionally
    // was not accepted at all, and --dir silently won over a positional case. Every flag of this verb takes a value, so
    // Positionals reads the free tokens correctly. An unknown case name exits 2 (LoadSelected), a second case argument
    // exits 2, a missing or unloadable file or folder exits 1, and a positional case with a different --dir exits 2.
    for (int i = 1; i < a.Count; i++) if (a[i] == "-d") a[i] = "--dir";   // the short alias this verb always accepted
    // R082 (October 2026): --outer-loop-only is this verb's one value-less flag, so it is taken off the list before the
    // case is read (Positionals takes every remaining --flag to have a value).
    bool outerLoopOnly = a.Remove("--outer-loop-only");
    string? impPos = SingleCasePositional("impedance-stability", a);
    // D-DOC-134: the modal cross-check below uses the WSCC-9 Anderson-Fouad X'd when the case is the built-in case9
    // (named case9 / ieee9, or the default with no case and no --dir), exactly as stability, modal and experimental
    // modal-consistency choose it; any other case gets the synthetic X'd, and the output says which.
    bool impWscc9 = !a.Contains("--dir") && (impPos ?? "case9").ToLowerInvariant() is "case9" or "ieee9";
    GridModel m = LoadSelected("impedance-stability", SelectCase("impedance-stability",
        impPos, a, root, "case9", () => LoadNamed("case9", root)));

    PowerFlowResult pf = backend.NewtonSolver(m).Solve(m);   // shared rule on the selected backend (was CPU dense always; R104)
    if (!pf.Converged) { Console.Error.WriteLine("impedance-stability: power flow did not converge."); Environment.ExitCode = 3; return; }

    // Pick the inverter bus: --bus, else the largest generator bus (largest by SCHEDULED Pg: this only chooses the unit;
    // its operating point below is read from the solve). The unit's index in m.Generators is kept, not the record, so
    // the solved-output lookup cannot pick a different unit with equal fields.
    int busArg = FlagInt(a, "--bus", int.MinValue);
    int genIdx = -1;
    for (int k = 0; k < m.Generators.Count; k++)
    {
        if (busArg != int.MinValue) { if (m.Generators[k].Bus == busArg) { genIdx = k; break; } }
        else if (genIdx < 0 || m.Generators[k].Pg > m.Generators[genIdx].Pg) genIdx = k;   // first of the largest, as OrderByDescending was
    }
    if (genIdx < 0) { Console.Error.WriteLine("impedance-stability: no generator to attach a converter model to."); Environment.ExitCode = 2; return; }
    Generator gen = m.Generators[genIdx];
    int bus = gen.Bus;

    // Operating point from the solve: aligned Vd0 = |V|, Id0 = P/Vd0, Iq0 = -Q/Vd0 (pu on the converter rating).
    int bi = pf.BusIds.ToList().IndexOf(bus);
    double vm = bi >= 0 ? pf.Vm[bi] : 1.0;
    double mBase = gen.MBase > 0 ? gen.MBase : m.BaseMva;
    // D-DOC-054 (docs-session finding, Ruling R1: Mark delegated 2026-10-04, NUM): P and Q are the unit's SOLVED output
    // (SolvedGeneration.UnitOutput: the bus's solved generation, split between co-located units as the subtransient
    // initialisation splits it), not its schedule gen.Pg / gen.Qg. The power flow sets a PV unit's Q and the slack
    // unit's P, so the scheduled values put the converter at an operating point the network is not at (case9 bus 2 was
    // studied at its scheduled 6.54 MVAr; case14 bus 1, the slack, at its scheduled P and Q). Vd0 = |V| was already the
    // solved one.
    (double pSolvedMw, double qSolvedMvar) = SolvedGeneration.UnitOutput(m, pf, genIdx);
    double pPu = pSolvedMw / mBase;
    double qPu = qSolvedMvar / mBase;
    var op = ConverterOperatingPoint.Guarded(vm, 0.0, pPu / Math.Max(GridSim.Cli.CliDefaults.OperatingPointVmFloorPu, vm), -qPu / Math.Max(GridSim.Cli.CliDefaults.OperatingPointVmFloorPu, vm), pPu, qPu);

    // Converter model: from a bound asset class when the case binds one, else from CLI flags (CuratedPlaceholder).
    // R217: --converter and --criterion accept only their documented values; a typo used to mean GFL / SISO.
    string conv = (FlagString(a, "--converter") ?? "gfl").ToLowerInvariant() switch
    {
        "gfl" => "gfl",
        "gfm" => "gfm",
        var bad => FailFlag<string>("--converter", bad, "gfl or gfm"),
    };
    var crit = (FlagString(a, "--criterion") ?? "siso").ToLowerInvariant() switch
    {
        "siso" => StabilityCriterion.Siso,
        "mimo" => StabilityCriterion.Mimo,
        var bad => FailFlag<StabilityCriterion>("--criterion", bad, "siso or mimo"),
    };
    // R082 (October 2026): --outer-loop-only selects ImpedanceModelDetail.OuterLoopOnly, which no CLI path could reach:
    // the grid-following PLL is ideal (its gain frozen at 1/Vd0) and the current loop is the fast stand-in roll-off, a
    // first screen when no inner-loop data exist. The inner-loop flags would then be read and ignored, so they are
    // refused with it, and so is the grid-forming model, whose admittance does not use the detail level at all.
    if (outerLoopOnly)
        foreach (string inner in new[] { "--pll-bw", "--pll-damping", "--current-bw" })
            if (a.Contains(inner))
                FailFlag<string>(inner, FlagString(a, inner) ?? "", "no value: --outer-loop-only makes the PLL and current loop ideal, so it takes no inner-loop parameter");
    ImpedanceModelDetail detail = outerLoopOnly ? ImpedanceModelDetail.OuterLoopOnly
        : a.Contains("--current-bw") ? ImpedanceModelDetail.PllCurrentOuter : ImpedanceModelDetail.PllOuter;
    double? pllBw = a.Contains("--pll-bw") ? FlagDouble(a, "--pll-bw", GridSim.Cli.CliDefaults.PlaceholderPllBandwidthHz) : null;
    double? pllZeta = a.Contains("--pll-damping") ? FlagDouble(a, "--pll-damping", GridSim.Cli.CliDefaults.PlaceholderPllDamping) : null;
    // D-DOC-192 (docs-session finding, Ruling R1: Mark delegated 2026-10-04): --current-bw has NO default value. The call
    // used to pass 400.0 as FlagDouble's fallback, but FlagDouble is reached only when the flag is present, and a
    // present flag with no value exits 2, so the 400 was unreachable and suggested a default that never applied. Without
    // the flag the model has no current-loop bandwidth (the PllOuter detail level and its fast stand-in roll-off). The
    // NaN below is never returned for the same reason; it is there only because FlagDouble takes a fallback.
    // The value must also be a finite number above 0: a zero or negative bandwidth used to be passed on as a current-loop
    // corner of 0 or below, which the flag-built model silently replaced with its fast stand-in (while printing
    // "detail PllCurrentOuter") and the asset-class model refused with an unhandled exception. Exit 2 now, before the scan.
    double? ciBw = a.Contains("--current-bw") ? FlagDouble(a, "--current-bw", double.NaN) : null;
    if (ciBw is double ciBwValue && !(ciBwValue > 0.0))
        FailFlag<double>("--current-bw", ciBwValue.ToString(System.Globalization.CultureInfo.InvariantCulture), "a current-loop bandwidth in Hz above 0");
    // N266 (LF5, October 2026; Ruling R1: Mark delegated EE calls 2026-10-04): --pll-bw and --pll-damping had the defect
    // D-DOC-192 fixed for --current-bw. A PLL bandwidth or damping ratio of 0 or below (or NaN / infinite) was passed on:
    // the flag-built grid-following model floored it silently (ImpedancePllParameterFloor) while printing the value as
    // given, the flag-built grid-forming model took --pll-bw as a power-loop bandwidth of 0 or below, and a bound asset
    // class threw an unhandled ArgumentOutOfRangeException. A bandwidth is a positive frequency and a damping ratio of 0 is
    // an undamped (marginal) loop, neither a model parameter; each must be a finite number above 0. Exit 2, before the scan.
    if (pllBw is double pllBwValue && !(double.IsFinite(pllBwValue) && pllBwValue > 0.0))
        FailFlag<double>("--pll-bw", pllBwValue.ToString(System.Globalization.CultureInfo.InvariantCulture), "a finite PLL (or grid-forming power-loop) bandwidth in Hz above 0");
    if (pllZeta is double pllZetaValue && !(double.IsFinite(pllZetaValue) && pllZetaValue > 0.0))
        FailFlag<double>("--pll-damping", pllZetaValue.ToString(System.Globalization.CultureInfo.InvariantCulture), "a finite PLL damping ratio above 0");

    AssetClass? cls = null;
    if (m.AssetDynamics is not null && gen.DynamicsClass is not null && m.AssetDynamics.Bindings.Resolve(gen.DynamicsClass, gen.Type) is string cn && m.AssetDynamics.Library.Contains(cn))
        cls = m.AssetDynamics.Library.Get(cn);

    // R070: refuse a converter flag the selected model cannot honour, instead of parsing it and dropping it.
    //   --pll-damping reaches grid-following models only (flag-built, or as an override of a bound class since
    //   R244 gave FromAssetClass a pllDampingOverride); the grid-forming model has no PLL damping input;
    //   --current-bw's VALUE reaches only grid-following models (the grid-forming factories take no current-loop
    //   bandwidth; the flag used to switch the GFM detail level and silently drop the number);
    //   --pll-bw is not passed to the asset-class grid-forming model (it reads its own power-loop bandwidth).
    if (outerLoopOnly && conv == "gfm")
    {
        Console.Error.WriteLine("error: --outer-loop-only applies to the grid-following model only: the grid-forming admittance does not depend on the detail level, so the flag would change nothing.");
        Environment.Exit(2);
    }
    if (pllZeta is not null && conv == "gfm")
        FailFlag<double>("--pll-damping", pllZeta.Value.ToString(System.Globalization.CultureInfo.InvariantCulture),
            "no value: the grid-forming model does not take a PLL damping ratio");
    if (ciBw is not null && conv == "gfm")
        FailFlag<double>("--current-bw", ciBw.Value.ToString(System.Globalization.CultureInfo.InvariantCulture),
            "no value: the grid-forming model does not take a current-loop bandwidth");
    if (pllBw is not null && conv == "gfm" && cls is not null)
        FailFlag<double>("--pll-bw", pllBw.Value.ToString(System.Globalization.CultureInfo.InvariantCulture),
            $"no value: the grid-forming asset class '{cls.Name}' sets its own power-loop bandwidth");

    IConverterImpedanceModel model = conv == "gfm"
        ? (cls is not null
            // R140 (stream B5): the grid-forming power loop is per unit on the converter's rating, the same mBase the
            // operating point above is on. The flag-built model's power-loop bandwidth falls back to the grid-forming
            // placeholder (ConverterDefaults.GfmPowerLoopBandwidthHz, 5 Hz), not the grid-following PLL placeholder: they
            // were both 5 Hz, so nothing moves, and R138 moved the PLL placeholder on its own.
            ? GridFormingImpedance.FromAssetClass(cls, bus, m.FrequencyHz, op, detail, mBase, virtualReactancePuOverride: null, powerLoopBandwidthHzOverride: null)
            : GridFormingImpedance.FromParameters(bus, m.FrequencyHz, op, detail, ProvenanceTag.CuratedPlaceholder, GridSim.Cli.CliDefaults.PlaceholderGfmVirtualReactancePu, pllBw ?? GridSim.Core.Dynamics.ConverterDefaults.GfmPowerLoopBandwidthHz, 0.0, 0.0, mBase))
        : (cls is not null
            ? GridFollowingImpedance.FromAssetClass(cls, bus, op, detail, pllBw, ciBw, pllDampingOverride: pllZeta)
            : GridFollowingImpedance.FromParameters(bus, op, detail, ProvenanceTag.CuratedPlaceholder, pllBw ?? GridSim.Cli.CliDefaults.PlaceholderPllBandwidthHz, pllZeta ?? GridSim.Cli.CliDefaults.PlaceholderPllDamping, ciBw is double cb ? 2.0 * Math.PI * cb : 0.0));

    // N026 (R245 follow-up): --grid selects the grid impedance. 'canonical' (default) is the exact analytic
    // single-inverter-vs-Thevenin model swept over SCR; 'real' is the network's own harmonic driving-point impedance
    // at the converter bus (the path R245 made fail loud instead of silently falling back). The SCR sweep belongs to
    // the canonical model only, so its flags are refused with --grid real.
    bool realGrid = (FlagString(a, "--grid") ?? "canonical").ToLowerInvariant() switch
    {
        "canonical" => false,
        "real" => true,
        var bad => FailFlag<bool>("--grid", bad, "canonical or real"),
    };
    if (realGrid)
        foreach (string scrFlag in new[] { "--scr", "--scr-min", "--scr-max", "--scr-steps" })
            if (a.Contains(scrFlag))
                FailFlag<string>(scrFlag, FlagString(a, scrFlag) ?? "", "no value: the SCR sweep applies to --grid canonical only");

    var opt = new ImpedanceStabilityOptions
    {
        FMinHz = FlagDouble(a, "--fmin", 0.1),
        FMaxHz = FlagDouble(a, "--fmax", 250.0),
        PointsPerDecade = FlagInt(a, "--ppd", 50),
        F0Hz = m.FrequencyHz,
        Criterion = crit,
        UseCanonicalThevenin = !realGrid,
        Scr = FlagDouble(a, "--scr", 3.0),
        PRatedPu = Math.Max(1e-3, mBase / m.BaseMva),
        ScrMin = FlagDouble(a, "--scr-min", 1.0),
        ScrMax = FlagDouble(a, "--scr-max", 10.0),
        ScrSteps = FlagInt(a, "--scr-steps", 37),
    };
    // GR-198: the scan range and the SCR sweep must be physical; fmin above fmax, a zero or negative value used to reach
    // the scan, whose ArgumentException is caught only on the real-grid path.
    string Inv(double v) => v.ToString("R", System.Globalization.CultureInfo.InvariantCulture);
    if (!(opt.FMinHz > 0)) FailFlag<double>("--fmin", Inv(opt.FMinHz), "a frequency above 0 Hz");
    if (!(opt.FMaxHz > opt.FMinHz)) FailFlag<double>("--fmax", Inv(opt.FMaxHz), $"a frequency above --fmin ({Inv(opt.FMinHz)} Hz)");
    if (opt.PointsPerDecade < 1) FailFlag<int>("--ppd", opt.PointsPerDecade.ToString(System.Globalization.CultureInfo.InvariantCulture), "1 or more points per decade");
    if (!(opt.Scr > 0)) FailFlag<double>("--scr", Inv(opt.Scr), "a short-circuit ratio above 0");
    if (!(opt.ScrMin > 0)) FailFlag<double>("--scr-min", Inv(opt.ScrMin), "a short-circuit ratio above 0");
    if (!(opt.ScrMax >= opt.ScrMin)) FailFlag<double>("--scr-max", Inv(opt.ScrMax), $"a short-circuit ratio no lower than --scr-min ({Inv(opt.ScrMin)})");
    if (opt.ScrSteps < 1) FailFlag<int>("--scr-steps", opt.ScrSteps.ToString(System.Globalization.CultureInfo.InvariantCulture), "1 or more steps");

    ImpedanceStabilityResult r;
    // D-DOC-140: the export's meta.elapsedMs is the wall time of the scan (frequency sweep, Nyquist, SCR sweep), measured
    // here; it used to be a hard-coded 0.
    var impedanceClock = System.Diagnostics.Stopwatch.StartNew();
    try { r = ImpedanceStabilityScan.Run(opt, model, realGrid ? m : null); impedanceClock.Stop(); }
    catch (Exception ex) when (realGrid && ex is InvalidOperationException or ArgumentException)
    {
        // The real path fails loud (R245) on a singular driving-point solve or a reporting point on the dq DC arm.
        Console.Error.WriteLine($"impedance-stability: real-network grid impedance failed: {ex.Message}");
        Environment.ExitCode = 3;
        return;
    }

    // Workstream-C modal cross-check: the independent RHP eigenvalue count on the case's small-signal model
    // (with inverter states when the case binds them, else the swing-only core - a corroboration where the two
    // model structures align; the Routh oracle in ImpedanceModalAgreementTests is the decisive check).
    int? modalRhp = null;
    // D-DOC-134 (docs-session finding, Ruling R1: Mark delegated 2026-10-04): the cross-check's swing model used to be
    // built with no machine data at all, so every case (case9 included) ran on the synthetic X'd (SyntheticXdpPu) and zero
    // damping, and the output did not say so. Now the case's own X'd is used where GridSim has it (the WSCC-9
    // Anderson-Fouad values for the built-in case9, as stability / modal use them; any unit not in that table keeps the
    // synthetic value), and the cross-check line names the X'd source and the damping, which stays zero because no
    // bundled case carries machine damping data. The Nyquist verdict and the SCR sweep do not use this model.
    double[]? modalXdp = null;
    bool modalXdpSynthetic = true;
    if (impWscc9) modalXdp = Wscc9XdpByGenerator(m, out modalXdpSynthetic);
    string modalBasis = modalXdpSynthetic
        ? $"swing model: X'd synthetic {GridSim.Cli.CliDefaults.SyntheticXdpPu:F2} pu, zero damping (no damping data); INDICATIVE"
        : "swing model: X'd Anderson-Fouad, zero damping (no damping data)";
    try
    {
        bool hasInv = m.AssetDynamics is not null && m.Generators.Any(g =>
            g.DynamicsClass is not null && m.AssetDynamics.Bindings.Resolve(g.DynamicsClass, g.Type) is string rc &&
            m.AssetDynamics.Library.Contains(rc) &&
            m.AssetDynamics.Library.Get(rc).Kind is AssetKind.GridFollowingInverter or AssetKind.GridFormingInverter);
        SmallSignalModel ssm = hasInv
            ? SmallSignalAssembler.FromSolvedCaseWithInverters(m, pf, modalXdp)
            : SmallSignalAssembler.FromSolvedCase(m, pf, modalXdp);
        modalRhp = ModalAnalysis.Analyze(ssm).RhpEigenvalueCount;
        r = r.WithModalCrossCheck(modalRhp.Value);
    }
    catch (Exception ex)
    {
        // The cross-check is supplementary (the Nyquist verdict stands on its own), but its absence is reported
        // with the reason rather than swallowed silently (R009 follow-up, 1.95.038).
        Console.Error.WriteLine($"impedance-stability: modal cross-check unavailable on this case: {ex.Message}");
    }

    NyquistVerdict v = r.Nyquist;
    Console.WriteLine($"impedance-stability: case {m.Name}, inverter bus {bus}, mode {model.Kind}, detail {model.Detail}, criterion {r.Criterion}");
    Console.WriteLine($"  operating point : Vd0={op.Vd0Pu:F4} pu{(op.Vd0WasClamped ? " (CLAMPED - weak/depressed)" : "")}, Id0={op.Id0Pu:F4}, Iq0={op.Iq0Pu:F4} pu");
    Console.WriteLine($"  nyquist         : encirclements {v.Encirclements}  unstable-modes {v.UnstableModeCount}  " +
                      $"GM {(double.IsInfinity(v.GainMarginDb) ? "inf" : v.GainMarginDb.ToString("F1"))} dB  " +
                      $"PM {(double.IsInfinity(v.PhaseMarginDeg) ? "inf" : v.PhaseMarginDeg.ToString("F1"))} deg  " +
                      $"minDist {v.MinDistToMinusOne:F3}  -> {(v.Stable ? "STABLE" : "UNSTABLE")}");
    // GR-096: the encirclement count unwraps the smallest-angle phase step between grid points; a step above a
    // quarter turn means the grid may have skipped part of a sharp resonance, so the count (and the verdict) is not
    // trusted. Said loudly beside the verdict; the verdict and exit code are those of the count, as before.
    if (v.PhaseStepGuardTripped)
        Console.Error.WriteLine(
            $"WARNING: impedance-stability: the Nyquist contour turns {v.MaxPhaseStepRad * 180.0 / Math.PI:F1} deg between two " +
            $"grid points (trusted up to {MinorLoopNyquist.MaxTrustedPhaseStepRad * 180.0 / Math.PI:F0} deg), so the encirclement " +
            "count may be wrong; rerun with a larger --ppd (or a band that resolves the resonance).");
    // D-DOC-131 (docs-session finding, Ruling R1: Mark delegated 2026-10-04): the boundary line used to say "stable
    // across the swept SCR range" whenever no unstable-to-stable crossing was found, which is also the case when EVERY
    // swept SCR is unstable (case9 --outer-loop-only: the Nyquist verdict above reads UNSTABLE) and when no sweep ran at
    // all (--grid real, where the SCR flags are refused). It now says what the sweep found, from the sweep itself:
    //   * no samples (--grid real, or fewer than 2 steps): no sweep ran;
    //   * a crossing: the critical SCR, as before (unchanged text);
    //   * every sample stable: the old "stable across the swept SCR range" (unchanged text);
    //   * every sample unstable: unstable at every swept SCR, so the boundary (if any) is above the range;
    //   * a mix with no unstable-to-stable crossing (unstable only at the HIGH end): said plainly, with the count.
    // The sweep, the critical SCR and the export are unchanged; only this line's wording is.
    int scrSamples = r.ScrSweep.Count;
    int scrUnstable = r.ScrSweep.Count(s => !s.Stable);
    if (scrSamples == 0)
        Console.WriteLine(realGrid
            ? "  SCR boundary    : n/a (--grid real: the network's own impedance is used, no SCR sweep runs)"
            : "  SCR boundary    : n/a (no SCR sweep ran: --scr-steps below 2)");
    else if (r.BoundaryFound)
        Console.WriteLine($"  SCR boundary    : critical SCR {r.CriticalScr:F2}  (weak-grid instability below this)");
    else if (scrUnstable == 0)
        Console.WriteLine($"  SCR boundary    : none in [{opt.ScrMin:F1}, {opt.ScrMax:F1}]  (stable across the swept SCR range)");
    else if (scrUnstable == scrSamples)
        Console.WriteLine($"  SCR boundary    : none in [{opt.ScrMin:F1}, {opt.ScrMax:F1}]  (UNSTABLE at every swept SCR: any boundary lies above {opt.ScrMax:F1})");
    else
        Console.WriteLine($"  SCR boundary    : none in [{opt.ScrMin:F1}, {opt.ScrMax:F1}]  (no unstable-to-stable crossing; {scrUnstable} of {scrSamples} swept SCRs UNSTABLE)");
    Console.WriteLine(modalRhp is int mr
        ? $"  cross-check (C) : RHP eigenvalues {mr}  agreement {(r.AgreesWithModal == true ? "OK" : "differs (structures differ; Routh oracle is decisive - see tests)")}  [{modalBasis}]"
        : "  cross-check (C) : n/a on this case (no modal model); decisive Routh check in ImpedanceModalAgreementTests");
    Console.WriteLine($"  provenance      : {model.Provenance}{(model.Provenance == ProvenanceTag.CuratedPlaceholder ? " [VERIFY] pll/current-loop params literature-typical" : "")}");

    if (export)
    {
        var meta = new SolveExportMeta(m.Name, "impedance-stability", RunInfo.GitCommit, DateTime.UtcNow.ToString("o"),
            impedanceClock.Elapsed.TotalMilliseconds, Environment.MachineName);   // D-DOC-140: was a hard-coded 0
        string path = exportPath ?? DefaultResultsPath("impedance-stability-export.json");   // N079: was in the current directory
        ImpedanceStabilityExport.WriteJson(CliFiles.Output(path, "impedance-stability export"), m, r, meta);
        Console.WriteLine($"  export -> {Path.GetFullPath(path)}");
    }
}

void RunEstimate(List<string> a, string root)
{
    // Gather the space-separated --phaseangle tuples and REMOVE them from the arg list before PositionalArg
    // runs, so the extra BUS:ANGLE:UTC:FREQ tokens are not mistaken for the positional case id.
    string? phaseAngleSpec = GatherContiguousValues(a, "--phaseangle");

    // The boolean (value-less) flags of this verb. Positionals assumes every remaining --flag takes the next token as
    // its value, so the booleans are left out of the list it scans: "estimate --synth case14" used to treat case14 as
    // the value of --synth and print the usage banner.
    var estimateBooleans = new HashSet<string>(StringComparer.Ordinal)
    {
        "--synth", "--no-bad-data", "--warm-start", "--lean", "--trace", "--backfill-removals", "--hti", "--hti-correct", "--fdia-screen",
        "--export-solve",
    };
    string? caseName = PositionalArg(a.Where(t => !estimateBooleans.Contains(t)).ToList());
    bool synth = a.Contains("--synth");
    string? measurementsPath = FlagString(a, "--measurements");
    if (caseName is null || (!synth && measurementsPath is null))
    {
        // The full flag list (docs-programme finding: --method, --prior, --warm-start, --backfill-removals, --lean,
        // --trace, --export-solve and --phaseangle-from-gda were missing). Keep in step with ch. 19 "estimate".
        Console.Error.WriteLine("usage: gridsim estimate <case> (--measurements <m.json> | --synth [--seed N] [--noise S]");
        Console.Error.WriteLine("                        [--coverage-vm F] [--coverage-inj F] [--coverage-flow F])");
        Console.Error.WriteLine("                        [--method wls|huber|lav|lav-lp|schweppe-gm|qr|constrained|feasible]");
        Console.Error.WriteLine("                        [--prior flat|solve] [--warm-start] [--no-bad-data] [--backfill-removals]");
        Console.Error.WriteLine("                        [--hti [--hti-correct]] [--fdia-screen] [--lean] [--trace] [--export-solve]");
        Console.Error.WriteLine("                        [--tol 1e-8] [--max-iter N] [--out <dir>]");
        Console.Error.WriteLine("                        [--phaseangle BUS:ANGLE:UTC:FREQ ...] [--phaseangle-ref auto|referenced|raw]");
        Console.Error.WriteLine("                        [--phaseangle-sigma DEG] [--phaseangle-at UTC] [--phaseangle-from-gda <gda-root>]");
        Console.Error.WriteLine("Estimates the grid state from measurements (gridsim-measurements/1). --synth samples a");
        Console.Error.WriteLine("deterministic noisy set from the case's own solved truth and scores the estimate against it.");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }
    // --synth builds its own measurement set, so a --measurements file given with it used to be ignored without a
    // word: the run estimated from synthetic data while the caller believed it used their telemetry. Refuse it.
    if (synth && measurementsPath is not null)
    {
        Console.Error.WriteLine("error: estimate: give either --measurements <file> or --synth, not both (--synth would ignore the file).");
        Environment.ExitCode = 2;
        return;
    }

    // R075: the case and the measurement file, hashed before anything reads them, so even a run that fails to load
    // them records which inputs it was given (a bundled case name is recorded as case-id, the hash of the name, never
    // as a content hash; a measurement file that cannot be read fails here, loud, exit 1).
    try
    {
        auditRun?.AddInput(GridSim.Core.Diagnostics.AuditRunRecorder.InputForArgument("case", caseName));
        if (!synth) auditRun?.AddInput(GridSim.Core.Diagnostics.AuditInput.OfFile("measurements", measurementsPath!));
    }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
    {
        Console.Error.WriteLine($"error reading an input to record in the audit log: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }

    GridModel model;
    try
    {
        // A GDA/JSON case directory (has system.json) loads via the same loader the app and
        // crossval use - so gb-spine/gb-full materialisations can be estimated on directly.
        bool isCaseDir = Directory.Exists(caseName) && File.Exists(Path.Combine(caseName, "system.json"));
        model = isCaseDir ? Gated.Dir(caseName) : LoadNamed(caseName, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{caseName}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    string caseLabel = Path.GetFileName(caseName.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"estimate-{caseLabel}");
    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file

    MeasurementSet set;
    PowerFlowResult? truth = null;
    try
    {
        if (synth)
        {
            IPowerFlowSolver raw = backend.Solver(model);
            truth = raw.Solve(model, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
            if (!truth.Converged)
            {
                Console.Error.WriteLine($"error: could not solve '{caseName}' for ground truth ({truth.Status}).");
                Environment.ExitCode = 1;
                return;
            }
            var sopt = new SyntheticMeasurementOptions
            {
                Seed = FlagInt(a, "--seed", 20260713),
                NoiseScale = FlagDouble(a, "--noise", 1.0),
                VmCoverage = FlagDouble(a, "--coverage-vm", 1.0),
                InjCoverage = FlagDouble(a, "--coverage-inj", 1.0),
                FlowCoverage = FlagDouble(a, "--coverage-flow", 1.0),
            };
            set = SyntheticMeasurements.Sample(model, truth, sopt);
            // Persist the sampled set so the crossval sidecar (and any re-run) consumes the identical input.
            set.Save(CliFiles.Output(Path.Combine(outDir, "measurements.json"), "measurements.json"));
            auditRun?.AddInput(GridSim.Core.Diagnostics.AuditInput.OfFile("synthetic-measurements", Path.Combine(outDir, "measurements.json")));
        }
        else
        {
            set = MeasurementSet.Load(measurementsPath!);
        }
    }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.HorizonViolation, $"estimate input refused: {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) when (ex is not OutputRefusedException)   // D-DOC-072: a refused --synth save is exit 2 (the process-wide handler), not a load error
    { Console.Error.WriteLine($"error loading measurements: {ex.Message}"); Environment.ExitCode = 1; return; }

    // Phase-angle override: turn manually-supplied (or GDA-referenced) per-bus voltage angles into
    // slack-referenced VaDeg measurement rows and merge them in - BEFORE the prior/warm-start so the injected
    // angles also condition the measured-injection prior. Genuine per-bus angle differences directly observe
    // the estimator's weakest directions; a common-mode system angle cancels on re-referencing (used correctly
    // it is only a reference frame / projection frequency - see --phaseangle-from-gda).
    // --prior and the raw solver are resolved before the phase-angle feed because an AutoReference feed whose datum
    // is not the slack needs the datum's PRESENT-STATE angle as its anchor (R028 / N024), which comes from the
    // solved prior (or the --warm-start base solve). Each solve is done once and reused below.
    string prior = (FlagString(a, "--prior") ?? "flat").Trim().ToLowerInvariant();
    if (prior is not ("flat" or "solve"))
        FailFlag<int>("--prior", prior, "'flat' or 'solve'");
    IPowerFlowSolver rawSolver = backend.Solver(model);
    PowerFlowResult? preSolvedPrior = null;   // MeasuredInjectionPrior.Solve, if the anchor needed it
    PowerFlowResult? preSolvedBase = null;    // the --warm-start base solve, if the anchor needed it

    if (phaseAngleSpec is not null)
    {
        if (phaseAngleSpec.Length == 0)
            FailFlag<int>("--phaseangle", "", "one or more BUS:ANGLE_DEG:UTC:FREQ_HZ tuples");

        PhaseAngleReference mode = (FlagString(a, "--phaseangle-ref") ?? "auto").Trim().ToLowerInvariant() switch
        {
            "auto" => PhaseAngleReference.AutoReference,
            "referenced" => PhaseAngleReference.AlreadyReferenced,
            "raw" => PhaseAngleReference.Raw,
            var s => FailFlag<PhaseAngleReference>("--phaseangle-ref", s, "'auto', 'referenced', or 'raw'"),
        };
        double sigmaDeg = FlagDouble(a, "--phaseangle-sigma", 2.0);

        DateTime? target = set.TakenUtc;   // align to the set's instant when it is dated
        string? atS = FlagString(a, "--phaseangle-at");
        if (atS is not null)
        {
            // D-DOC-063: strict ISO 8601 (invariant culture); 01/02/2100 and other ambiguous shapes are refused.
            if (!GridSim.Core.Diagnostics.UtcTime.TryParseIso8601(atS, out DateTime atv))
                FailFlag<int>("--phaseangle-at", atS, "an ISO 8601 UTC instant (for example 2024-03-01T12:00:00Z)");
            target = DateTime.SpecifyKind(atv, DateTimeKind.Utc);
        }

        // Optional GDA reference frame: read the SYSTEM COI angle + true frequency at the target instant from
        // PHASEANGLE_INFERED. This is the correct use of the common-mode system angle - it de-rotates an
        // absolute (inertial-frame) feed in 'referenced' mode; under 'auto' the datum already removes it.
        double commonModeDeg = 0.0;
        string? gdaRoot = FlagString(a, "--phaseangle-from-gda");
        if (gdaRoot is not null)
        {
            if (target is not DateTime tref)
            {
                Console.Error.WriteLine("error: --phaseangle-from-gda needs a target instant (--phaseangle-at or a dated --measurements set).");
                Environment.ExitCode = 2;
                return;
            }
            try
            {
                PhaseAngleSample s = PhaseAngleInferedReader.ReadWeek(gdaRoot, tref).At(tref);
                commonModeDeg = s.PhaseDeg;
                Console.WriteLine($"  gda reference: theta_sys={s.PhaseDeg:0.###} deg, f={s.FreqHz:0.####} Hz, rocof={s.RocofHzPerS:0.####} Hz/s at {s.Utc:u}");
            }
            catch (Exception ex) { Console.Error.WriteLine($"error: --phaseangle-from-gda: {ex.Message}"); Environment.ExitCode = 1; return; }
        }

        try
        {
            IReadOnlyList<PhaseAngleObs> obs = PhaseAngleFeed.Parse(phaseAngleSpec);

            // N024: with no slack observation the datum is the first observed bus, and its anchor must be the
            // datum's present-state angle (the solved prior, else the --warm-start base solve). The prior solve uses
            // only the injection rows, so solving it before the angle rows are appended gives the same result.
            double? anchorDeg = null;
            int? slackId = model.Buses.FirstOrDefault(b => b.Type == BusType.Slack)?.Id;
            if (mode == PhaseAngleReference.AutoReference && obs.Count > 0 && !obs.Any(o => o.Bus == slackId))
            {
                int datum = obs[0].Bus;
                PowerFlowResult? src = null;
                if (prior == "solve")
                {
                    preSolvedPrior = MeasuredInjectionPrior.Solve(model, set, rawSolver);
                    if (preSolvedPrior.Converged) src = preSolvedPrior;
                }
                else if (a.Contains("--warm-start"))
                {
                    preSolvedBase = rawSolver.Solve(model, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
                    if (preSolvedBase.Converged) src = preSolvedBase;
                }
                if (src is null)
                {
                    Console.Error.WriteLine($"error: --phaseangle-ref auto: no observation at the slack bus {slackId}, so the datum bus {datum} " +
                        "needs its present-state angle as an anchor. Add --prior solve (or --warm-start), or include the slack bus " +
                        "among the observations.");
                    Environment.ExitCode = 2;
                    return;
                }
                int di = -1;
                for (int i = 0; i < src.BusIds.Count; i++) if (src.BusIds[i] == datum) { di = i; break; }
                if (di < 0) { Console.Error.WriteLine($"error: --phaseangle datum bus {datum} is not in the model."); Environment.ExitCode = 2; return; }
                anchorDeg = src.VaDeg[di];
                Console.WriteLine($"  phaseangle: datum bus {datum} anchored at {anchorDeg:0.######} deg from the {(prior == "solve" ? "solved prior" : "warm-start base solve")}");
            }
            var opt = new PhaseAngleOptions { Mode = mode, SigmaDeg = sigmaDeg, TargetUtc = target, CommonModeDeg = commonModeDeg, DatumAnchorDeg = anchorDeg };
            (IReadOnlyList<Measurement> rows, DateTime tgt) = PhaseAngleFeed.ToMeasurements(model, obs, opt);
            // Dated angles obey the same historical-horizon invariant as every other dated input.
            ForwardInferenceGuard.RejectFuture(tgt, null, "phase-angle override");
            set = set with { Measurements = set.Measurements.Concat(rows).ToList(), TakenUtc = set.TakenUtc ?? tgt };
            Console.WriteLine($"  phaseangle: injected {rows.Count} VaDeg row(s) at {tgt:u} (mode {mode}, sigma {sigmaDeg:0.###} deg)");
        }
        catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.HorizonViolation, $"estimate input refused: {ex.Message}"); Environment.ExitCode = 2; return; }
        catch (Exception ex) { Console.Error.WriteLine($"error: --phaseangle: {ex.Message}"); Environment.ExitCode = 2; return; }
    }

    // --prior selects where the operating-point PRIOR comes from (the triad: GDA supplies
    // the measured injections, GridSim SOLVES them, the estimator fuses solve + telemetry):
    //   flat  (default) - keep the set's own voltage-schedule rows as-is.
    //   solve           - solve the measured-injection power flow built FROM the set; the
    //                     solution replaces the flat voltage-schedule values (tighter sigma,
    //                     source=prior-solved) AND becomes the warm start.
    PowerFlowResult? warmStart = null;
    if (prior == "solve")
    {
        PowerFlowResult conditioned = preSolvedPrior ?? MeasuredInjectionPrior.Solve(model, set, rawSolver);
        if (conditioned.Converged)
        {
            // Count the rows the prior actually replaced (the set's pseudo voltage-schedule rows, now tagged
            // prior-solved). A set with no such rows (any --synth set, most telemetry) has nothing replaced; the
            // message used to claim a replacement regardless. The warm start is used either way.
            int scheduleRowsBefore = set.Measurements.Count(m => m.Source == MeasuredInjectionPrior.SolvedPriorSource);
            set = MeasuredInjectionPrior.ApplyVoltagePrior(set, conditioned);
            int replaced = set.Measurements.Count(m => m.Source == MeasuredInjectionPrior.SolvedPriorSource) - scheduleRowsBefore;
            warmStart = conditioned;
            Console.WriteLine($"  prior: measured-injection solve converged ({conditioned.Iterations} iters); " +
                              (replaced > 0
                                  ? $"{replaced} voltage-schedule row(s) replaced with the solved profile; used as the warm start"
                                  : "the set has no voltage-schedule rows, so nothing was replaced; used as the warm start"));
        }
        else
        {
            Console.Error.WriteLine($"warning: measured-injection prior solve {conditioned.Status}; " +
                                    $"falling back to the flat schedule");
        }
    }
    // A solved prior outside the voltage band is a warning sign the chi-square test cannot see (October 2026
    // investigation of a GDA re-run whose SP02 estimate passed chi-square at vm_max 1.267891 pu). The prior is a power
    // flow of the SAME injection rows, and its voltages enter as prior-solved VmPu rows (sigma 0.02), so the estimate is
    // held near a state that agrees with those injections by construction: the rows are not independent evidence, and
    // a voltage-level error in the prior passes the test. The run is not changed; the user is told (stderr).
    if (prior == "solve" && warmStart is not null && warmStart.Vm.Length > 0)
    {
        var band = new FeasibilityConstraints();
        double priorMax = warmStart.Vm.Max(), priorMin = warmStart.Vm.Min();
        if (priorMax > band.VmMax || priorMin < band.VmMin)
            Console.Error.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"warning: the measured-injection prior solve puts Vm at {priorMin:F4} to {priorMax:F4} pu, outside the {band.VmMin:F2} to {band.VmMax:F2} pu band. Its voltages enter as prior-solved rows, so a chi-square PASS cannot vouch for the voltage level: check the injection rows (missing interconnector or unallocated generation), or run with --prior flat."));
    }
    if (warmStart is null && a.Contains("--warm-start"))
    {
        // Warm from the case's own solved operating point (standard EMS practice: the
        // estimator iterates from the last known state, not from flat). Falls back to
        // flat start with a warning if the base case will not solve.
        PowerFlowResult baseSolve = preSolvedBase ?? rawSolver.Solve(model, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
        if (baseSolve.Converged) warmStart = baseSolve;
        else Console.Error.WriteLine($"warning: base-case solve {baseSolve.Status}; estimating from flat start");
    }

    // --method selects the estimation method behind the IWlsStep seam (the project's
    // --inertia-model= convention). Every EstimationMethod member is selectable (R062: schweppe-gm and qr were
    // API-only); an unknown value fails loud rather than silently running WLS.
    EstimationMethod method = (FlagString(a, "--method") ?? "wls").Trim().ToLowerInvariant() switch
    {
        "wls" => EstimationMethod.Wls,
        "huber" => EstimationMethod.Huber,
        // N356 (CF6, ruled by main under Ruling R1): `lav` is the exact LAV (linear programming, CF5's lav-lp);
        // `lav-lp` stays an accepted alias (the Core normalises LavLp to Lav: identical output); the IRLS form that
        // `lav` used to run is `lav-irls`, marked approximate in its output.
        "lav" => EstimationMethod.Lav,
        "lav-lp" => EstimationMethod.LavLp,   // N331 (CF5): LAV solved exactly as a linear program
        "lav-irls" => EstimationMethod.LavIrls,   // N356 (CF6): the approximate IRLS LAV, the pre-N356 `lav`
        "schweppe-gm" or "gm" => EstimationMethod.SchweppeGm,
        "qr" => EstimationMethod.Qr,
        "constrained" => EstimationMethod.Constrained,
        "feasible" or "constrained-physics" => EstimationMethod.Feasible,
        var other => FailFlag<EstimationMethod>("--method", other, "'wls', 'huber', 'lav', 'lav-lp', 'lav-irls', 'schweppe-gm', 'qr', 'constrained' or 'feasible'"),
    };

    var eopt = new EstimationOptions
    {
        Tolerance = FlagDouble(a, "--tol", 1e-8),
        MaxIterations = FlagInt(a, "--max-iter", 30),
        DetectBadData = !a.Contains("--no-bad-data"),
        WarmStart = warmStart,
        Method = method,
        // --lean: skip the m residual-covariance solves when chi-square already PASSED
        // (normalized residuals become NaN diagnostics; removal behaviour unchanged) -
        // the backfill throughput switch.
        LeanResiduals = a.Contains("--lean"),
        // --trace: capture the per-iteration convergence path into the export.
        Trace = a.Contains("--trace") ? new EstimationTrace() : null,
        // --backfill-removals: observability restoration (A-6) - a removed measurement is
        // replaced by a loose prior-evaluated pseudo (source="removal-backfill-prior") so
        // removal in a weakly-redundant region cannot let the state run away from the prior.
        BackfillRemovedFromPrior = a.Contains("--backfill-removals"),
    };

    // R062: --hti swaps the bad-data METHOD from sequential largest-normalised-residual removal to
    // Hypothesis-Testing Identification (HtiBadDataEstimation). --fdia-screen adds the residual-cloaked false-data-
    // injection screen (FdiaScreen) on the final estimate. Both are opt-in; without them nothing below changes.
    // Combinations that cannot mean anything are refused up front (exit 2), never silently ignored.
    bool useHti = a.Contains("--hti");
    // N061: --hti-correct makes HTI correct each identified measurement in place (z - e^, the row kept) and re-verify,
    // removing only a row whose correction did not clear it. It qualifies --hti, so alone it is a usage error.
    bool htiCorrect = a.Contains("--hti-correct");
    if (htiCorrect && !useHti)
    {
        Console.Error.WriteLine("error: --hti-correct chooses what --hti does with the bad data it identifies, so it needs --hti.");
        Environment.ExitCode = 2;
        return;
    }
    bool fdiaScreen = a.Contains("--fdia-screen");
    // GR-531: a backfill is evaluated at the start state, which without --prior solve or --warm-start is the flat start.
    if (eopt.BackfillRemovedFromPrior && warmStart is null)
    {
        Console.Error.WriteLine("error: --backfill-removals evaluates each removed row at the prior, and with neither --prior solve nor --warm-start the start is the flat start, not a prior; add one of them.");
        Environment.ExitCode = 2;
        return;
    }
    if (useHti && !eopt.DetectBadData)
    {
        Console.Error.WriteLine("error: --hti selects the bad-data method, so it cannot be combined with --no-bad-data.");
        Environment.ExitCode = 2;
        return;
    }
    if (fdiaScreen && !eopt.DetectBadData)
    {
        Console.Error.WriteLine("error: --fdia-screen needs the chi-square bad-data test (it screens measurement-consistent estimates), so it cannot be combined with --no-bad-data.");
        Environment.ExitCode = 2;
        return;
    }

    string desc = $"estimate  case={caseLabel}  measurements={set.Measurements.Count}  source={(synth ? "synthetic" : measurementsPath)}";
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    EstimationResult est;
    HtiEstimationResult? hti = null;
    // D-DOC-140: the export's meta.elapsedMs is the wall time of the estimate itself (HTI included), measured here; it
    // used to be a hard-coded 0.
    var estimateClock = System.Diagnostics.Stopwatch.StartNew();
    try
    {
        if (useHti)
        {
            hti = htiCorrect
                ? HtiBadDataEstimation.Estimate(new WlsStateEstimator(), model, set, eopt, action: HtiAction.CorrectThenReverify)
                : HtiBadDataEstimation.Estimate(new WlsStateEstimator(), model, set, eopt);
            est = hti.Estimate;
        }
        else
        {
            est = new WlsStateEstimator().Estimate(model, set, eopt);
        }
    }
    catch (InvalidDataException ex) { Console.Error.WriteLine($"invalid measurement set: {ex.Message}"); Environment.ExitCode = 1; return; }
    catch (NotSupportedException ex) when (useHti)
    {
        // HTI refuses the robust methods, prior backfill and systems above its dense limit (fail loud, usage error).
        Console.Error.WriteLine($"error: --hti: {ex.Message}");
        Environment.ExitCode = 2;
        return;
    }
    catch (NotSupportedException ex)
    {
        // Docs-programme finding: --method constrained, feasible and qr are dense only and throw above
        // DenseEstimationLimits.DenseMethodMaxBuses (3,000 buses). That escaped as an unhandled exception (stack trace,
        // exit -532462766). It is a request the tool cannot honour on this case: a usage error, exit 2, with the reason.
        Console.Error.WriteLine($"error: estimate: {ex.Message}");
        Environment.ExitCode = 2;
        return;
    }
    catch (InvalidOperationException ex) when (useHti)
    {
        // Docs-programme finding: HTI inverts the covariance block of the suspect measurements; on a low-redundancy
        // set that block can be singular (the suspects are not jointly identifiable), and DseLinAlg.Invert threw an
        // unhandled "singular matrix in DSE covariance inverse". That is a failed bad-data identification on this
        // set, not a crash: report it and exit 3 (validation failure), as an estimate that cannot be completed does.
        Console.Error.WriteLine($"error: --hti could not identify the bad data on this set: {ex.Message}");
        Console.Error.WriteLine("       the suspect measurements are not jointly identifiable (too little redundancy around them); " +
            "run without --hti for largest-normalised-residual removal, or add measurements.");
        Environment.ExitCode = 3;
        return;
    }

    estimateClock.Stop();
    string host = $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}";
    var meta = new SolveExportMeta(caseLabel, RunInfo.Backend, RunInfo.GitCommit, DateTime.UtcNow.ToString("o"),
        estimateClock.Elapsed.TotalMilliseconds, host);   // D-DOC-140
    EstimateExport.WriteJson(CliFiles.Output(Path.Combine(outDir, "estimate-export.json"), "estimate-export.json"), model, set, est, meta, eopt.Trace);

    // --export-solve: additionally project the estimate into the solved-state shape
    // (injections/losses/flows at x^) as a gridsim-solve-export/1 document, so the
    // presolved-replay/bridge plumbing can consume estimated states unchanged - the
    // feed the Derived/estimated_state lake product is built from.
    if (a.Contains("--export-solve") && est.Converged)
    {
        PowerFlowResult projected = est.ToPowerFlowResult(model);
        // D-DOC-040: the physics block is the estimate's own audit (the same one estimate-export.json carries), not
        // the case-file dispatch audit a solve gets.
        // D-DOC-071: the solve block names the estimator, its status and its state update (maxStateUpdate); there was no
        // power-flow solve, so no maxMismatch is written (it used to hold the state update under that name).
        SolveExport.WriteJson(CliFiles.Output(Path.Combine(outDir, "estimated-solve-export.json"), "estimated-solve-export.json"),
            model, projected, new GridSim.Core.Diagnostics.SolveTrace(), meta, physics: EstimateExport.PhysicsReport(model, est),
            estimate: new SolveExportEstimate(est.Status.ToString(), est.MaxStateUpdate, method.ToString()));
    }

    using (var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "residuals.csv"), "residuals.csv")))
    {
        foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
        csv.WriteLine("kind,location,value,sigma,predicted,residual,normalized_residual,critical");
        foreach (MeasurementResidual r in est.Residuals)
        {
            Measurement m = r.Measurement;
            csv.WriteLine($"{m.Kind},{m.Describe()},{m.Value:G17},{m.Sigma:G6},{r.Predicted:G17},{r.Residual:E6},{r.NormalizedResidual:F3},{r.IsCritical}");
        }
    }

    // --hti: the HTI removals in their own file. estimate-export.json's "removed" list is the WLS loop's own LNR
    // removals, which are empty under HTI by construction, so this file is where the HTI verdicts live.
    if (hti is not null)
    {
        using var htiCsv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "hti-removals.csv"), "hti-removals.csv"));
        foreach (string h in RunInfo.HeaderLines(desc)) htiCsv.WriteLine("# " + h);
        htiCsv.WriteLine($"# passes={hti.Passes} total_iterations={hti.TotalIterations} stop_reason={hti.StopReason}");
        // N177 (October 2026, a CSV contract change): the estimated error used to sit in a column called
        // `estimated_error_pu`, but it is in the estimator's internal units, which are radians for the angle rows
        // (VaDeg, IAngDeg) and per-unit of the system base for the power rows. The column is now `estimated_error`
        // (the same number, unchanged, G17) followed by `estimated_error_unit` naming that unit per row (pu, rad or
        // pu_base_mva), then the same error in the measurement's own units (`estimated_error_measured`, MW / Mvar /
        // deg / pu, the conversion the correct-in-place path uses) with `measured_unit`.
        htiCsv.WriteLine("pass,kind,location,value,sigma,estimated_error,estimated_error_unit,estimated_error_measured,measured_unit,test_statistic");
        foreach (HtiRemoval bad in hti.Removed)
        {
            Measurement m = bad.Identified.Measurement;
            htiCsv.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"{bad.Pass},{m.Kind},{m.Describe()},{m.Value:G17},{m.Sigma:G6},{HtiErrorColumns(m.Kind, bad.Identified.EstimatedError, model.BaseMva)},{bad.Identified.TestStatistic:G17}"));
        }
        // N061: with --hti-correct, the in-place corrections in their own file (original value, corrected value).
        if (htiCorrect)
        {
            using var corrCsv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "hti-corrections.csv"), "hti-corrections.csv"));
            foreach (string h in RunInfo.HeaderLines(desc)) corrCsv.WriteLine("# " + h);
            corrCsv.WriteLine($"# passes={hti.Passes} total_iterations={hti.TotalIterations} stop_reason={hti.StopReason}");
            // N177: the same four error columns as hti-removals.csv (see there).
            corrCsv.WriteLine("pass,kind,location,original_value,corrected_value,sigma,estimated_error,estimated_error_unit,estimated_error_measured,measured_unit,test_statistic");
            foreach (HtiCorrection c in hti.Corrected)
            {
                Measurement m = c.Identified.Measurement;
                corrCsv.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                    $"{c.Pass},{m.Kind},{m.Describe()},{m.Value:G17},{c.CorrectedValue:G17},{m.Sigma:G6},{HtiErrorColumns(m.Kind, c.Identified.EstimatedError, model.BaseMva)},{c.Identified.TestStatistic:G17}"));
            }
        }
    }

    Console.WriteLine();
    // The header names the method that ran (it said "WLS" whatever --method chose).
    string methodName = method switch
    {
        EstimationMethod.Wls => "WLS",
        EstimationMethod.Huber => "Huber M-estimator",
        // N356 (CF6): lav and its alias lav-lp print the same header (identical output, as the ruling asks).
        EstimationMethod.Lav or EstimationMethod.LavLp => "LAV (linear programming)",
        EstimationMethod.LavIrls => "LAV by IRLS (approximate)",
        EstimationMethod.SchweppeGm => "Schweppe GM",
        EstimationMethod.Qr => "WLS (QR)",
        EstimationMethod.Constrained => "Constrained WLS",
        EstimationMethod.Feasible => "Feasible (physics-constrained) WLS",
        _ => method.ToString(),
    };
    Console.WriteLine($"=== {methodName} state estimate: {caseName} ===");
    Console.WriteLine($"  status: {est.Status}   iterations: {est.Iterations}   max |dx|: {est.MaxStateUpdate:E2}");
    Console.WriteLine($"  measurements: {set.Measurements.Count}   states: {est.Observability.StateSize}   redundancy (dof): {est.DegreesOfFreedom}");
    Console.WriteLine($"  observability: {(est.Observability.Observable ? $"observable (rank {est.Observability.Rank}/{est.Observability.StateSize})" : "UNOBSERVABLE")}");
    if (!est.Observability.Observable)
    {
        if (est.Observability.UnmeasuredIslandBuses.Count > 0)
            Console.WriteLine($"    unmeasured island buses: {string.Join(", ", est.Observability.UnmeasuredIslandBuses)}");
        if (est.Observability.UnobservableStates.Count > 0)
            Console.WriteLine($"    free state directions: {string.Join(", ", est.Observability.UnobservableStates)}");
    }
    // R175: a robust method (Huber, LAV, Schweppe GM) whose re-weighting hit its cap returns the solve under the
    // second-last weights, not a settled robust estimate. The flag was set by the estimator but never printed.
    if (est.IrlsCapReached)
        Console.WriteLine("  WARNING: the robust re-weighting (IRLS) reached its cap before the weights settled; " +
                          "the state is not a fixed point of the robust estimator.");
    // N331 (CF5): LAV by IRLS is an approximation of the LAV optimum (its weights do not settle: the optimum fits some
    // rows exactly), so every IRLS run says so and names the exact method. Printed after the cap warning, which it explains.
    // N356 (CF6): the IRLS form is --method lav-irls now; --method lav is the exact form.
    if (method == EstimationMethod.LavIrls)
        Console.WriteLine("  NOTE: --method lav-irls is LAV by IRLS, an approximation of the least-absolute-values optimum; " +
                          "--method lav solves it exactly (linear programming).");
    if (est.Converged)
    {
        if (!est.ChiSquareIsVerdict)
        {
            // N356 (CF6, Ruling R1): a LAV estimate (lav, lav-lp, lav-irls) reports the objective LAV minimises and gives
            // no chi-square verdict: neither sum |r| / sigma nor J at the LAV state is chi-square distributed, so a
            // PASS / FAIL against the chi-square quantile would test nothing. J is still printed, labelled as
            // information only. Every non-LAV run takes the else branch, which is the previous code unchanged.
            Console.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"  objective: sum |r| / sigma = {est.LavObjective:F2} (the LAV objective, over {est.Residuals.Count} measurements)"));
            Console.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"  consistency: no chi-square verdict (J = {est.ObjectiveJ:F2}, information only)"));
            Console.WriteLine("  NOTE: the LAV objective is not chi-square distributed (and J at the LAV state is not the least-squares " +
                              "minimum), so no chi-square test applies to a LAV estimate; use --method wls or huber for a consistency verdict.");
        }
        else
        {
            // Why the chi-square test did not run, in words. With --no-bad-data the test is switched off, which used to
            // print "n/a (no redundancy)" next to a redundancy of 95.
            string chi = !double.IsNaN(est.ChiSquareThreshold)
                ? $"J = {est.ObjectiveJ:F2} vs chi2(95%) = {est.ChiSquareThreshold:F2} -> {ChiText(est.ChiSquareTest)}"
                : !eopt.DetectBadData
                    ? $"not tested (chi-square not run: --no-bad-data; J = {est.ObjectiveJ:F2})"
                    // N208: a test that did not run says so ("not run"), never a verdict.
                    : est.DegreesOfFreedom <= 0 ? $"not run (no redundancy: dof {est.DegreesOfFreedom}; J = {est.ObjectiveJ:F2})" : "not run (chi-square not run)";
            Console.WriteLine($"  consistency: {chi}");
        }
        foreach (BadDataRemoval bad in est.Removed)
            Console.WriteLine($"  removed bad data (pass {bad.Pass}): {bad.Measurement.Kind} @ {bad.Measurement.Describe()}  rN = {bad.NormalizedResidual:F1}");
        if (hti is not null)
        {
            // HTI removals carry the jointly estimated gross error and the hypothesis-test statistic t, not a
            // normalised residual, so they are printed (and written to hti-removals.csv) in their own terms.
            foreach (HtiCorrection c in hti.Corrected)   // N061: empty unless --hti-correct
                Console.WriteLine($"  corrected bad data in place (HTI pass {c.Pass}): {c.Identified.Measurement.Kind} @ {c.Identified.Measurement.Describe()}  " +
                                  $"t = {c.Identified.TestStatistic:F1}  {c.Identified.Measurement.Value:G6} -> {c.CorrectedValue:G6}");
            foreach (HtiRemoval bad in hti.Removed)
                Console.WriteLine($"  removed bad data (HTI pass {bad.Pass}): {bad.Identified.Measurement.Kind} @ {bad.Identified.Measurement.Describe()}  " +
                                  $"t = {bad.Identified.TestStatistic:F1}  estimated error = {HtiErrorText(bad.Identified.Measurement.Kind, bad.Identified.EstimatedError, model.BaseMva)}");
            Console.WriteLine($"  bad-data method: HTI, {hti.Passes} pass(es), {hti.TotalIterations} iteration(s) in all, stopped: {hti.StopReason}");
        }
        int critical = est.Residuals.Count(r => r.IsCritical);
        if (critical > 0)
            Console.WriteLine($"  critical measurements (sole observers, unremovable, errors undetectable): {critical}");

        if (truth is not null)
        {
            double dvm = 0, dva = 0;
            for (int i = 0; i < model.BusCount; i++)
            {
                dvm = Math.Max(dvm, Math.Abs(est.Vm[i] - truth.Vm[i]));
                dva = Math.Max(dva, Math.Abs(est.VaDeg[i] - truth.VaDeg[i]));
            }
            Console.WriteLine($"  vs synthetic truth: max |dVm| = {dvm:E3} pu   max |dVa| = {dva:E3} deg");
        }
    }
    // --fdia-screen (R062): screen the final estimate for a residual-cloaked false-data injection - measurement-
    // consistent (chi-square PASSED) yet physically impossible or outside the operational envelope. The verdict is
    // one of: suspected, clear, chi-square failed (conventional bad data, not a cloaked attack), or NO VERDICT (the
    // estimate did not converge, or the chi-square test never ran - no redundancy). A requested screen that is
    // suspected or has no verdict exits 3 below (validation failure); clear and chi-square-failed do not change the
    // exit code (the chi-square failure itself has never changed it, matching the plain estimate verb).
    bool fdiaFailed = false;
    string? fdiaVerdict = null;
    if (fdiaScreen)
    {
        string fdiaSummary;
        if (!est.Converged)
        {
            fdiaVerdict = "no-verdict";
            fdiaSummary = $"not run: the estimate did not converge ({est.Status}), so there is no state to screen.";
            fdiaFailed = true;
        }
        else if (!est.ChiSquareIsVerdict)
        {
            // N356 (CF6): a LAV estimate has no chi-square verdict, so the measurement-consistency half of the screen
            // has nothing to stand on: no verdict, exactly as for a test that did not run.
            fdiaVerdict = "no-verdict";
            fdiaSummary = "not run: a LAV estimate gives no chi-square verdict (its objective is not chi-square distributed), so the measurement-consistency half of the screen has no verdict.";
            fdiaFailed = true;
        }
        else if (est.ChiSquareTest == ChiSquareOutcome.NotRun)
        {
            fdiaVerdict = "no-verdict";
            fdiaSummary = "not run: the chi-square test did not run (no measurement redundancy), so the measurement-consistency half of the screen has no verdict.";
            fdiaFailed = true;
        }
        else
        {
            GridSim.Core.Estimation.Security.FdiaScreenReport fdia = GridSim.Core.Estimation.Security.FdiaScreen.Screen(model, est);
            fdiaVerdict = fdia.SuspectedFdia ? "suspected" : fdia.ChiSquarePassed ? "clear" : "chi-square-failed";
            fdiaSummary = fdia.Summary;
            fdiaFailed = fdia.SuspectedFdia;
            // Every breach is listed; one inside the estimate's 3-sigma uncertainty (telemetry noise, not evidence of
            // an attack) is marked as such and does not raise the flag (FdiaScreen.Screen, October 2026).
            foreach (GridSim.Core.Physics.PhysicsFeasibility.LimitViolation v in fdia.LimitViolations)
                Console.WriteLine($"    fdia limit violation: {v.Kind} ({v.A}-{v.B}) value {v.Value:G6} vs limit {v.Limit:G6}: {v.Detail}" +
                    (fdia.SignificantLimitViolations.Contains(v) ? "" : " [within estimate uncertainty; not counted]"));
        }
        Console.WriteLine($"  FDIA screen: {(fdiaVerdict == "suspected" ? "SUSPECTED FALSE-DATA INJECTION" : fdiaVerdict)} - {fdiaSummary}");
        if (fdiaVerdict == "suspected")   // CAF C1: one audit entry for the detection
            AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.SuspectedFdia, $"FDIA screen: {fdiaSummary}");
        File.WriteAllText(CliFiles.Output(Path.Combine(outDir, "fdia-screen.json"), "fdia-screen.json"), System.Text.Json.JsonSerializer.Serialize(
            new { schema = "gridsim-fdia-screen/1", verdict = fdiaVerdict, summary = fdiaSummary, status = est.Status.ToString(), chiSquareTest = est.ChiSquareTest.ToString() },
            RunInfo.MetadataJson));
    }

    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
    // NCSC CAF C1: one audit entry per security event this estimate raised, beside the run's own entry.
    if (est.Status == EstimationStatus.Infeasible)
        AuditSecurityEvent(GridSim.Core.Diagnostics.SecurityEventKind.InfeasibleState,
            $"estimate converged to a physically infeasible state and was rejected (method {method})");
    Environment.ExitCode = est.Converged && est.Observability.Observable ? 0 : 3;
    if (fdiaFailed) Environment.ExitCode = 3;   // a suspected FDIA, or a requested screen with no verdict

    // R075: the estimate's result in one line, and the instant it describes. The text comes from
    // EstimationAuditTrail.Outcome, the one source of an estimate's audit outcome (October 2026: this line used to be
    // built here separately from EstimationAuditTrail.Record, which nothing called). The text is unchanged.
    if (auditRun is not null)
    {
        // The HTI and FDIA fields are appended only when those flags were given, so a plain run's outcome line is
        // exactly what it was before R062.
        string extra = string.Create(System.Globalization.CultureInfo.InvariantCulture,
            $"{(hti is null ? "" : $" bad_data=hti hti_removed={hti.Removed.Count} hti_passes={hti.Passes} hti_stop={hti.StopReason}")}{(fdiaVerdict is null ? "" : $" fdia={fdiaVerdict}")}");
        auditRun.SetOutcome(EstimationAuditTrail.Outcome(method.ToString(), est, set.Measurements.Count, extra));
        auditRun.StateTimeUtc = set.TakenUtc;
    }
}

// estimate-noise-floor <export.json|dir> [<export.json|dir> ...] [--miscal-tol 0.25] [--min-samples 8] [--out dir]
//   R062: the measurement noise-floor study (NoiseFloorAnalysis). Reads the residual tables of one or many
//   estimate-export.json files (a directory is searched recursively for files of that name), pools the normalised
//   residuals by (source tag, measurement kind), and reports per class how the true noise compares with the declared
//   sigma and which classes are miscalibrated. A study, not a gate: miscalibrated classes are its findings, so the
//   exit code is 0 whenever a report is produced. Exit 1 for input errors (an unreadable or wrong-schema file, no
//   export found, or no usable residual in the whole corpus); exit 2 for usage errors.
void RunEstimateNoiseFloor(List<string> a, string root)
{
    List<string> inputs = Positionals(a).Skip(1).ToList();
    if (inputs.Count == 0)
    {
        Console.Error.WriteLine("usage: gridsim estimate-noise-floor <estimate-export.json|dir> [<estimate-export.json|dir> ...]");
        Console.Error.WriteLine("                                    [--miscal-tol 0.25] [--min-samples 8] [--out <dir>]");
        Console.Error.WriteLine("Pools the normalised residuals of many 'gridsim estimate' runs by (source tag, kind) and reports");
        Console.Error.WriteLine("whether each class's declared sigma matches the noise it actually carries.");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    double tol = FlagDouble(a, "--miscal-tol", NoiseFloorAnalysis.DefaultMiscalibrationTolerance);
    if (!(tol > 0)) FailFlag<double>("--miscal-tol", tol.ToString(System.Globalization.CultureInfo.InvariantCulture), "a positive tolerance");
    int minSamples = FlagInt(a, "--min-samples", NoiseFloorAnalysis.DefaultMinSamplesPerClass);
    if (minSamples < 1) FailFlag<int>("--min-samples", minSamples.ToString(System.Globalization.CultureInfo.InvariantCulture), "a positive sample count");

    // Resolve the corpus: a file is taken as given; a directory contributes every estimate-export.json beneath it.
    // The list is sorted (ordinal) and de-duplicated by full path, so the pooled order, and with it every statistic,
    // is the same on every run and a path given twice is not counted twice.
    var files = new SortedSet<string>(StringComparer.Ordinal);
    foreach (string input in inputs)
    {
        if (File.Exists(input)) files.Add(Path.GetFullPath(input));
        else if (Directory.Exists(input))
        {
            int before = files.Count;
            foreach (string f in Directory.EnumerateFiles(input, "estimate-export.json", SearchOption.AllDirectories))
                files.Add(Path.GetFullPath(f));
            if (files.Count == before)
            {
                Console.Error.WriteLine($"error: no estimate-export.json under '{input}'.");
                Environment.ExitCode = 1;
                return;
            }
        }
        else
        {
            Console.Error.WriteLine($"error: '{input}' is neither a file nor a directory.");
            Environment.ExitCode = 1;
            return;
        }
    }

    var residuals = new List<MeasurementResidual>();
    int usedExports = 0, skippedNonConverged = 0;
    foreach (string f in files)
    {
        EstimateExportResidualTable table;
        try { table = EstimateExportResiduals.Load(f); }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidDataException)
        {
            Console.Error.WriteLine($"error reading '{f}': {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        if (!table.Converged)
        {
            // A non-converged estimate is not a state; its residuals would poison the study. Skipped, and counted.
            Console.Error.WriteLine($"warning: skipping '{f}': its estimate did not converge.");
            skippedNonConverged++;
            continue;
        }
        residuals.AddRange(table.Residuals);
        usedExports++;
    }

    NoiseFloorReport report = NoiseFloorAnalysis.Characterise(residuals, tol, minSamples);
    if (report.TotalSamples - report.SkippedNonFinite == 0)
    {
        Console.Error.WriteLine($"error: no finite normalised residual in the corpus ({files.Count} file(s), {skippedNonConverged} non-converged, " +
            $"{report.SkippedNonFinite} NaN residual(s)); nothing to characterise. Lean runs (--lean) and non-redundant sets carry no normalised residuals.");
        Environment.ExitCode = 1;
        return;
    }

    string outDir = FlagString(a, "--out") ?? DefaultResultsPath("estimate-noise-floor");
    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    string desc = $"estimate-noise-floor  exports={usedExports}  skipped-non-converged={skippedNonConverged}  samples={report.TotalSamples}";
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);
    using (var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "noise-floor.csv"), "noise-floor.csv")))
    {
        foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
        csv.WriteLine("source,kind,count,spread_robust,spread_std,bias,suggested_sigma_scale,miscalibrated");
        foreach (NoiseFloorClass c in report.Classes)
            csv.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"{c.Source},{c.Kind},{c.Count},{c.SpreadRobust:G17},{c.SpreadStd:G17},{c.Bias:G17},{c.SuggestedSigmaScale:G17},{c.Miscalibrated}"));
    }

    Console.WriteLine();
    Console.WriteLine($"=== Measurement noise floor: {usedExports} estimate(s), {report.TotalSamples} residual(s) ({report.SkippedNonFinite} NaN skipped) ===");
    if (skippedNonConverged > 0) Console.WriteLine($"  skipped {skippedNonConverged} non-converged estimate(s)");
    Console.WriteLine($"  {"source",-24} {"kind",-10} {"count",7} {"k_robust",9} {"k_std",8} {"bias",8}  verdict");
    foreach (NoiseFloorClass c in report.Classes)
    {
        string verdict = c.Miscalibrated ? $"MISCALIBRATED: scale sigma by {c.SuggestedSigmaScale:F3}"
                       : c.Count < minSamples ? $"too few samples (< {minSamples}) to judge"
                       : "ok";
        Console.WriteLine($"  {c.Source,-24} {c.Kind,-10} {c.Count,7} {c.SpreadRobust,9:F3} {c.SpreadStd,8:F3} {c.Bias,8:F3}  {verdict}");
    }
    int miscal = report.Miscalibrated.Count();
    Console.WriteLine($"  {miscal} of {report.Classes.Count} class(es) miscalibrated (tolerance {tol:G}, k = true noise / declared sigma)");
    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
    Environment.ExitCode = 0;   // a report was produced; miscalibration is the study's finding, not a run failure
}

// crossval <case|solve-export.json> [--tool pandapower] [--tol 9.09e-13] [--out dir]
//   Solve a case, export the full math, and diff it against an independent pandapower solve of the same network.
void RunCrossval(List<string> a, string root)
{
    string? arg = PositionalArg(a);   // skip flag values (e.g. --tol 9.09e-13) when picking the case
    if (arg is null)
    {
        Console.Error.WriteLine("usage: gridsim crossval <case|solve-export.json> [--tool pandapower] [--tol 9.09e-13] [--out dir]");
        Console.Error.WriteLine("Rebuilds the network in pandapower and diffs its bus voltages/angles vs GridSim's (case9 is real ground truth).");
        Console.Error.WriteLine("Requires Python + pandapower (pip install pandapower). Interpreter: GRIDSIM_PYTHON if set, else the active");
        Console.Error.WriteLine("virtual environment (VIRTUAL_ENV), else the first on PATH. Without one, the run is env-gated (exit 77).");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    // R069: --tool was accepted and ignored. pandapower is the only sidecar, so any other value fails loud.
    if (FlagString(a, "--tool") is string tool && !tool.Equals("pandapower", StringComparison.OrdinalIgnoreCase))
        FailFlag<string>("--tool", tool, "pandapower (the only cross-validation sidecar)");
    // N243 (October 2026, Mark's machine-epsilon rule): with no --tol the sidecar judges at its own default, 4096 machine
    // epsilons (crossval.py DEFAULT_TOL, about 9.09e-13, on |V| in pu and the angle in rad), so the verb no longer
    // overrides it with a looser number (it passed 1e-3 pu). An explicit --tol is passed through unchanged.
    double? tol = a.Contains("--tol") ? FlagDouble(a, "--tol", 0.0) : null;
    if (tol is < 0) FailFlag<double>("--tol", tol.Value.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a tolerance >= 0");
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"crossval-{Path.GetFileNameWithoutExtension(arg)}");
    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    // GR-692: the run folder carries run-metadata.json like every other run folder, so a crossval-diff.json can be traced to
    // the commit, machine and backend that produced it.
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run metadata"), $"crossval {arg}");

    // R075: the case (or the given solve-export), hashed before use.
    auditRun?.AddInput(GridSim.Core.Diagnostics.AuditRunRecorder.InputForArgument("case", arg));

    // 1. Obtain a solve-export: either given directly, or produced by solving a named case here.
    string exportPath;
    // GR-206: a .json argument is a solve export UNLESS it is a JSON v2 case manifest (schema gridsim-case/2), which is a
    // case to solve here like any other case argument; it used to be handed to the sidecar, which cannot read it.
    if (arg.EndsWith(".json", StringComparison.OrdinalIgnoreCase) && File.Exists(arg) && !IsV2CaseManifest(arg))
        exportPath = arg;
    else
    {
        GridModel m;
        // A GDA/JSON case directory (has system.json) loads via the same loader the app uses  -
        // demand folded, generators dispatched, taps applied  -  so gb-full can be cross-validated too.
        // D-DOC-151: LoadCaseArgument (the same three branches, plus the folder fallback).
        try
        {
            m = LoadCaseArgument(arg, root);
        }
        catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

        var trace = new GridSim.Core.Diagnostics.SolveTrace();
        var opt = new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true, Trace = trace };
        // N057: a solve export, so the export's own engine routing (SolverBackend.ExportSolver), unchanged by the
        // always-sparse power-flow rule (the trace the sidecar reads keeps the engine and contents it always had).
        IPowerFlowSolver raw = backend.ExportSolver(m);
        var firstSolveClock = System.Diagnostics.Stopwatch.StartNew();   // D-DOC-140
        PowerFlowResult r = raw.Solve(m, opt);
        firstSolveClock.Stop();
        // N243 (Mark's machine-epsilon rule): the comparison needs GridSim's TIGHTEST converged state, not the state at
        // the everyday 1e-8 pu stopping test. Newton checks the mismatch before each step, so it stops with a residual
        // just under the tolerance (up to about 1e-9 pu on the bundled cases), and the state then differs from the
        // exact solution by about J^-1 times that residual (up to about 1e-9 pu in |V|): a convergence SETTING, not an
        // error in the maths. So after the ordinary solve converges, the same case is solved afresh with the same engine
        // and options at 1e-9, 1e-10, ... 1e-15 pu, keeping the tightest one that converges (below a case's rounding
        // floor, about 1e-15 to 1e-11 pu, Newton cannot meet the test and the ladder stops). Each rung is an ordinary,
        // complete GridSim solve; nothing in the solver changes, and the export records the kept state's own
        // maxMismatch. A first solve that does not converge is exported as it is (the sidecar judges it).
        double reachedTol = opt.Tolerance;
        // D-DOC-140: meta.elapsedMs is the wall time of the solve whose state is exported (the kept rung of the ladder, or
        // the first solve when no tighter rung converged), measured round each solve; it used to be a hard-coded 0.
        double keptSolveMs = firstSolveClock.Elapsed.TotalMilliseconds;
        if (r.Converged)
        {
            foreach (double tight in new[] { 1e-9, 1e-10, 1e-11, 1e-12, 1e-13, 1e-14, 1e-15 })
            {
                var tightTrace = new GridSim.Core.Diagnostics.SolveTrace();
                var rungClock = System.Diagnostics.Stopwatch.StartNew();
                PowerFlowResult rt = raw.Solve(m, opt with { Tolerance = tight, Trace = tightTrace });
                rungClock.Stop();
                if (!rt.Converged) break;   // below this case's floor: keep the last converged rung
                r = rt;
                trace = tightTrace;
                reachedTol = tight;
                keptSolveMs = rungClock.Elapsed.TotalMilliseconds;
            }
        }
        var meta = new SolveExportMeta(arg, backend.Description, RunInfo.GitCommit, DateTime.UtcNow.ToString("o"), keptSolveMs,
            $"{Environment.MachineName} / {System.Runtime.InteropServices.RuntimeInformation.OSDescription}");
        exportPath = Path.Combine(outDir, "solve-export.json");
        SolveExport.WriteJson(CliFiles.Output(exportPath, "solve export"), m, r, trace, meta);
        auditRun?.AddInput(GridSim.Core.Diagnostics.AuditInput.OfFile("solve-export", exportPath));   // what the sidecar compares
        Console.WriteLine($"[crossval] solved '{arg}' ({(r.Converged ? "converged" : "DID NOT CONVERGE")}, {r.Iterations} iters) -> {exportPath}");
        if (r.Converged)
            Console.WriteLine(string.Create(System.Globalization.CultureInfo.InvariantCulture,
                $"[crossval] solve tolerance {reachedTol:G3} pu (the tightest of 1e-8 ... 1e-15 that converged; final mismatch {r.MaxMismatch:E3} pu)"));
    }

    // 2. Locate the sidecar and a Python interpreter.
    string? script = FindFirstExisting(new[]
    {
        // Only beside the executable (or the source tree it was built from): never the CURRENT directory, where a
        // downloaded data folder holding a tools/crossval/crossval.py would have had its code run with the user's rights.
        // The build and the publish copy the sidecar to <executable folder>/tools/crossval (GridSim.Cli.csproj), so the
        // first candidate is found in a build tree and in a release folder alike; the second is the source tree.
        Path.Combine(root, "tools", "crossval", "crossval.py"),
        Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "tools", "crossval", "crossval.py"),
    });
    if (script is null) { Console.Error.WriteLine("crossval: could not find tools/crossval/crossval.py"); Environment.ExitCode = 1; return; }

    string diffPath = Path.Combine(outDir, "crossval-diff.json");
    // N219: a GRIDSIM_PYTHON that names nothing is a configuration error, reported before anything runs (exit 1, an
    // input that cannot be used), never silently replaced by another interpreter.
    if (GridSim.Cli.PythonLocator.Candidates(Environment.GetEnvironmentVariable, OperatingSystem.IsWindows(), File.Exists,
            out string? pythonConfigError).Count == 0 && pythonConfigError is not null)
    {
        Console.Error.WriteLine($"[crossval] error: {pythonConfigError}");
        Console.Error.WriteLine($"           The export is at {exportPath}.");
        Environment.ExitCode = 1;
        return;
    }
    // N243: --tol is forwarded only when given (else the sidecar's machine-epsilon default applies).
    var sidecarArgs = new List<string> { script, exportPath };
    if (tol is double tolGiven) sidecarArgs.AddRange(new[] { "--tol", tolGiven.ToString("R", System.Globalization.CultureInfo.InvariantCulture) });
    sidecarArgs.AddRange(new[] { "--out", diffPath });
    string tolHint = tol is double th ? $" --tol {th.ToString("R", System.Globalization.CultureInfo.InvariantCulture)}" : "";
    (int code, string stdout, string stderr, string? python, string pythonSource) = RunPython(sidecarArgs.ToArray());

    // An absent interpreter / pandapower is an ENVIRONMENT SKIP, not a pass: exit 77 (the conventional
    // "skipped" code) so a CI gate can tell "validated & agrees" (0) apart from "never ran".
    if (python is null)
    {
        Console.WriteLine("[crossval] no Python interpreter found (GRIDSIM_PYTHON unset, no VIRTUAL_ENV interpreter, none on PATH) - sidecar not run (env-gated).");
        Console.WriteLine($"           To validate: install Python + pandapower, then `python {script} {exportPath}{tolHint}`.");
        Environment.ExitCode = 77;
        return;
    }
    // N219: say which interpreter ran and why it was chosen, on every run.
    Console.WriteLine($"[crossval] Python: {python} (from {pythonSource})");
    // Exit 77 = pandapower absent -> genuine ENVIRONMENT skip (77). Exit 3/4 (unreadable export, ppc solve crash)
    // are real validation failures and must NOT read as "never ran".
    // R218: the sidecar used to signal "pandapower absent" with exit 2, so a Python argparse usage error or
    // "can't open file" (also exit 2) read as a skip. Exit 2 is now a failure: the sidecar was not run as intended.
    if (code == 77)
    {
        Console.WriteLine($"[crossval] sidecar unavailable ({python}): {stderr.Trim()}");
        Console.WriteLine($"           install pandapower into that interpreter (pip install pandapower), or point GRIDSIM_PYTHON at one that "
            + $"has it (or activate its virtual environment). The export is at {exportPath}.");
        Environment.ExitCode = 77;
        return;
    }
    if (code == 2)
    {
        Console.Error.WriteLine($"[crossval] the sidecar refused its arguments or could not start ({python}, exit 2): {stderr.Trim()}");
        Console.Error.WriteLine($"           this is a GridSim/sidecar mismatch, not a missing dependency. Export is at {exportPath}.");
        Environment.ExitCode = 3;
        return;
    }
    if (code == 3 || code == 4)
    {
        Console.Error.WriteLine($"[crossval] validation FAILED ({python}, exit {code}): {stderr.Trim()}");
        Console.Error.WriteLine($"           export is at {exportPath}.");
        Environment.ExitCode = 3;
        return;
    }

    Console.WriteLine();
    Console.WriteLine($"=== Cross-validation vs pandapower: {arg} ===");
    if (File.Exists(diffPath))
    {
        try
        {
            using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(diffPath));
            var rootEl = doc.RootElement;
            // N243: the tolerance actually applied comes from the sidecar's report (its machine-epsilon default, the
            // --tol given, or a documented allowance's own bound), printed in full precision: at machine-epsilon level
            // the old fixed-point angle (F4 deg) showed 0.0000 for every case.
            var inv = System.Globalization.CultureInfo.InvariantCulture;
            // GR-910: the sidecar's verdict is "passed" (voltages within tolerance AND the same reactive-limit outcome);
            // an older sidecar without it is read by its voltage verdict alone.
            bool agrees = rootEl.TryGetProperty("passed", out var passedEl)
                ? passedEl.GetBoolean()
                : rootEl.GetProperty("within_tolerance").GetBoolean();
            double tolPu = rootEl.TryGetProperty("tolerance_pu", out var tp) ? tp.GetDouble() : rootEl.GetProperty("tolerance").GetDouble();
            double tolRad = rootEl.TryGetProperty("tolerance_rad", out var tr) ? tr.GetDouble() : tolPu;
            double dvaRad = rootEl.TryGetProperty("max_dva_rad", out var dr) ? dr.GetDouble() : rootEl.GetProperty("max_dva_deg").GetDouble() * Math.PI / 180.0;
            Console.WriteLine($"  buses compared: {rootEl.GetProperty("buses_compared").GetInt32()}");
            Console.WriteLine(string.Create(inv, $"  max |delta Vm|: {rootEl.GetProperty("max_dvm_pu").GetDouble():E3} pu   max |delta Va|: {dvaRad:E3} rad ({rootEl.GetProperty("max_dva_deg").GetDouble():E3} deg)"));
            Console.WriteLine(string.Create(inv, $"  tolerance: {tolPu:E3} pu, {tolRad:E3} rad   -> {(agrees ? "AGREES" : "MISMATCH")}"));
            if (rootEl.TryGetProperty("allowance", out var al) && al.ValueKind == System.Text.Json.JsonValueKind.Object)
                Console.WriteLine($"  judged under a documented allowance: {al.GetProperty("reason").GetString()}");
            if (!agrees && stderr.Trim().Length > 0) Console.WriteLine($"  {stderr.Trim()}");
            auditRun?.SetOutcome(string.Create(inv,
                $"verdict={(agrees ? "AGREES" : "MISMATCH")} buses={rootEl.GetProperty("buses_compared").GetInt32()} max_dvm_pu={rootEl.GetProperty("max_dvm_pu").GetDouble():R} max_dva_deg={rootEl.GetProperty("max_dva_deg").GetDouble():R} tol={tolPu:R}"));
        }
        catch (Exception ex) { Console.Error.WriteLine($"  (could not parse diff: {ex.Message})"); }
    }
    else Console.WriteLine(stdout.Trim());
    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
    Environment.ExitCode = code == 0 ? 0 : 3;
}

static string? FindFirstExisting(IEnumerable<string> candidates)
{
    foreach (string c in candidates)
    {
        string full = Path.GetFullPath(c);
        if (File.Exists(full)) return full;
    }
    return null;
}

// N219: run the sidecar with the first interpreter of PythonLocator's documented order (GRIDSIM_PYTHON, the active
// VIRTUAL_ENV, PATH in order, the py launcher, then the bare names); returns (exitCode, stdout, stderr,
// interpreterUsed-or-null, where it came from or why none could be used). Before, it started the bare names python /
// py / python3 and let the OS search, which on Windows looks in system folders before PATH (N219).
static (int code, string stdout, string stderr, string? python, string source) RunPython(string[] args)
{
    IReadOnlyList<GridSim.Cli.PythonLocator.Candidate> candidates = GridSim.Cli.PythonLocator.Candidates(
        Environment.GetEnvironmentVariable, OperatingSystem.IsWindows(), File.Exists, out string? locateError);
    if (locateError is not null) return (2, "", locateError, null, locateError);
    foreach (GridSim.Cli.PythonLocator.Candidate cand in candidates)
    {
        string exe = cand.Command;
        try
        {
            var psi = new System.Diagnostics.ProcessStartInfo(exe)
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            };
            foreach (string x in args) psi.ArgumentList.Add(x);
            using var p = System.Diagnostics.Process.Start(psi);
            if (p is null) continue;
            // Read both pipes concurrently: pandapower fills stderr with chatter while case118/300 diffs fill
            // stdout, so a sequential ReadToEnd()-then-ReadToEnd() can deadlock on a full pipe buffer.
            Task<string> soTask = p.StandardOutput.ReadToEndAsync();
            Task<string> seTask = p.StandardError.ReadToEndAsync();
            // GR-685: the sidecar is waited on for at most the CI job's own limit (2 h); a hung interpreter used to hold
            // the verb for ever. On timeout the process tree is killed and the run fails with a message.
            if (!p.WaitForExit(TimeSpan.FromHours(2)))
            {
                try { p.Kill(entireProcessTree: true); } catch (InvalidOperationException) { /* already exited */ }
                return (2, "", "the Python sidecar did not finish within 2 hours; it was stopped.", exe, cand.Source);
            }
            string so = soTask.GetAwaiter().GetResult();
            string se = seTask.GetAwaiter().GetResult();
            // The Windows Store 'python' stub prints nothing and exits 9009/49 without running - treat as absent.
            if (p.ExitCode == 9009) continue;
            if (se.Contains("was not found") && string.IsNullOrWhiteSpace(so)) continue;
            return (p.ExitCode, so, se, exe, cand.Source);
        }
        catch { /* try the next interpreter */ }
    }
    return (2, "", "no interpreter", null, "no interpreter found (GRIDSIM_PYTHON unset, no VIRTUAL_ENV interpreter, none on PATH)");
}

// fleet --event <id> [--catalog f] [--units 1,100] [--total-inertia GVA] [--total-ffr GW]
//       [--stagger S] [--tau S] [--deadband Hz] [--inertia GVA] [--out dir]
//   Same TOTAL device budget split across N staggered units: shows FFR is non-additive (inertia is additive).
void RunFleet(List<string> a, string root)
{
    RequireVerbFlags("fleet", a, "--event", "--catalog", "--out", "--units", "--total-inertia", "--total-ffr",
        "--stagger", "--tau", "--deadband", "--inertia", "--trace");
    // N291 (October 2026, stream B5; Ruling R1: Mark delegated EE calls 2026-10-04): the fleet engines run grid-forming
    // now (they refused it, R263), so fleet takes the global --forming / --forming-inertia / --forming-damping switches.
    RefuseIgnoredGlobalSwitches("fleet", usesForming: true);
    string? id = FlagString(a, "--event");
    if (id is null)
    {
        Console.Error.WriteLine("usage: gridsim fleet --event <id> [--catalog f] [--units 1,100] [--total-inertia GVA]");
        Console.Error.WriteLine("                     [--total-ffr GW] [--stagger S] [--tau S] [--deadband Hz] [--inertia GVA] [--trace neso.csv] [--out dir]");
        Console.Error.WriteLine("Built-in events: " + string.Join(", ", EventCatalog.Builtin().Select(e => e.Id)));
        Console.Error.WriteLine("Splits one device budget across N staggered units: intrinsic inertia is N-additive, FFR is NOT.");
        Environment.ExitCode = 2;   // missing required arg is not success
        return;
    }

    string? catalog = FlagString(a, "--catalog");
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath($"fleet-{id}");

    GridEvent ev;
    try { ev = EventCatalog.Get(id, catalog); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = 1; return; }
    // D-DOC-032: the same --trace as replay-event, so the gate can score the per-sample RMSE.
    if (AttachTraceFlag("fleet", a, ev) is not { } flTraced) return;
    ev = flTraced;

    // fleet strips the recorded LFDD and prints/exports counterfactual nadir/LFDD claims - the exact
    // ungrounded-claim path the whole pipeline exists to gate. Refuse it, like scenario/evidence, unless the
    // device-free baseline reproduces the record.
    // D-DOC-002 (same class): a catalog event may name its own NESO trace, which Validate reads under the
    // forward-inference guard; a fresh trace is a refusal (REJECTED, exit 2), never a crash.
    ReplayResult gate;
    try { gate = ReplayValidator.Validate(ev); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = CliExit.Usage; return; }
    // D-DOC-027: a damaged row in an attached trace is refused by name (exit 1).
    catch (InvalidDataException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
    if (gate.Verdict != ReplayVerdict.Reproduced)
    {
        Console.Error.WriteLine($"GATE FAILED: baseline verdict is {gate.Verdict}, not Reproduced - {gate.Summary}");
        Console.Error.WriteLine("Fix the event's [VERIFY] figures (or tolerances) until 'replay-event' reports Reproduced, then re-run.");
        Environment.ExitCode = 3;
        return;
    }

    IReadOnlyList<int> unitCounts = ParseIntList(FlagString(a, "--units"), "--units") ?? new[] { 1, 100 };
    double totalInertiaMwS = FlagDouble(a, "--total-inertia", GridSim.Cli.CliDefaults.DefaultFleetInertiaGvaS) * 1000.0; // GVA.s -> MW.s
    double totalFfrMw = FlagDouble(a, "--total-ffr", GridSim.Cli.CliDefaults.DefaultFleetFfrGw) * 1000.0;           // GW -> MW
    // Default onset spread across the fleet. GB primary frequency response need only be FULLY delivered by
    // 10 s (Grid Code), and a heterogeneous FFR/DSR fleet's units cross their deadbands and dispatch across
    // that window - so a realistic default is ~10 s, not sub-second. A sub-second spread completes long before
    // a large event's nadir, collapsing the whole "FFR is non-additive at the nadir" result to delta~0.
    double stagger = FlagDouble(a, "--stagger", GridSim.Cli.CliDefaults.DefaultFleetStaggerS);
    double tau = FlagDouble(a, "--tau", GridSim.Cli.CliDefaults.DefaultFfrTimeConstantS);
    double deadband = FlagDouble(a, "--deadband", GridSim.Cli.CliDefaults.DefaultFfrDeadbandHz);
    double sysInertiaMwS = (FlagDouble(a, "--inertia", ev.PreEventInertiaMwS / 1000.0)) * 1000.0;
    var losses = ev.ExogenousLossEvents();

    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    string desc = $"fleet  event={ev.Id}  units=[{string.Join(",", unitCounts)}]  totalInertia={totalInertiaMwS / 1000:F0}GVAs  " +
                  $"totalFFR={totalFfrMw / 1000:F2}GW  stagger={stagger}s  sysInertia={sysInertiaMwS / 1000:F0}GVAs"
                  + DesignBasisDesc(ev);   // CF6: empty for a recorded event
    // N291: a forming run says so in the metadata (a run without --forming keeps its exact old description).
    if (formingMode != FormingMode.None)
        desc += $"  forming={formingMode}  formingInertia={formingInertiaMwS / 1000:F0}GVAs  formingDamping={formingDampingMwPerHz:F0}MW/Hz";
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    Console.WriteLine();
    Console.WriteLine($"=== Fleet emergent behaviour: {ev.Title} ===");
    if (DesignBasisLine(ev) is { } flProv) Console.WriteLine(flProv);   // CF6: only for an event below DerivedFromRecorded
    Console.WriteLine($"  system inertia: {sysInertiaMwS / 1000:F0} GVA.s   device budget: {totalInertiaMwS / 1000:F0} GVA.s inertia + {totalFfrMw / 1000:F2} GW FFR   stagger: {stagger:F2} s");
    Console.WriteLine($"  (same TOTAL budget split N ways - intrinsic inertia N-additive, FFR non-additive)");
    // N291: printed only with --forming, so a run without it prints exactly the old lines.
    if (formingMode != FormingMode.None)
        Console.WriteLine($"  grid-forming: {formingMode.ToString().ToLowerInvariant()} former, virtual inertia {formingInertiaMwS / 1000:F0} GVA.s, " +
                          $"damping {formingDampingMwPerHz:F0} MW/Hz (an aggregate virtual former over the real inertia; the units add real inertia and FFR)");
    Console.WriteLine();
    Console.WriteLine($"  {"units",6} | {"RoCoF",11} | {"nadir",8} | {"FFR @ nadir",12} | {"peak FFR",10} | LFDD");
    Console.WriteLine("  " + new string('-', 74));

    double lfddHz = FrequencyLimits.LfddFirstStageHz;
    // The event's RECORDED response services are part of the reality every
    // simulation of this event must carry (the evidence verb's fleet section
    // already does this) - omitting them ran the fleet on a generic governor
    // with a 50.00 Hz start, so fleet and evidence printed different nadirs
    // for the identical budget.
    // N291: the global forming switches carry the aggregate virtual former (defaults: None, 0, 0, the old config).
    DynamicsConfig fleetCfg = ev.ApplyRecordedServices(new DynamicsConfig
    {
        Forming = formingMode,
        VirtualInertiaMwS = formingInertiaMwS,
        FormingDampingMwPerHz = formingDampingMwPerHz,
    });
    // Cover the whole staged loss sequence (the gate/evidence/scenario paths all do): the 30 s
    // default would clip later losses (9 Aug 2019 runs to 90 s) and print a milder nadir than the
    // baseline the gate just validated.
    double lastLossAt = losses.Count > 0 ? losses.Max(l => l.AtSeconds) : 0.0;
    fleetCfg = fleetCfg with { DurationSeconds = Math.Max(fleetCfg.DurationSeconds, lastLossAt + 30.0) };
    var rows = new List<(int n, double rocof, double nadir, double ffrAtNadir, double peakFfr, bool lfdd)>();
    foreach (int n in unitCounts)
    {
        FleetSpec spec = FleetSpec.Uniform(n, totalInertiaMwS, totalFfrMw, tau, deadband, n <= 1 ? 0.0 : stagger);
        FleetResult r = FleetDynamics.Simulate(sysInertiaMwS, ev.PreEventDemandMw, losses, spec, fleetCfg);
        bool lfdd = r.Response.NadirHz <= lfddHz;
        rows.Add((n, r.Response.InitialRocofHzPerS, r.Response.NadirHz, r.FfrAtNadirMw, r.PeakFleetFfrMw, lfdd));
        Console.WriteLine($"  {n,6} | {r.Response.InitialRocofHzPerS,8:+0.000;-0.000}Hz/s | {r.Response.NadirHz,6:F2}Hz | " +
                          $"{r.FfrAtNadirMw,9:F0}MW | {r.PeakFleetFfrMw,7:F0}MW | {(lfdd ? "YES" : "no")}");
    }

    if (rows.Count >= 2)
    {
        // The comparison baseline is the FIRST unit count actually simulated (rows[0]), which need not be 1 -
        // e.g. `--units 10,100`. Describe it by its real count rather than hard-coding "1 aggregate unit", so
        // the printed claim always matches what was run.
        var single = rows[0]; var fleet = rows[^1];
        string baseDesc = single.n == 1 ? "1 aggregate unit" : $"the {single.n}-unit case";
        Console.WriteLine();
        // D-DOC-124 (October 2026, docs-session finding): these three lines used to be fixed text ("RoCoF identical across
        // unit counts", "FFR is NON-additive when it counts", "delta ... deeper") whatever the table showed: gb-2019-08-09
        // printed "identical" beside -0.104 and -0.126 Hz/s, and "only 1500 MW online vs 1500 MW (100 %) - NON-additive".
        // Each line now states what the rows show, compared at the printed precision (the comparison uses the same
        // rounding the table prints, so the sentence never contradicts the digits beside it).
        foreach (string line in FleetConclusions(single.n, single.rocof, single.nadir, single.ffrAtNadir,
                     fleet.n, fleet.rocof, fleet.nadir, fleet.ffrAtNadir, baseDesc))
            Console.WriteLine("  " + line);
    }

    using (var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "fleet.csv"), "fleet.csv")))
    {
        foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
        csv.WriteLine("units,rocof_hz_s,nadir_hz,ffr_at_nadir_mw,peak_fleet_ffr_mw,lfdd_at_risk");
        foreach (var r in rows)
            csv.WriteLine($"{r.n},{r.rocof:F4},{r.nadir:F3},{r.ffrAtNadir:F1},{r.peakFfr:F1},{r.lfdd}");
    }
    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
}

// D-DOC-124: the fleet verb's three conclusion lines, derived from the first and last rows of the table. Values are
// compared as they are printed (RoCoF to 3 decimals in Hz/s, nadir to 2 decimals in Hz, FFR to whole MW), so the words
// agree with the digits printed beside them. Pure text; no number is computed here that the table does not already hold.
static IReadOnlyList<string> FleetConclusions(int nA, double rocofA, double nadirA, double ffrA,
    int nB, double rocofB, double nadirB, double ffrB, string baseDesc)
{
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string R(double v) => v.ToString("+0.000;-0.000", inv);
    var lines = new List<string>();

    // RoCoF. The device inertia is the same total in every row, so a difference here is set by WHEN the fast response
    // arrives (the staggered fleet delivers later, so the steepest slope before it lands is steeper), not by the inertia.
    if (R(rocofA) == R(rocofB))
        lines.Add($"RoCoF the same across unit counts ({R(rocofA)} vs {R(rocofB)} Hz/s): intrinsic inertia is N-additive.");
    else
        lines.Add($"RoCoF differs across unit counts ({R(rocofA)} vs {R(rocofB)} Hz/s): the inertia total is the same in both " +
                  "(it is N-additive), so the difference is the timing of the fast response, not the inertia.");

    // FFR online at the nadir.
    long fA = (long)Math.Round(ffrA, MidpointRounding.AwayFromZero), fB = (long)Math.Round(ffrB, MidpointRounding.AwayFromZero);
    string share = fA <= 0 ? "n/a" : ((double)fB / fA).ToString("P0", inv);
    if (fB < fA)
        lines.Add($"At the nadir the {nB}-unit staggered fleet has {fB} MW online vs {fA} MW for {baseDesc} ({share}): " +
                  "FFR is non-additive when it counts.");
    else if (fB == fA)
        lines.Add($"At the nadir the {nB}-unit fleet has the same {fB} MW online as {baseDesc} ({share}): on this event the " +
                  "staggered fleet is fully delivered by the nadir, so the split costs nothing here.");
    else
        lines.Add($"At the nadir the {nB}-unit fleet has MORE online, {fB} MW vs {fA} MW for {baseDesc} ({share}).");

    // Consequence for the nadir.
    double dNadir = Math.Round(nadirA, 2, MidpointRounding.AwayFromZero) - Math.Round(nadirB, 2, MidpointRounding.AwayFromZero);
    string nA2 = nadirA.ToString("F2", inv), nB2 = nadirB.ToString("F2", inv);
    if (Math.Abs(dNadir) < 0.005)
        lines.Add($"Consequence: the same nadir, {nB2} Hz for the {nB}-unit fleet and {nA2} Hz for {nA} unit(s).");
    else if (dNadir > 0)
        lines.Add($"Consequence: fleet nadir {nB2} Hz vs {nA}-unit {nA2} Hz ({dNadir.ToString("F2", inv)} Hz deeper).");
    else
        lines.Add($"Consequence: fleet nadir {nB2} Hz vs {nA}-unit {nA2} Hz ({(-dNadir).ToString("F2", inv)} Hz shallower).");
    return lines;
}

// N079 (Ruling R1, Mark delegated 2026-10-04): every verb's DEFAULT output goes under results/ in the CURRENT directory,
// as the CLI reference (manual ch. 19) has always said. Before, most verbs wrote their default output beside the
// executable (AppContext.BaseDirectory: bin/Release/net10.0 under `dotnet run`), a few in the current directory
// itself (emt-out, harmonic-export.json, exports/<case>-solve.json) and bench into docs/; only gda-replay, transient,
// nminus1-sweep, stress and chain followed the contract. An explicit --out (or --enableExport=<path>) is used exactly
// as given, unchanged. The desktop app and the web app find run directories in a results/ folder up to seven levels
// above themselves, so runs started from the repository root are still discovered.
// The path is RELATIVE ("results/..."), so it resolves against the current directory when used, and a verb that prints
// its output path as given prints "results\emt-out" rather than a long absolute path.
static string DefaultResultsPath(params string[] parts) =>
    Path.Combine(new[] { "results" }.Concat(parts).ToArray());

// A steady-state solver sized to the model, on the selected CPU/GPU backend (N057: always sparse on the CPU; sparse
// past 200 buses on a GPU, dense otherwise). --bfs forces the radial backward/forward-sweep solver
// (for distribution feeders the transmission Newton-Raphson can't converge).
// --tap-control (Tranche A) also gives the solver its ramp start (SteadyStateSolver.LoadRampStages), which acts only
// when a model with tap changers does not converge from its own taps; without the flag it stays off (0).
// --shunt-control (Tranche A): a model whose .raw file gave regulating switched shunts is solved with
// SwitchedShuntPowerFlow (the banks) wrapping the engine, inside the tap loop.
SteadyStateSolver PickSolver(GridModel m)
{
    bool radial = useBfs || SolverBackend.LooksRadial(m);
    SteadyStateSolver solver;
    if (Gated.ShuntsOf(m) is { Count: > 0 } banks)
    {
        var shuntLoop = new SwitchedShuntPowerFlow(radial ? new BackwardForwardSweep() : backend.Solver(m), banks);
        solver = new SteadyStateSolver(shuntLoop);
        Gated.RememberShuntLoop(solver, shuntLoop);
    }
    else solver = radial
        ? new SteadyStateSolver(new BackwardForwardSweep())   // radial distribution feeder -> two-way sweep
        : backend.Pick(m);
    if (Gated.ApplyTapControl) solver.LoadRampStages = Gated.TapControlRampStages;
    return solver;
}

// ---------------------------------------------------------------------------

GridModel PrintAndExitCase9()
{
    var m = IeeeCases.Case9();
    PrintDetailed(m, PickSolver(m));   // GR-690: --bfs is honoured as on every other bare case (case9 is meshed, so without it the pick is unchanged)
    // Exit with whatever PrintDetailed decided: it sets Environment.ExitCode = 3 on a non-converged solve (R022).
    // This used to be Environment.Exit(0), which overwrote that 3 and reported a failed case9 solve as success.
    Environment.Exit(Environment.ExitCode);
    return m;
}

void RunLive(GridModel baseModel, int maxTicks)
{
    using var gcScope = GcScope.LowLatency(); // no gen2 stutter while the loop runs
    var solver = PickSolver(baseModel);
    bool interactive = maxTicks <= 0;
    // GR-196: see InteractiveWithoutConsole.
    if (interactive && InteractiveWithoutConsole("the live run", "--once or --ticks N")) return;
    try { Console.CursorVisible = false; } catch { /* redirected */ }

    int tick = 0;
    int divergedTicks = 0;   // D-DOC-015: headless ticks whose solve did not converge
    double minutes = GridSim.Cli.CliDefaults.LiveLoopStartMinutes; // start the clock at 08:00
    const double stepMinutes = GridSim.Cli.CliDefaults.LiveLoopStepMinutes;

    try
    {
        while (true)
        {
            if (interactive && KeyPressed()) break;
            if (!interactive && tick >= maxTicks) break;

            double hour = (minutes / 60.0) % 24.0;
            double factor = LoadProfile.DailyFactor(hour);
            GridModel m = GridScenario.AtLoad(baseModel, factor);
            PowerFlowResult r = solver.Solve(m);

            if (interactive) RenderDashboard(m, r, solver, hour, tick);
            else RenderLine(m, r, hour, tick);
            if (!r.Converged) divergedTicks++;

            tick++;
            minutes += stepMinutes;
            Thread.Sleep(interactive ? GridSim.Cli.CliDefaults.LiveLoopInteractiveSleepMs : GridSim.Cli.CliDefaults.LiveLoopBatchSleepMs);
        }
    }
    finally { try { Console.CursorVisible = true; } catch { } }

    // D-DOC-015: a headless run (--ticks N) used to exit 0 even when every tick printed DIV ("case14 --bfs --ticks 2":
    // the forced radial sweep declines the meshed case14 on every tick). A tick whose solve did not converge is a failed
    // solve, so the run exits 3 (the default solve report's code, R022) and says how many ticks failed. Every tick is
    // still run and printed. The interactive loop is a live view stopped by a key press, not a scripted run, and keeps
    // its exit code.
    if (!interactive && divergedTicks > 0)
    {
        Console.Error.WriteLine($"error: {divergedTicks} of {tick} tick(s) did not converge (DIV)"
            + (useBfs ? "; --bfs forces the radial sweep, which declines a meshed network: leave it out to use the Newton engine" : "")
            + ". Exit 3.");
        Environment.ExitCode = 3;   // CliExit.Verdict, written as the literal 3 that CliExitCodeContractTests reads
    }
}

// GR-196: an interactive loop ends only on a key press. With stdin redirected (CI, a scheduled task, a service) no key
// can ever arrive (KeyPressed swallows the InvalidOperationException and returns false for ever), so the process ran
// until killed and never produced an exit code. Such a run is refused (exit 2), naming the headless flags.
static bool InteractiveWithoutConsole(string what, string headless)
{
    if (!Console.IsInputRedirected) return false;
    Console.Error.WriteLine($"error: {what} is interactive (it stops on a key press), but standard input is redirected, so no key can " +
                            $"arrive and it would never stop. Run it headless with {headless}.");
    Environment.ExitCode = CliExit.Usage;
    return true;
}

static bool KeyPressed()
{
    try { return Console.KeyAvailable && Console.ReadKey(true).Key != 0; }
    catch { return false; }
}

// gen = the generators' total real output (MW) at the solved state; load = the nominal bus demand (MW).
// gen used to be the sum of the POSITIVE bus net injections, which is not generator output (a generator bus with
// local load counts only its surplus), so case14 read 0.25 GW of "Generation" against 0.26 GW of demand plus losses.
static (double gen, double load) Totals(GridModel m, PowerFlowResult r)
    => (SolvedGeneration.GeneratorOutputMw(m, r), m.Buses.Sum(b => b.Pd));

// The generator-output figure for a report line: GW to 2 d.p. on a converged state, else "n/a". Generator output is
// read off the solved injections, so on a non-converged state it is a figure from a transient iterate (or, for a
// declined sweep, from all-zero injections, which would print the generator buses' own load as "output").
static string GenOutText(PowerFlowResult r, double genMw)
    => r.Converged ? (genMw / 1000.0).ToString("F2", System.Globalization.CultureInfo.InvariantCulture) + " GW" : "n/a (not converged)";

void RenderDashboard(GridModel m, PowerFlowResult r, SteadyStateSolver solver, double hour, int tick)
{
    try { Console.Clear(); } catch { }
    var (gen, load) = Totals(m, r);
    string clock = $"{(int)hour:00}:{(int)((hour % 1) * 60):00}";

    Console.WriteLine($"  GridSim  -  {m.Name}   live   t={clock}   tick {tick}");
    Console.WriteLine("  " + new string('=', 70));
    // R196 remainder (D2 nominal frequency, October 2026; Ruling R1: Mark delegated EE calls 2026-10-04): a balanced
    // steady state runs at the model's nominal frequency, not a printed literal 50.00 (a 60 Hz case showed 50 Hz). Same
    // text for every 50 Hz model ("50.00").
    string nominalText = m.FrequencyHz.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
    Console.WriteLine(m.AllGenerators.Any(g => g.H > 0)
        ? $"  Frequency   {nominalText} Hz (balanced)        Inertia   {m.SystemInertiaGvaS,6:F1} GVAs"
        : $"  Frequency   {nominalText} Hz (balanced)        Inertia   not in the data (no generator H)");   // N058
    Console.WriteLine($"  Demand    {load / 1000.0,6:F2} GW        Generation {gen / 1000.0,6:F2} GW        Losses {r.TotalLossMw,5:F0} MW");
    Console.WriteLine($"  Voltages  {r.Vm.Min():F3}-{r.Vm.Max():F3} p.u. {(r.Vm.Min() >= GridSim.Core.Analysis.VoltageLimits.OperationalLowPu && r.Vm.Max() <= GridSim.Core.Analysis.VoltageLimits.OperationalHighPu ? "(in band)" : "(OUT OF BAND)")}" +
                      $"     {(r.Converged ? "converged" : "NOT CONVERGED")} ({r.Iterations} NR, {solver.OltcPasses} OLTC)");
    if (r.Converged && m.Oltcs.Count > 0 && !solver.TapsSettled) Console.WriteLine("  " + TapsNotSettledLine(solver));   // N054
    // D-DOC-087: BoundaryAnalysis refuses a non-converged state (the convergence contract): a tick that did not converge
    // shows no boundary line (its status line already says NOT CONVERGED).
    IReadOnlyList<BoundaryFlow> bnd = r.Converged ? BoundaryAnalysis.Evaluate(m, r) : Array.Empty<BoundaryFlow>();
    if (bnd.Count > 0)
    {
        BoundaryFlow top = bnd.OrderByDescending(x => x.LoadingPercent).First();
        Console.WriteLine($"  Boundary  {Trunc(top.Name, 30),-30} {top.FlowMw,6:F0}/{top.LimitMw:F0} MW  {top.LoadingPercent:F0}% {(top.Overloaded ? "OVERLOAD" : "")}");
    }
    Console.WriteLine();
    // N056 (1.95.125): the zone table used to pair every >= 200 kV bus with bus id + 100, which only holds on the GB
    // 10-zone model; on any other case it printed NaN or an unrelated bus. LiveZoneTable pairs each upper-voltage bus
    // with a real lower-voltage in-service neighbour and reproduces the GB table byte for byte (LiveZoneTableTests).
    var zones = GridSim.Core.Presentation.LiveZoneTable.Build(m, r);
    Console.WriteLine($"  Zone                         {zones.UpperHeader,5}   {zones.LowerHeader,5}    Demand");
    Console.WriteLine("  " + new string('-', 56));
    foreach (GridSim.Core.Presentation.LiveZoneTable.Row z in zones.Rows)
    {
        string lower = double.IsNaN(z.LowerVmPu) ? "  -  " : z.LowerVmPu.ToString("F3", System.Globalization.CultureInfo.InvariantCulture);
        Console.WriteLine($"  {Trunc(z.Zone, 26),-26}  {z.UpperVmPu,5:F3}   {lower,5}   {z.DemandMw,6:F0} MW");
    }
    if (zones.Omitted > 0) Console.WriteLine($"  ... and {zones.Omitted} more buses at this voltage");
    if (zones.Note is not null) Console.WriteLine("  " + zones.Note);

    Console.WriteLine();
    Console.WriteLine("  press any key to stop");
}

// N058 (October 2026): the inertia figure for a report line. A case whose generators carry no inertia constant at all
// (MATPOWER files have no H column, so case14 and every IEEE case) used to print "Inertia 0.0 GVAs", correct for the data
// but read as a bug; it now says the value is not in the data. A case with H on any unit prints the figure as before
// (even 0.0, which is then a real answer, for example with every inertial unit out of service).
static string InertiaText(GridModel m)
    => m.AllGenerators.Any(g => g.H > 0)
        ? m.SystemInertiaGvaS.ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + " GVAs"
        : "not in the data (no generator H)";

// N054 (October 2026): the one-line report of an OLTC loop that did not settle: which taps ran out of range with their
// bus still outside the deadband (up to ten named), or that the loop stopped at its pass cap with taps still moving.
static string TapsNotSettledLine(SteadyStateSolver solver)
{
    IReadOnlyList<string> atLimit = solver.TapsAtLimit;
    if (atLimit.Count == 0)
        return $"Taps NOT SETTLED: the tap changer loop stopped after {solver.OltcPasses} pass(es) with taps still moving; the voltages are not the regulated steady state.";
    return $"Taps NOT SETTLED: {atLimit.Count} tap changer(s) at the end of their range with the controlled bus still outside its deadband: "
        + string.Join(", ", atLimit.Take(10)) + (atLimit.Count > 10 ? $", ... and {atLimit.Count - 10} more" : "") + ".";
}

// Tranche A (October 2026): the one-line report of a ramp start (SteadyStateSolver.LoadRampStages, set by --tap-control).
static string RampStartLine(SteadyStateSolver solver)
{
    int n = solver.LoadRampStages;
    string Pct(double f) => (f * 100).ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) + " %";
    const string head = "Ramp start: the solve from the file's taps did not converge, ";
    if (solver.LoadRampFailedAt is double f && f < 1)
        return head + $"and neither did the stage at {Pct(f)} of demand and generation; the result is the solve from the file's taps.";
    string stages = $"so the case was solved at {Pct(1.0 / n)}, {Pct(2.0 / n)}, ... {Pct((n - 1.0) / n)} of its demand and generation first, the taps settling at each stage, then at full load from those taps";
    return solver.LoadRampFailedAt is null
        ? head + stages + $" ({n} stages)."
        : head + stages + ", which did not converge either.";
}

void RenderLine(GridModel m, PowerFlowResult r, double hour, int tick)
{
    var (gen, load) = Totals(m, r);
    string clock = $"{(int)hour:00}:{(int)((hour % 1) * 60):00}";
    Console.WriteLine($"t={clock} tick {tick,2}  load {load / 1000.0,5:F2}GW  gen {gen / 1000.0,5:F2}GW  " +
                      $"loss {r.TotalLossMw,4:F0}MW  V {r.Vm.Min():F3}-{r.Vm.Max():F3}  " +
                      $"{(r.Converged ? "ok" : "DIV")} ({r.Iterations} NR)");
}

void PrintDetailed(GridModel m, SteadyStateSolver solver)
{
    PowerFlowResult r = solver.Solve(m);
    var (gen, load) = Totals(m, r);

    Console.WriteLine($"GridSim  -  {m.Name}");
    Console.WriteLine($"{m.BusCount} buses  {m.Branches.Count} branches  {m.Generators.Count} generators  base {m.BaseMva} MVA  {m.FrequencyHz} Hz");
    Console.WriteLine(new string('=', 72));
    // D-DOC-150: a sweep result (--bfs, or a radial case) names its own convergence test; the Newton line is unchanged.
    Console.WriteLine(r.Converged
        ? (r.SweepVoltageStepPu is null
            ? $"Converged ({r.Iterations} NR iters, {solver.OltcPasses} OLTC passes, max mismatch {r.MaxMismatch:E2} p.u.)"
            : $"Converged on the voltage step ({r.Iterations} sweep iters, {solver.OltcPasses} OLTC passes, last |dV| {r.SweepVoltageStepPu:E2} p.u.; max mismatch {r.MaxMismatch:E2} p.u., which the sweep does not test)")
        : $"DID NOT CONVERGE ({r.Iterations} iters, max mismatch {r.MaxMismatch:E2} p.u.)");
    if (!r.Converged) Environment.ExitCode = 3;   // R022: a reported non-convergence is a failure, not exit 0
    // Two-terminal LCC links (2026-10-25): why an AC/DC solve failed, and each link's solved DC state.
    if (r.LccNote is not null) Console.Error.WriteLine($"LCC HVDC: {r.LccNote}");
    if (r.LccLinks is { Count: > 0 } lccLinks)
        foreach (GridSim.Core.PowerFlow.LccLinkResult d in lccLinks)
            Console.WriteLine($"LCC link {d.Name}: {d.Control}, {d.CurrentA:F1} A, Vdr {d.RectifierDcKv:F2} kV, Vdi {d.InverterDcKv:F2} kV, " +
                $"alpha {d.AlphaDeg:F2} deg, gamma {d.GammaDeg:F2} deg, taps {d.RectifierTap:F5} / {d.InverterTap:F5}, " +
                $"rectifier {d.RectifierMw:F2} MW {d.RectifierMvar:F2} Mvar, inverter {d.InverterMw:F2} MW {d.InverterMvar:F2} Mvar" +
                (d.PowerOrderSwitchedToCurrent ? " (power order switched to current below VCMOD)" : ""));
    if (r.VscNote is not null) Console.Error.WriteLine($"VSC HVDC: {r.VscNote}");
    if (r.MtdcNote is not null) Console.Error.WriteLine($"Multi-terminal DC: {r.MtdcNote}");
    if (r.MtdcLinks is { Count: > 0 } mtdcLinks)
        foreach (GridSim.Core.PowerFlow.MtdcLinkResult d in mtdcLinks)
            Console.WriteLine($"Multi-terminal DC link {d.Name}: " + string.Join("; ", d.Converters.Select(c =>
                $"bus {c.Bus} {(c.Rectifier ? "rectifier" : "inverter")} {c.CurrentA:F1} A {c.DcKv:F2} kV angle {c.AngleDeg:F2} deg tap {c.Tap:F5} {c.DrawnMw:F2} MW drawn {c.AbsorbedMvar:F2} Mvar")));
    if (r.FactsNote is not null) Console.Error.WriteLine($"FACTS: {r.FactsNote}");
    if (r.FactsDevices is { Count: > 0 } factsDevices)
        foreach (GridSim.Core.PowerFlow.FactsResult d in factsDevices)
            Console.WriteLine($"FACTS device {d.Name} ({d.Mode}): bus {d.SendingBus} shunt {d.ShuntMvar:F2} Mvar, {d.ShuntCurrentMva:F2} MVA at unity voltage{(d.ShuntLimited ? " (current-limited)" : "")}" +
                (d.Mode == GridSim.Core.Model.FactsMode.Upfc
                    ? $"; series to bus {d.TerminalBus} {d.SeriesMw:F2} MW {d.SeriesMvar:F2} Mvar, {d.SeriesVoltagePu:F4} pu, {d.SeriesCurrentMva:F2} MVA, bridge {d.BridgeMw:F2} MW"
                    : ""));
    if (r.StaticVarCompensators is { Count: > 0 } svcs)
        foreach (GridSim.Core.PowerFlow.SvcResult d in svcs)
            Console.WriteLine($"Static var compensator {d.Name}: bus {d.Bus} {d.SusceptanceMvar:F2} Mvar at 1 pu, {d.Mvar:F2} Mvar, {d.State}" +
                (double.IsNaN(d.SetpointPu) ? "" : $" (set-point {d.SetpointPu:F4} pu)"));
    if (r.InductionNote is not null) Console.Error.WriteLine($"Induction machines: {r.InductionNote}");
    if (r.InductionMachines is { Count: > 0 } machines)
        foreach (GridSim.Core.PowerFlow.InductionMachineResult d in machines)
            Console.WriteLine($"Induction machine {d.Name}: slip {d.Slip:F6}, {d.Mw:F2} MW {d.Mvar:F2} Mvar drawn, shaft {d.MechanicalMw:F2} MW");
    if (r.VscLinks is { Count: > 0 } vscLinks)
        foreach (GridSim.Core.PowerFlow.VscLinkResult d in vscLinks)
            Console.WriteLine($"VSC link {d.Name}: {d.CurrentA:F1} A; bus {d.First.Bus} {d.First.Mw:F2} MW {d.First.Mvar:F2} Mvar {d.First.DcKv:F2} kV loss {d.First.LossMw:F3} MW{(d.First.Limited ? " (rating-limited)" : "")}; " +
                $"bus {d.Second.Bus} {d.Second.Mw:F2} MW {d.Second.Mvar:F2} Mvar {d.Second.DcKv:F2} kV loss {d.Second.LossMw:F3} MW{(d.Second.Limited ? " (rating-limited)" : "")}");
    // N054 (October 2026): say when the on-load tap changer loop did not finish. A tap that ran out of range with its bus
    // still outside the deadband, or a loop that hit its pass cap, used to be reported exactly like a regulated state.
    // Printed only when the model has tap changers and the loop did not settle, so every settled run's report is
    // unchanged. Reporting only: the exit code stays as the power flow decides (the converged state is genuine; a tap
    // at the end of its range is a property of the network, not a failed solve).
    if (r.Converged && m.Oltcs.Count > 0 && !solver.TapsSettled) Console.WriteLine(TapsNotSettledLine(solver));
    // Tranche A: say when the ramp start (--tap-control) was used, and how it ended. Printed only when it ran, so every
    // other run's report is unchanged.
    if (solver.LoadRampStagesRun > 0) Console.WriteLine(RampStartLine(solver));
    // Tranche A: the switched shunts' state (--shunt-control), printed only when the case has regulating banks.
    if (Gated.ShuntLoopOf(solver) is SwitchedShuntPowerFlow shuntLoop)
        Console.WriteLine($"Switched shunts: {shuntLoop.LastSteps.Count} bank(s), {shuntLoop.LastPasses} switching pass(es) in the last solve, "
            + (shuntLoop.ShuntsSettled ? "settled." : $"NOT SETTLED: {shuntLoop.LastNote}."));
    Console.WriteLine($"Generator output {GenOutText(r, gen)}  Demand {load / 1000.0:F2} GW  Losses {r.TotalLossMw:F1} MW  Inertia {InertiaText(m)}");
    Console.WriteLine();
    Console.WriteLine("Bus  Name                            kV    Vm(pu)  Va(deg)    P(MW)   Q(MVAr)");
    Console.WriteLine(new string('-', 78));
    var busById = m.Buses.ToDictionary(b => b.Id);
    int noKv = 0;
    for (int i = 0; i < m.BusCount; i++)
    {
        Bus b = busById[r.BusIds[i]];
        // N058: a bus whose case gives no base voltage (MATPOWER baseKV 0, as in case14) shows "-" rather than a kV of 0,
        // which read as a bug; the line under the table says why. Labels only: no number changes.
        string kv = b.BaseKv > 0 ? b.BaseKv.ToString("F0", System.Globalization.CultureInfo.InvariantCulture) : "-";
        if (!(b.BaseKv > 0)) noKv++;
        Console.WriteLine($"{b.Id,3}  {Trunc(b.Name ?? "", 28),-28}  {kv,4}  {r.Vm[i],6:F3}  {r.VaDeg[i],7:F2}  {r.PInjMw[i],8:F1}  {r.QInjMvar[i],8:F1}");
    }
    if (noKv > 0)
        Console.WriteLine($"kV '-': base voltage not in the data for {noKv} of {m.BusCount} bus(es) (the case gives 0).");
    // D-DOC-087: the boundary table needs a converged state (BoundaryAnalysis refuses any other); a non-converged report
    // (exit 3, set above) says the table is left out rather than printing flows read from a transient iterate.
    IReadOnlyList<BoundaryFlow> boundaries = r.Converged ? BoundaryAnalysis.Evaluate(m, r) : Array.Empty<BoundaryFlow>();
    if (!r.Converged && m.Boundaries.Count > 0)
    {
        Console.WriteLine();
        Console.WriteLine($"Boundaries: {m.Boundaries.Count} not evaluated (the power flow did not converge).");
    }
    if (boundaries.Count > 0)
    {
        Console.WriteLine();
        Console.WriteLine("Boundary                          Flow(MW)  Limit(MW)  Loading");
        Console.WriteLine(new string('-', 64));
        foreach (BoundaryFlow bf in boundaries)
            Console.WriteLine($"{Trunc(bf.Name, 30),-30}  {bf.FlowMw,8:F0}  {bf.LimitMw,8:F0}   {bf.LoadingPercent,5:F1}% {(bf.Overloaded ? "OVERLOAD" : "")}");
    }

    var loaded = r.LineFlows.Where(f => f.RatingMva > 0).OrderByDescending(f => f.LoadingPercent).Take(5).ToList();
    if (loaded.Count > 0)
    {
        Console.WriteLine();
        Console.WriteLine("Most-loaded branches:");
        foreach (LineFlow f in loaded)
            Console.WriteLine($"  {Trunc(BranchDisplayName(f.Name, f.From, f.To), 28),-28} {Math.Max(Math.Abs(f.PFromMw), Math.Abs(f.PToMw)),7:F0} MW   {f.LoadingPercent,5:F1}%");
    }

    Console.WriteLine();
    Console.WriteLine($"Voltage range: {r.Vm.Min():F3} - {r.Vm.Max():F3} p.u. ({(r.Vm.Min() >= GridSim.Core.Analysis.VoltageLimits.OperationalLowPu && r.Vm.Max() <= GridSim.Core.Analysis.VoltageLimits.OperationalHighPu ? "in band" : "OUT OF BAND")})");
    Console.WriteLine($"Total losses: {r.TotalLossMw:F2} MW, {r.TotalLossMvar:F2} MVAr");

    // A passive protection overlay - the solve above is untouched; this only reports what a relay layer
    // would likely do on the solved state (full detail: `gridsim protection-check <case>`). Only on a CONVERGED
    // state: protection verdicts on a non-converged iterate are meaningless (the convergence contract refuses
    // them), and the non-convergence itself has already been reported above with exit 3.
    if (!r.Converged)
    {
        Console.WriteLine("Protection simulation: skipped - the power flow did not converge, so there is no state to assess.");
        return;
    }
    var prot = GridSim.Core.Protection.ProtectionAssessment.Assess(m, r);
    IReadOnlyList<GridSim.Core.Protection.RelayVerdict> protOps = prot.Operating;
    if (protOps.Count == 0)
        Console.WriteLine("Protection simulation: no relay would operate on this state (generic settings).");
    else
    {
        GridSim.Core.Protection.RelayVerdict w = protOps[0];
        Console.WriteLine($"Protection simulation: {protOps.Count} event(s) suggested  -  e.g. on {w.LocationName}, "
            + $"relay {w.Device} ({w.Function}) would likely operate ({w.Basis}). Run `protection-check` for the full list.");
    }
}

void PrintFrequency(string path)
{
    if (!File.Exists(path)) { Console.Error.WriteLine($"error: frequency file not found: {path}"); Environment.ExitCode = 1; return; }   // an absent input is a failure, not success

    // D-DOC-001: the reader enforces the forward-inference horizon on every row (a row newer than 169 h is refused with
    // ForwardInferenceException). freq used to let that escape as an unhandled exception (a stack trace and the runtime
    // crash code); it is a refusal by design, reported as every other event verb reports it: REJECTED and exit 2.
    // ToList() reads the whole file here, so every later read of the same file below sees rows already accepted.
    List<GridSim.Core.Frequency.FrequencySample> samples;
    try { samples = NesoFrequencyCsv.Read(path).ToList(); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = CliExit.Usage; return; }
    // D-DOC-027 (docs-session finding, October 2026): a line that is not a data row is now refused by the reader, naming
    // the line (it used to be skipped without a word). An input error: exit 1.
    catch (InvalidDataException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
    // D-DOC-027: a file with no data rows at all (empty, or a header only) used to print zero statistics ("Samples 0",
    // min / mean / max 0.000 Hz, "RoCoF within", "LFDD clear") and exit 0, which reads as a calm grid. There is nothing
    // to summarise: refuse it, exit 1.
    if (samples.Count == 0)
    {
        Console.Error.WriteLine($"error: frequency file '{path}' holds no data rows (only a header or blank lines); there is nothing to summarise.");
        Environment.ExitCode = CliExit.InputError;
        return;
    }
    FrequencyStats s = RocofUpsampler.Summarize(samples);
    Console.WriteLine($"NESO frequency  -  {Path.GetFileName(path)}");
    Console.WriteLine(new string('=', 64));
    Console.WriteLine($"Samples      {s.Count:N0}  (1 s cadence)");
    Console.WriteLine($"Frequency    min {s.MinHz:F3} Hz  mean {s.MeanHz:F3} Hz  max {s.MaxHz:F3} Hz");
    Console.WriteLine($"Max |RoCoF|  {s.MaxAbsRocofHzPerS:F4} Hz/s  at {s.MaxRocofAt:yyyy-MM-dd HH:mm:ss}");

    // Score the real trace against the GB limits (operational/statutory/LFDD + RoCoF).
    FrequencyTraceReport rep = FrequencyLimits.AssessTrace(samples);
    Console.WriteLine();
    Console.WriteLine("vs GB limits:");
    Console.WriteLine($"  RoCoF 0.125 Hz/s: {(rep.RocofLimitExceeded ? "EXCEEDED" : "within")}  (worst {rep.MaxAbsRocofHzPerS:F4} Hz/s)");
    Console.WriteLine($"  operational 49.8 Hz: {(rep.SamplesBelowOperational > 0 ? $"{rep.SamplesBelowOperational} s below" : "held")}" +
                      $"    statutory 49.5 Hz: {(rep.SamplesBelowStatutory > 0 ? $"{rep.SamplesBelowStatutory} s below" : "held")}" +
                      $"    LFDD 48.8 Hz: {(rep.LfddReached ? "REACHED" : "clear")}");
    // R081 (October 2026, stream B1): the high side of the same bands. Printed only when the trace goes above 50.2 Hz, so
    // the output of every trace that stays inside the operational band is unchanged.
    if (rep.SamplesAboveOperational > 0)
        Console.WriteLine($"  over-frequency: operational 50.2 Hz: {rep.SamplesAboveOperational} s above" +
                          $"    statutory 50.5 Hz: {(rep.SamplesAboveStatutory > 0 ? $"{rep.SamplesAboveStatutory} s above" : "held")}");
    Console.WriteLine();
    Console.WriteLine("Upsample demo  -  1 s frames expanded to 20 ms by RoCoF interpolation:");
    Console.WriteLine("  time            Hz         RoCoF (Hz/s)");
    foreach (FrequencyPoint p in RocofUpsampler.Upsample(NesoFrequencyCsv.Read(path).Take(3)).Take(8))
        Console.WriteLine($"  {p.Time:HH:mm:ss.fff}   {p.Hz:F5}   {p.RocofHzPerS,8:F4}");
    // F10: the statistics and the limit scan at full precision (the upsample demo is a demonstration, not a result).
    CliOutput.Report?.Set("file", Path.GetFileName(path)).Set("samples", s.Count)
        .Set("min_hz", s.MinHz).Set("mean_hz", s.MeanHz).Set("max_hz", s.MaxHz)
        .Set("max_abs_rocof_hz_per_s", s.MaxAbsRocofHzPerS).Set("max_rocof_at", s.MaxRocofAt)
        .Set("rocof_limit_exceeded", rep.RocofLimitExceeded).Set("trace_max_abs_rocof_hz_per_s", rep.MaxAbsRocofHzPerS)
        .Set("seconds_below_operational", rep.SamplesBelowOperational).Set("seconds_below_statutory", rep.SamplesBelowStatutory)
        .Set("seconds_above_operational", rep.SamplesAboveOperational).Set("seconds_above_statutory", rep.SamplesAboveStatutory)
        .Set("lfdd_reached", rep.LfddReached).Complete();
}

void RunReplay(string path, double sps, int seconds, int frames)
{
    if (!File.Exists(path)) { Console.Error.WriteLine($"error: frequency file not found: {path}"); Environment.ExitCode = 1; return; }   //

    using var gcScope = GcScope.LowLatency(); // smooth 20 ms playback
    Console.WriteLine($"Loading {Path.GetFileName(path)} ({seconds} s) and upsampling to 20 ms...");
    // D-DOC-001: as in freq, a row newer than the forward-inference horizon is a refusal (REJECTED, exit 2), not a crash.
    List<FrequencyPoint> pts;
    try { pts = RocofUpsampler.Upsample(NesoFrequencyCsv.Read(path).Take(seconds + 1), 50).ToList(); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = CliExit.Usage; return; }
    // D-DOC-027: a damaged row inside the played window is refused by name (it used to be skipped silently). Exit 1.
    catch (InvalidDataException ex) { Console.Error.WriteLine($"error: {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
    if (pts.Count == 0) { Console.Error.WriteLine("No data."); Environment.ExitCode = 1; return; }   //
    var rc = new ReplayController(pts, sps);

    if (frames > 0) // headless
    {
        for (int i = 0; i < frames && !rc.AtEnd; i++)
        {
            FrequencyPoint p = rc.Current;
            Console.WriteLine($"[{rc.Index,6}/{rc.Count}] {p.Time:HH:mm:ss.fff}  {p.Hz:F4} Hz  RoCoF {p.RocofHzPerS,7:F4}  @{rc.SlicesPerSecond:F0} sps");
            rc.Advance();
        }
        return;
    }

    // GR-196: see InteractiveWithoutConsole.
    if (InteractiveWithoutConsole("replay", "--frames N")) return;
    try { Console.CursorVisible = false; Console.Clear(); } catch { }
    try
    {
        while (true)
        {
            RenderReplay(rc, Path.GetFileName(path));

            ConsoleKeyInfo? k = null;
            try { if (Console.KeyAvailable) k = Console.ReadKey(true); } catch { }
            if (k is { } key)
            {
                switch (key.Key)
                {
                    case ConsoleKey.Q or ConsoleKey.Escape: try { Console.CursorVisible = true; } catch { } return;
                    case ConsoleKey.Spacebar: rc.Paused = !rc.Paused; break;
                    case ConsoleKey.UpArrow or ConsoleKey.OemPlus or ConsoleKey.Add: rc.Faster(); break;
                    case ConsoleKey.DownArrow or ConsoleKey.OemMinus or ConsoleKey.Subtract: rc.Slower(); break;
                    case ConsoleKey.RightArrow: rc.Paused = true; rc.Advance(); break;
                    case ConsoleKey.LeftArrow: rc.Paused = true; rc.Rewind(); break;
                    case ConsoleKey.Home: rc.Restart(); break;
                }
            }

            if (!rc.Paused)
            {
                if (rc.AtEnd) rc.Paused = true;
                else rc.Advance();
            }
            Thread.Sleep(rc.SlicePeriod);
        }
    }
    finally { try { Console.CursorVisible = true; } catch { } }
}

void RenderReplay(ReplayController rc, string file)
{
    FrequencyPoint p = rc.Current;
    // A replayed trace is a GB (NESO) frequency record, so its deviation is taken from the GB nominal (named, R196).
    double dev = p.Hz - FrequencyLimits.NominalHz;
    ConsoleColor fc = Math.Abs(dev) < 0.10 ? ConsoleColor.Green
                    : Math.Abs(dev) < 0.20 ? ConsoleColor.DarkYellow
                    : Math.Abs(dev) < 0.50 ? ConsoleColor.Yellow : ConsoleColor.Red;

    void Line(int row, string s, ConsoleColor col = ConsoleColor.Gray)
    {
        try { Console.SetCursorPosition(0, row); } catch { }
        var ob = Console.ForegroundColor; Console.ForegroundColor = col;
        // GR-215: Console.WindowWidth throws when the output is not a console (redirected on Windows); a plain line is
        // written then instead of crashing the replay as an internal error.
        int width;
        try { width = Console.WindowWidth; } catch (IOException) { width = 0; }
        Console.Write(width > 0 ? s.PadRight(width - 1) : s + Environment.NewLine);
        Console.ForegroundColor = ob;
    }

    Line(0, $"  Frequency replay  -  {file}", ConsoleColor.White);
    Line(1, $"  {p.Time:yyyy-MM-dd HH:mm:ss.fff}   slice {rc.Index:N0}/{rc.Count:N0}   {rc.SlicesPerSecond:F2} slices/s   {(rc.Paused ? "PAUSED" : "PLAYING")}", ConsoleColor.DarkGray);
    Line(3, "  " + Gauge(p.Hz), fc);
    Line(4, $"  {p.Hz:F4} Hz   ({dev:+0.000;-0.000} Hz)     RoCoF {p.RocofHzPerS,7:F4} Hz/s", fc);
    Line(6, "  " + ProgressBar(rc.ProgressFraction, 50), ConsoleColor.DarkGray);
    Line(8, "  [space] play/pause   [^/v] speed   [<-/->] step (paused)   [home] restart   [q] quit", ConsoleColor.DarkGray);
}

static string Gauge(double hz)
{
    const double lo = 49.5, hi = 50.5;
    int w = 51;
    int pos = (int)Math.Round((Math.Clamp(hz, lo, hi) - lo) / (hi - lo) * (w - 1));
    int mid = (w - 1) / 2;
    var sb = new System.Text.StringBuilder();
    sb.Append("49.5 [");
    for (int i = 0; i < w; i++) sb.Append(i == pos ? '#' : i == mid ? '|' : '-');
    sb.Append("] 50.5");
    return sb.ToString();
}

static string ProgressBar(double frac, int w)
{
    int fill = (int)Math.Round(Math.Clamp(frac, 0, 1) * w);
    return "[" + new string('#', fill) + new string('-', w - fill) + $"] {frac * 100,5:F1}%";
}

// GR-670 (October 2026): the index of a value flag, or -1 when it is absent. A value flag given twice ("--top 5 ... --top
// 10") used to take its FIRST occurrence and silently drop the second, so the run answered a question the caller had
// overridden. A run takes one value per flag, so a second occurrence is refused (exit 2) naming the flag; the few flags
// that are repeatable by design (--event, --bess) are taken off the argument list by their own loops before any of these
// parsers sees it, and the global switches with their own repeat checks (--dir, --frequency-hz, --audit-*) are unchanged.
static int FlagIndex(List<string> a, string name)
{
    int i = a.IndexOf(name);
    if (i >= 0 && a.IndexOf(name, i + 1) >= 0)
    {
        Console.Error.WriteLine($"error: {name} given more than once; give each flag once (a run takes one value per flag).");
        Environment.Exit(CliExit.Usage);
    }
    return i;
}

// Flag parsers are invariant-culture and FAIL LOUD: if the flag is present with an unparseable value
// (a typo like "--trip 100O", or "--dt-ms 0.5" on a comma-decimal locale) we exit non-zero rather than
// silently substituting the default and producing a wrong-physics run that "succeeds".
// R219: a flag that is PRESENT but has no value (the last token, or followed by another --flag, the usual result
// of a shell variable that expanded to empty) also fails loud; only an ABSENT flag takes the default. A number
// flag also refuses NaN and +/-Infinity, which double.TryParse would otherwise accept.
static double FlagDouble(List<string> a, string name, double dflt)
{
    int i = FlagIndex(a, name);
    if (i < 0) return dflt;
    if (FlagValueMissing(a, i)) return FailFlag<double>(name, "", "a number");
    if (double.TryParse(a[i + 1], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double v)
        && double.IsFinite(v))
        return v;
    return FailFlag<double>(name, a[i + 1], "a finite number");
}

static int FlagInt(List<string> a, string name, int dflt)
{
    int i = FlagIndex(a, name);
    if (i < 0) return dflt;
    if (FlagValueMissing(a, i)) return FailFlag<int>(name, "", "an integer");
    if (int.TryParse(a[i + 1], System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out int v))
        return v;
    return FailFlag<int>(name, a[i + 1], "an integer");
}

static T FailFlag<T>(string name, string value, string expected)
{
    Console.Error.WriteLine($"error: {name} expected {expected} but got '{value}'");
    Environment.Exit(2);
    return default!; // unreachable; Exit does not return
}

// Null only when the flag is ABSENT. Present with no value fails loud (R219), so "--out" with an empty shell
// variable behind it no longer writes to the default directory as if nothing were wrong.
static string? FlagString(List<string> a, string name)
{
    int i = FlagIndex(a, name);
    if (i < 0) return null;
    if (FlagValueMissing(a, i)) return FailFlag<string>(name, "", "a value");
    return a[i + 1];
}

// True when the flag at index i has no value after it: it is the last token, or the next token is another --flag.
// (A negative number such as "-5" is a value: it starts with a single dash.)
// GR-191: an empty value (`--dir ""`, or `--dir=` which the normaliser splits into "--dir" "") is missing too; it used to
// be accepted and then crash Path.GetFullPath("") as an internal error.
// GR-205: `chain --bess --steps 0` (or negative) used to be clamped to 1 without a word.
static int StorageSteps(int steps) => steps >= 1 ? steps : FailFlag<int>("--steps", steps.ToString(System.Globalization.CultureInfo.InvariantCulture), "a whole number, 1 or more");

// True when the JSON file at `path` declares "schema": "gridsim-case/2" (a v2 case manifest). An unreadable file is not a
// manifest here; whatever reads it next reports it.
static bool IsV2CaseManifest(string path)
{
    try
    {
        using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(path),
            new System.Text.Json.JsonDocumentOptions { CommentHandling = System.Text.Json.JsonCommentHandling.Skip, AllowTrailingCommas = true });
        return doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Object
            && doc.RootElement.TryGetProperty("schema", out System.Text.Json.JsonElement s)
            && s.ValueKind == System.Text.Json.JsonValueKind.String
            && s.GetString() == "gridsim-case/2";
    }
    catch (Exception ex) when (ex is System.Text.Json.JsonException or IOException or UnauthorizedAccessException)
    {
        return false;
    }
}

// GR-675: a count flag (--top, --candidates, --sample, --frames, --export-every) must be at least `min`; a negative
// value used to be accepted (Take of a negative count printed nothing, exit 0).
static int FlagCount(List<string> a, string name, int dflt, int min)
{
    int v = FlagInt(a, name, dflt);
    return v >= min ? v : FailFlag<int>(name, v.ToString(System.Globalization.CultureInfo.InvariantCulture), $"a whole number, {min} or more");
}

// GR-706: "host:port", "[ipv6]:port", "[ipv6]" (default port) or a bare "port"; the port is 0..65535. False for
// anything else, including an unbracketed value with more than one ':' (an IPv6 address without brackets, which
// cannot be told apart from a port).
static bool TryParseListen(string value, int defaultPort, out string host, out int port)
{
    host = "0.0.0.0";
    port = defaultPort;
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    static bool PortOk(string t, System.Globalization.CultureInfo c, out int p)
        => int.TryParse(t, System.Globalization.NumberStyles.None, c, out p) && p <= 65535;
    if (value.StartsWith('['))
    {
        int close = value.IndexOf(']');
        if (close < 2) return false;
        string addr = value[1..close];
        if (!System.Net.IPAddress.TryParse(addr, out System.Net.IPAddress? ip)
            || ip.AddressFamily != System.Net.Sockets.AddressFamily.InterNetworkV6) return false;
        string tail = value[(close + 1)..];
        if (tail.Length == 0) { host = addr; return true; }
        if (tail[0] != ':' || !PortOk(tail[1..], inv, out int p6)) return false;
        host = addr; port = p6;
        return true;
    }
    string[] hp = value.Split(':');
    if (hp.Length == 1) return PortOk(hp[0], inv, out port);
    if (hp.Length == 2 && hp[0].Length > 0 && PortOk(hp[1], inv, out int p4)) { host = hp[0]; port = p4; return true; }
    return false;
}

// Bug hunt 2026-10-29, finding 77 (decided, documented): a value that begins with "--" is read as MISSING on purpose.
// The common mistake is a flag given without its value and followed by the next flag ("--out --top 5"); reading "--top"
// as the output path would run the verb with a wrong file and a lost flag, silently. The price is that a value which
// itself begins with "--" (a label "--draft", a file named "--x") cannot be passed, and there is no "--"
// end-of-options marker; give such a file as "./--x". Changing this would weaken the missing-value refusal on every verb.
static bool FlagValueMissing(List<string> a, int i) =>
    i + 1 >= a.Count || a[i + 1].StartsWith("--", StringComparison.Ordinal) || string.IsNullOrWhiteSpace(a[i + 1]);

// Gather the contiguous non-flag tokens after an exact `flag` (a space-separated value list), REMOVE the flag
// and those tokens from `a`, and return them joined by spaces. Returns null when the flag is absent, or "" when
// present with no values. For multi-token flags (e.g. --phaseangle A:.. B:..) that must be stripped from the
// arg list before positional-arg detection so their values aren't mistaken for the positional case id.
static string? GatherContiguousValues(List<string> a, string flag)
{
    int i = a.IndexOf(flag);
    if (i < 0) return null;
    int j = i + 1;
    var vals = new List<string>();
    while (j < a.Count && !a[j].StartsWith("--", StringComparison.Ordinal)) { vals.Add(a[j]); j++; }
    a.RemoveRange(i, j - i);
    return string.Join(' ', vals);
}

// Positional (free) arguments, in order: every token that is neither a --flag nor the value a --flag consumes.
// Relies on the established convention that boolean flags are already removed via a.Remove(...) before this is
// called, so every remaining --flag takes the next token as its value. Bug hunt 2026-10-29, finding 76 (decided,
// documented): a boolean flag a verb forgot to remove would swallow the following positional, and the per-verb flag
// check cannot see it (the flag is accepted). The three callers (trip, export, estimate-noise-floor) were checked:
// trip removes its bare-allowed flags (--gb-services, --band, and the global switches removed at start-up) first, and
// export and estimate-noise-floor take only value flags. A new caller must do the same; a value-flag table for the
// whole CLI would remove the convention but touches every verb, so it is not done for this finding. This stops a flag's value (e.g. the
// path after --catalog, or the number after --minutes) being mistaken for the positional case/event.
static List<string> Positionals(List<string> a)
{
    var pos = new List<string>();
    for (int i = 0; i < a.Count; i++)
    {
        if (a[i].StartsWith("--")) { i++; continue; }   // skip the flag AND its value
        pos.Add(a[i]);
    }
    return pos;
}

// Per-verb flag check (docs-programme finding). The global knownFlags gate only rejects a flag NO verb knows, so a
// flag that belongs to another verb passed it and was silently ignored: "fleet --device-ffr 2" ran with the default
// FFR budget, "evidence --corners worst" ran without corners, "replay-event --device-ffr 1" ran without a device.
// A verb that calls this lists every flag it actually reads; any other --flag still in the argument list is refused
// with exit 2, naming the flag and the verb's accepted list. The global switches parsed and removed at start-up
// (--once, --cpu, --gpu, --inertia-model, --bfs, --ticks, --enableExport, --export-jacobian, --audit-log, and the
// forming / asset-dynamics switches, which the caller checks separately) are no longer in the list by then.
static void RequireVerbFlags(string verb, List<string> a, params string[] accepted)
{
    var ok = new HashSet<string>(accepted, StringComparer.Ordinal);
    foreach (string tok in a.Skip(1))   // a[0] is the verb itself
    {
        if (!tok.StartsWith("--", StringComparison.Ordinal) || ok.Contains(tok)) continue;
        Console.Error.WriteLine($"error: {verb} does not use {tok} (it belongs to another verb, so it would be silently ignored). " +
            $"{verb} accepts: {string.Join(", ", accepted)}.");
        Environment.Exit(2);
    }
}

// N074 (October 2026): the one file argument of freq and replay, found wherever it sits. They used to read their file
// only from the token right after the verb, so "freq --json out.json data.csv" (the writer flag is taken off first, so
// that case worked by luck) or "replay --sps 100 run.csv" silently loaded the bundled sample instead. Every flag these
// verbs take has a value, so Positionals reads the free tokens correctly. Null when no file is given (the bundled
// sample is the documented default); a second free token is refused (exit 2) instead of being ignored.
static string? SingleFilePositional(string verb, List<string> a)
{
    List<string> pos = Positionals(a).Skip(1).ToList();
    if (pos.Count > 1)
    {
        Console.Error.WriteLine($"error: {verb} takes at most one file argument but got: {string.Join(' ', pos)}");
        Environment.Exit(2);
    }
    return pos.Count == 1 ? pos[0] : null;
}

// The single positional argument of a verb (the case/event id), i.e. the first free arg after the verb token.
static string? PositionalArg(List<string> a) => Positionals(a).Skip(1).FirstOrDefault();

// ---- Case selection shared by every verb that takes a positional <case> and/or --dir -------------------------------
//
// Why this exists (docs-programme finding, SERIOUS fail-loud breach): nminus1, nminus2, n-1-1, screen, trip, domains
// and export used to load their model through a helper that read ONLY --dir and otherwise loaded data/uk, so
// "gridsim nminus1 case14" printed GB reduced results under a heading the user did not ask for. The mirror defect
// was in nminus1-sweep, stress and chain, which read only the positional case and ignored --dir. Now all of them
// resolve the network the same way:
//
//   * a positional <case> is resolved by LoadCaseArgument (a JSON case folder, a MATPOWER .m file - a bare .m name is
//     searched for under data/matpower - or a built-in name such as case14, uk or gb-full);
//   * --dir <folder> loads that JSON case folder;
//   * both given: accepted only when they name the same folder (for example "uk --dir data/uk"); otherwise the run is
//     refused with exit 2, because we cannot know which network the caller meant;
//   * neither given: the verb's documented default.
//
// A --dir folder that does not exist exits 1 with a message naming the full path (an input error, user manual
// ch. 19), and it does so BEFORE the verb opens any output file. A present-but-valueless --dir (an empty shell
// variable) is a usage error, exit 2, never a silent fall-back to the default model.

// Resolve one positional case argument to a model. THROWS on failure, so a batch verb can still turn it into a
// LOAD FAIL row: ArgumentException for an unknown name (usage error, exit 2 when it reaches LoadSelected), or the
// missing-path / CaseLoadException family (input error, exit 1 through the process-wide handler).
GridModel LoadCaseArgument(string arg, string root)
{
    // A JSON case folder (it has a system.json) wins first, exactly as the other verbs' isCaseDir checks do.
    if (Directory.Exists(arg) && File.Exists(Path.Combine(arg, "system.json"))) return Gated.Dir(arg);
    // A MATPOWER file. Gated.Matpower takes it as a path; a bare name that is not a file here is looked up under
    // data/matpower (and its subfolders) there, so "case33bw.m" finds data/matpower/dist/case33bw.m.
    if (arg.EndsWith(".m", StringComparison.OrdinalIgnoreCase)) return Gated.Matpower(arg);
    // Tranche A: a PSS/E RAW file (revisions 33, 34, 35), taken as a path.
    if (arg.EndsWith(".raw", StringComparison.OrdinalIgnoreCase)) return Gated.Psse(arg);
    // Tranche A: a UCTE-DEF file, taken as a path.
    if (arg.EndsWith(".uct", StringComparison.OrdinalIgnoreCase)) return Gated.Ucte(arg);
    try { return LoadNamed(arg, root); }
    catch (ArgumentException) when (Directory.Exists(arg))
    {
        // Not a known name, but it IS a folder (one with no system.json): load it so the loader reports what is
        // wrong with it (CaseLoadException, exit 1) instead of calling an existing folder an "unknown case".
        return Gated.Dir(arg);
    }
}

// The folder a positional case argument stands for, when it stands for one: an existing directory, or a built-in
// name that loads a shipped folder. Null for everything else (built-in IEEE cases, .m files, unknown names). Used
// only to decide whether a positional case and --dir agree.
static string? CaseFolderOf(string arg, string root)
{
    if (Directory.Exists(arg)) return arg;
    return arg.ToLowerInvariant() switch
    {
        "uk" or "gb" or "gb-reduced" => Path.Combine(root, "data", "uk"),
        "gb-full" => Path.Combine(root, "data", "gb-full"),
        // N316 (LF7, Ruling R1): the name is the shipped folder for every verb (LoadNamed), so a positional gb-synthetic
        // and --dir data/gb-synthetic name the same network and agree, as uk / gb-full do with their folders.
        "gb-synthetic" or "synthetic" => Path.Combine(root, "data", "gb-synthetic"),
        _ => null,
    };
}

// True when two folder paths name the same folder (full paths compared, trailing separators ignored; ordinal and
// case-insensitive, because the shipped tool runs on Windows where paths are case-insensitive).
static bool SameFolder(string x, string y)
{
    static string Norm(string p) => Path.GetFullPath(p).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
    return string.Equals(Norm(x), Norm(y), StringComparison.OrdinalIgnoreCase);
}

// Decide which network a verb runs on, from its positional case argument (null when none was given), --dir, and the
// verb's default. Returns a label for the report and a loader that is called later (a batch verb loads lazily and
// catches a failure per case). Refuses (exit 2) when the two disagree; exits 1 up front for a missing --dir folder.
(string Label, Func<GridModel> Load) SelectCase(string verb, string? caseArg, List<string> a, string root,
    string defaultLabel, Func<GridModel> defaultLoad)
{
    string? dir = null;
    int di = a.IndexOf("--dir");
    if (di >= 0)
    {
        if (FlagValueMissing(a, di)) FailFlag<string>("--dir", "", "a directory path");
        dir = a[di + 1];
        if (a.IndexOf("--dir", di + 1) >= 0)
        {
            Console.Error.WriteLine($"error: {verb}: --dir given more than once; a run analyses exactly one network.");
            Environment.Exit(2);
        }
    }
    if (dir is not null && caseArg is not null)
    {
        string? posFolder = CaseFolderOf(caseArg, root);
        if (posFolder is null || !SameFolder(posFolder, dir))
        {
            Console.Error.WriteLine($"error: {verb}: a positional case '{caseArg}' and --dir '{dir}' were both given and name " +
                "different networks. Give one of them.");
            Environment.Exit(2);
        }
    }
    if (dir is not null)
    {
        if (!Directory.Exists(dir))
        {
            Console.Error.WriteLine($"error: {verb}: case folder not found: '{dir}' (full path {Path.GetFullPath(dir)}).");
            Environment.Exit(1);
        }
        string d = dir;
        return (d, () => Gated.Dir(d));
    }
    if (caseArg is not null)
    {
        string c = caseArg;
        return (c, () => LoadCaseArgument(c, root));
    }
    return (defaultLabel, defaultLoad);
}

// Load the selected network for a single-model verb. An unknown case name is a usage error (exit 2, message names
// the verb and the name); a missing or unloadable file escapes to the process-wide handler (exit 1).
static GridModel LoadSelected(string verb, (string Label, Func<GridModel> Load) sel)
{
    try { return sel.Load(); }
    catch (ArgumentException ex)
    {
        Console.Error.WriteLine($"error: {verb}: {ex.Message}");
        Environment.Exit(2);
        return null!;   // unreachable; Exit does not return
    }
}

// GR-684 (October 2026): the report label of a stability / modal run. "WSCC-9" is reserved for the built-in WSCC 9-bus
// case, because the classical engines read that exact label as "use the Anderson-Fouad machine data"; a user case (a
// folder, a .m file, a --dir path) whose label would be "WSCC-9" is labelled "WSCC-9 (user case)" instead, so it never
// takes the built-in data. Every other label is returned unchanged.
static string UserCaseLabel(string label, bool builtinWscc9) =>
    !builtinWscc9 && label == "WSCC-9" ? "WSCC-9 (user case)" : label;

// GR-676 (October 2026): the case of an analysis verb (dcopf, ptdf, lodf, physics-check, protection-check, fault and the
// verbs that load through LoadAnalysisCase: cpf, pf, dcpf, taps, restore, acopf, iec60909). They took the first free
// token and ignored any further one, so "gridsim pf case14 case30" solved case14 alone and said nothing about case30.
// A second free token is now refused (exit 2), as SingleCasePositional does for the contingency verbs. The count here
// is conservative: a --flag skips its next token only when that token is not itself a --flag, so a switch that is still
// on the list (one with no value) can never make a flag's value look like a second case; the case returned is the one
// PositionalArg picks, exactly as before.
static string? AnalysisCasePositional(string verb, List<string> a)
{
    var pos = new List<string>();
    for (int i = 1; i < a.Count; i++)   // a[0] is the verb
    {
        if (a[i].StartsWith("--", StringComparison.Ordinal))
        {
            if (i + 1 < a.Count && !a[i + 1].StartsWith("--", StringComparison.Ordinal)) i++;   // the flag's value
            continue;
        }
        pos.Add(a[i]);
    }
    if (pos.Count > 1)
    {
        Console.Error.WriteLine($"error: {verb} takes one case argument but got: {string.Join(' ', pos)} (the extra one would be silently ignored).");
        Environment.Exit(CliExit.Usage);
    }
    return PositionalArg(a);
}

// The verbs nminus1, nminus2, n-1-1, screen and domains take at most ONE positional case. A second free token used
// to be ignored; now it is refused (exit 2), so "gridsim screen case14 case30" cannot silently screen one of them.
static string? SingleCasePositional(string verb, List<string> a)
{
    List<string> pos = Positionals(a).Skip(1).ToList();
    if (pos.Count > 1)
    {
        Console.Error.WriteLine($"error: {verb} takes at most one case argument but got: {string.Join(' ', pos)}");
        Environment.Exit(2);
    }
    return pos.Count == 1 ? pos[0] : null;
}

// Case list for the batch verbs nminus1-sweep and stress: --all (the whole registry), or exactly one network from
// the positional case and/or --dir through SelectCase (default case118). --all is a boolean flag, so it is removed
// before the positional is looked for (Positionals would otherwise take the token after it as its value). --all with
// a case or --dir is refused (exit 2): it used to ignore them silently and sweep the registry.
List<(string Label, Func<GridModel> Load, int SortKey)> SelectBatchCases(string verb, List<string> a, string root)
{
    bool all = a.Remove("--all");
    string? pos = SingleCasePositional(verb, a);
    if (all)
    {
        if (pos is not null || a.Contains("--dir"))
        {
            Console.Error.WriteLine($"error: {verb}: --all runs the whole case registry and cannot be combined with a case or --dir.");
            Environment.Exit(2);
        }
        return BuildCases(root).OrderBy(c => c.SortKey).ToList();
    }
    // D-DOC-130 (one rule for every verb): ONE named case that names no case at all is a usage error, exit 2, before the
    // report is opened, exactly as on the single-model verbs. (A case that exists but does not load is still a LOAD FAIL
    // row and exit 1, the batch rule.) NamesNoCase is true exactly when LoadNamed would reach its "unknown case" arm, so
    // calling it then throws the one standard message without loading anything.
    if (pos is not null && NamesNoCase(pos))
    {
        try { _ = LoadNamed(pos, root); }
        catch (UnknownCaseException ex) { Console.Error.WriteLine($"error: {verb}: {ex.Message}"); Environment.Exit(CliExit.Usage); }
    }
    (string label, Func<GridModel> load) = SelectCase(verb, pos, a, root, "case118", () => LoadNamed("case118", root));
    return new() { (label, load, 0) };
}

// A short tag for a case label in a default report file name ("chain-<tag>.md"): the last path element, without a
// .m extension, so "--dir data/uk" gives "uk" and "dist/case33bw.m" gives "case33bw" (a path must not end up as
// folders inside results/).
static string CaseFileTag(string label)
{
    string last = Path.GetFileName(label.TrimEnd('/', '\\'));
    if (last.EndsWith(".m", StringComparison.OrdinalIgnoreCase)) last = last[..^2];
    return last.Length > 0 ? last : "case";
}

// The default network of the GB verbs: the shipped reduced GB model in data/uk.
GridModel LoadUkDefault(string root) => Gated.Dir(Path.Combine(root, "data", "uk"));

void RunGda(List<string> a)
{
    // D06 (Ruling R1, Mark delegated 2026-10-04): an explicit --root wins; otherwise GDA_DATA_ROOT (the GDA estate's
    // own convention) is read first and GDA_ROOT is the fallback. A variable that is set but names no folder is
    // refused naming the variable (exit 1, an input error); its value is never printed.
    string? root = FlagString(a, "--root");
    if (root is null)
    {
        try { root = GdaRootEnvironment.Resolve(out _); }
        catch (DirectoryNotFoundException ex)
        {
            Console.Error.WriteLine($"error: GDA root error: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }
    if (string.IsNullOrEmpty(root))
    {
        Console.Error.WriteLine("usage: gridsim gda --root <path-to-/gda> [--licence EMIDS|WMIDS|SWEST|SWALES]");
        Console.Error.WriteLine("                   [--gsp <GSP group>] [--minkv N] [--out <dir>] [--solve] [--neg-gen] [--all-gen]");
        Console.Error.WriteLine("Reads the read-only GDA data lake and materialises a GridSim replica. Data stays out of the repo.");
        Environment.ExitCode = 2;   // no --root / GDA_DATA_ROOT / GDA_ROOT is a missing required arg, not success
        return;
    }

    var opt = new GdaBuildOptions
    {
        Licence = FlagString(a, "--licence"),
        GspGroup = FlagString(a, "--gsp"),
        // GR-198: a zero or negative base divided by zero in the per-unit conversion; a negative voltage cut is not one.
        MinKv = FlagDouble(a, "--minkv", 0) is var minKv && minKv >= 0 ? minKv
            : FailFlag<double>("--minkv", FlagString(a, "--minkv") ?? "", "a voltage of 0 kV or above"),
        BaseMva = FlagDouble(a, "--base", 100) is var baseMvaFlag && baseMvaFlag > 0 ? baseMvaFlag
            : FailFlag<double>("--base", FlagString(a, "--base") ?? "", "a base above 0 MVA"),
        EmbeddedGenAsNegativeLoad = a.Contains("--neg-gen"),
        CreateOltcs = !a.Contains("--no-oltc"),
        // R015: by default only connected embedded generation enters the model; --all-gen restores the old
        // behaviour (every register row whatever its connection status), for planning what-ifs.
        ConnectedGenerationOnly = !a.Contains("--all-gen"),
    };

    GdaPaths paths;
    // As-of = the no-forward-inference horizon: the materialised model (which gda-replay later
    // reconstructs state on) may only draw on registers already published at least ForwardInferenceGuard.HorizonHours
    // (169 h, 7 days + 1 hour) ago, never one
    // published inside the replayed window. --as-of overrides for a specific replay date.
    DateTime registerAsOf = ForwardInferenceGuard.Horizon(DateTime.UtcNow);
    string? asOfStr = FlagString(a, "--as-of");
    if (asOfStr is not null)
    {
        // Fail loud on an unparseable --as-of: silently falling back to now minus the forward-inference horizon (ForwardInferenceGuard.HorizonHours)
        // materialises a model from the wrong register vintage while "succeeding".
        // ISO-only formats kill the dd/MM vs MM/dd invariant-culture ambiguity.
        string[] asOfFormats = { "yyyy-MM-dd", "yyyy-MM-ddTHH:mm", "yyyy-MM-ddTHH:mm:ss", "yyyy-MM-ddTHH:mm:ssZ", "o" };
        if (DateTime.TryParseExact(asOfStr, asOfFormats, System.Globalization.CultureInfo.InvariantCulture,
                System.Globalization.DateTimeStyles.AdjustToUniversal | System.Globalization.DateTimeStyles.AssumeUniversal, out DateTime parsedAsOf))
        {
            // GR-210: the registers may only be drawn from the historical side of the horizon, so a later --as-of (inside
            // the horizon, or in the future) is refused, as serve --utc-now refuses the same thing.
            if (parsedAsOf > registerAsOf)
                FailFlag<DateTime>("--as-of", asOfStr,
                    $"a date no later than the historical horizon ({registerAsOf:yyyy-MM-ddTHH:mm:ssZ}, {ForwardInferenceGuard.HorizonHours} h before now)");
            registerAsOf = parsedAsOf;
        }
        else
            FailFlag<DateTime>("--as-of", asOfStr, "an ISO-8601 UTC timestamp (yyyy-MM-dd[THH:mm[:ss]])");
    }
    try { paths = new GdaPaths(root, registerAsOf); }
    catch (Exception ex) { Console.Error.WriteLine($"error: GDA root error: {ex.Message}"); Environment.ExitCode = 1; return; }   //

    // Geolocate buses onto GB geography from the NGED substation table, unless --no-geo.
    string subsPath = Path.Combine(root, "NationalGrid", "RAWData", "Network Capacity", "substations.csv");
    if (!a.Contains("--no-geo") && File.Exists(subsPath)) opt.SubstationsPath = subsPath;

    if (a.Contains("--fleet")) { RunGdaFleet(paths); return; }   // national NESO fleet (DNO-independent)

    string? schemaPath = FlagString(a, "--schema");
    if (schemaPath is not null) { RunSchema(schemaPath); return; }

    string dno = (FlagString(a, "--dno") ?? "nged").ToLowerInvariant();
    LtdsDataset ds;
    try
    {
        ds = dno switch
        {
            // N185: UKPN reports each table it had to read from the lake's Parquet copy (its RAWData CSV being
            // header-only) as a "note:" line; a build read wholly from CSV prints nothing new.
            "ukpn" => UkpnSource.Load(root, n => Console.WriteLine($"note: {n}")),
            "npg" => NpgSource.Load(root),
            "nged" => GdaModelBuilder.LoadNged(paths),
            // fail loud: a typo used to silently load NGED and label it with the typo
            var other => FailFlag<LtdsDataset>("--dno", other, "'nged', 'ukpn' or 'npg'"),
        };
    }
    catch (Exception ex) { Console.Error.WriteLine($"Load failed: {ex.Message}"); Environment.ExitCode = 1; return; }

    if (a.Contains("--all-gsps")) { RunGdaAllGsps(ds, opt); return; }

    // Refuse an unknown --gsp up front (usage error, exit 2). A mistyped group used to build an empty model, print
    // "Converged ... (0 NR)" and then die on "Sequence contains no elements" (exit 1). The match is the carve's own
    // (canonical keys, so "Berkswell 132kV" and "berkswell 132 kv" are the same group).
    if (opt.GspGroup is not null && !GdaModelBuilder.IsKnownGspGroup(ds, opt.GspGroup))
    {
        IReadOnlyList<string> near = GdaModelBuilder.SuggestGspGroups(ds, opt.GspGroup);
        Console.Error.WriteLine($"error: --gsp '{opt.GspGroup}' is not a GSP group of {ds.Name}." +
            (near.Count > 0 ? $" Nearest: {string.Join(", ", near.Select(n => $"'{n}'"))}." : "") +
            " gda --all-gsps lists every group.");
        Environment.ExitCode = 2;
        return;
    }

    Console.WriteLine($"GridSim  -  GDA ingestion from {root}  ({dno.ToUpperInvariant()})");
    Console.WriteLine(new string('=', 74));
    var sw = System.Diagnostics.Stopwatch.StartNew();
    GdaBuildResult built;
    try { built = GdaModelBuilder.Build(ds, opt); }
    catch (Exception ex) { Console.Error.WriteLine($"Build failed: {ex.Message}"); Environment.ExitCode = 1; return; }
    sw.Stop();

    GdaDiagnostics d = built.Diagnostics;
    GridModel m = built.Model;
    Console.WriteLine($"Built in {sw.ElapsedMilliseconds} ms  -  {m.Name}");
    Console.WriteLine();
    Console.WriteLine($"  Raw LTDS nodes        {d.RawNodes,8:N0}");
    Console.WriteLine($"  Electrical buses      {d.Buses,8:N0}   (busbar/disconnector ties merged: {d.BusbarTiesMerged:N0})");
    Console.WriteLine($"  Series circuits       {d.SeriesBranches,8:N0}   (cables & lines)");
    Console.WriteLine($"  Transformers (2w/3w)  {d.Transformers2,8:N0} / {d.Transformers3:N0}   (+{d.StarNodes} star nodes)");
    Console.WriteLine($"  Total branches        {m.Branches.Count,8:N0}");
    Console.WriteLine($"  Demand points         {d.DemandPoints,8:N0}   matched {d.DemandPoints - d.UnmatchedDemand:N0}, total {d.TotalDemandMw / 1000.0:F2} GW");
    Console.WriteLine($"  Generators            {d.Generators,8:N0}   ({d.TotalGenCapacityMw / 1000.0:F2} GW capacity, {d.UnmatchedGen} unmatched)");
    Console.WriteLine($"  System inertia        {m.SystemInertiaGvaS,8:F1} GVAs");
    Console.WriteLine($"  OLTCs                 {m.Oltcs.Count,8:N0}");
    Console.WriteLine($"  Connected islands     {d.Islands,8:N0}   (largest {d.LargestIslandBuses:N0} buses)");
    Console.WriteLine();
    Console.WriteLine("  Buses by voltage:");
    foreach (KeyValuePair<int, int> kv in d.BusesByKv)
        Console.WriteLine($"     {kv.Key,4} kV   {kv.Value,7:N0}");
    if (d.Notes.Count > 0)
    {
        Console.WriteLine();
        foreach (string note in d.Notes) Console.WriteLine($"   {note}");
    }

    // An empty carve is not a model. A --licence / --gsp / --minkv combination that keeps no live element used to
    // exit 0 and write an empty model directory that later verbs would load as if it were a network. Refuse it
    // (validation failure, exit 3) before anything is written or solved.
    if (m.BusCount == 0)
    {
        Console.Error.WriteLine("error: the carve selected no live element (0 buses): check --licence, --gsp and --minkv " +
            "(out-of-service, decommissioned and planned elements are excluded). No model was written.");
        Environment.ExitCode = 3;
        return;
    }

    string? outDir = FlagString(a, "--out");
    if (!string.IsNullOrEmpty(outDir))
    {
        // N212: notes name anything a JSON v1 case cannot carry (none for a GDA build today).
        IReadOnlyList<string> notes = GdaModelWriter.WriteDirectory(m, outDir);
        foreach (string note in notes) Console.Error.WriteLine("note: " + note);
        Console.WriteLine();
        Console.WriteLine($"Materialised replica -> {Path.GetFullPath(outDir)} (git-ignored). Run it: gridsim --dir \"{outDir}\"");
    }

    if (a.Contains("--solve"))
    {
        Console.WriteLine();
        // Engine: an explicit --dense / --sparse wins (the user's own choice); otherwise the shared rule on the whole
        // model's bus count (SolverSelector.ResolveNewton), like every other verb. It used to compare the LARGEST
        // ISLAND with the threshold, a rule no other verb used: the dense engine stores the whole n x n system
        // whatever the islands, so the whole model is the size that matters. Bit-identical engines on the CPU, so
        // this changes speed and memory only, never a number.
        // N057: the shared rule through the backend (always sparse on the CPU; the old 200-bus crossover on a GPU).
        SolverKind gdaKind = a.Contains("--dense") ? SolverKind.DenseNewton
                           : a.Contains("--sparse") ? SolverKind.SparseNewton
                           : backend.ResolveNewton(m);
        bool sparse = gdaKind == SolverKind.SparseNewton;
        Console.WriteLine($"Solving with the {(sparse ? "sparse" : "dense")} backend...");
        var solver = backend.Pick(gdaKind);
        var pfOpt = new PowerFlowOptions { MaxIterations = 60, EnforceQLimits = false };
        var solveSw = System.Diagnostics.Stopwatch.StartNew();
        try
        {
            PowerFlowResult r = solver.Solve(m, pfOpt);
            solveSw.Stop();
            var (gen, load) = Totals(m, r);
            Console.WriteLine(r.Converged
                ? $"Converged in {solveSw.ElapsedMilliseconds} ms ({r.Iterations} NR, {solver.OltcPasses} OLTC, mismatch {r.MaxMismatch:E2})"
                : $"DID NOT CONVERGE ({r.Iterations} iters, mismatch {r.MaxMismatch:E2})");
            if (!r.Converged) Environment.ExitCode = 3;   // R022
            Console.WriteLine($"Generator output {GenOutText(r, gen)}  Demand {load / 1000.0:F2} GW  Losses {r.TotalLossMw:F1} MW  V {r.Vm.Min():F3}-{r.Vm.Max():F3} p.u.");
        }
        catch (Exception ex) { Console.Error.WriteLine($"Solve failed: {ex.Message}"); Environment.ExitCode = 1; }
    }
}

void RunSchema(string pathOrDir)
{
    // Inspect a CSV / Parquet dataset: column names + row count (schema only, no data dump).
    try
    {
        using DataSourceTable t = DataSourceTable.Open(pathOrDir);
        int rows = t.Rows().Count();
        Console.WriteLine($"{pathOrDir}");
        Console.WriteLine($"  {t.Headers.Count} columns  {rows:N0} rows");
        foreach (string h in t.Headers) Console.WriteLine($"    {h}");
    }
    catch (Exception ex) { Console.Error.WriteLine($"schema read failed: {ex.Message}"); Environment.ExitCode = 1; }
}

void RunGdaFleet(GdaPaths paths)
{
    NationalFleet fleet;
    try { fleet = NationalFleetBuilder.Build(paths); }
    catch (Exception ex) { Console.Error.WriteLine($"Fleet build failed: {ex.Message}"); Environment.ExitCode = 1; return; }

    Console.WriteLine("GridSim  -  GB transmission-connected generation fleet");
    Console.WriteLine("(NESO TEC register + interconnectors + embedded register)");
    // The register vintage depends on the as-of (now minus 169 h unless --as-of is given), so the same command on two
    // days can read different registers: name the as-of and every file actually read, so the output says which.
    Console.WriteLine($"register as-of {paths.AsOfUtc:yyyy-MM-ddTHH:mm:ssZ}");
    foreach ((string label, Func<string> file) in new (string, Func<string>)[]
             { ("TEC register", () => paths.TecRegister), ("interconnector register", () => paths.InterconnectorRegister),
               ("embedded register", () => paths.EmbeddedRegister) })
    {
        try { Console.WriteLine($"  {label}: {Path.GetFileName(file())}"); }
        catch (Exception ex) when (ex is IOException or InvalidDataException) { Console.WriteLine($"  {label}: none ({ex.Message})"); }
    }
    Console.WriteLine(new string('=', 72));
    Console.WriteLine("Technology          Units   Capacity   % cap   Dispatch   Inertia");
    Console.WriteLine(new string('-', 72));
    foreach (FleetCategory c in fleet.Categories)
        Console.WriteLine($"{Trunc(c.Type, 18),-18}  {c.Count,5}   {c.CapacityMw / 1000.0,6:F2} GW  {(fleet.TotalCapacityMw > 0 ? c.CapacityMw / fleet.TotalCapacityMw * 100 : 0),5:F1}   {c.DispatchMw / 1000.0,5:F2} GW   {c.InertiaGvaS,5:F1} GVAs");
    Console.WriteLine(new string('-', 72));
    Console.WriteLine($"{"TOTAL",-18}  {fleet.Units.Count,5}   {fleet.TotalCapacityMw / 1000.0,6:F2} GW          {fleet.DispatchMw / 1000.0,5:F2} GW   {fleet.InertiaGvaS,5:F1} GVAs");
    Console.WriteLine();
    double syncPct = fleet.TotalCapacityMw > 0 ? fleet.SynchronousCapacityMw / fleet.TotalCapacityMw * 100 : 0;
    Console.WriteLine($"Synchronous (inertial) {fleet.SynchronousCapacityMw / 1000.0:F2} GW ({syncPct:F0}%)  " +
                      $"converter-connected {fleet.ConverterCapacityMw / 1000.0:F2} GW ({100 - syncPct:F0}%)");
    Console.WriteLine($"System inertia (whole synchronous fleet online): {fleet.InertiaGvaS:F1} GVAs");

    // N325 (DOC-17) checked: this GDA fleet screen does NOT need GridModel.SystemInertiaMwS. It works on NESO register
    // units (FleetUnit), whose H comes from FuelMap.InertiaH, which is exactly 0 for every converter technology
    // (storage, wind, solar, tidal, interconnector, and any type it does not know), so NationalFleet.InertiaGvaS, the sum
    // over every unit, already is the rotating-mass total; Doc17TextHygieneTests pins that FuelMap rule.
    // A more realistic operating point: only the dispatched fraction of each synchronous
    // unit is actually spinning, so weight its HMBase by a representative capacity factor.
    double opInertiaGvaS = fleet.Units
        .Where(u => u.Synchronous)
        .Sum(u => u.H * u.CapacityMw * FuelMap.CapacityFactor(u.Type)) / 1000.0;
    Console.WriteLine($"  at a typical dispatch (synchronous x capacity factor): {opInertiaGvaS:F1} GVAs");

    // Largest-infeed-loss trip, driven by the real fleet inertia.
    GridSim.Gda.Neso.FleetUnit big = fleet.Largest;
    double lost = big.CapacityMw * FuelMap.CapacityFactor(big.Type);
    if (lost <= 1) lost = big.CapacityMw;
    double inertiaMwS = fleet.InertiaGvaS * 1000.0;
    double demand = Math.Max(fleet.DispatchMw, GridSim.Cli.CliDefaults.FleetDemandFloorMw);
    var cfg = new DynamicsConfig();
    var ev = new[] { new FrequencyEvent(FrequencyDynamics.DesignEventSeconds, -lost) };   // R171: the shared 1 s design-event time
    FrequencyResponse resp = FrequencyDynamics.Simulate(inertiaMwS, demand, ev, cfg);
    FrequencyResponse op = FrequencyDynamics.Simulate(Math.Max(1.0, opInertiaGvaS * 1000.0), demand, ev, cfg);
    FrequencyResponse half = FrequencyDynamics.Simulate(inertiaMwS / 2, demand, ev, cfg);

    Console.WriteLine();
    Console.WriteLine($"Largest single infeed: {Trunc(big.Name, 36)} ({big.CapacityMw:F0} MW {big.Type})");
    Console.WriteLine($"Trip it ({lost:F0} MW lost): RoCoF {resp.InitialRocofHzPerS:F3} Hz/s  nadir {resp.NadirHz:F3} Hz  settle {resp.SettleHz:F3} Hz");
    Console.WriteLine($"  at a typical dispatch ({opInertiaGvaS:F1} GVAs): RoCoF {op.InitialRocofHzPerS:F3} Hz/s  nadir {op.NadirHz:F3} Hz");
    Console.WriteLine($"  at HALF the inertia ({fleet.InertiaGvaS / 2:F1} GVAs): RoCoF {half.InitialRocofHzPerS:F3} Hz/s  nadir {half.NadirHz:F3} Hz");

    // Score it against the GB limits, and size the TSGB device that would secure it.
    FrequencyAssessment assess = FrequencyLimits.Assess(resp);
    FrequencyAssessment assessHalf = FrequencyLimits.Assess(half);
    double estGva = InertiaEstimator.EstimateInertiaGvaS(lost, resp.InitialRocofHzPerS);
    TsgbSizing sizeNow = TsgbSizer.SizeForTargets(
        inertiaMwS, demand, lost, FrequencyLimits.RocofLimitHzPerS, FrequencyLimits.StatutoryLowHz);
    TsgbSizing sizeHalf = TsgbSizer.SizeForTargets(
        inertiaMwS / 2, demand, lost, FrequencyLimits.RocofLimitHzPerS, FrequencyLimits.StatutoryLowHz);

    Console.WriteLine();
    Console.WriteLine($"vs GB limits (RoCoF <= 0.125 Hz/s, statutory floor 49.5 Hz):");
    Console.WriteLine($"  full inertia: {assess.Summary}      half inertia: {assessHalf.Summary}");
    Console.WriteLine($"  inertia inferred from that RoCoF: {estGva:F1} GVAs  (actual {fleet.InertiaGvaS:F1} GVAs)");
    double floorGva = InertiaEstimator.EstimateInertiaGvaS(lost, FrequencyLimits.RocofLimitHzPerS);
    Console.WriteLine($"  inertia floor for 0.125 Hz/s on this loss: {floorGva:F1} GVAs  (headroom {fleet.InertiaGvaS - floorGva:+0.0;-0.0} GVAs)");
    // R254: a size the search could not make hold the nadir target is labelled as such (the suffix is empty when the
    // target is met, so a feasible line is byte-identical to before).
    Console.WriteLine($"  TSGB to secure the loss now:  +{sizeNow.SyntheticInertiaMwS / 1000:F1} GVAs inertia  {sizeNow.FastResponseMw / 1000:F2} GW fast response  ->  RoCoF {sizeNow.AchievedRocofHzPerS:F3} Hz/s, nadir {sizeNow.AchievedNadirHz:F2} Hz{TsgbSizingShortfall(sizeNow)}");
    Console.WriteLine($"  TSGB to secure it at half inertia: +{sizeHalf.SyntheticInertiaMwS / 1000:F1} GVAs  {sizeHalf.FastResponseMw / 1000:F2} GW  ->  RoCoF {sizeHalf.AchievedRocofHzPerS:F3} Hz/s, nadir {sizeHalf.AchievedNadirHz:F2} Hz{TsgbSizingShortfall(sizeHalf)}");

    // N-1 RoCoF screening across the whole fleet  -  the worst credible single losses.
    IEnumerable<Contingency> conts = fleet.Units
        .Select(u => new Contingency(u.Name, u.CapacityMw * FuelMap.CapacityFactor(u.Type), u.H * u.CapacityMw))
        .Where(c => c.LostMw > 1);
    IReadOnlyList<RocofScreeningResult> screen = RocofScreening.Screen(inertiaMwS, demand, conts);
    if (screen.Count > 0)
    {
        Console.WriteLine();
        Console.WriteLine("N-1 RoCoF screening  -  worst credible single losses:");
        Console.WriteLine("  Unit                              MW    RoCoF    Nadir   Verdict");
        foreach (RocofScreeningResult r in screen.Take(8))
        {
            string verdict = r.LfddRisk ? "LFDD RISK" : r.StatutoryBreach ? "<49.5 Hz" : r.RocofBreach ? ">0.125 Hz/s" : "ok";
            Console.WriteLine($"  {Trunc(r.Name, 30),-30}  {r.LostMw,5:F0}  {r.InitialRocofHzPerS,6:F3}  {r.NadirHz,6:F2}  {verdict}");
        }
        int br = screen.Count(r => r.RocofBreach || r.StatutoryBreach || r.LfddRisk);
        Console.WriteLine($"  {screen.Count} losses screened  {br} breach a limit");
    }

    // ETYS boundary transfer limits (24-months-ahead constraint envelope).
    if (paths.Has(p => p.ConstraintLimits24Mo))
    {
        var limits = NesoReader.BoundaryLimits(paths.ConstraintLimits24Mo).OrderByDescending(b => b.MaxMw).ToList();
        if (limits.Count > 0)
        {
            Console.WriteLine();
            Console.WriteLine("ETYS boundary transfer limits (24-months-ahead, MW):");
            Console.WriteLine("  Boundary        min     median     max    samples");
            foreach (BoundaryLimit b in limits)
                Console.WriteLine($"  {Trunc(b.Code, 12),-12}  {b.MinMw,6:F0}  {b.MedianMw,8:F0}  {b.MaxMw,7:F0}   {b.Samples}");
        }
    }
}

void RunGdaAllGsps(LtdsDataset ds, GdaBuildOptions baseOpt)
{
    // Solve the whole DNO the way it's physically organised: one Grid Supply Point
    // supply area at a time (each is an independent transmission infeed). The dataset
    // is held in memory, so each area builds from it without re-reading the files.
    var spelt = ds.Circuits.Select(c => c.GspGroup).Where(g => g.Length > 0)
        .Distinct().OrderBy(g => g, StringComparer.Ordinal).ToList();   // GR-678: ordinal, not the ICU culture order
    // Spellings with the same canonical key select exactly the same elements (the carve compares keys, see
    // GdaModelBuilder.GspGroupKey), so building each spelling separately built one area twice and counted its demand
    // and losses twice ("Iron Acton 132 kV" and "Iron Acton 132kV" each built 193 buses). Build each key once, under
    // its first spelling, and list the other spellings it covers after the table. GroupBy keeps first-seen order.
    List<List<string>> byKey = spelt.GroupBy(GdaModelBuilder.GspGroupKey).Select(k => k.ToList()).ToList();
    var groups = byKey.Select(l => l[0]).ToList();
    var mergedSpellings = byKey.Where(l => l.Count > 1).ToList();

    Console.WriteLine($"GridSim  -  solving every GSP supply area of {ds.Name} ({groups.Count} groups" +
        (spelt.Count != groups.Count ? $", {spelt.Count} spellings)" : ")"));
    Console.WriteLine(new string('=', 78));
    Console.WriteLine("GSP group                         Buses  Demand   Loss   Vmin   Vmax   Status");
    Console.WriteLine(new string('-', 78));

    var pfOpt = new PowerFlowOptions { MaxIterations = 60, EnforceQLimits = false };
    int ok = 0;
    var emptyGroups = new List<string>();
    double totDemand = 0, totLoss = 0, solvedDemand = 0;
    var sw = System.Diagnostics.Stopwatch.StartNew();

    foreach (string g in groups)
    {
        var opt = new GdaBuildOptions
        {
            GspGroup = g, MinKv = baseOpt.MinKv, BaseMva = baseOpt.BaseMva,
            CreateOltcs = baseOpt.CreateOltcs, EmbeddedGenAsNegativeLoad = baseOpt.EmbeddedGenAsNegativeLoad,
            ConnectedGenerationOnly = baseOpt.ConnectedGenerationOnly,   // carry --all-gen into every GSP area
        };
        GdaBuildResult built;
        try { built = GdaModelBuilder.Build(ds, opt); }
        catch (Exception ex) { Console.WriteLine($"{Trunc(g, 32),-32}  build failed: {ex.Message}"); Environment.ExitCode = 3; continue; }   // R022

        GridModel m = built.Model;
        double demand = built.Diagnostics.TotalDemandMw;
        totDemand += demand;
        // A group name that keeps no live element (typically a spelling variant such as "Exeter 132" beside the real
        // "Exeter 132 kV", whose circuits are all out of service or planned) is not an area that failed to solve:
        // it has nothing to solve. It used to print "(empty)" and count as not converged, so the run exited 3 on
        // NGED although every real area converged. Now it is set aside, listed after the table, and not counted.
        if (m.BusCount == 0) { emptyGroups.Add(g); continue; }

        try
        {
            // Shared dense/sparse rule per GSP area (was always sparse); bit-identical engines, so speed only.
            var solver = backend.Pick(m);
            PowerFlowResult r = solver.Solve(m, pfOpt);
            string status = r.Converged ? "converged" : $"DIV {r.MaxMismatch:E0}";
            if (r.Converged) { ok++; solvedDemand += demand; totLoss += r.TotalLossMw; }
            Console.WriteLine($"{Trunc(g, 32),-32}  {m.BusCount,5}  {demand / 1000.0,5:F2}GW  {r.TotalLossMw,5:F0}MW  {r.Vm.Min(),5:F3}  {r.Vm.Max(),5:F3}  {status}");
        }
        catch (Exception ex) { Console.WriteLine($"{Trunc(g, 32),-32}  {m.BusCount,5}  solve error: {ex.Message}"); }
    }
    sw.Stop();

    Console.WriteLine(new string('-', 78));
    int areas = groups.Count - emptyGroups.Count;
    Console.WriteLine($"{ok}/{areas} GSP areas converged in {sw.Elapsed.TotalSeconds:F1}s");
    foreach (List<string> l in mergedSpellings)
        Console.WriteLine($"  '{l[0]}' also covers {string.Join(", ", l.Skip(1).Select(s => $"'{s}'"))} (same group, built once)");
    if (emptyGroups.Count > 0)
    {
        // Name each empty group with the non-empty group it most likely spells differently, so a real data gap
        // (an area that should have elements) is still visible.
        Console.WriteLine($"{emptyGroups.Count} group name(s) select no live element and were skipped (not counted):");
        var emptySet = new HashSet<string>(emptyGroups, StringComparer.Ordinal);
        foreach (string e in emptyGroups)
        {
            string? variant = groups.Where(x => !emptySet.Contains(x) && x.StartsWith(e, StringComparison.OrdinalIgnoreCase))
                                    .OrderBy(x => x, StringComparer.Ordinal).FirstOrDefault();
            Console.WriteLine($"  {e}{(variant is null ? "" : $"   (spelling variant of '{variant}')")}");
        }
    }
    if (ok < areas || areas == 0) Environment.ExitCode = 3;   // R022: any area that did not build/converge fails the run; so does a run with no area at all
    Console.WriteLine($"Demand: {solvedDemand / 1000.0:F2} GW solved of {totDemand / 1000.0:F2} GW total  losses {totLoss:F0} MW ({(solvedDemand > 0 ? totLoss / solvedDemand * 100 : 0):F2}%)");
}

// The shared case registry: the embedded classic IEEE/CIGRE systems plus every .m file found
// under data/matpower (recursively) - so whatever fetch-cases.sh drops in is picked up. Disk
// files that duplicate an embedded classic (by filename stem) are skipped.
List<(string Label, Func<GridModel> Load, int SortKey)> BuildCases(string root)
{
    var known = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        { "case9", "case14", "case30", "case57", "case118", "case145", "case300", "case24_ieee_rts", "cigre_mv" };
    var cases = new List<(string, Func<GridModel>, int)>
    {
        ("case9 (WSCC)", IeeeCases.Case9, 9),
        ("case14", IeeeCases.Case14, 14),
        ("case30", IeeeCases.Case30, 30),
        ("case57", IeeeCases.Case57, 57),
        ("case118", IeeeCases.Case118, 118),
        ("case145", IeeeCases.Case145, 145),
        ("case300", IeeeCases.Case300, 300),
        ("case24_ieee_rts", IeeeCases.Case24Rts, 24),
        ("cigre_mv", IeeeCases.CigreMv, 15),
    };
    string mp = Path.Combine(root, "data", "matpower");
    if (Directory.Exists(mp))
        foreach (string f in Directory.EnumerateFiles(mp, "*.m", SearchOption.AllDirectories)
                                      .OrderBy(f => f, StringComparer.OrdinalIgnoreCase).ThenBy(f => f, StringComparer.Ordinal))
        {
            string stem = Path.GetFileNameWithoutExtension(f);
            if (known.Contains(stem)) continue;      // already an embedded classic
            // A rough size hint for ordering, parsed from the case number in the name.
            int busHint = new string(stem.Where(char.IsDigit).ToArray()) is { Length: > 0 } d
                ? int.Parse(d[..Math.Min(6, d.Length)]) : 0;
            string path = f;
            cases.Add((stem, () => Gated.Matpower(path), busHint));
        }
    return cases;
}

// Fail-fast GPU preflight: report each backend's availability and try one tiny isolated solve on it,
// flushing every step, so a rented box reveals go/no-go (and exactly where it breaks) in seconds -
// before the full sweep, and before a bad native call can take the whole run down with it.
void RunDcOpf(List<string> a, string root)
{
    bool noLimits = a.Remove("--no-limits");
    // F19 (October 2026): --prices adds the nodal prices (LMPs) and line shadow prices; --costs case|<file.json>
    // dispatches on the generators' own cost curves (the case's MATPOWER gencost, or a gridsim-costs/1 file laid over the
    // case). Both are opt-in: without them the run, its output and its result file are exactly as before.
    bool prices = a.Remove("--prices");
    string? costs = FlagString(a, "--costs");
    int top = FlagCount(a, "--top", 12, 0);
    string? arg = AnalysisCasePositional("dcopf", a);
    if (arg is null) { Console.Error.WriteLine("usage: gridsim dcopf <case> [--no-limits] [--top N] [--costs case|<file.json>] [--prices]"); Environment.ExitCode = 2; return; }

    GridModel m;
    try
    {
        // D-DOC-151: LoadCaseArgument (the same three branches, plus the folder fallback: an existing folder that is
        // not a known name loads as a case folder, so the loader names what is wrong instead of "unknown case").
        m = LoadCaseArgument(arg, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    if (costs is not null)
    {
        GridModel? costed = ApplyCostSource(m, costs, "dcopf");
        if (costed is null) return;
        m = costed;
    }

    GridSim.Core.Analysis.DcOptimalPowerFlow.DcOpfResult res;
    if (costs is null && !prices)
    {
        // D-DOC-004: the solver refuses invalid generator data (a unit whose Pmin is above its Pmax) with
        // InvalidDataException. Only InvalidOperationException was caught on this path (the --costs / --prices path
        // below caught both), so that refusal crashed the verb. Invalid case data is an input error: exit 1, as the
        // other path already gave.
        try { res = GridSim.Core.Analysis.DcOptimalPowerFlow.Solve(m, enforceLineLimits: !noLimits); }
        catch (Exception ex) when (ex is InvalidOperationException or InvalidDataException)
        { Console.Error.WriteLine($"[dcopf] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
    }
    else
    {
        var opts = new GridSim.Core.Analysis.DcOptimalPowerFlow.DcOpfOptions
        {
            EnforceLineLimits = !noLimits, UseGeneratorCosts = costs is not null, ComputePrices = prices,
        };
        try { res = GridSim.Core.Analysis.DcOptimalPowerFlow.Solve(m, opts); }
        catch (Exception ex) when (ex is InvalidOperationException or InvalidDataException)
        { Console.Error.WriteLine($"[dcopf] {ex.Message}"); Environment.ExitCode = 1; return; }
    }

    // Money units: the fuel-type merit order is in GBP; a cost curve is in the case's own currency (MATPOWER's are
    // usually $/h), so with --costs the figures are labelled "cost units".
    string money = costs is null ? "GBP" : "cost units";
    Console.WriteLine(costs is null
        ? $"DC-OPF - {m.Name} ({m.BusCount} buses)  [cheapest secure dispatch]"
        : $"DC-OPF - {m.Name} ({m.BusCount} buses)  [cheapest secure dispatch on generator cost curves: {(costs.Equals("case", StringComparison.OrdinalIgnoreCase) ? "case gencost" : Path.GetFileName(costs))}]");
    // F10: the result file (when asked for) carries the summary, EVERY generator's dispatch (the console lists the top
    // N above the display floor), every binding line and the island list. The tables are created up front so the CSV
    // layout is the same whatever the outcome (an infeasible run has an empty dispatch table).
    CliResult? rep = CliOutput.Report;
    rep?.Set("case", m.Name).Set("buses", m.BusCount).Set("line_limits_enforced", !noLimits).Set("feasible", res.Feasible);
    // D-DOC-139 (October 2026): one honest unit. On the fuel-type merit order the money is GBP and the keys say so
    // (unchanged). With --costs it is the case's own currency, printed as "cost units"; the result file used to say GBP
    // anyway (total_cost_gbp_per_h, cost_gbp_per_mwh). With --costs the keys are now unit-neutral, total_cost_per_h and
    // marginal_cost_per_mwh (the column holds each unit's marginal cost), and cost_units names the unit.
    CliResultTable? repDispatch = rep?.Table("dispatch", "gen_bus", "pg_mw", costs is null ? "cost_gbp_per_mwh" : "marginal_cost_per_mwh");
    CliResultTable? repBinding = rep?.Table("binding_lines", "branch", "name", "flow_mw", "rate_mw");
    CliResultTable? repIslands = rep?.Table("islands", "reference_bus", "buses", "load_mw", "generation_mw", "has_generation", "feasible", "security_lp_status");
    // N034: a network of several DC islands is dispatched island by island; list every island, so an island with
    // no generation (whose load cannot be supplied) is visible rather than silently dropped.
    if (res.Islands is { } islands)
    {
        Console.WriteLine($"  {islands.Count} DC islands, each dispatched on its own (its own balance, its own reference bus):");
        foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.IslandDispatch isl in islands)
        {
            Console.WriteLine($"      island ref bus {isl.ReferenceBus,-6} {isl.BusCount,5} buses  demand {isl.LoadMw,10:N1} MW  generation {isl.GenMw,10:N1} MW  "
                + (!isl.HasGeneration ? (isl.Feasible ? "no generation (no load)" : "NO GENERATION: load cannot be supplied")
                   : isl.Feasible ? "feasible" : "INFEASIBLE")
                + (isl.SecurityLpStatus is { } st ? $"  (security LP {st})" : ""));
            repIslands?.Row(isl.ReferenceBus, isl.BusCount, isl.LoadMw, isl.GenMw, isl.HasGeneration, isl.Feasible, isl.SecurityLpStatus?.ToString());
        }
    }
    // N109 (Ruling R1, Mark delegated 2026-10-04): rated lines that no dispatch can bring within their rating are left out
    // of the security LP (as the corrective redispatch leaves out what no generator can move) and named here, whatever
    // the outcome, with the range of flows any dispatch could give them. They stay overloaded at the dispatch below, so
    // "secure" never covers them. Printed only when there are some, so every other run's output is unchanged; the result
    // file gains its "unrelievable_lines" table only then too.
    if (res.UnrelievableLines.Count > 0)
    {
        Console.WriteLine($"  {res.UnrelievableLines.Count} rated line(s) cannot be brought within rating by any dispatch; left out of the security LP and still overloaded:");
        CliResultTable? repUnrelievable = rep?.Table("unrelievable_lines", "branch", "name", "rate_mw", "reachable_min_mw", "reachable_max_mw");
        foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.UnrelievableLine u in res.UnrelievableLines)
        {
            Console.WriteLine($"      branch {u.Branch,-5} {BranchDisplayName(u.Name, m.Branches[u.Branch].From, m.Branches[u.Branch].To),-28} rating {u.RateMw:N1} MW, any dispatch gives {u.ReachableMinMw:N1} .. {u.ReachableMaxMw:N1} MW");
            repUnrelievable?.Row(u.Branch, u.Name, u.RateMw, u.ReachableMinMw, u.ReachableMaxMw);
        }
        rep?.Set("unrelievable_line_count", res.UnrelievableLines.Count);
    }
    if (!res.Feasible)
    {
        // N111 (October 2026): on a connected case the message used to be "generation capability cannot meet demand" for
        // every infeasible result, including a security LP that is Infeasible because of the line limits (gb-synthetic:
        // 70,420 MW of capability for 39,291 MW of demand). The two causes are now told apart: no security LP ran (the
        // merit order itself fell short), or the LP ran and did not reach an optimum.
        if (res.Islands is not null)
            Console.WriteLine("  INFEASIBLE: at least one island has no dispatch that meets its demand (within its line limits, when they are enforced); see the island list.");
        else if (res.SecurityLpStatus is GridSim.Core.Numerics.LpStatus.Infeasible)
            Console.WriteLine("  INFEASIBLE: no dispatch within the units' output limits keeps every rated line within its rating (security LP Infeasible); '--no-limits' drops the line limits.");
        else if (res.SecurityLpStatus is { } lpStatus)
            Console.WriteLine($"  INFEASIBLE: the security LP stopped without proving an optimum (status {lpStatus}); no secure dispatch is reported.");
        else
            Console.WriteLine($"  INFEASIBLE: generation capability cannot meet demand ({m.Generators.Sum(g => g.Pmax):N1} MW of in-service capability for {res.TotalLoadMw:N1} MW of demand).");
        // F19: the cost-curve solver says when it stopped without an optimum (rather than proving infeasibility).
        if (res.SolverFailure is { } why) Console.WriteLine($"  solver: {why} (status {res.SecurityLpStatus?.ToString() ?? "n/a"})");
        // N172 (Ruling R1, Mark delegated 2026-10-04): an infeasible dispatch is a VALIDATION failure, not an input
        // error. The case loaded and the LP ran; the answer is "no secure dispatch exists", which PLAN rule 3 gives exit
        // 3 (as a NOT SECURE contingency verdict or a non-converged solve). It exited 1 (input error) before.
        Environment.ExitCode = 3;
        rep?.Complete();   // an infeasible dispatch is a finished result (exit 3), written with its island list
        return;
    }
    // N109: a dispatch that left lines out is secure only for the lines the LP kept; say so on the summary line.
    if (res.UnrelievableLines.Count > 0)
        Console.WriteLine($"  secure for every rated line except the {res.UnrelievableLines.Count} listed above (no dispatch can relieve them)");
    Console.WriteLine(costs is null
        ? $"  demand {res.TotalLoadMw:N0} MW  generation {res.TotalGenMw:N0} MW  total cost {res.TotalCost:N0} GBP/h" +
          (res.NetworkConstrained ? "  (network-constrained redispatch applied)" : "  (unconstrained merit order)")
        : $"  demand {res.TotalLoadMw:N0} MW  generation {res.TotalGenMw:N0} MW  total cost {res.TotalCost:N2} {money}/h" +
          (res.NetworkConstrained ? "  (network-constrained)" : "  (no line limit binds)"));
    rep?.Set("total_load_mw", res.TotalLoadMw).Set("total_generation_mw", res.TotalGenMw).Set(costs is null ? "total_cost_gbp_per_h" : "total_cost_per_h", res.TotalCost)   // D-DOC-139
        .Set("network_constrained", res.NetworkConstrained);
    Console.WriteLine("  dispatch (by output):");
    foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.GenDispatch d in res.Dispatch.Where(d => d.Pg > GridSim.Cli.CliDefaults.DcopfDispatchDisplayFloorMw).OrderByDescending(d => d.Pg).Take(top))
        Console.WriteLine(costs is null
            ? $"      gen bus {d.GenBus,-6} {d.Pg,8:N1} MW  @ {d.CostPerMwh,5:N0} GBP/MWh"
            : $"      gen bus {d.GenBus,-6} {d.Pg,8:N2} MW  marginal {d.CostPerMwh,9:N4} {money}/MWh");
    if (res.BindingLines.Count > 0)
    {
        Console.WriteLine("  binding line limits:");
        foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.LineBinding b in res.BindingLines.Take(top))
            Console.WriteLine($"      branch {b.Branch,-4} {BranchDisplayName(b.Name, m.Branches[b.Branch].From, m.Branches[b.Branch].To),-12} {b.FlowMw,8:N1} MW / {b.RateMw:N0} MVA");
    }

    // F19: nodal prices and shadow prices (only with --prices; the result file's price tables likewise).
    if (prices)
    {
        if (res.Prices is not { } pr)
            Console.WriteLine("  prices: not available (the dispatch did not reach an optimum with duals)");
        else
        {
            var byLmp = pr.Buses.OrderByDescending(p => p.Lmp).ThenBy(p => p.BusId).ToList();
            Console.WriteLine($"  nodal prices (LMP, {money}/MWh, lossless DC): {pr.Buses.Count} bus(es), "
                + (byLmp.Count > 0 ? $"highest {byLmp[0].Lmp:N4} at bus {byLmp[0].BusId}, lowest {byLmp[^1].Lmp:N4} at bus {byLmp[^1].BusId}" : "none"));
            foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.BusPrice p in byLmp.Take(top))
                Console.WriteLine($"      bus {p.BusId,-6} LMP {p.Lmp,10:N4}  (energy {p.EnergyComponent:N4}, congestion {p.CongestionComponent:N4})");
            if (pr.Lines.Count > 0)
            {
                Console.WriteLine($"  line shadow prices ({money}/MWh per MW of extra rating):");
                foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.LinePrice lp in pr.Lines.Take(top))
                    Console.WriteLine($"      branch {lp.Branch,-4} {BranchDisplayName(lp.Name, m.Branches[lp.Branch].From, m.Branches[lp.Branch].To),-12} {lp.FlowMw,8:N1} MW / {lp.RateMw:N0} MVA  shadow price {lp.ShadowPrice:N4}");
            }
        }
    }

    if (rep is not null)
    {
        foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.GenDispatch d in res.Dispatch) repDispatch!.Row(d.GenBus, d.Pg, d.CostPerMwh);
        foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.LineBinding b in res.BindingLines) repBinding!.Row(b.Branch, b.Name, b.FlowMw, b.RateMw);
        if (costs is not null) rep.Set("cost_source", costs).Set("cost_units", money);
        if (prices && res.Prices is { } pr)
        {
            // Named so the column says what it holds; with --costs the dispatch table's cost column is the marginal cost.
            CliResultTable repPrices = rep.Table("prices", "bus_id", "lmp_per_mwh", "energy_per_mwh", "congestion_per_mwh");
            foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.BusPrice p in pr.Buses) repPrices.Row(p.BusId, p.Lmp, p.EnergyComponent, p.CongestionComponent);
            CliResultTable repShadow = rep.Table("shadow_prices", "branch", "name", "flow_mw", "rate_mw", "shadow_price_per_mwh");
            foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.LinePrice lp in pr.Lines) repShadow.Row(lp.Branch, lp.Name, lp.FlowMw, lp.RateMw, lp.ShadowPrice);
        }
        rep.Complete();
    }
}

// F19 (October 2026): lay the generator cost curves named by --costs onto the model. "case" uses the case's own curves
// (MATPOWER gencost) and refuses a case where any in-service unit has none; anything else is a gridsim-costs/1 file laid
// over the case (GeneratorCostFile). Returns null (exit 1, message on stderr) on any problem.
GridModel? ApplyCostSource(GridModel m, string costs, string verb)
{
    if (costs.Equals("case", StringComparison.OrdinalIgnoreCase))
    {
        int missing = m.Generators.Count(g => g.Cost is null);
        if (missing > 0)
        {
            Console.Error.WriteLine($"[{verb}] --costs case: {missing} of {m.Generators.Count} in-service generator(s) carry no cost curve (the case has no mpc.gencost for them); give a cost file instead.");
            Environment.ExitCode = 1;
            return null;
        }
        return m;
    }
    try { return GridSim.Core.IO.Json.GeneratorCostFile.Apply(m, costs); }
    catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or IOException)
    {
        Console.Error.WriteLine($"[{verb}] --costs: {ex.Message}");
        Environment.ExitCode = 1;
        return null;
    }
}

// Load the positional case for the analysis verbs (a case directory, a .m file, or a named case).
// D-DOC-151 (October 2026): through LoadCaseArgument, so an existing folder that is not a known name and has no
// system.json is loaded as a case folder and the loader says what is wrong with it (input error, exit 1). `pf docs`
// used to answer "unknown case 'docs'" (a usage error) about a folder that plainly exists. Every other argument loads
// exactly as before (the folder-with-system.json, .m and named-case branches are the same calls).
GridModel? LoadAnalysisCase(List<string> a, string root, string verb, string usage)
{
    string? arg = AnalysisCasePositional(verb, a);
    if (arg is null) { Console.Error.WriteLine($"usage: {usage}"); Environment.ExitCode = 2; return null; }
    try
    {
        return LoadCaseArgument(arg, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return null; }
}

// cpf <case> [--step 0.25] [--min-step 1e-3] [--max-steps 200]
// R072: maximum loadability by stepping and bisection (ContinuationPowerFlow.MaxLoadability; D-DOC-189: not a
// predictor-corrector continuation power flow, whatever the verb and class are called): scales every bus's P and Q demand by
// lambda with the SLACK absorbing the extra generation, stepping up while the power flow converges and bisecting at
// the nose. This is a different question from `stress`, which re-dispatches generation at each load factor
// (GridScenario.AtLoad) on a fixed grid of factors; the two answers differ by design and both are labelled.
void RunCpf(List<string> a, string root)
{
    double step = FlagDouble(a, "--step", 0.25);
    double minStep = FlagDouble(a, "--min-step", 1e-3);
    int maxSteps = FlagInt(a, "--max-steps", 200);
    // F18: --pv-out <file.csv> also writes every converged point's bus voltages (the PV curves), from the same loop.
    string? pvOut = FlagString(a, "--pv-out");
    if (!(step > 0)) FailFlag<double>("--step", step.ToString(System.Globalization.CultureInfo.InvariantCulture), "a step above 0");
    if (!(minStep > 0) || minStep > step) FailFlag<double>("--min-step", minStep.ToString(System.Globalization.CultureInfo.InvariantCulture), "a value in (0, --step]");
    if (maxSteps < 1) FailFlag<int>("--max-steps", maxSteps.ToString(System.Globalization.CultureInfo.InvariantCulture), "at least 1");
    if (pvOut is not null && !pvOut.EndsWith(".csv", StringComparison.OrdinalIgnoreCase)) FailFlag<string>("--pv-out", pvOut, "a file name ending in .csv");
    GridModel? m = LoadAnalysisCase(a, root, "cpf", "gridsim cpf <case> [--step 0.25] [--min-step 1e-3] [--max-steps 200] [--pv-out <file.csv>]");
    if (m is null) return;

    // N161 (Ruling R1, Mark delegated 2026-10-04): every point is solved exactly as `stress` solves its load points, so
    // the two loadability verbs share one definition of a converged point: the contingency study option set
    // (ContingencyAnalysis.StudyOptions: 100 iterations, generator reactive limits on, 1e-8 pu) through the shared Newton
    // engine on the selected backend, wrapped in the on-load tap changer loop (skipped when the model has no OLTCs).
    // Before, cpf solved with the engine's defaults (30 iterations instead of 100, and no OLTC loop; reactive limits were
    // already on), so the two verbs could disagree about a point. Measured on every bundled case (r1-defaults notes): the
    // printed lambda is the same bits before and after; the change is the definition, not a number.
    IPowerFlowSolver cpfSolver = ContingencyAnalysis.WithOltcLoop(backend.NewtonSolver(m));
    PowerFlowOptions cpfOptions = ContingencyAnalysis.StudyOptions;
    // TracePvCurve runs the very loop MaxLoadability runs (its MaxLambda is the same bits), recording each point.
    GridSim.Core.Analysis.PvCurve? curve = pvOut is null ? null
        : GridSim.Core.Analysis.ContinuationPowerFlow.TracePvCurve(m, cpfSolver, cpfOptions, step, minStep, maxSteps);
    // D-DOC-129: the walk also says how it ended (bracketed to --min-step, or stopped by --max-steps); the multiplier is
    // the same bits as MaxLoadability's (the same loop).
    double lambda;
    GridSim.Core.Analysis.LoadabilityWalkEnd walkEnd;
    if (curve is not null) { lambda = curve.MaxLambda; walkEnd = curve.WalkEnd!; }
    else (lambda, walkEnd) = GridSim.Core.Analysis.ContinuationPowerFlow.MaxLoadabilityWithEnd(m, cpfSolver, cpfOptions, step, minStep, maxSteps);
    if (curve is not null)
    {
        WritePvCurveCsv(pvOut!, "lambda", new[] { (m.Name, curve.BusIds, (IReadOnlyList<(double, double[])>)curve.Points.Select(p => (p.Lambda, p.Vm)).ToList()) });
        Console.Error.WriteLine($"[cpf] PV curves: {curve.Points.Count} converged point(s) x {curve.BusIds.Count} bus(es) -> {Path.GetFullPath(pvOut!)}");
    }
    double baseMw = m.Buses.Sum(b => b.Pd);
    Console.WriteLine($"CPF - {m.Name} ({m.BusCount} buses)  [load scaled uniformly, slack absorbs the balance]");
    if (lambda <= 0)
    {
        // Not even the base case converged: there is no margin to report.
        Console.Error.WriteLine("cpf: the base case (lambda = 1) did not converge; no loadability margin.");
        Environment.ExitCode = 3;
        return;
    }
    // D-DOC-129 (October 2026): "nose bracketed to <min-step>" is said only when it is true, i.e. the walk ended because
    // its step fell below --min-step. When --max-steps ran out first, the line says so and gives what is known: with a
    // failed solve the nose lies between the printed lambda and the smallest lambda that failed; with none the nose was
    // never reached and the lambda is only a lower bound. Either way the requested bracket was not reached, so the run
    // exits 3 (below), the code of a solve that did not converge. A bracketed run prints exactly as before.
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string how = walkEnd.Bracketed
        ? $"nose bracketed to {minStep:G3}"
        : double.IsNaN(walkEnd.LowestFailedLambda)
            ? $"NOT bracketed: --max-steps {maxSteps} ran out with every solve converged, so lambda is only a lower bound"
            : $"NOT bracketed: --max-steps {maxSteps} ran out first; the nose lies between this lambda and {walkEnd.LowestFailedLambda.ToString("R", inv)}";
    Console.WriteLine($"  max loadability lambda = {lambda.ToString("R", inv)}  " +
        $"(base demand {baseMw:N1} MW -> {baseMw * lambda:N1} MW at the last converged point; {how})");
    Console.WriteLine($"  margin {(lambda - 1.0) * 100.0:F2}% above base load");
    // F10: the same numbers, at full precision (the margin and the demand at the nose are the printed expressions).
    CliOutput.Report?.Set("case", m.Name).Set("buses", m.BusCount).Set("step", step).Set("min_step", minStep).Set("max_steps", maxSteps)
        .Set("max_lambda", lambda).Set("base_demand_mw", baseMw).Set("demand_at_max_lambda_mw", baseMw * lambda)
        .Set("margin_pct", (lambda - 1.0) * 100.0).Set("nose_bracketed", walkEnd.Bracketed).Set("solves", walkEnd.Solves)
        .Set("lowest_failed_lambda", double.IsNaN(walkEnd.LowestFailedLambda) ? null : walkEnd.LowestFailedLambda).Complete();
    if (!walkEnd.Bracketed)
    {
        Console.Error.WriteLine($"cpf: --max-steps {maxSteps} ran out before the nose was bracketed to --min-step {minStep.ToString("G3", inv)}; " +
            "the lambda above is a lower bound, not the loadability limit. Raise --max-steps (or --min-step). Exit 3.");
        Environment.ExitCode = 3;   // CliExit.Verdict, written as the literal 3 that CliExitCodeContractTests reads
    }
    // D-DOC-010: the loop steps lambda up from the base load (lambda = 1) and bisects back only when a step fails, so a
    // largest converged lambda below 1 can only mean the base case itself did not converge and only a lighter load did.
    // That used to exit 0 with a negative margin ("margin -1.37% above base load" on data/intl/france), which a script
    // reads as success. It is a convergence failure of the case as given: the numbers above are kept (they say how far
    // the load must fall before the case solves), and the run exits 3, the documented code for a power flow that did
    // not converge. Nothing computed changes: lambda and the margin are the same bits.
    if (lambda < 1.0)
    {
        Console.Error.WriteLine($"cpf: the base case (lambda = 1) did not converge; only a lighter load did (largest converged lambda " +
            $"{lambda.ToString("R", System.Globalization.CultureInfo.InvariantCulture)}, margin {(lambda - 1.0) * 100.0:F2}%), so the case as given has no " +
            "loadability margin. Exit 3.");
        Environment.ExitCode = 3;   // CliExit.Verdict, written as the literal 3 that CliExitCodeContractTests reads
    }
}

// F18 (October 2026): write PV curves as one long CSV: case, the load multiplier (named by multiplierColumn: "lambda" for
// cpf, "load_factor" for stress), bus id, voltage magnitude in pu. One row per converged point and bus, in the order
// solved; numbers in round-trip form, invariant culture.
void WritePvCurveCsv(string path, string multiplierColumn, IEnumerable<(string Case, IReadOnlyList<int> BusIds, IReadOnlyList<(double, double[])> Points)> cases)
{
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string full = CliFiles.Output(path, "PV-curve CSV");   // D-DOC-072: the one output policy (creates the folder)
    using var w = new StreamWriter(full);
    w.WriteLine($"case,{multiplierColumn},bus_id,vm_pu");
    foreach ((string caseName, IReadOnlyList<int> busIds, IReadOnlyList<(double, double[])> points) in cases)
    {
        string c = CsvField(caseName);
        foreach ((double mult, double[] vm) in points)
            for (int i = 0; i < vm.Length && i < busIds.Count; i++)
                w.WriteLine($"{c},{mult.ToString("R", inv)},{busIds[i].ToString(inv)},{vm[i].ToString("R", inv)}");
    }
}

// A CSV field: quoted (with doubled quotes) when it holds a comma, a quote or a line break.
static string CsvField(string s) =>
    s.Contains(',') || s.Contains('"') || s.Contains('\n') || s.Contains('\r')
        ? "\"" + s.Replace("\"", "\"\"", StringComparison.Ordinal) + "\"" : s;

// pf <case> [--distributed-slack pmax|pg|equal] [--switched-shunts <file.json>] [--top 12]
// F22 (October 2026): one AC power flow on the selected engine (the shared dense / sparse rule), 100 iterations with
// reactive limits on (the fault and protection verbs' set), printed: convergence, losses, the voltage range and the
// --top lowest voltages. --distributed-slack shares the real-power balance among the units by participation factors
// (DistributedSlackPowerFlow); --switched-shunts regulates discrete shunt banks into their voltage bands
// (SwitchedShuntPowerFlow). Both wrap the unchanged engine. Exit 0 converged (and shunts settled); 3 not converged or
// shunts not settled; 1 load or input-file error; 2 usage.
void RunPf(List<string> a, string root)
{
    const string usage = "gridsim pf <case> [--distributed-slack pmax|pg|equal] [--switched-shunts <file.json>] [--top 12]";
    RequireVerbFlags("pf", a, "--distributed-slack", "--switched-shunts", "--top");
    string? ds = FlagString(a, "--distributed-slack");
    string? ssPath = FlagString(a, "--switched-shunts");
    int top = FlagCount(a, "--top", 12, 0);
    if (top < 0) FailFlag<int>("--top", top.ToString(System.Globalization.CultureInfo.InvariantCulture), "0 or more");
    ParticipationRule? rule = ds?.ToLowerInvariant() switch
    {
        null => null,
        "pmax" => ParticipationRule.Pmax,
        "pg" => ParticipationRule.Pg,
        "equal" => ParticipationRule.Equal,
        _ => FailFlag<ParticipationRule>("--distributed-slack", ds!, "pmax, pg or equal"),
    };
    GridModel? m = LoadAnalysisCase(a, root, "pf", usage);
    if (m is null) return;
    IReadOnlyList<SwitchedShunt>? shunts = null;
    if (ssPath is not null)
    {
        try { shunts = SwitchedShuntPowerFlow.ReadFile(File.ReadAllText(ssPath), Path.GetFileName(ssPath)); }
        catch (Exception ex) when (ex is IOException or InvalidDataException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"pf: --switched-shunts: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }

    // Tranche A: --shunt-control gives pf the .raw file's regulating switched shunts, as a --switched-shunts file would.
    if (Gated.ShuntsOf(m) is { Count: > 0 } fileBanks)
    {
        if (shunts is not null)
        {
            Console.Error.WriteLine("pf: --switched-shunts and --shunt-control both give switched shunts; give one.");
            Environment.Exit(2);
        }
        shunts = fileBanks;
    }

    IPowerFlowSolver solver = backend.Solver(m);
    DistributedSlackPowerFlow? dsp = null;
    SwitchedShuntPowerFlow? ssp = null;
    PowerFlowResult r;
    try
    {
        if (rule is ParticipationRule pr) solver = dsp = new DistributedSlackPowerFlow(solver, pr);
        if (shunts is not null) solver = ssp = new SwitchedShuntPowerFlow(solver, shunts);
        r = solver.Solve(m, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
    }
    catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
    {
        Console.Error.WriteLine($"pf: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }

    Console.WriteLine($"Power flow - {m.Name} ({m.BusCount} buses)"
        + (dsp is not null ? $"  [distributed slack, factors by {ds!.ToLowerInvariant()}]" : "")
        + (ssp is not null ? $"  [{shunts!.Count} switched shunt(s)]" : ""));
    // D-DOC-150: a converged sweep is labelled by its own test (the voltage step), not left to read as a mismatch test.
    Console.WriteLine($"  {(r.Converged ? r.ConvergedLabel() : $"NOT CONVERGED ({r.Status})")} in {r.Iterations} iteration(s), mismatch {r.MaxMismatch:E2} pu   "
        + $"losses {r.TotalLossMw:F3} MW / {r.TotalLossMvar:F3} MVAr");
    if (r.Vm.Length > 0) Console.WriteLine($"  voltage range {r.Vm.Min():F4} - {r.Vm.Max():F4} pu");
    if (dsp is not null)
    {
        Console.WriteLine($"  distributed slack: {dsp.LastPasses} pass(es), imbalance {dsp.LastImbalanceMw:F4} MW shared by "
            + $"{dsp.LastFactors.Count(f => f > 0)} unit(s)" + (dsp.LastNote is { } dn ? $"   NOT SETTLED: {dn}" : ""));
        var units = Enumerable.Range(0, m.Generators.Count).Where(i => dsp.LastFactors[i] > 0)
            .OrderByDescending(i => Math.Abs(dsp.LastDispatchMw[i] - m.Generators[i].Pg)).Take(top);
        foreach (int i in units)
            Console.WriteLine($"      gen {i,-4} bus {m.Generators[i].Bus,-6} factor {dsp.LastFactors[i]:F4}  {m.Generators[i].Pg,9:F3} -> {dsp.LastDispatchMw[i],9:F3} MW");
    }
    if (ssp is not null)
    {
        Console.WriteLine($"  switched shunts: {ssp.LastPasses} pass(es), {(ssp.ShuntsSettled ? "settled" : $"NOT SETTLED: {ssp.LastNote}")}");
        for (int i = 0; i < shunts!.Count; i++)
        {
            SwitchedShunt s = shunts[i];
            int bi = r.BusIds.ToList().IndexOf(s.ControlsBus ?? s.Bus);
            Console.WriteLine($"      {(s.Name ?? $"bus {s.Bus}"),-16} bus {s.Bus,-6} steps {ssp.LastSteps[i],3} of {s.MinSteps}..{s.MaxSteps}  "
                + $"{s.AddedMvar(ssp.LastSteps[i]),9:F2} MVAr at 1 pu   V {(bi >= 0 ? r.Vm[bi] : double.NaN):F4} pu (band {s.VminPu}-{s.VmaxPu})");
        }
    }
    if (top > 0 && r.Vm.Length > 0)
    {
        Console.WriteLine($"  lowest voltages:");
        foreach (int i in Enumerable.Range(0, r.Vm.Length).OrderBy(i => r.Vm[i]).ThenBy(i => i).Take(top))
            Console.WriteLine($"      bus {r.BusIds[i],-6} {r.Vm[i]:F4} pu  {r.VaDeg[i],9:F3} deg");
    }
    bool ok = r.Converged && (ssp is null || ssp.ShuntsSettled);
    if (!ok) Environment.ExitCode = 3;

    // N122 (October 2026): the result file, from the same values the console shows but complete (every bus, every
    // participating unit, every switched shunt) and at full precision. Written only for a converged solve (a run that
    // does not converge has no result: F10 writes nothing and says so on stderr); a converged run whose switched shunts
    // did not settle is a finished result with exit 3, written with the exit code inside, as every writer verb does.
    CliResult? prep = CliOutput.Report;
    if (prep is null || !r.Converged) return;
    prep.Set("case", m.Name).Set("buses", m.BusCount).Set("converged", r.Converged).Set("iterations", r.Iterations)
        .Set("max_mismatch_pu", r.MaxMismatch).Set("loss_mw", r.TotalLossMw).Set("loss_mvar", r.TotalLossMvar)
        .Set("vmin_pu", r.Vm.Length > 0 ? r.Vm.Min() : null).Set("vmax_pu", r.Vm.Length > 0 ? r.Vm.Max() : null)
        .Set("distributed_slack", dsp is null ? null : ds!.ToLowerInvariant())
        .Set("switched_shunts", ssp is null ? null : shunts!.Count)
        .Set("shunts_settled", ssp is null ? null : ssp.ShuntsSettled);
    if (dsp is not null)
        prep.Set("slack_passes", dsp.LastPasses).Set("slack_imbalance_mw", dsp.LastImbalanceMw).Set("slack_note", dsp.LastNote);
    if (ssp is not null) prep.Set("shunt_passes", ssp.LastPasses).Set("shunt_note", ssp.LastNote);
    CliResultTable pbuses = prep.Table("buses", "bus", "vm_pu", "va_deg", "p_inj_mw", "q_inj_mvar");
    for (int i = 0; i < r.Vm.Length; i++) pbuses.Row(r.BusIds[i], r.Vm[i], r.VaDeg[i], r.PInjMw[i], r.QInjMvar[i]);
    if (dsp is not null)
    {
        CliResultTable units = prep.Table("slack_units", "gen", "bus", "factor", "scheduled_mw", "dispatch_mw");
        for (int i = 0; i < m.Generators.Count; i++)
            if (dsp.LastFactors[i] > 0) units.Row(i, m.Generators[i].Bus, dsp.LastFactors[i], m.Generators[i].Pg, dsp.LastDispatchMw[i]);
    }
    if (ssp is not null)
    {
        CliResultTable st = prep.Table("switched_shunts", "name", "bus", "steps", "min_steps", "max_steps", "mvar_at_1pu", "vmin_pu", "vmax_pu");
        for (int i = 0; i < shunts!.Count; i++)
        {
            SwitchedShunt s = shunts[i];
            st.Row(s.Name ?? "", s.Bus, ssp.LastSteps[i], s.MinSteps, s.MaxSteps, s.AddedMvar(ssp.LastSteps[i]), s.VminPu, s.VmaxPu);
        }
    }
    prep.Complete();
}

// dcpf <case> [--top 12] [--out <branches.csv>]
// F18 (October 2026): the DC power flow (Core DcPowerFlow, which reuses DistributionFactors: one DC model in GridSim).
// Prints each DC island's balance and the largest branch flows with their loading against RateA. --out writes every
// branch flow to the given .csv and every bus angle and net injection to <stem>-buses.csv beside it. Exit 1 when the
// case does not load or the DC model cannot be formed; exit 3 when an island carries load but has no generator (the
// linear model would make its reference bus inject power that has no source); overloads are reported, not an error.
void RunDcpf(List<string> a, string root)
{
    const string usage = "gridsim dcpf <case> [--top 12] [--out <file.csv|file.json>] [--json <file>] [--csv <file>]";
    // --out / --json / --csv are taken off the argument list by the shared result writer (F10) before this runs; they
    // stay in the accepted list so the refusal message names them.
    RequireVerbFlags("dcpf", a, "--top", "--out", "--json", "--csv");
    int top = FlagCount(a, "--top", 12, 0);
    if (top < 0) FailFlag<int>("--top", top.ToString(System.Globalization.CultureInfo.InvariantCulture), "0 or more");
    GridModel? m = LoadAnalysisCase(a, root, "dcpf", usage);
    if (m is null) return;

    GridSim.Core.Analysis.DcPowerFlowResult r;
    try { r = GridSim.Core.Analysis.DcPowerFlow.Solve(m); }
    catch (InvalidOperationException ex) { Console.Error.WriteLine($"dcpf: {ex.Message}"); Environment.ExitCode = 1; return; }

    Console.WriteLine($"DC power flow - {m.Name} ({m.BusCount} buses, {m.Branches.Count} branches)  [linear: series reactance only; R, charging, shunts, taps and phase shifts ignored; |V| = 1 pu; lossless]");
    int dead = 0;
    foreach (GridSim.Core.Analysis.DcIslandBalance isl in r.Islands)
    {
        bool unsupplied = !isl.HasGeneration && isl.LoadMw != 0.0;
        if (unsupplied) dead++;
        Console.WriteLine($"  island ref bus {isl.ReferenceBusId,-6} {isl.BusCount,5} buses  demand {isl.LoadMw,10:N1} MW  scheduled generation {isl.ScheduledGenerationMw,10:N1} MW  " +
            $"reference injects {isl.ReferenceInjectionMw,10:N1} MW" + (unsupplied ? "  NO GENERATION: load cannot be supplied" : ""));
    }
    int rated = 0, over = 0;
    for (int l = 0; l < m.Branches.Count; l++)
    {
        if (m.Branches[l].RateAMva > 0) rated++;
        if (r.LoadingPercent[l] > GridSim.Core.Analysis.ContingencyAnalysis.OverloadThresholdPercent) over++;
    }
    Console.WriteLine($"  {over} of {rated} rated branch(es) above {GridSim.Core.Analysis.ContingencyAnalysis.OverloadThresholdPercent:0}% of RateA");
    if (top > 0)
    {
        Console.WriteLine("  largest flows:");
        foreach (int l in Enumerable.Range(0, m.Branches.Count).OrderByDescending(l => Math.Abs(r.FlowMw[l])).ThenBy(l => l).Take(top))
        {
            Branch br = m.Branches[l];
            string name = string.IsNullOrEmpty(br.Name) ? $"{br.From}-{br.To}" : br.Name;
            Console.WriteLine($"      branch {l,-5} {name,-16} {br.From,6} -> {br.To,-6} {r.FlowMw[l],10:F2} MW  " +
                (br.RateAMva > 0 ? $"{r.LoadingPercent[l],7:F1}% of {br.RateAMva:N0} MVA" : "unrated"));
        }
    }

    // F10: the result goes through the shared writer. The CSV form keeps the files dcpf --out wrote before (F18), byte
    // for byte: the branch table is the main file (index,name,from,to,flow_mw,rate_mva,loading_pct) and the bus table is
    // <stem>-buses.csv (bus_id,va_deg,p_inj_mw), numbers in round-trip form. The writer adds <stem>-islands.csv and
    // <stem>-summary.csv beside them, and --json writes the same tables as one document.
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("buses", m.BusCount).Set("branches", m.Branches.Count)
            .Set("rated_branches", rated).Set("overloaded_branches", over)
            .Set("overload_threshold_pct", GridSim.Core.Analysis.ContingencyAnalysis.OverloadThresholdPercent)
            .Set("unsupplied_islands", dead);
        CliResultTable branches = rep.Table("branches", "index", "name", "from", "to", "flow_mw", "rate_mva", "loading_pct");
        for (int l = 0; l < m.Branches.Count; l++)
        {
            Branch br = m.Branches[l];
            branches.Row(l, br.Name ?? "", br.From, br.To, r.FlowMw[l], br.RateAMva, r.LoadingPercent[l]);
        }
        CliResultTable buses = rep.Table("buses", "bus_id", "va_deg", "p_inj_mw");
        for (int i = 0; i < r.BusIds.Count; i++) buses.Row(r.BusIds[i], r.VaDeg[i], r.PInjMw[i]);
        CliResultTable islandTable = rep.Table("islands", "reference_bus", "buses", "load_mw", "scheduled_generation_mw", "reference_injection_mw", "has_generation");
        foreach (GridSim.Core.Analysis.DcIslandBalance isl in r.Islands)
            islandTable.Row(isl.ReferenceBusId, isl.BusCount, isl.LoadMw, isl.ScheduledGenerationMw, isl.ReferenceInjectionMw, isl.HasGeneration);
        rep.Complete();
    }

    if (dead > 0)
    {
        Console.Error.WriteLine($"dcpf: {dead} island(s) carry load but have no generator, so the DC solution has no physical meaning there.");
        Environment.ExitCode = 3;
    }
}

// zonal <pypsa-gb-zonal|folder>
// S2 / P02 (October 2026): show a PyPSA-GB zonal transport model (Core PypsaGbZonal): its zones, its links and the
// transfer capacity across each boundary cut (boundaries.json, derived from the official ETYS boundary GIS lines). The
// model has no impedances, so there is no power flow to run: this verb only reports what the files hold, and every AC
// verb refuses the model (LoadNamed). Exit 0 shown; 1 when the files do not load; 2 on a usage error.
void RunZonal(List<string> a, string root)
{
    const string usage = "gridsim zonal <pypsa-gb-zonal|folder> [--out <file.csv|file.json>] [--json <file>] [--csv <file>]";
    // --out / --json / --csv are taken off the argument list by the shared result writer (F10) before this runs; they
    // stay in the accepted list so the refusal message names them.
    RequireVerbFlags("zonal", a, "--out", "--json", "--csv");
    List<string> pos = Positionals(a).Skip(1).ToList();
    if (pos.Count != 1) { Console.Error.WriteLine("usage: " + usage); Environment.ExitCode = 2; return; }
    string arg = pos[0];
    string folder = arg.Equals(GridSim.Core.IO.PyPsa.GbReferenceModels.PypsaZonalId, StringComparison.OrdinalIgnoreCase)
        ? Path.Combine(root, "data", GridSim.Core.IO.PyPsa.GbReferenceModels.PypsaZonalRelativeDir)
        : arg;
    if (!Directory.Exists(folder))
    {
        Console.Error.WriteLine($"error: zonal: '{arg}' is neither {GridSim.Core.IO.PyPsa.GbReferenceModels.PypsaZonalId} nor a folder (full path {Path.GetFullPath(folder)}).");
        Environment.ExitCode = 1;
        return;
    }

    GridSim.Core.IO.PyPsa.PypsaGbZonalNetwork z;
    try { z = GridSim.Core.IO.PyPsa.PypsaGbZonal.Load(folder, arg.Equals(GridSim.Core.IO.PyPsa.GbReferenceModels.PypsaZonalId, StringComparison.OrdinalIgnoreCase) ? GridSim.Core.IO.PyPsa.GbReferenceModels.PypsaZonalId : CaseFileTag(arg)); }
    catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException)
    {
        Console.Error.WriteLine($"error: zonal: cannot load '{arg}': {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }

    int external = z.Links.Count(l => l.External);
    Console.WriteLine($"Zonal transport model - {z.Name} ({z.Zones.Count} zones, {z.Links.Count} links: {z.Links.Count - external} between zones, {external} interconnectors)");
    Console.WriteLine($"  [not AC solvable: {GridSim.Core.IO.PyPsa.PypsaGbZonalNetwork.NotAcSolvableReason}]");
    Console.WriteLine("  zones (name, latitude, longitude):");
    foreach (GridSim.Core.IO.PyPsa.PypsaGbZone zone in z.Zones)
        Console.WriteLine($"      {zone.Name,-6} {zone.LatDeg,8:F3} {zone.LonDeg,8:F3}"
            + (zone.LayoutClamped ? "  (outside the GB layout box: drawn on its edge)" : ""));   // finding 56
    Console.WriteLine("  links (name, from, to, carrier, capacity MW, reverse capacity MW):");
    foreach (GridSim.Core.IO.PyPsa.PypsaGbLink l in z.Links)
        Console.WriteLine($"      {l.Name,-12} {l.Bus0,-12} -> {l.Bus1,-12} {l.Carrier,-3} {l.PNomMw,8:N0} {-l.PMinPu * l.PNomMw,8:N0}" + (l.External ? "  (interconnector)" : ""));
    if (z.Boundaries.Count == 0) Console.WriteLine("  no boundary cuts defined for this model.");
    else
    {
        Console.WriteLine("  boundary transfer capacity (links crossing each cut; north to south / south to north, MW):");
        foreach (GridSim.Core.IO.PyPsa.PypsaGbZonalBoundary b in z.Boundaries)
            Console.WriteLine($"      {b.Name,-36} {b.NorthToSouthMw,8:N0} / {b.SouthToNorthMw,8:N0}   ({string.Join(", ", b.Links.Select(x => x.Branch))})");
    }

    // F10: the result goes through the shared writer, every row and number complete.
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("model", z.Name).Set("zones", z.Zones.Count).Set("links", z.Links.Count)
            .Set("interconnectors", external).Set("ac_solvable", GridSim.Core.IO.PyPsa.PypsaGbZonalNetwork.IsAcSolvable);
        CliResultTable zones = rep.Table("zones", "name", "lat_deg", "lon_deg", "v_nom_kv");
        foreach (GridSim.Core.IO.PyPsa.PypsaGbZone zone in z.Zones) zones.Row(zone.Name, zone.LatDeg, zone.LonDeg, zone.VNomKv);
        CliResultTable links = rep.Table("links", "name", "bus0", "bus1", "carrier", "p_nom_mw", "p_min_pu", "interconnector");
        foreach (GridSim.Core.IO.PyPsa.PypsaGbLink l in z.Links) links.Row(l.Name, l.Bus0, l.Bus1, l.Carrier, l.PNomMw, l.PMinPu, l.External);
        CliResultTable bounds = rep.Table("boundaries", "boundary", "north_to_south_mw", "south_to_north_mw", "links");
        foreach (GridSim.Core.IO.PyPsa.PypsaGbZonalBoundary b in z.Boundaries)
            bounds.Row(b.Name, b.NorthToSouthMw, b.SouthToNorthMw, string.Join(";", b.Links.Select(x => x.Branch)));
        rep.Complete();
    }
}

// convert <input.m|input.raw|input.uct|case-dir|case> <output.m|output.raw|output.json|output-dir>
// Export pack (October 2026): an output ending in .raw is written as PSS/E RAW revision 33 (PsseRawWriter, with the
// devices the RAW reader models) and read back with tap and shunt control applied; RAW keeps lines and transformers in
// separate sections, so the read-back is compared with the input in the file's order (PsseRawWriter.InFileOrder), and a
// second line says whether the input in its own order also solves to the same bits.
// N299 (LF5, October 2026; Ruling R1): an output ending in .json is written as a JSON v2 case (V2CaseWriter: the manifest
// at that path and <stem>.network.json beside it), which carries the N234 fault sequence data v1 cannot; its proof adds a
// bit-for-bit comparison of that data (V2CaseWriter.FirstSequenceDifference), which the power flow cannot see. N321 (LF7):
// the v2 output also carries the asset-dynamics and protection bundles (local templates, bindings, element templates,
// placed devices); a bundle the writer cannot represent exactly is left out whole, with a note.
// F24 (October 2026): write a case as MATPOWER (.m output) or as a JSON case folder (any other output), then PROVE the
// conversion: the written file is read back with the Core loaders and both are solved with the contingency family's
// steady-state solver (StudyOptions, the OLTC loop), and every voltage, angle, injection, loss and line flow must be the
// same bits. A mismatch (for example a ZIP load or OLTCs, which MATPOWER cannot hold) exits 3 naming the first
// difference; the output is kept so it can be inspected. Never overwrites (an existing .m file, or a folder that is not
// empty, exits 2). What the target format cannot carry is printed as notes (and written into a .m file as comments).
// Export pack (October 2026): an output ending in .xml is written as CGMES RDF/XML (CgmesWriter) and read back through the
// CIM reader with the SV starting voltages and the ratings (CgmesWriter.ReadBackOptions); the read-back numbers buses 1..n
// and lists lines before transformers, so it is compared with CgmesWriter.InFileOrder(input). A model CGMES cannot hold
// exactly (devices the CIM reader does not rebuild, a bus with no base voltage, ...) is refused with every reason listed
// and nothing written (exit 1, as the RAW writer's refusals).
void RunConvert(List<string> a, string root)
{
    const string usage = "gridsim convert <input.m|input.raw|input.uct|case-dir|case> <output.m|output.raw|output.xml|output.json|output-dir> [--public [--provenance <manifest.json>]]";
    // --json / --csv (F10) are taken off the argument list by the shared result writer before this runs; convert does
    // not take --out (its second positional argument is the output), so --out is refused here.
    RequireVerbFlags("convert", a, "--json", "--csv", "--public", "--provenance");
    // Export pack slice 2 (October 2026): --public writes only what a provenance manifest traces to published sources
    // (PublicExportGate). --public takes no value, so it is taken off before Positionals (which would swallow the token
    // after it); --provenance names the manifest and means nothing without --public.
    bool toPublic = a.Remove("--public");
    string? provenanceArg = FlagString(a, "--provenance");
    if (provenanceArg is not null && !toPublic)
    {
        Console.Error.WriteLine("error: convert: --provenance names the manifest of a public export and is read only with --public.");
        Environment.ExitCode = 2;
        return;
    }
    List<string> pos = Positionals(a).Skip(1).ToList();
    if (pos.Count != 2) { Console.Error.WriteLine("usage: " + usage); Environment.ExitCode = 2; return; }
    string input = pos[0], output = pos[1];
    bool toMatpower = output.EndsWith(".m", StringComparison.OrdinalIgnoreCase);
    bool toV2 = output.EndsWith(".json", StringComparison.OrdinalIgnoreCase);   // N299: a JSON v2 case manifest
    bool toRaw = output.EndsWith(".raw", StringComparison.OrdinalIgnoreCase);   // export pack: PSS/E RAW revision 33
    bool toCgmes = output.EndsWith(".xml", StringComparison.OrdinalIgnoreCase); // export pack: CGMES RDF/XML
    if (File.Exists(output) || (Directory.Exists(output) && Directory.EnumerateFileSystemEntries(output).Any()))
    {
        Console.Error.WriteLine($"error: convert refuses to overwrite '{output}' (it exists{(Directory.Exists(output) ? " and is not empty" : "")}); choose a new output.");
        Environment.ExitCode = 2;
        return;
    }
    // N299: a v2 output also writes its network file beside the manifest; that one is never overwritten either. And the
    // proof reads the written case back through the v2 loader, which needs the v2 schemas: without them nothing is
    // written (exit 1, the validate verb's rule).
    string? v2Schemas = null;
    if (toV2)
    {
        string networkOut = Path.Combine(Path.GetDirectoryName(Path.GetFullPath(output))!, GridSim.Core.IO.Json.V2CaseWriter.NetworkFileNameFor(output));
        if (File.Exists(networkOut) || Directory.Exists(networkOut))
        {
            Console.Error.WriteLine($"error: convert refuses to overwrite '{networkOut}' (the network file of the v2 case '{output}' exists); choose a new output.");
            Environment.ExitCode = 2;
            return;
        }
        v2Schemas = FindV2Schemas(root);
        if (v2Schemas is null)
        {
            Console.Error.WriteLine("error: convert: a JSON v2 output is proved by reading it back through the v2 loader, which needs the v2 schemas "
                + "(schemas/v2 beside the program or above it, or above the current folder), and none was found; nothing was written.");
            Environment.ExitCode = 1;
            return;
        }
    }

    // Export pack slice 2: a public export needs its provenance manifest; its absence is refused before the case is even
    // loaded (exit 1, nothing written), so a case that has none (gb-full) fails loud at once.
    string? provenancePath = null;
    if (toPublic)
    {
        provenancePath = provenanceArg ?? DefaultProvenancePath(input, root);
        if (provenancePath is null)
        {
            Console.Error.WriteLine($"error: convert --public: '{input}' is a built-in case with no case folder, so it has no default provenance manifest; "
                + "give one with --provenance <manifest.json>. Nothing was written.");
            Environment.ExitCode = 1;
            return;
        }
        if (!File.Exists(provenancePath))
        {
            Console.Error.WriteLine($"error: convert --public: no provenance manifest at '{provenancePath}'. A public export keeps only what a "
                + $"{GridSim.Core.IO.Provenance.ProvenanceManifest.Schema} manifest traces to published sources, so without one nothing is public. Nothing was written.");
            Environment.ExitCode = 1;
            return;
        }
    }

    GridModel m;
    IReadOnlyList<MatpowerDcLine> dcLines = Array.Empty<MatpowerDcLine>();
    try
    {
        bool isCaseDir = Directory.Exists(input) && File.Exists(Path.Combine(input, "system.json"));
        if (isCaseDir) m = Gated.Dir(input);
        else if (input.EndsWith(".m", StringComparison.OrdinalIgnoreCase))
        {
            MatpowerParseResult parsed = Gated.MatpowerDetailed(input);
            m = parsed.Model;
            dcLines = parsed.DcLines;
        }
        else if (input.EndsWith(".raw", StringComparison.OrdinalIgnoreCase)) m = Gated.Psse(input);   // Tranche A
        else if (input.EndsWith(".uct", StringComparison.OrdinalIgnoreCase)) m = Gated.Ucte(input);   // Tranche A
        else m = LoadNamed(input, root);
    }
    catch (Exception ex) when (ex is IOException or InvalidDataException or ArgumentException or UnauthorizedAccessException)
    {
        Console.Error.WriteLine($"error loading case '{input}': {ex.Message}");
        Environment.ExitCode = CliExit.CaseLoadFailure(ex);   // D-DOC-130: an unknown case name is 2, an unloadable file 1
        return;
    }

    // Export pack slice 2: the PUBLIC export gate, before anything is written. No manifest means no public export at all
    // (exit 1, nothing written): a manifest is evidence, and nothing here makes provenance up.
    IReadOnlyList<string> publicStripped = Array.Empty<string>();
    if (toPublic)
    {
        try
        {
            var manifest = GridSim.Core.IO.Provenance.ProvenanceManifest.Load(provenancePath!);
            var gated = GridSim.Core.IO.Provenance.PublicExportGate.Apply(m, manifest);
            m = gated.Model;
            var lines = new List<string>(gated.Stripped);
            if (dcLines.Count > 0)
            {
                lines.Add($"{dcLines.Count} MATPOWER DC line(s) stripped (the manifest has no section for them).");
                dcLines = Array.Empty<MatpowerDcLine>();
            }
            publicStripped = lines;
        }
        catch (Exception ex) when (ex is IOException or InvalidDataException)
        {
            Console.Error.WriteLine($"error: convert --public: {ex.Message} Nothing was written.");
            Environment.ExitCode = 1;
            return;
        }
    }

    IReadOnlyList<string> notes;
    GridSim.Core.IO.Psse.PsseWriteResult? rawWritten = null;
    GridSim.Core.IO.Cim.CgmesWriteResult? cgmesWritten = null;
    try
    {
        if (toCgmes)
        {
            cgmesWritten = GridSim.Core.IO.Cim.CgmesWriter.Write(m);   // refuses (InvalidDataException) before writing anything
            string full = Path.GetFullPath(output);
            Directory.CreateDirectory(Path.GetDirectoryName(full)!);
            using (var fs = new FileStream(full, FileMode.CreateNew, FileAccess.Write))
            using (var sw = new StreamWriter(fs))
                sw.Write(cgmesWritten.Text);
            var all = new List<string>(cgmesWritten.Notes);
            if (dcLines.Count > 0) all.Add($"{dcLines.Count} DC line(s) (mpc.dcline) not written: a MATPOWER DC line has no CGMES equivalent this writer writes.");
            notes = all;
        }
        else if (toRaw)
        {
            rawWritten = GridSim.Core.IO.Psse.PsseRawWriter.Write(m);
            string full = Path.GetFullPath(output);
            Directory.CreateDirectory(Path.GetDirectoryName(full)!);
            using (var fs = new FileStream(full, FileMode.CreateNew, FileAccess.Write))
            using (var sw = new StreamWriter(fs))
                sw.Write(rawWritten.Text);
            var all = new List<string>(rawWritten.Notes);
            if (dcLines.Count > 0) all.Add($"{dcLines.Count} DC line(s) (mpc.dcline) not written: a MATPOWER DC line has no PSS/E RAW record.");
            notes = all;
        }
        else if (toMatpower)
        {
            MatpowerWriteResult w = MatpowerWriter.Write(m, dcLines);
            string full = Path.GetFullPath(output);
            Directory.CreateDirectory(Path.GetDirectoryName(full)!);
            using (var fs = new FileStream(full, FileMode.CreateNew, FileAccess.Write))
            using (var sw = new StreamWriter(fs))
                sw.Write(w.Text);
            notes = w.Notes;
        }
        else if (toV2)
        {
            var all = new List<string>(GridSim.Core.IO.Json.V2CaseWriter.Write(m, output).Notes);
            if (dcLines.Count > 0) all.Add($"{dcLines.Count} DC line(s) (mpc.dcline) not written: JSON v2 has no DC line element.");
            notes = all;
        }
        else
        {
            var all = new List<string>(JsonCaseWriter.WriteDirectory(m, output));
            if (dcLines.Count > 0) all.Add($"{dcLines.Count} DC line(s) (mpc.dcline) not written: JSON v1 has no DC line element.");
            notes = all;
        }
    }
    catch (Exception ex) when (ex is IOException or InvalidDataException or UnauthorizedAccessException)
    {
        Console.Error.WriteLine($"error: convert could not write '{output}': {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }

    Console.WriteLine($"converted {input} -> {output}: {m.BusCount} buses, {m.AllGenerators.Count} generators ({m.OutOfServiceGenerators.Count} out of service), {m.Branches.Count} branches");
    foreach (string n in notes) Console.WriteLine("  note: " + n);
    // F10: what was converted, the notes, and (below) the round-trip proof. A failed proof is a finished result too
    // (exit 3), written with the first difference.
    CliResult? rep = CliOutput.Report;
    rep?.Set("input", input).Set("output", output).Set("format", toCgmes ? "cgmes" : toRaw ? "psse-raw" : toMatpower ? "matpower" : toV2 ? "json-v2" : "json")
        .Set("buses", m.BusCount).Set("generators", m.AllGenerators.Count).Set("out_of_service_generators", m.OutOfServiceGenerators.Count)
        .Set("branches", m.Branches.Count);
    CliResultTable? repNotes = rep?.Table("notes", "note");
    if (repNotes is not null) foreach (string n in notes) repNotes.Row(n);
    // Export pack slice 2: a public export says which manifest it used and everything the gate left out.
    if (toPublic)
    {
        Console.WriteLine($"  public export: provenance manifest {provenancePath}; {(publicStripped.Count == 0 ? "nothing stripped" : $"{publicStripped.Count} kind(s) of element stripped or zeroed")}");
        foreach (string n in publicStripped) Console.WriteLine("  public: " + n);
        rep?.Set("public", true).Set("provenance", provenancePath);
        CliResultTable? repStripped = rep?.Table("public_stripped", "stripped");
        if (repStripped is not null) foreach (string n in publicStripped) repStripped.Row(n);
    }

    // The proof: read the written case back with the Core loaders (an internal check, so no licence count) and compare
    // the two steady states bit for bit.
    GridModel back;
    try
    {
        back = toCgmes
            // Export pack: the CIM reader with the SV starting voltages and the ratings, on the input's system base.
            ? Gated.ReadBackCgmes(output, m.BaseMva)
            : toRaw
            // Export pack: the RAW reader with tap and shunt control applied, so the written controls and static var
            // compensators are rebuilt (an internal check: no licence count).
            ? Gated.ReadBackPsse(output)
            : toMatpower
            ? Gated.ReadBackMatpower(output, m.FrequencyHz)
            : toV2
                // N299: the v2 loader's own checks (schemas, N234 sequence rules); no imports, so no data root.
                ? GridSim.Core.IO.Json.V2CaseLoader.Load(output, v2Schemas!)
                : JsonGridLoader.LoadDirectory(output);
    }
    catch (Exception ex) when (ex is IOException or InvalidDataException)
    {
        Console.Error.WriteLine($"convert: the written case does not load back: {ex.Message}");
        Environment.ExitCode = 3;
        rep?.Set("round_trip_identical", false).Set("first_difference", $"the written case does not load back: {ex.Message}").Complete();
        return;
    }
    // Export pack: a RAW file holds lines, transformers and FACTS series elements in separate sections, so the read-back
    // is the input in that order; it is compared with the input put in that order (the same network and records).
    GridModel expected = rawWritten is not null ? GridSim.Core.IO.Psse.PsseRawWriter.InFileOrder(m, rawWritten)
        // Export pack: the CGMES read-back numbers buses 1..n in model order and lists lines, then transformers.
        : cgmesWritten is not null ? GridSim.Core.IO.Cim.CgmesWriter.InFileOrder(m, cgmesWritten)
        : m;
    PowerFlowResult r1 = ContingencyAnalysis.CreateStudySolver(expected).Solve(expected, ContingencyAnalysis.StudyOptions);
    PowerFlowResult r2 = ContingencyAnalysis.CreateStudySolver(back).Solve(back, ContingencyAnalysis.StudyOptions);
    string? diff = FirstSolveDifference(r1, r2);
    // N299: a v2 output carries the fault sequence data, which no power flow reads; it is compared bit for bit as well.
    if (diff is null && toV2) diff = GridSim.Core.IO.Json.V2CaseWriter.FirstSequenceDifference(m, back) is string sd ? "fault sequence data: " + sd : null;
    if (diff is not null)
    {
        // Bug #57: the first difference in bus order can be a last-bit one while others are large (gb-full to .m: Vm at bus
        // 1010 one ulp apart, the largest 0.0598 pu, because the format drops the tap changers the loop moves), so the
        // largest voltage difference is named as well whenever the two voltage profiles can be compared bus by bus.
        string? largest = LargestVoltageDifference(r1, r2, positional: cgmesWritten is not null);
        Console.Error.WriteLine($"convert: the written case does NOT solve bit-identically to the input: {diff}" +
            (largest is null ? "" : $"; {largest}") + ". The output is kept; see the notes above for what the format could not carry.");
        Environment.ExitCode = 3;
        rep?.Set("round_trip_identical", false).Set("first_difference", diff);
        if (largest is not null) rep?.Set("largest_voltage_difference", largest);
        rep?.Complete();
        return;
    }
    Console.WriteLine($"  round trip: the written case solves bit-identically ({(r1.Converged ? "converged" : "NOT converged, identically")}; " +
        $"{r1.Vm.Length} bus voltages and angles, {r1.LineFlows.Count} line flows and the losses compared bit for bit, study options with the OLTC loop)");
    if (toV2)
        Console.WriteLine($"  round trip: the fault sequence data of {back.AllGenerators.Count} generator(s) and {back.Branches.Count} branch(es) read back bit for bit (N234 fields)");
    bool? ownOrderIdentical = null;
    if (rawWritten is not null)
    {
        // The input in its own branch order, for the record: the same network, but the admittance sums may round differently.
        PowerFlowResult r0 = ContingencyAnalysis.CreateStudySolver(m).Solve(m, ContingencyAnalysis.StudyOptions);
        string? own = FirstSolveDifference(r0, r2);
        ownOrderIdentical = own is null;
        Console.WriteLine(own is null
            ? "  round trip: compared in the file's branch order (lines, then transformers); the input in its own order solves to the same bits too"
            : $"  round trip: compared in the file's branch order (lines, then transformers); the input in its own order differs in the last bits ({own}): the same network, summed in another order");
    }
    if (cgmesWritten is not null)
    {
        // The input in its own numbering and branch order, for the record, compared bus by bus in position.
        PowerFlowResult r0 = ContingencyAnalysis.CreateStudySolver(m).Solve(m, ContingencyAnalysis.StudyOptions);
        string? own = FirstSolveDifference(r0, r2, positional: true);
        ownOrderIdentical = own is null;
        Console.WriteLine(own is null
            ? "  round trip: compared with buses numbered 1..n in model order and lines before transformers; the input in its own numbering and order solves to the same bits too"
            : $"  round trip: compared with buses numbered 1..n in model order and lines before transformers; the input in its own order differs in the last bits ({own}): the same network, summed in another order");
    }
    if (!r1.Converged) Console.WriteLine("  note: the case itself does not converge with the study options; the conversion is exact all the same.");
    rep?.Set("round_trip_identical", true).Set("first_difference", null).Set("case_converged", r1.Converged)
        .Set("buses_compared", r1.Vm.Length).Set("line_flows_compared", r1.LineFlows.Count).Set("input_order_identical", ownOrderIdentical).Complete();
}

// Export pack slice 2: where convert --public looks for a case's provenance manifest when --provenance is not given:
// provenance.json in a case folder (given as a path, or a built-in name that is a shipped folder), or <file>.provenance.json
// beside a case file. Null for a case with no folder or file of its own (the embedded IEEE cases, pypsa-gb-reduced).
static string? DefaultProvenancePath(string input, string root)
{
    if (Directory.Exists(input)) return Path.Combine(input, "provenance.json");
    if (File.Exists(input)) return Path.ChangeExtension(input, ".provenance.json");
    string? folder = input.ToLowerInvariant() switch
    {
        "uk" or "gb" or "gb-reduced" => "uk",
        "gb-full" => "gb-full",
        "gb-synthetic" or "synthetic" => "gb-synthetic",
        _ => null,
    };
    if (folder is not null) return Path.Combine(root, "data", folder, "provenance.json");
    string? file = input.ToLowerInvariant() switch
    {
        "gb-reduced-29" => GridSim.Core.IO.PyPsa.GbReferenceModels.Gb29RelativePath,
        "gb-network-2224" => GridSim.Core.IO.PyPsa.GbReferenceModels.Gb2224RelativePath,
        _ => null,
    };
    return file is null ? null : Path.ChangeExtension(Path.Combine(root, "data", file), ".provenance.json");
}

// Bug #57: the largest bus voltage difference between two solves of the same buses, as "the largest voltage difference
// is |dVm| = ... pu at bus N (a vs b) and |dVa| = ... deg at bus M, over K of the n buses", or null when the bus lists
// differ (or no voltage differs). Positional compares bus by bus in list order (a CGMES read-back renumbers the buses).
static string? LargestVoltageDifference(PowerFlowResult a, PowerFlowResult b, bool positional = false)
{
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    if (positional ? a.BusIds.Count != b.BusIds.Count : !a.BusIds.SequenceEqual(b.BusIds)) return null;
    int n = a.Vm.Length, differing = 0, iVm = -1, iVa = -1;
    double dVm = 0, dVa = 0;
    for (int i = 0; i < n; i++)
    {
        bool differs = BitConverter.DoubleToInt64Bits(a.Vm[i]) != BitConverter.DoubleToInt64Bits(b.Vm[i])
                       || BitConverter.DoubleToInt64Bits(a.VaDeg[i]) != BitConverter.DoubleToInt64Bits(b.VaDeg[i]);
        if (!differs) continue;
        differing++;
        double m = Math.Abs(a.Vm[i] - b.Vm[i]), g = Math.Abs(a.VaDeg[i] - b.VaDeg[i]);
        if (iVm < 0 || m > dVm) { dVm = m; iVm = i; }
        if (iVa < 0 || g > dVa) { dVa = g; iVa = i; }
    }
    if (differing == 0) return null;
    return $"the largest voltage difference is |dVm| = {dVm.ToString("R", inv)} pu at bus {a.BusIds[iVm]} ({a.Vm[iVm].ToString("R", inv)} vs {b.Vm[iVm].ToString("R", inv)}) "
        + $"and |dVa| = {dVa.ToString("R", inv)} deg at bus {a.BusIds[iVa]}, over {differing} of the {n} buses";
}

// The first bit-level difference between two power-flow results, or null when they are identical (F24).
// Export pack: positional compares bus by bus in list order (a CGMES read-back renumbers the buses 1..n).
static string? FirstSolveDifference(PowerFlowResult a, PowerFlowResult b, bool positional = false)
{
    static bool Same(double x, double y) => BitConverter.DoubleToInt64Bits(x) == BitConverter.DoubleToInt64Bits(y);
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    if (a.Converged != b.Converged) return $"converged {a.Converged} vs {b.Converged}";
    if (a.Iterations != b.Iterations) return $"iterations {a.Iterations} vs {b.Iterations}";
    if (positional ? a.BusIds.Count != b.BusIds.Count : !a.BusIds.SequenceEqual(b.BusIds)) return "the bus lists differ";
    (string Name, double[] X, double[] Y)[] arrays = { ("Vm", a.Vm, b.Vm), ("VaDeg", a.VaDeg, b.VaDeg), ("PInjMw", a.PInjMw, b.PInjMw), ("QInjMvar", a.QInjMvar, b.QInjMvar) };
    foreach ((string name, double[] x, double[] y) in arrays)
        for (int i = 0; i < x.Length; i++)
            if (!Same(x[i], y[i])) return $"{name} at bus {a.BusIds[i]}: {x[i].ToString("R", inv)} vs {y[i].ToString("R", inv)}";
    if (!Same(a.TotalLossMw, b.TotalLossMw)) return $"losses {a.TotalLossMw.ToString("R", inv)} vs {b.TotalLossMw.ToString("R", inv)} MW";
    if (!Same(a.TotalLossMvar, b.TotalLossMvar)) return $"reactive losses {a.TotalLossMvar.ToString("R", inv)} vs {b.TotalLossMvar.ToString("R", inv)} MVAr";
    if (a.LineFlows.Count != b.LineFlows.Count) return $"{a.LineFlows.Count} vs {b.LineFlows.Count} line flows (out-of-service branches are not carried)";
    for (int i = 0; i < a.LineFlows.Count; i++)
    {
        LineFlow x = a.LineFlows[i], y = b.LineFlows[i];
        if (!(Same(x.PFromMw, y.PFromMw) && Same(x.QFromMvar, y.QFromMvar) && Same(x.PToMw, y.PToMw) && Same(x.QToMvar, y.QToMvar)
              && Same(x.PLossMw, y.PLossMw) && Same(x.QLossMvar, y.QLossMvar) && Same(x.LoadingPercent, y.LoadingPercent)))
            return $"line flow {i} ({x.From}-{x.To})";
    }
    return null;
}

// validate <file.json|folder>... [--schemas <dir>]
// F24 (October 2026): check GridSim JSON v2 documents (gridsim-case/2, gridsim-network/2, gridsim-library/2,
// gridsim-kind/2) with the Phase 1 validator (Core V2DocumentValidator). A folder is searched for *.json files. Every
// error is printed with its file and JSON pointer. Exit 0 when every document is valid, 3 when any is not (a file that
// is not JSON counts as invalid), 1 when a path is missing or the schemas cannot be found or loaded, 2 for usage.
void RunValidate(List<string> a, string root)
{
    const string usage = "gridsim validate <file.json|folder>... [--schemas <dir>]";
    // --json / --csv / --out (F10) are taken off the argument list by the shared result writer before this runs.
    RequireVerbFlags("validate", a, "--schemas", "--json", "--csv", "--out");
    string? schemasArg = FlagString(a, "--schemas");
    List<string> pos = Positionals(a).Skip(1).ToList();
    if (pos.Count == 0) { Console.Error.WriteLine("usage: " + usage); Environment.ExitCode = 2; return; }

    var files = new List<string>();
    foreach (string p in pos)
    {
        if (Directory.Exists(p))
            files.AddRange(Directory.EnumerateFiles(p, "*.json", SearchOption.AllDirectories).OrderBy(f => f, StringComparer.Ordinal));
        else if (File.Exists(p)) files.Add(p);
        else { Console.Error.WriteLine($"error: validate: '{p}' does not exist."); Environment.ExitCode = 1; return; }
    }
    if (files.Count == 0) { Console.Error.WriteLine("error: validate: no .json files found in the paths given."); Environment.ExitCode = 1; return; }

    string? schemasDir = schemasArg ?? FindV2Schemas(root);
    if (schemasDir is null || !File.Exists(Path.Combine(schemasDir, "case.schema.json")))
    {
        Console.Error.WriteLine($"error: validate: cannot find the v2 schemas{(schemasArg is null ? " (looked for schemas/v2 beside the program and above it, and above the current folder)" : $" in '{schemasArg}'")}; pass --schemas <dir>.");
        Environment.ExitCode = 1;
        return;
    }

    IReadOnlyList<GridSim.Core.IO.Json.Schema.V2DocumentReport> reports;
    try { reports = GridSim.Core.IO.Json.Schema.V2DocumentValidator.ValidateFiles(files, schemasDir); }
    catch (Exception ex) when (ex is IOException or InvalidDataException)
    {
        Console.Error.WriteLine($"error: validate: the schema set in '{schemasDir}' cannot be loaded: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }

    // F10: one row per document and one per error, from the same reports the console prints.
    CliResult? result = CliOutput.Report;
    CliResultTable? resultDocs = result?.Table("documents", "path", "schema_tag", "valid", "errors");
    CliResultTable? resultErrors = result?.Table("errors", "path", "error");
    int bad = 0;
    foreach (GridSim.Core.IO.Json.Schema.V2DocumentReport rep in reports)
    {
        string tag = rep.SchemaTag is null ? "no tag" : rep.SchemaTag;
        resultDocs?.Row(rep.Path, rep.SchemaTag, rep.Valid, rep.Errors.Count);
        if (resultErrors is not null) foreach (GridSim.Core.IO.Json.Schema.SchemaError e in rep.Errors) resultErrors.Row(rep.Path, e.ToString());
        if (rep.Valid) { Console.WriteLine($"OK    {rep.Path} ({tag})"); continue; }
        bad++;
        Console.WriteLine($"FAIL  {rep.Path} ({tag}): {rep.Errors.Count} error(s)");
        foreach (GridSim.Core.IO.Json.Schema.SchemaError e in rep.Errors) Console.WriteLine("        " + e);
    }
    Console.WriteLine($"validate: {reports.Count - bad} of {reports.Count} document(s) valid (schemas: {schemasDir})");
    if (bad > 0) Environment.ExitCode = 3;
    result?.Set("documents", reports.Count).Set("valid", reports.Count - bad).Set("invalid", bad).Set("schemas", schemasDir).Complete();
}

// The v2 schema folder: schemas/v2 beside the program, else the nearest one above the program or the current folder.
// N065: the search lives in Gated.FindV2Schemas, shared with the JSON v2 case loader, so both read the same schemas.
static string? FindV2Schemas(string programDir) => Gated.FindV2Schemas(programDir);

// taps <case> [--target 1.0]
// R072: TapOptimizer.Flatten: one coordinated tap schedule across every OLTC that minimises the bus-voltage
// deviation from the target, rounded to each OLTC's step grid.
void RunTaps(List<string> a, string root)
{
    double target = FlagDouble(a, "--target", 1.0);
    if (!(target > 0)) FailFlag<double>("--target", target.ToString(System.Globalization.CultureInfo.InvariantCulture), "a voltage above 0 pu");
    GridModel? m = LoadAnalysisCase(a, root, "taps", "gridsim taps <case> [--target 1.0]");
    if (m is null) return;
    if (m.Oltcs.Count == 0)
    {
        Console.Error.WriteLine($"taps: case '{m.Name}' has no on-load tap changers to schedule.");
        Environment.ExitCode = 1;
        return;
    }

    // D-DOC-046 (October 2026): an OLTC record that names no branch (or several), or controls a bus the case does not
    // have, is invalid case data: refused before any solve (exit 1), naming every such record. The schedule used to drop
    // an unmatched OLTC silently and schedule the others as if it did not exist.
    IReadOnlyList<string> oltcProblems = GridSim.Core.Analysis.TapOptimizer.OltcProblems(m);
    if (oltcProblems.Count > 0)
    {
        Console.Error.WriteLine($"taps: case '{m.Name}': {string.Join("; ", oltcProblems)}. No schedule.");
        Environment.ExitCode = 1;
        return;
    }

    GridSim.Core.Analysis.TapSchedule sch = GridSim.Core.Analysis.TapOptimizer.Flatten(m, target);
    Console.WriteLine($"TAP SCHEDULE - {m.Name} ({m.Oltcs.Count} OLTCs)  [minimise sum of squared deviation from {target:F3} pu]");
    if (!sch.Solved)
    {
        Console.Error.WriteLine("taps: the base case did not converge; no schedule.");
        Environment.ExitCode = 3;
        return;
    }
    Console.WriteLine($"  objective {sch.ObjectiveBefore:E6} -> {sch.ObjectiveAfter:E6}  {(sch.Improved ? "(improved)" : "(current taps already best)")}");
    foreach (GridSim.Core.Analysis.TapSetting t in sch.Taps)
        Console.WriteLine($"      {t.Transformer,-24} {t.CurrentTap,8:F4} -> {t.RecommendedTap,8:F4}");
    // D-DOC-046: each OLTC's own target and deadband. The schedule minimises every bus's deviation from the one --target,
    // so it can leave an OLTC's controlled bus outside that OLTC's own band, where its local regulator would move the tap
    // away from the schedule. Those OLTCs are named (only when there are some, so a schedule every OLTC accepts prints
    // as before); it is information about the schedule, not a failure.
    var outside = sch.Regulation.Where(c => !c.WithinDeadband).ToList();
    if (outside.Count > 0)
    {
        Console.WriteLine($"  {outside.Count} OLTC(s) would leave this schedule: the bus each controls is outside its own target +/- deadband, so its local regulator would retap:");
        foreach (GridSim.Core.Analysis.OltcRegulationCheck c in outside)
            Console.WriteLine($"      {c.Transformer,-24} bus {c.ControlsBus,-6} {c.VmPu,7:F4} pu  (own target {c.TargetVpu:F4} +/- {c.DeadbandPu:F4})");
    }
    // D-DOC-046: a search cut off at its iteration cap is not an optimum. It used to be reported exactly like a converged
    // one (exit 0). The schedule found is still printed (it is the best point the search reached, snapped to the step
    // grid), the shortfall is said on stderr, and the run exits 3, the code of a solve that did not converge.
    if (!sch.OptimizerConverged)
    {
        Console.Error.WriteLine($"taps: the tap search stopped at its iteration cap ({sch.OptimizerIterations} iterations) without converging; "
            + "the schedule above is the best point it reached, not a proven optimum. Exit 3.");
        Environment.ExitCode = 3;   // CliExit.Verdict, written as the literal 3 that CliExitCodeContractTests reads
    }
    // F10: the schedule at full precision.
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("oltcs", m.Oltcs.Count).Set("target_pu", target)
            .Set("objective_before", sch.ObjectiveBefore).Set("objective_after", sch.ObjectiveAfter).Set("improved", sch.Improved)
            .Set("optimizer_converged", sch.OptimizerConverged).Set("optimizer_iterations", sch.OptimizerIterations);
        CliResultTable taps = rep.Table("taps", "transformer", "current_tap", "recommended_tap");
        foreach (GridSim.Core.Analysis.TapSetting t in sch.Taps) taps.Row(t.Transformer, t.CurrentTap, t.RecommendedTap);
        // D-DOC-046: every OLTC's own regulation check at the recommended taps.
        CliResultTable reg = rep.Table("regulation", "transformer", "controls_bus", "vm_pu", "target_pu", "deadband_pu", "within_deadband");
        foreach (GridSim.Core.Analysis.OltcRegulationCheck c in sch.Regulation)
            reg.Row(c.Transformer, c.ControlsBus, c.VmPu, c.TargetVpu, c.DeadbandPu, c.WithinDeadband);
        rep.Complete();
    }
}

// restore <case> --order <b1,b2,...> [--vmin 0.90] [--vmax 1.10] [--qtol 1.0]
// R072 (October 2026): RestorationSequencer.Evaluate, the black-start sequence checker. The listed branches start open
// and are energised one per step; each step re-solves the live (slack-connected) network with generator reactive
// limits enforced and the live OLTCs regulating (Q6, Mark: correctness first, done in 1.95.033), and reports the
// voltage-band breaches and the generators pinned at a reactive limit. A branch is named by its name in the case, or by
// "#k" (its 1-based row in the case's branch table) for cases whose branches carry no names (MATPOWER files). Exit 0
// when every step solves and is feasible; 3 when any step does not solve or is unsafe (a verdict that is not secure,
// like the contingency verbs); 1 for an unknown or repeated branch, or a load error; 2 for usage.
void RunRestore(List<string> a, string root)
{
    const string usage = "gridsim restore <case> --order <b1,b2,...> [--vmin 0.90] [--vmax 1.10] [--qtol 1.0]";
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    RequireVerbFlags("restore", a, "--order", "--vmin", "--vmax", "--qtol");
    string? order = FlagString(a, "--order");
    double vMin = FlagDouble(a, "--vmin", GridSim.Core.Analysis.VoltageLimits.StatutoryLowPu);
    double vMax = FlagDouble(a, "--vmax", GridSim.Core.Analysis.VoltageLimits.StatutoryHighPu);
    double qTol = FlagDouble(a, "--qtol", 1.0);
    if (order is null) { Console.Error.WriteLine($"usage: {usage}  (--order is required)"); Environment.ExitCode = 2; return; }
    if (!(vMin > 0)) FailFlag<double>("--vmin", vMin.ToString(inv), "a voltage above 0 pu");
    if (!(vMax > vMin)) FailFlag<double>("--vmax", vMax.ToString(inv), $"a voltage above --vmin ({vMin.ToString(inv)} pu)");
    if (!(qTol >= 0)) FailFlag<double>("--qtol", qTol.ToString(inv), "0 or more Mvar");
    // The order: comma-separated, each entry trimmed; an empty entry (",," or a trailing comma) is a usage error, not
    // something to skip, since a skipped entry would silently shorten the sequence.
    string[] tokens = order.Split(',');
    if (tokens.Any(t => t.Trim().Length == 0)) FailFlag<string>("--order", order, "a comma-separated list of branch names or #row numbers with no empty entry");
    GridModel? m = LoadAnalysisCase(a, root, "restore", usage);
    if (m is null) return;

    // Resolve "#k" tokens to the k-th branch (1-based). An unnamed branch referenced that way is given the name "#k"
    // for the evaluation (names are labels only: nothing numeric reads them, and OLTCs refer to named transformers, so an
    // unnamed branch is never an OLTC's). A "#k" that is also some branch's real name is ambiguous and refused.
    var branches = m.Branches.ToList();
    var names = new List<string>(tokens.Length);
    bool renamed = false;
    foreach (string raw in tokens)
    {
        string t = raw.Trim();
        if (t.StartsWith('#'))
        {
            if (!int.TryParse(t.AsSpan(1), System.Globalization.NumberStyles.None, inv, out int row) || row < 1 || row > branches.Count)
            {
                Console.Error.WriteLine($"restore: '{t}' is not a branch row of case '{m.Name}' (rows are #1 to #{branches.Count}).");
                Environment.ExitCode = 1;
                return;
            }
            if (m.Branches.Any(b => string.Equals(b.Name, t, StringComparison.Ordinal) && !ReferenceEquals(b, m.Branches[row - 1])))
            {
                Console.Error.WriteLine($"restore: '{t}' is ambiguous: it is both row {row} and the name of another branch of case '{m.Name}'.");
                Environment.ExitCode = 1;
                return;
            }
            Branch target = branches[row - 1];
            if (target.Name is null) { branches[row - 1] = target with { Name = t }; renamed = true; names.Add(t); }
            else names.Add(target.Name);   // the row has a real name: sequence it by that name
        }
        else names.Add(t);
    }
    GridModel evalModel = renamed ? m.CopyWith(branches: branches) : m;

    GridSim.Core.Analysis.RestorationReport rep;
    try
    {
        rep = GridSim.Core.Analysis.RestorationSequencer.Evaluate(evalModel, names, vMin, vMax, qTol);
    }
    catch (ArgumentException ex)
    {
        // An unknown or repeated branch name (the sequencer refuses both, naming the branch).
        Console.Error.WriteLine($"restore: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }

    Console.WriteLine($"RESTORATION - {m.Name} ({m.BusCount} buses, {names.Count} step(s))  " +
        $"[reactive limits enforced, live OLTCs regulating; band {vMin.ToString("F3", inv)}-{vMax.ToString("F3", inv)} pu; Q tolerance {qTol.ToString("G", inv)} Mvar]");
    Console.WriteLine($"  {"step",4}  {"energised",-24} {"solved",6} {"Vmin",8} {"Vmax",8}  verdict");
    foreach (GridSim.Core.Analysis.RestorationStepResult s in rep.Steps)
    {
        string verdict = !s.Solved ? "NOT SOLVED"
            : s.Feasible ? "ok"
            : string.Join("; ", new[]
              {
                  s.OverVoltageBuses.Count > 0 ? $"over-voltage at bus(es) {string.Join(' ', s.OverVoltageBuses)}" : null,
                  s.UnderVoltageBuses.Count > 0 ? $"under-voltage at bus(es) {string.Join(' ', s.UnderVoltageBuses)}" : null,
                  s.GeneratorsAtReactiveLimit.Count > 0 ? $"generator(s) at a reactive limit at bus(es) {string.Join(' ', s.GeneratorsAtReactiveLimit)}" : null,
              }.Where(x => x is not null));
        // A step that did not solve has no voltages: print dashes, not the sequencer's 0 placeholders.
        string vmin = s.Solved ? s.MinVpu.ToString("F4", inv) : "-";
        string vmax = s.Solved ? s.MaxVpu.ToString("F4", inv) : "-";
        Console.WriteLine($"  {s.Step + 1,4}  {s.Energized,-24} {(s.Solved ? "yes" : "no"),6} {vmin,8} {vmax,8}  {verdict}");
    }
    int first = rep.FirstInfeasibleStep;
    if (first < 0) Console.WriteLine("  sequence feasible: every step solves inside the band with no generator at a reactive limit.");
    else Console.WriteLine($"  sequence NOT feasible: first unsafe step is {first + 1} ({rep.Steps[first].Energized}).");

    // F10: the steps at full precision (a step that did not solve carries null voltages, not 0).
    CliResult? res = CliOutput.Report;
    if (res is not null)
    {
        res.Set("case", m.Name).Set("buses", m.BusCount).Set("steps", rep.Steps.Count).Set("vmin_pu", vMin).Set("vmax_pu", vMax)
            .Set("q_tolerance_mvar", qTol).Set("all_feasible", rep.AllFeasible).Set("first_infeasible_step", first < 0 ? 0 : first + 1);
        CliResultTable t = res.Table("steps", "step", "energised", "solved", "min_vm_pu", "max_vm_pu", "over_voltage_buses",
            "under_voltage_buses", "generators_at_reactive_limit", "feasible");
        foreach (GridSim.Core.Analysis.RestorationStepResult s in rep.Steps)
            t.Row(s.Step + 1, s.Energized, s.Solved, s.Solved ? s.MinVpu : null, s.Solved ? s.MaxVpu : null,
                string.Join(' ', s.OverVoltageBuses), string.Join(' ', s.UnderVoltageBuses),
                string.Join(' ', s.GeneratorsAtReactiveLimit), s.Feasible);
        // The verdict is a complete result either way (an unsafe sequence is the answer, as an insecure contingency
        // verdict is); the file records the exit code alongside it.
        res.Complete();
    }
    if (!rep.AllFeasible)
    {
        Console.Error.WriteLine($"restore: the sequence is not feasible (first unsafe step {first + 1}, {rep.Steps[first].Energized}" +
            $"{(rep.Steps[first].Solved ? "" : ": the power flow did not converge")}).");
        Environment.ExitCode = 3;
    }
}

// acopf <case> [--loss-tol 1e-3] [--max-iter 20] [--top N] [--costs case|<file.json>] [--prices]
// R072: AcOptimalPowerFlow.Solve: the DC-OPF dispatch inside an outer loop that inflates demand by the AC losses and
// re-dispatches until the losses converge, so the dispatch pays for its own losses. F15 (October 2026): it is NOT a full
// AC optimal power flow (voltages, reactive power and AC branch flows are neither optimised nor limited), and the header
// now says so instead of the old claim of a loss-aware dispatch by linearisation. A real AC-OPF is post-1.0 work.
void RunAcOpf(List<string> a, string root)
{
    double lossTol = FlagDouble(a, "--loss-tol", 1e-3);
    int maxIter = FlagInt(a, "--max-iter", 20);
    int top = FlagCount(a, "--top", 12, 0);
    string? costs = FlagString(a, "--costs");   // F19: generator cost curves for every DC pass (opt-in)
    bool prices = a.Remove("--prices");         // N121: the final DC pass's nodal and line prices (opt-in)
    if (!(lossTol > 0)) FailFlag<double>("--loss-tol", lossTol.ToString(System.Globalization.CultureInfo.InvariantCulture), "a tolerance above 0 MW");
    if (maxIter < 1) FailFlag<int>("--max-iter", maxIter.ToString(System.Globalization.CultureInfo.InvariantCulture), "at least 1");
    GridModel? m = LoadAnalysisCase(a, root, "acopf", "gridsim acopf <case> [--loss-tol 1e-3] [--max-iter 20] [--top N] [--costs case|<file.json>] [--prices]");
    if (m is null) return;
    if (costs is not null)
    {
        m = ApplyCostSource(m, costs, "acopf");
        if (m is null) return;
    }

    GridSim.Core.Analysis.AcOpfResult r;
    if (costs is null)
    {
        // D-DOC-004: as in dcopf, the DC passes refuse invalid generator data (Pmin above Pmax) with
        // InvalidDataException, which this path (no --costs, with or without --prices) did not catch, so the run crashed.
        // Invalid case data is an input error: exit 1, as the --costs path already gave.
        try { r = GridSim.Core.Analysis.AcOptimalPowerFlow.Solve(m, costPerGen: null, lossToleranceMw: lossTol, maxIterations: maxIter, computePrices: prices); }
        catch (Exception ex) when (ex is InvalidOperationException or InvalidDataException)
        { Console.Error.WriteLine($"[acopf] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
    }
    else
    {
        try { r = GridSim.Core.Analysis.AcOptimalPowerFlow.Solve(m, costPerGen: null, lossToleranceMw: lossTol, maxIterations: maxIter, useGeneratorCosts: true, computePrices: prices); }
        catch (Exception ex) when (ex is InvalidOperationException or InvalidDataException)
        { Console.Error.WriteLine($"[acopf] {ex.Message}"); Environment.ExitCode = 1; return; }
    }

    Console.WriteLine($"ACOPF (DC dispatch + AC loss loop) - {m.Name} ({m.BusCount} buses)  [not a full AC-OPF: no voltage, reactive-power or AC branch-flow limits]");
    // N109 (Ruling R1, Mark delegated 2026-10-04): the final DC pass left out rated lines no dispatch can relieve; name
    // them whatever the outcome (they stay over their rating at the dispatch below). Printed only when there are some.
    if (r.UnrelievableLines.Count > 0)
    {
        Console.WriteLine($"  the final DC pass left out {r.UnrelievableLines.Count} rated line(s) no dispatch can bring within rating (still overloaded; 'gridsim dcopf' lists them):");
        foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.UnrelievableLine u in r.UnrelievableLines.Take(top))
            Console.WriteLine($"      branch {u.Branch,-5} {BranchDisplayName(u.Name, m.Branches[u.Branch].From, m.Branches[u.Branch].To),-28} rating {u.RateMw:N1} MW, any dispatch gives {u.ReachableMinMw:N1} .. {u.ReachableMaxMw:N1} MW");
        if (r.UnrelievableLines.Count > top) Console.WriteLine($"      ... and {r.UnrelievableLines.Count - top} more (--top N lists more)");
    }
    if (!r.Converged)
    {
        // N111 (October 2026): say which of the three causes stopped the run. One message ("the loss iteration did not
        // converge in N iteration(s)") used to cover all three, and on case118 / case300 it blamed the loss loop for what
        // was an AC power flow that failed at pass 0.
        var inv = System.Globalization.CultureInfo.InvariantCulture;
        switch (r.Failure)
        {
            case GridSim.Core.Analysis.AcOpfFailure.AcPowerFlowNotConverged when r.AcFailure is { } f:
                Console.Error.WriteLine($"acopf: the AC power flow at the DC-OPF dispatch of loss pass {f.Pass} (passes count from 0) did not converge: " +
                    $"{f.Status} after {f.Iterations} iteration(s), largest mismatch {f.MaxMismatchPu.ToString("E3", inv)} pu, lowest voltage " +
                    $"{f.MinVmPu.ToString("F4", inv)} pu where it stopped. The DC dispatch is chosen without voltages or reactive power, so it can be a " +
                    "point the network cannot carry within the units' reactive limits: the case's physics at that dispatch, not a solver fault.");
                // A dispatch on one flat price is one arbitrary optimum of a degenerate LP (MATPOWER files carry no fuel types,
                // so every unit is priced the same); the case's own cost curves give a meaningful dispatch.
                if (costs is null && r.Dispatch.Count > 1 && r.Dispatch.All(d => d.CostPerMwh.Equals(r.Dispatch[0].CostPerMwh)))
                    Console.Error.WriteLine($"acopf: every unit is priced the same ({r.Dispatch[0].CostPerMwh.ToString("R", inv)} GBP/MWh: the case gives no fuel " +
                        "types), so that dispatch is one arbitrary optimum of a degenerate LP; '--costs case' dispatches on the case's own cost curves (a .m file's mpc.gencost).");
                break;
            case GridSim.Core.Analysis.AcOpfFailure.DcDispatchInfeasible when r.StoppedAtInfeasibleFirstPass:
                // N173 (October 2026): the loop stopped at pass 0 instead of solving AC power flows of an insecure dispatch
                // and re-dispatching at higher demand (gb-full spent 3 min 37 s that way): the loss loop only raises
                // demand, and this infeasibility is proved to survive every increase.
                Console.Error.WriteLine("acopf: the DC-OPF dispatch of loss pass 0 (passes count from 0) is infeasible (no dispatch meets the demand " +
                    "within the units' limits and the rated lines' limits), and no later pass can be feasible: the loss loop only raises demand, " +
                    "which cannot cure this infeasibility, so the loop stopped there; 'gridsim dcopf' on this case shows why.");
                break;
            case GridSim.Core.Analysis.AcOpfFailure.DcDispatchInfeasible:
                Console.Error.WriteLine($"acopf: the losses settled after {r.Iterations} pass(es), but the DC-OPF dispatch of the final pass is infeasible " +
                    "(no dispatch meets the loss-inflated demand within the units' limits and the rated lines' limits); 'gridsim dcopf' on this case shows why.");
                break;
            default:
                Console.Error.WriteLine($"acopf: the losses did not settle within {r.Iterations} pass(es) (--max-iter {maxIter}, --loss-tol {lossTol.ToString("R", inv)} MW).");
                break;
        }
        Environment.ExitCode = 3;
        return;
    }
    Console.WriteLine(costs is null
        ? $"  converged in {r.Iterations} iteration(s)  losses {r.TotalLossMw:F3} MW  cost {r.TotalCostPerHour:N0} GBP/h"
        : $"  converged in {r.Iterations} iteration(s)  losses {r.TotalLossMw:F3} MW  cost {r.TotalCostPerHour:N2} cost units/h (generator cost curves)");
    foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.GenDispatch d in r.Dispatch.Where(d => d.Pg > GridSim.Cli.CliDefaults.DcopfDispatchDisplayFloorMw).OrderByDescending(d => d.Pg).Take(top))
        Console.WriteLine(costs is null
            ? $"      gen bus {d.GenBus,-6} {d.Pg,8:N1} MW  @ {d.CostPerMwh,5:N0} GBP/MWh"
            : $"      gen bus {d.GenBus,-6} {d.Pg,8:N2} MW  marginal {d.CostPerMwh,9:N4} cost units/MWh");
    // N121: the final DC pass's prices, labelled for what they are (lossless DC prices at the loss-inflated demand; the
    // loss loop only scales demand, so there is no marginal-loss component), as dcopf --prices prints them.
    string money = costs is null ? "GBP" : "cost units";
    if (prices)
    {
        if (r.Prices is not { } pr)
            Console.WriteLine("  prices: not available (the final DC pass did not reach an optimum with duals)");
        else
        {
            var byLmp = pr.Buses.OrderByDescending(p => p.Lmp).ThenBy(p => p.BusId).ToList();
            Console.WriteLine($"  nodal prices of the final DC pass (LMP, {money}/MWh, lossless DC at the loss-inflated demand; no marginal-loss component): {pr.Buses.Count} bus(es), "
                + (byLmp.Count > 0 ? $"highest {byLmp[0].Lmp:N4} at bus {byLmp[0].BusId}, lowest {byLmp[^1].Lmp:N4} at bus {byLmp[^1].BusId}" : "none"));
            foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.BusPrice p in byLmp.Take(top))
                Console.WriteLine($"      bus {p.BusId,-6} LMP {p.Lmp,10:N4}  (energy {p.EnergyComponent:N4}, congestion {p.CongestionComponent:N4})");
            if (pr.Lines.Count > 0)
            {
                Console.WriteLine($"  line shadow prices ({money}/MWh per MW of extra rating):");
                foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.LinePrice lp in pr.Lines.Take(top))
                    Console.WriteLine($"      branch {lp.Branch,-4} {BranchDisplayName(lp.Name, m.Branches[lp.Branch].From, m.Branches[lp.Branch].To),-12} {lp.FlowMw,8:N1} MW / {lp.RateMw:N0} MVA  shadow price {lp.ShadowPrice:N4}");
            }
        }
    }
    // F10: every generator's dispatch (the console lists the top N above the display floor).
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("buses", m.BusCount).Set("loss_tol_mw", lossTol).Set("max_iter", maxIter)
            .Set("converged", r.Converged).Set("iterations", r.Iterations).Set("total_loss_mw", r.TotalLossMw)
            .Set(costs is null ? "total_cost_gbp_per_h" : "total_cost_per_h", r.TotalCostPerHour);   // D-DOC-139: one honest unit, as dcopf
        CliResultTable dispatch = rep.Table("dispatch", "gen_bus", "pg_mw", costs is null ? "cost_gbp_per_mwh" : "marginal_cost_per_mwh");
        foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.GenDispatch d in r.Dispatch) dispatch.Row(d.GenBus, d.Pg, d.CostPerMwh);
        if (costs is not null) rep.Set("cost_source", costs).Set("cost_units", money);
        if (prices && r.Prices is { } pr)
        {
            // N121: the same tables as dcopf --prices, from the final DC pass.
            rep.Set("prices_source", "final DC-OPF pass at the loss-inflated demand (lossless DC: energy + congestion, no marginal-loss component)");
            CliResultTable repPrices = rep.Table("prices", "bus_id", "lmp_per_mwh", "energy_per_mwh", "congestion_per_mwh");
            foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.BusPrice p in pr.Buses) repPrices.Row(p.BusId, p.Lmp, p.EnergyComponent, p.CongestionComponent);
            CliResultTable repShadow = rep.Table("shadow_prices", "branch", "name", "flow_mw", "rate_mw", "shadow_price_per_mwh");
            foreach (GridSim.Core.Analysis.DcOptimalPowerFlow.LinePrice lp in pr.Lines) repShadow.Row(lp.Branch, lp.Name, lp.FlowMw, lp.RateMw, lp.ShadowPrice);
        }
        rep.Complete();
    }
}

// acopf-full <case> [--max-iter 150] [--top 12] [--cost-file <file.json>]
// 2026-10-25 (roadmap Tranche B item 7): the full AC optimal power flow (AcOpfInteriorPoint, MATPOWER's MIPS primal-dual interior
// point method) over every bus voltage and every unit's P and Q, with the AC power balance, the rated branches' MVA limits
// at both ends, the bus voltage limits and the unit limits. Costs are the case's own curves (a .m file's mpc.gencost), or a
// cost file. Unlike acopf (a DC dispatch with an AC loss loop, left as it was) it optimises voltages and reactive power.
// Exit 0 converged, 1 a case the method refuses (the reason is printed), 2 usage, 3 not converged (the iteration log is
// printed; the numbers of a run that did not converge are never shown as a result).
void RunAcOpfFull(List<string> a, string root)
{
    int maxIter = FlagInt(a, "--max-iter", 150);
    int top = FlagCount(a, "--top", 12, 0);
    string? costFile = FlagString(a, "--cost-file");
    if (maxIter < 1) FailFlag<int>("--max-iter", maxIter.ToString(System.Globalization.CultureInfo.InvariantCulture), "at least 1");
    GridModel? m = LoadAnalysisCase(a, root, "acopf-full", "gridsim acopf-full <case> [--max-iter 150] [--top 12] [--cost-file <file.json>]");
    if (m is null) return;
    if (costFile is not null)
    {
        m = ApplyCostSource(m, costFile, "acopf-full");
        if (m is null) return;
    }

    GridSim.Core.Analysis.AcOpfIpmResult r;
    try { r = GridSim.Core.Analysis.AcOpfInteriorPoint.Solve(m, new GridSim.Core.Analysis.AcOpfIpmOptions { MaxIterations = maxIter }); }
    catch (InvalidDataException ex) { Console.Error.WriteLine($"[acopf-full] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }

    var inv = System.Globalization.CultureInfo.InvariantCulture;
    Console.WriteLine($"AC-OPF (full AC, primal-dual interior point) - {m.Name} ({m.BusCount} buses, {m.Generators.Count} units)");
    if (!r.Converged)
    {
        // Fail loud: the state the iteration stopped in is not an optimum, so only the cause and the log are printed.
        Console.Error.WriteLine($"acopf-full: {(r.Status == GridSim.Core.Analysis.AcOpfIpmStatus.IterationCap ? "not converged" : "numerical failure")}: {r.Message}.");
        Console.Error.WriteLine("acopf-full: iteration log (objective in cost units/h; the conditions are MIPS's relative measures): it, objective, feasibility, gradient, complementarity, cost change, barrier, primal step, dual step");
        foreach (GridSim.Core.Analysis.AcOpfIpmIteration l in r.Log)
            Console.Error.WriteLine($"  {l.Iteration,4} {l.Objective.ToString("R", inv),22} {l.Feasibility.ToString("E3", inv)} {l.Gradient.ToString("E3", inv)} " +
                $"{l.Complementarity.ToString("E3", inv)} {l.CostChange.ToString("E3", inv)} {l.Barrier.ToString("E3", inv)} {l.StepPrimal.ToString("F6", inv)} {l.StepDual.ToString("F6", inv)}");
        Environment.ExitCode = CliExit.Verdict;
        return;
    }

    Console.WriteLine($"  converged in {r.Iterations} iteration(s)  objective {r.ObjectivePerHour.ToString("F2", inv)} cost units/h  " +
        $"generation {r.TotalGenerationMw.ToString("F3", inv)} MW  load {r.TotalLoadMw.ToString("F3", inv)} MW  losses {r.LossesMw.ToString("F3", inv)} MW");
    Console.WriteLine($"  dispatch (largest {Math.Min(top, r.Generators.Count)} of {r.Generators.Count} units):");
    foreach (GridSim.Core.Analysis.AcOpfGenResult g in r.Generators.OrderByDescending(g => g.PgMw).ThenBy(g => g.Index).Take(top))
        Console.WriteLine($"      unit {g.Index,-4} bus {g.Bus,-6} {g.PgMw.ToString("F2", inv),10} MW {g.QgMvar.ToString("F2", inv),10} MVAr");
    var byLmp = r.Buses.OrderByDescending(b => b.LmpP).ThenBy(b => b.BusId).ToList();
    Console.WriteLine($"  nodal prices (cost units/MWh; reactive per MVArh): highest {byLmp[0].LmpP.ToString("F4", inv)} at bus {byLmp[0].BusId}, " +
        $"lowest {byLmp[^1].LmpP.ToString("F4", inv)} at bus {byLmp[^1].BusId}");
    foreach (GridSim.Core.Analysis.AcOpfBusResult b in byLmp.Take(top))
        Console.WriteLine($"      bus {b.BusId,-6} LMP {b.LmpP.ToString("F4", inv),10}  reactive {b.LmpQ.ToString("F4", inv),9}  V {b.VmPu.ToString("F4", inv)} pu {b.VaDeg.ToString("F3", inv),9} deg");
    Console.WriteLine($"  binding constraints: {r.Binding.Count}");
    foreach (GridSim.Core.Analysis.AcOpfBinding bd in r.Binding.OrderByDescending(b => b.ShadowPrice).ThenBy(b => b.Kind, StringComparer.Ordinal).ThenBy(b => b.Element, StringComparer.Ordinal).Take(top))
        Console.WriteLine($"      {bd.Kind,-4} {bd.Element,-32} shadow price {bd.ShadowPrice.ToString("F4", inv)}");
    if (r.Binding.Count > top) Console.WriteLine($"      ... and {r.Binding.Count - top} more (--top N lists more)");

    // Result files: every bus, unit, branch, binding constraint and iteration.
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("buses", m.BusCount).Set("method", "primal-dual interior point (MIPS)").Set("max_iter", maxIter)
            .Set("converged", true).Set("iterations", r.Iterations).Set("objective_per_h", r.ObjectivePerHour)
            .Set("total_generation_mw", r.TotalGenerationMw).Set("total_load_mw", r.TotalLoadMw).Set("losses_mw", r.LossesMw)
            .Set("cost_source", costFile ?? "case");
        CliResultTable buses = rep.Table("buses", "bus_id", "vm_pu", "va_deg", "lmp_p_per_mwh", "lmp_q_per_mvarh", "mu_vmin", "mu_vmax");
        foreach (GridSim.Core.Analysis.AcOpfBusResult b in r.Buses) buses.Row(b.BusId, b.VmPu, b.VaDeg, b.LmpP, b.LmpQ, b.MuVmin, b.MuVmax);
        CliResultTable gens = rep.Table("generators", "unit", "bus", "pg_mw", "qg_mvar", "mu_pmin", "mu_pmax", "mu_qmin", "mu_qmax");
        foreach (GridSim.Core.Analysis.AcOpfGenResult g in r.Generators) gens.Row(g.Index, g.Bus, g.PgMw, g.QgMvar, g.MuPmin, g.MuPmax, g.MuQmin, g.MuQmax);
        CliResultTable branches = rep.Table("branches", "branch", "from", "to", "pf_mw", "qf_mvar", "pt_mw", "qt_mvar", "rate_mva", "mu_sf", "mu_st");
        foreach (GridSim.Core.Analysis.AcOpfBranchResult b in r.Branches) branches.Row(b.Index, b.From, b.To, b.PfMw, b.QfMvar, b.PtMw, b.QtMvar, b.RateMva, b.MuSf, b.MuSt);
        CliResultTable binding = rep.Table("binding", "kind", "element", "shadow_price");
        foreach (GridSim.Core.Analysis.AcOpfBinding bd in r.Binding) binding.Row(bd.Kind, bd.Element, bd.ShadowPrice);
        CliResultTable log = rep.Table("iterations", "iteration", "objective", "feasibility", "gradient", "complementarity", "cost_change", "barrier", "step_primal", "step_dual");
        foreach (GridSim.Core.Analysis.AcOpfIpmIteration l in r.Log)
            log.Row(l.Iteration, l.Objective, l.Feasibility, l.Gradient, l.Complementarity, l.CostChange, l.Barrier, l.StepPrimal, l.StepDual);
        rep.Complete();
    }
}

// inertia-placement [case] [--placements fleet,demand,spine-t,south,optimised] [--budgets 120,180,240,360,480,700,900,1200]
//                   [--losses sizewell,hinkley,kent,scotland] [--residual 0.25] [--condenser-h 8] [--rocof-limits 0.125,0.25,0.5,1]
//                   [--post-event 6] [--optimise-budget 240] [--optimise-passes 1]
// The inertia placement study (October 2026, InertiaPlacementStudy): with GB's synchronous inertia in ideal places, can
// the system run on less of it? Today's fleet keeps a residual share of its inertia; the rest of each budget is
// synchronous condensers placed by each placement; each credible 1.8 GW loss is run on the RMS engine with every
// 132 kV and above bus measured (BusFrequencyMeter). Prints the centre-of-inertia and worst bus RoCoF, K (their ratio),
// the angle jump, the inter-area oscillation and the time to 49.8 Hz per run, and the smallest budget meeting each
// criterion per placement. Exit 0 done, 1 a case that cannot be studied (the reason is printed), 2 usage.
void RunInertiaPlacement(List<string> a, string root)
{
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string placementText = FlagString(a, "--placements") ?? "fleet,demand,spine-t,south,optimised";
    var defaults = new GridSim.Core.Dynamics.Placement.InertiaPlacementOptions();
    IReadOnlyList<double> budgets = ParseDoubleList(FlagString(a, "--budgets"), "--budgets", 0, minExclusive: true) ?? defaults.BudgetsGvaS;
    string lossText = FlagString(a, "--losses") ?? "sizewell,hinkley,kent,scotland";
    double residual = FlagDouble(a, "--residual", defaults.ResidualFleetFraction);
    double condenserH = FlagDouble(a, "--condenser-h", defaults.CondenserH);
    IReadOnlyList<double> rocofLimits = ParseDoubleList(FlagString(a, "--rocof-limits"), "--rocof-limits", 0, minExclusive: true) ?? defaults.RocofLimitsHzPerS;
    double postEvent = FlagDouble(a, "--post-event", defaults.PostEventSeconds);
    double optimiseBudget = FlagDouble(a, "--optimise-budget", 240.0);
    int optimisePasses = FlagInt(a, "--optimise-passes", 1);
    // The field of every synchronous machine and condenser: IEEET1 (the default: real machines and condensers regulate
    // their terminal voltage, and with the field held the RMS loads, constant admittances, sag and hide part of the loss),
    // SEXS, or none (held). Typical, indicative settings: the ones stability --rms --avr uses.
    string avr = (FlagString(a, "--avr") ?? "ieeet1").ToLowerInvariant() switch
    {
        "none" => "none",
        "sexs" => "sexs",
        "ieeet1" => "ieeet1",
        var bad => FailFlag<string>("--avr", bad, "none, sexs or ieeet1"),
    };
    Func<Generator, GridSim.Core.Dynamics.Models.RmsExciter?>? exciter = avr switch
    {
        "sexs" => _ => GridSim.Core.Dynamics.Models.RmsExciter.FromSexs(GridSim.Cli.CliDefaults.SexsLeadS, GridSim.Cli.CliDefaults.SexsLagS,
            GridSim.Cli.CliDefaults.SexsGain, GridSim.Cli.CliDefaults.SexsExciterTimeS,
            fieldMinPu: GridSim.Cli.CliDefaults.SexsFieldMinPu, fieldMaxPu: GridSim.Cli.CliDefaults.SexsFieldMaxPu),
        "ieeet1" => _ => GridSim.Core.Dynamics.Models.RmsExciter.FromIeeet1(GridSim.Cli.CliDefaults.Ieeet1RegulatorGain,
            GridSim.Cli.CliDefaults.Ieeet1RegulatorTimeS, GridSim.Cli.CliDefaults.Ieeet1ExciterConstant, GridSim.Cli.CliDefaults.Ieeet1ExciterTimeS,
            GridSim.Cli.CliDefaults.Ieeet1FeedbackGain, GridSim.Cli.CliDefaults.Ieeet1FeedbackTimeS,
            GridSim.Cli.CliDefaults.Ieeet1RegulatorMinPu, GridSim.Cli.CliDefaults.Ieeet1RegulatorMaxPu),
        _ => null,
    };
    if (!(residual > 0.0) || residual > 1.0) FailFlag<double>("--residual", residual.ToString("R", inv), "a fraction above 0 and at most 1");
    if (!(condenserH > 0.0)) FailFlag<double>("--condenser-h", condenserH.ToString("R", inv), "an inertia constant above 0 s");
    if (!(postEvent >= 1.0) || postEvent > 60.0) FailFlag<double>("--post-event", postEvent.ToString("R", inv), "1 to 60 seconds");
    if (optimisePasses < 1) FailFlag<int>("--optimise-passes", optimisePasses.ToString(inv), "at least 1");
    for (int i = 1; i < budgets.Count; i++)
        if (!(budgets[i] > budgets[i - 1])) FailFlag<string>("--budgets", string.Join(",", budgets.Select(b => b.ToString("R", inv))), "budgets in ascending order with no repeats");

    var lossByKey = new Dictionary<string, GridSim.Core.Dynamics.Placement.PlacementLoss>(StringComparer.OrdinalIgnoreCase)
    {
        ["sizewell"] = GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.DefaultLosses[0],
        ["hinkley"] = GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.DefaultLosses[1],
        ["kent"] = GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.DefaultLosses[2],
        ["scotland"] = GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.DefaultLosses[3],
    };
    var losses = new List<GridSim.Core.Dynamics.Placement.PlacementLoss>();
    foreach (string key in lossText.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
    {
        if (!lossByKey.TryGetValue(key, out var l)) FailFlag<string>("--losses", key, "a comma list of sizewell, hinkley, kent, scotland");
        else if (losses.Contains(l)) FailFlag<string>("--losses", key, "each loss once");
        else losses.Add(l);
    }
    var known = new[] { "fleet", "demand", "spine-t", "south", "optimised" };
    var placementNames = new List<string>();
    foreach (string p in placementText.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
    {
        string k = p.ToLowerInvariant();
        if (!known.Contains(k)) FailFlag<string>("--placements", p, "a comma list of fleet, demand, spine-t, south, optimised");
        else if (placementNames.Contains(k)) FailFlag<string>("--placements", p, "each placement once");
        else placementNames.Add(k);
    }
    if (losses.Count == 0) FailFlag<string>("--losses", lossText, "at least one loss");
    if (placementNames.Count == 0) FailFlag<string>("--placements", placementText, "at least one placement");

    string caseArg = AnalysisCasePositional("inertia-placement", a) ?? "gb-full";
    GridModel m;
    try { m = LoadCaseArgument(caseArg, root); }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{caseArg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    var options = defaults with
    {
        BudgetsGvaS = budgets, ResidualFleetFraction = residual, CondenserH = condenserH, RocofLimitsHzPerS = rocofLimits,
        PostEventSeconds = postEvent,
    };
    PowerFlowResult Solve(GridModel g) => backend.NewtonSolver(g).Solve(g, new PowerFlowOptions { MaxIterations = 100 });

    Console.WriteLine($"GridSim  -  INERTIA PLACEMENT STUDY (RMS, synthetic GENROU machines, field: {(avr == "none" ? "held" : avr.ToUpperInvariant())})  *  {m.Name}");
    Console.WriteLine(new string('=', 66));
    GridSim.Core.Dynamics.Placement.InertiaPlacementReport rep;
    try
    {
        var sites = GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.SpineTSites
            .Select(s => GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.MapSite(m, s)).ToList();
        var placements = new List<GridSim.Core.Dynamics.Placement.InertiaPlacement>();
        foreach (string name in placementNames)
        {
            switch (name)
            {
                case "fleet": placements.Add(GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.FleetPlacement(m)); break;
                case "demand": placements.Add(GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.DemandPlacement(m)); break;
                case "spine-t":
                    placements.Add(GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.SitePlacement("spine-t",
                        "the inverted T / ladder sites, equal shares", sites));
                    break;
                case "south":
                    placements.Add(GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.SitePlacement("south",
                        "everything at one site, Thames (London): a deliberately concentrated contrast",
                        sites.Where(s => s.Site.Name.StartsWith("Thames", StringComparison.Ordinal)).ToList()));
                    break;
                case "optimised":
                {
                    Console.WriteLine($"optimising the site weights at {optimiseBudget.ToString("0.###", inv)} GVA.s ({optimisePasses} pass(es)):");
                    var opt = GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.Optimise(m, sites, optimiseBudget, losses, options,
                        optimisePasses, InertiaPlacementMachineData, Solve, exciter, line => Console.WriteLine("  " + line));
                    Console.WriteLine($"  {opt.Evaluations} evaluations; worst bus RoCoF {opt.StartObjective.ToString("0.00000", inv)} -> {opt.Objective.ToString("0.00000", inv)} Hz/s");
                    placements.Add(GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.SitePlacement("optimised",
                        "the T sites, weights from the coordinate search at " + optimiseBudget.ToString("0.###", inv) + " GVA.s: "
                        + string.Join(", ", sites.Select((s, i) => $"{s.Site.Name} {opt.Weights[i].ToString("0.###", inv)}")),
                        sites, opt.Weights));
                    break;
                }
            }
        }
        rep = GridSim.Core.Dynamics.Placement.InertiaPlacementStudy.Run(m, placements, losses, options, sites,
            InertiaPlacementMachineData, Solve, exciter, line => Console.WriteLine("  " + line));
    }
    catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
    {
        Console.Error.WriteLine($"error: inertia-placement: {ex.Message}");
        Environment.ExitCode = CliExit.InputError;
        return;
    }

    Console.WriteLine();
    Console.WriteLine($"fleet inertia {rep.FleetInertiaGvaS.ToString("0.###", inv)} GVA.s, residual kept {rep.ResidualInertiaGvaS.ToString("0.###", inv)} GVA.s "
        + $"({residual.ToString("0.###", inv)} of it); condensers H = {condenserH.ToString("0.###", inv)} s; demand {rep.DemandMw.ToString("0", inv)} MW; "
        + $"{rep.MeasuredBuses} buses measured (132 kV and above)");
    Console.WriteLine("sites:");
    foreach (var s in rep.Sites)
        Console.WriteLine($"  {s.Site.Name,-34} bus {s.BusId,-6} {s.BusName,-24} {s.BaseKv,5:0} kV  {s.DistanceMiles.ToString("0.0", inv),6} miles");
    Console.WriteLine("losses:");
    foreach (var (loss, at) in rep.Losses)
        Console.WriteLine($"  {loss.Site.Name,-34} {loss.Mw.ToString("0", inv)} MW at bus {at.BusId} {at.BusName} ({at.DistanceMiles.ToString("0.0", inv)} miles)");
    Console.WriteLine();
    Console.WriteLine("smallest scanned budget meeting each criterion (interpolated between the last budget that fails and the first that passes):");
    foreach (var mn in rep.Minimums)
        Console.WriteLine($"  {mn.Placement,-10} {mn.Criterion,-44} "
            + (double.IsNaN(mn.FirstPassingBudgetGvaS) ? "not met by any scanned budget"
               : $"{mn.FirstPassingBudgetGvaS.ToString("0", inv)} GVA.s" + (double.IsNaN(mn.InterpolatedBudgetGvaS) ? " (the smallest scanned)" : $" (about {mn.InterpolatedBudgetGvaS.ToString("0", inv)})")));
    Console.WriteLine();
    Console.WriteLine("with the case's frequency response (lumped model, default GB response; placement makes no difference):");
    foreach (var l in rep.Lumped)
        Console.WriteLine($"  {l.BudgetGvaS,7:0} GVA.s  {l.LossMw.ToString("0", inv)} MW  time to {options.FrequencyFloorHz.ToString("0.0", inv)} Hz "
            + (double.IsNaN(l.TimeToFloorSeconds) ? "never" : l.TimeToFloorSeconds.ToString("0.000", inv) + " s") + $"  nadir {l.NadirHz.ToString("0.000", inv)} Hz");
    foreach (string note in rep.Notes) Console.WriteLine($"note: {note}");
    if (rep.Runs.Any(r => !r.StayedInSynchronism)) Console.WriteLine("note: at least one run lost synchronism (see the runs table, in_sync).");
    if (rep.Runs.Any(r => r.ConverterIterationFailures > 0)) Console.WriteLine("note: at least one run had converter iterations that hit their cap (see the runs table).");

    CliResult? res = CliOutput.Report;
    if (res is not null)
    {
        res.Set("case", m.Name).Set("fleet_inertia_gva_s", rep.FleetInertiaGvaS).Set("residual_inertia_gva_s", rep.ResidualInertiaGvaS)
            .Set("residual_fraction", residual).Set("condenser_h_s", condenserH).Set("demand_mw", rep.DemandMw)
            .Set("measured_buses", rep.MeasuredBuses).Set("rocof_limits_hz_per_s", string.Join(",", rocofLimits.Select(l => l.ToString("R", inv)))).Set("post_event_s", postEvent).Set("avr", avr);
        CliResultTable runs = res.Table("runs", "placement", "budget_gva_s", "loss", "loss_bus", "loss_mw", "coi_rocof_hz_per_s",
            "worst_bus_rocof_hz_per_s", "worst_rocof_bus", "worst_rocof_bus_lat_deg", "k", "worst_angle_jump_deg", "worst_jump_bus",
            "inter_area_damping_ratio", "inter_area_hz", "time_to_floor_no_response_s", "lowest_coi_hz", "in_sync", "converter_iteration_failures",
            "machine_inertia_gva_s", "effective_loss_mw", "full_loss_worst_bus_rocof_hz_per_s", "swing_time_to_floor_s",
            "inter_area_half_cycles");
        foreach (var r in rep.Runs)
            runs.Row(r.Placement, r.BudgetGvaS, r.Loss, r.LossBusId, r.LossMw, r.CoiRocofHzPerS, r.WorstBusRocofHzPerS, r.WorstRocofBusId,
                r.WorstRocofBusLatDeg, r.SpatialPenaltyK, r.WorstAngleJumpDeg, r.WorstJumpBusId, r.InterAreaDampingRatio, r.InterAreaFrequencyHz,
                r.TimeToFloorNoResponseSeconds, r.LowestCoiHz, r.StayedInSynchronism, r.ConverterIterationFailures,
                r.MachineInertiaGvaS, r.EffectiveLossMw, r.ScaledWorstBusRocofHzPerS, r.SwingTimeToFloorSeconds,
                r.InterAreaHalfCycles);
        CliResultTable mins = res.Table("minimums", "placement", "criterion", "first_passing_budget_gva_s", "last_failing_budget_gva_s", "interpolated_budget_gva_s");
        foreach (var mn in rep.Minimums) mins.Row(mn.Placement, mn.Criterion, mn.FirstPassingBudgetGvaS, mn.LastFailingBudgetGvaS, mn.InterpolatedBudgetGvaS);
        CliResultTable lumpedT = res.Table("lumped", "budget_gva_s", "loss_mw", "time_to_floor_s", "nadir_hz");
        foreach (var l in rep.Lumped) lumpedT.Row(l.BudgetGvaS, l.LossMw, l.TimeToFloorSeconds, l.NadirHz);
        CliResultTable sitesT = res.Table("sites", "site", "lat_deg", "lon_deg", "bus", "bus_name", "base_kv", "distance_miles");
        foreach (var s in rep.Sites) sitesT.Row(s.Site.Name, s.Site.LatDeg, s.Site.LonDeg, s.BusId, s.BusName, s.BaseKv, s.DistanceMiles);
        CliResultTable placementsT = res.Table("placements", "placement", "description", "bus", "share");
        foreach (var p in rep.Placements) foreach (var (bus, share) in p.Shares) placementsT.Row(p.Name, p.Description, bus, share);
        res.Complete();
    }
}

// The inertia placement study's RMS machine data: the synthetic GENROU machine `stability --rms` builds when a case
// carries no machine dynamics (typical ratios off X'd = CliDefaults.SyntheticXdpPu, clearly indicative), for every unit,
// the added condensers included (the study reads only the integrated machines' entries).
static GridSim.Core.Dynamics.Models.SubtransientInit.MachineData InertiaPlacementMachineData(Generator gen)
{
    double xdp = GridSim.Cli.CliDefaults.SyntheticXdpPu;
    return new GridSim.Core.Dynamics.Models.SubtransientInit.MachineData(
        H: gen.H, Damping: GridSim.Cli.CliDefaults.SyntheticMachineDamping,
        Xd: GridSim.Cli.CliDefaults.GenrouXdOverXdp * xdp, Xdp: xdp, Xdpp: GridSim.Cli.CliDefaults.GenrouXdppOverXdp * xdp,
        Xq: GridSim.Cli.CliDefaults.GenrouXqOverXdp * xdp, Xqp: GridSim.Cli.CliDefaults.GenrouXqpOverXdp * xdp,
        Xqpp: GridSim.Cli.CliDefaults.GenrouXqppOverXdp * xdp,
        Tdop: GridSim.Cli.CliDefaults.GenrouTdopS, Tdopp: GridSim.Cli.CliDefaults.GenrouTdoppS,
        Tqop: GridSim.Cli.CliDefaults.GenrouTqopS, Tqopp: GridSim.Cli.CliDefaults.GenrouTqoppS);
}

// scuc <case> [--uc-data <file.json>] [--periods N] [--no-line-limits] [--node-cap 100000] [--gap 1e-6] [--top 12]
// 2026-10-25 (roadmap Tranche B item 8, backlog P0-3): security-constrained unit commitment (UnitCommitment, a mixed-integer
// program solved by MilpBranchAndBound over the sparse interior point LP): which units run in each period and at what
// output, at least cost, with minimum up/down times, start-up costs, ramps, spinning reserve, the rated branches' DC limits
// and the secured outages of a gridsim-uc/1 data file. Exit 0 optimal, 1 input the commitment cannot build (the reason is
// printed), 2 usage, 3 no proven optimum (infeasible, node cap or a node relaxation that failed; an incumbent found before
// a cap is printed, labelled as not proven).
void RunScuc(List<string> a, string root)
{
    string? dataFile = FlagString(a, "--uc-data");
    int periodsFlag = FlagInt(a, "--periods", 0);
    bool noLimits = a.Remove("--no-line-limits");
    int nodeCap = FlagInt(a, "--node-cap", 100_000);
    double gap = FlagDouble(a, "--gap", 1e-6);
    int top = FlagCount(a, "--top", 12, 0);
    if (periodsFlag < 0) FailFlag<int>("--periods", periodsFlag.ToString(System.Globalization.CultureInfo.InvariantCulture), "at least 1");
    if (nodeCap < 1) FailFlag<int>("--node-cap", nodeCap.ToString(System.Globalization.CultureInfo.InvariantCulture), "at least 1");
    if (!(gap >= 0) || !double.IsFinite(gap)) FailFlag<double>("--gap", gap.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a finite number at or above 0");
    GridModel? m = LoadAnalysisCase(a, root, "scuc", "gridsim scuc <case> [--uc-data <file.json>] [--periods N] [--no-line-limits] [--node-cap 100000] [--gap 1e-6] [--top 12]");
    if (m is null) return;

    GridSim.Core.Analysis.UcOptions o;
    try
    {
        int? periods = periodsFlag > 0 ? periodsFlag : null;
        if (dataFile is not null)
        {
            if (!File.Exists(dataFile)) { Console.Error.WriteLine($"[scuc] unit commitment file not found: {dataFile}"); Environment.ExitCode = CliExit.InputError; return; }
            o = GridSim.Core.Analysis.UnitCommitmentFile.Read(File.ReadAllText(dataFile), Path.GetFileName(dataFile), m, periods);
        }
        else
        {
            o = new GridSim.Core.Analysis.UcOptions { Periods = periods ?? 1 };
        }
        o = o with
        {
            EnforceLineLimits = !noLimits,
            Milp = new GridSim.Core.Numerics.MilpOptions { NodeCap = nodeCap, RelativeGap = gap },
        };
    }
    catch (InvalidDataException ex) { Console.Error.WriteLine($"[scuc] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }

    GridSim.Core.Analysis.UcResult r;
    try { r = GridSim.Core.Analysis.UnitCommitment.Solve(m, o); }
    catch (Exception ex) when (ex is ArgumentException or InvalidDataException) { Console.Error.WriteLine($"[scuc] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }

    var inv = System.Globalization.CultureInfo.InvariantCulture;
    Console.WriteLine($"SCUC (unit commitment, branch-and-bound) - {m.Name} ({m.BusCount} buses, {m.Generators.Count} units, {o.Periods} period(s) of {o.PeriodHours.ToString("R", inv)} h)");
    Console.WriteLine($"  problem: {r.Rows} rows, {r.Columns} columns ({r.IntegerColumns} whole); {r.Nodes} node(s), {r.LpIterations} interior point iteration(s)");
    foreach (string note in r.Notes) Console.WriteLine($"  note: {note}");
    if (!r.Optimal)
    {
        Console.Error.WriteLine($"scuc: no proven optimum ({r.Status}): {r.Message}.");
        Environment.ExitCode = CliExit.Verdict;
        if (r.Units.Count == 0) return;
        Console.WriteLine($"  NOT PROVEN OPTIMAL: best schedule found so far, cost {r.TotalCost.ToString("F2", inv)}, best bound {r.Bound.ToString("F2", inv)}");
    }
    else
    {
        Console.WriteLine($"  optimal: total cost {r.TotalCost.ToString("F2", inv)} (energy {r.EnergyCost.ToString("F2", inv)}, no-load {r.NoLoadCost.ToString("F2", inv)}, start-up {r.StartupCost.ToString("F2", inv)}), bound {r.Bound.ToString("F2", inv)}");
    }
    Console.WriteLine("  period  demand MW  generation MW  headroom MW  reserve MW  system price /MWh  units on");
    foreach (GridSim.Core.Analysis.UcPeriod p in r.Periods)
    {
        int on = r.Units.Count(u => u.On[p.Period - 1]);
        Console.WriteLine($"  {p.Period,6} {p.DemandMw.ToString("F2", inv),10} {p.GenerationMw.ToString("F2", inv),14} {p.HeadroomMw.ToString("F2", inv),12} {p.ReserveMw.ToString("F2", inv),11} {p.SystemPrice.ToString("F4", inv),18} {on,9}");
    }
    Console.WriteLine($"  schedules (largest {Math.Min(top, r.Units.Count)} of {r.Units.Count} units by energy; 1 = on, * = started):");
    foreach (GridSim.Core.Analysis.UcUnitSchedule u in r.Units.OrderByDescending(u => u.OutputMw.Sum()).ThenBy(u => u.Index).Take(top))
    {
        string pattern = string.Concat(Enumerable.Range(0, u.On.Length).Select(t => u.Started[t] ? '*' : u.On[t] ? '1' : '0'));
        Console.WriteLine($"      unit {u.Index,-4} bus {u.Bus,-6} {u.Name,-20} {pattern}  energy {(u.OutputMw.Sum() * o.PeriodHours).ToString("F2", inv)} MWh  cost {u.Cost.ToString("F2", inv)}");
    }
    Console.WriteLine($"  binding branch limits: {r.Bindings.Count}");
    foreach (GridSim.Core.Analysis.UcBinding b in r.Bindings.Take(top))
        Console.WriteLine($"      period {b.Period,-4} branch {b.Branch,-5} {b.Name,-24} {(b.Contingency < 0 ? "intact" : $"after outage of branch {b.Contingency}"),-30} flow {b.FlowMw.ToString("F2", inv)} MW / {b.RateMw.ToString("F2", inv)}");
    if (r.Bindings.Count > top) Console.WriteLine($"      ... and {r.Bindings.Count - top} more (--top N lists more)");

    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("buses", m.BusCount).Set("units", m.Generators.Count).Set("periods", o.Periods)
            .Set("period_hours", o.PeriodHours).Set("status", r.Status.ToString()).Set("optimal", r.Optimal)
            .Set("total_cost", r.TotalCost).Set("energy_cost", r.EnergyCost).Set("no_load_cost", r.NoLoadCost)
            .Set("startup_cost", r.StartupCost).Set("bound", r.Bound).Set("nodes", r.Nodes).Set("lp_iterations", r.LpIterations)
            .Set("rows", r.Rows).Set("columns", r.Columns).Set("integer_columns", r.IntegerColumns)
            .Set("line_limits", !noLimits).Set("contingencies", o.Contingencies.Count).Set("uc_data", dataFile ?? "none");
        CliResultTable periods = rep.Table("periods", "period", "demand_mw", "generation_mw", "headroom_mw", "reserve_mw", "system_price_per_mwh");
        foreach (GridSim.Core.Analysis.UcPeriod p in r.Periods) periods.Row(p.Period, p.DemandMw, p.GenerationMw, p.HeadroomMw, p.ReserveMw, p.SystemPrice);
        CliResultTable sched = rep.Table("schedule", "unit", "bus", "name", "period", "on", "started", "output_mw");
        foreach (GridSim.Core.Analysis.UcUnitSchedule u in r.Units)
            for (int t = 0; t < u.On.Length; t++) sched.Row(u.Index, u.Bus, u.Name, t + 1, u.On[t], u.Started[t], u.OutputMw[t]);
        CliResultTable binding = rep.Table("binding", "period", "branch", "name", "contingency", "flow_mw", "rate_mw");
        foreach (GridSim.Core.Analysis.UcBinding b in r.Bindings) binding.Row(b.Period, b.Branch, b.Name, b.Contingency, b.FlowMw, b.RateMw);
        rep.Complete();
    }
}

// scopf <case> [--contingencies all|<i,j,...>] [--post-rating A|B|C] [--linear-costs case|<file.json>] [--full-lp] [--max-rounds 50] [--top 12]
// 2026-10-25 (backlog P0-3): preventive security-constrained DC OPF (DcScopf, a sparse LP on bus angles solved by
// SparseBoundedSimplex, the outage limits added by constraint generation through the LODF). Exit 0 optimal, 1 input the
// SCOPF cannot build (the reason is printed), 2 usage, 3 no optimum (infeasible security set, round cap, LP failure).
void RunScopf(List<string> a, string root)
{
    const string usage = "gridsim scopf <case> [--contingencies all|<i,j,...>] [--post-rating A|B|C] [--linear-costs case|<file.json>] [--full-lp] [--max-rounds 50] [--top 12]";
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    bool fullLp = a.Remove("--full-lp");
    string? contText = FlagString(a, "--contingencies");
    string? costs = FlagString(a, "--linear-costs");
    int maxRounds = FlagCount(a, "--max-rounds", 50, 1);
    int top = FlagCount(a, "--top", 12, 0);
    string? ratingText = FlagString(a, "--post-rating");
    PostFaultRating rating = (ratingText ?? "A").ToUpperInvariant() switch
    {
        "A" => PostFaultRating.RateA,
        "B" => PostFaultRating.RateB,
        "C" => PostFaultRating.RateC,
        _ => FailFlag<PostFaultRating>("--post-rating", ratingText!, "A, B or C"),
    };
    int[]? contingencies = null;
    if (contText is not null && !contText.Equals("all", StringComparison.OrdinalIgnoreCase))
    {
        var list = new List<int>();
        foreach (string part in contText.Split(','))
        {
            if (!int.TryParse(part.Trim(), System.Globalization.NumberStyles.None, inv, out int k))
                FailFlag<string>("--contingencies", contText, "all or a comma list of branch indices (from 0)");
            list.Add(k);
        }
        contingencies = list.ToArray();
    }
    GridModel? m = LoadAnalysisCase(a, root, "scopf", usage);
    if (m is null) return;

    // Costs: the fuel-type merit order (GBP/MWh), or with --linear-costs each unit's own curve, which must be linear (the
    // preventive SCOPF takes a marginal cost per unit; a quadratic or piecewise-linear curve is refused, not approximated).
    double[]? costPerGen = null;
    double constantCost = 0;
    if (costs is not null)
    {
        if (costs.Equals("case", StringComparison.OrdinalIgnoreCase))
        {
            int missing = m.Generators.Count(g => g.Cost is null);
            if (missing > 0)
            {
                Console.Error.WriteLine($"[scopf] --linear-costs case: {missing} of {m.Generators.Count} in-service generator(s) carry no cost curve (the case has no mpc.gencost for them); give a cost file instead.");
                Environment.ExitCode = CliExit.InputError;
                return;
            }
        }
        else
        {
            try { m = GridSim.Core.IO.Json.GeneratorCostFile.Apply(m, costs); }
            catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or IOException)
            { Console.Error.WriteLine($"[scopf] --linear-costs: {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
        }
        costPerGen = new double[m.Generators.Count];
        for (int g = 0; g < m.Generators.Count; g++)
        {
            string who = $"unit {g} ({m.Generators[g].Name ?? $"bus {m.Generators[g].Bus}"})";
            if (m.Generators[g].Cost is null)
            {
                Console.Error.WriteLine($"[scopf] --linear-costs: {who} has no cost curve (neither the case nor the file gives one).");
                Environment.ExitCode = CliExit.InputError;
                return;
            }
            GridSim.Core.Analysis.GeneratorCostCurve curve;
            try { curve = GridSim.Core.Analysis.GeneratorCostCurve.From(m.Generators[g].Cost!, who); }
            catch (InvalidDataException ex) { Console.Error.WriteLine($"[scopf] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
            if (curve.IsPiecewiseLinear || curve.Quadratic != 0.0)
            {
                Console.Error.WriteLine($"[scopf] {who}: the cost curve is {(curve.IsPiecewiseLinear ? "piecewise-linear" : "quadratic")}; scopf takes linear costs only (a polynomial with no quadratic term). Give a cost file with linear curves, or leave --linear-costs out for the fuel-type costs.");
                Environment.ExitCode = CliExit.InputError;
                return;
            }
            costPerGen[g] = curve.Linear;
            constantCost += curve.Constant;
        }
    }

    var o = new GridSim.Core.Analysis.ScopfOptions
    {
        Contingencies = contingencies, PostContingencyRating = rating, CostPerGen = costPerGen,
        ConstraintGeneration = !fullLp, MaxRounds = maxRounds,
    };
    GridSim.Core.Analysis.ScopfResult r;
    try { r = GridSim.Core.Analysis.DcScopf.Solve(m, o); }
    catch (Exception ex) when (ex is ArgumentException or InvalidDataException or InvalidOperationException)
    { Console.Error.WriteLine($"[scopf] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }

    string money = costs is null ? "GBP" : "cost units";
    string rateLetter = rating switch { PostFaultRating.RateB => "B", PostFaultRating.RateC => "C", _ => "A" };
    Console.WriteLine($"SCOPF (preventive, DC) - {m.Name} ({m.BusCount} buses, {m.Generators.Count} units, {m.Branches.Count} branches)");
    Console.WriteLine($"  outages secured: {r.Contingencies.Count}; islanding outages not secured: {r.IslandingOutages.Count}; post-outage rating: {rateLetter} (A where not given)");
    Console.WriteLine($"  LP: {r.Rows} rows, {r.Columns} columns, {r.PostContingencyRows} post-outage limit(s); {r.Rounds} solve(s) {(fullLp ? "(full LP)" : "(constraint generation)")}, {r.LpIterations} simplex iteration(s)");
    if (r.IslandingOutages.Count > 0)
        Console.WriteLine($"  islanding outages (not secured): {string.Join(", ", r.IslandingOutages.Take(top))}{(r.IslandingOutages.Count > top ? $" ... and {r.IslandingOutages.Count - top} more" : "")}");
    if (!r.Optimal)
    {
        Console.Error.WriteLine($"scopf: no secure dispatch ({r.Status}): {r.Message}.");
        Environment.ExitCode = CliExit.Verdict;
        return;
    }
    double total = r.TotalCost + constantCost;
    Console.WriteLine($"  optimal: total cost {total.ToString("F2", inv)} {money}/h, demand {r.DemandMw.ToString("F2", inv)} MW");
    double minLmp = r.Prices.Min(p => p.Lmp), maxLmp = r.Prices.Max(p => p.Lmp);
    Console.WriteLine($"  nodal prices: {minLmp.ToString("F4", inv)} to {maxLmp.ToString("F4", inv)} {money}/MWh");
    Console.WriteLine($"  dispatch (largest {Math.Min(top, r.Dispatch.Count)} of {r.Dispatch.Count} units):");
    foreach (GridSim.Core.Analysis.ScopfDispatch d in r.Dispatch.OrderByDescending(d => d.Pmw).ThenBy(d => d.Index).Take(top))
        Console.WriteLine($"      unit {d.Index,-4} bus {d.Bus,-6} {d.Name,-20} {d.Pmw.ToString("F2", inv),10} MW  at {d.CostPerMwh.ToString("F2", inv)} {money}/MWh");
    Console.WriteLine($"  binding branch limits: {r.Bindings.Count}");
    foreach (GridSim.Core.Analysis.ScopfBinding b in r.Bindings.Take(top))
        Console.WriteLine($"      branch {b.Branch,-5} {b.Name,-24} {(b.Contingency < 0 ? "intact" : $"after outage of branch {b.Contingency}"),-30} flow {b.FlowMw.ToString("F2", inv)} MW / {b.RateMw.ToString("F2", inv)}");
    if (r.Bindings.Count > top) Console.WriteLine($"      ... and {r.Bindings.Count - top} more (--top N lists more)");

    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("buses", m.BusCount).Set("units", m.Generators.Count).Set("status", r.Status.ToString())
            .Set("optimal", r.Optimal).Set("total_cost_per_h", total).Set("cost_units", money).Set("demand_mw", r.DemandMw)
            .Set("post_fault_rating", rateLetter).Set("outages_secured", r.Contingencies.Count)
            .Set("islanding_outages", r.IslandingOutages.Count).Set("rounds", r.Rounds).Set("post_outage_rows", r.PostContingencyRows)
            .Set("rows", r.Rows).Set("columns", r.Columns).Set("lp_iterations", r.LpIterations).Set("full_lp", fullLp);
        CliResultTable dispatch = rep.Table("dispatch", "unit", "bus", "name", "p_mw", "marginal_cost_per_mwh");
        foreach (GridSim.Core.Analysis.ScopfDispatch d in r.Dispatch) dispatch.Row(d.Index, d.Bus, d.Name, d.Pmw, d.CostPerMwh);
        CliResultTable prices = rep.Table("prices", "bus_id", "lmp_per_mwh");
        foreach (GridSim.Core.Analysis.ScopfBusPrice p in r.Prices) prices.Row(p.BusId, p.Lmp);
        CliResultTable binding = rep.Table("binding", "branch", "name", "contingency", "flow_mw", "rate_mw");
        foreach (GridSim.Core.Analysis.ScopfBinding b in r.Bindings) binding.Row(b.Branch, b.Name, b.Contingency, b.FlowMw, b.RateMw);
        CliResultTable islandingT = rep.Table("islanding_outages", "branch");
        foreach (int k in r.IslandingOutages) islandingT.Row(k);
        rep.Complete();
    }
}

// qsts <case> --study <file.json> [--top 10] [--allow-unsettled]
// P2-2: quasi-static time series (GridSim.Core.Qsts): a sequence of warm-started power flows over the study file's
// profiles with timed controls (tap changers, capacitor banks, inverter functions, storage). The engine is the one the
// case solve picks (the sweep for a radial feeder or with --bfs, else the shared Newton on the selected backend), with
// the default power-flow options. Work and report in QstsCli.
void RunQsts(List<string> a, string root)
{
    const string usage = "gridsim qsts <case> --study <file.json> [--top 10] [--allow-unsettled]";
    RequireVerbFlags("qsts", a, "--study", "--top", "--allow-unsettled");
    bool allowUnsettled = a.Remove("--allow-unsettled");
    string? studyPath = FlagString(a, "--study");
    int top = FlagCount(a, "--top", 10, 0);
    if (studyPath is null) { Console.Error.WriteLine($"error: qsts needs --study <file.json>. usage: {usage}"); Environment.ExitCode = CliExit.Usage; return; }
    GridModel? m = LoadAnalysisCase(a, root, "qsts", usage);
    if (m is null) return;
    bool radial = useBfs || SolverBackend.LooksRadial(m);
    IPowerFlowSolver engine = radial ? new BackwardForwardSweep() : backend.Solver(m);
    string label = radial ? SolverSelector.Label(SolverKind.DistributionSweep) : engine.GetType().Name;
    Environment.ExitCode = GridSim.Cli.QstsCli.Run(m, engine, label, studyPath, top, allowUnsettled);
}

// hosting <case> [--study <file.json>] [--method snapshot|qsts] [--resource pv|load] [--buses all|<ids>] [--max-mw X]
// [--tolerance-mw T] [--snapshots d:r,...] [--resource-profile NAME] [--pv-function unity|pf|volt-var|volt-watt]
// [--mva-per-mw 1] [--load-pf 1] [--reverse-branch auto|none|NAME] [--reverse-allowance-mw 0] [--allowed-violation-s 0]
// [--tap-increase-pct P] [--criteria list] [--threads N] [--top 20]
// P2-2: hosting capacity by bisection (GridSim.Core.Qsts.HostingCapacity), snapshot or QSTS method. Report in HostingCli.
void RunHosting(List<string> a, string root)
{
    const string usage = "gridsim hosting <case> [--study <file.json>] [--method snapshot|qsts] [--resource pv|load] [--buses all|<ids>] [--max-mw X] [--tolerance-mw T] [--snapshots d:r,...] [--resource-profile NAME] [--pv-function unity|pf|volt-var|volt-watt] [--mva-per-mw 1] [--load-pf 1] [--reverse-branch auto|none|NAME] [--reverse-allowance-mw 0] [--allowed-violation-s 0] [--tap-increase-pct P] [--criteria list] [--threads N] [--top 20]";
    RequireVerbFlags("hosting", a, "--study", "--method", "--resource", "--buses", "--max-mw", "--tolerance-mw", "--snapshots", "--resource-profile",
        "--pv-function", "--mva-per-mw", "--load-pf", "--reverse-branch", "--reverse-allowance-mw", "--allowed-violation-s", "--tap-increase-pct",
        "--criteria", "--threads", "--top");
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string? studyPath = FlagString(a, "--study");
    HC.HostingMethod method = (FlagString(a, "--method") ?? "snapshot") switch
    {
        "snapshot" => HC.HostingMethod.Snapshot,
        "qsts" => HC.HostingMethod.Qsts,
        var bad => FailFlag<HC.HostingMethod>("--method", bad, "snapshot or qsts"),
    };
    HC.HostedResource resource = (FlagString(a, "--resource") ?? "pv") switch
    {
        "pv" => HC.HostedResource.Pv,
        "load" => HC.HostedResource.Load,
        var bad => FailFlag<HC.HostedResource>("--resource", bad, "pv or load"),
    };
    string? busesText = FlagString(a, "--buses");
    double maxMw = FlagDouble(a, "--max-mw", double.NaN);
    double tolMw = FlagDouble(a, "--tolerance-mw", double.NaN);
    string? snapText = FlagString(a, "--snapshots");
    string? resourceProfile = FlagString(a, "--resource-profile");
    HC.InverterFunction fn = (FlagString(a, "--pv-function") ?? "unity") switch
    {
        "unity" => HC.InverterFunction.Unity,
        "pf" => HC.InverterFunction.FixedPowerFactor,
        "volt-var" => HC.InverterFunction.VoltVar,
        "volt-watt" => HC.InverterFunction.VoltWatt,
        var bad => FailFlag<HC.InverterFunction>("--pv-function", bad, "unity, pf, volt-var or volt-watt"),
    };
    double mvaPerMw = FlagDouble(a, "--mva-per-mw", 1.0);
    double loadPf = FlagDouble(a, "--load-pf", 1.0);
    string reverseText = FlagString(a, "--reverse-branch") ?? "auto";
    double reverseAllowance = FlagDouble(a, "--reverse-allowance-mw", 0.0);
    double allowedS = FlagDouble(a, "--allowed-violation-s", 0.0);
    double tapPct = FlagDouble(a, "--tap-increase-pct", double.NaN);
    string? criteriaText = FlagString(a, "--criteria");
    int threads = FlagCount(a, "--threads", 1, 1);
    int top = FlagCount(a, "--top", 20, 0);
    if (method == HC.HostingMethod.Qsts && studyPath is null)
    {
        Console.Error.WriteLine($"error: hosting --method qsts needs --study <file.json> (the time series). usage: {usage}");
        Environment.ExitCode = CliExit.Usage;
        return;
    }
    if (method == HC.HostingMethod.Snapshot && resourceProfile is not null) FailFlag<string>("--resource-profile", resourceProfile, "only with --method qsts");
    HashSet<HC.HostingConstraint>? criteria = null;
    if (criteriaText is not null)
    {
        criteria = new HashSet<HC.HostingConstraint>();
        foreach (string c in criteriaText.Split(','))
            criteria.Add(c.Trim() switch
            {
                "overvoltage" => HC.HostingConstraint.Overvoltage,
                "undervoltage" => HC.HostingConstraint.Undervoltage,
                "thermal" => HC.HostingConstraint.Thermal,
                "reverse-power" => HC.HostingConstraint.ReversePower,
                "tap-operations" => HC.HostingConstraint.TapOperations,
                "non-convergence" => HC.HostingConstraint.NonConvergence,
                var bad => FailFlag<HC.HostingConstraint>("--criteria", bad, "a comma list of overvoltage, undervoltage, thermal, reverse-power, tap-operations, non-convergence"),
            });
    }
    List<HC.HostingSnapshot>? snaps = null;
    if (snapText is not null)
    {
        snaps = new List<HC.HostingSnapshot>();
        foreach (string part in snapText.Split(','))
        {
            string[] dr = part.Split(':');
            if (dr.Length != 2
                || !double.TryParse(dr[0], System.Globalization.NumberStyles.Float, inv, out double d)
                || !double.TryParse(dr[1], System.Globalization.NumberStyles.Float, inv, out double rr))
                FailFlag<string>("--snapshots", snapText, "demand:resource pairs, e.g. 0.3:1,1:1");
            else snaps.Add(new HC.HostingSnapshot(d, rr));
        }
    }
    GridModel? m = LoadAnalysisCase(a, root, "hosting", usage);
    if (m is null) return;
    List<int>? candidates = null;
    if (busesText is not null && !busesText.Equals("all", StringComparison.OrdinalIgnoreCase))
    {
        candidates = new List<int>();
        foreach (string part in busesText.Split(','))
        {
            if (!int.TryParse(part.Trim(), System.Globalization.NumberStyles.AllowLeadingSign, inv, out int b)) FailFlag<string>("--buses", busesText, "all or a comma list of bus ids");
            candidates.Add(b);
        }
    }
    HC.QstsStudy baseStudy;
    if (studyPath is not null)
    {
        try { baseStudy = HC.QstsFile.Load(studyPath, m); }
        catch (InvalidDataException ex) { Console.Error.WriteLine($"[hosting] {ex.Message}"); Environment.ExitCode = CliExit.InputError; return; }
    }
    else baseStudy = new HC.QstsStudy { StepSeconds = 1, Steps = 1 };
    double totalDemand = m.Buses.Sum(b => Math.Max(0.0, b.Pd));
    if (double.IsNaN(maxMw)) maxMw = Math.Max(1.0, 2.0 * totalDemand);
    if (double.IsNaN(tolMw)) tolMw = maxMw / 1024.0;
    string? reverseBranch = reverseText switch
    {
        "none" => null,
        "auto" => m.Branches.FirstOrDefault(b => b.InService && b.Name is not null && m.Buses.Any(x => x.Id == b.From && x.Type == BusType.Slack))?.Name,
        var name => name,
    };
    if (reverseText == "auto" && reverseBranch is null)
        Console.Error.WriteLine("[hosting] --reverse-branch auto: no named branch leaves the slack bus, so there is no reverse-power check (name one with --reverse-branch).");
    var study = new HC.HostingStudy
    {
        Resource = resource, Method = method, Candidates = candidates, MaxMw = maxMw, ToleranceMw = tolMw, Snapshots = snaps, Base = baseStudy,
        ResourceProfile = resourceProfile, Inverter = new HC.InverterSettings(fn), MvaPerMw = mvaPerMw, LoadPowerFactor = loadPf,
        ReverseFlowBranch = reverseBranch, ReverseFlowAllowanceMw = reverseAllowance, AllowedViolationSeconds = allowedS,
        TapIncreasePercent = double.IsNaN(tapPct) ? null : tapPct, Criteria = criteria, Threads = threads,
    };
    bool radial = useBfs || SolverBackend.LooksRadial(m);
    Func<IPowerFlowSolver> engines = radial ? () => new BackwardForwardSweep() : () => backend.Solver(m);
    string label = radial ? SolverSelector.Label(SolverKind.DistributionSweep) : backend.Solver(m).GetType().Name;
    Environment.ExitCode = GridSim.Cli.HostingCli.Run(m, engines, label, study, top);
}

// iec60909 <case> --bus <id> [--type 3ph|ll|slg] [--objective max|min] [--tb 0.10] [--tk 1.0]
// R095: the IEC 60909 short-circuit duties (Iec60909.ThreePhase / LineToLine / SingleLineToGround) had no CLI entry
// point. Prints Ik'', ip, Ib, Ith, Ik, idc, the peak factor and the fault-loop R/X, and the converter share of Ik''.
void RunIec60909(List<string> a, string root)
{
    int bus = FlagInt(a, "--bus", int.MinValue);
    string type = (FlagString(a, "--type") ?? "3ph").ToLowerInvariant();
    GridSim.Core.Protection.ShortCircuit.ShortCircuitObjective objective = (FlagString(a, "--objective") ?? "max").ToLowerInvariant() switch
    {
        "max" => GridSim.Core.Protection.ShortCircuit.ShortCircuitObjective.Maximum,
        "min" => GridSim.Core.Protection.ShortCircuit.ShortCircuitObjective.Minimum,
        var bad => FailFlag<GridSim.Core.Protection.ShortCircuit.ShortCircuitObjective>("--objective", bad, "max or min"),
    };
    double tb = FlagDouble(a, "--tb", 0.10);
    double tk = FlagDouble(a, "--tk", 1.0);
    // N134 (Ruling R1): --peak-method b|c chooses the peak factor of a duty: b (the default, IEC 60909-0 Method B,
    // unchanged) or c (Method C, the equivalent frequency method NESO uses, ETYS Appendix D, S242 p.4).
    // N353 (CF5): CF4 gave the unbalanced duties (ll, slg, dlg) Method C on their own sequence loops
    // (Iec60909.LineToLine / SingleLineToGround / DoubleLineToGround take peakFactorMethod), so --peak-method c is no longer
    // refused with --type ll, slg or dlg; it is passed through. With the default b every duty is exactly as before.
    string? peakMethodText = FlagString(a, "--peak-method");
    GridSim.Core.Protection.ShortCircuit.PeakFactorMethod peakMethod = (peakMethodText ?? "b").ToLowerInvariant() switch
    {
        "b" => GridSim.Core.Protection.ShortCircuit.PeakFactorMethod.MethodB,
        "c" => GridSim.Core.Protection.ShortCircuit.PeakFactorMethod.MethodC,
        var bad => FailFlag<GridSim.Core.Protection.ShortCircuit.PeakFactorMethod>("--peak-method", bad, "b or c"),
    };
    // F21 (October 2026): --type dlg (double line to earth); --breaker kV,making,breaking,withstand[,seconds] checks a
    // switchgear rating against the duty (Iec60909.CheckBreaker); --branches lists every branch's current for the
    // three-phase fault; --all-buses runs the duty at every bus with a base kV instead of one --bus; --corrections
    // applies the IEC 60909-0 impedance-correction factors (K_G, K_S / K_SO, K_T) with the generators' rated power factor
    // from --rated-pf (required: GridSim carries none). All opt-in: without them the run is exactly as before.
    string? breakerSpec = FlagString(a, "--breaker");
    bool branchesOut = a.Remove("--branches");
    bool allBuses = a.Remove("--all-buses");
    bool corrections = a.Remove("--corrections");
    bool noUnitOltc = a.Remove("--no-unit-oltc");
    double ratedPf = FlagDouble(a, "--rated-pf", double.NaN);
    if (type is not ("3ph" or "ll" or "slg" or "dlg")) FailFlag<string>("--type", type, "3ph, ll, slg or dlg");
    if (!(tb > 0)) FailFlag<double>("--tb", tb.ToString(System.Globalization.CultureInfo.InvariantCulture), "a breaker time above 0 s");
    if (!(tk > 0)) FailFlag<double>("--tk", tk.ToString(System.Globalization.CultureInfo.InvariantCulture), "a fault duration above 0 s");
    const string usage = "gridsim iec60909 <case> (--bus <id> | --all-buses) [--type 3ph|ll|slg|dlg] [--objective max|min] [--tb 0.10] [--tk 1.0] "
        + "[--breaker kV,making_kA,breaking_kA,withstand_kA[,seconds[,asym_kA]]] [--branches [--top N]] [--corrections --rated-pf <cos phi> [--no-unit-oltc]]";
    if (bus == int.MinValue && !allBuses) { Console.Error.WriteLine("usage: " + usage); Environment.ExitCode = 2; return; }
    if (bus != int.MinValue && allBuses) { Console.Error.WriteLine("error: give --bus or --all-buses, not both."); Environment.ExitCode = 2; return; }
    if (branchesOut && (type != "3ph" || allBuses))
    {
        Console.Error.WriteLine("error: --branches lists the branch currents of a three-phase fault at one --bus.");
        Environment.ExitCode = 2; return;
    }
    // D-DOC-168 (October 2026): --top N limits the --branches list (default: every branch; it used to stop silently at 12).
    int? branchTop = null;
    if (a.Contains("--top"))
    {
        if (!branchesOut) { Console.Error.WriteLine("error: --top limits the --branches list; add --branches."); Environment.ExitCode = 2; return; }
        branchTop = FlagCount(a, "--top", 0, 0);
        if (branchTop < 1) FailFlag<int>("--top", branchTop.Value.ToString(System.Globalization.CultureInfo.InvariantCulture), "a row count of 1 or more");
    }
    if (corrections != !double.IsNaN(ratedPf) || (noUnitOltc && !corrections))
    {
        Console.Error.WriteLine("error: --corrections needs --rated-pf <cos phi> (the generators' rated power factor; GridSim carries none), and --rated-pf / --no-unit-oltc need --corrections.");
        Environment.ExitCode = 2; return;
    }
    if (corrections && !(ratedPf > 0 && ratedPf <= 1)) FailFlag<double>("--rated-pf", ratedPf.ToString(System.Globalization.CultureInfo.InvariantCulture), "a power factor in (0, 1]");
    if (corrections && objective != GridSim.Core.Protection.ShortCircuit.ShortCircuitObjective.Maximum)
    {
        Console.Error.WriteLine("error: --corrections applies the IEC 60909-0 correction factors for the maximum short-circuit current; use --objective max.");
        Environment.ExitCode = 2; return;
    }
    GridSim.Core.Protection.ShortCircuit.Iec60909.BreakerRating? breaker = null;
    if (breakerSpec is not null)
    {
        double[] parts = breakerSpec.Split(',').Select(s => double.TryParse(s, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double v) ? v : double.NaN).ToArray();
        // GR-124: an optional sixth value is the rated asymmetrical breaking current, which adds the DC breaking check.
        if (parts.Length is not (4 or 5 or 6) || parts.Any(v => !(v > 0) || !double.IsFinite(v)))
            FailFlag<string>("--breaker", breakerSpec, "kV,making_kA,breaking_kA,withstand_kA[,seconds[,asym_breaking_kA]], every value above 0");
        breaker = new GridSim.Core.Protection.ShortCircuit.Iec60909.BreakerRating(parts[0], parts[1], parts[2], parts[3], parts.Length >= 5 ? parts[4] : 1.0,
            parts.Length == 6 ? parts[5] : double.NaN);
    }
    GridModel? m = LoadAnalysisCase(a, root, "iec60909", usage);
    if (m is null) return;
    if (!allBuses && !m.Buses.Any(b => b.Id == bus)) { Console.Error.WriteLine($"iec60909: bus {bus} is not in case '{m.Name}'."); Environment.ExitCode = 2; return; }

    if (corrections)
    {
        GridSim.Core.Protection.ShortCircuit.Iec60909.CorrectionReport cr;
        try { cr = GridSim.Core.Protection.ShortCircuit.Iec60909.ApplyCorrectionFactors(m, ratedPf, unitTransformersHaveOltc: !noUnitOltc); }
        catch (ArgumentException ex) { Console.Error.WriteLine($"iec60909: {ex.Message}"); Environment.ExitCode = 1; return; }
        Console.WriteLine($"IEC 60909-0 impedance corrections (rated power factor {ratedPf}): {cr.Applied.Count} applied"
            + (cr.NotApplied.Count > 0 ? $", {cr.NotApplied.Count} not applied" : ""));
        foreach (IGrouping<string, GridSim.Core.Protection.ShortCircuit.Iec60909.CorrectionApplied> g in cr.Applied.GroupBy(x => x.Factor))
            Console.WriteLine($"  {g.Key}: {g.Count()} element(s), {g.Min(x => x.Value):F4} to {g.Max(x => x.Value):F4}");
        foreach (string why in cr.NotApplied.Take(10)) Console.WriteLine($"  not applied: {why}");
        if (cr.NotApplied.Count > 10) Console.WriteLine($"  ... and {cr.NotApplied.Count - 10} more");
        CliResult? crep = CliOutput.Report;
        if (crep is not null)
        {
            crep.Set("corrections", true).Set("rated_pf", ratedPf).Set("unit_transformers_oltc", !noUnitOltc);
            CliResultTable ct = crep.Table("corrections", "element", "name", "factor", "value");
            foreach (GridSim.Core.Protection.ShortCircuit.Iec60909.CorrectionApplied x in cr.Applied) ct.Row(x.Element, x.Name, x.Factor, x.Value);
        }
        m = cr.Model;
    }

    GridSim.Core.Protection.ShortCircuit.Iec60909.Duty DutyAt(int b) => type switch
    {
        // N353 (CF5): the peak method passes to the unbalanced duties too (default B: the call is exactly the old one).
        "ll" => GridSim.Core.Protection.ShortCircuit.Iec60909.LineToLine(m, b, objective, f0Hz: m.FrequencyHz, breakTimeSeconds: tb, faultDurationSeconds: tk,
            peakFactorMethod: peakMethod),
        "slg" => GridSim.Core.Protection.ShortCircuit.Iec60909.SingleLineToGround(m, b, objective, f0Hz: m.FrequencyHz, breakTimeSeconds: tb, faultDurationSeconds: tk,
            peakFactorMethod: peakMethod),
        "dlg" => GridSim.Core.Protection.ShortCircuit.Iec60909.DoubleLineToGround(m, b, objective, f0Hz: m.FrequencyHz, breakTimeSeconds: tb, faultDurationSeconds: tk,
            peakFactorMethod: peakMethod),
        _ => GridSim.Core.Protection.ShortCircuit.Iec60909.ThreePhase(m, b, objective, f0Hz: m.FrequencyHz, breakTimeSeconds: tb, faultDurationSeconds: tk,
            peakFactorMethod: peakMethod),
    };
    string typeName = type switch { "3ph" => "three-phase", "ll" => "line-to-line", "slg" => "single-line-to-earth", _ => "double-line-to-earth" };

    if (allBuses)
    {
        RunIec60909Sweep(m, type, typeName, objective, tb, tk, breaker, DutyAt);
        return;
    }

    GridSim.Core.Protection.ShortCircuit.Iec60909.Duty d;
    try { d = DutyAt(bus); }
    catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
    {
        Console.Error.WriteLine($"iec60909: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    Console.WriteLine($"IEC 60909 - {m.Name}, bus {bus}, {typeName}, {objective} ({m.FrequencyHz} Hz, tb {tb} s, Tk {tk} s)");
    Console.WriteLine($"  Ik''  = {d.IkppKa.ToString("R", inv)} kA  ({d.IkppPu.ToString("R", inv)} pu)" + (d.ConverterIkppKa > 0 ? $", of which converters {d.ConverterIkppKa.ToString("R", inv)} kA" : ""));
    // D-DOC-098: say when kappa is the meshed-network Method B value (1.15 x kappa(R/X), capped at 2.0 / 1.8 at LV).
    Console.WriteLine($"  ip    = {d.PeakIpKa.ToString("R", inv)} kA  (kappa {d.Kappa.ToString("R", inv)}, R/X {d.RoverX.ToString("R", inv)}"
        + (d.MeshedPeakFactor ? ", meshed network: 1.15 x kappa(R/X), Method B)"
            // N134: only with --peak-method c, so the default line is exactly as before
            : d.PeakMethod == GridSim.Core.Protection.ShortCircuit.PeakFactorMethod.MethodC
                ? $", Method C: kappa(R/X_C), R/X_C {d.PeakRoverX.ToString("R", inv)} at fc = 0.4 f)"
                : ")"));
    // D-DOC-097: say which IEC 60909-0 rule Ik (and n = 1 in Ith) follows, so an upper bound is never read as exact.
    Console.WriteLine($"  Ib    = {d.BreakingIbKa.ToString("R", inv)} kA    Ik = {d.SteadyIkKa.ToString("R", inv)} kA" + SteadyBasisNote(d.SteadyBasis));
    Console.WriteLine($"  Ith   = {d.ThermalIthKa.ToString("R", inv)} kA  (m {d.ThermalM.ToString("R", inv)})    idc(tb) = {d.DcComponentKa.ToString("R", inv)} kA");
    Console.WriteLine($"  Zth   = {d.TheveninRPu.ToString("R", inv)} + j{d.TheveninXPu.ToString("R", inv)} pu");

    // F21: the breaker check, when ratings were given. An inadequate breaker is a validation failure (exit 3).
    GridSim.Core.Protection.ShortCircuit.Iec60909.BreakerAdequacy? adequacy = null;
    if (breaker is not null)
    {
        double systemKv = m.Buses.First(b => b.Id == bus).BaseKv;
        adequacy = GridSim.Core.Protection.ShortCircuit.Iec60909.CheckBreaker(d, breaker, systemKv);
        Console.WriteLine($"  breaker {breaker.RatedVoltageKv} kV / making {breaker.MakingPeakKa} kA / breaking {breaker.BreakingSymKa} kA / {breaker.ShortTimeWithstandKa} kA for {breaker.ShortTimeSeconds} s: "
            + (adequacy.Adequate ? "ADEQUATE" : "NOT ADEQUATE"));
        // GR-606: the rated voltage is judged against the highest system voltage Um, which the line names.
        Console.WriteLine($"    voltage {(adequacy.VoltageOk ? "ok" : "TOO LOW")} (system {systemKv} kV, highest {adequacy.RequiredVoltageKv.ToString("R", inv)} kV)   making margin {adequacy.MakingMarginKa.ToString("R", inv)} kA   "
            + $"breaking margin {adequacy.BreakingMarginKa.ToString("R", inv)} kA   thermal margin {adequacy.ThermalMarginKa.ToString("R", inv)} kA"
            + (adequacy.AsymmetricalChecked ? $"   asymmetrical breaking margin {adequacy.AsymmetricalMarginKa.ToString("R", inv)} kA" : ""));
        // GR-617: a double-line-to-earth duty is checked at its largest line-conductor current, which the line states.
        if (d.DlgLineToEarthRatio > 1.0)
            Console.WriteLine($"    double-line-to-earth: currents checked at the largest line-conductor current, {d.DlgLineToEarthRatio.ToString("R", inv)} x the earth current");
        if (!adequacy.Adequate) Environment.ExitCode = 3;
    }

    // F21: the per-branch currents of the three-phase fault (the current a relay on each branch sees).
    IReadOnlyList<GridSim.Core.Protection.ShortCircuit.Iec60909.BranchFaultCurrent>? branchCurrents = null;
    if (branchesOut)
    {
        // D-DOC-168 (October 2026): the list used to stop silently at 12 rows while its header counted every in-service
        // branch. It now prints every branch by default; --top N limits it and the footer says how many were left out.
        branchCurrents = GridSim.Core.Protection.ShortCircuit.Iec60909.BranchFaultCurrents(m, bus);
        int shown = branchTop is int t ? Math.Min(t, branchCurrents.Count) : branchCurrents.Count;
        Console.WriteLine($"  branch currents ({branchCurrents.Count} in-service branch(es) in the fault bus's island, largest first"
            + (shown < branchCurrents.Count ? $", top {shown} shown" : "") + "; c_max source):");
        foreach (GridSim.Core.Protection.ShortCircuit.Iec60909.BranchFaultCurrent bc in branchCurrents.OrderByDescending(x => Math.Max(x.FromEndKa, x.ToEndKa)).Take(shown))
            Console.WriteLine($"    {bc.Name,-24} {bc.From,6} -> {bc.To,-6}  from end {bc.FromEndKa:F3} kA  to end {bc.ToEndKa:F3} kA");
        if (shown < branchCurrents.Count)
            Console.WriteLine($"    ... {branchCurrents.Count - shown} more branch(es) not shown (--top {shown}); the result file (--json / --csv) holds every one");
    }

    // F10: the same duties (already printed at round-trip precision).
    CliResult? irep = CliOutput.Report;
    irep?.Set("case", m.Name).Set("bus", bus).Set("type", type).Set("objective", objective.ToString())
        .Set("frequency_hz", m.FrequencyHz).Set("tb_s", tb).Set("tk_s", tk)
        .Set("ikpp_ka", d.IkppKa).Set("ikpp_pu", d.IkppPu).Set("converter_ikpp_ka", d.ConverterIkppKa)
        .Set("ip_ka", d.PeakIpKa).Set("kappa", d.Kappa).Set("r_over_x", d.RoverX)
        .Set("ib_ka", d.BreakingIbKa).Set("ik_ka", d.SteadyIkKa).Set("ith_ka", d.ThermalIthKa).Set("thermal_m", d.ThermalM)
        .Set("idc_ka", d.DcComponentKa).Set("thevenin_r_pu", d.TheveninRPu).Set("thevenin_x_pu", d.TheveninXPu)
        .Set("kappa_meshed", d.MeshedPeakFactor).Set("ik_basis", d.SteadyBasis.ToString());   // D-DOC-098 / D-DOC-097
    // N134: the Method C fields only when it was asked for, so a default result file is unchanged.
    if (d.PeakMethod == GridSim.Core.Protection.ShortCircuit.PeakFactorMethod.MethodC)
        irep?.Set("peak_method", "C").Set("r_over_x_c", d.PeakRoverX);
    // N116 (October 2026): fail loud on missing earthing data, exactly as the --all-buses sweep, the fault verb and
    // protection-check --fault-type already do. An earth fault (slg, dlg) on a model that carries no transformer winding
    // connection anywhere (MATPOWER and JSON v1 cannot hold them, so no bundled case does) has no earthed neutral at
    // all: the single-line-to-earth duty comes out all-zero, and the double-line-to-earth one is solved as a
    // line-to-line fault, and both used to be reported with exit 0 as if they were the network's answer. The duty is
    // still printed (it is what the data gives), then the reason goes to stderr and the run exits 3 (a validation
    // failure: the result cannot be trusted). The result file, if asked for, records earthing_data = false. Three-phase
    // and line-to-line faults never touch the zero sequence, so they are unaffected.
    bool singleNoEarthingData = type is "slg" or "dlg" && !m.Branches.Any(b => b.FromWinding is not null || b.ToWinding is not null);
    if (type is "slg" or "dlg") irep?.Set("earthing_data", !singleNoEarthingData);
    if (singleNoEarthingData)
    {
        Console.Error.WriteLine("iec60909: the model carries no transformer winding connections at all (MATPOWER and JSON v1 cannot hold them), "
            + "so it has no earthed neutral and the earth-fault duty above reflects missing data. Exit 3.");
        Environment.ExitCode = 3;
    }
    if (irep is not null && adequacy is not null)
        irep.Set("breaker_adequate", adequacy.Adequate).Set("breaker_voltage_ok", adequacy.VoltageOk)
            .Set("making_margin_ka", adequacy.MakingMarginKa).Set("breaking_margin_ka", adequacy.BreakingMarginKa).Set("thermal_margin_ka", adequacy.ThermalMarginKa);
    if (irep is not null && branchCurrents is not null)
    {
        CliResultTable bt = irep.Table("branch_currents", "name", "from", "to", "from_end_ka", "to_end_ka", "from_end_pu", "to_end_pu");
        foreach (GridSim.Core.Protection.ShortCircuit.Iec60909.BranchFaultCurrent bc in branchCurrents) bt.Row(bc.Name, bc.From, bc.To, bc.FromEndKa, bc.ToEndKa, bc.FromEndPu, bc.ToEndPu);
    }
    irep?.Complete();
}

// F21 (October 2026): iec60909 --all-buses: the duty at every bus with a base kV, in bus order. A bus the study cannot
// form (no base kV, no source) is listed with the reason and makes the run exit 1 after the table; an inadequate breaker
// at any bus (with --breaker, checked at each bus's own voltage) makes it exit 3.
void RunIec60909Sweep(GridModel m, string type, string typeName, GridSim.Core.Protection.ShortCircuit.ShortCircuitObjective objective,
    double tb, double tk, GridSim.Core.Protection.ShortCircuit.Iec60909.BreakerRating? breaker,
    Func<int, GridSim.Core.Protection.ShortCircuit.Iec60909.Duty> dutyAt)
{
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    Console.WriteLine($"IEC 60909 sweep - {m.Name}, every bus, {typeName}, {objective} ({m.FrequencyHz} Hz, tb {tb} s, Tk {tk} s)");
    Console.WriteLine("   bus      kV        Ik'' kA        ip kA        Ib kA       Ith kA" + (breaker is not null ? "  breaker" : ""));
    CliResult? srep = CliOutput.Report;
    CliResultTable? table = srep?.Table("buses", "bus", "base_kv", "ikpp_ka", "ip_ka", "ib_ka", "ith_ka", "ik_ka", "idc_ka", "kappa", "r_over_x", "breaker_adequate", "error");
    int failed = 0, inadequate = 0, done = 0;
    double worst = 0; int worstBus = 0;
    foreach (Bus b in m.Buses)
    {
        if (!(b.BaseKv > 0))
        {
            failed++;
            Console.WriteLine($"  {b.Id,6}  no base kV: IEC 60909 needs a nominal voltage");
            table?.Row(b.Id, b.BaseKv, null, null, null, null, null, null, null, null, null, "no base kV");
            continue;
        }
        GridSim.Core.Protection.ShortCircuit.Iec60909.Duty d;
        try { d = dutyAt(b.Id); }
        catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
        {
            failed++;
            Console.WriteLine($"  {b.Id,6}  {ex.Message}");
            table?.Row(b.Id, b.BaseKv, null, null, null, null, null, null, null, null, null, ex.Message);
            continue;
        }
        done++;
        if (d.IkppKa > worst) { worst = d.IkppKa; worstBus = b.Id; }
        bool? ok = null;
        if (breaker is not null)
        {
            ok = GridSim.Core.Protection.ShortCircuit.Iec60909.CheckBreaker(d, breaker, b.BaseKv).Adequate;
            if (ok == false) inadequate++;
        }
        Console.WriteLine($"  {b.Id,6} {b.BaseKv,7:F1}  {d.IkppKa,12:F4} {d.PeakIpKa,12:F4} {d.BreakingIbKa,12:F4} {d.ThermalIthKa,12:F4}"
            + (ok is bool o ? (o ? "  adequate" : "  NOT ADEQUATE") : ""));
        table?.Row(b.Id, b.BaseKv, d.IkppKa, d.PeakIpKa, d.BreakingIbKa, d.ThermalIthKa, d.SteadyIkKa, d.DcComponentKa, d.Kappa, d.RoverX, ok, null);
    }
    Console.WriteLine($"  {done} bus(es) studied, {failed} not studied"
        + (worst > 0 ? $"; largest Ik'' {worst.ToString("R", inv)} kA at bus {worstBus}" : done > 0 ? "; no short-circuit current at any studied bus" : "")
        + (breaker is not null ? $"; breaker not adequate at {inadequate} bus(es)" : ""));
    // Fail loud on missing data, as the fault verb: an earth fault on a model with no transformer winding connection
    // anywhere has no earthed neutral, so every zero above reflects missing data, not the network.
    bool noEarthingData = type is "slg" or "dlg" && !m.Branches.Any(b => b.FromWinding is not null || b.ToWinding is not null);
    if (noEarthingData)
        Console.Error.WriteLine("iec60909: the model carries no transformer winding connections at all (MATPOWER and JSON v1 cannot hold them), "
            + "so it has no earthed neutral and the earth-fault duties above reflect missing data. Exit 3.");
    srep?.Set("case", m.Name).Set("type", type).Set("objective", objective.ToString()).Set("frequency_hz", m.FrequencyHz).Set("tb_s", tb).Set("tk_s", tk)
        .Set("studied", done).Set("not_studied", failed).Set("breaker_inadequate", breaker is null ? null : inadequate)
        .Set("earthing_data", !noEarthingData);
    srep?.Complete();
    if (failed > 0) Environment.ExitCode = 1;
    else if (inadequate > 0 || noEarthingData) Environment.ExitCode = 3;
}

// audit verify <file> [--anchor-count N --anchor-head HEX]
// audit show   <file> [--anchor-count N --anchor-head HEX]
// R075: recompute the hash chain of a gridsim-audit/1 file. OK -> exit 0; tampered (edited, deleted, inserted,
// reordered, truncated, or not matching the external anchor) -> exit 3 naming the first broken entry; a missing or
// unreadable file -> exit 1; usage errors -> exit 2. Tail truncation and a whole-log rewrite are only detectable
// against an anchor kept outside the log (count + head hash printed by the last verify or by the writer).
// N064 (October 2026): `show` runs exactly the same verification and, only when the WHOLE log verifies, prints every
// entry, one per line, in the Core display form (AuditLogFile.Describe), then the same OK line as verify. A log that
// does not verify prints NO entries (nothing after a broken link can be trusted, and printing the clean prefix next to
// a tampered tail invites reading it as evidence): the TAMPERED line and exit 3, exactly as verify.
void RunAudit(List<string> a)
{
    const string usage = "usage: gridsim audit verify|show <file> [--anchor-count N --anchor-head HEX] [--pubkey <public.pem> [--anchor <file>] [--sig <file>]]\n"
                       + "       gridsim audit sign <file> --key <private.pem> [--anchor <file>] [--sig <file>]\n"
                       + "       gridsim audit keygen <private.pem> <public.pem>";
    // `audit sign`: the strong form of the signed anchor, where the private key never sits on the host. At a checkpoint
    // the key holder verifies the log against its anchor (the whole chain), then signs that anchor offline; the host,
    // configured with only the public key (--audit-verify-key), accepts its next run against the signed anchor. A log
    // that does not verify is never signed (exit 3).
    if (a.Count >= 2 && a[1].Equals("sign", StringComparison.OrdinalIgnoreCase))
    {
        if (a.Count < 3 || a[2].StartsWith("--", StringComparison.Ordinal) || FlagString(a, "--key") is not string keyPath)
        {
            Console.Error.WriteLine(usage);
            Environment.ExitCode = 2;
            return;
        }
        string logFile = a[2];
        string anchorFileToSign = FlagString(a, "--anchor") ?? GridSim.Core.Diagnostics.AuditAnchorFile.DefaultPathFor(logFile);
        string sigOut = FlagString(a, "--sig") ?? GridSim.Core.Diagnostics.SignedAuditAnchor.DefaultPathFor(logFile);
        try
        {
            GridSim.Core.Diagnostics.AuditAnchor? toSign = GridSim.Core.Diagnostics.AuditAnchorFile.ReadIfExists(anchorFileToSign);
            if (toSign is null)
            {
                Console.Error.WriteLine($"error: audit sign: no anchor file '{anchorFileToSign}' to sign.");
                Environment.ExitCode = 1;
                return;
            }
            GridSim.Core.Diagnostics.AuditLogVerification check = GridSim.Core.Diagnostics.AuditLogFile.Verify(logFile, toSign);
            if (!check.IsValid)
            {
                Console.Error.WriteLine($"TAMPERED {logFile}: entry {check.FirstBrokenIndex}: {check.Reason}; the anchor is NOT signed.");
                Environment.ExitCode = 3;
                return;
            }
            using System.Security.Cryptography.ECDsa key = GridSim.Core.Diagnostics.AuditRecorderOptions.LoadKey(keyPath, requirePrivate: true);
            GridSim.Core.Diagnostics.SignedAuditAnchor.Write(sigOut, toSign, key);
            Console.WriteLine($"signed anchor count={toSign.Count} head={toSign.HeadHash} -> {Path.GetFullPath(sigOut)}");
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidOperationException or ArgumentException)
        {
            Console.Error.WriteLine($"error: audit sign: {ex.Message}");
            Environment.ExitCode = 1;
        }
        return;
    }
    // `audit keygen`: a fresh ECDSA P-256 key pair for the signed anchor (--audit-sign-key / --audit-verify-key). The
    // private key is written for the signing station; only the public key belongs on the host. Neither file may exist
    // already (a key is never overwritten silently).
    if (a.Count >= 2 && a[1].Equals("keygen", StringComparison.OrdinalIgnoreCase))
    {
        if (a.Count != 4 || a[2].StartsWith("--", StringComparison.Ordinal) || a[3].StartsWith("--", StringComparison.Ordinal))
        {
            Console.Error.WriteLine(usage);
            Environment.ExitCode = 2;
            return;
        }
        foreach (string target in new[] { a[2], a[3] })
            if (File.Exists(target))
            {
                Console.Error.WriteLine($"error: audit keygen: '{target}' already exists; a key file is never overwritten.");
                Environment.ExitCode = 1;
                return;
            }
        using var key = System.Security.Cryptography.ECDsa.Create(System.Security.Cryptography.ECCurve.NamedCurves.nistP256);
        try
        {
            File.WriteAllText(a[2], key.ExportPkcs8PrivateKeyPem() + "\n");
            File.WriteAllText(a[3], key.ExportSubjectPublicKeyInfoPem() + "\n");
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"error: audit keygen: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        Console.WriteLine($"private key (keep OFF the host): {Path.GetFullPath(a[2])}");
        Console.WriteLine($"public key  (for --audit-verify-key / audit verify --pubkey): {Path.GetFullPath(a[3])}");
        return;
    }
    bool show = a.Count >= 2 && a[1].Equals("show", StringComparison.OrdinalIgnoreCase);
    if (a.Count < 3 || !(show || a[1].Equals("verify", StringComparison.OrdinalIgnoreCase)) || a[2].StartsWith("--", StringComparison.Ordinal))
    {
        Console.Error.WriteLine(usage);
        Environment.ExitCode = 2;
        return;
    }
    string file = a[2];
    bool hasCount = a.Contains("--anchor-count"), hasHead = a.Contains("--anchor-head");
    if (hasCount != hasHead)
    {
        Console.Error.WriteLine("error: --anchor-count and --anchor-head go together (the anchor is the pair).");
        Environment.ExitCode = 2;
        return;
    }
    GridSim.Core.Diagnostics.AuditAnchor? anchor = null;
    if (hasCount)
    {
        int count = FlagInt(a, "--anchor-count", -1);
        if (count < 0) FailFlag<int>("--anchor-count", count.ToString(System.Globalization.CultureInfo.InvariantCulture), "a non-negative entry count");
        anchor = new GridSim.Core.Diagnostics.AuditAnchor(count, FlagString(a, "--anchor-head")!);
    }

    // The signed anchor (CAF C1): --pubkey checks the detached signature over the anchor file (default <log>.anchor,
    // signature <log>.anchor.sig), then verifies the log against that anchor. A missing or invalid signature is a
    // tamper verdict (exit 3): the log and its anchor may have been rewritten together.
    if (FlagString(a, "--pubkey") is string pubPath)
    {
        if (anchor is not null)
        {
            Console.Error.WriteLine("error: --pubkey checks the signed anchor FILE; it does not combine with --anchor-count / --anchor-head.");
            Environment.ExitCode = 2;
            return;
        }
        string anchorFile = FlagString(a, "--anchor") ?? GridSim.Core.Diagnostics.AuditAnchorFile.DefaultPathFor(file);
        string sigFile = FlagString(a, "--sig") ?? GridSim.Core.Diagnostics.SignedAuditAnchor.DefaultPathFor(file);
        try
        {
            using System.Security.Cryptography.ECDsa pub = GridSim.Core.Diagnostics.AuditRecorderOptions.LoadKey(pubPath, requirePrivate: false);
            GridSim.Core.Diagnostics.AuditAnchor? signedAnchor = GridSim.Core.Diagnostics.AuditAnchorFile.ReadIfExists(anchorFile);
            if (signedAnchor is null)
            {
                Console.Error.WriteLine($"TAMPERED {file}: no anchor file '{anchorFile}' to check the signature against");
                Environment.ExitCode = 3;
                return;
            }
            string? sig = GridSim.Core.Diagnostics.SignedAuditAnchor.ReadIfExists(sigFile);
            string why = "";
            if (sig is null || !GridSim.Core.Diagnostics.SignedAuditAnchor.Verify(signedAnchor, sig, pub, out why))
            {
                Console.Error.WriteLine($"TAMPERED {file}: anchor signature '{sigFile}': {(sig is null ? "missing" : why)}");
                Environment.ExitCode = 3;
                return;
            }
            Console.WriteLine($"signature OK: {sigFile} signs anchor count={signedAnchor.Count} head={signedAnchor.HeadHash}");
            anchor = signedAnchor;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidOperationException)
        {
            Console.Error.WriteLine($"audit: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }

    GridSim.Core.Diagnostics.AuditLogVerification v;
    try { v = GridSim.Core.Diagnostics.AuditLogFile.Verify(file, anchor); }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException)
    {
        Console.Error.WriteLine($"audit: cannot read '{file}': {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }
    if (v.IsValid)
    {
        // N064: the entries first (show only), so the OK line with the anchor is the last line, as for verify.
        if (show)
            foreach (GridSim.Core.Diagnostics.AuditLogEntry entry in v.Entries)
                Console.WriteLine(GridSim.Core.Diagnostics.AuditLogFile.Describe(entry));
        Console.WriteLine($"OK {file}: {v.VerifiedCount} entries, head {v.HeadHash}");
        return;
    }
    Console.Error.WriteLine($"TAMPERED {file}: entry {v.FirstBrokenIndex}: {v.Reason} ({v.VerifiedCount} entries verified before it)");
    Environment.ExitCode = 3;
}

void RunDistributionFactors(List<string> a, string root)
{
    bool lodf = a[0].Equals("lodf", StringComparison.OrdinalIgnoreCase);
    int bus = FlagInt(a, "--bus", -1);
    int branch = FlagInt(a, "--branch", -1);
    int top = FlagCount(a, "--top", 12, 0);
    string? arg = AnalysisCasePositional(a[0], a);
    if (arg is null) { Console.Error.WriteLine($"usage: gridsim {a[0]} <case> [{(lodf ? "--branch IDX" : "--bus ID")}] [--top N]"); Environment.ExitCode = 2; return; }

    GridModel m;
    try
    {
        // D-DOC-151: LoadCaseArgument (the same three branches, plus the folder fallback: an existing folder that is
        // not a known name loads as a case folder, so the loader names what is wrong instead of "unknown case").
        m = LoadCaseArgument(arg, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    GridSim.Core.Analysis.DistributionFactors df;
    try { df = GridSim.Core.Analysis.DistributionFactors.Build(m); }
    catch (InvalidOperationException ex) { Console.Error.WriteLine($"[{a[0]}] {ex.Message}"); Environment.ExitCode = 1; return; }

    string BranchLabel(int l) => $"{m.Branches[l].From}->{m.Branches[l].To}";

    if (lodf)
    {
        if (branch < 0 || branch >= m.Branches.Count) { Console.Error.WriteLine($"usage: gridsim lodf <case> --branch <0..{m.Branches.Count - 1}>"); Environment.ExitCode = 2; return; }
        // F10: the result file carries every branch's factor (the console lists the top N above the display floor).
        CliResult? lrep = CliOutput.Report;
        lrep?.Set("case", m.Name).Set("buses", m.BusCount).Set("branch", branch)
            .Set("from", m.Branches[branch].From).Set("to", m.Branches[branch].To);
        CliResultTable? lfactors = lrep?.Table("factors", "branch", "from", "to", "lodf");
        if (df.OutageIslands(branch))
        {
            Console.WriteLine($"LODF - {m.Name}: outage of branch {branch} ({BranchLabel(branch)}) ISLANDS the system (bridge line); LODF undefined.");
            lrep?.Set("islands_system", true).Complete();   // a finished answer: no factors exist
            return;
        }
        double[] col = df.LodfColumn(branch);
        Console.WriteLine($"LODF - {m.Name} ({m.BusCount} buses): outage of branch {branch} ({BranchLabel(branch)}) redistributes onto:");
        var ranked = Enumerable.Range(0, col.Length).Where(l => l != branch && Math.Abs(col[l]) > GridSim.Cli.CliDefaults.SensitivityDisplayFloor)
            .OrderByDescending(l => Math.Abs(col[l])).Take(top);
        foreach (int l in ranked)
            Console.WriteLine($"    branch {l,-4} {BranchLabel(l),-14} LODF {col[l],7:F4}  ({col[l] * 100,5:F1}% of the lost flow)");
        if (lrep is not null)
        {
            lrep.Set("islands_system", false);
            // The outaged branch itself is left out, as on the console (its own factor is -1 by definition).
            for (int l = 0; l < col.Length; l++)
                if (l != branch) lfactors!.Row(l, m.Branches[l].From, m.Branches[l].To, col[l]);
            lrep.Complete();
        }
    }
    else
    {
        if (bus < 0) { Console.Error.WriteLine("usage: gridsim ptdf <case> --bus <busId>"); Environment.ExitCode = 2; return; }
        // D-DOC-047 (October 2026): a --bus the case does not have is a bad flag value (exit 2, naming bus and case, the
        // D-DOC-159 rule every bus flag follows). It used to print a header and an empty list and exit 0, which reads as
        // "an injection there moves nothing".
        if (!m.Buses.Any(b => b.Id == bus))
        {
            Console.Error.WriteLine($"error: ptdf --bus {bus}: case '{m.Name}' has no bus {bus}.");
            Environment.ExitCode = 2;
            return;
        }
        double[] col = df.PtdfColumn(bus);
        // N034: with several DC islands each island has its own reference; the injection is withdrawn at the
        // reference of the bus's own island (the slack, for a connected case).
        int withdrawnAt = df.SlackBusId;
        foreach (GridSim.Core.Analysis.DcIsland isl in df.Islands)
            if (isl.BusIds.Contains(bus)) { withdrawnAt = isl.ReferenceBusId; break; }
        string where = df.Islands.Count > 1 ? $"withdrawn at its island's reference {withdrawnAt}; {df.Islands.Count} DC islands" : $"withdrawn at slack {withdrawnAt}";
        Console.WriteLine($"PTDF - {m.Name} ({m.BusCount} buses): +1 MW injected at bus {bus} ({where}) flows on:");
        var ranked = Enumerable.Range(0, col.Length).Where(l => Math.Abs(col[l]) > GridSim.Cli.CliDefaults.SensitivityDisplayFloor)
            .OrderByDescending(l => Math.Abs(col[l])).Take(top);
        foreach (int l in ranked)
            Console.WriteLine($"    branch {l,-4} {BranchLabel(l),-14} PTDF {col[l],7:F4}  ({col[l] * 100,5:F1}%)");
        // F10: every branch's factor (the console lists the top N above the display floor).
        CliResult? prep = CliOutput.Report;
        if (prep is not null)
        {
            prep.Set("case", m.Name).Set("buses", m.BusCount).Set("bus", bus).Set("withdrawn_at_bus", withdrawnAt).Set("dc_islands", df.Islands.Count);
            CliResultTable factors = prep.Table("factors", "branch", "from", "to", "ptdf");
            for (int l = 0; l < col.Length; l++) factors.Row(l, m.Branches[l].From, m.Branches[l].To, col[l]);
            prep.Complete();
        }
    }
}

void RunExperimental(List<string> a, string root)
{
    // Umbrella for opt-in, provenance-tagged experimental models. Everything here is UNVALIDATED AT
    // SCALE by design and off the validated paths: a subcommand or a bare listing.
    string? sub = a.Count > 1 ? a[1] : null;

    void Banner() => Console.Error.WriteLine(
        "[experimental] opt-in, unvalidated-at-scale models. Not part of the validated solve/estimate paths.");

    GridModel? Load(string? arg)
    {
        if (arg is null) { Console.Error.WriteLine("usage: gridsim experimental <reciprocity|wave> <case>"); Environment.ExitCode = 2; return null; }
        try
        {
            // D-DOC-151: LoadCaseArgument (same branches, plus the folder fallback).
            return LoadCaseArgument(arg, root);
        }
        catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return null; }
    }

    // F10: each subcommand fills the result file (when asked for) from the values it prints; the bare listing has no
    // result, so it writes none.
    CliResult? xrep = CliOutput.Report;
    xrep?.Set("subcommand", sub?.ToLowerInvariant());

    if (sub is null)
    {
        Console.WriteLine("GridSim experimental models (opt-in, unvalidated-at-scale):");
        Console.WriteLine("  reciprocity <case>   physical-consistency law Y = Y^T (passive-network reciprocity)");
        Console.WriteLine("  wave <case>          continuum electromechanical-wave model: inter-area normal modes");
        Console.WriteLine("                       (the 'grid as a damped-wave medium' lens; needs per-machine inertia)");
        Console.WriteLine("  modal-consistency <case>  small-signal structural residuals (COI null mode + K_ext row sum)");
        Console.WriteLine("  harmonic-kcl <case>  harmonic KCL: Y(h) V(h) = I(h) on the study-model penetration (law 12)");
        Console.WriteLine("  passivity <case> [--bus ID]  grid driving-point impedance is positive-real, 5..2500 Hz (law 14)");
        Console.WriteLine("  trace <case>         power-flow tracing: where each generator's power actually went");
        Console.WriteLine("                       (Bialek proportional-sharing over the solved flows)");
        Console.WriteLine("  carbon <case>        carbon tracing: the fuel/CO2 each load actually consumes");
        Console.WriteLine("                       (per-load gCO2/kWh from traced generation)");
        Console.WriteLine("  trace <case> --losses    which generators cause the network losses");
        Console.WriteLine("  boundaries <case>    which generators supply each ETYS boundary's transfer");
        Banner();
        return;
    }

    if (sub.Equals("boundaries", StringComparison.OrdinalIgnoreCase))
    {
        GridModel? m = Load(a.Count > 2 ? a[2] : null);
        if (m is null) return;
        int top = FlagCount(a, "--top", 6, 0);
        IPowerFlowSolver solver = backend.Solver(m);
        PowerFlowResult r = solver.Solve(m, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
        if (!r.Converged) { Console.Error.WriteLine($"[experimental] boundaries: solve did not converge ({r.Status})"); Environment.ExitCode = 3; return; }

        IReadOnlyList<GridSim.Core.Physics.Experimental.PowerFlowTracing.BoundaryTransfer> bts =
            GridSim.Core.Physics.Experimental.PowerFlowTracing.BoundaryTransfers(m, r);
        Console.WriteLine($"Boundary attribution - {m.Name} ({m.BusCount} buses)  [which generators supply each boundary transfer]");
        xrep?.Set("case", m.Name).Set("buses", m.BusCount).Set("boundaries", bts.Count);
        CliResultTable? xBoundaries = xrep?.Table("boundaries", "boundary", "net_mw", "limit_mw");
        CliResultTable? xShares = xrep?.Table("generator_shares", "boundary", "gen_bus", "mw");
        if (bts.Count == 0) { Console.WriteLine("  no boundaries defined for this case."); Banner(); xrep?.Complete(); return; }
        foreach (GridSim.Core.Physics.Experimental.PowerFlowTracing.BoundaryTransfer bt in bts)
        {
            Console.WriteLine($"  {bt.Boundary}: net {bt.NetMw:N0} MW (limit {bt.LimitMw:N0} MW):");
            foreach (GridSim.Core.Physics.Experimental.PowerFlowTracing.GenShare gs in bt.ByGenerator.Take(top))
                Console.WriteLine($"      gen bus {gs.GenBus,-6} {gs.Mw,8:N1} MW");
            // Every generator's share (the console lists the top N per boundary).
            xBoundaries?.Row(bt.Boundary, bt.NetMw, bt.LimitMw);
            if (xShares is not null)
                foreach (GridSim.Core.Physics.Experimental.PowerFlowTracing.GenShare gs in bt.ByGenerator) xShares.Row(bt.Boundary, gs.GenBus, gs.Mw);
        }
        Banner();
        xrep?.Complete();
        return;
    }

    if (sub.Equals("carbon", StringComparison.OrdinalIgnoreCase))
    {
        GridModel? m = Load(a.Count > 2 ? a[2] : null);
        if (m is null) return;
        int top = FlagCount(a, "--top", 8, 0);
        IPowerFlowSolver solver = backend.Solver(m);
        PowerFlowResult r = solver.Solve(m, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
        if (!r.Converged) { Console.Error.WriteLine($"[experimental] carbon: solve did not converge ({r.Status})"); Environment.ExitCode = 3; return; }

        GridSim.Core.Physics.Experimental.CarbonTracing.CarbonTraceResult c =
            GridSim.Core.Physics.Experimental.CarbonTracing.Trace(m, r);
        Console.WriteLine($"Carbon tracing - {m.Name} ({m.BusCount} buses)  [fuel each load actually consumes]");
        if (!c.Traced) { Console.Error.WriteLine("[experimental] carbon: flow graph has a loop - trace undefined."); Environment.ExitCode = 1; return; }
        bool anyFuel = m.Generators.Any(g => !string.IsNullOrEmpty(g.Type));
        if (!anyFuel) Console.WriteLine("  (this case carries no fuel data - intensities are the 'other' placeholder)");
        Console.WriteLine($"  system blended intensity      : {c.SystemGramsPerKwh:F0} gCO2/kWh   ({c.TotalTonnesPerHour:N1} tCO2/h)");
        Console.WriteLine("  most carbon-intensive loads:");
        foreach (GridSim.Core.Physics.Experimental.CarbonTracing.LoadCarbon lc in c.Loads.Take(top))
            Console.WriteLine($"      load bus {lc.LoadBus,-6} {lc.DemandMw,7:N0} MW   {lc.GramsPerKwh,5:F0} gCO2/kWh   ({lc.TonnesPerHour,6:N1} tCO2/h)");
        Banner();
        if (xrep is not null)
        {
            // Every load (the console lists the top N), in the order the trace ranks them.
            xrep.Set("case", m.Name).Set("buses", m.BusCount).Set("fuel_data", anyFuel)
                .Set("system_g_co2_per_kwh", c.SystemGramsPerKwh).Set("total_t_co2_per_h", c.TotalTonnesPerHour);
            CliResultTable loads = xrep.Table("loads", "load_bus", "demand_mw", "g_co2_per_kwh", "t_co2_per_h");
            foreach (GridSim.Core.Physics.Experimental.CarbonTracing.LoadCarbon lc in c.Loads) loads.Row(lc.LoadBus, lc.DemandMw, lc.GramsPerKwh, lc.TonnesPerHour);
            xrep.Complete();
        }
        return;
    }

    if (sub.Equals("trace", StringComparison.OrdinalIgnoreCase))
    {
        GridModel? m = Load(a.Count > 2 ? a[2] : null);
        if (m is null) return;
        int top = FlagCount(a, "--top", 5, 0);
        bool losses = a.Remove("--losses");
        IPowerFlowSolver solver = backend.Solver(m);
        PowerFlowResult r = solver.Solve(m, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
        if (!r.Converged) { Console.Error.WriteLine($"[experimental] trace: solve did not converge ({r.Status})"); Environment.ExitCode = 3; return; }

        GridSim.Core.Physics.Experimental.PowerFlowTracing.TraceResult tr =
            GridSim.Core.Physics.Experimental.PowerFlowTracing.Trace(m, r);
        if (!tr.FlowGraphAcyclic)
        {
            Console.Error.WriteLine("[experimental] trace: the solved flow graph has a loop - a strict proportional-sharing trace is not defined here.");
            Environment.ExitCode = 1; return;
        }
        xrep?.Set("case", m.Name).Set("buses", m.BusCount).Set("losses_mode", losses).Set("total_loss_mw", r.TotalLossMw);
        if (losses)
        {
            Console.WriteLine($"Loss attribution - {m.Name} ({m.BusCount} buses)  [which generators cause the {r.TotalLossMw:N1} MW of losses]");
            foreach (var kv in tr.GenToLossMw.OrderByDescending(x => x.Value).Take(top))
                Console.WriteLine($"  gen bus {kv.Key,-6} {kv.Value,7:N2} MW to losses  ({kv.Value / Math.Max(1e-9, r.TotalLossMw) * 100,4:N0}% of total)");
            Banner();
            if (xrep is not null)
            {
                // Every generator (the console lists the top N), largest share first.
                CliResultTable lossTable = xrep.Table("loss_attribution", "gen_bus", "loss_mw");
                foreach (var kv in tr.GenToLossMw.OrderByDescending(x => x.Value)) lossTable.Row(kv.Key, kv.Value);
                xrep.Complete();
            }
            return;
        }
        Console.WriteLine($"Power-flow tracing - {m.Name} ({m.BusCount} buses)  [where each generator's power went]");
        var byGen = tr.Allocations.GroupBy(x => x.GenBus).OrderByDescending(gp => tr.GenerationMw[gp.Key]);
        foreach (var gp in byGen)
        {
            double outMw = tr.GenerationMw[gp.Key];
            double loss = tr.GenToLossMw.TryGetValue(gp.Key, out double lv) ? lv : 0.0;
            Console.WriteLine($"  gen bus {gp.Key}  ({outMw:N0} MW out, {loss:N1} MW to losses):");
            foreach (GridSim.Core.Physics.Experimental.PowerFlowTracing.GenLoadFlow f in
                     gp.OrderByDescending(x => x.Mw).Take(top))
                Console.WriteLine($"      -> load bus {f.LoadBus,-6} {f.Mw,8:N1} MW  ({f.Mw / outMw * 100,4:N0}%)");
        }
        Banner();
        if (xrep is not null)
        {
            // Every generator and every traced allocation (the console lists the top N per generator).
            CliResultTable gens = xrep.Table("generators", "gen_bus", "generation_mw", "loss_mw");
            foreach (var g in tr.GenerationMw.OrderByDescending(x => x.Value))
                gens.Row(g.Key, g.Value, tr.GenToLossMw.TryGetValue(g.Key, out double gl) ? gl : 0.0);
            CliResultTable allocations = xrep.Table("allocations", "gen_bus", "load_bus", "mw");
            foreach (GridSim.Core.Physics.Experimental.PowerFlowTracing.GenLoadFlow f in tr.Allocations) allocations.Row(f.GenBus, f.LoadBus, f.Mw);
            xrep.Complete();
        }
        return;
    }

    if (sub.Equals("reciprocity", StringComparison.OrdinalIgnoreCase))
    {
        GridModel? m = Load(a.Count > 2 ? a[2] : null);
        if (m is null) return;
        GridSim.Core.Physics.LawResult r = GridSim.Core.Physics.Experimental.ReciprocityCheck.Evaluate(m);
        Console.WriteLine($"Reciprocity (experimental) - {m.Name} ({m.BusCount} buses)");
        Console.WriteLine($"  status: {r.Status}   residual: {r.Residual:E3} pu   {r.Detail}");
        Banner();
        xrep?.Set("case", m.Name).Set("buses", m.BusCount).Set("status", r.Status.ToString()).Set("residual_pu", r.Residual)
            .Set("detail", r.Detail).Complete();
        return;
    }

    if (sub.Equals("wave", StringComparison.OrdinalIgnoreCase))
    {
        GridModel? m = Load(a.Count > 2 ? a[2] : null);
        if (m is null) return;
        IPowerFlowSolver solver = backend.Solver(m);
        PowerFlowResult r = solver.Solve(m, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
        if (!r.Converged) { Console.Error.WriteLine($"[experimental] wave: solve did not converge ({r.Status})"); Environment.ExitCode = 3; return; }

        // N155 (October 2026): ask first whether the wave model can form at all. A case with no per-machine inertia (a
        // MATPOWER case's loader leaves H = 0) used to be refused only after the classical reduction had built its dense
        // network matrices (about 1.46 GB on gb-full) and then thrown. CannotFormReason gives the same refusal, with the
        // same message, before anything is built; the exit code is unchanged (1, input data the model cannot use).
        string? cannotForm = GridSim.Core.Physics.Experimental.ContinuumWaveModel.CannotFormReason(m, r);
        if (cannotForm is not null)
        {
            Console.Error.WriteLine($"[experimental] wave: {cannotForm}");
            Console.Error.WriteLine("[experimental] wave: refused before the classical reduction (no network matrix was built): " +
                "the wave model needs a machine inertia constant H > 0 for every generator. Give the case per-machine inertia " +
                "(H in the generator data) to run it.");
            Environment.ExitCode = 1;
            return;
        }

        GridSim.Core.Physics.Experimental.ContinuumWaveModel.WaveModes w;
        try { w = GridSim.Core.Physics.Experimental.ContinuumWaveModel.FromSolvedCase(m, r); }
        catch (InvalidOperationException ex) { Console.Error.WriteLine($"[experimental] wave: {ex.Message}"); Environment.ExitCode = 1; return; }

        Console.WriteLine($"Continuum electromechanical-wave model - {m.Name} ({m.BusCount} buses)");
        Console.WriteLine("  The linearised swing is a damped wave equation M d2(delta)/dt2 + D d(delta)/dt + K_L delta = P.");
        Console.WriteLine("  Its normal modes are the network's inter-area electromechanical oscillations.");
        Console.WriteLine($"  centre-of-inertia (null) mode : {w.CoiModeHz:F4} Hz");
        // N282 (October 2026, stream B1): an islanded network has one rigid-body (zero) mode per island of machines; they
        // are all skipped before the dominant mode. Printed only when there is more than one, so a connected case's
        // output is unchanged.
        if (w.RigidBodyModeCount > 1)
            Console.WriteLine($"  rigid-body (island) modes     : {w.RigidBodyModeCount} (one per island of machines; skipped)");
        Console.WriteLine($"  dominant inter-area mode      : {w.DominantInterAreaHz:F4} Hz");
        Console.WriteLine($"  all inter-area modes (Hz)     : {string.Join(", ", w.InterAreaModesHz.Select(f => f.ToString("F3")))}");
        Console.WriteLine($"  medium 'stiffness' (mean K)   : {w.MeanSynchronisingMwPerRad:F1} MW/rad");
        // R035 (October 2026, stream B5): the modes are those of the SYMMETRIC part of the synchronising coupling; the
        // antisymmetric part (the transfer-conductance term) is set aside and its size is printed so the approximation
        // is visible. Mean K above is now in MW/rad (it was the per-unit figure on the case base).
        Console.WriteLine($"  coupling asymmetry set aside  : {w.MaxCouplingAsymmetry:F1} MW/rad (largest |k_ij - k_ji|, transfer conductances; the symmetric part is analysed)");
        Console.WriteLine($"  medium 'density' (mean H)     : {w.MeanInertiaSeconds:F2} s");
        if (w.DominantModeShape.Count > 0)
        {
            var plus = w.DominantModeShape.Where(s => s.Amplitude > 0.05).OrderByDescending(s => s.Amplitude).Select(s => $"bus {s.Machine}");
            var minus = w.DominantModeShape.Where(s => s.Amplitude < -0.05).OrderBy(s => s.Amplitude).Select(s => $"bus {s.Machine}");
            Console.WriteLine($"  dominant mode shape           : ({string.Join(", ", plus)})  swings AGAINST  ({string.Join(", ", minus)})");
        }
        Console.WriteLine("  (Inertia is the density term; damping D is the viscosity analogue. Undamped modes shown.)");
        Banner();
        if (xrep is not null)
        {
            xrep.Set("case", m.Name).Set("buses", m.BusCount).Set("coi_mode_hz", w.CoiModeHz).Set("dominant_inter_area_hz", w.DominantInterAreaHz)
                .Set("mean_synchronising_mw_per_rad", w.MeanSynchronisingMwPerRad).Set("mean_inertia_s", w.MeanInertiaSeconds)
                .Set("max_coupling_asymmetry_mw_per_rad", w.MaxCouplingAsymmetry);
            CliResultTable modes = xrep.Table("inter_area_modes", "index", "hz");
            for (int k = 0; k < w.InterAreaModesHz.Count; k++) modes.Row(k, w.InterAreaModesHz[k]);
            CliResultTable shape = xrep.Table("dominant_mode_shape", "machine_bus", "amplitude");
            foreach (var s in w.DominantModeShape) shape.Row(s.Machine, s.Amplitude);
            xrep.Complete();
        }
        return;
    }

    if (sub.Equals("modal-consistency", StringComparison.OrdinalIgnoreCase))
    {
        GridModel? m = Load(a.Count > 2 ? a[2] : null);
        if (m is null) return;
        PowerFlowResult r = backend.NewtonSolver(m).Solve(m);   // shared rule on the selected backend (was CPU dense always; R104)
        if (!r.Converged) { Console.Error.WriteLine($"[experimental] modal-consistency: solve did not converge ({r.Status})"); Environment.ExitCode = 3; return; }
        double[]? xdp = null;
        // GR-684: chosen by the case argument only (a user case whose name is "WSCC-9" used to get these reactances too).
        if (a.Count > 2 && a[2].ToLowerInvariant() is "case9" or "ieee9")
        {
            var byBus = IeeeCases.Wscc9TransientReactancePu;
            xdp = m.Generators.Select(gn => byBus.GetValueOrDefault(gn.Bus, GridSim.Cli.CliDefaults.SyntheticXdpPu)).ToArray();
        }
        SmallSignalModel ssm;
        try { ssm = SmallSignalAssembler.FromSolvedCase(m, r, xdp); }
        catch (InvalidOperationException ex) { Console.Error.WriteLine($"[experimental] modal-consistency: {ex.Message}"); Environment.ExitCode = 1; return; }
        GridSim.Core.Physics.Experimental.SmallSignalConsistencyReport rep =
            GridSim.Core.Physics.Experimental.SmallSignalConsistency.Evaluate(ssm);
        Console.WriteLine($"Small-signal consistency (experimental) - {m.Name} ({m.BusCount} buses)");
        foreach (GridSim.Core.Physics.LawResult lr in rep.Laws)
            Console.WriteLine($"  [{lr.Status}] {lr.Name}: residual {lr.Residual:E3} {lr.Unit} (tol {lr.Tolerance:E3}) - {lr.Detail}");
        Console.WriteLine($"  overall: {rep.Status}");
        Banner();
        if (xrep is not null)
        {
            xrep.Set("case", m.Name).Set("buses", m.BusCount).Set("overall", rep.Status.ToString());
            CliResultTable laws = xrep.Table("laws", "number", "name", "status", "residual", "unit", "tolerance", "detail");
            foreach (GridSim.Core.Physics.LawResult lr in rep.Laws) laws.Row(lr.Number, lr.Name, lr.Status.ToString(), lr.Residual, lr.Unit, lr.Tolerance, lr.Detail);
            xrep.Complete();
        }
        return;
    }

    if (sub.Equals("harmonic-kcl", StringComparison.OrdinalIgnoreCase))
    {
        // R091: the harmonic KCL law had no production caller. Run the study-model penetration (synthetic 6-pulse
        // source at the largest-demand bus, as the 'harmonics' verb does) and audit Y(h) V(h) = I(h).
        GridModel? m = Load(a.Count > 2 ? a[2] : null);
        if (m is null) return;
        int srcBus = m.Buses.OrderByDescending(b => b.Pd).FirstOrDefault()?.Id ?? m.Buses[0].Id;
        // N131 (Ruling R1): the default synthetic source is the G5 Issue 5 Table B.3 six-pulse profile, as in 'harmonics'.
        var src = new[] { HarmonicSourceLibrary.Make(HarmonicSourceLibrary.DefaultSyntheticSourceType, srcBus, fundamentalCurrentPu: GridSim.Cli.CliDefaults.DefaultHarmonicSourcePu) };
        HarmonicModelOptions hopt = HarmonicModelOptions.Study;
        HarmonicPenetrationResult pen;
        try { pen = HarmonicPenetration.Solve(m, src, hopt); }
        catch (SingularHarmonicNetworkException ex) { Console.Error.WriteLine($"[experimental] harmonic-kcl: {ex.Message}"); Environment.ExitCode = 1; return; }
        GridSim.Core.Physics.LawResult lr = GridSim.Core.Physics.Experimental.HarmonicKclCheck.Evaluate(m, src, pen, hopt);
        Console.WriteLine($"Harmonic KCL (experimental) - {m.Name} ({m.BusCount} buses), {HarmonicSourceLibrary.DefaultSyntheticSourceType} source at bus {srcBus}");
        Console.WriteLine($"  [{lr.Status}] law {lr.Number} {lr.Name}: residual {lr.Residual:E3} {lr.Unit} (tol {lr.Tolerance:E3}) - {lr.Detail}");
        if (lr.Status == GridSim.Core.Physics.LawStatus.Violated) Environment.ExitCode = 1;
        Banner();
        xrep?.Set("case", m.Name).Set("buses", m.BusCount).Set("source_bus", srcBus).Set("law", lr.Number).Set("name", lr.Name)
            .Set("status", lr.Status.ToString()).Set("residual", lr.Residual).Set("unit", lr.Unit).Set("tolerance", lr.Tolerance)
            .Set("detail", lr.Detail).Complete();
        return;
    }

    if (sub.Equals("passivity", StringComparison.OrdinalIgnoreCase))
    {
        // R091: the grid passivity law had no production caller. Driving-point impedance at --bus (default: the
        // largest generator's bus) over 5..2500 Hz in 5 Hz steps, on the positive-sequence study network
        // (machines + loads; a fractional-frequency sweep, so not the balanced-harmonic mode).
        GridModel? m = Load(a.Count > 2 && !a[2].StartsWith("--") ? a[2] : null);
        if (m is null) return;
        int bus = FlagInt(a, "--bus", int.MinValue);
        if (bus == int.MinValue)
        {
            Generator? big = m.Generators.OrderByDescending(g => g.Pg).FirstOrDefault();
            if (big is null) { Console.Error.WriteLine("[experimental] passivity: no generator to pick a default bus; pass --bus ID"); Environment.ExitCode = 2; return; }
            bus = big.Bus;
        }
        if (!m.Buses.Any(b => b.Id == bus)) { Console.Error.WriteLine($"[experimental] passivity: bus {bus} is not in the model"); Environment.ExitCode = 2; return; }
        double f0 = m.FrequencyHz;
        double[] fHz = Enumerable.Range(1, 500).Select(k => 5.0 * k).ToArray();
        HarmonicModelOptions popt = HarmonicModelOptions.Study with { BalancedHarmonicSequences = false };
        GridSim.Core.Physics.LawResult lr;
        try { lr = GridSim.Core.Physics.Experimental.ImpedancePassivityCheck.AuditGridPassivity(m, bus, fHz, f0, popt); }
        catch (InvalidOperationException ex) { Console.Error.WriteLine($"[experimental] passivity: {ex.Message}"); Environment.ExitCode = 1; return; }
        Console.WriteLine($"Grid passivity (experimental) - {m.Name} ({m.BusCount} buses), bus {bus}, 5..2500 Hz");
        Console.WriteLine($"  [{lr.Status}] law {lr.Number} {lr.Name}: residual {lr.Residual:E3} {lr.Unit} (tol {lr.Tolerance:E3}) - {lr.Detail}");
        if (lr.Status == GridSim.Core.Physics.LawStatus.Violated) Environment.ExitCode = 1;
        Banner();
        xrep?.Set("case", m.Name).Set("buses", m.BusCount).Set("bus", bus).Set("law", lr.Number).Set("name", lr.Name)
            .Set("status", lr.Status.ToString()).Set("residual", lr.Residual).Set("unit", lr.Unit).Set("tolerance", lr.Tolerance)
            .Set("detail", lr.Detail).Complete();
        return;
    }

    Console.Error.WriteLine($"unknown experimental subcommand '{sub}' (expected 'reciprocity', 'wave', 'modal-consistency', 'harmonic-kcl', 'passivity', 'trace', 'carbon' or 'boundaries')");
    Environment.ExitCode = 2;
}

void RunConformance(List<string> a, string root)
{
    // D-DOC-039: --no-allowances switches off the documented list of known-unconverged corpus cases
    // (ConformanceAllowances), for a run that wants every case to converge.
    bool useAllowances = !a.Remove("--no-allowances");
    string outDir = FlagString(a, "--out") ?? DefaultResultsPath("conformance");
    // D-DOC-125: with no --tol each case is audited at the one documented default, BaseMva * 1e-8 MVA (the solver's
    // own convergence promise on that case's base; PhysicsLaws.DefaultTolMva). It was an absolute 1e-4 MVA, which on
    // a 100 MVA case was a hundred times looser than the solve it judged. --tol still sets one absolute line for all.
    double? tolFlag = a.Contains("--tol") ? FlagDouble(a, "--tol", 0.0) : null;
    if (tolFlag is double tf && !(tf >= 0.0))
        FailFlag<double>("--tol", tf.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a tolerance of 0 MVA or more");
    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    // GR-678: ties on the size key are broken by ordinal label order, which no ICU version can change.
    var cases = BuildCases(root).OrderBy(c => c.SortKey).ThenBy(c => c.Label, StringComparer.Ordinal).ToList();
    string tolText = tolFlag is double t0 ? $"{t0:E1}" : "BaseMva*1e-8";
    string desc = $"conformance  cases={cases.Count}  tol={tolText}  allowances={(useAllowances ? "on" : "off")}";

    string mdPath = Path.Combine(outDir, "conformance.md");
    using var md = new StreamWriter(CliFiles.Output(mdPath, "conformance report")) { AutoFlush = true };
    using var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "conformance.csv"), "conformance.csv")) { AutoFlush = true };
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run-metadata.json"), desc);

    void Emit(string s) { Console.WriteLine(s); md.WriteLine(s); }
    foreach (string h in RunInfo.HeaderLines(desc)) Emit("    " + h);
    foreach (string h in RunInfo.HeaderLines(desc)) csv.WriteLine("# " + h);
    csv.WriteLine("case,buses,converged,gate_pass,law_number,law_name,status,residual,unit,tolerance,commit");

    Emit("");
    Emit("Physical-law conformance sweep. GATE = every hard law (energy/Ohm/Joule/KCL/complex-power)");
    Emit("holds, i.e. the solved state is physically admissible. NOTE: lake-scale sweep over stored");
    Emit("estimated/presolved states runs via tools/crossval/physics_audit.py (this verb sweeps cases).");
    Emit(tolFlag is null
        ? "Tolerance: BaseMva x 1e-8 MVA per case (the solver's convergence tolerance on that case's base)."
        : $"Tolerance: {tolText} MVA for every case (--tol).");
    Emit("");
    Emit("| case | buses | conv | gate | worst hard law | residual |");
    Emit("|------|------:|:----:|:----:|----------------|---------:|");

    var hard = new HashSet<int>(GridSim.Core.Physics.PhysicsCheckRegistry.HardGateLaws);
    int pass = 0, total = 0, skipped = 0, unallowed = 0;
    var allowedHits = new List<(string Case, string Reason)>();
    var allowanceNotNeeded = new List<string>();
    foreach ((string label, Func<GridModel> load, int _) in cases)
    {
        GridModel model;
        try { model = load(); }
        catch (Exception ex) { Console.Error.WriteLine($"  [skip] {label}: {ex.Message}"); skipped++; continue; }

        string caseName = Path.GetFileNameWithoutExtension(label);
        IPowerFlowSolver raw = backend.Solver(model);
        PowerFlowResult r;
        try { r = raw.Solve(model, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true }); }
        catch (Exception ex) { Console.Error.WriteLine($"  [skip] {caseName}: {ex.Message}"); skipped++; continue; }

        if (!r.Converged)
        {
            // D-DOC-039: a case on the allowance list that ends with exactly the status the list expects is reported
            // as an allowed failure (with its reason) and does not fail the run; anything else is a real failure.
            GridSim.Cli.ConformanceAllowances.Allowance? allowed = useAllowances
                ? GridSim.Cli.ConformanceAllowances.For(caseName, r.Status.ToString())
                : null;
            if (allowed is not null)
            {
                Emit($"| {caseName} | {model.BusCount} | no | allowed | (unconverged: {r.Status}; known, see below) | - |");
                allowedHits.Add((caseName, allowed.Reason));
            }
            else
            {
                Emit($"| {caseName} | {model.BusCount} | no | - | (unconverged: {r.Status}) | - |");
                unallowed++;   // R220: counted, and fails the run below
            }
            continue;
        }
        if (useAllowances && GridSim.Cli.ConformanceAllowances.IsListed(caseName))
            allowanceNotNeeded.Add(caseName);

        GridSim.Core.Physics.PhysicsLawReport report = GridSim.Core.Physics.PhysicsLaws.Audit(model, r, tolFlag);
        bool gate = report.Gate(GridSim.Core.Physics.PhysicsCheckRegistry.HardGateLaws);
        total++;
        if (gate) pass++;

        GridSim.Core.Physics.LawResult worst = report.Laws
            .Where(l => hard.Contains(l.Number))
            .OrderByDescending(l => double.IsNaN(l.Residual) ? 0.0 : l.Residual)
            .First();
        Emit($"| {caseName} | {model.BusCount} | yes | {(gate ? "PASS" : "**FAIL**")} | {worst.Name} | {worst.Residual:E2} |");

        foreach (GridSim.Core.Physics.LawResult l in report.Laws)
        {
            string res = double.IsNaN(l.Residual) ? "" : l.Residual.ToString("E6", System.Globalization.CultureInfo.InvariantCulture);
            csv.WriteLine($"{caseName},{model.BusCount},true,{gate},{l.Number},\"{l.Name}\",{l.Status},{res},{l.Unit},{l.Tolerance},{RunInfo.GitCommit}");
        }
    }

    Emit("");
    Emit($"Conformance: **{pass}/{total}** converged cases physically admissible (all hard laws hold); {skipped} skipped; "
        + $"{allowedHits.Count} known unconverged (allowed); {unallowed} unconverged and not allowed.");
    if (allowedHits.Count > 0)
    {
        Emit("");
        Emit("Allowed unconverged cases (the documented list in src/GridSim.Cli/ConformanceAllowances.cs; --no-allowances turns it off):");
        foreach ((string c, string why) in allowedHits) Emit($"- {c}: {why}");
    }
    Console.Error.WriteLine($"[conformance] {pass}/{total} admissible -> {Path.GetFullPath(mdPath)}");
    foreach (string c in allowanceNotNeeded)
        Console.Error.WriteLine($"[conformance] note: {c} is on the allowance list but converged this run; it was audited like any other case.");
    // D-DOC-039: one exit rule (ConformanceAllowances.ExitCode): 3 for a case that could not be run or did not
    // converge without an allowance (R220: such a case must never vanish from the gate), else 1 for a gate failure on
    // a converged case, else 0. Before, the three known PGLib cases made every run of the shipped corpus exit 3.
    if (unallowed > 0 || skipped > 0)
        Console.Error.WriteLine($"[conformance] {unallowed} case(s) did not converge without an allowance and {skipped} could not be run: gate FAILED.");
    if (pass < total)
        Console.Error.WriteLine($"[conformance] {total - pass} converged case(s) failed the hard-law gate: gate FAILED.");
    Environment.ExitCode = GridSim.Cli.ConformanceAllowances.ExitCode(total - pass, unallowed, skipped);
}

void RunPhysicsCheck(List<string> a, string root)
{
    string? arg = AnalysisCasePositional("physics-check", a);
    if (arg is null)
    {
        Console.Error.WriteLine("usage: gridsim physics-check <case|case.m|case-dir> [--tol MVA]");
        Environment.ExitCode = 2; return;
    }
    // D-DOC-125: with no --tol the audit uses the one documented default, BaseMva * 1e-8 MVA (the solver's own
    // convergence promise on this case's base; PhysicsLaws.DefaultTolMva). It was an absolute 1e-4 MVA. --tol still
    // sets an absolute line in MVA. A negative tolerance is refused (nothing could ever pass it).
    double? tolFlag = a.Contains("--tol") ? FlagDouble(a, "--tol", 0.0) : null;
    if (tolFlag is double tf && !(tf >= 0.0))
        FailFlag<double>("--tol", tf.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a tolerance of 0 MVA or more");

    GridModel m;
    try
    {
        // D-DOC-151: LoadCaseArgument (the same three branches, plus the folder fallback: an existing folder that is
        // not a known name loads as a case folder, so the loader names what is wrong instead of "unknown case").
        m = LoadCaseArgument(arg, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    double tol = tolFlag ?? GridSim.Core.Physics.PhysicsLaws.DefaultTolMva(m);
    var opt = new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true };
    IPowerFlowSolver solver = backend.Solver(m);
    PowerFlowResult r = solver.Solve(m, opt);

    string tolNote = tolFlag is null ? $"tol {tol:E1} MVA = BaseMva {m.BaseMva:G} x 1e-8" : $"tol {tol:E1} MVA";
    Console.WriteLine($"Physics-law audit  -  {arg}  ({m.BusCount} buses, converged={r.Converged}, {tolNote})");
    Console.WriteLine("| # | law | status | residual | unit | detail |");
    Console.WriteLine("|---|-----|--------|----------|------|--------|");
    GridSim.Core.Physics.PhysicsLawReport report = GridSim.Core.Physics.PhysicsLaws.Audit(m, r, tol);
    foreach (GridSim.Core.Physics.LawResult law in report.Laws)
    {
        string res = double.IsNaN(law.Residual) ? "-"
            : law.Residual.ToString("E2", System.Globalization.CultureInfo.InvariantCulture);
        Console.WriteLine($"| {law.Number} | {law.Name} | {law.Status} | {res} | {law.Unit} | {law.Detail} |");
    }
    bool lawsHold = report.Gate(GridSim.Core.Physics.PhysicsCheckRegistry.HardGateLaws);
    // D-DOC-042 (October 2026): the gate also requires a converged solve. Before, it read the hard laws alone, so a
    // non-converged iterate whose hard laws happened to hold printed "GATE: PASS" and exited 0 (fail loud, CONTRIBUTING.md:
    // a non-converged result is never reported as success). The laws are still printed above for diagnosis.
    bool gate = r.Converged && lawsHold;
    // D-DOC-128 (October 2026): the worst violated law is printed as a sentence, not the raw LawResult record.
    string? worstText = report.Worst is { } w ? WorstLawText(w) : null;
    Console.WriteLine();
    if (gate)
        Console.WriteLine("GATE: PASS  -  state is physically admissible (all hard laws hold).");
    else if (!r.Converged)
        Console.WriteLine($"GATE: FAIL  -  the power flow did not converge (status {r.Status}, max mismatch {r.MaxMismatch:E2} pu after "
            + $"{r.Iterations} iterations); a non-converged state is not audited as admissible."
            + (worstText is null ? "" : $" Worst law at the last iterate: {worstText}"));
    else
        Console.WriteLine($"GATE: FAIL  -  physically-impossible state. Worst: {worstText}");
    // Exit codes (manual ch. 19): 3 when the power flow did not converge (the convergence rule every verb follows,
    // and the same code conformance gives an unconverged case), 1 when a converged state fails the hard-law gate.
    if (!r.Converged) Environment.ExitCode = 3;
    else if (!lawsHold) Environment.ExitCode = 1;
    // F10: every law's row at full precision (a residual the console shows as "-" is NaN here), and the gate. A failed
    // gate is a finished result (exit 1 or 3) and is written too.
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", arg).Set("buses", m.BusCount).Set("converged", r.Converged).Set("tol_mva", tol)
            .Set("gate_pass", gate).Set("worst", gate ? null : worstText);
        CliResultTable laws = rep.Table("laws", "number", "name", "status", "residual", "unit", "detail");
        foreach (GridSim.Core.Physics.LawResult law in report.Laws) laws.Row(law.Number, law.Name, law.Status.ToString(), law.Residual, law.Unit, law.Detail);
        rep.Complete();
    }
}

// D-DOC-128: one violated law as a sentence ("law 6 Kirchhoff's current law: residual 1.90E+000 MW above the
// tolerance 1.00E-006 MW (detail)") for the physics-check gate line and its result file, in place of the record's
// raw ToString ("LawResult { Number = 6, Name = ... }").
static string WorstLawText(GridSim.Core.Physics.LawResult law)
    => string.Create(System.Globalization.CultureInfo.InvariantCulture,
        $"law {law.Number} {law.Name}: residual {law.Residual:E2} {law.Unit} above the tolerance {law.Tolerance:E2} {law.Unit} ({law.Detail})");

void RunProtectionCheck(List<string> a, string root)
{
    // GR-214: --cascade is a switch with no value, but PositionalArg skips every --flag together with the token after
    // it, so `protection-check --cascade case9` lost the case. The positional is looked up without the switch.
    string? arg = AnalysisCasePositional("protection-check", a.Where(t => t != "--cascade").ToList());
    if (arg is null)
    {
        Console.Error.WriteLine("usage: gridsim protection-check <case|case.m|case-dir> "
            + "[--uv pu] [--ov pu] [--uf Hz] [--of Hz] [--oc xIn] [--thermal frac] [--rocof Hz/s] "
            + "[--cascade [--alarms <soe.csv>] | --fault-bus ID [--zf pu]]");
        Environment.ExitCode = 2; return;
    }

    // R095: --fault-bus ID assesses the protection on a balanced three-phase fault at that bus
    // (ProtectionAssessment.AssessThreePhaseFault), instead of on the steady solved state. --zf is the fault
    // impedance (pu, default 0 = bolted) and needs --fault-bus. The cascade follows the steady state, so it does not
    // combine with a fault study; both refusals are usage errors (exit 2) rather than a silently ignored flag.
    int? faultBus = null;
    if (a.Contains("--fault-bus")) faultBus = FlagInt(a, "--fault-bus", 0);
    // F21 (October 2026): --fault-type slg|ll|dlg assesses an unbalanced fault (the earth-fault and negative-sequence
    // elements then have sequence currents to measure); 3ph, the default, is the balanced study, unchanged.
    string faultType = (FlagString(a, "--fault-type") ?? "3ph").ToLowerInvariant();
    if (faultType is not ("3ph" or "slg" or "ll" or "dlg")) FailFlag<string>("--fault-type", faultType, "3ph, slg, ll or dlg");
    if (a.Contains("--fault-type") && faultBus is null)
    {
        Console.Error.WriteLine("error: --fault-type is the type of a --fault-bus study; add --fault-bus.");
        Environment.ExitCode = 2;
        return;
    }
    double faultZPu = 0.0;
    if (a.Contains("--zf"))
    {
        if (faultBus is null)
        {
            Console.Error.WriteLine("error: --zf is the fault impedance of a --fault-bus study; add --fault-bus.");
            Environment.ExitCode = 2;
            return;
        }
        faultZPu = FlagDouble(a, "--zf", 0.0);
        // D-DOC-089: also refuse an infinite value (it passed the >= 0 test); the same rule and wording as fault --zf.
        if (!(faultZPu >= 0.0) || !double.IsFinite(faultZPu))
            FailFlag<double>("--zf", faultZPu.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a finite fault reactance of 0 pu or more (Zf = j zf)");
    }
    if (faultBus is not null && a.Contains("--cascade"))
    {
        Console.Error.WriteLine("error: --cascade follows the steady solved state; it does not combine with --fault-bus.");
        Environment.ExitCode = 2;
        return;
    }

    GridModel m;
    try
    {
        // D-DOC-151: LoadCaseArgument (the same three branches, plus the folder fallback: an existing folder that is
        // not a known name loads as a case folder, so the loader names what is wrong instead of "unknown case").
        m = LoadCaseArgument(arg, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }
    if (faultBus is int fbCheck && !m.Buses.Any(b => b.Id == fbCheck))
    {
        Console.Error.WriteLine($"protection-check: fault bus {fbCheck} is not in case '{m.Name}'.");
        Environment.ExitCode = 2;
        return;
    }

    // R095: --alarms <soe.csv> cross-references the predicted cascade against a real sequence-of-events log
    // (SequenceOfEvents.CrossReference). It needs --cascade, and the log is read before the solve so a bad file
    // fails before any work.
    IReadOnlyList<GridSim.Core.Protection.AlarmEvent>? alarms = null;
    if (FlagString(a, "--alarms") is string alarmsPath)
    {
        if (!a.Contains("--cascade"))
        {
            Console.Error.WriteLine("error: --alarms cross-references the predicted cascade; add --cascade.");
            Environment.ExitCode = 2;
            return;
        }
        try { alarms = GridSim.Core.Protection.AlarmLogCsv.Load(alarmsPath); }
        catch (Exception ex) when (ex is IOException or InvalidDataException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"error reading --alarms '{alarmsPath}': {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }

    var opt = new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true };
    IPowerFlowSolver solver = backend.Solver(m);
    PowerFlowResult r = solver.Solve(m, opt);
    if (!r.Converged)   // R023: protection on a non-converged state would judge garbage
    {
        Console.Error.WriteLine($"protection-check: the power flow did not converge ({r.Status}, mismatch {r.MaxMismatch:E2}); no assessment is possible.");
        Environment.ExitCode = 3;
        return;
    }

    var baseSettings = new GridSim.Core.Protection.ProtectionSettings();
    var settings = baseSettings with
    {
        UnderVoltagePu = FlagDouble(a, "--uv", baseSettings.UnderVoltagePu),
        OverVoltagePu = FlagDouble(a, "--ov", baseSettings.OverVoltagePu),
        UnderFrequencyHz = FlagDouble(a, "--uf", baseSettings.UnderFrequencyHz),
        OverFrequencyHz = FlagDouble(a, "--of", baseSettings.OverFrequencyHz),
        InstantaneousOcMultiple = FlagDouble(a, "--oc", baseSettings.InstantaneousOcMultiple),
        ThermalPickupFraction = FlagDouble(a, "--thermal", baseSettings.ThermalPickupFraction),
        RocofTripHzPerS = FlagDouble(a, "--rocof", baseSettings.RocofTripHzPerS),
        // D2 nominal frequency (with N017; Ruling R1: Mark delegated EE calls 2026-10-04): the default 81U / 81O pickups are
        // G99's, written for a 50 Hz system. Giving BOTH --uf and --of supplies the frequency settings for this case, so they
        // are taken as written for the case's own nominal frequency; otherwise the G99 values keep their 50 Hz nominal and a
        // case at another frequency (case9, 60 Hz) reports 81U / 81O not-checkable instead of a fabricated trip. On a 50 Hz
        // case both branches give 50.0, so every existing run is unchanged.
        SettingsNominalHz = a.Contains("--uf") && a.Contains("--of") ? m.FrequencyHz : baseSettings.SettingsNominalHz,
    };
    // GR-198: the pickups must be physical: every one above 0, and the under-voltage / under-frequency pickups below the
    // over ones (--uv 1.2 --ov 0.9 reported every bus under- and over-voltage at once, exit 0).
    {
        string Inv(double v) => v.ToString("R", System.Globalization.CultureInfo.InvariantCulture);
        if (!(settings.UnderVoltagePu > 0)) FailFlag<double>("--uv", Inv(settings.UnderVoltagePu), "a voltage above 0 pu");
        if (!(settings.OverVoltagePu > settings.UnderVoltagePu)) FailFlag<double>("--ov", Inv(settings.OverVoltagePu), $"a voltage above --uv ({Inv(settings.UnderVoltagePu)} pu)");
        if (!(settings.UnderFrequencyHz > 0)) FailFlag<double>("--uf", Inv(settings.UnderFrequencyHz), "a frequency above 0 Hz");
        if (!(settings.OverFrequencyHz > settings.UnderFrequencyHz)) FailFlag<double>("--of", Inv(settings.OverFrequencyHz), $"a frequency above --uf ({Inv(settings.UnderFrequencyHz)} Hz)");
        if (!(settings.InstantaneousOcMultiple > 0)) FailFlag<double>("--oc", Inv(settings.InstantaneousOcMultiple), "a multiple above 0");
        if (!(settings.ThermalPickupFraction > 0)) FailFlag<double>("--thermal", Inv(settings.ThermalPickupFraction), "a fraction above 0");
        if (!(settings.RocofTripHzPerS > 0)) FailFlag<double>("--rocof", Inv(settings.RocofTripHzPerS), "a rate above 0 Hz/s");
    }
    // F10: the result file (when asked for): the settings used, the fault study (with --fault-bus), every operating
    // element, what could not be evaluated, the cascade steps (with --cascade) and the alarm-log comparison (with
    // --alarms). Filled alongside the console text below.
    CliResult? pcr = CliOutput.Report;
    pcr?.Set("case", arg).Set("buses", m.BusCount).Set("mode", faultBus is null ? "steady" : "fault")
        .Set("uv_pu", settings.UnderVoltagePu).Set("ov_pu", settings.OverVoltagePu)
        .Set("uf_hz", settings.UnderFrequencyHz).Set("of_hz", settings.OverFrequencyHz)
        .Set("oc_multiple", settings.InstantaneousOcMultiple).Set("thermal_fraction", settings.ThermalPickupFraction)
        .Set("rocof_hz_per_s", settings.RocofTripHzPerS);

    // A steady-state snapshot carries no trajectory, so the frequency-derivative elements report
    // not-checkable rather than a fabricated transient.
    GridSim.Core.Protection.ProtectionReport rep;
    if (faultBus is int fbU && faultType != "3ph")
    {
        // F21: the unbalanced study, assessed with the same settings.
        GridSim.Core.Protection.FaultType ut = faultType switch
        {
            "slg" => GridSim.Core.Protection.FaultType.SingleLineToGround,
            "ll" => GridSim.Core.Protection.FaultType.LineToLine,
            _ => GridSim.Core.Protection.FaultType.DoubleLineToGround,
        };
        GridSim.Core.Protection.UnbalancedFaultResult ufault;
        try { (ufault, rep) = GridSim.Core.Protection.ProtectionAssessment.AssessUnbalancedFault(m, r, fbU, ut, faultZPu, settings); }
        catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
        {
            Console.Error.WriteLine($"protection-check: fault study at bus {fbU} failed: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        Console.WriteLine($"Protection assessment  -  {arg}  ({m.BusCount} buses)  {faultType} fault at bus {fbU}, Zf=j{faultZPu:F3} pu  [passive; prefault solve unchanged]");
        Console.WriteLine($"  phase currents Ia {ufault.PhaseAPu:F2}  Ib {ufault.PhaseBPu:F2}  Ic {ufault.PhaseCPu:F2} pu   earth current |3I0| {ufault.EarthCurrentPu:F2} pu"
            + (ufault.FaultBusGrounded ? "" : "   (no earth path in the zero sequence at the fault bus)"));
        Console.WriteLine("  (phase elements on the phase currents and voltages; 50N/51N/21N/46 on the sequence currents; generic pickups)");
        ConvertersWithoutInfeedNote(ufault);
        pcr?.Set("converters_without_fault_infeed", ufault.ConvertersWithoutFaultInfeed.Count);
        pcr?.Set("fault_bus", fbU).Set("fault_type", faultType).Set("zf_pu", faultZPu)
            .Set("phase_a_pu", ufault.PhaseAPu).Set("phase_b_pu", ufault.PhaseBPu).Set("phase_c_pu", ufault.PhaseCPu)
            .Set("earth_current_pu", ufault.EarthCurrentPu).Set("fault_bus_grounded", ufault.FaultBusGrounded);
        // Fail loud on missing data (as the fault verb): no winding connection anywhere means no earthed neutral at all.
        if (faultType is "slg" or "dlg" && !m.Branches.Any(b => b.FromWinding is not null || b.ToWinding is not null))
        {
            Console.Error.WriteLine("protection-check: the model carries no transformer winding connections at all, so it has no earthed neutral; "
                + "the earth-fault verdicts below reflect missing data. Exit 3.");
            Environment.ExitCode = 3;
        }
    }
    else if (faultBus is int fb)
    {
        // R095: the faulted network (FaultAnalysis.ThreePhase superposed on the converged prefault state) assessed with
        // the same settings, so the current, voltage, distance and busbar-differential elements see a real fault.
        GridSim.Core.Protection.FaultResult fault;
        try
        {
            // The same two steps as ProtectionAssessment.AssessThreePhaseFault, split so that a faulted state whose
            // converter current iteration did not converge is reported (study printed, relays not assessed, exit 3, as
            // `fault` does) instead of reaching Assess, which refuses a non-converged state by the convergence contract.
            r.RequireConverged("Protection assessment (fault)");
            fault = GridSim.Core.Protection.FaultAnalysis.ThreePhase(m, r, fb, faultZPu);
            rep = fault.ConvertersConverged
                ? GridSim.Core.Protection.ProtectionAssessment.Assess(m, fault.State, settings, null, fault.DifferentialCurrentPuByBus)
                : null!;
        }
        catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
        {
            Console.Error.WriteLine($"protection-check: fault study at bus {fb} failed: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        string ka = fault.FaultCurrentKa > 0 ? $" ({fault.FaultCurrentKa:F2} kA)" : "";
        Console.WriteLine($"Protection assessment  -  {arg}  ({m.BusCount} buses)  three-phase fault at bus {fb}, Zf=j{faultZPu:F3} pu  [passive; prefault solve unchanged]");
        Console.WriteLine($"  fault current: {fault.FaultCurrentPu:F2} pu{ka}   Thevenin Z: {fault.TheveninZPu:F4} pu");
        Console.WriteLine($"  (generator subtransient reactance synthesised at {GridSim.Core.Protection.FaultAnalysis.DefaultSubtransientXdPu:F2} pu; positive-sequence, so three-phase only)");
        pcr?.Set("fault_bus", fb).Set("zf_pu", faultZPu).Set("fault_current_pu", fault.FaultCurrentPu).Set("fault_current_ka", fault.FaultCurrentKa)
            .Set("thevenin_z_pu", fault.TheveninZPu).Set("converters_converged", fault.ConvertersConverged);
        // Fail loud: a converter current iteration that did not settle leaves the faulted state unreliable, so the
        // relays are not assessed (below) and the run is a failure (exit 3), never a clean pass.
        if (fault.Converters is { Count: > 0 } && !fault.ConvertersConverged)
        {
            Console.Error.WriteLine("protection-check: the converter current iteration of the fault study did not converge; the faulted state is not reliable.");
            Environment.ExitCode = 3;
        }
        if (!fault.ConvertersConverged)
        {
            Console.WriteLine("  relays: not assessed (the faulted state did not converge, so no relay verdict can be computed from it)");
            pcr?.Set("relays", "not assessed: the faulted state did not converge");
            Environment.ExitCode = 3;
            return;
        }
    }
    else
    {
        rep = GridSim.Core.Protection.ProtectionAssessment.Assess(m, r, settings);
        Console.WriteLine($"Protection assessment  -  {arg}  ({m.BusCount} buses, converged={r.Converged})  [passive; solve unchanged]");
    }
    var operating = rep.Operating;
    Console.WriteLine($"  operating elements: {operating.Count}");
    if (operating.Count > 0)
    {
        Console.WriteLine("  | device | function | location | quantity | pickup | time | basis |");
        Console.WriteLine("  |--------|----------|----------|----------|--------|------|-------|");
        foreach (GridSim.Core.Protection.RelayVerdict v in operating)
        {
            string t = v.TimeToTripS is { } ts ? (ts <= 0 ? "inst" : $"{ts:F2}s") : "-";
            Console.WriteLine($"  | {v.Device} | {v.Function} | {v.LocationName} | {v.Quantity:F3} {v.Unit} | {v.Pickup:F3} | {t} | {v.Basis} |");
        }
    }
    if (pcr is not null) RelayVerdictTable(pcr.Set("operating_elements", operating.Count), "operating", operating);

    // Honestly list what could not be evaluated on this snapshot.
    var notCheckable = rep.Verdicts
        .Where(v => v.Confidence == GridSim.Core.Protection.ProtectionConfidence.NotCheckable)
        .Select(v => $"{v.Device} ({v.Function})").ToList();
    pcr?.Set("not_evaluated", string.Join("; ", notCheckable));
    if (notCheckable.Count > 0)
        Console.WriteLine(faultBus is null
            ? $"  not evaluated on a steady snapshot: {string.Join("; ", notCheckable)}"
            : $"  not evaluated without a trajectory or the needed sequence data: {string.Join("; ", notCheckable)}");

    Console.WriteLine();
    if (operating.Count == 0)
        Console.WriteLine(faultBus is null
            ? "PROTECTION SIMULATION: no relay would operate on this state (within the generic settings)."
            : $"PROTECTION SIMULATION: no relay would operate on the {(faultType == "3ph" ? "three-phase" : faultType)} fault at bus {faultBus} (within the generic settings).");
    else
    {
        GridSim.Core.Protection.RelayVerdict worst = operating[0];
        Console.WriteLine($"PROTECTION SIMULATION suggests {operating.Count} protection event(s) would occur. "
            + $"e.g. on {worst.LocationName}, relay {worst.Device} ({worst.Function}) would likely operate: {worst.Basis}.");
    }

    // --cascade follows the propagation: trip the first branch element, re-solve, repeat (a what-if; the
    // solve above is untouched).
    if (a.Contains("--cascade"))
    {
        Console.WriteLine();
        GridSim.Core.Protection.CascadeResult cas = GridSim.Core.Protection.ProtectionCascade.Simulate(m, r, settings);
        if (!cas.Cascaded)
            Console.WriteLine($"Cascade: {cas.StopReason}.");
        else
        {
            Console.WriteLine($"Cascade propagation ({cas.Steps.Count} trip(s)):");
            foreach (GridSim.Core.Protection.CascadeStep st in cas.Steps)
            {
                string t = st.TripTimeS is { } ts ? (ts <= 0 ? "inst" : $"{ts:F2}s") : "-";
                string after = st.ResolveConverged ? $"{st.OverloadedBranchesAfter} branch(es) then overloaded" : "re-solve did NOT converge";
                Console.WriteLine($"  {st.Order}. relay {st.Device} ({st.Function}) opens {st.BranchName} in {t}  ->  {after}");
            }
            Console.WriteLine($"  stop: {cas.StopReason}.");
        }
        if (pcr is not null)
        {
            pcr.Set("cascaded", cas.Cascaded).Set("cascade_stop_reason", cas.StopReason);
            CliResultTable steps = pcr.Table("cascade", "order", "device", "function", "branch", "trip_time_s", "resolve_converged", "overloaded_branches_after");
            foreach (GridSim.Core.Protection.CascadeStep st in cas.Steps)
                steps.Row(st.Order, st.Device, st.Function, st.BranchName, st.TripTimeS, st.ResolveConverged, st.OverloadedBranchesAfter);
        }

        // R095: reconcile the prediction with the real alarm log. A model that does not reproduce the event is a
        // validation failure (exit 3); the divergences are listed first because they are what to investigate.
        if (alarms is not null)
        {
            GridSim.Core.Protection.SoeCrossReference x = GridSim.Core.Protection.SequenceOfEvents.CrossReference(cas, alarms);
            int nonBranch = alarms.Count(al => al.From == 0);
            Console.WriteLine();
            Console.WriteLine($"Sequence of events vs prediction ({alarms.Count} alarm(s), {nonBranch} non-branch not matched): " +
                $"{x.Agreements} agree, {x.PredictedNotObserved} predicted not observed, {x.ObservedNotPredicted} observed not predicted, " +
                $"{x.OrderMismatches} out of order");
            foreach (GridSim.Core.Protection.SoeEntry e in x.Divergences)
                Console.WriteLine($"  {e.Kind}: {e.Detail}");
            foreach (GridSim.Core.Protection.SoeEntry e in x.Entries.Where(e => e.Kind == GridSim.Core.Protection.SoeMatchKind.Agreement))
                Console.WriteLine($"  Agreement: {e.Detail} (predicted #{e.PredictedOrder}, observed at {e.ObservedAtSeconds:R} s)");
            Console.WriteLine(x.FullyConsistent
                ? "SOE: FULLY CONSISTENT - the predicted cascade reproduces the alarm log."
                : "SOE: DIVERGES - the predicted cascade does not reproduce the alarm log.");
            if (!x.FullyConsistent) Environment.ExitCode = 3;
            if (pcr is not null)
            {
                pcr.Set("alarms", alarms.Count).Set("alarms_non_branch", nonBranch).Set("soe_agreements", x.Agreements)
                    .Set("soe_predicted_not_observed", x.PredictedNotObserved).Set("soe_observed_not_predicted", x.ObservedNotPredicted)
                    .Set("soe_order_mismatches", x.OrderMismatches).Set("soe_fully_consistent", x.FullyConsistent);
                CliResultTable soe = pcr.Table("soe", "kind", "detail", "predicted_order", "observed_at_s");
                foreach (GridSim.Core.Protection.SoeEntry e in x.Entries) soe.Row(e.Kind.ToString(), e.Detail, e.PredictedOrder, e.ObservedAtSeconds);
            }
        }
    }
    pcr?.Complete();
}

// F10: the relay-verdict table shared by protection-check and fault: one row per verdict, from the fields the console
// table prints (time_to_trip_s is empty when the element has no trip time; 0 or less is instantaneous).
static void RelayVerdictTable(CliResult rep, string name, IEnumerable<GridSim.Core.Protection.RelayVerdict> verdicts)
{
    CliResultTable t = rep.Table(name, "device", "function", "location", "quantity", "unit", "pickup", "time_to_trip_s", "basis");
    foreach (GridSim.Core.Protection.RelayVerdict v in verdicts)
        t.Row(v.Device, v.Function, v.LocationName, v.Quantity, v.Unit, v.Pickup, v.TimeToTripS, v.Basis);
}

// grade --chain SPEC,SPEC[,...] --current I[,I...] [--cti S]
// R095: grade a radial chain of inverse-time / definite-time overcurrent relays, ordered downstream to upstream, at
// one or more fault currents (OvercurrentCoordination.GradeChain). SPEC is CURVE:PICKUP:TIMEDIAL or dt:PICKUP:DELAY_S;
// pickup and current share one unit (amps or per unit). Exit 0 when every pair is coordinated at every current, 3
// when any pair is not (the primary does not operate, the backup does not operate (D-DOC-092), or the backup lags it by
// less than the CTI), 2 on a usage error (D-DOC-174: including a --current list that is not strictly ascending).
void RunGrade(List<string> a)
{
    const string usage = "usage: gridsim grade --chain CURVE:PICKUP:TD,... --current I[,I...] [--cti 0.4]\n" +
        "       curves: iec-si iec-vi iec-ei iec-lti ieee-mi ieee-vi ieee-ei, or dt:PICKUP:DELAY_S; chain downstream first";
    string? chainSpec = FlagString(a, "--chain");
    string? currentSpec = FlagString(a, "--current");
    if (chainSpec is null || currentSpec is null)
    {
        Console.Error.WriteLine(usage);
        Environment.ExitCode = 2;
        return;
    }

    var chain = new List<GridSim.Core.Protection.Coordination.OvercurrentElement>();
    foreach (string spec in chainSpec.Split(',', StringSplitOptions.TrimEntries))
    {
        try { chain.Add(GridSim.Core.Protection.Coordination.OvercurrentCoordination.ParseElement(spec)); }
        catch (FormatException ex) { Console.Error.WriteLine($"error: --chain: {ex.Message}"); Environment.ExitCode = 2; return; }
    }
    if (chain.Count < 2)
    {
        Console.Error.WriteLine("error: --chain needs at least two relays (a primary and its backup), downstream first.");
        Environment.ExitCode = 2;
        return;
    }

    var currents = new List<double>();
    foreach (string c in currentSpec.Split(',', StringSplitOptions.TrimEntries))
    {
        if (!double.TryParse(c, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double i)
            || !double.IsFinite(i) || i < 0.0)
            FailFlag<double>("--current", c, "comma-separated finite fault currents >= 0 (same unit as the pickups)");
        // D-DOC-174 (October 2026): the list must be strictly ascending. The comma is the list separator, so a decimal
        // comma ("2000,5" meant as 2000.5) used to be split silently into the two currents 2000 and 5 and graded at both
        // (exit 3 from the second). Each current is graded on its own, so the order carries no meaning and asking for
        // it costs nothing, while a decimal comma almost always breaks it (the fraction after the comma is smaller than
        // the number before it). A list out of order or with a repeat is refused (exit 2), naming the decimal-point rule.
        // (A decimal comma that happens to ascend, "5,75", cannot be told from the two currents 5 and 75; both are
        // printed as their own "fault current" section, so what was graded is always visible.)
        if (currents.Count > 0 && !(i > currents[^1]))
            FailFlag<double>("--current", currentSpec,
                "a strictly ascending list of fault currents separated by commas; write decimals with a point (2000.5, not 2000,5)");
        currents.Add(i);
    }
    double cti = FlagDouble(a, "--cti", GridSim.Cli.CliDefaults.GradeCtiS);
    if (!double.IsFinite(cti) || cti < 0.0)
        FailFlag<double>("--cti", cti.ToString(System.Globalization.CultureInfo.InvariantCulture), "a finite coordination time interval >= 0 s");

    static string T(double t) => double.IsPositiveInfinity(t) ? "never" : t.ToString("F4", System.Globalization.CultureInfo.InvariantCulture);

    Console.WriteLine($"Overcurrent grading  -  {chain.Count} relays (downstream first), CTI {cti:R} s");
    for (int k = 0; k < chain.Count; k++)
    {
        var e = chain[k];
        string setting = e.Curve == GridSim.Core.Protection.Coordination.OvercurrentCurve.DefiniteTime
            ? $"delay {e.DefiniteTimeSeconds:R} s" : $"time dial {e.TimeDial:R}";
        Console.WriteLine($"  R{k + 1}: {e.Curve}, pickup {e.PickupCurrent:R}, {setting}");
    }
    bool allCoordinated = true;
    double binding = double.PositiveInfinity;
    // F10: every pair at every current goes into the result file (a time that never operates is Infinity; a margin the
    // console shows as "-" is NaN). The pairs table is the main one, so it is created first.
    CliResult? gradeRep = CliOutput.Report;
    CliResultTable? gradePairs = gradeRep?.Table("pairs", "fault_current", "pair", "primary_s", "backup_s", "margin_s", "required_margin_s", "coordinated");
    foreach (double i in currents)
    {
        IReadOnlyList<GridSim.Core.Protection.Coordination.GradingResult> g =
            GridSim.Core.Protection.Coordination.OvercurrentCoordination.GradeChain(chain, i, cti);
        Console.WriteLine();
        Console.WriteLine($"  fault current {i:R}");
        Console.WriteLine("  | pair | primary s | backup s | margin s | verdict |");
        Console.WriteLine("  |------|-----------|----------|----------|---------|");
        for (int k = 0; k < g.Count; k++)
        {
            GridSim.Core.Protection.Coordination.GradingResult r = g[k];
            // D-DOC-169 (October 2026): a margin of minus infinity (the primary never operates, the backup does) printed
            // as "inf", the same as plus infinity; the sign is now printed.
            string margin = double.IsNaN(r.MarginSeconds) ? "-"
                : double.IsPositiveInfinity(r.MarginSeconds) ? "inf"
                : double.IsNegativeInfinity(r.MarginSeconds) ? "-inf"
                : r.MarginSeconds.ToString("F4", System.Globalization.CultureInfo.InvariantCulture);
            // D-DOC-092: a backup that never operates is its own failure reason (it used to be graded OK, margin inf).
            string verdict = r.Coordinated ? "OK"
                : double.IsPositiveInfinity(r.PrimaryTimeSeconds) ? "NOT COORDINATED (primary does not operate)"
                : !r.BackupOperates ? "NOT COORDINATED (backup does not operate)"
                : "NOT COORDINATED (margin below CTI)";
            Console.WriteLine($"  | R{k + 1}->R{k + 2} | {T(r.PrimaryTimeSeconds)} | {T(r.BackupTimeSeconds)} | {margin} | {verdict} |");
            gradePairs?.Row(i, $"R{k + 1}->R{k + 2}", r.PrimaryTimeSeconds, r.BackupTimeSeconds, r.MarginSeconds, r.RequiredMarginSeconds, r.Coordinated);
            allCoordinated &= r.Coordinated;
            if (r.Coordinated) binding = Math.Min(binding, r.MarginSeconds);
        }
    }
    Console.WriteLine();
    if (allCoordinated)
        Console.WriteLine($"GRADED: every pair coordinated at every current; binding margin {T(binding)} s (CTI {cti:R} s).");
    else
        Console.WriteLine("NOT GRADED: at least one pair is not coordinated (see above).");
    Environment.ExitCode = allCoordinated ? 0 : 3;
    // F10: the verdict (the pair rows were added in the loop above, from the very results printed). NOT GRADED is a
    // finished result (exit 3) and is written too.
    if (gradeRep is not null)
    {
        gradeRep.Set("relays", chain.Count).Set("cti_s", cti).Set("all_coordinated", allCoordinated)
            .Set("binding_margin_s", allCoordinated ? binding : null);
        CliResultTable relays = gradeRep.Table("relays", "relay", "curve", "pickup", "time_dial", "definite_time_s");
        for (int k = 0; k < chain.Count; k++)
            relays.Row(k + 1, chain[k].Curve.ToString(), chain[k].PickupCurrent, chain[k].TimeDial, chain[k].DefiniteTimeSeconds);
        gradeRep.Complete();
    }
}

// dist3ph <feeder.json> [sweep] [--tol 1e-10] [--max-iter 200]
// dist3ph <feeder.json> fault --bus ID [--type all|3ph|slg|ll|llg] [--zf PU]
// dist3ph <feeder.json> estimate --measurements <m.json> [--method wls|wlav|branch-current] [--tol 1e-10] [--max-iter 50]
//                                 [--robust-passes 8] [--robust-floor 0.001]   (wlav only; D-DOC-217)
// dist3ph <feeder.json> harmonics --bus ID --spectrum TYPE --current PU
// R059: the experimental three-phase distribution stack, reachable at last. N062 (October 2026): the feeder may also be
// a radial positive-sequence case (a .m file or a JSON case folder), lifted by MultiPhaseGridModelAdapter; the
// branch-current estimator (BranchCurrentDsse) and the three-phase harmonic penetration are on the verb. The feeder is a gridsim-dist3ph/1 file
// (MultiPhaseJsonLoader; the format is in technical ch. 18, "The gridsim-dist3ph/1 feeder file", and user manual ch. 7;
// D-DOC-155: this used to cite "technical chapter 18.5", a section number that no longer exists). Exit codes: 0 success; 1 input error (unreadable or invalid
// feeder / measurement file, a bus the feeder does not have, a study that refuses the input); 2 usage error;
// 3 the solve did not converge (status printed, no voltages reported as a result).
void RunDist3ph(List<string> a)
{
    const string usage =
        "usage: gridsim dist3ph <feeder.json> [sweep] [--tol 1e-10] [--max-iter 200]\n" +
        "       gridsim dist3ph <feeder.json> fault --bus ID [--type all|3ph|slg|ll|llg] [--zf PU]\n" +
        "       gridsim dist3ph <feeder.json> estimate --measurements <m.json> [--method wls|wlav|branch-current] [--tol 1e-10] [--max-iter 50]\n" +
        "                                      [--robust-passes 8] [--robust-floor 0.001]   (wlav only)\n" +
        "       gridsim dist3ph <feeder.json> harmonics --bus ID --spectrum TYPE --current PU [--afe feeder]\n" +
        "       gridsim dist3ph <feeder.json> to-v2 --to <out.json>   (N339: write the JSON v2 form, then prove it reads back bit for bit)\n" +
        "       (experimental; feeder format gridsim-dist3ph/1 or /2, see user manual ch. 7 and technical ch. 18; a radial .m case or JSON case folder is lifted balanced)";
    var inv = System.Globalization.CultureInfo.InvariantCulture;

    // Positionals after the verb: the feeder file, then an optional mode word. Anything more is a usage error.
    List<string> pos = Positionals(a).Skip(1).ToList();
    if (pos.Count == 0 || pos.Count > 2)
    {
        Console.Error.WriteLine(usage);
        Environment.ExitCode = 2;
        return;
    }
    string file = pos[0];
    string mode = pos.Count == 2 ? pos[1].ToLowerInvariant() : "sweep";

    // Each mode accepts only its own flags: a flag that belongs to another mode (say --bus on a sweep) is refused
    // rather than silently ignored, so nobody believes a fault was studied when a sweep ran.
    string[] allowedFlags = mode switch
    {
        "sweep" => new[] { "--tol", "--max-iter" },
        "fault" => new[] { "--bus", "--type", "--zf" },
        "estimate" => new[] { "--measurements", "--method", "--tol", "--max-iter", "--robust-passes", "--robust-floor" },   // D-DOC-217: the two robust controls
        "harmonics" => new[] { "--bus", "--spectrum", "--current", "--afe" },   // N062; N354 (CF5): --afe feeder
        "to-v2" => new[] { "--to" },                                    // N339
        _ => Array.Empty<string>(),
    };
    if (mode is not ("sweep" or "fault" or "estimate" or "harmonics" or "to-v2"))
    {
        Console.Error.WriteLine($"error: dist3ph mode '{pos[1]}' is not one of sweep, fault, estimate, harmonics, to-v2.");
        Console.Error.WriteLine(usage);
        Environment.ExitCode = 2;
        return;
    }
    foreach (string tok in a.Skip(1))
        if (tok.StartsWith("--", StringComparison.Ordinal) && Array.IndexOf(allowedFlags, tok) < 0)
        {
            Console.Error.WriteLine($"error: dist3ph {mode} does not take {tok} (allowed: {(allowedFlags.Length == 0 ? "none" : string.Join(", ", allowedFlags))}).");
            Environment.ExitCode = 2;
            return;
        }

    GridSim.Core.Distribution.MultiPhaseFeeder feeder;
    try
    {
        // N062: a positive-sequence case (a MATPOWER .m file or a JSON case folder) is lifted into a balanced feeder by
        // MultiPhaseGridModelAdapter, which refuses what the sweep cannot model (PV buses, taps, a meshed network).
        bool isCaseDir = Directory.Exists(file) && File.Exists(Path.Combine(file, "system.json"));
        feeder = file.EndsWith(".m", StringComparison.OrdinalIgnoreCase) || isCaseDir
            ? GridSim.Core.Distribution.MultiPhaseGridModelAdapter.FromGridModel(isCaseDir ? Gated.Dir(file) : Gated.Matpower(file), file)
            : Gated.Dist3ph(file);
    }
    catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or DirectoryNotFoundException or IOException or UnauthorizedAccessException or ArgumentException)
    {
        Console.Error.WriteLine($"error loading three-phase feeder: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }
    GridSim.Core.Distribution.MultiPhaseModel model = feeder.Model;

    Console.WriteLine($"THREE-PHASE DISTRIBUTION ({mode}) - {feeder.Name}   [EXPERIMENTAL]");
    Console.WriteLine($"  file: {file}");
    Console.WriteLine($"  {model.Buses.Count} buses, {model.Branches.Count} branches, {model.Loads.Count} loads, base {feeder.BaseMva.ToString("R", inv)} MVA (three-phase)");
    // N062: the new elements, counted, so a reader sees what the feeder holds (a v1 feeder prints none of this line).
    // D-DOC-167 (October 2026): a closed switch is a zero-impedance three-phase branch, which HasExtendedElements does not
    // count (a v1 model could always hold one), so a feeder whose only extra elements were closed switches printed no
    // line at all and the reader never learnt they were there. The switch count from the loader now prints it too. A
    // feeder with no extended element, no closed switch and no open switch still prints nothing here, as before.
    if (model.HasExtendedElements || feeder.OpenSwitchIds.Count > 0 || feeder.BranchKinds.Any(k => k == "switch"))
        Console.WriteLine($"  {feeder.BranchKinds.Count(k => k == "regulator")} regulator(s), {feeder.BranchKinds.Count(k => k == "switch")} closed switch(es), " +
            $"{feeder.OpenSwitchIds.Count} open switch(es) (not branches), {model.Capacitors.Count} capacitor bank(s), " +
            $"{model.Branches.Count(b => b.Phases != GridSim.Core.Distribution.Phase.Abc)} single- or two-phase branch(es)" +
            // 1.95.251 (N168): named only when the feeder has one, so every other feeder prints the line it always did.
            (model.Branches.Any(b => b.IsDeltaWye) ? $", {model.Branches.Count(b => b.IsDeltaWye)} delta / grounded-wye transformer(s)" : ""));
    // F10: the result file (when asked for) carries the mode's figures at full precision: the voltage table for a sweep
    // or an estimate, the Thevenin impedances and fault currents for a fault study.
    CliResult? drep = CliOutput.Report;
    drep?.Set("feeder", feeder.Name).Set("file", file).Set("mode", mode).Set("buses", model.Buses.Count)
        .Set("branches", model.Branches.Count).Set("loads", model.Loads.Count).Set("base_mva", feeder.BaseMva);

    // Print a per-bus, per-phase voltage table in per-unit and in line-to-neutral volts. N062: with the bus phases given
    // (the sweep's result), a phase a bus does not have (a single- or two-phase lateral) is printed as "-" and has no
    // result row, and the unbalance factor is printed only for a three-phase bus; a named bus shows its name.
    void PrintVoltages(IReadOnlyList<int> busIds, System.Numerics.Complex[][] v, IReadOnlyList<GridSim.Core.Distribution.Phase>? busPhases = null)
    {
        Console.WriteLine("  | bus | kV LL | phase | |V| pu | |V| V (LN) | angle deg | VUF % |");
        Console.WriteLine("  |-----|-------|-------|--------|------------|-----------|-------|");
        string[] names = { "a", "b", "c" };
        // F10: one row per bus and phase, the printed quantities unrounded (VUF on phase a only, as printed).
        CliResultTable? vt = drep?.Table("voltages", "bus", "kv_ll", "phase", "vm_pu", "v_ln_volts", "angle_deg", "vuf_pct");
        for (int i = 0; i < busIds.Count; i++)
        {
            int id = busIds[i];
            GridSim.Core.Distribution.Phase have = busPhases?[i] ?? GridSim.Core.Distribution.Phase.Abc;
            bool threePhase = have == GridSim.Core.Distribution.Phase.Abc;
            System.Numerics.Complex[] seq = GridSim.Core.Distribution.SymmetricalComponents.ToSequence(v[i]);
            double pos1 = seq[1].Magnitude;
            // GR-601: a dead bus has no unbalance factor; NaN (printed and written as NaN), never 0 (balanced).
            double vuf = pos1 > 0 ? 100.0 * seq[2].Magnitude / pos1 : double.NaN;
            string label = feeder.BusLabel(id);
            int firstPhase = -1;
            for (int p = 0; p < 3 && firstPhase < 0; p++) if (GridSim.Core.Distribution.PhaseIndex.Has(have, p)) firstPhase = p;
            for (int p = 0; p < 3; p++)
            {
                if (!GridSim.Core.Distribution.PhaseIndex.Has(have, p))
                {
                    Console.WriteLine($"  | {label} | {feeder.BaseKvLLByBus[id].ToString("R", inv)} | {names[p]} | - | - | - | |");
                    continue;
                }
                double mag = v[i][p].Magnitude;
                double ang = GridSim.Core.Numerics.DetMath.Phase(v[i][p]) * 180.0 / Math.PI;   // D1: deterministic atan2
                bool vufHere = threePhase && p == firstPhase;
                Console.WriteLine($"  | {label} | {feeder.BaseKvLLByBus[id].ToString("R", inv)} | {names[p]} | {mag.ToString("F6", inv)} | " +
                    $"{(mag * feeder.VoltBaseLN(id)).ToString("F2", inv)} | {ang.ToString("F3", inv)} | {(vufHere ? vuf.ToString("F4", inv) : "")} |");
                vt?.Row(id, feeder.BaseKvLLByBus[id], names[p], mag, mag * feeder.VoltBaseLN(id), ang, vufHere ? vuf : null);
            }
        }
    }

    // N339 (October 2026): write the feeder as a gridsim-dist3ph/2 document (MultiPhaseV2Writer), then PROVE it: read
    // the written file back with the v2 reader and compare the two feeders bit for bit (MultiPhaseV2Writer.FirstDifference:
    // every per-unit double by its 64 bits, ids, kinds, phases, flags, order). Never overwrites (exit 2). A difference
    // exits 3 naming it and keeps the file for inspection; a feeder the v2 form cannot hold exits 1 with the reason and
    // writes nothing. A feeder read from a v2 file keeps its own provenance; one from a v1 file or a lifted case has none,
    // and is written with an honest CuratedPlaceholder naming the source and carrying [VERIFY] (GridSim invents no tag).
    if (mode == "to-v2")
    {
        string? outPath = FlagString(a, "--to");
        if (outPath is null)
        {
            Console.Error.WriteLine("error: dist3ph to-v2 needs --to <out.json> (the v2 file to write).");
            Environment.ExitCode = 2;
            return;
        }
        if (File.Exists(outPath) || Directory.Exists(outPath))
        {
            Console.Error.WriteLine($"error: dist3ph to-v2 refuses to overwrite '{outPath}' (it exists); choose a new output.");
            Environment.ExitCode = 2;
            return;
        }
        string text;
        try
        {
            text = GridSim.Core.Distribution.MultiPhaseV2Writer.ToJson(feeder,
                feeder.Provenance is null ? GridSim.Core.Distribution.MultiPhaseV2Writer.ConvertedWithoutProvenance(file) : null);
        }
        catch (Exception ex) when (ex is InvalidDataException or ArgumentException)
        {
            Console.Error.WriteLine($"error: dist3ph to-v2: {ex.Message} Nothing was written.");
            Environment.ExitCode = 1;
            return;
        }
        try
        {
            string? dir = Path.GetDirectoryName(Path.GetFullPath(outPath));
            if (dir is not null) Directory.CreateDirectory(dir);
            byte[] bytes = new System.Text.UTF8Encoding(encoderShouldEmitUTF8Identifier: false).GetBytes(text);
            using var fs = new FileStream(outPath, FileMode.CreateNew, FileAccess.Write);
            fs.Write(bytes, 0, bytes.Length);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"error: dist3ph to-v2 could not write '{outPath}': {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        GridSim.Core.Distribution.MultiPhaseFeeder back;
        try { back = GridSim.Core.Distribution.MultiPhaseJsonLoader.ParseV2(File.ReadAllText(outPath), outPath); }
        catch (Exception ex) when (ex is InvalidDataException or ArgumentException)
        {
            Console.Error.WriteLine($"error: dist3ph to-v2: the written file does not read back: {ex.Message} The file is kept for inspection.");
            Environment.ExitCode = 3;
            return;
        }
        string? diff = GridSim.Core.Distribution.MultiPhaseV2Writer.FirstDifference(feeder, back);
        if (diff is not null)
        {
            Console.Error.WriteLine($"error: dist3ph to-v2: the written file reads back to a different feeder ({diff}). The file is kept for inspection.");
            Environment.ExitCode = 3;
            return;
        }
        GridSim.Core.Assets.AssetClassProvenance writtenProv = back.Provenance!.Default;
        Console.WriteLine($"  wrote {outPath} ({GridSim.Core.Distribution.MultiPhaseJsonLoader.SchemaV2}); read back: the same feeder, bit for bit");
        Console.WriteLine($"  provenance: {writtenProv.Tag}{(feeder.Provenance is null ? " (the source carries none: set the tag and note before relying on it)" : "")}");
        drep?.Set("written", outPath).Set("provenance", writtenProv.Tag.ToString()).Set("round_trip_identical", true);
        drep?.Complete();
        return;
    }

    if (mode == "sweep")
    {
        double tol = FlagDouble(a, "--tol", 1e-10);
        int maxIter = FlagInt(a, "--max-iter", 200);
        if (!(tol > 0)) FailFlag<double>("--tol", tol.ToString("R", inv), "a tolerance above 0 pu");
        if (maxIter < 1) FailFlag<int>("--max-iter", maxIter.ToString(inv), "at least 1");

        GridSim.Core.Distribution.MultiPhaseResult r;
        try
        {
            r = new GridSim.Core.Distribution.ThreePhaseSweep().Solve(
                model, new GridSim.Core.Distribution.ThreePhaseSweepOptions { Tolerance = tol, MaxIterations = maxIter });
        }
        catch (ArgumentException ex)
        {
            // N062: a model the sweep refuses (phases that do not fit the tree); the loader catches these first.
            Console.Error.WriteLine($"dist3ph sweep: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        if (!r.Converged)
        {
            // Fail loud: the iterate is not a solution, so no voltage table is printed as if it were.
            Console.Error.WriteLine($"dist3ph: the three-phase sweep did not converge ({r.Status}) after {r.Iterations} sweep(s); " +
                $"final max voltage change {r.MaxDelta.ToString("E3", inv)} pu against tolerance {tol.ToString("E3", inv)}. No result reported.");
            Environment.ExitCode = 3;
            return;
        }
        Console.WriteLine($"  sweep CONVERGED in {r.Iterations} iteration(s), max voltage change {r.MaxDelta.ToString("E3", inv)} pu (tolerance {tol.ToString("E3", inv)})");
        drep?.Set("converged", true).Set("iterations", r.Iterations).Set("max_delta_pu", r.MaxDelta).Set("tol", tol).Set("max_iter", maxIter);
        PrintVoltages(r.BusIds, r.V, r.BusPhases);
        drep?.Complete();
        return;
    }

    if (mode == "fault")
    {
        int bus = FlagInt(a, "--bus", int.MinValue);
        if (bus == int.MinValue)
        {
            Console.Error.WriteLine("error: dist3ph fault needs --bus ID.");
            Console.Error.WriteLine(usage);
            Environment.ExitCode = 2;
            return;
        }
        string type = (FlagString(a, "--type") ?? "all").ToLowerInvariant();
        if (type is not ("all" or "3ph" or "slg" or "ll" or "llg"))
            FailFlag<string>("--type", type, "one of all, 3ph, slg, ll, llg");
        double zf = FlagDouble(a, "--zf", 0.0);
        if (zf < 0) FailFlag<double>("--zf", zf.ToString("R", inv), "a fault resistance >= 0 pu");
        if (!feeder.BaseKvLLByBus.ContainsKey(bus))
        {
            Console.Error.WriteLine($"error: bus {bus} is not in the feeder {file}.");
            Environment.ExitCode = 1;
            return;
        }
        if (model.Buses.Any(b => b.Id == bus && b.IsSource))
        {
            // The source is an infinite bus (zero source impedance), so a bolted fault there has no finite current.
            Console.Error.WriteLine($"error: bus {bus} is the source (an infinite bus with zero impedance); a fault there has no finite current in this model.");
            Environment.ExitCode = 1;
            return;
        }

        var zfC = new System.Numerics.Complex(zf, 0.0);
        double ampBase = feeder.AmpBase(bus);
        try
        {
            (System.Numerics.Complex z0, System.Numerics.Complex z1, System.Numerics.Complex z2) =
                GridSim.Core.Distribution.SequenceFaultStudy.Thevenin(model, bus);
            // D-DOC-166 (October 2026): here --zf is a fault RESISTANCE (Zf = zf + j0), while fault / protection-check
            // take it as a reactance (Zf = j zf); the header says which, so the same flag name cannot be misread.
            Console.WriteLine($"  fault at bus {bus} ({feeder.BaseKvLLByBus[bus].ToString("R", inv)} kV LL), Zf = {zf.ToString("R", inv)} pu (resistive), prefault E1 = 1.0 pu, infinite source;");
            Console.WriteLine("  each branch reduced to its transposed-equivalent sequence impedances (z1 = z2 = zs - zm, z0 = zs + 2 zm).");
            Console.WriteLine($"  Thevenin Z0 = {z0.Real.ToString("F6", inv)} + j{z0.Imaginary.ToString("F6", inv)} pu   " +
                $"Z1 = {z1.Real.ToString("F6", inv)} + j{z1.Imaginary.ToString("F6", inv)} pu   Z2 = {z2.Real.ToString("F6", inv)} + j{z2.Imaginary.ToString("F6", inv)} pu");
            Console.WriteLine($"  current base at this bus {ampBase.ToString("F3", inv)} A");
            Console.WriteLine("  | fault | current pu | current A |");
            Console.WriteLine("  |-------|------------|-----------|");
            drep?.Set("bus", bus).Set("kv_ll", feeder.BaseKvLLByBus[bus]).Set("zf_pu", zf).Set("type", type)
                .Set("z0_r_pu", z0.Real).Set("z0_x_pu", z0.Imaginary).Set("z1_r_pu", z1.Real).Set("z1_x_pu", z1.Imaginary)
                .Set("z2_r_pu", z2.Real).Set("z2_x_pu", z2.Imaginary).Set("current_base_a", ampBase);
            CliResultTable? ft = drep?.Table("faults", "fault", "current_pu", "current_a");
            void Row(string label, double pu)
            {
                // A study that produced a non-finite current has failed; never print it as a number.
                if (!double.IsFinite(pu)) throw new InvalidOperationException($"{label} fault current is not finite at bus {bus}.");
                Console.WriteLine($"  | {label} | {pu.ToString("F6", inv)} | {(pu * ampBase).ToString("F2", inv)} |");
                ft?.Row(label, pu, pu * ampBase);
            }
            if (type is "all" or "3ph") Row("3ph", GridSim.Core.Distribution.SequenceFaultStudy.ThreePhaseFaultCurrentPu(model, bus, zfC));
            if (type is "all" or "slg") Row("slg", GridSim.Core.Distribution.SequenceFaultStudy.SingleLineToGround(model, bus, zfC).FaultCurrentPu);
            if (type is "all" or "ll") Row("ll", GridSim.Core.Distribution.SequenceFaultStudy.LineToLineFaultCurrentPu(model, bus, zfC));
            if (type is "all" or "llg") Row("llg (ground)", GridSim.Core.Distribution.SequenceFaultStudy.LineToLineGroundFaultCurrentPu(model, bus, zfC));
            drep?.Complete();   // reached only when every requested current was finite (Row throws otherwise: exit 1)
        }
        catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
        {
            Console.Error.WriteLine($"dist3ph fault: {ex.Message}");
            Environment.ExitCode = 1;
        }
        return;
    }

    if (mode == "harmonics")
    {
        // N062: the three-phase harmonic penetration (ThreePhaseHarmonicPenetration) with one balanced source at --bus:
        // the --spectrum library profile (HarmonicSourceLibrary; there is no default, see N131) scaled to a fundamental
        // current of --current pu, rotated by h x 120 degrees per phase. The network is the feeder's series impedances
        // with reactance scaled by the order and the source as the harmonic reference; loads are not in the harmonic
        // model (as in the Core API). Exit 1 for a bus not in the feeder, the source bus, a feeder with a lateral or regulator (N167), or
        // a singular network; 2 for a missing or bad flag.
        int hbus = FlagInt(a, "--bus", int.MinValue);
        string? spectrumName = FlagString(a, "--spectrum");
        double current = FlagDouble(a, "--current", double.NaN);
        if (hbus == int.MinValue || spectrumName is null || double.IsNaN(current))
        {
            Console.Error.WriteLine("error: dist3ph harmonics needs --bus ID, --spectrum TYPE and --current PU.");
            Console.Error.WriteLine(usage);
            Environment.ExitCode = 2;
            return;
        }
        if (!(current > 0)) FailFlag<double>("--current", current.ToString("R", inv), "a fundamental current above 0 pu");
        if (!GridSim.Core.Harmonics.HarmonicSourceLibrary.ByType.TryGetValue(spectrumName, out IReadOnlyList<GridSim.Core.Harmonics.HarmonicComponent>? spectrum))
            FailFlag<string>("--spectrum", spectrumName, "one of " + string.Join(", ", GridSim.Core.Harmonics.HarmonicSourceLibrary.ByType.Keys));
        if (!feeder.BaseKvLLByBus.ContainsKey(hbus))
        {
            Console.Error.WriteLine($"error: bus {hbus} is not in the feeder {file}.");
            Environment.ExitCode = 1;
            return;
        }
        if (model.Buses.Any(b => b.Id == hbus && b.IsSource))
        {
            // The source is the harmonic reference (zero harmonic voltage): an injection there would be silently dropped.
            Console.Error.WriteLine($"error: bus {hbus} is the source, the harmonic reference; inject at another bus.");
            Environment.ExitCode = 1;
            return;
        }
        // N354 (CF5): --afe feeder stamps the feeder file's active-front-end converter units (its "converters" section)
        // into Y(h) as balanced three-wire shunts (ThreePhaseActiveFrontEnd). Without the flag nothing is stamped and the
        // study is exactly as before; with it on a feeder that has no converter units the run is refused (exit 1), never
        // run as if there were some.
        string? afeText = FlagString(a, "--afe");
        IReadOnlyList<GridSim.Core.Harmonics.ThreePhaseActiveFrontEnd>? afe = null;
        if (afeText is not null)
        {
            if (!afeText.Equals("feeder", StringComparison.OrdinalIgnoreCase))
                FailFlag<string>("--afe", afeText, "feeder (stamp the feeder file's converter units)");
            if (feeder.Converters.Count == 0)
            {
                Console.Error.WriteLine($"error: dist3ph harmonics --afe feeder: the feeder {file} has no \"converters\" section (no active-front-end units to stamp).");
                Environment.ExitCode = 1;
                return;
            }
            afe = feeder.Converters;
        }
        var src = GridSim.Core.Harmonics.ThreePhaseHarmonicSource.Balanced(hbus, spectrumName, current, spectrum!);
        int[] orders = spectrum!.Select(c => c.Order).OrderBy(h => h).ToArray();
        GridSim.Core.Harmonics.ThreePhasePenetrationResult hr;
        try { hr = GridSim.Core.Harmonics.ThreePhaseHarmonicPenetration.Solve(model, new[] { src }, orders, activeFrontEnds: afe); }
        catch (Exception ex) when (ex is ArgumentException or InvalidOperationException)
        {
            Console.Error.WriteLine($"dist3ph harmonics: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        int at = hr.BusIds.ToList().IndexOf(hbus);
        if (afe is not null)
            Console.WriteLine($"  active-front-end converters in Y(h) (N354): {afe.Count} unit(s) from the feeder ({string.Join(", ", feeder.ConverterIds)}), " +
                "each R + j h X on its rating as a three-wire shunt (no zero-sequence path).");
        Console.WriteLine($"  balanced harmonic source at bus {feeder.BusLabel(hbus)}: spectrum {spectrumName} " +
            "(library profile, assumed-typical unless a G5-cited one [VERIFY]), fundamental current " + current.ToString("R", inv) + " pu;");
        // N167: capacitors, line charging and closed switches are now in Y(h); say so when the feeder has any (a feeder
        // without them prints exactly the line it always did).
        GridSim.Core.Distribution.MultiPhaseElement inY = model.ElementsPresent &
            (GridSim.Core.Distribution.MultiPhaseElement.Capacitor | GridSim.Core.Distribution.MultiPhaseElement.LineCharging | GridSim.Core.Distribution.MultiPhaseElement.ClosedSwitch);
        Console.WriteLine(inY == GridSim.Core.Distribution.MultiPhaseElement.None
            ? "  network only (series impedances, R + j h X; loads not modelled), source bus as the harmonic reference."
            : "  network only (series impedances, R + j h X; shunt capacitors and line charging, G + j h B; closed switches as one node; " +
              "loads not modelled), source bus as the harmonic reference.");
        Console.WriteLine("  | order | |Va| pu | |Vb| pu | |Vc| pu | |V0| pu | |V1| pu | |V2| pu | worst bus | worst |V| pu |");
        Console.WriteLine("  |-------|--------|--------|--------|--------|--------|--------|-----------|-------------|");
        drep?.Set("bus", hbus).Set("spectrum", spectrumName).Set("fundamental_current_pu", current);
        CliResultTable? ht = drep?.Table("harmonic_voltages", "order", "bus", "phase", "vm_pu", "angle_deg");
        var sumSq = new double[3];
        for (int oi = 0; oi < hr.Orders.Count; oi++)
        {
            System.Numerics.Complex[] v = hr.Voltage[oi][at];
            System.Numerics.Complex[] seq = hr.Sequence(oi, at);
            int worstBus = hr.BusIds[0];
            double worstMag = -1;
            for (int bi = 0; bi < hr.BusIds.Count; bi++)
                for (int p = 0; p < 3; p++)
                {
                    double mag = hr.Voltage[oi][bi][p].Magnitude;
                    if (mag > worstMag) { worstMag = mag; worstBus = hr.BusIds[bi]; }
                    ht?.Row(hr.Orders[oi], hr.BusIds[bi], "abc"[p].ToString(), mag, GridSim.Core.Numerics.DetMath.Phase(hr.Voltage[oi][bi][p]) * 180.0 / Math.PI);
                }
            for (int p = 0; p < 3; p++) sumSq[p] += v[p].Magnitude * v[p].Magnitude;
            Console.WriteLine($"  | {hr.Orders[oi]} | {v[0].Magnitude.ToString("F6", inv)} | {v[1].Magnitude.ToString("F6", inv)} | {v[2].Magnitude.ToString("F6", inv)} | " +
                $"{seq[0].Magnitude.ToString("F6", inv)} | {seq[1].Magnitude.ToString("F6", inv)} | {seq[2].Magnitude.ToString("F6", inv)} | {feeder.BusLabel(worstBus)} | {worstMag.ToString("F6", inv)} |");
        }
        // The root-sum-square harmonic voltage at the source bus, per phase, in pu of the nominal (1 pu) fundamental.
        Console.WriteLine($"  RSS harmonic voltage at bus {feeder.BusLabel(hbus)}: a {Math.Sqrt(sumSq[0]).ToString("F6", inv)} pu, " +
            $"b {Math.Sqrt(sumSq[1]).ToString("F6", inv)} pu, c {Math.Sqrt(sumSq[2]).ToString("F6", inv)} pu");
        drep?.Set("rss_a_pu", Math.Sqrt(sumSq[0])).Set("rss_b_pu", Math.Sqrt(sumSq[1])).Set("rss_c_pu", Math.Sqrt(sumSq[2])).Complete();
        return;
    }

    // mode == "estimate"
    string? mPath = FlagString(a, "--measurements");
    if (mPath is null)
    {
        Console.Error.WriteLine("error: dist3ph estimate needs --measurements <m.json>.");
        Console.Error.WriteLine(usage);
        Environment.ExitCode = 2;
        return;
    }
    string method = (FlagString(a, "--method") ?? "wls").ToLowerInvariant();
    if (method is not ("wls" or "wlav" or "branch-current")) FailFlag<string>("--method", method, "wls, wlav or branch-current");
    // N062: the branch-current estimator has no iteration, so the iteration flags would be ignored: refuse them.
    if (method == "branch-current" && (a.Contains("--tol") || a.Contains("--max-iter")))
    {
        Console.Error.WriteLine("error: dist3ph estimate --method branch-current takes no --tol or --max-iter (it combines the current phasors and makes one forward sweep).");
        Environment.ExitCode = 2;
        return;
    }
    double etol = FlagDouble(a, "--tol", 1e-10);
    int emax = FlagInt(a, "--max-iter", 50);
    if (!(etol > 0)) FailFlag<double>("--tol", etol.ToString("R", inv), "a tolerance above 0");
    if (emax < 1) FailFlag<int>("--max-iter", emax.ToString(inv), "at least 1");
    // D-DOC-217 (October 2026): the robust (WLAV) re-weighting's pass cap and residual floor were fixed at 8 and 1e-3
    // with no way to change them from the command line. They are now flags, with the same defaults (so a run without them
    // is unchanged to the bit), and they belong to --method wlav only: on another method they would be ignored, so they
    // are refused (exit 2) rather than silently accepted.
    if (method != "wlav" && (a.Contains("--robust-passes") || a.Contains("--robust-floor")))
    {
        Console.Error.WriteLine($"error: dist3ph estimate --method {method} takes no --robust-passes or --robust-floor (they control the wlav re-weighting only).");
        Environment.ExitCode = 2;
        return;
    }
    int robustPasses = FlagInt(a, "--robust-passes", 8);
    double robustFloor = FlagDouble(a, "--robust-floor", 1e-3);
    if (robustPasses < 1) FailFlag<int>("--robust-passes", robustPasses.ToString(inv), "at least 1");
    if (!(robustFloor > 0) || !double.IsFinite(robustFloor)) FailFlag<double>("--robust-floor", robustFloor.ToString("R", inv), "a finite number above 0");

    GridSim.Core.Distribution.MultiPhaseMeasurementSet ms;
    try { ms = GridSim.Core.Distribution.MultiPhaseJsonLoader.LoadMeasurements(mPath, feeder); }
    catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or IOException or UnauthorizedAccessException)
    {
        Console.Error.WriteLine($"error loading measurements: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }
    if (method == "branch-current")
    {
        // N062: the branch-current estimator (BranchCurrentDsse, Baran-Kelley): WLS-combines the current phasors per
        // branch and phase, then one forward sweep from the source gives the voltages. It uses current phasors only, so a
        // file with voltage magnitudes or pseudo-measurements is refused rather than have them silently ignored. Every
        // tree branch needs a current measurement; otherwise the estimate is not converged (exit 3).
        if (ms.VoltageMagnitudes.Count > 0 || ms.PseudoVoltageValuePu is not null)
        {
            Console.Error.WriteLine($"error: dist3ph estimate --method branch-current uses current phasors only; {mPath} also has " +
                $"{ms.VoltageMagnitudes.Count} voltage magnitude(s){(ms.PseudoVoltageValuePu is null ? "" : " and pseudo-measurements")}, which it would ignore.");
            Environment.ExitCode = 1;
            return;
        }
        Console.WriteLine($"  measurements: {ms.Currents.Count} current phasor(s); method branch-current");
        GridSim.Core.Distribution.BranchCurrentEstimate be;
        try { be = GridSim.Core.Distribution.BranchCurrentDsse.Estimate(model, ms.Currents); }
        catch (Exception ex) when (ex is InvalidOperationException or ArgumentException)
        {
            Console.Error.WriteLine($"dist3ph estimate: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        if (!be.Converged)
        {
            // D-DOC-114 / D-DOC-165 (October 2026): name what is unobservable. A branch measured on some of its phases only
            // is now not converged (it used to pass with zero current on the unmeasured phases), and a current named in
            // reversed orientation is accepted (it used to land here, blamed on a missing phasor).
            string what = be.UnobservableBranchPhases.Count > 0
                ? $"{be.UnobservableBranchPhases.Count} branch phase(s) have no current phasor and are unobservable: " +
                  string.Join(", ", be.UnobservableBranchPhases.Take(20)) + (be.UnobservableBranchPhases.Count > 20 ? ", ..." : "")
                : "the feeder is not a single radial tree from the source (a bus is not reached, or a loop or parallel branch), or a value is not finite";
            Console.Error.WriteLine($"dist3ph: the branch-current estimate is not converged: {what}. No estimate reported.");
            Environment.ExitCode = 3;
            return;
        }
        Console.WriteLine($"  estimate CONVERGED (one forward sweep over {be.BranchCurrents.Count} measured branch(es))");
        drep?.Set("method", method).Set("current_measurements", ms.Currents.Count).Set("converged", true);
        PrintVoltages(be.BusIds, be.V);
        drep?.Complete();
        return;
    }

    var vmags = new List<GridSim.Core.Distribution.ThreePhaseVMag>(ms.VoltageMagnitudes);
    int pseudoCount = 0;
    if (ms.PseudoVoltageValuePu is double pv && ms.PseudoVoltageSigmaPu is double ps)
    {
        var metered = new HashSet<int>(ms.VoltageMagnitudes.Select(m => m.BusId));
        IReadOnlyList<GridSim.Core.Distribution.ThreePhaseVMag> pseudo =
            GridSim.Core.Distribution.DistributionPseudoMeasurements.NominalVoltageMagnitudes(model, metered, pv, ps);
        vmags.AddRange(pseudo);
        pseudoCount = pseudo.Count;
    }
    Console.WriteLine($"  measurements: {ms.VoltageMagnitudes.Count} voltage magnitude(s), {ms.Currents.Count} current phasor(s), " +
        $"{pseudoCount} nominal-voltage pseudo-measurement(s); method {method}");

    GridSim.Core.Distribution.ThreePhaseWlsResult er;
    try
    {
        er = GridSim.Core.Distribution.ThreePhaseWlsEstimator.Estimate(
            model, vmags, ms.Currents, etol, emax, robust: method == "wlav",
            maxRobustIterations: robustPasses, robustFloor: robustFloor);
    }
    // D-DOC-112: NotSupportedException is the estimator's dense size limit (exit 1, an input it refuses, like the others).
    catch (Exception ex) when (ex is InvalidOperationException or ArgumentException or NotSupportedException)
    {
        Console.Error.WriteLine($"dist3ph estimate: {ex.Message}");
        Environment.ExitCode = 1;
        return;
    }
    if (!er.Converged)
    {
        Console.Error.WriteLine($"dist3ph: the three-phase estimator did not converge after {er.Iterations} iteration(s) " +
            $"(final max state update {er.MaxDelta.ToString("E3", inv)}); the measurement set may be unobservable. No estimate reported.");
        Environment.ExitCode = 3;
        return;
    }
    Console.WriteLine($"  estimate CONVERGED in {er.Iterations} iteration(s), objective J = {er.ObjectiveJ.ToString("E6", inv)}");
    // D-DOC-115 (October 2026): a robust run whose re-weighting hit its pass cap before the weights settled is reported,
    // with the same words the single-phase estimate prints (R175). The exit code stays 0, as there.
    if (er.IrlsCapReached)
        Console.WriteLine($"  WARNING: the robust re-weighting (IRLS) reached its cap of {robustPasses} pass(es) before the weights settled; " +
                          "the state is not a fixed point of the robust estimator.");
    drep?.Set("method", method).Set("voltage_measurements", ms.VoltageMagnitudes.Count).Set("current_measurements", ms.Currents.Count)
        .Set("pseudo_measurements", pseudoCount).Set("converged", true).Set("iterations", er.Iterations).Set("objective_j", er.ObjectiveJ)
        .Set("max_delta", er.MaxDelta).Set("tol", etol).Set("max_iter", emax);
    if (method == "wlav")
        drep?.Set("robust_passes", robustPasses).Set("robust_floor", robustFloor).Set("irls_cap_reached", er.IrlsCapReached);
    PrintVoltages(er.BusIds, er.V);

    // D-DOC-217 (October 2026): the per-measurement residuals, so a reader can see which measurement the objective comes
    // from (there were none). One row per measurement in the fit, in file order (magnitudes, then the pseudo-measurements,
    // then currents); a source-bus magnitude is not in the fit and is not listed. r/sigma is |measured - estimate| / sigma.
    Console.WriteLine("  | measurement | phase | measured pu | estimate pu | r/sigma |");
    Console.WriteLine("  |-------------|-------|-------------|-------------|---------|");
    CliResultTable? residualTable = drep?.Table("residuals", "kind", "from", "to", "phase", "measured_re_pu", "measured_im_pu", "estimate_re_pu", "estimate_im_pu", "sigma_pu", "r_over_sigma");
    string PuText(System.Numerics.Complex c, bool real) => real
        ? c.Real.ToString("F6", inv)
        : $"{c.Real.ToString("F6", inv)}{(c.Imaginary < 0 ? "-" : "+")}j{Math.Abs(c.Imaginary).ToString("F6", inv)}";
    foreach (GridSim.Core.Distribution.ThreePhaseMeasurementResidual resRow in er.Residuals)
    {
        bool isMag = resRow.Kind == "vmag";
        string resWhere = isMag ? $"|V| bus {feeder.BusLabel(resRow.FromBusId)}" : $"I {feeder.BusLabel(resRow.FromBusId)}->{feeder.BusLabel(resRow.ToBusId)}";
        Console.WriteLine($"  | {resWhere} | {"abc"[resRow.Phase]} | {PuText(resRow.Measured, isMag)} | {PuText(resRow.Estimated, isMag)} | {resRow.Standardised.ToString("F3", inv)} |");
        residualTable?.Row(resRow.Kind, resRow.FromBusId, isMag ? null : (object)resRow.ToBusId, "abc"[resRow.Phase].ToString(), resRow.Measured.Real, resRow.Measured.Imaginary,
            resRow.Estimated.Real, resRow.Estimated.Imaginary, resRow.Sigma, resRow.Standardised);
    }
    drep?.Complete();
}

// pmu-estimate <case> --measurements <set.json>
// 1.95.245 (FEATURE-GAPS-RELEASE section 7, R062 rest): the linear PMU state estimate. The set's polar phasor rows
// (VmPu + VaDeg per bus, IMagPu + IAngDeg per from-end branch current, as pmu-ingest --measurements-dir writes them)
// are paired into rectangular phasors with their exact first-order error covariance (Core PmuMeasurementSetAdapter) and
// solved in one non-iterative weighted least-squares step (Core LinearPmuStateEstimator). Rows of other kinds, and a
// magnitude or angle without its partner, are listed as not used (never dropped without a line). Exit 0 estimated;
// 1 for a set or case that cannot be read, fails validation or holds no phasor; 2 for usage or a set newer than the
// horizon (REJECTED); 3 when the phasors do not determine every bus voltage (singular gain: not observable).
void RunPmuEstimate(List<string> a, string root)
{
    const string usage = "usage: gridsim pmu-estimate <case> --measurements <set.json> [--json <file>] [--csv <file>] [--out <file.json|file.csv>]";
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    RequireVerbFlags("pmu-estimate", a, "--measurements", "--out", "--json", "--csv");
    List<string> pos = Positionals(a).Skip(1).ToList();
    string? setPath = FlagString(a, "--measurements");
    if (pos.Count != 1 || setPath is null) { Console.Error.WriteLine(usage); Environment.ExitCode = 2; return; }

    GridModel m;
    try { m = LoadCaseArgument(pos[0], root); }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{pos[0]}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    MeasurementSet set;
    try { set = MeasurementSet.Load(setPath); set.Validate(m); }
    catch (ForwardInferenceException ex) { Console.Error.WriteLine($"REJECTED (forward inference): {ex.Message}"); Environment.ExitCode = 2; return; }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidDataException or System.Text.Json.JsonException)
    { Console.Error.WriteLine($"pmu-estimate: {setPath}: {ex.Message}"); Environment.ExitCode = 1; return; }

    GridSim.Core.Estimation.PmuPhasorSet phasors;
    GridSim.Core.Estimation.LinearPmuResult r;
    try
    {
        phasors = GridSim.Core.Estimation.PmuMeasurementSetAdapter.FromSet(set, m);
        if (phasors.Voltages.Count + phasors.Currents.Count == 0)
        {
            Console.Error.WriteLine($"pmu-estimate: {setPath}: the set holds no voltage or current phasor (a VmPu + VaDeg pair at a bus, or an IMagPu + IAngDeg pair on a branch), so there is nothing to estimate from.");
            foreach (string line in phasors.NotUsed) Console.Error.WriteLine($"  not used: {line}");
            Environment.ExitCode = 1;
            return;
        }
        r = GridSim.Core.Estimation.LinearPmuStateEstimator.Estimate(m, phasors.Voltages, phasors.Currents);
    }
    catch (InvalidDataException ex) { Console.Error.WriteLine($"pmu-estimate: {setPath}: {ex.Message}"); Environment.ExitCode = 1; return; }

    int rows = 2 * (phasors.Voltages.Count + phasors.Currents.Count);
    int states = 2 * m.BusCount;
    Console.WriteLine($"Linear PMU state estimate - {m.Name} ({m.BusCount.ToString(inv)} buses) from {Path.GetFileName(setPath)}" +
        (set.TakenUtc is DateTime taken ? $" taken {taken.ToString("yyyy-MM-ddTHH:mm:ss.fffZ", inv)}" : ""));
    Console.WriteLine($"  phasors used: {phasors.Voltages.Count.ToString(inv)} voltage, {phasors.Currents.Count.ToString(inv)} current " +
        $"({rows.ToString(inv)} rectangular rows for {states.ToString(inv)} states); not used: {phasors.NotUsed.Count.ToString(inv)} row(s)");
    foreach (string line in phasors.NotUsed) Console.WriteLine($"  not used: {line}");
    if (!r.Converged)
    {
        Console.Error.WriteLine($"pmu-estimate: NOT OBSERVABLE - the {phasors.Voltages.Count.ToString(inv)} voltage and {phasors.Currents.Count.ToString(inv)} current phasor(s) do not determine every bus voltage of {m.Name} (the gain matrix is singular); no estimate.");
        Environment.ExitCode = 3;
        return;
    }
    Console.WriteLine($"  objective J = sum (r / sigma)^2 = {r.ObjectiveJ.ToString("G6", inv)} over {(rows - states).ToString(inv)} degree(s) of freedom (one non-iterative solve; no bad-data test)");
    Console.WriteLine("  bus      |V| pu      angle deg");
    for (int i = 0; i < r.BusIds.Count; i++)
        Console.WriteLine($"  {r.BusIds[i],-6} {r.Vm[i].ToString("F6", inv),10} {r.VaDeg[i].ToString("F4", inv),14}");

    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("measurements", Path.GetFileName(setPath)).Set("voltage_phasors", phasors.Voltages.Count)
            .Set("current_phasors", phasors.Currents.Count).Set("rows_not_used", phasors.NotUsed.Count)
            .Set("objective_j", r.ObjectiveJ).Set("degrees_of_freedom", rows - states);
        CliResultTable buses = rep.Table("buses", "bus_id", "vm_pu", "va_deg");
        for (int i = 0; i < r.BusIds.Count; i++) buses.Row(r.BusIds[i], r.Vm[i], r.VaDeg[i]);
        CliResultTable unused = rep.Table("not_used", "row");
        foreach (string line in phasors.NotUsed) unused.Row(line);
        rep.Complete();
    }
}

// N340 (CF5): the live half of pmu-ingest --live. Parses the address and the live flags, receives over TCP (connect to
// the PMU / PDC, send CONFIG-2 and transmission-on commands to --live-idcode) or UDP (listen), and returns the frames as a
// capture for the recorded pipeline. Usage errors exit 2, an address or transport failure (no connection, a framing
// fault) exits 1 (an input error, as an unreadable capture file is); null then, with the reason printed.
GridSim.Core.Synchrophasor.C37118LiveCapture? ReceiveLivePmu(List<string> a, string address)
{
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    (bool tcp, string host, int port) target;
    try { target = GridSim.Core.Synchrophasor.C37118LiveReceiver.ParseAddress(address); }
    catch (ArgumentException ex) { Console.Error.WriteLine($"error: pmu-ingest --live: {ex.Message}"); Environment.ExitCode = 2; return null; }
    string? framesText = FlagString(a, "--live-frames");
    if (framesText is null) { Console.Error.WriteLine("error: pmu-ingest --live needs --live-frames N (how many DATA frames to collect)."); Environment.ExitCode = 2; return null; }
    if (!int.TryParse(framesText, System.Globalization.NumberStyles.None, inv, out int dataFrames) || dataFrames < 1)
    { Console.Error.WriteLine($"error: pmu-ingest --live-frames must be a whole number of 1 or more (got '{framesText}')."); Environment.ExitCode = 2; return null; }
    string secondsText = FlagString(a, "--live-seconds") ?? "30";
    if (!double.TryParse(secondsText, System.Globalization.NumberStyles.Float, inv, out double seconds) || !double.IsFinite(seconds) || !(seconds > 0) || seconds > 86400)
    { Console.Error.WriteLine($"error: pmu-ingest --live-seconds must be a number above 0 and at most 86400 (got '{secondsText}')."); Environment.ExitCode = 2; return null; }
    string? idText = FlagString(a, "--live-idcode");
    if (!target.tcp && idText is not null)
    { Console.Error.WriteLine("error: pmu-ingest --live-idcode addresses TCP commands; a udp:// stream is listened to, not commanded."); Environment.ExitCode = 2; return null; }
    int idCode = 1;
    if (idText is not null && (!int.TryParse(idText, System.Globalization.NumberStyles.None, inv, out idCode) || idCode > ushort.MaxValue))
    { Console.Error.WriteLine($"error: pmu-ingest --live-idcode must be a whole number from 0 to 65535 (got '{idText}')."); Environment.ExitCode = 2; return null; }
    // GR-818 (opt-in): --live-udp-source <ip> reads only datagrams sent from that address; others are dropped and counted.
    string? sourceText = FlagString(a, "--live-udp-source");
    System.Net.IPAddress? udpSource = null;
    if (sourceText is not null)
    {
        if (target.tcp)
        { Console.Error.WriteLine("error: pmu-ingest --live-udp-source filters a udp:// stream; a tcp:// connection already has one peer."); Environment.ExitCode = 2; return null; }
        if (!System.Net.IPAddress.TryParse(sourceText, out udpSource))
        { Console.Error.WriteLine($"error: pmu-ingest --live-udp-source must be an IP address (got '{sourceText}')."); Environment.ExitCode = 2; return null; }
    }
    var options = new GridSim.Core.Synchrophasor.C37118LiveOptions(dataFrames, TimeSpan.FromSeconds(seconds), udpSource);
    try
    {
        return target.tcp
            ? GridSim.Core.Synchrophasor.C37118LiveReceiver.ReceiveTcp(target.host, target.port, idCode, options)
            : GridSim.Core.Synchrophasor.C37118LiveReceiver.ReceiveUdp(System.Net.IPAddress.Parse(target.host), target.port, options);
    }
    catch (Exception ex) when (ex is InvalidDataException or IOException or System.Net.Sockets.SocketException or FormatException)
    {
        Console.Error.WriteLine($"pmu-ingest: {address}: {ex.Message}");
        Environment.ExitCode = 1;
        return null;
    }
}

// pmu-ingest <capture.bin>
// N061 (October 2026): read a recorded IEEE C37.118.2 stream (the frames as sent, back to back: a CONFIG-1 or CONFIG-2
// frame, then DATA frames) through the Core decoder: every frame's CRC is checked, the CONFIG frame is parsed, every
// DATA frame is decoded with one block per PMU of that configuration (C37118Decoder's stream overload), and the samples
// are aligned by the phasor data concentrator. Prints the frame counts, one line per PMU (samples, time span,
// frequency range, non-zero STAT words) and the aligned instants with any PMU missing. Exit 0 when every frame decoded;
// 3 when any DATA frame failed its CRC, was malformed, or came before any CONFIG frame (the summary is still printed);
// 1 when the file is missing, cannot be split into frames, or holds no usable CONFIG frame; 2 for usage.
//
// D-DOC-107 (October 2026): every decoded DATA frame's time passes the horizon guard (real clock) before anything is
// printed: a capture holding any frame newer than the horizon is refused whole, REJECTED, exit 2 (as freq and replay
// refuse a fresh CSV). With --channels <map.json> --measurements-dir <dir>, every aligned instant is mapped through
// PmuMeasurementSetMapper (which applies the guard again) into a gridsim-measurements/1 set in <dir>, ready for
// estimate or serve; before, pmu-ingest built no measurement set at all.
// D-DOC-108 (October 2026): STAT and the FRACSEC time quality are acted on by the documented rule in
// C37118SampleQuality: a sample the PMU flags as invalid data, an unsynchronised sample, and every sample of a frame
// whose time is unreliable is dropped (never aligned, never mapped), counted per PMU and per reason, and the run exits
// 3, like a frame with a bad CRC. Before, both were stored and never read.
// DOC-15 (October 2026): the capture is framed whole before any frame is decoded (D-DOC-223); the channel map is checked
// against every configuration in force for a decoded DATA frame, not only the last one (D-DOC-008); a CONFIG frame with
// TIME_BASE 0 is refused by name (D-DOC-111) and a DATA frame whose FRACSEC is not below TIME_BASE is malformed; frame
// times are exact integer ticks (D-DOC-110).
void RunPmuIngest(List<string> a)
{
    const string usage = "usage: gridsim pmu-ingest (<capture.bin> | --live tcp://host:port|udp://[bind]:port --live-frames N [--live-seconds S] [--live-idcode ID] [--live-quarantine <dir>])\n" +
                         "                          [--channels <map.json> --measurements-dir <dir>]   (an IEEE C37.118.2 stream: CONFIG then DATA frames)";
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    RequireVerbFlags("pmu-ingest", a, "--channels", "--measurements-dir", "--live", "--live-frames", "--live-seconds", "--live-idcode",
        "--live-quarantine",   // N358 (CF6)
        "--live-udp-source");  // GR-818
    // D-DOC-107: the channel map and the output folder go together: one without the other cannot build a set.
    string? channelsPath = FlagString(a, "--channels");
    string? setsDir = FlagString(a, "--measurements-dir");
    if ((channelsPath is null) != (setsDir is null))
    {
        Console.Error.WriteLine("error: pmu-ingest: --channels and --measurements-dir go together (the channel map says what each phasor " +
            "measures; the folder receives one gridsim-measurements/1 set per aligned instant).");
        Environment.ExitCode = 2;
        return;
    }
    List<string> pos = Positionals(a).Skip(1).ToList();
    // N340 (CF5): --live replaces the capture file with a live C37.118 stream. Default off: without --live this verb reads
    // a recorded capture exactly as before. The live flags mean nothing without --live, so they are refused alone.
    string? liveAddress = FlagString(a, "--live");
    // N358 (CF6): --live-quarantine <dir> is opt-in and qualifies --live only (a recorded capture is never quarantined:
    // a capture holding a present-time frame is still refused whole, as before).
    string? quarantineDir = FlagString(a, "--live-quarantine");
    bool liveFlagsAlone = liveAddress is null && (a.Contains("--live-frames") || a.Contains("--live-seconds") || a.Contains("--live-idcode")
        || a.Contains("--live-quarantine"));
    if (liveFlagsAlone || (liveAddress is null ? pos.Count != 1 : pos.Count != 0))
    {
        if (liveFlagsAlone) Console.Error.WriteLine("error: pmu-ingest: --live-frames, --live-seconds, --live-idcode and --live-quarantine qualify --live.");
        else if (liveAddress is not null) Console.Error.WriteLine("error: pmu-ingest: --live reads a stream; give no capture file with it.");
        Console.Error.WriteLine(usage);
        Environment.ExitCode = 2;
        return;
    }
    string path = liveAddress ?? pos[0];
    // Load the channel map before the capture so a bad map stops the run before any work (exit 1, an input error).
    GridSim.Core.Synchrophasor.PmuChannelMapSet? channelMap = null;
    if (channelsPath is not null)
    {
        try { channelMap = GridSim.Core.Synchrophasor.PmuChannelMapFile.Load(channelsPath); }
        catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or DirectoryNotFoundException or IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"pmu-ingest: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }
    // N358 (CF6): refuse a quarantine folder inside the GDA public evidence lake before any receive (exit 1, an input
    // error), so a live run never connects only to find it has nowhere lawful to put the present-time frames.
    if (quarantineDir is not null)
    {
        try { GridSim.Core.Synchrophasor.PmuLiveQuarantine.RefuseIfInsideEvidenceLake(quarantineDir); }
        catch (Exception ex) when (ex is InvalidDataException or ArgumentException or IOException or UnauthorizedAccessException or System.Security.SecurityException)
        {
            Console.Error.WriteLine($"pmu-ingest: --live-quarantine: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }
    byte[] bytes;
    DateTime liveReceivedUtc = default;   // N358 (CF6): when the live receive ended (names the quarantine capture)
    // N340 (CF5): a live receive that hit a transport fault the pipeline cannot see (UDP datagrams that were not one frame,
    // or a timeout before the DATA frames asked for) still runs the pipeline on what arrived, then exits 3.
    bool liveShortfall = false;
    if (liveAddress is not null)
    {
        GridSim.Core.Synchrophasor.C37118LiveCapture? live = ReceiveLivePmu(a, liveAddress);
        if (live is null) return;   // usage or transport error already reported, exit code set
        liveReceivedUtc = DateTime.UtcNow;
        bytes = live.Bytes;
        Console.WriteLine($"live: {live.Frames} frame(s) received from {liveAddress} ({live.DataFrames} DATA, {live.CrcFailures} with a bad CRC" +
            (live.MalformedDatagrams > 0 ? $", {live.MalformedDatagrams} datagram(s) not one frame, dropped" : "") +
            (live.ForeignDatagrams > 0 ? $", {live.ForeignDatagrams} datagram(s) from another sender, dropped (--live-udp-source)" : "") +
            (live.TimedOut ? "; stopped on the timeout before the DATA frames asked for" : "") + ")");
        liveShortfall = live.MalformedDatagrams > 0 || live.TimedOut;
        if (bytes.Length == 0)
        {
            Console.Error.WriteLine($"pmu-ingest: {liveAddress}: no frame arrived.");
            Environment.ExitCode = 3;
            return;
        }
    }
    else
    {
        // N358 (CF6): a quarantined live capture (named *.quarantine.c37, or with a .quarantine.json sidecar) is never read
        // as a recorded capture, whatever its age: past the horizon it would pass the time check and launder its tag.
        try { GridSim.Core.Synchrophasor.PmuLiveQuarantine.RefuseQuarantinedCapture(path); }
        catch (InvalidDataException ex)
        {
            Console.Error.WriteLine($"pmu-ingest: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        try { bytes = File.ReadAllBytes(path); }
        catch (Exception ex) when (ex is FileNotFoundException or DirectoryNotFoundException or IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"pmu-ingest: cannot read {path}: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }

    // D-DOC-223 (October 2026): framing first, decoding second. Pass 1 only splits the capture into frames (SYNC 0xAA,
    // the 16-bit FRAMESIZE, the 14-byte common header) and refuses the file whole, exit 1, when it does not split cleanly,
    // before any frame is decoded. Pass 2 then parses and decodes the frames it found. Before, one loop framed and decoded
    // together, so a capture that failed to frame at byte N had already parsed every CONFIG frame and decoded every DATA
    // frame before N (and a decode refusal among them was reported instead of the framing fault). Splitting the passes
    // also gives pass 2 the whole list of frames, so each DATA frame can be tied to the configuration in force for it
    // (D-DOC-008, below).
    var frameAt = new List<(int Offset, int Size, GridSim.Core.Synchrophasor.C37118CommonHeader Header)>();
    int at = 0;
    while (at < bytes.Length)
    {
        // Framing: SYNC 0xAA, then the 16-bit FRAMESIZE. A stream that does not split cleanly is refused whole: there is
        // no way to tell where the next frame starts, and guessing could decode garbage as data.
        if (bytes.Length - at < 4 || bytes[at] != 0xAA)
        {
            Console.Error.WriteLine($"pmu-ingest: {path}: byte {at} does not start a C37.118 frame (expected SYNC 0xAA and a frame size); " +
                $"{frameAt.Count} frame(s) read before it. The file is not a clean C37.118 capture.");
            Environment.ExitCode = 1;
            return;
        }
        int size = System.Buffers.Binary.BinaryPrimitives.ReadUInt16BigEndian(bytes.AsSpan(at + 2));
        if (size < 16 || at + size > bytes.Length)
        {
            Console.Error.WriteLine($"pmu-ingest: {path}: the frame at byte {at} declares {size} bytes but {(size < 16 ? "a frame is at least 16" : $"only {bytes.Length - at} remain")}; the capture is truncated or corrupt.");
            Environment.ExitCode = 1;
            return;
        }
        GridSim.Core.Synchrophasor.C37118CommonHeader h;
        try { h = GridSim.Core.Synchrophasor.C37118Decoder.ReadHeader(bytes.AsSpan(at, size)); }
        catch (ArgumentException ex)
        {
            Console.Error.WriteLine($"pmu-ingest: {path}: frame {frameAt.Count + 1} (byte {at}): {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        frameAt.Add((at, size, h));
        at += size;
    }
    int frames = frameAt.Count;

    // Pass 2: parse the CONFIG frames and decode the DATA frames, in capture order. Each DATA frame is decoded against the
    // configuration in force when it arrived (the last good CONFIG frame before it).
    GridSim.Core.Synchrophasor.C37118ConfigFrame? config = null;
    int configFrameNumber = 0;   // the frame number (1-based) the configuration in force arrived in
    int configFrames = 0, dataOk = 0, dataCrc = 0, dataMalformed = 0, dataBeforeConfig = 0, configCrc = 0, otherFrames = 0, configChanges = 0;
    // GR-304: DATA frames refused because their IDCODE is not the stream's (counted within dataMalformed as well, so the
    // report keys keep their meaning; named separately on stderr). GR-826: CONFIG-1 frames not put in force because a
    // CONFIG-2 already was.
    int dataWrongStream = 0, config1Ignored = 0;
    var samples = new List<GridSim.Core.Synchrophasor.C37118StreamDataFrame>();
    var sampleTimeQuality = new List<byte>();   // D-DOC-108: FRACSEC time quality of samples[i]
    // D-DOC-008: every configuration that decoded at least one DATA frame, in order: the configuration, the frame number it
    // arrived in, and how many DATA frames it decoded. The channel map is checked against each of them, not only the last.
    var configsInForce = new List<(GridSim.Core.Synchrophasor.C37118ConfigFrame Config, int FrameNumber)>();
    var dataFramesPerConfig = new List<int>();
    // N260 (October 2026): for each decoded sample (samples[i]), the index into configsInForce of the configuration it was
    // decoded with, so the per-PMU table, the expected-PMU list and the "PMU missing" count can follow the configuration
    // in force at each instant rather than the last one of the capture.
    var sampleConfig = new List<int>();
    // N358 (CF6): for each decoded sample (samples[i]), the index of its frame in frameAt, so a quarantine can keep the
    // frames it holds back, byte for byte. Bookkeeping only: no decoded value depends on it.
    var sampleFrame = new List<int>();
    for (int n = 0; n < frameAt.Count; n++)
    {
        (int offset, int size, GridSim.Core.Synchrophasor.C37118CommonHeader h) = frameAt[n];
        ReadOnlySpan<byte> frame = bytes.AsSpan(offset, size);
        switch (h.FrameType)
        {
            case GridSim.Core.Synchrophasor.C37118FrameType.Config1 or GridSim.Core.Synchrophasor.C37118FrameType.Config2:
                configFrames++;
                if (!GridSim.Core.Synchrophasor.C37118Decoder.VerifyCrc(frame)) { configCrc++; break; }
                try
                {
                    GridSim.Core.Synchrophasor.C37118ConfigFrame next = GridSim.Core.Synchrophasor.C37118ConfigParser.Parse(frame);
                    // GR-826: CONFIG-1 is what the PMU CAN send, CONFIG-2 what the stream DOES send (IEEE C37.118.2). A
                    // CONFIG-1 is still parsed (so a corrupt one fails loud) and is used when no CONFIG-2 has arrived yet,
                    // but it never replaces a CONFIG-2 in force; it used to, so a capability frame in the middle of a
                    // capture could resize every DATA frame after it.
                    if (next.IsConfig1 && config is not null && !config.IsConfig1) { config1Ignored++; break; }
                    if (config is not null && !SameConfig(config, next)) configChanges++;
                    config = next;
                    configFrameNumber = n + 1;
                }
                catch (Exception ex) when (ex is ArgumentException or ArgumentOutOfRangeException)
                {
                    Console.Error.WriteLine($"pmu-ingest: {path}: CONFIG frame {n + 1} passed its CRC but cannot be parsed: {ex.Message}");
                    Environment.ExitCode = 1;
                    return;
                }
                break;
            case GridSim.Core.Synchrophasor.C37118FrameType.Data:
                if (config is null) { dataBeforeConfig++; break; }
                GridSim.Core.Synchrophasor.C37118StreamDataFrame d;
                try { d = GridSim.Core.Synchrophasor.C37118Decoder.DecodeData(frame, config); }
                catch (ArgumentException ex)
                {
                    Console.Error.WriteLine($"pmu-ingest: {path}: {ex.Message}");
                    Environment.ExitCode = 1;
                    return;
                }
                // D-DOC-108: keep the frame's FRACSEC message time quality beside it (the header holds it; the decoded
                // frame does not), so every block of the frame can be judged.
                if (d.Status == GridSim.Core.Synchrophasor.FrameDecodeStatus.Ok)
                {
                    dataOk++;
                    samples.Add(d);
                    sampleFrame.Add(n);   // N358 (CF6)
                    sampleTimeQuality.Add(h.TimeQuality);
                    // D-DOC-008: note the configuration this frame was decoded with (by reference: the same object for
                    // every frame until the next CONFIG frame replaces it).
                    if (configsInForce.Count == 0 || !ReferenceEquals(configsInForce[^1].Config, config))
                    {
                        configsInForce.Add((config, configFrameNumber));
                        dataFramesPerConfig.Add(0);
                    }
                    dataFramesPerConfig[^1]++;
                    sampleConfig.Add(configsInForce.Count - 1);   // N260
                }
                else if (d.Status == GridSim.Core.Synchrophasor.FrameDecodeStatus.CrcMismatch) dataCrc++;
                else
                {
                    dataMalformed++;
                    if (d.Status == GridSim.Core.Synchrophasor.FrameDecodeStatus.WrongStream) dataWrongStream++;   // GR-304
                }
                break;
            default:
                otherFrames++;   // HEADER, COMMAND and CONFIG-3 frames carry no measurement; counted, not decoded
                break;
        }
    }
    if (config is null)
    {
        Console.Error.WriteLine($"pmu-ingest: {path}: no usable CONFIG-1 / CONFIG-2 frame ({configFrames} found, {configCrc} with a bad CRC), so no DATA frame can be decoded.");
        Environment.ExitCode = 1;
        return;
    }

    // N358 (CF6): --live --live-quarantine <dir>. A live device streams the present, so (below) the horizon refuses the
    // whole run. With the quarantine asked for, the decoded DATA frames newer than the horizon are held back FIRST: their
    // frames are written to the quarantine folder as received (with the CONFIG frames and every frame that carried no
    // trusted time: bad CRC, malformed, before any CONFIG, other types), tagged CuratedPlaceholder (never Recorded) and
    // marked non-evidential by a sidecar, and they are removed from the samples, so no later step (quality, concentrator,
    // channel map, measurement sets, the report table) ever sees them. Only DATA frames already older than the horizon
    // stay, and they still pass the unchanged horizon check below. Without the flag nothing here runs.
    DateTime guardNow = DateTime.UtcNow;
    string? quarantineLine = null;
    int quarantinedDataFrames = 0;
    if (quarantineDir is not null && liveAddress is not null)
    {
        var fresh = new bool[samples.Count];
        DateTime? oldestFresh = null, newestFresh = null;
        for (int i = 0; i < samples.Count; i++)
        {
            if (!GridSim.Core.Synchrophasor.PmuLiveQuarantine.IsNewerThanHorizon(samples[i].TimeUtc, guardNow)) continue;
            fresh[i] = true;
            quarantinedDataFrames++;
            if (oldestFresh is null || samples[i].TimeUtc < oldestFresh) oldestFresh = samples[i].TimeUtc;
            if (newestFresh is null || samples[i].TimeUtc > newestFresh) newestFresh = samples[i].TimeUtc;
        }
        // The frames that continue as recorded data (decoded, older than the horizon) are the only ones NOT quarantined.
        var continuing = new HashSet<int>();
        for (int i = 0; i < samples.Count; i++) if (!fresh[i]) continuing.Add(sampleFrame[i]);
        if (quarantinedDataFrames > 0)
        {
            var held = new List<byte[]>();
            for (int n = 0; n < frameAt.Count; n++)
                if (!continuing.Contains(n)) held.Add(bytes.AsSpan(frameAt[n].Offset, frameAt[n].Size).ToArray());
            try
            {
                (string capturePath, string sidecarPath) = GridSim.Core.Synchrophasor.PmuLiveQuarantine.Write(
                    quarantineDir, held, liveAddress, liveReceivedUtc, GridSim.Core.Diagnostics.ForwardInferenceGuard.Horizon(guardNow),
                    quarantinedDataFrames, oldestFresh, newestFresh);
                quarantineLine = $"  quarantine: {quarantinedDataFrames} DATA frame(s) newer than the horizon held back, not ingested: {held.Count} frame(s) " +
                    $"written to {capturePath} (sidecar {Path.GetFileName(sidecarPath)}; provenance {GridSim.Core.Synchrophasor.PmuLiveQuarantine.Tag}, " +
                    "non-evidential, never Recorded)";
            }
            catch (Exception ex) when (ex is InvalidDataException or ArgumentException or IOException or UnauthorizedAccessException)
            {
                Console.Error.WriteLine($"pmu-ingest: --live-quarantine: {ex.Message}");
                Environment.ExitCode = 1;
                return;
            }
            // Remove the held-back samples from every per-sample list, in step (the lists are parallel by index).
            var keepSamples = new List<GridSim.Core.Synchrophasor.C37118StreamDataFrame>();
            var keepQuality = new List<byte>();
            var keepConfig = new List<int>();
            var keepFrame = new List<int>();
            for (int i = 0; i < samples.Count; i++)
            {
                if (fresh[i]) continue;
                keepSamples.Add(samples[i]);
                keepQuality.Add(sampleTimeQuality[i]);
                keepConfig.Add(sampleConfig[i]);
                keepFrame.Add(sampleFrame[i]);
            }
            samples = keepSamples;
            sampleTimeQuality = keepQuality;
            sampleConfig = keepConfig;
            sampleFrame = keepFrame;
        }
        else quarantineLine = "  quarantine: no DATA frame newer than the horizon; nothing written to the quarantine";
    }

    // D-DOC-107 (HORIZON): every decoded DATA frame's time must be older than the horizon, judged against the real clock,
    // before anything is printed or written: one fresh (or future) frame refuses the whole capture, REJECTED, exit 2, as
    // freq and replay refuse a fresh CSV. (A frame whose CRC failed carries no trusted time and is already not used.)
    // N358 (CF6): after a quarantine the frames it held back are no longer in samples, so this check sees only what
    // continues; without --live-quarantine it is exactly the previous check (guardNow is the same real-clock read).
    try
    {
        foreach (GridSim.Core.Synchrophasor.C37118StreamDataFrame d in samples)
            ForwardInferenceGuard.RejectFuture(d.TimeUtc, guardNow, "C37.118 DATA frame");
    }
    catch (ForwardInferenceException ex)
    {
        Console.Error.WriteLine($"REJECTED (forward inference): pmu-ingest: {path}: {ex.Message}");
        Environment.ExitCode = CliExit.Usage;
        return;
    }

    // D-DOC-107: the channel map must fit the capture's CONFIG frame (PMU ids, phasor indices, voltage vs current),
    // checked before any output so a mistyped index never reaches the mapper.
    // D-DOC-008 (October 2026): checked against EVERY configuration in force for a decoded DATA frame, not only the last
    // CONFIG frame of the capture. Before, a capture whose configuration changed mid-stream was checked against its last
    // configuration only, so a map that fitted the later configuration but not an earlier one (an earlier configuration
    // with fewer phasors, or without a mapped PMU) passed, and the earlier frames' samples then reached the mapper with
    // too few phasors: a raw IndexOutOfRangeException. Each configuration that does not fit is named by the frame it
    // arrived in. A capture with no decoded DATA frame is checked against its last configuration, as before.
    if (channelMap is not null)
    {
        var checkAgainst = configsInForce.Count > 0 ? configsInForce : new() { (config, configFrameNumber) };
        var misfits = new List<string>();
        for (int c = 0; c < checkAgainst.Count; c++)
        {
            try { GridSim.Core.Synchrophasor.PmuChannelMapFile.ValidateAgainst(channelMap, checkAgainst[c].Config); }
            catch (InvalidDataException ex)
            {
                // One configuration: the message as before. Several: say which one (and how many frames it decoded).
                misfits.Add(checkAgainst.Count == 1 ? ex.Message
                    : $"against the configuration from CONFIG frame {checkAgainst[c].FrameNumber} (in force for {dataFramesPerConfig[c]} decoded DATA frame(s)): {ex.Message}");
            }
        }
        if (misfits.Count > 0)
        {
            foreach (string m in misfits) Console.Error.WriteLine($"pmu-ingest: {channelsPath}: {m}");
            Environment.ExitCode = 1;
            return;
        }
    }

    // D-DOC-108: judge every block by the documented rule (C37118SampleQuality): the frame's FRACSEC time quality, then
    // the block's STAT word. Only usable samples are aligned (and so mapped); the rest are counted per PMU and reason.
    var verdicts = new List<GridSim.Core.Synchrophasor.C37118SampleVerdict[]>(samples.Count);
    var droppedByPmu = new Dictionary<int, int>();
    int droppedInvalid = 0, droppedUnsync = 0, droppedFrameTime = 0;
    for (int i = 0; i < samples.Count; i++)
    {
        var v = new GridSim.Core.Synchrophasor.C37118SampleVerdict[samples[i].Blocks.Count];
        for (int k = 0; k < v.Length; k++)
        {
            GridSim.Core.Synchrophasor.C37118PmuBlock b = samples[i].Blocks[k];
            v[k] = GridSim.Core.Synchrophasor.C37118SampleQuality.Of(sampleTimeQuality[i], b.Stat);
            if (v[k] == GridSim.Core.Synchrophasor.C37118SampleVerdict.Usable) continue;
            droppedByPmu[b.IdCode] = droppedByPmu.GetValueOrDefault(b.IdCode) + 1;
            if (v[k] == GridSim.Core.Synchrophasor.C37118SampleVerdict.InvalidData) droppedInvalid++;
            else if (v[k] == GridSim.Core.Synchrophasor.C37118SampleVerdict.Unsynchronised) droppedUnsync++;
            else droppedFrameTime++;
        }
        verdicts.Add(v);
    }
    int droppedSamples = droppedInvalid + droppedUnsync + droppedFrameTime;

    // N260 (October 2026): the PMUs of EVERY configuration in force for a decoded DATA frame, in order of first appearance
    // (the last configuration's PMUs when no DATA frame decoded). The per-PMU table and the expected-PMU list used only the
    // capture's LAST configuration, so after a mid-stream change that removed a PMU its earlier samples were in no row
    // (and not expected), and a PMU added later counted as missing at every instant before it existed. For a capture with
    // one configuration this is exactly that configuration's list, so its output is unchanged.
    var pmuOrder = new List<int>();
    var pmuStation = new Dictionary<int, string>();
    var pmuPhasorCounts = new Dictionary<int, List<int>>();
    foreach (GridSim.Core.Synchrophasor.C37118ConfigFrame c in configsInForce.Count > 0 ? configsInForce.Select(x => x.Config) : new[] { config })
        foreach (GridSim.Core.Synchrophasor.PmuConfig pc in c.Pmus)
        {
            if (!pmuPhasorCounts.TryGetValue(pc.IdCode, out List<int>? counts))
            {
                pmuOrder.Add(pc.IdCode);
                pmuPhasorCounts[pc.IdCode] = counts = new List<int>();
            }
            pmuStation[pc.IdCode] = pc.StationName;   // the latest name the PMU was configured with
            if (!counts.Contains(pc.PhasorCount)) counts.Add(pc.PhasorCount);
        }
    // The PMUs expected at each reporting instant: those of the configuration(s) the instant's frames were decoded with.
    var expectedAt = new Dictionary<long, HashSet<int>>();
    for (int i = 0; i < samples.Count; i++)
    {
        long ticks = samples[i].TimeUtc.Ticks;
        if (!expectedAt.TryGetValue(ticks, out HashSet<int>? ids)) expectedAt[ticks] = ids = new HashSet<int>();
        foreach (GridSim.Core.Synchrophasor.PmuConfig pc in configsInForce[sampleConfig[i]].Config.Pmus) ids.Add(pc.IdCode);
    }

    // Align every PMU's usable samples on their reporting instants (end of stream: flush everything). A dropped sample
    // leaves its PMU missing at that instant, exactly as if it had not reported.
    var pdc = new GridSim.Core.Synchrophasor.PhasorDataConcentrator(pmuOrder, TimeSpan.Zero);
    for (int i = 0; i < samples.Count; i++)
        for (int k = 0; k < samples[i].Blocks.Count; k++)
        {
            if (verdicts[i][k] != GridSim.Core.Synchrophasor.C37118SampleVerdict.Usable) continue;
            GridSim.Core.Synchrophasor.C37118PmuBlock b = samples[i].Blocks[k];
            pdc.Ingest(new GridSim.Core.Synchrophasor.PmuSample(b.IdCode, samples[i].TimeUtc, b.Phasors, b.FreqHz, b.RocofHzPerS));
        }
    IReadOnlyList<GridSim.Core.Synchrophasor.PdcSuperframe> aligned = pdc.FlushAll();
    // N260: an instant is incomplete when a PMU of the configuration in force THEN did not report usably (for a capture
    // with one configuration, exactly the concentrator's own dropout list, as before).
    int incomplete = aligned.Count(s => expectedAt.TryGetValue(s.TimeUtc.Ticks, out HashSet<int>? ids)
        ? ids.Any(id => !s.Samples.ContainsKey(id))
        : s.Dropped.Count > 0);

    Console.WriteLine($"PMU INGEST - {path}  [IEEE C37.118.2 capture, {bytes.Length} bytes]   [EXPERIMENTAL]");
    Console.WriteLine($"  {frames} frame(s): {configFrames} CONFIG ({configCrc} bad CRC), {dataOk + dataCrc + dataMalformed + dataBeforeConfig} DATA " +
        $"({dataOk} decoded, {dataCrc} bad CRC, {dataMalformed} malformed, {dataBeforeConfig} before any CONFIG), {otherFrames} other");
    if (quarantineLine is not null) Console.WriteLine(quarantineLine);   // N358 (CF6): only with --live-quarantine
    // N260: the line used to say "the last one is used for later frames" after a change, which read as if every frame
    // were decoded with the last configuration. Each DATA frame is decoded with the configuration in force when it
    // arrived, and the table lists every PMU of every configuration in force.
    Console.WriteLine((configChanges > 0 ? "  last configuration: " : "  configuration: ") +
        $"{config.Pmus.Count} PMU(s), TIME_BASE {config.TimeBase.ToString(inv)}, DATA_RATE {config.DataRate.ToString(inv)}" +
        (configChanges > 0
            ? $"; the configuration CHANGED {configChanges} time(s) in the capture: each DATA frame was decoded with the configuration " +
              $"in force when it arrived, and the table lists the {pmuOrder.Count} PMU(s) of every configuration in force"
            : ""));
    // D-DOC-108: the last column counts the PMU's samples dropped by the quality rule (the samples column still counts
    // every decoded sample, so the two together say how much of each PMU was usable).
    Console.WriteLine("  | PMU | IDCODE | phasors | samples | first (UTC) | last (UTC) | freq min Hz | freq max Hz | STAT non-zero | dropped |");
    Console.WriteLine("  |-----|--------|---------|---------|-------------|------------|-------------|-------------|---------------|---------|");
    CliResult? prep = CliOutput.Report;
    prep?.Set("file", path).Set("frames", frames).Set("config_frames", configFrames).Set("data_decoded", dataOk).Set("data_bad_crc", dataCrc)
        .Set("data_malformed", dataMalformed).Set("data_before_config", dataBeforeConfig).Set("other_frames", otherFrames)
        .Set("pmus", pmuOrder.Count).Set("time_base", config.TimeBase).Set("data_rate", config.DataRate)
        .Set("config_changes", configChanges)
        .Set("aligned_instants", aligned.Count).Set("incomplete_instants", incomplete)
        .Set("samples_dropped", droppedSamples).Set("dropped_invalid_data", droppedInvalid)
        .Set("dropped_unsynchronised", droppedUnsync).Set("dropped_unreliable_frame_time", droppedFrameTime);
    // N358 (CF6): only a run with --live-quarantine gains this field, so every other report is unchanged.
    if (quarantineDir is not null) prep?.Set("quarantined_data_frames", quarantinedDataFrames);
    foreach (int idCode in pmuOrder)
    {
        // N260: one row per PMU of any configuration in force; a PMU whose phasor count changed between configurations
        // shows each count it had, in order ("2/3").
        string station = pmuStation[idCode];
        string phasors = string.Join("/", pmuPhasorCounts[idCode].Select(k => k.ToString(inv)));
        var mine = samples.SelectMany(d => d.Blocks.Where(b => b.IdCode == idCode).Select(b => (d.TimeUtc, b))).ToList();
        string first = mine.Count > 0 ? mine.Min(x => x.TimeUtc).ToString("yyyy-MM-ddTHH:mm:ss.ffffffZ", inv) : "-";
        string last = mine.Count > 0 ? mine.Max(x => x.TimeUtc).ToString("yyyy-MM-ddTHH:mm:ss.ffffffZ", inv) : "-";
        string fmin = mine.Count > 0 ? mine.Min(x => x.b.FreqHz).ToString("F4", inv) : "-";
        string fmax = mine.Count > 0 ? mine.Max(x => x.b.FreqHz).ToString("F4", inv) : "-";
        Console.WriteLine($"  | {station} | {idCode} | {phasors} | {mine.Count} | {first} | {last} | {fmin} | {fmax} | {mine.Count(x => x.b.Stat != 0)} | {droppedByPmu.GetValueOrDefault(idCode)} |");
    }
    Console.WriteLine($"  aligned instants: {aligned.Count} ({incomplete} with a PMU missing)");
    Console.WriteLine($"  quality: {droppedSamples} sample(s) dropped and not used ({droppedInvalid} invalid data (STAT bits 15-14), " +
        $"{droppedUnsync} unsynchronised (STAT bit 13, time quality or unlocked time), {droppedFrameTime} with an unreliable frame time (FRACSEC time quality))");

    // D-DOC-107: one gridsim-measurements/1 set per aligned instant, through PmuMeasurementSetMapper (re-referenced
    // angles, R295; the horizon guard again, against the real clock). Never overwrites: a clash gets a -dupN name.
    int setsWritten = 0, setsNoReference = 0, setsEmpty = 0;
    if (channelMap is not null && setsDir is not null)
    {
        try { Directory.CreateDirectory(setsDir); }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"pmu-ingest: cannot create --measurements-dir '{setsDir}': {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
        foreach (GridSim.Core.Synchrophasor.PdcSuperframe sf in aligned)
        {
            MeasurementSet set;
            try
            {
                set = GridSim.Core.Synchrophasor.PmuMeasurementSetMapper.Map(sf, channelMap.Maps, channelMap.BaseMva, channelMap.Case,
                    utcNow: null, angleReference: channelMap.Reference);
            }
            catch (GridSim.Core.Synchrophasor.PmuChannelMapMismatchException ex)
            {
                // D-DOC-008: the map does not fit what a PMU reported at this instant. Every configuration in force was
                // checked above, so this should not happen; if it ever does it is an input error, refused by name (it
                // used to be a raw IndexOutOfRangeException), never counted as a missing reference.
                Console.Error.WriteLine($"pmu-ingest: {channelsPath}: {ex.Message}");
                Environment.ExitCode = 1;
                return;
            }
            catch (InvalidDataException)
            {
                setsNoReference++;   // the reference PMU did not report usably at this instant: no angle can be referenced
                continue;
            }
            if (set.Measurements.Count == 0) { setsEmpty++; continue; }   // no mapped PMU reported usably here
            string file = Path.Combine(setsDir, $"pmu-{sf.TimeUtc.ToString("yyyyMMdd'T'HHmmssfffffff'Z'", inv)}.json");
            _ = set.SaveWithoutOverwrite(file);
            setsWritten++;
        }
        Console.WriteLine($"  measurement sets: {setsWritten} written to {setsDir} ({setsNoReference} instant(s) without a usable " +
            $"reference channel, {setsEmpty} with no mapped PMU; neither is written)");
        prep?.Set("measurement_sets_written", setsWritten).Set("instants_without_reference", setsNoReference).Set("instants_without_mapped_pmu", setsEmpty);
    }

    if (prep is not null)
    {
        // Every phasor of every decoded block, at full precision (rectangular and polar), with its PMU's FREQ, ROCOF, STAT,
        // and (D-DOC-108) the quality verdict: Usable, or why the sample was dropped.
        CliResultTable t = prep.Table("samples", "time_utc", "pmu_idcode", "station", "stat", "freq_hz", "rocof_hz_per_s",
            "phasor", "real", "imag", "magnitude", "angle_deg", "quality");
        for (int i = 0; i < samples.Count; i++)
        {
            GridSim.Core.Synchrophasor.C37118StreamDataFrame d = samples[i];
            for (int bi = 0; bi < d.Blocks.Count; bi++)
            {
                GridSim.Core.Synchrophasor.C37118PmuBlock b = d.Blocks[bi];
                for (int k = 0; k < b.Phasors.Length; k++)
                {
                    GridSim.Core.Synchrophasor.Phasor ph = b.Phasors[k];
                    t.Row(d.TimeUtc.ToString("yyyy-MM-ddTHH:mm:ss.fffffffZ", inv), b.IdCode, b.StationName, (int)b.Stat, b.FreqHz, b.RocofHzPerS,
                        k, ph.Real, ph.Imag, ph.Magnitude, ph.AngleRad * 180.0 / Math.PI, verdicts[i][bi].ToString());
                }
            }
        }
        prep.Complete();
    }
    int bad = dataCrc + dataMalformed + dataBeforeConfig;
    if (bad > 0)
    {
        Console.Error.WriteLine($"pmu-ingest: {bad} DATA frame(s) could not be decoded ({dataCrc} bad CRC, {dataMalformed} malformed, {dataBeforeConfig} before any CONFIG); they are counted, not used.");
        // GR-304: name the frames of another stream, so a capture holding two streams is not mistaken for line noise.
        if (dataWrongStream > 0)
            Console.Error.WriteLine($"pmu-ingest: {dataWrongStream} of the malformed DATA frame(s) carry an IDCODE other than the stream IDCODE of the CONFIG frame in force; capture one stream per file.");
        Environment.ExitCode = 3;
    }
    if (config1Ignored > 0)   // GR-826: informational; the CONFIG-2 in force decoded the data
        Console.Error.WriteLine($"pmu-ingest: {config1Ignored} CONFIG-1 frame(s) arrived while a CONFIG-2 was in force and were not used (CONFIG-2 describes the stream as sent).");
    // D-DOC-108: a dropped sample is data the capture holds but must not be used; the run did not get everything it was
    // given, so it is a validation failure, exit 3 (the same rule as an undecodable frame).
    if (droppedSamples > 0)
    {
        Console.Error.WriteLine($"pmu-ingest: {droppedSamples} PMU sample(s) dropped by the STAT / time-quality rule ({droppedInvalid} invalid data, " +
            $"{droppedUnsync} unsynchronised, {droppedFrameTime} unreliable frame time); they are counted, not used.");
        Environment.ExitCode = 3;
    }
    // D-DOC-107: an instant whose reference channel did not report usably gives no measurement set (its angles cannot be
    // put in the slack frame): evidence the run could not produce, exit 3.
    if (setsNoReference > 0)
    {
        Console.Error.WriteLine($"pmu-ingest: {setsNoReference} aligned instant(s) had no usable reference channel, so no measurement set was written for them.");
        Environment.ExitCode = 3;
    }
    // N340 (CF5): the live transport dropped datagrams that were not one frame, or stopped on its timeout short of the DATA
    // frames asked for: the run did not get everything it asked for, exit 3 (the summary above is still printed).
    if (liveShortfall)
    {
        Console.Error.WriteLine($"pmu-ingest: {path}: the live receive was incomplete (see the live: line); the run is not a full success.");
        Environment.ExitCode = 3;
    }

    // Two configurations describe the same stream when every field the decoder reads is equal.
    static bool SameConfig(GridSim.Core.Synchrophasor.C37118ConfigFrame x, GridSim.Core.Synchrophasor.C37118ConfigFrame y) =>
        x.TimeBase == y.TimeBase && x.Pmus.Count == y.Pmus.Count &&
        x.Pmus.Zip(y.Pmus).All(p => p.First.IdCode == p.Second.IdCode && p.First.Format == p.Second.Format &&
            p.First.PhasorCount == p.Second.PhasorCount && p.First.AnalogCount == p.Second.AnalogCount &&
            p.First.DigitalCount == p.Second.DigitalCount && p.First.Is50Hz == p.Second.Is50Hz &&
            (p.First.PhasorUnits ?? Array.Empty<uint>()).SequenceEqual(p.Second.PhasorUnits ?? Array.Empty<uint>()));
}

void RunFault(List<string> a, string root)
{
    string? arg = AnalysisCasePositional("fault", a);
    int bus = FlagInt(a, "--bus", int.MinValue);
    if (arg is null || bus == int.MinValue)
    {
        Console.Error.WriteLine("usage: gridsim fault <case|case.m|case-dir> --bus <id> [--zf pu] [--type 3ph|slg|ll|dlg]");
        Environment.ExitCode = 2; return;
    }
    double zf = FlagDouble(a, "--zf", 0.0);
    // D-DOC-089 (October 2026): --zf is the fault REACTANCE (Zf = j zf, pu; D-DOC-166: dist3ph's --zf is a resistance,
    // so the header below prints the j). A negative or non-finite value is refused as protection-check --zf already
    // refused it (usage error, exit 2); fault used to take it and exit 0 (`fault case9 --bus 5 --zf -0.1` printed a
    // faulted-bus voltage of 2.776 pu, a series resonance with the negative reactance, not a fault).
    if (!(zf >= 0.0) || !double.IsFinite(zf))
        FailFlag<double>("--zf", zf.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a finite fault reactance of 0 pu or more (Zf = j zf)");
    // F21 (October 2026): --type slg|ll|dlg runs the unbalanced fault on the three sequence networks
    // (FaultAnalysis.Unbalanced); 3ph (the default) is the balanced study below, unchanged.
    string ftype = (FlagString(a, "--type") ?? "3ph").ToLowerInvariant();
    if (ftype is not ("3ph" or "slg" or "ll" or "dlg")) FailFlag<string>("--type", ftype, "3ph, slg, ll or dlg");

    GridModel m;
    try
    {
        // D-DOC-151: LoadCaseArgument (the same three branches, plus the folder fallback: an existing folder that is
        // not a known name loads as a case folder, so the loader names what is wrong instead of "unknown case").
        m = LoadCaseArgument(arg, root);
    }
    catch (Exception ex) { Console.Error.WriteLine($"error loading case '{arg}': {ex.Message}"); Environment.ExitCode = CliExit.CaseLoadFailure(ex); return; }

    // D-DOC-159 (one rule for an unknown bus on every verb): a --bus that is not a bus of the case is a flag value that
    // names nothing in it, a usage error, exit 2, naming the bus and the case. fault used to find out inside the fault
    // study and exit 1 with the C# parameter name leaking ("(Parameter 'faultBusId')"), while protection-check
    // --fault-bus, iec60909 --bus, harmonics --bus and chain --bess already exited 2. Checked before the prefault solve,
    // so nothing is solved for a bus that is not there.
    if (!m.Buses.Any(b => b.Id == bus))
    {
        Console.Error.WriteLine($"error: fault: fault bus {bus} is not in case '{m.Name}'.");
        Environment.ExitCode = CliExit.Usage;
        return;
    }

    var opt = new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true };
    IPowerFlowSolver solver = backend.Solver(m);
    PowerFlowResult prefault = solver.Solve(m, opt);
    if (!prefault.Converged)   // R023: never fault a non-converged prefault state
    {
        Console.Error.WriteLine($"fault: the pre-fault power flow did not converge ({prefault.Status}, mismatch {prefault.MaxMismatch:E2}); no fault study is possible.");
        Environment.ExitCode = 3;
        return;
    }

    if (ftype != "3ph")
    {
        RunUnbalancedFault(m, arg, prefault, bus, zf, ftype);
        return;
    }

    GridSim.Core.Protection.FaultResult fault;
    try { fault = GridSim.Core.Protection.FaultAnalysis.ThreePhase(m, prefault, bus, zf); }
    catch (Exception ex) { Console.Error.WriteLine($"fault analysis: {CliExit.UserMessage(ex)}"); Environment.ExitCode = CliExit.InputError; return; }   // D-DOC-159: no C# parameter name in the message

    string ka = fault.FaultCurrentKa > 0 ? $" ({fault.FaultCurrentKa:F2} kA)" : "";
    Console.WriteLine($"Balanced three-phase fault  -  {arg}  bus {bus}  Zf=j{zf:F3} pu");   // D-DOC-166: a reactance (Zf = j zf)
    Console.WriteLine($"  fault current: {fault.FaultCurrentPu:F2} pu{ka}   Thevenin Z: {fault.TheveninZPu:F4} pu   "
        + $"faulted bus voltage: {fault.State.Vm[Array.IndexOf(fault.State.BusIds.ToArray(), bus)]:F3} pu");
    Console.WriteLine($"  (generator subtransient reactance synthesised at {GridSim.Core.Protection.FaultAnalysis.DefaultSubtransientXdPu:F2} pu; positive-sequence, so three-phase only)");
    if (fault.Converters is { Count: > 0 } conv)
    {
        int atLimit = conv.Count(c => c.AtCurrentLimit);
        double convPu = conv.Sum(c => c.CurrentPu);
        Console.WriteLine($"  converter-interfaced units: {conv.Count} (current-limited, K={GridSim.Core.Protection.FaultAnalysis.DefaultConverterReactiveGain:F1} "
            + $"reactive priority)  total infeed {convPu:F2} pu, {atLimit} at current limit"
            + (fault.ConvertersConverged ? "" : "   WARNING: converter current iteration did not converge"));
        // D-DOC-013: a converter current iteration that did not settle leaves the faulted state unreliable. fault printed
        // the WARNING above and still exited 0; protection-check --fault-bus already failed the same state with exit 3.
        // Same rule here: the study and the relays below are still printed, for diagnosis, and the run exits 3.
        if (!fault.ConvertersConverged)
        {
            Console.Error.WriteLine("fault: the converter current iteration of the fault study did not converge; the faulted state is not reliable. Exit 3.");
            Environment.ExitCode = 3;   // CliExit.Verdict, written as the literal 3 that CliExitCodeContractTests reads
        }
    }

    // Since 1.95.304 a faulted state whose converter current iteration did not converge is marked not converged, and
    // ProtectionAssessment.Assess refuses it (the convergence contract): the relays used to be assessed on it anyway and
    // printed "for diagnosis". It is not a network state, so no relay verdict is computed from it; the study above is
    // still printed and the run exits 3 (set above). Without this the refusal escaped as an unhandled crash.
    if (!fault.ConvertersConverged)
    {
        Console.WriteLine("  relays: not assessed (the faulted state did not converge, so no relay verdict can be computed from it)");
        Environment.ExitCode = 3;
        return;
    }
    GridSim.Core.Protection.ProtectionReport rep = GridSim.Core.Protection.ProtectionAssessment.Assess(
        m, fault.State, null, null, fault.DifferentialCurrentPuByBus);

    var operating = rep.Operating;
    Console.WriteLine($"  relays operating on the faulted state: {operating.Count}");
    Console.WriteLine("  | device | function | location | quantity | pickup | time | basis |");
    Console.WriteLine("  |--------|----------|----------|----------|--------|------|-------|");
    foreach (GridSim.Core.Protection.RelayVerdict v in operating)
    {
        string t = v.TimeToTripS is { } ts ? (ts <= 0 ? "inst" : $"{ts:F2}s") : "-";
        Console.WriteLine($"  | {v.Device} | {v.Function} | {v.LocationName} | {v.Quantity:F3} {v.Unit} | {v.Pickup:F3} | {t} | {v.Basis} |");
    }
    Console.WriteLine();
    Console.WriteLine($"PROTECTION SIMULATION: a three-phase fault at bus {bus} would drive {operating.Count} relay operation(s)"
        + PrimaryClearanceText(rep));
    // F10: the fault study at full precision, the converter infeeds and every operating relay.
    CliResult? frep = CliOutput.Report;
    if (frep is not null)
    {
        frep.Set("case", arg).Set("buses", m.BusCount).Set("bus", bus).Set("zf_pu", zf)
            .Set("fault_current_pu", fault.FaultCurrentPu).Set("fault_current_ka", fault.FaultCurrentKa).Set("thevenin_z_pu", fault.TheveninZPu)
            .Set("faulted_bus_vm_pu", fault.State.Vm[Array.IndexOf(fault.State.BusIds.ToArray(), bus)])
            .Set("subtransient_xd_pu", GridSim.Core.Protection.FaultAnalysis.DefaultSubtransientXdPu)
            .Set("converters_converged", fault.ConvertersConverged).Set("relays_operating", operating.Count);
        RelayVerdictTable(frep, "relays", operating);
        CliResultTable convTable = frep.Table("converters", "bus", "name", "terminal_voltage_pu", "current_pu", "current_per_rated", "at_current_limit");
        foreach (GridSim.Core.Protection.ConverterFaultInfeed c in fault.Converters ?? Array.Empty<GridSim.Core.Protection.ConverterFaultInfeed>())
            convTable.Row(c.Bus, c.Name, c.TerminalVoltagePu, c.CurrentPu, c.CurrentPerRated, c.AtCurrentLimit);
        frep.Complete();
    }
}

// F21 (October 2026): the fault verb's unbalanced study (single line to ground, line to line, double line to ground) on
// the three sequence networks, with the protection overlay: the phase elements on the faulted positive-sequence state,
// the earth-fault (50N / 51N / 21N) and negative-sequence (46) elements on the sequence currents.
void RunUnbalancedFault(GridModel m, string arg, PowerFlowResult prefault, int bus, double zf, string ftype)
{
    GridSim.Core.Protection.FaultType type = ftype switch
    {
        "slg" => GridSim.Core.Protection.FaultType.SingleLineToGround,
        "ll" => GridSim.Core.Protection.FaultType.LineToLine,
        _ => GridSim.Core.Protection.FaultType.DoubleLineToGround,
    };
    GridSim.Core.Protection.UnbalancedFaultResult uf;
    GridSim.Core.Protection.ProtectionReport rep;
    try { (uf, rep) = GridSim.Core.Protection.ProtectionAssessment.AssessUnbalancedFault(m, prefault, bus, type, zf); }
    catch (Exception ex) { Console.Error.WriteLine($"fault analysis: {CliExit.UserMessage(ex)}"); Environment.ExitCode = CliExit.InputError; return; }   // D-DOC-159: no C# parameter name in the message

    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string label = type switch
    {
        GridSim.Core.Protection.FaultType.SingleLineToGround => "Single line to ground (phase a)",
        GridSim.Core.Protection.FaultType.LineToLine => "Line to line (phases b-c)",
        _ => "Double line to ground (phases b-c-earth)",
    };
    string Ka(double pu) => uf.BaseKv > 0 ? $" ({uf.ToKa(pu, m.BaseMva):F3} kA)" : "";
    (double va, double vb, double vc) = uf.FaultBusPhaseVoltages();
    Console.WriteLine($"{label} fault  -  {arg}  bus {bus}  Zf=j{zf:F3} pu");   // D-DOC-166: a reactance (Zf = j zf)
    Console.WriteLine($"  phase currents: Ia {uf.PhaseAPu:F3} pu{Ka(uf.PhaseAPu)}  Ib {uf.PhaseBPu:F3} pu{Ka(uf.PhaseBPu)}  Ic {uf.PhaseCPu:F3} pu{Ka(uf.PhaseCPu)}");
    Console.WriteLine($"  earth current |3I0|: {uf.EarthCurrentPu:F3} pu{Ka(uf.EarthCurrentPu)}   sequence |I1| {uf.I1.Magnitude:F3}  |I2| {uf.I2.Magnitude:F3}  |I0| {uf.I0.Magnitude:F3} pu");
    Console.WriteLine($"  faulted bus phase voltages: Va {va:F3}  Vb {vb:F3}  Vc {vc:F3} pu");
    Console.WriteLine($"  driving-point Z1 {uf.Z1Pu.Real.ToString("F4", inv)}+j{uf.Z1Pu.Imaginary.ToString("F4", inv)}  Z2 {uf.Z2Pu.Real.ToString("F4", inv)}+j{uf.Z2Pu.Imaginary.ToString("F4", inv)}  Z0 "
        + (uf.FaultBusGrounded ? $"{uf.Z0Pu.Real.ToString("F4", inv)}+j{uf.Z0Pu.Imaginary.ToString("F4", inv)} pu" : "infinite (no earth path in the zero sequence)"));
    if (!uf.FaultBusGrounded && type != GridSim.Core.Protection.FaultType.LineToLine)
        Console.WriteLine("  the fault bus reaches no earthed neutral in the zero sequence: no earth current can flow"
            + (type == GridSim.Core.Protection.FaultType.DoubleLineToGround ? " (the fault is solved as line to line)." : "."));
    // Fail loud on missing data: a model with no transformer winding connection anywhere (MATPOWER and JSON v1 cannot
    // hold them) has no earthed neutral at all, so a zero earth current reflects the missing data, not the network.
    bool noEarthingData = type != GridSim.Core.Protection.FaultType.LineToLine && !m.Branches.Any(b => b.FromWinding is not null || b.ToWinding is not null);
    if (noEarthingData)
        Console.Error.WriteLine("fault: the model carries no transformer winding connections at all (MATPOWER and JSON v1 cannot hold them), so it "
            + "has no earthed neutral and no earth-fault current can be computed from it; the result above reflects missing data. Exit 3.");
    Console.WriteLine($"  (generator X''d synthesised at {GridSim.Core.Protection.FaultAnalysis.DefaultSubtransientXdPu:F2} pu where not supplied, X2 = X''d where not supplied; "
        + "line Z0 = 3 x Z1 where not supplied; loads neglected in the zero sequence; converter units keep their prefault current)");
    ConvertersWithoutInfeedNote(uf);
    var operating = rep.Operating;
    Console.WriteLine($"  relays operating on the faulted state: {operating.Count} (phase elements on the phase currents and voltages; 50N/51N/21N/46 on the sequence currents)");
    Console.WriteLine("  | device | function | location | quantity | pickup | time | basis |");
    Console.WriteLine("  |--------|----------|----------|----------|--------|------|-------|");
    foreach (GridSim.Core.Protection.RelayVerdict v in operating)
    {
        string t = v.TimeToTripS is { } ts ? (ts <= 0 ? "inst" : $"{ts:F2}s") : "-";
        Console.WriteLine($"  | {v.Device} | {v.Function} | {v.LocationName} | {v.Quantity:F3} {v.Unit} | {v.Pickup:F3} | {t} | {v.Basis} |");
    }
    Console.WriteLine();
    Console.WriteLine($"PROTECTION SIMULATION: a {label.ToLowerInvariant()} fault at bus {bus} would drive {operating.Count} relay operation(s)"
        + PrimaryClearanceText(rep));
    CliResult? frep = CliOutput.Report;
    if (frep is not null)
    {
        frep.Set("case", arg).Set("buses", m.BusCount).Set("bus", bus).Set("type", ftype).Set("zf_pu", zf)
            .Set("phase_a_pu", uf.PhaseAPu).Set("phase_b_pu", uf.PhaseBPu).Set("phase_c_pu", uf.PhaseCPu)
            .Set("phase_a_ka", uf.ToKa(uf.PhaseAPu, m.BaseMva)).Set("phase_b_ka", uf.ToKa(uf.PhaseBPu, m.BaseMva)).Set("phase_c_ka", uf.ToKa(uf.PhaseCPu, m.BaseMva))
            .Set("earth_current_pu", uf.EarthCurrentPu).Set("earth_current_ka", uf.ToKa(uf.EarthCurrentPu, m.BaseMva))
            .Set("i1_pu", uf.I1.Magnitude).Set("i2_pu", uf.I2.Magnitude).Set("i0_pu", uf.I0.Magnitude)
            .Set("fault_bus_grounded", uf.FaultBusGrounded).Set("va_pu", va).Set("vb_pu", vb).Set("vc_pu", vc)
            .Set("relays_operating", operating.Count)
            .Set("converters_without_fault_infeed", uf.ConvertersWithoutFaultInfeed.Count)
            .Set("converters_without_fault_infeed_mva", uf.ConvertersWithoutFaultInfeed.Sum(c => c.RatedMva));
        RelayVerdictTable(frep, "relays", operating);
        CliResultTable bt = frep.Table("branches", "index", "name", "from", "to", "max_phase_from_pu", "max_phase_to_pu",
            "residual_from_pu", "residual_to_pu", "negative_sequence_from_pu", "negative_sequence_to_pu");
        foreach (GridSim.Core.Protection.BranchSequenceCurrents b in uf.Branches)
            bt.Row(b.Index, b.Name, b.From, b.To, b.MaxPhaseFromPu, b.MaxPhaseToPu, b.ResidualFromPu, b.ResidualToPu, b.NegativeSequenceFromPu, b.NegativeSequenceToPu);
        frep.Set("earthing_data", !noEarthingData);
        frep.Complete();
    }
    if (noEarthingData) Environment.ExitCode = 3;
}

// D-DOC-158 (October 2026): the end of the fault summary line. "Primary clearance" is ProtectionReport.PrimaryClearance:
// the faulted busbar's differential (87, instantaneous unit protection) when it operates, else the fastest operating
// BRANCH element with an operating time (50 / 51 / 21 zones / 49 / 50N / 51N / 21N zones / 46). It used to be whatever row headed the list sorted by raw margin, whose unit differs
// per element, so `fault uk --bus 1` named Moyle reverse power (a generator element, in MW) as the primary clearance.
// When no timed branch element operates, the line says so instead of naming a non-clearing element.
// D-DOC-097 (October 2026): the note after "Ik = ..." in iec60909, saying which IEC 60909-0 rule the steady-state current
// follows. Nothing is printed far from every generator (Ik = Ik'' exactly, as before).
static string SteadyBasisNote(GridSim.Core.Protection.ShortCircuit.SteadyStateBasis basis) => basis switch
{
    GridSim.Core.Protection.ShortCircuit.SteadyStateBasis.MeshedMultipleFed =>
        "  (near a generator, fed from several sources: IEC 60909-0 Ik = Ik''M, the initial current without motors; no motors are modelled)",
    GridSim.Core.Protection.ShortCircuit.SteadyStateBasis.SingleFedUpperBound =>
        "  (UPPER BOUND: single-fed near a generator, the standard's Ik = lambda x IrG needs the machine's x_dsat, which the model does not carry; Ith with n = 1 is an upper bound too)",
    GridSim.Core.Protection.ShortCircuit.SteadyStateBasis.UnbalancedNoDecay =>
        "  (unbalanced fault: IEC 60909-0 takes no decay, Ik = Ib = Ik'')",
    _ => "",
};

static string PrimaryClearanceText(GridSim.Core.Protection.ProtectionReport rep)
{
    if (rep.Operating.Count == 0) return ".";
    GridSim.Core.Protection.RelayVerdict? p = rep.PrimaryClearance;
    if (p is null) return " - no branch element with an operating time picks up (no circuit is cleared by the elements above).";
    string t = p.TimeToTripS is { } ts && ts > 0 ? $"{ts:F2} s" : "instantaneously";
    return $" - primary clearance by {p.Device} ({p.Function}) on {p.LocationName}, {t}.";
}

// N118 (October 2026): say plainly, when the model has converter-interfaced units, that the unbalanced study gives them
// no fault infeed (the model defines no negative- or zero-sequence fault behaviour for them), so the fault currents
// printed leave their contribution out. Printed on stdout with the study it qualifies.
static void ConvertersWithoutInfeedNote(GridSim.Core.Protection.UnbalancedFaultResult uf)
{
    if (uf.ConvertersWithoutFaultInfeed.Count == 0) return;
    double mva = uf.ConvertersWithoutFaultInfeed.Sum(c => c.RatedMva);
    Console.WriteLine($"  note: {uf.ConvertersWithoutFaultInfeed.Count} converter-interfaced unit(s) ({mva.ToString("N1", System.Globalization.CultureInfo.InvariantCulture)} MVA rated) "
        + "add no fault current in this study: the model defines no negative- or zero-sequence fault behaviour for them, so they stay at their "
        + "prefault current in all three sequence networks and the currents above leave their contribution out (the 3ph study models their "
        + "positive-sequence fast fault current).");
}

void RunSimdCheck(GridSim.Core.Numerics.SimdTier? expect)
{
    void Line(string s) { Console.WriteLine(s); Console.Out.Flush(); }
    Line("GridSim SIMD preflight");
    Line("======================");
    Line($"CPU cores: {Environment.ProcessorCount}   OS: {System.Runtime.InteropServices.RuntimeInformation.OSDescription}");
    Line($"process arch: {System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture}");
    Line($"commit: {RunInfo.GitCommit}");
    Line("");
    Line(GridSim.Core.Numerics.SimdCapabilities.Describe());
    Line("");
    Line($"Active vector tier: {GridSim.Core.Numerics.SimdCapabilities.Tier} "
       + $"({GridSim.Core.Numerics.SimdCapabilities.DoubleLanes} doubles per vector step)");
    Line("Dense-LU / normal-equations / covariance kernels dispatch to this width at run time.");
    Line("If this reports Avx256 on a box you expect to be AVX-512, the CPU or the runtime is capping the width.");

    // R102: say plainly when the CPU has AVX-512 that the runtime is not using (the Skylake-SP / Cascade Lake default).
    if (GridSim.Core.Numerics.SimdCapabilities.Avx512Unused)
        Line("WARNING: this CPU supports AVX-512F but the active tier is narrower. Set DOTNET_PreferredVectorBitWidth=512 "
           + "before starting GridSim to use the 8-wide kernels.");
    if (expect is { } want)
    {
        var have = GridSim.Core.Numerics.SimdCapabilities.Tier;
        if (have < want)
        {
            Console.Error.WriteLine($"simdcheck: FAILED - expected at least {want}, but the active tier is {have}.");
            Environment.ExitCode = 3;
        }
        else Line($"simdcheck: OK - active tier {have} meets the expected {want}.");
    }
}

void RunGpuCheck()
{
    void Line(string s) { Console.WriteLine(s); Console.Out.Flush(); }
    Line("GridSim GPU preflight");
    Line("=====================");
    Line($"CPU cores: {Environment.ProcessorCount}   OS: {System.Runtime.InteropServices.RuntimeInformation.OSDescription}");
    Line($"commit: {RunInfo.GitCommit}");
    Line("");

    // D-DOC-011: every probe that ran and failed (a FAIL line: the solver threw; or a solve that ran but did not converge)
    // is tallied, and the preflight ends with exit 3 naming them. It used to print the FAIL line and exit 0, so a script
    // or CI step gating on gpucheck passed on a broken backend. A backend that is not present is skipped, not failed: the
    // preflight's job is to prove that what is there works (exit 0 on a machine with no GPU, as before).
    var tally = new FailureTally();
    Probe("CPU", SolverBackend.Select("cpu"));
    Probe("ROCm", SolverBackend.Select("rocm"));
    Probe("OpenCL", SolverBackend.Select("opencl"));
    Probe("CUDA", SolverBackend.Select("cuda"));
    Line("Preflight done. A FAIL line names the failing call; if the process died mid-line, that call");
    Line("segfaulted (a P/Invoke signature mismatch) - send that last line and I'll fix the binding.");
    Line(tally.ExitCode == CliExit.Ok
        ? "gpucheck: OK - every probe that ran passed (absent backends are skipped, not failed)."
        : "gpucheck: FAILED - see the summary on stderr.");
    foreach (string l in tally.SummaryLines("gpucheck")) Console.Error.WriteLine(l);
    Environment.ExitCode = tally.ExitCode;

    void Probe(string label, SolverBackend b)
    {
        Line($"[{label}] {b.Description}   (vendor={b.Device})");
        if (label == "CUDA") Line($"[CUDA] raw probe: {GridSim.Gpu.GpuContext.DeviceDescription}");
        if (label == "OpenCL") Line($"[OpenCL] raw probe: {GridSim.Gpu.GpuContext.OpenClDescription}");
        if (label == "ROCm") Line($"[ROCm] raw probe: {GridSim.Gpu.RocmContext.DeviceDescription}");
        if (label != "CPU" && b.Device == SolverBackend.Vendor.Cpu)
        {
            Line($"[{label}]   not present - skipped."); Line(""); return;
        }
        TinySolve($"{label} dense", b.DenseSolver);
        TinySolve($"{label} sparse", b.SparseSolver);
        Line("");
    }

    void TinySolve(string what, Func<IPowerFlowSolver> make)
    {
        try
        {
            Console.Write($"  {what}: build solver... "); Console.Out.Flush();
            IPowerFlowSolver s = make();
            Console.Write("solve case9... "); Console.Out.Flush();
            var sw = System.Diagnostics.Stopwatch.StartNew();
            PowerFlowResult r = s.Solve(IeeeCases.Case9(), new PowerFlowOptions { MaxIterations = 50, EnforceQLimits = false });
            sw.Stop();
            Line(r.Converged
                ? $"PASS  ({r.Iterations} it, {sw.Elapsed.TotalMilliseconds:F1} ms, |mis|={r.MaxMismatch:E1})"
                : $"ran but NOT converged ({r.Iterations} it, |mis|={r.MaxMismatch:E1})");
            if (!r.Converged) tally.RunFailed($"{what} did not converge on case9");
        }
        catch (Exception ex)
        {
            Line($"FAIL  {ex.GetType().Name}: {ex.Message.Replace('\n', ' ')}");
            tally.RunFailed($"{what} threw {ex.GetType().Name}");
        }
    }
}

// bench --estimate [--runs N] [--cases case14,case118,...] [<case-dir> ...]
//   Times the WLS state estimator per case per step backend (dense vs sparse, forced via
//   SparseBusThreshold) on a fixed-seed synthetic noisy set. Sampling and the truth solve sit
//   OUTSIDE the timed region, so the number is the estimator alone (gate + iterations + chi2 +
//   covariance). This is the instrument the A-2 sparse-performance work is measured with.
void RunBenchEstimate(List<string> a, int runs, string root)
{
    string casesArg = FlagString(a, "--cases") ?? "case14,case30,case57,case118,case300";
    var labels = casesArg.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList();
    labels.AddRange(Positionals(a).Skip(1).Where(p => Directory.Exists(p) && File.Exists(Path.Combine(p, "system.json"))));

    string outDir = DefaultResultsPath("bench-estimate");   // N079: under results/ in the current directory
    CliFiles.OutputFolder(outDir, "output folder");   // D-DOC-072: refused if it is an existing file
    RunInfo.WriteJson(CliFiles.Output(Path.Combine(outDir, "run-metadata.json"), "run metadata"), "bench --estimate");   // GR-692
    using var csv = new StreamWriter(CliFiles.Output(Path.Combine(outDir, "bench-estimate.csv"), "bench-estimate.csv"));
    csv.WriteLine("case,buses,measurements,states,backend,converged,iterations,mean_ms,runs,commit");

    Console.WriteLine("GridSim - WLS estimation benchmark");
    Console.WriteLine($"| {"case",-12} | {"buses",5} | {"meas",6} | {"backend",-7} | {"iters",5} | {"mean ms",9} |");
    Console.WriteLine($"|{new string('-', 14)}|{new string('-', 7)}|{new string('-', 8)}|{new string('-', 9)}|{new string('-', 7)}|{new string('-', 11)}|");

    // D-DOC-012 (bench --estimate): as in bench, a case that does not load, a truth solve that does not converge, or an
    // estimate that does not converge is tallied; the run still covers every case and ends with exit 1 (a load failure)
    // or 3 (a failed solve or estimate) instead of exit 0.
    var estTally = new FailureTally();
    foreach (string label in labels)
    {
        GridModel model;
        try
        {
            model = Directory.Exists(label) ? Gated.Dir(label) : LoadNamed(label, root);
        }
        catch (Exception ex) { Console.Error.WriteLine($"  [skip] {label}: {ex.Message}"); estTally.LoadFailed(label); continue; }

        IPowerFlowSolver raw = backend.Solver(model);
        PowerFlowResult truth = raw.Solve(model, new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = true });
        if (!truth.Converged) { Console.Error.WriteLine($"  [skip] {label}: truth solve {truth.Status}"); estTally.RunFailed($"{label}: truth solve {truth.Status}"); continue; }
        MeasurementSet set = SyntheticMeasurements.Sample(model, truth);

        string caseLabel = Path.GetFileName(label.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
        foreach ((string name, int threshold) in new[] { ("dense", int.MaxValue), ("sparse", 0) })
        {
            // Dense at very large scale is exactly the wall the sparse backend exists for; skip it.
            // routing-exempt: bench --estimate times BOTH estimator backends on purpose; this only skips an infeasible dense run.
            if (name == "dense" && model.BusCount > 1500) continue;
            var opt = new EstimationOptions { SparseBusThreshold = threshold };
            var est = new WlsStateEstimator();

            EstimationResult r = est.Estimate(model, set, opt);   // warm-up (JIT, allocations)
            int n = model.BusCount > 1000 ? Math.Max(1, runs / 3) : runs;
            var sw = System.Diagnostics.Stopwatch.StartNew();
            for (int k = 0; k < n; k++) r = est.Estimate(model, set, opt);
            sw.Stop();
            double meanMs = sw.Elapsed.TotalMilliseconds / n;

            Console.WriteLine($"| {caseLabel,-12} | {model.BusCount,5} | {set.Measurements.Count,6} | {name,-7} | {r.Iterations,5} | {meanMs,9:F1} |");
            csv.WriteLine($"{caseLabel},{model.BusCount},{set.Measurements.Count},{r.Observability.StateSize},{name},{r.Converged},{r.Iterations},{meanMs:F2},{n},{RunInfo.GitCommit}");
            if (!r.Converged) estTally.RunFailed($"{caseLabel} {name}: estimate {r.Status}");
        }
    }
    Console.WriteLine($"\n  -> {Path.GetFullPath(outDir)}");
    foreach (string l in estTally.SummaryLines("bench --estimate")) Console.Error.WriteLine(l);
    Environment.ExitCode = estTally.ExitCode;
}

// A focused, diffable micro-benchmark for exactly the paths the performance-opportunity programme
// touches: sparse-NR end-to-end (wall + managed allocations), the fault study's
// pre-solve/solve split at the dense cap, the OLTC outer loop, and the many-order harmonic scan. It is
// deliberately single-threaded and deterministic so before/after runs diff cleanly (keyed by commit).
void RunPerfBench(List<string> rest, int runs, string? outPath, string root, string? note)
{
    outPath ??= DefaultResultsPath("perf-baseline.md");   // N079: was docs/developer/benchmarks/perf-baseline.md; --out docs/developer/benchmarks/perf-baseline.md refreshes the committed copy
    // D-DOC-072: the report and its CSV through the one output policy (CliFiles creates the folder).
    using var file = new StreamWriter(CliFiles.Output(outPath, "report")) { AutoFlush = true };
    using var csv = new StreamWriter(CliFiles.Output(Path.ChangeExtension(outPath, ".csv"), "report CSV")) { AutoFlush = true };
    void Emit(string line) { Console.WriteLine(line); file.WriteLine(line); }

    string desc = $"perf-baseline  runs={runs}" + (string.IsNullOrWhiteSpace(note) ? "" : $"  note=\"{note}\"");
    foreach (string h in RunInfo.HeaderLines(desc)) Emit("    " + h);
    Emit("");
    Emit("Focused before/after yardstick for the performance programme. Single-threaded, warmed,");
    Emit("median of N runs. Allocations are managed bytes on the measuring thread.");
    Emit("");
    Emit("| Path | Case | Buses | metric | value |");
    Emit("|------|------|------:|--------|------:|");
    csv.WriteLine("path,case,buses,metric,value,runs,commit");

    // (median ms, allocated bytes/run) for an action, warmed once.
    (double MedMs, long Bytes) Time(Action act)
    {
        act(); // warm-up: JIT + first-touch allocations
        var samples = new double[runs];
        long before = GC.GetAllocatedBytesForCurrentThread();
        for (int k = 0; k < runs; k++)
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            act();
            sw.Stop();
            samples[k] = sw.Elapsed.TotalMilliseconds;
        }
        long after = GC.GetAllocatedBytesForCurrentThread();
        Array.Sort(samples);
        return (samples[runs / 2], (after - before) / runs);
    }
    void Row(string path, string caseLabel, int buses, string metric, double value, string fmt = "F3")
    {
        Emit($"| {path} | {caseLabel} | {buses} | {metric} | {value.ToString(fmt)} |");
        csv.WriteLine($"{path},{caseLabel},{buses},{metric},{value:F4},{runs},{RunInfo.GitCommit}");
    }

    var pfOpt = new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = false };

    // 1. Sparse Newton-Raphson end-to-end: wall + per-solve managed allocations (the §2/§3 target).
    foreach ((string label, GridModel model) in new[]
             { ("case118", IeeeCases.Case118()), ("case300", IeeeCases.Case300()) })
    {
        // routing-exempt: bench --perf measures the SPARSE engine itself, so it names that engine on purpose.
        var nr = new SparseNewtonRaphsonPowerFlow();
        (double ms, long bytes) = Time(() => nr.Solve(model, pfOpt));
        Row("sparse-nr", label, model.BusCount, "median_ms", ms);
        Row("sparse-nr", label, model.BusCount, "alloc_kb", bytes / 1024.0, "F1");
    }

    // 2. Fault study at a mid case - the target of sections 1 and 5. What is timed is the fault study; the prefault state comes
    // from the sparse engine, which is bit-identical to the dense one on the CPU, so the state is the same either way.
    {
        GridModel model = IeeeCases.Case300();
        // routing-exempt: a fixed engine keeps the bench --perf baseline comparable run to run (same code path timed).
        PowerFlowResult pre = new SparseNewtonRaphsonPowerFlow().Solve(model, pfOpt);
        int faultBus = model.Buses[0].Id;
        (double ms, long bytes) = Time(() =>
            GridSim.Core.Protection.FaultAnalysis.ThreePhase(model, pre, faultBus));
        Row("fault-study", "case300", model.BusCount, "median_ms", ms);
        Row("fault-study", "case300", model.BusCount, "alloc_kb", bytes / 1024.0, "F1");
    }

    // 3. OLTC outer loop overhead on a transformer-rich case - the §4 target.
    {
        GridModel model = IeeeCases.Case118();
        var oltc = new SteadyStateSolver();
        (double ms, long bytes) = Time(() => oltc.Solve(model, pfOpt));
        Row("oltc-loop", "case118", model.BusCount, "median_ms", ms);
        Row("oltc-loop", "case118", model.BusCount, "alloc_kb", bytes / 1024.0, "F1");
    }

    // 4. Many-order harmonic penetration scan (24 same-pattern builds + factorizations) - the §D target.
    {
        GridModel model = IeeeCases.Case118();
        var sources = new[] { HarmonicSourceLibrary.Make("6-pulse", model.Buses[4].Id, 0.8) };
        (double ms, long bytes) = Time(() => HarmonicPenetration.Solve(model, sources));
        Row("harmonic-scan", "case118", model.BusCount, "median_ms", ms);
        Row("harmonic-scan", "case118", model.BusCount, "alloc_kb", bytes / 1024.0, "F1");
    }

    Emit("");
    Emit($"-> {Path.GetFullPath(outPath)}");
}

void RunBench(int runs, int parallel, string? outPath, string root, string? gpuVendorSpec, string? note, string? casesArg)
{
    // D-DOC-012: the bench used to exit 0 whatever happened (a LOAD FAIL row, a solve that did not converge, an engine
    // that threw). Every such cell is now tallied, the run still completes its whole matrix and report, and it ends with
    // the batch verbs' code: exit 1 when any case could not be loaded, otherwise exit 3 when any solve did not converge or
    // failed (manual ch. 19). "n/a" cells (the radial sweep on a meshed case) and GPU size skips are not failures.
    var benchTally = new FailureTally();
    int dop = parallel <= 0 ? Environment.ProcessorCount : parallel;
    const int GpuBusCap = 3000;   // FP64 on a consumer GPU is slow; don't sink hours into giants

    // GR-689: a --cases list that names no case is refused before any report file is created (it used to leave empty
    // report files behind; the check below the case list then refused it).
    if (casesArg is not null && casesArg.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Length == 0)
        FailFlag<string>("--cases", casesArg, "a comma list of at least one case");
    outPath ??= DefaultResultsPath("benchmark-results.md");   // N079: was docs/developer/benchmarks/benchmark-results.md; --out docs/developer/benchmarks/benchmark-results.md refreshes the committed copy
    // D-DOC-072: every output goes through the one policy (CliFiles): parent folder created, never an input of the run.
    using var file = CliFiles.CreateText(outPath, "bench report");
    using var csv = CliFiles.CreateText(Path.ChangeExtension(outPath, ".csv"), "bench CSV");
    file.AutoFlush = true;
    csv.AutoFlush = true;
    var gate = new object();
    void Emit(string line) { Console.WriteLine(line); file.WriteLine(line); }

    // D-DOC-058 (October 2026, docs-session finding): which GPU vendors this bench probes. The bench used to turn any
    // --gpu into "probe all three" (it was told only that a GPU was asked for), so --gpu=cuda also benched ROCm and
    // OpenCL devices, and --gpu=cpu benched every GPU. Now the global switch means what it says, as it does for every
    // other verb (SolverBackend.Select): --gpu or --gpu=auto probes every vendor (ROCm, OpenCL, CUDA), --gpu=rocm,
    // --gpu=opencl or --gpu=cuda probes that vendor only, and --gpu=cpu (or no --gpu) adds no GPU engine. The spec was
    // checked against the known names at parse time (R222), so nothing else reaches here.
    string? vendor = gpuVendorSpec?.Trim().ToLowerInvariant();
    bool wantRocm = vendor is "" or "auto" or "rocm";
    bool wantOpenCl = vendor is "" or "auto" or "opencl";
    bool wantCuda = vendor is "" or "auto" or "cuda";
    bool includeGpu = wantRocm || wantOpenCl || wantCuda;

    // D-DOC-012: --cases a,b,c benches just those cases (any case argument: a built-in name, a .m file, a case folder), in
    // the order given, instead of the whole archive (the default, unchanged). It is what makes a bench run small enough to
    // check its exit code, and to time one case before and after a change. A name that does not load is a LOAD FAIL row
    // like any other (exit 1 at the end), the batch rule.
    var cases = casesArg is null
        ? BuildCases(root).OrderBy(c => c.SortKey).ThenBy(c => c.Label, StringComparer.Ordinal).ToList()   // GR-678
        : casesArg.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select((label, i) => (Label: label, Load: (Func<GridModel>)(() => LoadCaseArgument(label, root)), SortKey: i))
            .ToList();
    if (cases.Count == 0) FailFlag<string>("--cases", casesArg ?? "", "a comma list of at least one case");

    // Every engine x every available backend. CPU is always present; CUDA/ROCm are added only when a
    // real device answers (SolverBackend.Select falls back to CPU otherwise, which we detect and skip).
    var cpu = SolverBackend.Select("cpu");
    // D-DOC-058: only the vendors asked for are probed (a probe of an absent vendor prints the backend's own
    // "[gpu] no usable ... device found" line, so a vendor that was not asked for is not even touched).
    var cuda = wantCuda ? SolverBackend.Select("cuda") : cpu;
    var rocm = wantRocm ? SolverBackend.Select("rocm") : cpu;
    var opencl = wantOpenCl ? SolverBackend.Select("opencl") : cpu;
    // routing-exempt-begin: bench is the engine benchmark. It deliberately builds EVERY engine on every backend and
    // times each one on every case, so it must not route through SolverSelector (which would pick one engine per
    // case and leave nothing to compare). Nothing here feeds a study result.
    var engines = new List<(string Name, string Desc, bool Dense, bool Gpu, Func<GridModel, IPowerFlowSolver?> Make)>
    {
        ("cpu-dense",  "Dense Newton-Raphson, CPU LU",                 true,  false, _ => cpu.DenseSolver()),
        ("cpu-sparse", "Sparse Newton-Raphson, CPU (direct LU / ILU0-BiCGSTAB)", false, false, _ => cpu.SparseSolver()),
        ("bfs",        "Backward-forward sweep (radial feeders only)", false, false, m => SolverBackend.LooksRadial(m) ? new BackwardForwardSweep() : null),
    };
    // GPU engines are opt-in (bench --gpu): FP64 on a consumer card is slow, so we don't run it by
    // default. When asked, a vendor is added only if a real device actually answered.
    if (includeGpu && cuda.Device == SolverBackend.Vendor.Cuda)
    {
        engines.Add(("cuda-dense",  $"Dense NR, CUDA ({cuda.Description})",  true,  true, _ => cuda.DenseSolver()));
        engines.Add(("cuda-sparse", $"Sparse NR, CUDA ({cuda.Description})", false, true, _ => cuda.SparseSolver()));
    }
    if (includeGpu && rocm.Device == SolverBackend.Vendor.Rocm)
    {
        engines.Add(("rocm-dense",  $"Dense NR, ROCm ({rocm.Description})",  true,  true, _ => rocm.DenseSolver()));
        engines.Add(("rocm-sparse", $"Sparse NR, ROCm ({rocm.Description})", false, true, _ => rocm.SparseSolver()));
    }
    if (includeGpu && opencl.Device == SolverBackend.Vendor.OpenCl)
    {
        engines.Add(("opencl-dense",  $"Dense NR, OpenCL ({opencl.Description})",  true,  true, _ => opencl.DenseSolver()));
        engines.Add(("opencl-sparse", $"Sparse NR, OpenCL ({opencl.Description})", false, true, _ => opencl.SparseSolver()));
    }
    // routing-exempt-end

    string desc = $"bench-matrix  cases={cases.Count}  engines={engines.Count}  runs={runs}  parallel={dop}"
                + (string.IsNullOrWhiteSpace(note) ? "" : $"  note=\"{note}\"");
    foreach (string h in RunInfo.HeaderLines(desc)) Emit("    " + h);
    if (!string.IsNullOrWhiteSpace(note)) { Emit(""); Emit($"> **Run note:** {note}"); }
    // D-DOC-057: the sidecar is named after the report (<report>.run-metadata.json), so two bench runs (or a bench and a
    // sweep) sharing a folder no longer replace each other's metadata. It also records the run's own settings as
    // `parameters`, so a report can be matched to exactly what ran: the cases in order, the engines, the GPU request and
    // the warm-up rule (D-DOC-059).
    RunInfo.WriteJson(CliFiles.Output(RunInfo.MetadataPathFor(outPath), "run metadata"), desc, new
    {
        runs,
        parallel = dop,
        cases = cases.Select(c => c.Label).ToArray(),
        casesFlag = casesArg,
        gpuRequested = vendor is null ? null : (vendor.Length == 0 ? "auto" : vendor),
        engines = engines.Select(e => e.Name).ToArray(),
        warmupSolvesPerCell = 1,
        report = Path.GetFullPath(outPath),
        csv = Path.GetFullPath(Path.ChangeExtension(outPath, ".csv")),
    });

    Emit("");
    Emit("Full solver x backend matrix over the whole archive. Every **engine** below is swept across");
    Emit("every case (Q-limits off, tol 1e-8, max 100 iters). Cells: `conv / iters / mismatch / mean ms`.");
    Emit("BFS is radial-only (meshed cases show `n/a`). Dense solves are memory-gated (few concurrent)");
    Emit($"and ordered small->large; GPU engines run one case at a time and skip cases >{GpuBusCap} buses");
    Emit("(consumer-GPU FP64 is slow). Absent accelerators are simply not listed as engines.");
    Emit("Each cell first runs one untimed warm-up solve of the same case on the same engine, so the mean");
    Emit("excludes JIT compilation, GPU kernel compilation and first-touch allocation.");
    Emit("");
    Emit("**Engines this run:** " + string.Join("; ", engines.Select(e => $"`{e.Name}` - {e.Desc}")));
    if (!includeGpu) { Emit(""); Emit("_GPU engines not requested (pass `--gpu` to add ROCm/OpenCL/CUDA when a device is present)._"); }
    else
    {
        // D-DOC-058: name the request as it was given, and say nothing about a vendor that was not asked for.
        string asked = vendor is "" or "auto" ? "--gpu" : $"--gpu={vendor}";
        if (wantCuda && cuda.Device != SolverBackend.Vendor.Cuda) Emit($"_CUDA: `{asked}` requested but no device answered._");
        if (wantRocm && rocm.Device != SolverBackend.Vendor.Rocm) Emit($"_ROCm/AMD: `{asked}` requested but no device answered._");
        if (wantOpenCl && opencl.Device != SolverBackend.Vendor.OpenCl) Emit($"_OpenCL: `{asked}` requested but no device answered._");
    }
    csv.WriteLine("engine,case,buses,gens,branches,conv,iters,mismatch,mean_ms,runs,commit");

    var opt = new PowerFlowOptions { MaxIterations = 100, EnforceQLimits = false };
    var summary = new Dictionary<string, Dictionary<string, string>>();   // case -> engine -> cell
    var busOf = new Dictionary<string, int>();                            // case -> bus count (for the comparison table)

    (bool conv, int iters, double mism, double meanMs, int nRuns, string note) Measure(IPowerFlowSolver solver, GridModel m, int nRuns)
    {
        try
        {
            int iters = 0; bool conv = false; double mism = 0, total = 0;
            // D-DOC-059 (October 2026, docs-session finding): one untimed warm-up solve first. Without it the first timed
            // run of each cell paid for JIT compilation of the solver code (and, on a GPU, kernel compilation and device
            // buffer set-up), so the first cases' means and every GPU mean were inflated by one-off costs that are not
            // solve time. bench --perf and bench --estimate already warm up this way. Its result is discarded: the
            // reported conv / iters / mismatch are still those of the first TIMED run (a solve is deterministic, so they
            // are the same bits either way). The cost: every cell runs one extra solve (for the single-run giants above
            // 4,000 buses that doubles the cell's wall time).
            _ = solver.Solve(m, opt);
            for (int run = 0; run < nRuns; run++)
            {
                var sw = System.Diagnostics.Stopwatch.StartNew();
                PowerFlowResult r = solver.Solve(m, opt);
                sw.Stop();
                total += sw.Elapsed.TotalMilliseconds;
                if (run == 0) { iters = r.Iterations; conv = r.Converged; mism = r.MaxMismatch; }
            }
            return (conv, iters, mism, total / nRuns, nRuns, "");
        }
        catch (OutOfMemoryException) { return (false, 0, 0, 0, 0, "OOM"); }
        catch (Exception ex) { return (false, 0, 0, 0, 0, "ERR:" + ex.Message.Replace('\n', ' ').Replace('|', '/')); }
    }
    string Cell((bool conv, int iters, double mism, double meanMs, int nRuns, string note) r) =>
        r.note.Length > 0 ? r.note : $"{(r.conv ? "yes" : "**NO**")} / {r.iters} / {r.mism:E2} / {r.meanMs:F0}ms" + (r.nRuns < runs ? $" (x{r.nRuns})" : "");

    // One sweep per engine.
    using var bigGate = new SemaphoreSlim(3);      // dense 3k-8k buses: a few at a time
    using var hugeGate = new SemaphoreSlim(1);     // dense >8k buses: one at a time
    foreach (var eng in engines)
    {
        Emit("");
        Emit($"## {eng.Name} - {eng.Desc}");
        Emit("| Case | Buses | Gens | Branches | conv / iters / mismatch / mean ms |");
        Emit("|------|------:|-----:|---------:|-----------------------------------|");
        int done = 0, edop = eng.Gpu ? 1 : dop;
        // GR-679: the cases run in parallel, but each one's table row, CSV line and tally entry is kept by its case index
        // and written after the sweep, in case order, so two runs of the same matrix give the same report and CSV. Only
        // the progress lines on stderr still appear in completion order.
        var ordered = cases.OrderBy(c => c.SortKey).ToList();
        var after = new Action?[ordered.Count];
        Parallel.ForEach(ordered, new ParallelOptions { MaxDegreeOfParallelism = edop }, (c, _, idx) =>
        {
            GridModel m;
            try { m = c.Load(); }
            catch (Exception ex) { after[idx] = () => { Emit($"| {c.Label} | - | - | - | LOAD FAIL: {ex.Message} |"); Record(c.Label, eng.Name, "load-fail"); benchTally.LoadFailed($"{c.Label} ({eng.Name})"); }; return; }
            lock (gate) { busOf[c.Label] = m.BusCount; }

            IPowerFlowSolver? solver = eng.Make(m);
            if (solver is null)
            {
                after[idx] = () => { Emit($"| {c.Label} | {m.BusCount} | {m.Generators.Count} | {m.Branches.Count} | n/a (meshed) |"); Record(c.Label, eng.Name, "n/a"); };
                return;
            }
            if (eng.Gpu && m.BusCount > GpuBusCap)
            {
                after[idx] = () => { Emit($"| {c.Label} | {m.BusCount} | {m.Generators.Count} | {m.Branches.Count} | n/a (>{GpuBusCap} buses, skipped) |"); Record(c.Label, eng.Name, "skip"); };
                return;
            }

            // routing-exempt: these bus counts only throttle how many big DENSE benchmark runs share memory at once.
            SemaphoreSlim? sem = eng.Dense ? (m.BusCount > 8000 ? hugeGate : m.BusCount > 3000 ? bigGate : null) : null;
            sem?.Wait();
            try
            {
                int nRuns = eng.Gpu ? Math.Min(runs, 3) : m.BusCount > 4000 ? 1 : m.BusCount > 1000 ? Math.Min(runs, 3) : runs;
                Console.Error.WriteLine($"[{eng.Name} {done + 1}/{cases.Count}] {c.Label} ({m.BusCount} buses, {nRuns} run(s))...");
                var r = Measure(solver, m, nRuns);
                after[idx] = () =>
                {
                    Emit($"| {c.Label} | {m.BusCount} | {m.Generators.Count} | {m.Branches.Count} | {Cell(r)} |");
                    csv.WriteLine($"{eng.Name},{c.Label},{m.BusCount},{m.Generators.Count},{m.Branches.Count},{r.conv},{r.iters},{r.mism:E3},{r.meanMs:F2},{r.nRuns},{RunInfo.GitCommit}");
                    Record(c.Label, eng.Name, r.note.Length > 0 ? r.note : (r.conv ? $"{r.meanMs:F0}ms" : "NO"));
                    // D-DOC-012: a cell that did not converge, ran out of memory or threw is a failed solve.
                    if (!r.conv) benchTally.RunFailed($"{c.Label} on {eng.Name}: {(r.note.Length > 0 ? r.note : "did not converge")}");
                };
                lock (gate) { done++; }
            }
            finally { sem?.Release(); }
        });
        foreach (Action? write in after) write?.Invoke();
    }

    // ---- Comparison matrix: mean solve time per case per engine ----------------------------------
    Emit("");
    Emit("## Comparison - mean solve time (ms), converged unless noted");
    Emit("| Case | Buses | " + string.Join(" | ", engines.Select(e => e.Name)) + " |");
    Emit("|------|------:|" + string.Concat(engines.Select(_ => "------:|")));
    foreach (var c in cases.OrderBy(c => c.SortKey).ThenBy(c => c.Label, StringComparer.Ordinal))
    {
        string busesStr = busOf.TryGetValue(c.Label, out int bc) ? bc.ToString() : "-";
        var cells = engines.Select(e => summary.TryGetValue(c.Label, out var byEng) && byEng.TryGetValue(e.Name, out var v) ? v : "-");
        Emit($"| {c.Label} | {busesStr} | " + string.Join(" | ", cells) + " |");
    }
    Console.Error.WriteLine($"[bench] done ({engines.Count} engines x {cases.Count} cases) -> {Path.GetFullPath(outPath)}");
    // D-DOC-012: the verdict, after the full report (a failed cell never stops the matrix).
    foreach (string l in benchTally.SummaryLines("bench")) Console.Error.WriteLine(l);
    Environment.ExitCode = benchTally.ExitCode;

    void Record(string label, string engine, string cell)
    {
        if (!summary.TryGetValue(label, out var byEng)) summary[label] = byEng = new();
        byEng[engine] = cell;
    }
}

// -------- N-1 sweep (parallel, full or sampled) --------------------------------------------------
void RunLossAllocation(List<string> a, string root)
{
    // F01 (October 2026): an unknown case name used to escape LoadNamed as an unhandled ArgumentException (a stack
    // trace and the runtime's crash code). The case now goes through the shared loader every other verb uses: an
    // unknown name is a usage error (exit 2, naming it and listing the built-in names, as manual ch. 19 says for every
    // verb), a missing or unloadable .m file or case folder is an input error (exit 1, through the process-wide
    // handler), and a second case argument is refused (exit 2). A built-in name or a .m path loads exactly as before;
    // a JSON case folder is now accepted too.
    string pos = SingleCasePositional("losses", a) ?? "case9";
    GridModel m = LoadSelected("losses", (pos, () => LoadCaseArgument(pos, root)));
    // Newton engine by the shared rule (SolverSelector.ResolveNewton via backend.NewtonSolver); it was a local
    // 'BusCount > 1000'. Never the radial sweep: loss allocation reads the Newton solve, as before. The two Newton
    // engines are bit-identical on the CPU, so this changes speed only.
    IPowerFlowSolver solver = backend.NewtonSolver(m);
    var result = solver.Solve(m);
    if (!result.Converged) { Console.Error.WriteLine("error: base case did not converge."); Environment.ExitCode = 3; return; }

    var alloc = GridSim.Core.Analysis.LossAllocation.Allocate(m, result);
    // N105 (October 2026): a header naming the case, as every other analysis verb prints (dcpf, taps, ...). The report
    // used to start at "Total losses", so a saved output did not say which network it was about. One line; the rest of
    // the report is unchanged.
    Console.WriteLine($"Loss allocation - {m.Name} ({m.BusCount} buses, {m.Branches.Count} branches)");
    Console.WriteLine($"  Total losses: {alloc.TotalPLossMw:F2} MW  (reactive: {alloc.TotalQLossMvar:F2} MVAr)");
    // N053: the bus shunt conductances' draw is part of the solver's injection total but in no branch; shown on its own
    // line (only when the case has any) so the residual below is rounding, not 1.21 MW of it on case300.
    if (m.Buses.Any(b => b.Gs != 0))
        Console.WriteLine($"  Bus shunt conductance: {alloc.ShuntPMw:F2} MW  (not a branch loss; in the injection total)");
    Console.WriteLine($"  Reconciliation residual: {alloc.ReconciliationResidualMw:E2} MW");
    Console.WriteLine();

    if (alloc.ZoneLosses.Count > 0)
    {
        Console.WriteLine("  Zone losses:");
        Console.WriteLine("  | Zone | P Loss MW | Q Loss MVAr | Branches |");
        Console.WriteLine("  |------|----------:|------------:|---------:|");
        foreach (var z in alloc.ZoneLosses)
            Console.WriteLine($"  | {z.Zone} | {z.PLossMw:F2} | {z.QLossMvar:F2} | {z.BranchCount} |");
        Console.WriteLine();
    }

    Console.WriteLine("  Top 20 branch losses:");
    Console.WriteLine("  | Branch | From | To | P Loss MW | Q Loss MVAr | Loading % | Type |");
    Console.WriteLine("  |--------|-----:|---:|----------:|------------:|----------:|------|");
    foreach (var bl in alloc.BranchLosses.OrderByDescending(b => b.PLossMw).Take(20))
        Console.WriteLine($"  | {bl.Name} | {bl.From} | {bl.To} | {bl.PLossMw:F3} | {bl.QLossMvar:F3} | {bl.LoadingPercent:F1} | {(bl.IsTransformer ? "tx" : "line")} |");
    // F10: every branch (the console lists the top 20), in the allocation's own order, and every zone.
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", m.Name).Set("buses", m.BusCount).Set("total_p_loss_mw", alloc.TotalPLossMw).Set("total_q_loss_mvar", alloc.TotalQLossMvar)
            .Set("shunt_p_mw", alloc.ShuntPMw).Set("reconciliation_residual_mw", alloc.ReconciliationResidualMw);
        CliResultTable branches = rep.Table("branches", "name", "from", "to", "p_loss_mw", "q_loss_mvar", "loading_pct", "type");
        foreach (var bl in alloc.BranchLosses)
            branches.Row(bl.Name, bl.From, bl.To, bl.PLossMw, bl.QLossMvar, bl.LoadingPercent, bl.IsTransformer ? "tx" : "line");
        CliResultTable zones = rep.Table("zones", "zone", "p_loss_mw", "q_loss_mvar", "branches");
        foreach (var z in alloc.ZoneLosses) zones.Row(z.Zone, z.PLossMw, z.QLossMvar, z.BranchCount);
        rep.Complete();
    }
}

void RunNMinus1Sweep(List<string> a, int parallel, int sample, string? outPath, string root, bool losses = false)
{
    // Case selection, decided BEFORE any output file is opened: --all (the registry), or one network from the
    // positional case and/or --dir (SelectCase: --dir used to be accepted and ignored here; now it is honoured, a
    // disagreeing pair is refused with exit 2, and a missing folder exits 1).
    List<(string Label, Func<GridModel> Load, int SortKey)> cases = SelectBatchCases("nminus1-sweep", a, root);

    int dop = parallel <= 0 ? Environment.ProcessorCount : parallel;
    outPath ??= DefaultResultsPath("nminus1-sweep.md");
    // D-DOC-072: the report and its CSV through the one output policy (CliFiles creates the folder).
    using var file = new StreamWriter(CliFiles.Output(outPath, "report")) { AutoFlush = true };
    using var csv = new StreamWriter(CliFiles.Output(Path.ChangeExtension(outPath, ".csv"), "report CSV")) { AutoFlush = true };
    void Emit(string s) { Console.WriteLine(s); file.WriteLine(s); }

    string desc = $"nminus1-sweep  cases={cases.Count}  parallel={dop}  sample={(sample > 0 ? sample.ToString() : "full")}  vlimits={(busVlimits ? "per-bus" : "global")}";   // D-DOC-118: which voltage limits judged the outages
    foreach (string h in RunInfo.HeaderLines(desc)) Emit("    " + h);
    // D-DOC-057: the sidecar is named after the report (<report>.run-metadata.json), so reports sharing a folder no longer
    // replace each other's metadata.
    RunInfo.WriteJson(CliFiles.Output(RunInfo.MetadataPathFor(outPath), "run metadata"), desc);
    Emit("");
    // D03: "Base viol" is the number of violations the intact network already has; they are reported once, in that
    // column, and netted out of every outage's count (an outage counts as violating only for violations it causes).
    // N140: "Islanded" counts only the outages that split the network and "Not solved" the connected outages with no
    // solution (the N107 split every other contingency verb has applied since 1.95.124; this sweep counted every
    // non-converged outage as islanded). The CSV keeps its columns in place and appends not_solved at the end, so a
    // script reading the existing columns by position still finds them.
    Emit("| Case | Buses | Branches | Screened | Secure | Violations | Islanded | Not solved | Solves/s | Wall s | Base viol |");
    Emit("|------|------:|---------:|---------:|-------:|-----------:|---------:|-----------:|---------:|-------:|----------:|");
    csv.WriteLine("case,buses,branches,screened,secure,violations,islanded,solves_per_s,wall_s,sampled,commit,base_violations,not_solved");

    // D04: the contingency family's one option set (100 iterations, reactive limits ON; the sweep used to switch them
    // off, so it could classify an outage differently from nminus1) and the OLTC loop around the engine.
    PowerFlowOptions opt = ContingencyAnalysis.StudyOptions;
    // D-DOC-118 (October 2026): the outage verdicts use each bus's own voltage limits where the case gives them (the N092
    // default of nminus1, nminus2 and n-1-1; --global-vlimits restores the band), so the sweep and nminus1 agree on every
    // case. PerBusVoltageLimits is read only by the violation check (ContingencyAnalysis), never by a solver, so every
    // solve is the same bits; on a case with no per-bus limits the verdicts are exactly the band's, as before.
    opt = opt with { PerBusVoltageLimits = busVlimits };
    int ran = 0, loadFailed = 0, notSecure = 0;
    foreach ((string label, Func<GridModel> load, _) in cases)
    {
        GridModel m;
        try { m = load(); }
        catch (Exception ex) { Emit($"| {label} | - | - | LOAD FAIL: {ex.Message} | | | | | | | |"); loadFailed++; continue; }
        ran++;

        // Newton engine per worker by the shared rule (was a local 'BusCount > 1000'); bit-identical engines on the
        // CPU, so this changes speed only. Wrapped in the OLTC loop (D04): with no OLTC records in the model the loop
        // is skipped and the engine's answer is returned bit for bit.
        Func<IPowerFlowSolver> factory = () => ContingencyAnalysis.WithOltcLoop(backend.NewtonSolver(m));

        // D03: the base case first, with the same solver and options. One that does not converge cannot be netted:
        // the row says so and the run fails (exit 3) instead of screening against an unsolved state.
        ContingencyResult baseCase = ContingencyAnalysis.ScreenBaseCase(m, factory(), opt);
        if (!baseCase.Converged)
        {
            Emit($"| {label} | {m.BusCount} | {m.Branches.Count} | BASE FAIL: the base case did not converge ({string.Join("; ", baseCase.Violations)}) | | | | | | | |");
            csv.WriteLine($"{label},{m.BusCount},{m.Branches.Count},0,0,0,0,0,0,False,{RunInfo.GitCommit},base-not-converged,0");
            notSecure++;
            continue;
        }

        int nb = m.Branches.Count;
        IReadOnlyList<int>? idx = null;
        bool sampled = false;
        if (sample > 0 && nb > sample)
        {
            // Evenly-spaced sample across the branch list (logged, never silent).
            idx = Enumerable.Range(0, sample).Select(k => (int)((long)k * nb / sample)).Distinct().ToList();
            sampled = true;
            Console.Error.WriteLine($"[n-1] {label}: SAMPLING {idx.Count}/{nb} branches (--sample {sample})");
        }
        Console.Error.WriteLine($"[n-1] {label}: {m.BusCount} buses, screening {(idx?.Count ?? nb)} outages on {dop} threads...");

        var sw = System.Diagnostics.Stopwatch.StartNew();
        var results = ContingencyAnalysis.NetAgainstBase(ContingencyAnalysis.ScreenBranchesParallel(m, factory, opt, dop, idx), baseCase);
        sw.Stop();

        int screened = results.Count;
        int islanded = results.Count(r => !r.Converged && r.Islanded);     // N140: splits only (N107)
        int notSolved = results.Count(r => !r.Converged && !r.Islanded);   // connected, no solution
        int secure = results.Count(r => r.Secure);
        int viol = results.Count(r => r.Converged && r.Violations.Count > 0);
        double sps = screened / Math.Max(1e-6, sw.Elapsed.TotalSeconds);
        // F01: a case is not N-1 secure when its base case violates or any screened outage violates or islands.
        if (baseCase.Violations.Count > 0 || secure < screened) notSecure++;

        Emit($"| {label}{(sampled ? " (sampled)" : "")} | {m.BusCount} | {nb} | {screened} | {secure} | {viol} | {islanded} | {notSolved} | {sps:F0} | {sw.Elapsed.TotalSeconds:F1} | {baseCase.Violations.Count} |");
        csv.WriteLine($"{label},{m.BusCount},{nb},{screened},{secure},{viol},{islanded},{sps:F1},{sw.Elapsed.TotalSeconds:F2},{sampled},{RunInfo.GitCommit},{baseCase.Violations.Count},{notSolved}");

        if (losses)
        {
            // Same shared rule, the same OLTC loop and the same options as the outage solves (D04), so the loss deltas
            // compare like with like.
            IPowerFlowSolver baseSolver = ContingencyAnalysis.WithOltcLoop(backend.NewtonSolver(m));
            var baseResult = baseSolver.Solve(m, opt);
            if (baseResult.Converged)
            {
                Console.Error.WriteLine($"[n-1] {label}: running loss contingency sweep...");
                var lossSw = System.Diagnostics.Stopwatch.StartNew();
                var lossResults = LossContingency.SweepParallel(m, baseResult, factory, opt, dop);
                lossSw.Stop();
                Emit("");
                Emit($"### Loss contingency - {label} (base losses: {baseResult.TotalLossMw:F2} MW)");
                Emit("| Outage | Delta MW | Post MW | Loading % |");
                Emit("|--------|--------:|--------:|----------:|");
                foreach (var lr in lossResults.Where(r => r.Converged).OrderByDescending(r => r.DeltaLossMw).Take(20))
                    Emit($"| {lr.Outage} | {lr.DeltaLossMw:+0.00;-0.00} | {lr.PostLossMw:F2} | {lr.MaxBranchLoadingPercent:F1} |");
                int ncLoss = lossResults.Count(r => !r.Converged);
                if (ncLoss > 0) Emit($"| ({ncLoss} non-converged) | | | |");
                Emit("");
            }
        }
    }
    Console.Error.WriteLine($"[n-1] done -> {Path.GetFullPath(outPath)}");
    if (ran == 0) { Console.Error.WriteLine("error: no case loaded successfully - nothing ran."); Environment.ExitCode = 1; }
    // R215: a partial load failure is reported and exits 1 (input error) rather than 0. An input error outranks the
    // security verdict below: the run did not cover what was asked.
    else if (loadFailed > 0)
    {
        Console.Error.WriteLine($"error: {loadFailed} case(s) failed to load (LOAD FAIL rows above); the others ran.");
        if (Environment.ExitCode == 0) Environment.ExitCode = 1;
    }
    // F01: the security verdict is the exit code, as for nminus1: 3 when any case is not N-1 secure (a base-case
    // violation, an outage with violations, an islanding or unsolved outage, or a base case that did not converge).
    else if (notSecure > 0)
    {
        Console.Error.WriteLine($"[n-1] verdict: {notSecure} of {ran} case(s) not N-1 secure (exit 3).");
        if (Environment.ExitCode == 0) Environment.ExitCode = 3;
    }
}

// -------- Prioritised parallel analysis cycle ----------------------------------------------------
// Each cycle: one single-threaded Newton-Raphson base solve, then fan every downstream analysis out
// across a worker pool against the shared immutable frame. High-priority jobs (hot N-1, harmonics,
// watch list) complete every cycle; Low-priority jobs (rotating N-1 shards, RoCoF, conformance) run
// best-effort within the compute budget (workers x window) and rotate to full coverage over cycles.
void RunCycle(List<string> a, string root, bool holdSteady, bool pipeline)
{
    // Positional case and/or --dir through the shared SelectCase (default data/uk). The old code let --dir silently
    // win over a positional case, and on a missing --dir folder it said "could not load case ''", naming an empty
    // case, with exit 2. Now a disagreeing pair exits 2, a missing --dir folder exits 1 naming the folder, an unknown
    // case name exits 2 naming it, and a missing or unloadable .m file exits 1 (the process-wide handler).
    var cycleSel = SelectCase("cycle", SingleCasePositional("cycle", a), a, root, "data/uk", () => LoadUkDefault(root));
    GridModel m = LoadSelected("cycle", cycleSel);

    // GR-682: each count is refused below 1 (exit 2), not raised to 1 without a word.
    int windowMs = FlagCount(a, "--window-ms", 1000, 1);
    int workers = FlagCount(a, "--workers", Math.Max(1, Environment.ProcessorCount - 1), 1);
    int cycles = FlagCount(a, "--cycles", 10, 1);
    int shards = FlagCount(a, "--shards", 8, 1);
    double hotLoading = FlagDouble(a, "--hot-loading", 80.0);
    if (!(hotLoading >= 0)) FailFlag<double>("--hot-loading", hotLoading.ToString("R", System.Globalization.CultureInfo.InvariantCulture), "a loading of 0 % or above");
    string? jobsCsv = FlagString(a, "--jobs");
    // D-DOC-081: an unknown job key (or a list with no key) used to build zero jobs, so every cycle "met" the High
    // tier vacuously, the run printed "HP met every cycle: YES" and exited 0. Core's ParseJobKeys now refuses it, naming
    // the bad keys and the valid ones; that is a usage error (exit 2), like every other bad flag value.
    IReadOnlySet<string>? enabled = null;
    if (jobsCsv is not null)
    {
        try { enabled = AnalysisJobLibrary.ParseJobKeys(jobsCsv); }
        catch (ArgumentException ex)
        {
            Console.Error.WriteLine($"error: cycle --jobs: {CliExit.UserMessage(ex)}");
            Environment.Exit(2);
        }
    }

    var opt = new CycleOptions
    {
        WindowMs = windowMs,
        Workers = workers,
        NMinus1Shards = shards,
        HotBranchLoadingPercent = hotLoading,
        PipelineBacklog = pipeline,
    };
    IReadOnlyList<AnalysisJob> jobs = AnalysisJobLibrary.Build(m, opt, enabled);
    var runner = new CycleRunner(m, opt, jobs, holdSteady);
    int highN = jobs.Count(j => j.Priority == JobPriority.High);
    int lowN = jobs.Count - highN;
    int shardTotal = jobs.Count(j => j.Id.StartsWith("n-1:lp:", StringComparison.Ordinal));

    Console.WriteLine($"GridSim  -  prioritised parallel analysis cycle: {m.Name}");
    Console.WriteLine(new string('=', 92));
    Console.WriteLine($"case {m.BusCount} buses / {m.Branches.Count} branches   engine {runner.ActiveSolver}");
    Console.WriteLine($"window {windowMs} ms   workers {workers}   budget {(double)workers * windowMs / 1000.0:F1} core-s/cycle"
        + $"   jobs {jobs.Count} ({highN} High / {lowN} Low)");
    Console.WriteLine(new string('-', 92));
    Console.WriteLine("cycle |  base ms | wall ms |  HP   | LP done/adm/def | util% | backlog | note");
    Console.WriteLine(new string('-', 92));

    var coveredShards = new HashSet<string>(StringComparer.Ordinal);
    double utilSum = 0;
    bool everMissedHp = false;
    // F10: one row per cycle with the printed figures unrounded (timings are wall-clock, so they differ run to run).
    CliResult? rep = CliOutput.Report;
    CliResultTable? repCycles = rep?.Table("cycles", "cycle", "base_solve_ms", "wall_ms", "high_completed", "high_total",
        "low_completed", "low_admitted", "low_deferred", "utilisation", "backlog", "high_tier_met", "note");
    for (int c = 0; c < cycles; c++)
    {
        CycleResult r = runner.RunOnce();
        utilSum += r.Utilization;
        if (!r.HighTierMet) everMissedHp = true;
        foreach (JobResult jr in r.Results)
            if (jr.Outcome == JobOutcome.Completed && jr.Id.StartsWith("n-1:lp:", StringComparison.Ordinal))
                coveredShards.Add(jr.Id);
        string note = !r.HighTierMet ? "HP MISSED"
            : shardTotal > 0 ? $"n-1 shards {coveredShards.Count}/{shardTotal}"
            : "";
        Console.WriteLine(
            $"{r.CycleIndex,5} | {r.BaseSolveMs,8:F1} | {r.WallMs,7:F0} | {r.HighCompleted,2}/{r.HighTotal,-2} |"
            + $" {r.LowCompleted,3}/{r.LowAdmitted,-3}/{r.LowDeferred,-3}   | {r.Utilization * 100,4:F0}% | {r.BacklogDepth,7} | {note}");
        repCycles?.Row(r.CycleIndex, r.BaseSolveMs, r.WallMs, r.HighCompleted, r.HighTotal, r.LowCompleted, r.LowAdmitted, r.LowDeferred,
            r.Utilization, r.BacklogDepth, r.HighTierMet, note);
    }

    Console.WriteLine(new string('-', 92));
    Console.WriteLine(
        $"{cycles} cycles   avg util {utilSum / cycles * 100:F0}%   HP met every cycle: {(everMissedHp ? "NO" : "YES")}"
        + (shardTotal > 0 ? $"   N-1 coverage {coveredShards.Count}/{shardTotal} shards" : ""));
    if (everMissedHp) Environment.ExitCode = 1;   // the design's core guarantee was violated - fail loud
    // A missed High tier is a finished result (exit 1), written too.
    rep?.Set("case", m.Name).Set("buses", m.BusCount).Set("branches", m.Branches.Count).Set("engine", runner.ActiveSolver)
        .Set("window_ms", windowMs).Set("workers", workers).Set("jobs", jobs.Count).Set("high_jobs", highN).Set("low_jobs", lowN)
        .Set("cycles", cycles).Set("average_utilisation", utilSum / cycles).Set("high_tier_met_every_cycle", !everMissedHp)
        .Set("n1_shards_covered", coveredShards.Count).Set("n1_shards_total", shardTotal).Complete();
}

// -------- Batched dense linear solve (GPU batched kernel demonstrator + micro-bench) --------------
// Solves `count` independent n×n systems in one dispatch on the selected backend (GPU batched kernel,
// or the CPU reference loop when no device is present), verifies against the per-system CPU reference,
// and times both. This is the batched primitive a contingency sweep uses to factor many same-sized
// outages in one launch instead of one locked single solve each.
void RunBatchSolve(List<string> a)
{
    int count = Math.Max(1, FlagInt(a, "--count", 64));
    int n = Math.Max(1, FlagInt(a, "--n", 64));
    int runs = Math.Max(1, FlagInt(a, "--runs", 5));
    if ((long)count * n * n > int.MaxValue)
    {
        Console.Error.WriteLine("error: count*n*n exceeds the single-dispatch limit; reduce --count/--n (chunk it).");
        Environment.ExitCode = 2;
        return;
    }

    // Deterministic, strongly diagonally-dominant systems so LU is stable and the answer is well-defined.
    var rng = new Random(20260725);
    var aBase = new double[count * n * n];
    var bBase = new double[count * n];
    for (int s = 0; s < count; s++)
        for (int i = 0; i < n; i++)
        {
            double rowAbs = 0;
            for (int j = 0; j < n; j++)
            {
                if (i == j) continue;
                double v = rng.NextDouble() * 2 - 1;
                aBase[s * n * n + i * n + j] = v;
                rowAbs += Math.Abs(v);
            }
            aBase[s * n * n + i * n + i] = rowAbs + 1.0 + rng.NextDouble();
            bBase[s * n + i] = rng.NextDouble() * 10 - 5;
        }

    IBatchedLinearSolver batched = backend.DenseBatch();
    var cpuRef = new CpuBatchedLuSolver();

    Console.WriteLine($"GridSim  -  batched dense solve: {count} systems x {n}x{n}   backend {batched.Name}");
    Console.WriteLine(new string('=', 78));

    // Correctness vs the CPU reference.
    var (aC, bC) = ((double[])aBase.Clone(), (double[])bBase.Clone());
    var (aG, bG) = ((double[])aBase.Clone(), (double[])bBase.Clone());
    bool[] okRef = cpuRef.SolveBatch(count, n, aC, bC);
    bool[] okDev = batched.SolveBatch(count, n, aG, bG);
    double maxDiff = 0;
    int maskMismatch = 0;
    for (int i = 0; i < count * n; i++)
    {
        bool na = double.IsNaN(bC[i]), nb = double.IsNaN(bG[i]);
        if (na || nb) { if (na != nb) maskMismatch++; continue; }
        maxDiff = Math.Max(maxDiff, Math.Abs(bC[i] - bG[i]));
    }
    // D-DOC-135 (DOC-17): the word "Delta" in place of the Greek capital delta, which consoles printed as '?'.
    Console.WriteLine($"correctness: {okDev.Count(x => x)}/{count} solved   max|Delta| vs CPU reference = {maxDiff:E3}"
        + (maskMismatch > 0 ? $"   MASK MISMATCH x{maskMismatch}" : ""));

    double MedianMs(IBatchedLinearSolver solver)
    {
        var times = new double[runs];
        for (int r = 0; r < runs; r++)
        {
            var aa = (double[])aBase.Clone();
            var bb = (double[])bBase.Clone();
            var sw = System.Diagnostics.Stopwatch.StartNew();
            solver.SolveBatch(count, n, aa, bb);
            sw.Stop();
            times[r] = sw.Elapsed.TotalMilliseconds;
        }
        Array.Sort(times);
        return times[runs / 2];
    }

    double devMs = MedianMs(batched);
    double cpuMs = MedianMs(cpuRef);
    double devSps = devMs > 0 ? count / (devMs / 1000.0) : 0;
    Console.WriteLine($"timing (median of {runs}): backend {devMs:F1} ms   cpu-reference {cpuMs:F1} ms   backend {devSps:F0} solves/s");

    if (maxDiff > GridSim.Cli.CliDefaults.BatchedSolveAgreementTolerance || maskMismatch > 0)
    {
        Console.Error.WriteLine("error: batched result diverged from the CPU reference.");
        Environment.ExitCode = 1;
    }
}

// -------- Load-to-collapse (max loadability) -----------------------------------------------------
void RunStress(List<string> a, double from, double to, double step, int parallel, string? outPath, string root)
{
    // F18: --pv-out <file.csv> also writes, per case, every bus voltage at each load factor up to the last converged
    // one before the first failure (the factors that define the reported max loadability): the PV curves.
    string? pvOut = FlagString(a, "--pv-out");
    if (pvOut is not null && !pvOut.EndsWith(".csv", StringComparison.OrdinalIgnoreCase)) FailFlag<string>("--pv-out", pvOut, "a file name ending in .csv");
    // A non-positive --step makes the load sweep `for (f=from; f<=to; f+=step)` never advance -> infinite loop
    // that OOMs after the output files are created. Reject it up front.
    if (step <= 0)
    {
        Console.Error.WriteLine($"error: stress --step must be positive (got {step}); the load sweep would never terminate.");
        Environment.Exit(2);
    }
    // An empty load range (--from above --to) used to build no load points, solve nothing, print a table of
    // "<none>" rows and exit 0. Refuse it as a usage error before any output file is opened.
    if (from > to)
    {
        Console.Error.WriteLine($"error: stress --from ({from.ToString(System.Globalization.CultureInfo.InvariantCulture)}) is above --to " +
            $"({to.ToString(System.Globalization.CultureInfo.InvariantCulture)}); the load range is empty and nothing would be solved.");
        Environment.Exit(2);
    }
    // Case selection before any output file is opened (positional case, --dir, or --all; see SelectBatchCases).
    // --dir used to be accepted and ignored here, so the run silently stressed case118.
    List<(string Label, Func<GridModel> Load, int SortKey)> cases = SelectBatchCases("stress", a, root);

    int dop = parallel <= 0 ? Environment.ProcessorCount : parallel;
    outPath ??= DefaultResultsPath("stress.md");
    // D-DOC-072: the report and its CSV through the one output policy (CliFiles creates the folder).
    using var file = new StreamWriter(CliFiles.Output(outPath, "report")) { AutoFlush = true };
    using var csv = new StreamWriter(CliFiles.Output(Path.ChangeExtension(outPath, ".csv"), "report CSV")) { AutoFlush = true };
    void Emit(string s) { Console.WriteLine(s); file.WriteLine(s); }

    string desc = $"stress  cases={cases.Count}  load {from}->{to} step {step}  parallel={dop}";
    foreach (string h in RunInfo.HeaderLines(desc)) Emit("    " + h);
    // D-DOC-057: the sidecar is named after the report (<report>.run-metadata.json), so reports sharing a folder no longer
    // replace each other's metadata.
    RunInfo.WriteJson(CliFiles.Output(RunInfo.MetadataPathFor(outPath), "run metadata"), desc);
    Emit("");
    Emit("| Case | Buses | Max loadability (x base) | Vmin at collapse | Notes |");
    Emit("|------|------:|-------------------------:|-----------------:|-------|");
    csv.WriteLine("case,buses,max_loadability,vmin_at_max,commit");

    // D04: the contingency family's one option set (it was already 100 iterations with Q-limits on here) and, new, the
    // OLTC loop around the engine below, so a load point reaches the same tap-regulated state as the default solve.
    PowerFlowOptions opt = ContingencyAnalysis.StudyOptions;
    var factors = new List<double>();
    for (double f = from; f <= to + 1e-9; f += step) factors.Add(Math.Round(f, 4));

    int ran = 0, loadFailed = 0, noneConverged = 0;
    var pvCases = new List<(string Case, IReadOnlyList<int> BusIds, IReadOnlyList<(double, double[])> Points)>();   // F18
    foreach ((string label, Func<GridModel> load, _) in cases)
    {
        GridModel baseM;
        try { baseM = load(); }
        catch (Exception ex) { Emit($"| {label} | - | LOAD FAIL: {ex.Message} | | |"); loadFailed++; continue; }
        ran++;
        // Shared dense/sparse rule (was a local 1,000), wrapped in the OLTC loop (D04; skipped when the model has no OLTCs).
        Func<IPowerFlowSolver> factory = () => ContingencyAnalysis.WithOltcLoop(backend.NewtonSolver(baseM));

        Console.Error.WriteLine($"[stress] {label}: {factors.Count} load points on {dop} threads...");
        // R072 (October 2026): max loadability through the shared loadability loop (ContinuationPowerFlow.ScanGrid, the
        // same walk the cpf verb runs, on this verb's fixed grid): every load point is solved in parallel as before,
        // then the walk takes the highest factor that converged before the first non-convergence. The verb's own copy of
        // that rule is gone; the multipliers, the independent solves (AtLoad re-dispatch, the contingency option set, the
        // OLTC loop) and the rule are unchanged, so every number is too. A point whose solve throws counts as not
        // converged, as before (null result).
        // A load point whose solve throws a NUMERICAL failure (a singular or non-finite Jacobian near collapse is an
        // InvalidOperationException or an ArithmeticException) still counts as not converged, but it is no longer
        // silent: the points are counted and the first message is shown in the Notes column and on stderr. Any other
        // exception (a defect: null reference, index out of range, bad argument) is no longer swallowed and stops the
        // run, so a broken solver can never read as "collapsed at this load".
        int threw = 0;
        string? firstThrow = null;
        GridSim.Core.Analysis.LoadabilityGridScan scan = GridSim.Core.Analysis.ContinuationPowerFlow.ScanGrid(factors, f =>
        {
            try { return factory().Solve(GridScenario.AtLoad(baseM, f), opt); }
            catch (Exception ex) when (ex is InvalidOperationException or ArithmeticException)
            {
                Interlocked.Increment(ref threw);
                Interlocked.CompareExchange(ref firstThrow, $"x{f:F2}: {ex.Message}", null);
                return null;
            }
        }, dop);

        int lastOk = scan.LastConvergedIndex;
        // GR-700: the factors are rounded to 4 dp when built, so they print with up to 4 dp (at least 2, which is
        // exactly the old F2 text for any step of 0.01 or coarser) and invariantly: with --step 0.005 the report and the
        // CSV show the 2.375 the walk found, not 2.37 (or 2.38).
        string maxLoad = lastOk >= 0 ? factors[lastOk].ToString("0.00##", System.Globalization.CultureInfo.InvariantCulture) : "<none>";
        string vmin = lastOk >= 0 ? scan.Results[lastOk]!.Vm.Min().ToString("F3") : "-";
        string note = lastOk == factors.Count - 1 ? "did not collapse in range"
                    : lastOk < 0 ? "NO LOAD POINT CONVERGED"
                    : "";
        if (threw > 0)
        {
            note = (note.Length > 0 ? note + "; " : "") + $"{threw} point(s) failed numerically";
            Console.Error.WriteLine($"warning: [stress] {label}: {threw} load point(s) failed numerically, first {firstThrow}");
        }
        if (lastOk < 0)
        {
            noneConverged++;
            Console.Error.WriteLine($"error: [stress] {label}: no load point from {factors[0].ToString("0.00##", System.Globalization.CultureInfo.InvariantCulture)} converged; there is no loadability to report.");
        }
        Emit($"| {label} | {baseM.BusCount} | {maxLoad} | {vmin} | {note} |");
        csv.WriteLine($"{label},{baseM.BusCount},{maxLoad},{vmin},{RunInfo.GitCommit}");
        if (pvOut is not null && lastOk >= 0)
        {
            // F18: every converged point up to the reported one (all of them converged, by the walk's rule).
            var pts = new List<(double, double[])>(lastOk + 1);
            for (int i = 0; i <= lastOk; i++) pts.Add((factors[i], (double[])scan.Results[i]!.Vm.Clone()));
            pvCases.Add((label, scan.Results[0]!.BusIds, pts));
        }
    }
    if (pvOut is not null)
    {
        WritePvCurveCsv(pvOut, "load_factor", pvCases);
        Console.Error.WriteLine($"[stress] PV curves for {pvCases.Count} case(s) -> {Path.GetFullPath(pvOut)}");
    }
    Console.Error.WriteLine($"[stress] done -> {Path.GetFullPath(outPath)}");
    if (ran == 0) { Console.Error.WriteLine("error: no case loaded successfully - nothing ran."); Environment.ExitCode = 1; }
    // R215: a partial load failure is reported and exits 1 (input error) rather than 0.
    else if (loadFailed > 0)
    {
        Console.Error.WriteLine($"error: {loadFailed} case(s) failed to load (LOAD FAIL rows above); the others ran.");
        if (Environment.ExitCode == 0) Environment.ExitCode = 1;
    }
    // A case with no converged load point is a power flow that did not converge: exit 3, as every verb does (ch. 30).
    // An input error (exit 1) above takes precedence.
    if (noneConverged > 0 && Environment.ExitCode == 0)
    {
        Console.Error.WriteLine($"error: {noneConverged} case(s) had no converged load point (<none> rows above).");
        Environment.ExitCode = 3;
    }
}

// -------- Consecutive warm-started solves --------------------------------------------------------
void RunChain(List<string> a, int steps, string mode, double rampPct, string? outPath, string root)
{
    // Fail loud on an unknown --mode: the switch below degraded any typo or
    // capitalised value to 'fixed' while run-metadata recorded the REQUESTED
    // string - the output claimed one experiment and contained another.
    mode = mode.ToLowerInvariant();
    if (mode is not ("fixed" or "ramp" or "daily"))
        FailFlag<string>("--mode", mode, "'fixed', 'ramp' or 'daily'");

    // Positional case and/or --dir (SelectCase; --dir used to be accepted and ignored, so the run silently chained
    // case118). Decided before any output file is opened.
    (string caseArg, Func<GridModel> chainLoad) = SelectCase("chain", SingleCasePositional("chain", a), a, root,
        "case118", () => LoadNamed("case118", root));
    outPath ??= DefaultResultsPath($"chain-{CaseFileTag(caseArg)}.md");
    // D-DOC-072: the report and its CSV through the one output policy (CliFiles creates the folder).
    using var file = new StreamWriter(CliFiles.Output(outPath, "report")) { AutoFlush = true };
    using var csv = new StreamWriter(CliFiles.Output(Path.ChangeExtension(outPath, ".csv"), "report CSV")) { AutoFlush = true };
    void Emit(string s) { Console.WriteLine(s); file.WriteLine(s); }

    GridModel baseM;
    try
    {
        baseM = chainLoad();
    }
    catch (Exception ex)
    {
        // A bad case name threw out of the load and dumped a raw stack trace after the output stubs were
        // already opened. Fail cleanly with a non-zero exit instead.
        Console.Error.WriteLine($"error: chain could not load case '{caseArg}': {ex.Message}");
        Environment.ExitCode = CliExit.CaseLoadFailure(ex);   // D-DOC-130: an unknown case name is 2, an unloadable file 1
        return;
    }

    string desc = $"chain  case={caseArg}  steps={steps}  mode={mode}" + (mode == "ramp" ? $"  ramp={rampPct}%" : "");
    foreach (string h in RunInfo.HeaderLines(desc)) Emit("    " + h);
    // D-DOC-057: the sidecar is named after the report (<report>.run-metadata.json), so reports sharing a folder no longer
    // replace each other's metadata.
    RunInfo.WriteJson(CliFiles.Output(RunInfo.MetadataPathFor(outPath), "run metadata"), desc);
    Emit("");
    Emit("Each step feeds the previous solved voltages in as the initial condition (warm start).");
    Emit($"mode=fixed: same operating point re-solved (expect iters->1, no drift).  " +
         "ramp: +{0}% load/step.  daily: 24h demand curve.".Replace("{0}", rampPct.ToString()));
    Emit("");
    Emit("| Step | Load x | Warm-start iters | Mismatch | Vmin | Vmax |");
    Emit("|-----:|-------:|-----------------:|---------:|-----:|-----:|");
    csv.WriteLine("step,load_factor,iters,mismatch,vmin,vmax,commit");

    // D04: the contingency family's one option set (already 100 iterations with Q-limits on here) and, new, the OLTC
    // loop around the shared dense/sparse engine (was a local 1,000). With no OLTCs in the model the loop is skipped.
    PowerFlowOptions opt = ContingencyAnalysis.StudyOptions;
    IPowerFlowSolver solver = ContingencyAnalysis.WithOltcLoop(backend.NewtonSolver(baseM));

    // Cold baseline for the warm-start speed-up comparison.
    int coldIters = solver.Solve(baseM, opt with { FlatStart = true }).Iterations;

    GridModel state = baseM;
    PowerFlowResult? prev = null;
    int maxIters = 0;
    for (int s = 0; s < steps; s++)
    {
        double factor = mode switch
        {
            "ramp" => 1.0 + rampPct / 100.0 * s,
            "daily" => LoadProfile.DailyFactor((24.0 * s / steps) % 24.0),
            _ => 1.0,
        };
        GridModel m = GridScenario.AtLoad(baseM, factor);
        if (prev is not null) m = GridScenario.WithSolvedVoltages(m, prev);   // warm start from last solve

        PowerFlowResult r = solver.Solve(m, opt);
        if (r.Converged) prev = r;                      // R221: only a converged state seeds the next step
        else Environment.ExitCode = 3;                  // R221: a diverged step fails the run
        // Step 0 is NOT warm-started (there is no previous solve to start from: it solves from the case's own
        // starting voltages), so it is left out of the warm-start maximum. Counting it made the fixed-mode footer
        // ("converges in <=1 iter") impossible to print, because step 0 always takes the cold number of iterations.
        if (s > 0) maxIters = Math.Max(maxIters, r.Iterations);
        Emit($"| {s} | {factor:F3} | {r.Iterations} | {r.MaxMismatch:E2} | {(r.Converged ? r.Vm.Min() : double.NaN):F3} | {(r.Converged ? r.Vm.Max() : double.NaN):F3} |");
        csv.WriteLine($"{s},{factor:F4},{r.Iterations},{r.MaxMismatch:E3},{(r.Converged ? r.Vm.Min() : double.NaN):F4},{(r.Converged ? r.Vm.Max() : double.NaN):F4},{RunInfo.GitCommit}");
    }
    Emit("");
    // The warm-started steps are 1..steps-1; with --steps 1 there are none, and the footer says so rather than
    // reporting a maximum over an empty set as 0 (which would read as a perfect warm start).
    int warmSteps = steps - 1;
    string warmText = warmSteps > 0
        ? $"Max warm-start iters over {warmSteps} warm-started step(s) (steps 1-{steps - 1}; step 0 starts from the case): {maxIters}."
        : "No warm-started step (--steps 1 runs step 0 only).";
    Emit($"Cold (flat-start) iters: {coldIters}.  {warmText}  " +
         $"{(mode == "fixed" && warmSteps > 0 && maxIters <= 1 ? "Warm start converges in <=1 iter with no drift - as expected." : "")}");
    Console.Error.WriteLine($"[chain] done -> {Path.GetFullPath(outPath)}");
}

// N177: the four HTI error columns of hti-removals.csv / hti-corrections.csv for one row, already joined with commas:
// the estimated error exactly as the estimator returns it (G17, internal units), the name of that unit for this row's
// kind (pu, rad or pu_base_mva), the same error in the measurement's own units, and that unit's name (pu, deg, MW,
// Mvar). Both unit names and the conversion come from HtiBadDataEstimation, the one rule the correct-in-place path
// also uses, so the labels cannot drift from the numbers. Formatted with the invariant culture (the CSV contract).
static string HtiErrorColumns(MeasurementKind kind, double estimatedError, double baseMva) =>
    string.Create(System.Globalization.CultureInfo.InvariantCulture,
        $"{estimatedError:G17},{HtiBadDataEstimation.InternalUnitName(kind)},{HtiBadDataEstimation.ToMeasurementUnits(kind, estimatedError, baseMva):G17},{HtiBadDataEstimation.MeasurementUnitName(kind)}");

// N177: the console text after "estimated error = " for one HTI row. Before October 2026 every row said "<x> pu",
// which was wrong for the angle rows (radians). Now the internal unit is named per row and, where the measurement's
// own unit differs (angles, powers), the converted value follows in brackets, e.g. "-0.0012 rad (-0.0687549 deg)" or
// "0.23808 pu_base_mva (23.808 MW)". Magnitude rows (VmPu, IMagPu) are pu in both and print as before: "<x> pu".
static string HtiErrorText(MeasurementKind kind, double estimatedError, double baseMva)
{
    string inside = HtiBadDataEstimation.InternalUnitName(kind);
    string outside = HtiBadDataEstimation.MeasurementUnitName(kind);
    var inv = System.Globalization.CultureInfo.InvariantCulture;
    string text = string.Create(inv, $"{estimatedError:G6} {inside}");
    if (inside != outside)
        text += string.Create(inv, $" ({HtiBadDataEstimation.ToMeasurementUnits(kind, estimatedError, baseMva):G6} {outside})");
    return text;
}

// The chi-square verdict as text: PASS / FAIL when the test ran, not-run when it did not (R261: a test that never ran
// - unobservable, non-converged, detection off, no redundancy - used to print PASS; N208, Ruling R1 follow-up
// 2026-10-04: it now says "not-run" in so many words, where it said "n/a"). One token, because it is printed as
// chi2=<verdict> among other key=value fields.
static string ChiText(GridSim.Core.Estimation.ChiSquareOutcome o) => o switch
{
    GridSim.Core.Estimation.ChiSquareOutcome.Passed => "PASS",
    GridSim.Core.Estimation.ChiSquareOutcome.Failed => "FAIL",
    _ => "not-run",
};

// True when a free token names a case rather than something else (a generator name for trip, an output path for
// export): an existing folder, a MATPOWER .m name, or one of LoadNamed's built-in names. It does not load anything.
// True when the file is a GridSim v2 JSON document whose "schema" tag is a case manifest ("gridsim-case/...").
// Used by `export` so a manifest argument is read as the case and never overwritten (docs-session DATA LOSS finding).
// A file that does not parse as JSON is simply not a manifest.
static bool IsGridSimCaseManifest(string path)
{
    try
    {
        using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllBytes(path));
        return doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Object
            && doc.RootElement.TryGetProperty("schema", out System.Text.Json.JsonElement tag)
            && tag.ValueKind == System.Text.Json.JsonValueKind.String
            && tag.GetString()!.StartsWith("gridsim-case/", StringComparison.Ordinal);
    }
    catch (System.Text.Json.JsonException) { return false; }
}

// True when the file is a scene that `export` wrote earlier (a JSON object with the VizScene arrays "buses",
// "branches" and "frames"), so re-running `export` onto its own previous output is allowed and anything else is not.
static bool IsGridVizScene(string path)
{
    try
    {
        using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllBytes(path));
        System.Text.Json.JsonElement root = doc.RootElement;
        return root.ValueKind == System.Text.Json.JsonValueKind.Object
            && root.TryGetProperty("buses", out System.Text.Json.JsonElement b) && b.ValueKind == System.Text.Json.JsonValueKind.Array
            && root.TryGetProperty("branches", out System.Text.Json.JsonElement br) && br.ValueKind == System.Text.Json.JsonValueKind.Array
            && root.TryGetProperty("frames", out System.Text.Json.JsonElement f) && f.ValueKind == System.Text.Json.JsonValueKind.Array;
    }
    catch (System.Text.Json.JsonException) { return false; }
}

// D-DOC-130: true when a case argument names no case at all: not an existing folder, not a MATPOWER .m path, not a JSON v2
// .json manifest path, and not a built-in name. That is exactly the argument LoadCaseArgument / LoadNamed answer with an
// UnknownCaseException ("unknown case ..."), so a verb can refuse it (exit 2) before it opens any output.
static bool NamesNoCase(string arg) =>
    !Directory.Exists(arg)
    && !arg.EndsWith(".m", StringComparison.OrdinalIgnoreCase)
    && !arg.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
    && !arg.EndsWith(".raw", StringComparison.OrdinalIgnoreCase)
    && !arg.EndsWith(".uct", StringComparison.OrdinalIgnoreCase)
    && !BuiltInCases.Names.Contains(arg.ToLowerInvariant());

static bool IsCaseArgument(string arg, string root)
{
    _ = root;   // the built-in names do not depend on the install folder; kept so callers read like LoadNamed's
    // GR-703: a .json argument is a JSON v2 case manifest (LoadNamed loads it), not a generator or other name.
    return Directory.Exists(arg)
        || arg.EndsWith(".m", StringComparison.OrdinalIgnoreCase)
        || arg.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
        || arg.EndsWith(".raw", StringComparison.OrdinalIgnoreCase)
        || arg.EndsWith(".uct", StringComparison.OrdinalIgnoreCase)
        || BuiltInCases.Names.Contains(arg.ToLowerInvariant());
}

// Resolve a named built-in/library case for the sweep/stress/chain verbs.
// The names here must match BuiltInCases.Names (Gated.cs) exactly (CliInputHandlingTests checks the two lists agree).
// A name ending ".m" goes to Gated.Matpower, which takes it as a path and otherwise finds it under data/matpower
// (by relative path such as "pegase/case1354pegase.m", or by bare file name searched through the subfolders).
GridModel LoadNamed(string name, string root) => name.ToLowerInvariant() switch
{
    "case9" or "ieee9" => IeeeCases.Case9(),
    "case14" => IeeeCases.Case14(),
    "case30" => IeeeCases.Case30(),
    "case57" => IeeeCases.Case57(),
    "case118" => IeeeCases.Case118(),
    "case300" => IeeeCases.Case300(),
    "case145" => IeeeCases.Case145(),
    "case24" or "rts" => IeeeCases.Case24Rts(),
    "cigre" => IeeeCases.CigreMv(),
    "uk" or "gb" or "gb-reduced" => Gated.Dir(Path.Combine(root, "data", "uk")),
    "gb-full" => Gated.Dir(Path.Combine(root, "data", "gb-full")),   // the real 3,539-bus GB case, not the synthetic
    // N316 (LF7, October 2026; Ruling R1, Mark delegated EE calls 2026-10-04: one name, one case). The name gb-synthetic
    // (alias synthetic, any case) is the SHIPPED folder data/gb-synthetic for every verb, loaded exactly as
    // --dir data/gb-synthetic: the same loader, the same licence / bundled-content check, the loader's dispatch balancing,
    // and the hand-authored asset-classes, asset-bindings and protections files. It used to call the in-memory builder
    // (SyntheticGb.Build), which is the same network field for field (R1EGbSyntheticTests) but differs in three ways a
    // result can see: the folder's branch order (lines before transformers, so a degenerate DC-OPF can stop at another
    // optimal vertex), the builder's unbalanced written dispatch (the folder is balanced on load, as every JSON case is),
    // and no asset / protection bundle (so trip --asset-dynamics was refused and impedance-stability saw no bound
    // inverter). Only trip had been switched (N238); a name meaning two networks depending on the verb is the defect.
    // The builder stays for `synth` (which writes this folder) and for the Core tests that pin the builder itself.
    "gb-synthetic" or "synthetic" => Gated.Dir(Path.Combine(root, "data", "gb-synthetic")),
    // S2 (October 2026): the published GB reference networks shipped under data/matpower/gb (provenance and licences in
    // its README.md). The two MATPOWER files load exactly as the same file given by path; pypsa-gb-reduced is PyPSA-GB's
    // own 29-bus network (its CSV files) with GBreducednetwork.m's demand and generation; pypsa-gb-zonal is a transport
    // model with no power flow, so it is REFUSED here (an input error naming the zonal verb), never solved.
    "gb-reduced-29" => Gated.Matpower(Path.Combine(root, "data", GridSim.Core.IO.PyPsa.GbReferenceModels.Gb29RelativePath)),
    "gb-network-2224" => Gated.Matpower(Path.Combine(root, "data", GridSim.Core.IO.PyPsa.GbReferenceModels.Gb2224RelativePath)),
    "pypsa-gb-reduced" => Gated.PypsaGbReduced(root),
    "pypsa-gb-zonal" => throw Gated.NotAcSolvable(name),
    // A MATPOWER file name. The old fallback looked only at the top level of data/matpower, which holds no .m file
    // (every shipped case is in a subfolder), so a bare name such as "case33bw.m" never loaded. Gated.Matpower now
    // resolves it: as given, then relative to data/matpower, then by file name through the subfolders.
    var m when m.EndsWith(".m", StringComparison.Ordinal) => Gated.Matpower(name),
    // N065 (October 2026, JSON v2 Phase 2): a .json file is a gridsim-case/2 manifest (with its network files and library
    // imports). A v1 case is still a folder, and stays the default everywhere.
    var j when j.EndsWith(".json", StringComparison.Ordinal) => Gated.V2Case(name, root),
    // Tranche A (October 2026): a PSS/E RAW file (revisions 33, 34, 35), taken as a path.
    var r when r.EndsWith(".raw", StringComparison.Ordinal) => Gated.Psse(name),
    // Tranche A (October 2026): a UCTE-DEF file, taken as a path.
    var u when u.EndsWith(".uct", StringComparison.Ordinal) => Gated.Ucte(name),
    // D-DOC-130: an UnknownCaseException (an ArgumentException, as before) so every load handler can tell "names no case
    // at all" (usage error, exit 2) from a missing or unloadable file (input error, exit 1): CliExit.CaseLoadFailure.
    _ => throw new UnknownCaseException($"unknown case '{name}' (built-in names: {string.Join(", ", BuiltInCases.Names.Order(StringComparer.Ordinal))}; " +
                                     "or a case folder, or a MATPOWER .m file, or a JSON v2 case manifest .json, or a PSS/E .raw file, or a UCTE-DEF .uct file)"),
};

// ---- Shared by the contingency verbs nminus1, nminus2 and n-1-1 (October 2026, D03, D04, F01) ----------------------
//
// D04: every contingency verb solves with ONE option set, ContingencyAnalysis.StudyOptions (100 iterations, reactive
// limits on), through an engine wrapped in the OLTC loop (ContingencyAnalysis.CreateStudySolver / WithOltcLoop), the
// same regulated steady state the default case solve reaches. They used to differ (30 iterations here, Q-limits off in
// the sweep, no OLTC loop anywhere).
//
// D03: the base case is solved first with the same solver and options. Its own violations are printed ONCE, as
// base-case violations, and netted out of every outage (ContingencyAnalysis.NetAgainstBase), so an outage is charged
// only with the violations it causes. A base case that does not converge cannot be netted and is a failure (exit 3),
// never a silent screen against an unsolved state.
//
// F01: the verbs used to exit 0 whatever they found. Now the exit code is the verdict: 0 when the base case and every
// screened outage are secure, 3 (the "validation failure" code of manual ch. 19) when anything is not: a base-case
// violation, an outage with violations, an outage that islands or does not solve, or (nminus2 / n-1-1) a single outage
// left out of the pairing because it already fails on its own.

// Solve and classify the base case for a contingency verb; null (with exit code 3 set and the reason on stderr) when it
// does not converge.
// GR-213: the contingency verbs' study solver (D04: the Newton engine by the shared rule, in the OLTC loop) on the
// backend the user selected. CPU: identical to ContingencyAnalysis.CreateStudySolver.
IPowerFlowSolver StudySolverOnBackend(GridModel model) => ContingencyAnalysis.WithOltcLoop(backend.NewtonSolver(model));

ContingencyResult? ContingencyBaseCase(string verb, GridModel model)
{
    // GR-213: the study solver on the selected backend (--cpu / --gpu), as nminus1-sweep and stress use. On the CPU this
    // is exactly CreateStudySolver (the sparse engine on the CPU sparse LU, wrapped in the OLTC loop), so CPU runs are
    // bit for bit what they were; before, these verbs solved on the CPU whatever --gpu said.
    ContingencyResult b = ContingencyAnalysis.ScreenBaseCase(model, StudySolverOnBackend(model), ContingencyAnalysis.StudyOptions with { PerBusVoltageLimits = busVlimits, PostFaultRating = postFaultRating });
    if (b.Converged) return b;
    Console.Error.WriteLine($"error: {verb}: the base case of {model.Name} did not converge ({string.Join("; ", b.Violations)}), " +
        "so no outage can be screened against it. Exit 3.");
    Environment.ExitCode = 3;
    return null;
}

// The base-case line printed once above every contingency table (D03).
static void PrintContingencyBaseCase(ContingencyResult b)
{
    if (b.Violations.Count == 0)
        Console.WriteLine("Base case: secure (no violation before any outage).");
    else
        Console.WriteLine($"Base case: {b.Violations.Count} pre-existing violation(s), reported once here and not counted against " +
            $"any outage: {string.Join("; ", b.Violations)}");
}

// The verdict line and exit code of a contingency verb (F01). 'failing' counts every screened outage that is not secure
// (violations after netting, islanded or unsolved) plus any single outage reported apart from the pairing.
static void ContingencyVerdict(ContingencyResult b, int failing)
{
    bool secure = b.Violations.Count == 0 && failing == 0;
    if (secure)
    {
        Console.WriteLine("Verdict: SECURE (exit 0).");
        return;
    }
    string why = b.Violations.Count > 0 && failing > 0 ? $"{b.Violations.Count} base-case violation(s) and {failing} insecure outage(s)"
        : b.Violations.Count > 0 ? $"{b.Violations.Count} base-case violation(s)"
        : $"{failing} insecure outage(s)";
    Console.WriteLine($"Verdict: NOT SECURE, {why} (exit 3).");
    Environment.ExitCode = 3;
}

// The single outages a pruned nminus2 / n-1-1 screen left out of the pairing because they already fail on their own
// (D02): listed here, apart from the pair table, instead of filling the candidate list.
static void PrintExcludedSingles(IReadOnlyList<ContingencyResult> excluded)
{
    if (excluded.Count == 0) return;
    Console.WriteLine($"{excluded.Count} single outage(s) left out of the pairing because they already fail at N-1 (islanded or no solution):");
    foreach (ContingencyResult c in excluded)
        Console.WriteLine($"  {Trunc(c.Outage, 30),-30}  {c.Violations[0]}");
}

// N124: who picks up a generator or bus outage's lost generation, for the outage detail line. The default wording is the
// F20 text, unchanged.
static string OutagePickup(OutageDispatch d) => d switch
{
    OutageDispatch.GovernorDroop => "shared by governor droop",
    OutageDispatch.Inertia => "shared by inertia",
    _ => "picked up by the reference",
};

void RunNMinus1(GridModel model)
{
    // F20: the default (branches only, rating A) prints and writes exactly what it always did; any other choice says so.
    bool typesDefault = outBranch && !outGen && !outBus;
    string kinds = string.Join(", ", new[] { outBranch ? "branch" : null, outGen ? "generator" : null, outBus ? "bus" : null }.Where(k => k is not null));
    Console.WriteLine(typesDefault
        ? $"GridSim  -  N-1 branch screening: {model.Name}"
        : $"GridSim  -  N-1 screening ({kinds} outages): {model.Name}");
    if (postFaultRating != PostFaultRating.RateA)
        Console.WriteLine($"Post-fault loading judged against rating {(postFaultRating == PostFaultRating.RateB ? "B (short-term)" : "C (emergency)")}, "
            + "rating A where a branch has none; the base case against rating A (NETS SQSS v2.10 2.9.1 / 5.1.8).");
    Console.WriteLine(new string('=', 74));
    ContingencyResult? baseCase = ContingencyBaseCase("nminus1", model);
    if (baseCase is null) return;
    PrintContingencyBaseCase(baseCase);
    Console.WriteLine("Outage                          Status        MaxLoad  WorstBnd  Vmin   Vmax");
    Console.WriteLine(new string('-', 74));

    // D04: the study solver (OLTC loop) and options; D03: netted against the base case.
    PowerFlowOptions studyOptions = ContingencyAnalysis.StudyOptions with { PerBusVoltageLimits = busVlimits, PostFaultRating = postFaultRating };
    var raw = new List<ContingencyResult>();
    // N349 (CF5): with --batched-lanes the branch outages go through the batched sweep, bit-identical to ScreenBranches
    // with the study solver (the OLTC loop on the sparse engine: oltcLoop true is exactly CreateStudySolver).
    if (outBranch && nminus1BatchedLanes is int lanesUsed)
    {
        Console.Error.WriteLine($"note: nminus1: branch outages solved by the batched sweep ({(lanesUsed == 0 ? "one lane per processor" : $"{lanesUsed} lane(s)")}; bit-identical to the sequential screen).");
        // GR-213: the batched sweep has only the CPU batched backend, so with a GPU selected its branch outages run on
        // the CPU; said rather than left implicit.
        if (backend.Device != SolverBackend.Vendor.Cpu)
            Console.Error.WriteLine($"note: nminus1: --batched-lanes runs on the CPU batched solver; the base case and any generator or bus outages use {backend.Description}.");
        raw.AddRange(ContingencyAnalysis.ScreenBranchesBatched(model, null, studyOptions, lanesUsed == 0 ? -1 : lanesUsed, null, oltcLoop: true));
    }
    else if (outBranch) raw.AddRange(ContingencyAnalysis.ScreenBranches(model, StudySolverOnBackend(model), studyOptions));   // GR-213
    if (outGen || outBus)
        raw.AddRange(ContingencyAnalysis.ScreenElementOutages(model, ContingencyAnalysis.SingleOutages(model, false, outGen, outBus),
            StudySolverOnBackend(model), studyOptions, outageDispatch));   // N124: reference (default), droop or inertia; GR-213 backend
    var results = ContingencyAnalysis.NetAgainstBase(raw, baseCase);
    int insecure = 0, islanded = 0, notSolved = 0;
    foreach (ContingencyResult c in results.OrderByDescending(c => c.Converged ? 0 : 2).ThenByDescending(c => c.Violations.Count))
    {
        string status = ContingencyStatus(c);
        if (!c.Converged) { if (c.Islanded) islanded++; else notSolved++; }   // N107: a split apart from a connected failure
        else if (!c.Secure) insecure++;
        Console.WriteLine(c.Converged
            ? $"{Trunc(c.Outage, 30),-30}  {status,-12}  {c.MaxBranchLoadingPercent,5:F0}%   {c.WorstBoundaryLoadingPercent,5:F0}%  {c.MinVm:F3}  {c.MaxVm:F3}"
            : $"{Trunc(c.Outage, 30),-30}  {status,-12}  {c.Violations[0]}");
        // F20: what a generator or bus outage took with it, and any reference move the re-solve needed.
        if (c.Kind != OutageKind.Branch && (c.LostLoadMw != 0 || c.LostGenerationMw != 0 || c.Note is not null))
            Console.WriteLine($"    {(c.LostLoadMw != 0 ? $"lost load {c.LostLoadMw:F1} MW  " : "")}{(c.LostGenerationMw != 0 ? $"lost generation {c.LostGenerationMw:F1} MW ({OutagePickup(outageDispatch)})  " : "")}{c.Note ?? ""}".TrimEnd());
    }

    Console.WriteLine(new string('-', 74));
    Console.WriteLine(ScreenedSummary(results.Count, insecure, islanded, notSolved));
    PrintBaseOnlyNote(results);
    // F10: the result file (when asked for), rows in the printed order.
    var ordered = results.OrderByDescending(c => c.Converged ? 0 : 2).ThenByDescending(c => c.Violations.Count).ToList();
    ReportContingency(model.Name, typesDefault ? "every branch" : $"every {kinds}", baseCase, ordered, Array.Empty<ContingencyResult>(), insecure + islanded + notSolved,
        typesDefault && postFaultRating == PostFaultRating.RateA ? null : postFaultRating.ToString());
    ContingencyVerdict(baseCase, insecure + islanded + notSolved);
}

// F10: the result file of the contingency verbs (nminus1, nminus2, n-1-1): the base case, the counts and the verdict
// (the same rule as ContingencyVerdict), every screened outage or pair with its status and netted violations (the
// console shows the worst --top for nminus2 / n-1-1), and the single outages left out of the pairing. A NOT SECURE
// verdict is a finished result (exit 3) and is written; a base case that did not converge never reaches here.
static void ReportContingency(string caseName, string scope, ContingencyResult baseCase, IReadOnlyList<ContingencyResult> results,
    IReadOnlyList<ContingencyResult> excluded, int failing, string? f20PostFaultRating = null)
{
    CliResult? rep = CliOutput.Report;
    if (rep is null) return;
    // F20: only when outage types or the post-fault rating were chosen (the default file layout is unchanged): the rating
    // used and, per outage, its kind, the load / generation it took and any reference move.
    if (f20PostFaultRating is not null)
    {
        rep.Set("post_fault_rating", f20PostFaultRating);
        CliResultTable kinds = rep.Table("outage_details", "outage", "kind", "lost_load_mw", "lost_generation_mw", "note");
        foreach (ContingencyResult c in results) kinds.Row(c.Outage, c.Kind.ToString(), c.LostLoadMw, c.LostGenerationMw, c.Note ?? "");
    }
    bool secure = baseCase.Violations.Count == 0 && failing + excluded.Count == 0;
    // N107: "islanded" counts the outages that split the network; "not_solved" the connected ones with no solution
    // (both used to be counted as islanded).
    int islanded = results.Count(c => !c.Converged && c.Islanded);
    int notSolved = results.Count(c => !c.Converged && !c.Islanded);
    int withViolations = results.Count(c => c.Converged && !c.Secure);
    rep.Set("case", caseName).Set("scope", scope)
        .Set("base_case_violations", baseCase.Violations.Count).Set("base_case_violation_list", string.Join("; ", baseCase.Violations))
        .Set("screened", results.Count).Set("secure", results.Count - withViolations - islanded - notSolved).Set("with_violations", withViolations)
        .Set("islanded", islanded).Set("not_solved", notSolved).Set("base_only", results.Count(c => c.Secure && c.PreExistingViolations.Count > 0))
        .Set("excluded_single_outages", excluded.Count).Set("verdict", secure ? "SECURE" : "NOT SECURE");
    CliResultTable outages = rep.Table("outages", "outage", "status", "converged", "max_loading_pct", "worst_boundary_pct", "vmin_pu", "vmax_pu",
        "new_violations", "violations", "pre_existing_violations");
    foreach (ContingencyResult c in results)
        outages.Row(c.Outage, ContingencyStatus(c), c.Converged,
            c.Converged ? c.MaxBranchLoadingPercent : null, c.Converged ? c.WorstBoundaryLoadingPercent : null,
            c.Converged ? c.MinVm : null, c.Converged ? c.MaxVm : null,
            c.Converged ? c.Violations.Count : null, string.Join("; ", c.Violations), string.Join("; ", c.PreExistingViolations));
    CliResultTable ex = rep.Table("excluded_single_outages", "outage", "reason");
    foreach (ContingencyResult c in excluded) ex.Row(c.Outage, c.Violations.Count > 0 ? c.Violations[0] : "");
    rep.Complete();
}

// The Status column of the contingency tables (D03). 'secure': the post-outage state violates nothing. 'base only':
// the outage adds no violation of its own, but the state still carries the base case's violations (netted, printed
// once in the base-case line); it counts as secure for the outage, and the base case itself fails the verdict.
// 'VIOLATIONxN': N violations the base case did not have. 'ISLANDED': no converged state, and the outage split the
// network. 'NO SOLUTION': no converged state on a network still in one piece (N107, October 2026: both used to read
// ISLANDED).
static string ContingencyStatus(ContingencyResult c) =>
    !c.Converged ? (c.Islanded ? "ISLANDED" : "NO SOLUTION")
    : !c.Secure ? $"VIOLATIONx{c.Violations.Count}"
    : c.PreExistingViolations.Count > 0 ? "base only"
    : "secure";

// The count line under a contingency table. N107 (October 2026): "islanded" counts only the outages that split the
// network; a connected non-convergence is counted as "not solved", shown only when there is one (so a run with none
// prints the line exactly as before).
static string ScreenedSummary(int screened, int insecure, int islanded, int notSolved)
    => $"{screened} outages screened  {screened - insecure - islanded - notSolved} secure  {insecure} with violations  {islanded} islanded"
       + (notSolved > 0 ? $"  {notSolved} not solved" : "");

// The footer note for 'base only' rows (D03), so the secure count is never read as "violation-free".
static void PrintBaseOnlyNote(IReadOnlyList<ContingencyResult> results)
{
    int baseOnly = results.Count(c => c.Secure && c.PreExistingViolations.Count > 0);
    if (baseOnly > 0)
        Console.WriteLine($"({baseOnly} of the secure outages are 'base only': they add no violation, but the base case's own " +
            "violations remain in their state)");
    // GR-125: a 'base only' outage that deepened a base-case violation is named, so a worsened overload is never hidden.
    foreach (ContingencyResult c in results.Where(c => c.Secure && c.WorsenedPreExistingViolations.Count > 0))
        Console.WriteLine($"  {c.Outage}: makes base-case violation(s) worse: {string.Join("; ", c.WorsenedPreExistingViolations)}");
}

void RunNMinus2(GridModel model, int candidates, bool exhaustive, int top)
{
    string scope = exhaustive ? "exhaustive (every pair)" : $"top-{candidates} candidate pairs";
    Console.WriteLine($"GridSim  -  N-2 branch screening: {model.Name}  [{scope}]");
    Console.WriteLine(new string('=', 74));
    ContingencyResult? baseCase = ContingencyBaseCase("nminus2", model);
    if (baseCase is null) return;
    PrintContingencyBaseCase(baseCase);
    if (!exhaustive)
        Console.WriteLine($"Screening N-1 first, then pairing the {candidates} most-stressed single outages that solve.");
    Console.WriteLine("Outage                          Status        MaxLoad  WorstBnd  Vmin   Vmax");
    Console.WriteLine(new string('-', 74));

    // D04 study solver and options; D02 the outages that already fail at N-1 come back apart from the pairs; D03 netting.
    NkScreenReport report = ContingencyAnalysis.ScreenNMinusKReport(model, 2, () => StudySolverOnBackend(model),   // GR-213
        ContingencyAnalysis.StudyOptions with { PerBusVoltageLimits = busVlimits, PostFaultRating = postFaultRating }, candidateCount: candidates, exhaustive: exhaustive);
    IReadOnlyList<ContingencyResult> netted = ContingencyAnalysis.NetAgainstBase(report.Results, baseCase);
    int failing = PrintNkTable(netted, top);
    if (report.Note is not null) Console.WriteLine($"No pairs screened: {report.Note}");
    PrintExcludedSingles(report.ExcludedSingleOutages);
    ReportContingency(model.Name, scope, baseCase, netted, report.ExcludedSingleOutages, failing);   // F10: the result file
    ContingencyVerdict(baseCase, failing + report.ExcludedSingleOutages.Count);
}

void RunNMinus1Minus1(GridModel model, int candidates, bool exhaustive, int top)
{
    string scope = exhaustive ? "exhaustive (every ordered pair)" : $"top-{candidates} candidates";
    Console.WriteLine($"GridSim  -  N-1-1 sequential screening: {model.Name}  [{scope}]");
    Console.WriteLine(new string('=', 74));
    ContingencyResult? baseCase = ContingencyBaseCase("n-1-1", model);
    if (baseCase is null) return;
    PrintContingencyBaseCase(baseCase);
    Console.WriteLine("Lose one element; if a line or boundary is then over its limit, redispatch the fewest MW that relieve it");
    Console.WriteLine("(DC model, island by island); then lose a second.");
    if (!exhaustive)
        Console.WriteLine($"First and second outages are the {candidates} most-stressed single outages that solve.");
    Console.WriteLine("Outage (first => second)        Status        MaxLoad  WorstBnd  Vmin   Vmax");
    Console.WriteLine(new string('-', 74));

    // D04 study solver and options; D01 / N069 default corrective action; D02 excluded singles; D03 netting.
    NkScreenReport report = ContingencyAnalysis.ScreenNMinus1Minus1Report(model, solverFactory: () => StudySolverOnBackend(model),   // GR-213
        options: ContingencyAnalysis.StudyOptions with { PerBusVoltageLimits = busVlimits, PostFaultRating = postFaultRating }, candidateCount: candidates, exhaustive: exhaustive);
    IReadOnlyList<ContingencyResult> netted = ContingencyAnalysis.NetAgainstBase(report.Results, baseCase);
    int failing = PrintNkTable(netted, top);
    if (report.Note is not null) Console.WriteLine($"No pairs screened: {report.Note}");
    PrintExcludedSingles(report.ExcludedSingleOutages);
    ReportContingency(model.Name, scope, baseCase, netted, report.ExcludedSingleOutages, failing);   // F10: the result file
    ContingencyVerdict(baseCase, failing + report.ExcludedSingleOutages.Count);
}

// Shared worst-first printer for the N-2 / N-1-1 tables (results already ordered worst-first). Returns how many of the
// screened combinations are not secure (violations or islanded), for the verdict.
static int PrintNkTable(IReadOnlyList<ContingencyResult> results, int top)
{
    int insecure = 0, islanded = 0, notSolved = 0, shown = 0;
    foreach (ContingencyResult c in results)
    {
        if (!c.Converged) { if (c.Islanded) islanded++; else notSolved++; }   // N107
        else if (!c.Secure) insecure++;
        if (shown++ >= top) continue;
        string status = ContingencyStatus(c);
        Console.WriteLine(c.Converged
            ? $"{Trunc(c.Outage, 30),-30}  {status,-12}  {c.MaxBranchLoadingPercent,5:F0}%   {c.WorstBoundaryLoadingPercent,5:F0}%  {c.MinVm:F3}  {c.MaxVm:F3}"
            : $"{Trunc(c.Outage, 30),-30}  {status,-12}  {c.Violations[0]}");
    }

    Console.WriteLine(new string('-', 74));
    if (results.Count > top)
        Console.WriteLine($"(showing worst {top} of {results.Count})");
    Console.WriteLine(ScreenedSummary(results.Count, insecure, islanded, notSolved));
    PrintBaseOnlyNote(results);
    return insecure + islanded + notSolved;
}

void RunScreen(GridModel model, int top, string? csvPath = null)
{
    // D-DOC-066 (October 2026, docs-session finding): a case with no inertia data (every generator H = 0, as in the IEEE
    // MATPOWER cases, which carry no machine data) used to screen "successfully": RocofScreening floors the remaining
    // inertia at 1 MWs to avoid a division by zero, so every loss came out at an absurd RoCoF (case14: -5810 Hz/s) with
    // no word that the number is the floor's artefact, and the CSV carried it as data. With no inertia at all there is
    // nothing to screen, so it is refused: exit 1 (the input lacks the data the study needs), before anything is printed
    // or written. The sum is the same one RocofScreening.Screen(model) uses: N321 (LF7, October 2026; Ruling R1), the N289
    // rotating-mass total GridModel.SystemInertiaMwS, as trip uses since N314 (it used to be H x MBase over EVERY unit, so a
    // converter-typed unit with H > 0 counted here and nowhere else). For every bundled case the two sums are the same
    // terms in the same order, bit for bit. A case whose only H sits on converter-typed units now has no rotating mass
    // and is refused like a case with no H at all (it used to screen against the converters' synthetic-inertia figures).
    double totalInertiaMwS = model.SystemInertiaMwS;
    if (!(totalInertiaMwS > 0.0))
    {
        Console.Error.WriteLine($"error: screen: case '{model.Name}' carries no inertia data (no in-service rotating machine has H > 0; " +
            "converter-type units count no inertia), " +
            "so the RoCoF of a loss cannot be computed; the screen would report the 1 MWs inertia floor's artefact. " +
            "Use a case with generator inertia constants (for example uk or gb-synthetic). Exit 1.");
        Environment.ExitCode = CliExit.InputError;
        return;
    }
    IReadOnlyList<RocofScreeningResult> results = RocofScreening.Screen(model);
    double totalGva = model.SystemInertiaGvaS;   // N321: the same total / 1000, exactly the old expression for every bundled case
    double demand = model.Buses.Sum(b => b.Pd);

    Console.WriteLine($"GridSim  -  N-1 RoCoF screening: {model.Name}");
    Console.WriteLine(new string('=', 74));
    // N297 (B4, October 2026; Ruling R1: Mark delegated EE calls 2026-10-04; B2's band convention, FrequencyBands): the
    // screen grades against the GB bands about the case's own nominal, so the printed limits are those bands' edges. At
    // 50 Hz they are the constants themselves and print exactly as before ("statutory 49.5 Hz", "<49.5 Hz").
    FrequencyBands screenBands = FrequencyBands.ForModel(model);
    string statLabel = FrequencyBands.Label(screenBands.StatutoryLowHz);
    Console.WriteLine($"System inertia {totalGva:F1} GVAs  demand {demand / 1000:F2} GW  limits: RoCoF 0.125 Hz/s, statutory {statLabel} Hz");
    // N275 (October 2026, stream B1): the screen integrates at the case's own nominal frequency (RoCoF = f0 * dP / 2E).
    // N297 (B4): on a case that is not 50 Hz the GB statutory and LFDD bands are now evaluated about its nominal (they
    // were skipped: graded against 49.5 / 48.8 Hz, which a 60 Hz nadir never reaches). Printed only for such a case, so
    // 50 Hz output is unchanged.
    if (model.FrequencyHz != FrequencyLimits.NominalHz)
        Console.WriteLine($"note: '{model.Name}' runs at {model.FrequencyHz:0.###} Hz: RoCoF is screened at {model.FrequencyHz:0.###} Hz and the nadir is graded " +
                          $"against the GB bands about it (statutory {statLabel} Hz, LFDD {FrequencyBands.Label(screenBands.LfddFirstStageHz)} Hz).");
    Console.WriteLine(new string('-', 74));
    Console.WriteLine("Lost infeed                       MW   Inertia(rem)   RoCoF   Nadir   Verdict");
    Console.WriteLine(new string('-', 74));

    int breaches = 0;
    for (int i = 0; i < results.Count; i++)
    {
        RocofScreeningResult r = results[i];
        if (r.RocofBreach || r.StatutoryBreach || r.LfddRisk) breaches++;
        if (i >= top) continue;
        string verdict = r.LfddRisk ? "LFDD RISK" : r.StatutoryBreach ? $"<{statLabel} Hz" : r.RocofBreach ? ">0.125 Hz/s" : "ok";
        Console.WriteLine($"{Trunc(r.Name, 30),-30}  {r.LostMw,5:F0}   {r.RemainingInertiaGvaS,6:F1} GVAs  {r.InitialRocofHzPerS,6:F3}  {r.NadirHz,6:F2}  {verdict}");
    }

    Console.WriteLine(new string('-', 74));
    string worst = results.Count > 0 ? $"{results[0].InitialRocofHzPerS:F3} Hz/s ({Trunc(results[0].Name, 28)})" : "n/a";
    Console.WriteLine($"{results.Count} credible single losses screened  {breaches} breach a limit  worst RoCoF {worst}");
    if (results.Count > 0)
    {
        RocofScreeningResult b = results[0];
        double floor = InertiaEstimator.EstimateInertiaGvaS(b.LostMw, FrequencyLimits.RocofLimitHzPerS);
        Console.WriteLine($"binding case needs >= {floor:F1} GVAs spinning for 0.125 Hz/s " +
                          $"(has {b.RemainingInertiaGvaS:F1}, headroom {b.RemainingInertiaGvaS - floor:+0.0;-0.0} GVAs)");
    }

    // D-DOC-066: a single loss that takes (nearly) all of the system's inertia with it leaves less than the 1 MWs floor
    // RocofScreening applies, so that row's RoCoF and nadir are the floor's artefact, not physics. Flagged by name on
    // stderr (the rows, the CSV and the verdict are unchanged: such a loss does breach every limit).
    // N325 (DOC-17): each loss removes only its rotating-mass share (GridModel.RotatingInertiaMwS), exactly as
    // RocofScreening.Screen(model) does since N321, so this list names the same rows the screen floors; it used to
    // subtract H x MBase, so a converter-typed unit with H > 0 could be named here while the screen did not floor it.
    List<string> floored = model.Generators.Where(g => g.Pg > 0 && totalInertiaMwS - GridModel.RotatingInertiaMwS(g) < 1.0)
        .Select(g => g.Name ?? $"gen@{g.Bus}").ToList();
    if (floored.Count > 0)
        Console.Error.WriteLine($"warning: screen: {floored.Count} loss(es) leave less than 1 MWs of inertia, so their RoCoF and nadir " +
            $"are the 1 MWs floor's artefact, not a physical value: {string.Join(", ", floored.Take(10))}{(floored.Count > 10 ? ", ..." : "")}.");
    // Losses that leave too little inertia to integrate the swing stably at the screen's step: their RoCoF is the
    // closed form f0*P/(2E), their nadir is unknown (NaN) and every limit is reported breached.
    List<string> notIntegrated = results.Where(r => !r.Integrated).Select(r => r.Name).ToList();
    if (notIntegrated.Count > 0)
        Console.Error.WriteLine($"warning: screen: {notIntegrated.Count} loss(es) leave too little inertia to integrate the swing at this step; " +
            $"RoCoF is the closed-form initial value, the nadir is not known (NaN), and every limit is reported breached: " +
            $"{string.Join(", ", notIntegrated.Take(10))}{(notIntegrated.Count > 10 ? ", ..." : "")}.");

    if (!string.IsNullOrEmpty(csvPath))
    {
        using var w = new StreamWriter(CliFiles.Output(csvPath, "screen CSV"));   // D-DOC-072: through the one output policy
        // N076 (October 2026, a CSV contract change): the fourth column is the PEAK |df/dt| over the simulated run (what the
        // console's RoCoF column and the 0.125 Hz/s limit test use), so it is named peak_rocof_hz_per_s. It was called
        // initial_rocof_hz_per_s, which promised the t = 0+ value. Same numbers, same position; only the header changed.
        w.WriteLine("name,lost_mw,remaining_inertia_gva_s,peak_rocof_hz_per_s,nadir_hz,rocof_breach,statutory_breach,lfdd_risk");
        foreach (RocofScreeningResult r in results)
            w.WriteLine($"{Csv(r.Name)},{r.LostMw:F1},{r.RemainingInertiaGvaS:F2},{r.InitialRocofHzPerS:F4},{r.NadirHz:F3},{r.RocofBreach},{r.StatutoryBreach},{r.LfddRisk}");
        Console.WriteLine($"Screening -> {Path.GetFullPath(csvPath)} ({results.Count} rows)");
    }

    // F01 (October 2026): the verdict is the exit code. screen used to exit 0 even when losses breached a limit, so a
    // script could not tell a failing screen from a passing one. Any loss that breaches a limit (LFDD risk, below the
    // statutory 49.5 Hz, or above the 0.125 Hz/s RoCoF limit, the verdicts printed above) now exits 3, the "validation
    // failure" code of manual ch. 19; a clean screen exits 0. The CSV, when asked for, is written first either way.
    if (breaches > 0)
    {
        Console.WriteLine($"Verdict: NOT SECURE, {breaches} of {results.Count} single loss(es) breach a limit (exit 3).");
        Environment.ExitCode = 3;
    }
    else
    {
        Console.WriteLine("Verdict: SECURE (exit 0).");
    }
}

static string Csv(string s) => s.Contains(',') || s.Contains('"')
    ? "\"" + s.Replace("\"", "\"\"") + "\""
    : s;

void RunDomains(GridModel model)
{
    (var domains, DominanceReport dom) = DomainAssignment.Assign(model);
    string delta = double.IsInfinity(dom.DeltaGVa) ? "sole domain" : dom.DeltaGVa.ToString("P0");
    Console.WriteLine($"GridSim  -  SPEED DOMAINS on {model.Name}");
    Console.WriteLine(new string('=', 66));
    Console.WriteLine($"{domains.Count} speed domains  *  deltaGVa {delta}  *  " +
        (dom.HasDominant ? $"dominant = Domain {dom.DominantDomainId}"
                         : "no dominant domain (inertia too evenly spread - the LOS fragmentation mode)"));
    Console.WriteLine();
    Console.WriteLine($"{"Domain",-9}{"Speed",-14}{"Kind",-18}{"Mach",5}{"GVA.s",11}{"GVad GVA",11}");
    foreach (SpeedDomain d in domains.OrderByDescending(x => x.Gvad))
    {
        string speed = d.Poles > 0 ? $"{d.Poles}p/{d.Rpm:F0}rpm" : "inverter";
        Console.WriteLine($"Domain {d.Id,-2}{speed,-14}{d.Kind,-18}{d.MemberGenIndices.Count,5}" +
                          $"{d.AggregateInertiaGvaS,11:F2}{d.Gvad / 1000.0,11:F2}" +
                          (dom.DominantDomainId == d.Id ? "  *" : ""));
    }
    Console.WriteLine();
    Console.WriteLine("GVad = apparent-power stiffness sum(S*C); GVA.s = real spinning inertia. A domain is dominant");
    Console.WriteLine("when deltaGVa >= 10% (LOS sec. 5.5). Distributed model: spatial spread & propagation are unvalidated at scale.");
    // F10: every domain, as printed (GVad in MVA as the model holds it; the console shows it divided by 1,000 as GVA).
    // deltaGVa is Infinity when there is a sole domain.
    CliResult? rep = CliOutput.Report;
    if (rep is not null)
    {
        rep.Set("case", model.Name).Set("domains", domains.Count).Set("delta_gva", dom.DeltaGVa).Set("threshold", dom.Threshold)
            .Set("has_dominant", dom.HasDominant).Set("dominant_domain", dom.DominantDomainId);
        CliResultTable t = rep.Table("domains", "id", "poles", "rpm", "kind", "machines", "inertia_gva_s", "gvad_mva", "dominant");
        foreach (SpeedDomain d in domains.OrderByDescending(x => x.Gvad))
            t.Row(d.Id, d.Poles, d.Rpm, d.Kind.ToString(), d.MemberGenIndices.Count, d.AggregateInertiaGvaS, d.Gvad, dom.DominantDomainId == d.Id);
        rep.Complete();
    }
}

// The WSCC-9 Anderson-Fouad X'd per generator (aligned to model.Generators, machine base), with the synthetic default
// for any unit whose bus is not in the table; anySynthetic is true when at least one unit took the default. Shared by
// the classical stability screen, the classical stability study and the impedance-stability modal cross-check
// (D-DOC-134), so all read the one map.
static double[] Wscc9XdpByGenerator(GridModel model, out bool anySynthetic)
{
    var byBus = IeeeCases.Wscc9TransientReactancePu;
    var xdp = new double[model.Generators.Count];
    anySynthetic = false;
    for (int i = 0; i < xdp.Length; i++)
    {
        if (byBus.TryGetValue(model.Generators[i].Bus, out double v)) xdp[i] = v;
        else { xdp[i] = GridSim.Cli.CliDefaults.SyntheticXdpPu; anySynthetic = true; }
    }
    return xdp;
}

void RunStabilityScreen(GridModel model, string label, MachineDynamicsSet? dyn = null)
{
    // N314 (LF5): with a dynamics file, the machines it binds take its inertia H through a model copy (H enters no
    // power-flow equation, so the solve below is the same solve), and its X'd and damping further down.
    if (dyn is not null) model = DynDataCli.WithFileInertia(model, dyn);
    PowerFlowResult pf = backend.NewtonSolver(model).Solve(model);   // shared rule on the selected backend (was CPU dense always; R104)
    // A non-converged solve is a failure, not a clean run - exit non-zero so scripts don't read the empty
    // screen as "all secure".
    if (!pf.Converged) { Console.Error.WriteLine("error: stability: power flow did not converge."); Environment.ExitCode = 3; return; }

    double[]? xdp = null; bool syntheticXdp = true;
    // D-DOC-134: the same map the impedance-stability cross-check now uses, built by one shared helper (the values and
    // the synthetic flag are exactly what this block built inline before).
    if (label == "WSCC-9") xdp = Wscc9XdpByGenerator(model, out syntheticXdp);
    // N314 (LF5): the dynamics file's X'd and damping for the machines it binds (the rule modal uses, ClassicalDynData).
    double[]? screenDamping = null;
    if (dyn is not null) (xdp, screenDamping, syntheticXdp) = ClassicalDynData(model, label, xdp, dyn);

    var genBuses = new List<int>();
    foreach (Generator gg in model.Generators) if (!genBuses.Contains(gg.Bus)) genBuses.Add(gg.Bus);

    // D-DOC-133 (docs-session finding, Ruling R1: Mark delegated 2026-10-04): the header used to print
    // model.Generators.Count as "machines", held units included ("29 machines" on data/uk, where the study integrates
    // 13 and holds 16). The screen runs with holdNonMachines: true, so the machines are the units ClassicalInit integrates
    // and the rest are held as constant injections; count them with ClassicalInit's own classification and say both,
    // in the single-bus run's wording. The fault list (every distinct generator bus, held units' buses included) and
    // every CCT are unchanged.
    int screenMachines = model.Generators.Count(g => !ClassicalInit.IsNonMachine(g));
    Console.WriteLine($"GridSim  -  TRANSIENT STABILITY SCREEN (classical multi-machine)  *  {label}");
    Console.WriteLine(new string('=', 66));
    Console.WriteLine($"{screenMachines} machines ({model.Generators.Count - screenMachines} converter / power-flow-only / zero-inertia units held)  *  " +
                      $"{genBuses.Count} generator-bus faults  *  " +
                      $"X'd = {(dyn is not null ? ClassicalDynXdpText(dyn, label, syntheticXdp, screenMachines) : syntheticXdp ? $"synthetic {GridSim.Cli.CliDefaults.SyntheticXdpPu:F2} pu" : "Anderson-Fouad")}");
    if (dyn is not null) PrintClassicalDynDataLines(dyn);
    Console.WriteLine();

    var results = new List<(int Bus, double Cct, CctBracket Bracket)>();
    // R007 (stream P, October 2026): one FaultScreen for the whole screen, so the augmented network and the UNFAULTED
    // reduction (identical for every fault bus) are built once instead of once per bus; only the faulted reduction is
    // redone per bus. Every bracket is bit for bit the one the per-bus CriticalClearingBracket(model, pf, xdp, b, ...)
    // call gave (ClassicalInit.FaultScreen). Making the screen computes nothing, so a model with no generator bus
    // behaves as before.
    ClassicalInit.FaultScreen screen = ClassicalInit.PrepareFaultScreen(model, pf, xdp, holdNonMachines: true);
    foreach (int b in genBuses)
    {
        CctBracket br = ClassicalInit.CriticalClearingBracket(screen, b, machineDamping: screenDamping);   // N314: null = undamped, as always
        results.Add((b, br.StableSeconds, br));
    }
    GridSim.Core.Numerics.FrozenIntroSort.Sort(results, (a, c) => a.Cct.CompareTo(c.Cct));   // worst (lowest CCT) first; GR-867: frozen introsort, one tie order on every runtime

    Console.WriteLine($"{"Rank",5}{"Fault bus",11}{"CCT (ms)",11}");
    for (int i = 0; i < results.Count; i++)
        Console.WriteLine($"{i + 1,5}{results[i].Bus,11}{results[i].Cct * 1000.0,11:F0}" +
                          (i == 0 ? "   <- most critical" : "") + CctPocketNote(results[i].Bracket));
    Console.WriteLine();
    Console.WriteLine("Self-clearing 3-phase fault at each generator bus; lower critical clearing time = less margin.");
    Console.WriteLine(ClassicalCctMeaning());   // N042: what the step-quantised number means
    if (syntheticXdp)
        Console.WriteLine("Provenance: X'd is a synthetic default - the screen is INDICATIVE, not validated.");
    else if (dyn is not null && !ClassicalDynDataIsValidated(dyn))
        Console.WriteLine("Provenance: the machine data file's values are not all Recorded / DerivedFromRecorded - the screen is INDICATIVE, not validated.");
}

// N314 (LF5, October 2026; ruled by main, Ruling R1): the classical engines (stability single bus and --screen) take a
// gridsim-dynamics/2 file exactly as modal does. The classical swing is built from three numbers per machine: X'd (machine
// base, as the Anderson-Fouad map), H and the damping D (per unit on the system base, the same quantity as the RMS study's
// and modal's: every engine integrates d omegabar / dt = (Pm - Pe - D omegabar) / 2H). A machine the file binds takes all
// three from it; every other machine keeps the verb's X'd map (or the synthetic default) and D = 0, so a file binding no
// machine changes nothing. X'd stays "synthetic" only where a synchronous machine is neither bound by the file nor in the
// Anderson-Fouad map (modal's rule). Returns the X'd array, the per-generator damping and the synthetic flag.
(double[] Xdp, double[] Damping, bool Synthetic) ClassicalDynData(GridModel model, string label, double[]? baseXdp, MachineDynamicsSet dyn)
{
    var afMap = IeeeCases.Wscc9TransientReactancePu;
    bool synthetic = model.Generators.Select((g, i) => (g, i)).Any(x =>
        !ClassicalInit.IsNonMachine(x.g) && dyn.For(x.i) is null && !(label == "WSCC-9" && afMap.ContainsKey(x.g.Bus)));
    return (DynDataCli.TransientReactance(model, baseXdp, dyn), DynDataCli.Damping(model, null, dyn), synthetic);
}

// N314: the header's X'd text for a classical run with a dynamics file: how many machines it covers and where the rest
// came from (modal's wording).
static string ClassicalDynXdpText(MachineDynamicsSet dyn, string label, bool syntheticXdp, int machineCount) =>
    $"{dyn.Entries.Count} from {Path.GetFileName(dyn.Path)}"
    + (syntheticXdp ? $", the rest synthetic {GridSim.Cli.CliDefaults.SyntheticXdpPu:F2} pu (unvalidated)"
       : label == "WSCC-9" && dyn.Entries.Count < machineCount ? ", the rest Anderson-Fouad" : "");

// N314: what the file brought to the classical model, its provenance, and the loader's notes (modal's lines).
static void PrintClassicalDynDataLines(MachineDynamicsSet dyn)
{
    Console.WriteLine($"machine data: '{dyn.Name}'  *  H, X'd and damping of {dyn.Entries.Count} machine(s) from the file (its subtransient "
        + "data, exciters and governors are not part of the classical model; stability --rms uses them)  *  provenance: "
        + string.Join(", ", dyn.Entries.SelectMany(e => e.Provenance).Distinct().OrderBy(t => t)));
    foreach (MachineDynamicsEntry e in dyn.Entries)
        foreach (string note in e.Notes) Console.WriteLine($"  note: generator {e.GeneratorLabel}: {note}");
}

// N314: modal's rule for a classical result with a dynamics file: the caller already prints the INDICATIVE line for a
// synthetic X'd; otherwise the result stays indicative unless every value in the file is tagged Recorded or
// DerivedFromRecorded (MachineDynamicsSet.AllRecorded, the RMS study's rule).
static bool ClassicalDynDataIsValidated(MachineDynamicsSet dyn) => dyn.AllRecorded;

// RMS transient stability on the salient/subtransient fleet (P1-2). GENROU parameters are synthesised from
// X'd here (the CLI cases carry no machine dynamics), so the result is INDICATIVE, exactly as the classical
// screen flags its synthetic X'd - the engine itself is validated (technical manual ch. 24).
void RunRmsStability(GridModel model, string label, bool screen, int? faultBusArg, double? clearMs = null,
    string avr = "none", bool pss = false, string? dynData = null,
    IReadOnlyList<GridSim.Core.Dynamics.Models.RmsEvent>? rmsEvents = null, IReadOnlyList<int>? clearByTrip = null,
    string? eventsOut = null, int eventsEvery = 1)
{
    // Large cases (gb-full) use the sparse solver, as the fault verb does; the dense NR is minutes there.
    // Shared dense/sparse rule on the selected backend (R003: below 3,000 buses this built a CPU dense NR directly,
    // dropping --gpu and the 100-iteration cap the sparse branch had).
    PowerFlowResult pf = backend.NewtonSolver(model).Solve(model, new PowerFlowOptions { MaxIterations = 100 });
    if (!pf.Converged) { Console.Error.WriteLine("error: stability: power flow did not converge."); Environment.ExitCode = 3; return; }

    // F23 (October 2026, stream B3): the machine dynamic data file, validated against the v2 schemas and bound to this
    // case's generators before any study. A file that is missing or wrong is an input error (exit 1), naming every problem.
    MachineDynamicsSet? dyn = null;
    if (dynData is not null)
    {
        string? schemasDir = FindV2Schemas(baseDir);
        if (schemasDir is null)
        {
            Console.Error.WriteLine("error: stability: --dyn-data needs the v2 schemas (schemas/v2 beside the program or above it), and none was found.");
            Environment.ExitCode = 1;
            return;
        }
        try { dyn = LoadMachineDynamics(dynData, schemasDir, model); }
        catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or DirectoryNotFoundException)
        {
            Console.Error.WriteLine($"error: stability: --dyn-data: {ex.Message}");
            Environment.ExitCode = 1;
            return;
        }
    }

    var byBus = IeeeCases.Wscc9TransientReactancePu;   // WSCC-9 X'd
    bool wscc9 = label == "WSCC-9";
    var data = new List<SubtransientInit.MachineData>();
    foreach (Generator gen in model.Generators)
    {
        // F23: a machine the dynamics file binds takes the file's data (its own GENROU parameters, damping, saturation and
        // governor); every other machine keeps the synthesised, indicative data below, exactly as before.
        if (dyn?.For(data.Count) is { } fileEntry) { data.Add(fileEntry.Data); continue; }
        double xdp = wscc9 && byBus.TryGetValue(gen.Bus, out double v) ? v : GridSim.Cli.CliDefaults.SyntheticXdpPu;
        // Typical GENROU ratios off X'd - a synthesised, clearly-indicative machine.
        data.Add(new SubtransientInit.MachineData(
            H: gen.H, Damping: GridSim.Cli.CliDefaults.SyntheticMachineDamping,
            Xd: GridSim.Cli.CliDefaults.GenrouXdOverXdp * xdp, Xdp: xdp, Xdpp: GridSim.Cli.CliDefaults.GenrouXdppOverXdp * xdp,
            Xq: GridSim.Cli.CliDefaults.GenrouXqOverXdp * xdp, Xqp: GridSim.Cli.CliDefaults.GenrouXqpOverXdp * xdp,
            Xqpp: GridSim.Cli.CliDefaults.GenrouXqppOverXdp * xdp,
            Tdop: GridSim.Cli.CliDefaults.GenrouTdopS, Tdopp: GridSim.Cli.CliDefaults.GenrouTdoppS,
            Tqop: GridSim.Cli.CliDefaults.GenrouTqopS, Tqopp: GridSim.Cli.CliDefaults.GenrouTqoppS));
    }
    // WECC (expansion): a converter unit the DYR file gives a WECC renewable chain (REGC_A + REEC_A/B/C) carries it in its
    // data; the study then drives it with that chain (and treats it as converter plant whatever its case type).
    if (dyn is not null)
        foreach (var kv in dyn.Renewables) data[kv.Key] = data[kv.Key] with { Renewable = kv.Value };

    var genBuses = new List<int>();
    foreach (Generator gg in model.Generators) if (!genBuses.Contains(gg.Bus)) genBuses.Add(gg.Bus);

    // R061: one exciter per synchronous machine (null for converter, power-flow-only and zero-inertia units, which
    // the study holds), aligned to model.Generators. Typical, clearly indicative settings (as the GENROU data).
    // null for --avr none, so the study takes exactly its old path.
    List<RmsExciter?>? exciters = null;
    if (avr != "none")
    {
        exciters = new List<RmsExciter?>(model.Generators.Count);
        foreach (Generator gen in model.Generators)
        {
            bool machine = !gen.PowerFlowOnly && !SubtransientInit.IsConverterUnit(gen, data[exciters.Count]) && gen.H > 0;
            if (!machine) { exciters.Add(null); continue; }
            Pss1a? stabiliser = pss ? new Pss1a(GridSim.Cli.CliDefaults.Pss1aGain, GridSim.Cli.CliDefaults.Pss1aWashoutS,
                    GridSim.Cli.CliDefaults.Pss1aLead1S, GridSim.Cli.CliDefaults.Pss1aLag1S, GridSim.Cli.CliDefaults.Pss1aLead2S, GridSim.Cli.CliDefaults.Pss1aLag2S,
                    GridSim.Cli.CliDefaults.Pss1aOutputMinPu, GridSim.Cli.CliDefaults.Pss1aOutputMaxPu) : null;
            exciters.Add(avr == "sexs"
                ? RmsExciter.FromSexs(GridSim.Cli.CliDefaults.SexsLeadS, GridSim.Cli.CliDefaults.SexsLagS, GridSim.Cli.CliDefaults.SexsGain, GridSim.Cli.CliDefaults.SexsExciterTimeS,
                    fieldMinPu: GridSim.Cli.CliDefaults.SexsFieldMinPu, fieldMaxPu: GridSim.Cli.CliDefaults.SexsFieldMaxPu, stabiliser: stabiliser)
                : RmsExciter.FromIeeet1(GridSim.Cli.CliDefaults.Ieeet1RegulatorGain, GridSim.Cli.CliDefaults.Ieeet1RegulatorTimeS, GridSim.Cli.CliDefaults.Ieeet1ExciterConstant,
                    GridSim.Cli.CliDefaults.Ieeet1ExciterTimeS, GridSim.Cli.CliDefaults.Ieeet1FeedbackGain, GridSim.Cli.CliDefaults.Ieeet1FeedbackTimeS,
                    GridSim.Cli.CliDefaults.Ieeet1RegulatorMinPu, GridSim.Cli.CliDefaults.Ieeet1RegulatorMaxPu, stabiliser: stabiliser));
        }
    }
    // F23: a machine whose dynamics-file template names an exciter takes that exciter (with its stabiliser, if any), a
    // fresh instance per machine; --avr (and --pss) then fill only the machines the file gives no exciter.
    int fileExciters = 0;
    if (dyn is not null && dyn.Entries.Any(e => e.Exciter is not null))
    {
        exciters ??= Enumerable.Repeat<RmsExciter?>(null, model.Generators.Count).ToList();
        foreach (MachineDynamicsEntry e in dyn.Entries)
            if (e.Exciter is not null) { exciters[e.GeneratorIndex] = e.Exciter.Create(); fileExciters++; }
    }

    Console.WriteLine($"GridSim  -  RMS TRANSIENT STABILITY (salient/subtransient GENROU)  *  {label}");
    Console.WriteLine(new string('=', 66));
    int pfOnly = model.Generators.Count(g => g.PowerFlowOnly);
    int convCount = model.Generators.Select((g, k) => (g, k)).Count(x => !x.g.PowerFlowOnly && SubtransientInit.IsConverterUnit(x.g, data[x.k]));
    int weccCount = data.Count(d => d.Renewable is not null);
    // F23: a unit is integrated when its data (the file's or the case's) has inertia; with no file this is gen.H as before.
    int held = model.Generators.Select((g, k) => (g, k)).Count(x => !x.g.PowerFlowOnly && !SubtransientInit.IsConverterUnit(x.g, data[x.k]) && !(data[x.k].H > 0));
    int machineCount = model.Generators.Count - pfOnly - convCount - held;
    int fromFile = dyn?.Entries.Count ?? 0;
    string fieldText = avr == "none" ? "held (no AVR)" : avr.ToUpperInvariant() + (pss ? " + PSS1A" : "");
    if (fileExciters > 0)
        fieldText = $"{fileExciters} exciter(s) from the dynamics file" + (avr == "none" ? ", the rest held" : $", {fieldText} on the rest");
    string paramText = dyn is null ? "GENROU params synthesised from X'd"
        : fromFile == machineCount ? $"GENROU params from {Path.GetFileName(dyn.Path)}"
        : $"GENROU params: {fromFile} from {Path.GetFileName(dyn.Path)}, {machineCount - fromFile} synthesised from X'd";
    Console.WriteLine($"{machineCount} machines  *  6-state machines  *  field: {fieldText}  *  {paramText}");
    if (dyn is not null)
    {
        // F23: what the file brought, its provenance, and anything taken from the case instead of the file.
        int governed = dyn.Entries.Count(e => e.Data.Governor is not null);
        string governors = governed == 0 ? "no governors (mechanical power held)"
            : $"{governed} governor(s) ({string.Join(", ", dyn.Entries.Where(e => e.Data.Governor is not null).GroupBy(e => e.Data.Governor!.Model).Select(gr => $"{gr.Key} x{gr.Count()}"))}), the rest hold their mechanical power";
        Console.WriteLine($"machine data: '{dyn.Name}'  *  {governors}  *  provenance: {string.Join(", ", dyn.Entries.SelectMany(e => e.Provenance).Distinct().OrderBy(t => t))}");
        foreach (MachineDynamicsEntry e in dyn.Entries)
            foreach (string note in e.Notes) Console.WriteLine($"  note: generator {e.GeneratorLabel}: {note}");
    }
    if (convCount - weccCount > 0)
        Console.WriteLine($"{convCount - weccCount} converter-interfaced units  *  REGC_A/REEC-style current sources (K=2, reactive priority, LVACM)");
    if (weccCount > 0)
    {
        // WECC (expansion): each unit with a WECC chain from the DYR file, by name and chain.
        Console.WriteLine($"{weccCount} WECC renewable unit(s) from the dynamics file:");
        for (int k = 0; k < data.Count; k++)
            if (data[k].Renewable is { } plant)
                Console.WriteLine($"  {model.Generators[k].Name ?? "unit"} @ bus {model.Generators[k].Bus}: {plant.Chain}  ({plant.Source})");
    }
    if (pfOnly + held > 0)
        Console.WriteLine($"{pfOnly} power-flow-only + {held} zero-inertia units held as constant injections");
    Console.WriteLine();

    try
    {
        if (rmsEvents is not null)
        {
            // N351 (CF5): one scheduled-event study. The run lasts the default RMS duration, or 3 s past the last event
            // when that is later, so every event is followed by time to see its effect.
            double lastAt = rmsEvents.Max(e => e.AtSeconds);
            double duration = Math.Max(GridSim.Cli.CliDefaults.RmsDurationS, lastAt + GridSim.Cli.CliDefaults.RmsDurationS);
            var sw = System.Diagnostics.Stopwatch.StartNew();
            MultiMachineSubtransient.Result r = RmsTransientStability.StudyEvents(model, pf, data, rmsEvents,
                stepSeconds: GridSim.Cli.CliDefaults.RmsStepS, durationSeconds: duration, exciters: exciters);
            Console.WriteLine($"events ({rmsEvents.Count}), over {duration:0.###} s:");
            foreach (var e in rmsEvents.OrderBy(e => e.AtSeconds)) Console.WriteLine($"  {e.Describe()}");
            Console.WriteLine((r.StayedInSynchronism ? "STABLE (the connected machines stay in synchronism)" : "UNSTABLE (loss of synchronism)")
                + $"  *  {sw.Elapsed.TotalSeconds:F1} s");
            // GR-084: the converter current fixed point that did not settle on some steps is surfaced beside the verdict (the
            // verdict reads synchronism only, and the run carried on with the last iterate on those steps).
            if (r.ConverterIterationFailures > 0)
                Console.WriteLine($"WARNING: the converter current iteration did not settle on {r.ConverterIterationFailures} step(s); the verdict "
                    + "reads synchronism only and those steps carried the last iterate: treat it as unconfirmed.");
            // N363 (CF6): the export of this run, when asked for. Formatting only: the run above is unchanged (the
            // machine buses come from a second, read-only preparation of the same solved case, which is deterministic
            // and is not used by the study). An output fault is an input/output error (exit 1), never a crash.
            if (eventsOut is not null)
            {
                try
                {
                    SubtransientInit.Prepared labels = SubtransientInit.FromSolvedCase(model, pf, data);
                    int islandRefs = labels.IslandReferences?.Count ?? 0;
                    bool indicative = !(dyn is not null && fromFile == machineCount && dyn.AllRecorded);
                    string indicativeNote = dyn is null
                        ? "the GENROU parameters are synthesised from X'd: the result is INDICATIVE, not validated"
                        : !indicative
                            ? $"every machine's data comes from {Path.GetFileName(dyn.Path)}, all of it tagged Recorded or DerivedFromRecorded"
                            : $"machine data partly synthesised or not tagged Recorded / DerivedFromRecorded ({Path.GetFileName(dyn.Path)}): the result is INDICATIVE, not validated";
                    string desc = $"stability --rms --events  case={label}  events={rmsEvents.Count}  step={GridSim.Cli.CliDefaults.RmsStepS.ToString("R", System.Globalization.CultureInfo.InvariantCulture)}s"
                        + $"  duration={duration.ToString("R", System.Globalization.CultureInfo.InvariantCulture)}s  field={fieldText}"
                        + $"  verdict={(r.StayedInSynchronism ? "STABLE" : "UNSTABLE")}"
                        + (eventsEvery != 1 ? $"  every={eventsEvery}steps" : "");   // CF6-F5: absent at the default
                    IReadOnlyList<string> header = RunInfo.HeaderLines(desc);
                    CliFiles.OutputFolder(eventsOut, "--events-out folder");
                    RunInfo.WriteJson(CliFiles.Output(Path.Combine(eventsOut, "run-metadata.json"), "run-metadata.json"), desc);
                    string machinesPath = Path.Combine(eventsOut, GridSim.Core.IO.RmsEventsExport.MachinesCsv);
                    File.WriteAllText(CliFiles.Output(machinesPath, "RMS events machines CSV"),
                        GridSim.Core.IO.RmsEventsExport.MachinesCsvText(r, labels.GeneratorBuses, islandRefs, header, indicativeNote, eventsEvery));
                    string? convText = GridSim.Core.IO.RmsEventsExport.ConvertersCsvText(r, labels.GeneratorBuses, islandRefs, header, indicativeNote, eventsEvery);
                    if (convText is not null)
                        File.WriteAllText(CliFiles.Output(Path.Combine(eventsOut, GridSim.Core.IO.RmsEventsExport.ConvertersCsv), "RMS events converters CSV"), convText);
                    File.WriteAllText(CliFiles.Output(Path.Combine(eventsOut, GridSim.Core.IO.RmsEventsExport.SummaryJson), "RMS events summary"),
                        GridSim.Core.IO.RmsEventsExport.SummaryJsonText(r, labels.GeneratorBuses, islandRefs, rmsEvents, label,
                            model.FrequencyHz, GridSim.Cli.CliDefaults.RmsStepS, duration, indicative, indicativeNote, eventsEvery));
                    Console.WriteLine($"exported RMS event study ({r.Machines.Count} machine trace(s), {r.Machines[0].TimeSeconds.Count} samples"
                        + (convText is not null ? $", {r.Converters!.Count} converter trace(s)" : "") + $") -> {Path.GetFullPath(eventsOut)}");
                }
                catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException)
                {
                    Console.Error.WriteLine($"error: stability: --events-out: {ex.Message}");
                    Environment.ExitCode = CliExit.InputError;
                    return;
                }
            }
        }
        else if (clearByTrip is not null)
        {
            int faultBus = faultBusArg ?? (wscc9 ? 7 : DefaultFaultBus(model));
            string trips = string.Join(", ", clearByTrip.Select(k => $"branch {k}"));
            var actions = clearByTrip.Select(k => (GridSim.Core.Dynamics.Models.RmsEvent)new GridSim.Core.Dynamics.Models.RmsBranchTrip(0.0, k)).ToList();
            if (clearMs is double cmt)
            {
                // N351 (CF5): the fixed-time verdict with the fault cleared by tripping the branches.
                double onset = GridSim.Cli.CliDefaults.FaultOnsetS, at = onset + cmt / 1000.0;
                var evs = new List<GridSim.Core.Dynamics.Models.RmsEvent>
                {
                    new GridSim.Core.Dynamics.Models.RmsBusFault(onset, faultBus),
                    new GridSim.Core.Dynamics.Models.RmsFaultClear(at, faultBus),
                };
                evs.AddRange(actions.Select(a => a with { AtSeconds = at }));
                MultiMachineSubtransient.Result r = RmsTransientStability.StudyEvents(model, pf, data, evs,
                    stepSeconds: GridSim.Cli.CliDefaults.RmsStepS, durationSeconds: GridSim.Cli.CliDefaults.RmsDurationS, exciters: exciters);
                Console.WriteLine($"fault bus {faultBus}  *  cleared after {cmt:F0} ms by tripping {trips}  *  "
                    + (r.StayedInSynchronism ? "STABLE (fleet stays in synchronism)" : "UNSTABLE (loss of synchronism)"));
                // GR-084: the converter current fixed point that did not settle on some steps is surfaced beside the verdict (the
                // verdict reads synchronism only, and the run carried on with the last iterate on those steps).
                if (r.ConverterIterationFailures > 0)
                    Console.WriteLine($"WARNING: the converter current iteration did not settle on {r.ConverterIterationFailures} step(s); the verdict "
                        + "reads synchronism only and those steps carried the last iterate: treat it as unconfirmed.");
            }
            else
            {
                // N351 (CF5): the CCT search with the clearing actions.
                CctBracket rbt = RmsTransientStability.CriticalClearingBracketEvents(model, pf, data, faultBus, actions, exciters: exciters);
                double cct = rbt.StableSeconds;
                Console.WriteLine($"fault bus {faultBus}  *  cleared by tripping {trips}  *  critical clearing time = {cct * 1000.0:F0} ms");
                double stepMs = RmsTransientStability.CctDefaultStepSeconds * 1000.0;
                double windowMs = RmsTransientStability.CctDefaultMaxSeconds * 1000.0;
                if (cct == 0.0) Console.WriteLine("  (even an instantaneous clear loses synchronism)");
                else if (cct * 1000.0 > windowMs - 0.5 * stepMs) Console.WriteLine($"  (no clearing time up to the {windowMs:F0} ms search window loses synchronism)");
                else Console.WriteLine($"  (bracket: clearing at {cct * 1000.0:F0} ms holds synchronism, at {cct * 1000.0 + stepMs:F0} ms it is lost)");
                if (rbt.NonMonotone) Console.WriteLine(CctPocketLine(rbt));
                if (CctUnsettledLine(rbt) is string ut) Console.WriteLine(ut);
                Console.WriteLine(RmsCctMeaning());
            }
        }
        else if (screen)
        {
            // N048 / N068 (Ruling R1, Mark delegated 2026-10-04): ONE bracket search per fault bus. The number is the
            // bracket's stable end, which is exactly what CriticalClearingTimeSeconds returns (that method is
            // CriticalClearingBracket(...).StableSeconds with the same arguments), and the same search gives the
            // NON-MONOTONE flag. Before N068 the search ran twice (once through CriticalClearingTimeSeconds for the number,
            // once more for the flag) because StabilityAvrFlagContractTests pinned the old call text; the test now pins this
            // call, with its exciters, so the RMS screen costs half as much and prints the same numbers.
            var results = new List<(int Bus, double Cct, CctBracket Bracket)>();
            foreach (int b in genBuses)
            {
                CctBracket br = RmsTransientStability.CriticalClearingBracket(model, pf, data, b, exciters: exciters);
                results.Add((b, br.StableSeconds, br));
            }
            GridSim.Core.Numerics.FrozenIntroSort.Sort(results, (a, c) => a.Cct.CompareTo(c.Cct));   // GR-867, as above
            Console.WriteLine($"{"Rank",5}{"Fault bus",11}{"CCT (ms)",11}");
            for (int i = 0; i < results.Count; i++)
                Console.WriteLine($"{i + 1,5}{results[i].Bus,11}{results[i].Cct * 1000.0,11:F0}" + (i == 0 ? "   <- most critical" : "")
                    + CctPocketNote(results[i].Bracket)
                    + (results[i].Bracket.TrialsWithConverterIterationFailures > 0 ? "   UNCONFIRMED: converter iteration did not settle" : ""));
            Console.WriteLine();
            Console.WriteLine(RmsCctMeaning());
        }
        else if (clearMs is double cm)
        {
            // One fault-and-clear study (no bisection): the verdict plus the converter fleet's ride-through.
            int faultBus = faultBusArg ?? (wscc9 ? 7 : DefaultFaultBus(model));
            var sw = System.Diagnostics.Stopwatch.StartNew();
            // N246 rest (CF2): StudyWithFleet is Study (same run, same bits) plus the inertia vector and machine set its
            // synchronism test used, so law 9 below is scored on exactly what the verdict was judged on.
            RmsTransientStability.FleetStudy fleet = RmsTransientStability.StudyWithFleet(model, pf, data, faultBus,
                onsetSeconds: GridSim.Cli.CliDefaults.FaultOnsetS, clearingSeconds: cm / 1000.0,
                stepSeconds: GridSim.Cli.CliDefaults.RmsStepS, durationSeconds: GridSim.Cli.CliDefaults.RmsDurationS,
                exciters: exciters);
            MultiMachineSubtransient.Result r = fleet.Result;
            Console.WriteLine($"fault bus {faultBus}  *  cleared after {cm:F0} ms  *  "
                + (r.StayedInSynchronism ? "STABLE (fleet stays in synchronism)" : "UNSTABLE (loss of synchronism)")
                + $"  *  {sw.Elapsed.TotalSeconds:F1} s");
            // GR-084: the converter current fixed point that did not settle on some steps is surfaced beside the verdict (the
            // verdict reads synchronism only, and the run carried on with the last iterate on those steps).
            if (r.ConverterIterationFailures > 0)
                Console.WriteLine($"WARNING: the converter current iteration did not settle on {r.ConverterIterationFailures} step(s); the verdict "
                    + "reads synchronism only and those steps carried the last iterate: treat it as unconfirmed.");
            // N246 rest (CF2, October 2026; Ruling R1): law 9 (synchronism) from this RMS run's own trajectory, the same
            // out-of-step criterion and wording as the classical --clear path (any machine more than 180 degrees from the
            // centre of inertia at any sample, angle only). Printed beside the verdict above (the integrator's pole-slip
            // test, 360 degrees), never instead of it, with the same note when they differ.
            GridSim.Core.Physics.LawResult law9 = GridSim.Core.Physics.PhysicsLaws.ScoreSynchronism(
                GridSim.Core.Physics.SynchronismFromTrajectory.Subtransient(r, fleet.H, fleet.SynchronismMachines, fleet.NominalHz));
            Console.WriteLine($"law 9 (synchronism, scored from this run): {(law9.Status == GridSim.Core.Physics.LawStatus.Holds ? "HOLDS" : "VIOLATED")}: {law9.Detail}");
            if (r.StayedInSynchronism && law9.Status != GridSim.Core.Physics.LawStatus.Holds)
                Console.WriteLine("  note: a machine passed 180 degrees from the centre of inertia (out of step by the PSS/E / PowerFactory criterion) "
                    + "but did not slip a pole (360 degrees) within the run, which is the test the STABLE verdict above uses.");
            if (r.Converters is { Count: > 0 } cv)
            {
                int k = r.Machines[0].TimeSeconds.ToList().FindIndex(t => t >= GridSim.Cli.CliDefaults.FaultOnsetS + cm / 2000.0);
                int inDip = cv.Count(c => c.InDipMode[k]);
                int recovered = cv.Count(c => !c.InDipMode[^1]);
                double pBefore = cv.Sum(c => c.ActivePowerPu[0]) * model.BaseMva;
                double pEnd = cv.Sum(c => c.ActivePowerPu[^1]) * model.BaseMva;
                Console.WriteLine($"converters: {cv.Count} nodes, {inDip} in fault ride-through mid-fault, {recovered} recovered by 3 s; "
                    + $"active power {pBefore:F0} MW before, {pEnd:F0} MW at 3 s");
            }
        }
        else
        {
            int faultBus = faultBusArg ?? (wscc9 ? 7 : DefaultFaultBus(model));
            // N048 / N068: one bracket search; its stable end is the CCT (bit for bit CriticalClearingTimeSeconds) and the
            // same search gives the NON-MONOTONE flag (it used to run twice; see the screen branch above).
            CctBracket rbr = RmsTransientStability.CriticalClearingBracket(model, pf, data, faultBus, exciters: exciters);
            double cct = rbr.StableSeconds;
            Console.WriteLine($"fault bus {faultBus}  *  critical clearing time = {cct * 1000.0:F0} ms");
            // R106 (Q15): say exactly what the number is, including the two ends of the search window.
            double stepMs = RmsTransientStability.CctDefaultStepSeconds * 1000.0;
            double windowMs = RmsTransientStability.CctDefaultMaxSeconds * 1000.0;
            if (cct == 0.0)
                Console.WriteLine("  (even an instantaneous clear loses synchronism)");
            else if (cct * 1000.0 > windowMs - 0.5 * stepMs)
                Console.WriteLine($"  (no clearing time up to the {windowMs:F0} ms search window loses synchronism)");
            else
                Console.WriteLine($"  (bracket: clearing at {cct * 1000.0:F0} ms holds synchronism, at {cct * 1000.0 + stepMs:F0} ms it is lost)");
            if (rbr.NonMonotone) Console.WriteLine(CctPocketLine(rbr));   // N048
            if (CctUnsettledLine(rbr) is string ut) Console.WriteLine(ut);
            Console.WriteLine(RmsCctMeaning());
        }
    }
    catch (Exception ex) { Console.Error.WriteLine($"error: stability: {ex.Message}"); Environment.ExitCode = 2; return; }

    Console.WriteLine();
    // N351 (CF5): the first footer word says what was studied (the default runs print exactly the old line).
    Console.WriteLine((rmsEvents is not null ? "Scheduled RMS events" : clearByTrip is not null ? "3-phase fault cleared by branch trips" : "Self-clearing 3-phase fault")
        + "; the subtransient engine is validated (reduces to the classical CCT),");
    // F23: the INDICATIVE label goes only when every machine's data comes from the file AND every value there is tagged
    // Recorded or DerivedFromRecorded; synthetic defaults or placeholder / synthetic provenance keep it.
    if (dyn is null)
        Console.WriteLine("but these GENROU parameters are synthesised from X'd - the result is INDICATIVE, not validated.");
    else if (fromFile == machineCount && dyn.AllRecorded)
        Console.WriteLine($"and every machine's data comes from {Path.GetFileName(dyn.Path)}, all of it tagged Recorded or DerivedFromRecorded.");
    else
        Console.WriteLine($"but {(fromFile == machineCount ? "some machine data in the file is not tagged Recorded or DerivedFromRecorded" : $"{machineCount - fromFile} of {machineCount} machines use GENROU parameters synthesised from X'd")}"
            + " - the result is INDICATIVE, not validated.");
}

// R106 (Q15): what an RMS CCT means. The fault is switched only on whole integration steps, so the CCT is
// step-quantised: the longest clearing time on the step grid that keeps synchronism, with one step more losing it.
// Digits below the step are not information, so none are reported.
static string RmsCctMeaning()
{
    double stepMs = RmsTransientStability.CctDefaultStepSeconds * 1000.0;
    double windowMs = RmsTransientStability.CctDefaultMaxSeconds * 1000.0;
    return $"CCT = longest clearing time on the {stepMs:F0} ms integration-step grid that keeps synchronism "
        + $"(clearing one step, {stepMs:F0} ms, later loses it); resolution {stepMs:F0} ms.\n"
        + $"A CCT of 0 ms means even an instantaneous clear loses synchronism; {windowMs:F0} ms means no clearing "
        + $"time in the {windowMs:F0} ms search window loses it.\n" + CctFirstLossSentence(stepMs)
        + "\n" + CctWindowSentence(RmsTransientStability.PostClearWindowSeconds, rms: true);
}

// N341 / N343 (October 2026; Ruling R1, Mark delegated EE calls 2026-10-04): the CCT criterion and its window, stated with
// every CCT. The criterion is the FIRST loss of synchronism from below (CctFirstLossSentence; what PSS/E and PowerFactory
// report), and a stable pocket above it is a note, never the CCT. Each trial is judged over a fixed window after the
// fault clears, 5 s by default (ClassicalInit.CctPostClearWindowSeconds, RmsTransientStability.PostClearWindowSeconds):
// first-swing stability, the range in which the classical constant-E' model is valid. The undamped classical swing keeps
// every swing it starts, so a longer window can find a later-swing loss below the reported CCT (WSCC-9 bus 7 at 60 Hz:
// 550 ms at 5 s, 436 ms at 20 s; N341), and the sentence says so rather than leave the window implicit.
static string CctWindowSentence(double windowSeconds, bool rms = false)
    => $"Each trial is judged over the {windowSeconds:0.###} s after the fault clears (the documented default window: first-swing "
        + (rms ? "stability, the same window as the classical search" : "stability, the range in which the classical constant-E' model holds")
        + "); an undamped system can lose synchronism on a later swing, so a longer window can give a shorter CCT.";

// N048: the CCT is the FIRST loss of synchronism from below, checked around the bisection's answer; say so, and say
// what a NON-MONOTONE flag means. Shared by the RMS and classical meanings (the search is the same, CctSearch).
static string CctFirstLossSentence(double stepMs)
    => $"It is the first loss from below: the {GridSim.Core.Dynamics.Models.CctSearch.DefaultScanSteps} steps "
        + $"({GridSim.Core.Dynamics.Models.CctSearch.DefaultScanSteps * stepMs:F0} ms) below it are checked to hold and "
        + $"as many above it are probed; NON-MONOTONE marks a later clearing time that holds again (a stable pocket).";

// N048: the screen-table suffix for a bus whose search found a stable pocket above its first loss.
static string CctPocketNote(CctBracket b)
    => b.PocketStableSeconds is double p ? $"   NON-MONOTONE: holds again at {p * 1000.0:F0} ms" : "";

// Bug hunt 2026-10-29, finding 24: the WARNING for a CCT search with trials whose converter iteration hit its cap; null
// when every trial settled, so a settled run prints exactly what it always did.
static string? CctUnsettledLine(CctBracket b)
    => b.TrialsWithConverterIterationFailures > 0
        ? $"WARNING: {b.TrialsWithConverterIterationFailures} trial(s) of the search had converter steps whose current iteration did not settle; those verdicts read synchronism on the last iterate, so treat the CCT as unconfirmed."
        : null;

// N048: the single-study line for a bus whose search found a stable pocket above its first loss.
static string CctPocketLine(CctBracket b)
    => $"  NON-MONOTONE: clearing at {b.PocketStableSeconds!.Value * 1000.0:F0} ms holds synchronism again (a stable pocket above "
        + "the first loss); the reported CCT is the first loss from below, so do not read a longer clearing time as safe.";

// N042: what a CLASSICAL CCT means. Since N042 the classical search runs over whole integration steps like the RMS
// one (R106), so the same sentence applies with the classical step and window. Sub-step digits are not reported.
static string ClassicalCctMeaning()
{
    double stepMs = ClassicalInit.CctDefaultStepSeconds * 1000.0;
    double windowMs = ClassicalInit.CctDefaultMaxSeconds * 1000.0;
    return $"CCT = longest clearing time on the {stepMs:F0} ms integration-step grid that keeps synchronism "
        + $"(clearing one step, {stepMs:F0} ms, later loses it); resolution {stepMs:F0} ms.\n"
        + $"A CCT of 0 ms means even an instantaneous clear loses synchronism; {windowMs:F0} ms means no clearing "
        + $"time in the {windowMs:F0} ms search window loses it.\n" + CctFirstLossSentence(stepMs)
        + "\n" + CctWindowSentence(ClassicalInit.CctPostClearWindowSeconds);   // N341 / N343
}

void RunStability(GridModel model, string label, int? faultBusArg, double? clearMs, string? exportPath = null, MachineDynamicsSet? dyn = null)
{
    // N314 (LF5): with a dynamics file, the machines it binds take its H through a model copy (the solve below is the same
    // solve: H enters no power-flow equation), and its X'd and damping below (ClassicalDynData).
    if (dyn is not null) model = DynDataCli.WithFileInertia(model, dyn);
    // Shared dense/sparse rule on the selected backend (R003: below 3,000 buses this built a CPU dense NR directly,
    // dropping --gpu and the 100-iteration cap the sparse branch had).
    PowerFlowResult pf = backend.NewtonSolver(model).Solve(model, new PowerFlowOptions { MaxIterations = 100 });
    // A non-converged solve is a failure, not a clean run - exit non-zero.
    if (!pf.Converged) { Console.Error.WriteLine("error: stability: power flow did not converge."); Environment.ExitCode = 3; return; }

    // Transient reactance: Anderson-Fouad for WSCC-9, else a conservative synthetic default (flagged).
    double[]? xdp = null;
    bool syntheticXdp = true;
    if (label == "WSCC-9") xdp = Wscc9XdpByGenerator(model, out syntheticXdp);   // the one shared map (R151)
    double[]? studyDamping = null;   // N314: per-generator D from the file; null = undamped, exactly as before
    if (dyn is not null) (xdp, studyDamping, syntheticXdp) = ClassicalDynData(model, label, xdp, dyn);

    int faultBus = faultBusArg ?? (label == "WSCC-9" ? 7 : DefaultFaultBus(model));
    // R007 (stream P, October 2026): the study prepares the fault bus, then (without --clear) searches the CCT at the same
    // bus, which prepared it all over again. Both now come from one FaultScreen: ForFault is exactly FromSolvedCase, and
    // the CCT overload on the screen is exactly the one on (model, pf, xdp), so every printed number is unchanged.
    ClassicalInit.FaultScreen screen = ClassicalInit.PrepareFaultScreen(model, pf, xdp, holdNonMachines: true);
    ClassicalInit.Prepared p = screen.ForFault(faultBus);

    Console.WriteLine($"GridSim  -  TRANSIENT STABILITY (classical multi-machine)  *  {label}");
    Console.WriteLine(new string('=', 66));
    Console.WriteLine($"{p.H.Length} machines ({model.Generators.Count - p.H.Length} converter / power-flow-only / zero-inertia units held)  *  fault bus {faultBus}  *  " +
                      $"X'd = {(dyn is not null ? ClassicalDynXdpText(dyn, label, syntheticXdp, p.H.Length) : syntheticXdp ? $"synthetic {GridSim.Cli.CliDefaults.SyntheticXdpPu:F2} pu (unvalidated)" : "Anderson-Fouad")}");
    if (dyn is not null) PrintClassicalDynDataLines(dyn);
    Console.WriteLine();
    // D-DOC-132 (docs-session finding, Ruling R1: Mark delegated 2026-10-04): the last column was 12 wide and its title
    // "delta0 (deg)" is exactly 12 characters, so the header ran into the previous column ("|E'| pudelta0 (deg)").
    // The column is now 14 wide (title and data alike), which leaves a two-space gap; the numbers are unchanged.
    Console.WriteLine($"{"Bus",5}{"H sys (s)",12}{"|E'| pu",10}{"delta0 (deg)",14}");
    for (int i = 0; i < p.H.Length; i++)
        Console.WriteLine($"{p.GeneratorBuses[i],5}{p.H[i],12:F3}{p.Eq[i],10:F3}{p.Delta0[i] * 180.0 / Math.PI,14:F1}");
    Console.WriteLine();

    if (clearMs is double cm)
    {
        double onset = GridSim.Cli.CliDefaults.FaultOnsetS;
        var fault = new ClassicalMultiMachine.Fault(onset, onset + cm / 1000.0, p.YReducedFaulted!);
        // R151: f0 is the model's nominal frequency (it was a literal 50.0; every bundled case is 50 Hz today).
        ClassicalMultiMachine.Result res = ClassicalMultiMachine.Simulate(
            p.H, ClassicalInit.DampingByMachine(model, p, studyDamping) ?? new double[p.H.Length], p.Pm, p.Eq, p.Delta0, p.YReduced, model.FrequencyHz,
            GridSim.Cli.CliDefaults.ClassicalStepS, onset + cm / 1000.0 + GridSim.Cli.CliDefaults.ClassicalPostClearS, fault);
        Console.WriteLine($"3-phase fault at bus {faultBus}, cleared after {cm:F0} ms  ->  " +
                          (res.StayedInSynchronism ? "STABLE (holds synchronism)" : "UNSTABLE (loss of synchronism)"));
        // N246 (October 2026; Ruling R1): law 9 (synchronism) scored from this run's own rotor-angle trajectory, with the
        // out-of-step criterion of PSS/E and PowerFactory: any machine more than 180 degrees from the centre of inertia at
        // any sample. It is printed beside the verdict above (the integrator's pole-slip test, 360 degrees), never instead
        // of it; when the two differ (an excursion between 180 and 360 degrees) the note says so. Nothing above changes.
        GridSim.Core.Physics.LawResult law9 = GridSim.Core.Physics.PhysicsLaws.ScoreSynchronism(
            GridSim.Core.Physics.SynchronismFromTrajectory.Classical(res, p.H, model.FrequencyHz));
        Console.WriteLine($"law 9 (synchronism, scored from this run): {(law9.Status == GridSim.Core.Physics.LawStatus.Holds ? "HOLDS" : "VIOLATED")}: {law9.Detail}");
        if (res.StayedInSynchronism && law9.Status != GridSim.Core.Physics.LawStatus.Holds)
            Console.WriteLine("  note: a machine passed 180 degrees from the centre of inertia (out of step by the PSS/E / PowerFactory criterion) "
                + "but did not slip a pole (360 degrees) within the run, which is the test the STABLE verdict above uses.");
    }
    else
    {
        // N042: the classical CCT is step-quantised like the RMS one (R106), so print the bracket it stands for.
        CctBracket br = ClassicalInit.CriticalClearingBracket(screen, faultBus, machineDamping: studyDamping);   // R007: the screen above, same bits (N314: null damping = undamped)
        double cct = br.StableSeconds;
        Console.WriteLine($"Critical clearing time for a 3-phase fault at bus {faultBus}:  {cct * 1000.0:F0} ms");
        Console.WriteLine("(the longest the fault can persist before the fleet loses synchronism on self-clear)");
        if (br.UnstableAtZero)
            Console.WriteLine("  (even an instantaneous clear loses synchronism)");
        else if (br.UnstableSeconds is not double lost)
            Console.WriteLine($"  (no clearing time up to the {ClassicalInit.CctDefaultMaxSeconds * 1000.0:F0} ms search window loses synchronism)");
        else
            Console.WriteLine($"  (bracket: clearing at {cct * 1000.0:F0} ms holds synchronism, at {lost * 1000.0:F0} ms it is lost)");
        if (br.NonMonotone) Console.WriteLine(CctPocketLine(br));   // N048
        Console.WriteLine(ClassicalCctMeaning());
    }
    Console.WriteLine();
    Console.WriteLine("Classical model: constant E' behind X'd over the Kron-reduced network, RK4 swing.");
    if (syntheticXdp)
        Console.WriteLine("Provenance: X'd is a synthetic default - clearing times are INDICATIVE, not validated.");
    else if (dyn is not null && !ClassicalDynDataIsValidated(dyn))
        Console.WriteLine("Provenance: the machine data file's values are not all Recorded / DerivedFromRecorded - clearing times are INDICATIVE, not validated.");

    if (exportPath is not null)
    {
        // Standard perturbed no-fault run for cross-validation: bump the lowest-inertia machine and record
        // a smooth trajectory an independent integrator (scipy RK45) can reproduce from the same reduced
        // system - validating the multi-machine coupling numerics, not just the SMIB analytic limit.
        // N314 (LF5): this kernel check stays UNDAMPED with --dyn-data too (the export format carries no damping and the
        // scipy reference integrates the undamped swing); the file's H and X'd reach it through p, which the export records.
        int bump = 0;
        for (int i = 1; i < p.H.Length; i++) if (p.H[i] < p.H[bump]) bump = i;
        double[] d0 = (double[])p.Delta0.Clone();
        d0[bump] += GridSim.Cli.CliDefaults.ClassicalExportKickRad;
        const double dt = GridSim.Cli.CliDefaults.ClassicalExportStepS, dur = GridSim.Cli.CliDefaults.ClassicalExportDurationS;
        ClassicalMultiMachine.Result run = ClassicalMultiMachine.Simulate(
            p.H, new double[p.H.Length], p.Pm, p.Eq, d0, p.YReduced, model.FrequencyHz, dt, dur);

        int n = p.H.Length, nr = p.YReduced.GetLength(0);
        var gg = new double[nr][]; var bb = new double[nr][];
        for (int i = 0; i < nr; i++)
        {
            gg[i] = new double[nr]; bb[i] = new double[nr];
            for (int j = 0; j < nr; j++) { gg[i][j] = p.YReduced[i, j].Real; bb[i][j] = p.YReduced[i, j].Imaginary; }
        }
        var times = new List<double>(); var samp = new List<double[]>();
        System.Collections.Generic.IReadOnlyList<double> full = run.Machines[0].TimeSeconds;
        for (int k = 0; k < full.Count; k += 50)
        {
            times.Add(full[k]);
            var row = new double[n];
            for (int i = 0; i < n; i++) row[i] = run.Machines[i].DeltaRad[k];
            samp.Add(row);
        }
        var doc = new
        {
            schema = "gridsim-classical-export/1", label, f0 = model.FrequencyHz, stepSeconds = dt, durationSeconds = dur,
            bumpMachine = bump, bumpRad = GridSim.Cli.CliDefaults.ClassicalExportKickRad,   // GR-673: the kick actually applied
            machines = System.Linq.Enumerable.Range(0, n).Select(i => new
            { bus = p.GeneratorBuses[i], h = p.H[i], pm = p.Pm[i], eq = p.Eq[i], delta0 = p.Delta0[i] }).ToArray(),
            delta0Perturbed = d0, yReducedG = gg, yReducedB = bb,
            sampleTimes = times.ToArray(), sampleDelta = samp.ToArray(),
        };
        // D-DOC-176: through the one output policy, which creates a missing parent folder (this write used to fail on one).
        System.IO.File.WriteAllText(CliFiles.Output(exportPath, "classical stability export"), System.Text.Json.JsonSerializer.Serialize(doc));
        Console.WriteLine($"Exported classical trajectory ({n} machines, {times.Count} samples) -> {System.IO.Path.GetFullPath(exportPath)}");
    }
}

void RunModal(List<string> a, string root)
{
    // Flags (consume values up front so the sole positional token is the case name).
    double? damping = null;
    int di = a.IndexOf("--damping");
    if (di >= 0)
    {
        // Finite and not negative: NaN / Infinity crashed in the assembler (an ArgumentException the verb did not
        // catch), and a negative damping manufactured right-half-plane modes reported as "small-signal unstable".
        if (di + 1 >= a.Count || !double.TryParse(a[di + 1], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double dv)
            || !double.IsFinite(dv) || dv < 0.0)
            FailFlag<double>("--damping", di + 1 < a.Count ? a[di + 1] : "", "a finite damping, 0 or more"); 
        else { damping = dv; a.RemoveRange(di, 2); }
    }
    string? exportPath = null;
    int ei = a.IndexOf("--export");
    if (ei >= 0)
    {
        // GR-699: a following --flag is not a file name (it used to be taken as one).
        if (FlagValueMissing(a, ei)) FailFlag<string>("--export", "", "a file path");
        exportPath = a[ei + 1]; a.RemoveRange(ei, 2);
    }
    // F stream (October 2026, front doors; Ruling R1): --dyn-data <file>, the machine dynamic data file (gridsim-dynamics/2,
    // F23) that stability --rms reads. The classical small-signal model is built from exactly three machine numbers, the
    // transient reactance X'd, the inertia H and the damping D, and the file carries all three for each machine it binds,
    // so modal takes them from it (its GENROU subtransient reactances and time constants, exciters and governors are not
    // part of this model, and the header says so). Without the flag nothing below changes.
    string? dynDataPath = null;
    int ddi = a.IndexOf("--dyn-data");
    if (ddi >= 0)
    {
        if (ddi + 1 >= a.Count || a[ddi + 1].StartsWith("--", StringComparison.Ordinal))
            FailFlag<string>("--dyn-data", ddi + 1 < a.Count ? a[ddi + 1] : "", "a gridsim-dynamics/2 file");
        dynDataPath = a[ddi + 1]; a.RemoveRange(ddi, 2);
    }
    bool enableInverters = a.Remove("--enable-inverters");
    bool includeSoc = a.Remove("--include-soc");
    if (includeSoc)
    {
        // R085: the flag was accepted and had no effect. Refuse it plainly.
        Console.Error.WriteLine("error: modal --include-soc is not implemented (a state-of-charge integrator is a decoupled origin pole, excluded from the stability matrix by design).");
        Environment.Exit(2);
    }
    // N104 (October 2026): modal's own --json prints the model and modes as JSON on the console and takes no value; it is
    // not the shared writer's --json <file.json> (modal's file output is --export <file.json>). Decision: keep modal's
    // meaning (renaming it would break every script that uses it) and refuse the one way the two meanings collide: a
    // .json file name right after --json, which the writer verbs would write to but modal would have taken as a stray
    // positional argument. Exit 2, pointing at --export.
    {
        int ji = a.IndexOf("--json");
        if (ji >= 0 && ji + 1 < a.Count && a[ji + 1].EndsWith(".json", StringComparison.OrdinalIgnoreCase))
        {
            Console.Error.WriteLine($"error: modal --json prints JSON to the console and takes no file; to write the model and modes to " +
                $"'{a[ji + 1]}' use --export {a[ji + 1]}.");
            Environment.Exit(2);
        }
    }
    bool json = a.Remove("--json");

    // D-DOC-053 (one rule for every verb that takes a case): modal selects its network through the shared SelectCase /
    // LoadSelected, as stability now does (see there). Before, --dir silently won over a positional case, and every load
    // failure exited 2, including a missing --dir folder (stability exited 1 for the same folder). Now a positional case
    // and --dir together exit 2 unless they name the same folder, a second positional exits 2, an unknown case NAME exits
    // 2, and a missing --dir folder or a case that exists but cannot be loaded exits 1 (D-DOC-130). The default (case9)
    // and the label are unchanged: "WSCC-9" for case9 / ieee9, otherwise the model's own name.
    string? mPos = SingleCasePositional("modal", a);
    bool mViaDir = a.Contains("--dir");
    GridModel model = LoadSelected("modal", SelectCase("modal", mPos, a, root, "case9", () => IeeeCases.Case9()));
    string label = (!mViaDir && (mPos ?? "case9").ToLowerInvariant() is "case9" or "ieee9") ? "WSCC-9" : model.Name;
    label = UserCaseLabel(label, builtinWscc9: !mViaDir && (mPos ?? "case9").ToLowerInvariant() is "case9" or "ieee9");   // GR-684, as stability

    // F stream: the dynamics file is validated and bound to this case before any solve (exit 1 for a missing or invalid
    // file, every problem listed, as on stability --rms). The machines it binds take its inertia H through a model copy
    // (H enters no power-flow equation, so the solve below is the same solve), its X'd and its damping further down.
    MachineDynamicsSet? dyn = null;
    if (dynDataPath is not null)
    {
        dyn = LoadDynDataOrExit("modal", dynDataPath, model);
        model = DynDataCli.WithFileInertia(model, dyn);
    }

    PowerFlowResult pf = backend.NewtonSolver(model).Solve(model);   // shared rule on the selected backend (was CPU dense always; R104)
    if (!pf.Converged) { Console.Error.WriteLine("error: modal: power flow did not converge."); Environment.ExitCode = 3; return; }

    // Transient reactance: Anderson-Fouad for WSCC-9, else a conservative synthetic default (flagged) -
    // the SAME map RunStability uses, so the two verbs describe the same machine model.
    double[]? xdp = null;
    bool syntheticXdp = true;
    if (label == "WSCC-9") xdp = Wscc9XdpByGenerator(model, out syntheticXdp);   // the one shared map (R151)

    double[]? machineDamping = null;
    if (damping is double dd)
    {
        machineDamping = new double[model.Generators.Count];
        for (int i = 0; i < machineDamping.Length; i++) machineDamping[i] = dd;
    }

    // F stream: a machine the dynamics file binds takes the file's X'd (machine base, as the map above) and damping D (per
    // unit on the system base, the same D as the RMS study's: both engines integrate d omega/dt = (Pm - Pe - D omega)/2H);
    // every other machine keeps the map above and --damping (or 0). X'd stays synthetic only where a synchronous machine
    // is neither bound by the file nor in the Anderson-Fouad map.
    if (dyn is not null)
    {
        var afMap = IeeeCases.Wscc9TransientReactancePu;
        syntheticXdp = model.Generators.Select((g, i) => (g, i)).Any(x =>
            !x.g.PowerFlowOnly && !x.g.IsConverterInterfaced && x.g.H > 0
            && dyn.For(x.i) is null && !(label == "WSCC-9" && afMap.ContainsKey(x.g.Bus)));
        xdp = DynDataCli.TransientReactance(model, xdp, dyn);
        machineDamping = DynDataCli.Damping(model, machineDamping, dyn);
    }

    SmallSignalModel ssm;
    try
    {
        ssm = enableInverters
            ? SmallSignalAssembler.FromSolvedCaseWithInverters(model, pf, xdp, machineDamping, includeSoc)
            : SmallSignalAssembler.FromSolvedCase(model, pf, xdp, machineDamping);
    }
    catch (InvalidOperationException ex) when (!model.Generators.Any(g => g.H > 0.0))
    {
        // N179 (October 2026): on a MATPOWER case (the GB ones included: gb-reduced-29, gb-network-2224,
        // pypsa-gb-reduced, and the IEEE cases other than case9 / ieee9) modal used to print only Core's "No
        // synchronous machines with inertia" line, right under the parser's nominal-frequency note, so the exit 2
        // read as if it were about frequency. It is not: the 50 Hz assumption is the documented default (R269) and is
        // right for GB. The exit is because a MATPOWER file carries no dynamic data, so every unit loads with H = 0 and
        // the swing model has no rotor to linearise. Same exit code (2: a model that cannot be assembled); the
        // message now says why and what to use instead. No inertia is invented here (frequency / inertia pass).
        // N275 / D2 O6 (October 2026, stream B1): the note used to call the 50 Hz assumption "harmless"; it is harmless for
        // THIS exit (no inertia, no result) but not in general (a 60 Hz system studied at 50 Hz has every modal frequency
        // and RoCoF wrong), so the message now says it is not the reason for the exit and names --frequency-hz.
        Console.Error.WriteLine(
            $"modal: {label} has no synchronous machine with an inertia constant (H > 0), so there is no rotor angle to " +
            "linearise. This case carries no dynamic data: a MATPOWER file has no inertia (or frequency) fields, so every " +
            "unit loads with H = 0 (the nominal-frequency note, if shown, is a separate 50 Hz assumption and not the reason for this exit; " +
            "for a 60 Hz system pass --frequency-hz 60, which matters to every frequency result). " +
            "Use a JSON case directory that gives each machine its inertiaH (for GB: gb, gb-reduced, gb-synthetic, uk or " +
            $"gb-full). Core said: {ex.Message}");
        Environment.Exit(2);
        return;
    }
    ModalResult modal = ModalAnalysis.Analyze(ssm);
    // N011: a defective eigenproblem now falls back to eigenvalues only; say so instead of printing nothing.
    if (modal.ParticipationUnavailable)
        Console.Error.WriteLine($"modal: participation factors unavailable - {modal.ParticipationUnavailableReason}");

    // N180 (October 2026): the exit code is decided BEFORE anything is written, so the export (and --json) can carry
    // it: 1 when any eigenvalue lies in the right half-plane (small-signal unstable), else 0. The rule is unchanged;
    // it used to be applied only after the export had been written. The export also states whether participation is
    // available (participationAvailable / participationUnavailableReason), so a defective state matrix's all-zero
    // participation rows are no longer indistinguishable from real participation.
    int modalExit = modal.RhpEigenvalueCount > 0 ? 1 : 0;

    if (exportPath is not null)
    {
        SmallSignalExport.WriteJson(CliFiles.Output(exportPath, "small-signal export"), label, ssm, modal, modalExit);
        Console.WriteLine($"Exported small-signal model ({ssm.Order} states) -> {Path.GetFullPath(exportPath)}" +
                          (modal.ParticipationUnavailable ? " (participation factors unavailable: participationAvailable false)" : ""));
    }

    if (json)
    {
        Console.WriteLine(SmallSignalExport.ToJson(label, ssm, modal, modalExit));
        if (modalExit != 0) Environment.ExitCode = modalExit;   // as before: only an unstable result sets it
        return;
    }

    Console.WriteLine($"GridSim  -  SMALL-SIGNAL / MODAL STABILITY  *  {label}");
    Console.WriteLine(new string('=', 66));
    // F stream: with a dynamics file the X'd and damping texts say where the numbers came from; without one this is the
    // original line, character for character.
    string xdpText = dyn is null
        ? (syntheticXdp ? $"synthetic {GridSim.Cli.CliDefaults.SyntheticXdpPu:F2} pu (unvalidated)" : label == "WSCC-9" ? "Anderson-Fouad" : "default")
        : $"{dyn.Entries.Count} from {Path.GetFileName(dyn.Path)}"
          + (syntheticXdp ? $", the rest synthetic {GridSim.Cli.CliDefaults.SyntheticXdpPu:F2} pu (unvalidated)"
             : label == "WSCC-9" && dyn.Entries.Count < ssm.MachineCount ? ", the rest Anderson-Fouad" : "");
    string dampingText = (damping?.ToString("F3") ?? "0 (undamped)") + (dyn is null ? "" : $" (the file's own on its {dyn.Entries.Count} machine(s))");
    Console.WriteLine($"{ssm.MachineCount} machine(s), {ssm.Order} state(s)  *  " +
                      $"X'd = {xdpText}  *  " +
                      $"inverters {(ssm.InverterStatesIncluded ? "ON" : "off")}  *  damping D = {dampingText}");
    if (dyn is not null)
    {
        // What the file brought to this model, its provenance, and what was taken from the case instead (the loader's notes).
        Console.WriteLine($"machine data: '{dyn.Name}'  *  H, X'd and damping of {dyn.Entries.Count} machine(s) from the file (its subtransient "
            + "data, exciters and governors are not part of the classical small-signal model; stability --rms uses them)  *  provenance: "
            + string.Join(", ", dyn.Entries.SelectMany(e => e.Provenance).Distinct().OrderBy(t => t)));
        foreach (MachineDynamicsEntry e in dyn.Entries)
            foreach (string note in e.Notes) Console.WriteLine($"  note: generator {e.GeneratorLabel}: {note}");
    }
    Console.WriteLine();

    // Eigenvalue / mode table.
    Console.WriteLine($"{"sigma (1/s)",14}{"omega (rad/s)",15}{"f (Hz)",10}{"zeta",10}   mode");
    foreach (Mode m in modal.Modes)
    {
        string kind = m.IsOscillatory ? "oscillatory" : "real";
        Console.WriteLine($"{m.Eigenvalue.Real,14:F4}{m.Eigenvalue.Imaginary,15:F4}{m.FrequencyHz,10:F4}{m.DampingRatio,10:F4}   {kind}");
    }
    Console.WriteLine();

    Mode? dominant = modal.Modes.FirstOrDefault(m => m.IsOscillatory);
    if (dominant is not null)
    {
        Console.WriteLine($"Least-damped oscillatory mode: {dominant.FrequencyHz:F3} Hz, zeta = {dominant.DampingRatio:F4}" +
                          (dominant.DampingRatio < 0 ? "  (UNSTABLE)" : dominant.DampingRatio < 0.05 ? "  (poorly damped)" : ""));
    }
    Console.WriteLine($"Right-half-plane eigenvalues (small-signal unstable): {modal.RhpEigenvalueCount}");
    Console.WriteLine($"Minimum oscillatory damping ratio: {(double.IsNaN(modal.MinDampingRatio) ? "n/a" : modal.MinDampingRatio.ToString("F4"))}");
    Console.WriteLine();

    // Top-3 participating states per oscillatory mode.
    Console.WriteLine("Dominant participation (which state drives each oscillatory mode):");
    // N180: with a defective state matrix every participation row is an all-zero placeholder, which the loop below
    // would have printed as "(rigid COI mode)" against every oscillatory mode. Say it is unavailable instead.
    if (modal.ParticipationUnavailable)
        Console.WriteLine("  unavailable: the state matrix is defective, so participation factors are undefined (eigenvalues only; " +
                          "the reason is on stderr).");
    int shown = 0;
    foreach (Mode m in modal.Modes.Where(x => x.IsOscillatory && !modal.ParticipationUnavailable))
    {
        if (shown++ >= 6) break;   // conjugate pairs -> cap the listing
        var top = Enumerable.Range(0, ssm.Order)
            .OrderByDescending(k => m.ParticipationByState[k]).Take(3)
            .Where(k => m.ParticipationByState[k] > 1e-6)
            .Select(k => $"{modal.States[k].Name} {m.ParticipationByState[k] * 100:F0}%");
        string list = string.Join(", ", top);
        Console.WriteLine($"  {m.FrequencyHz,7:F3} Hz (zeta {m.DampingRatio,7:F4}) : {(string.IsNullOrEmpty(list) ? "(rigid COI mode)" : list)}");
    }
    Console.WriteLine();

    Console.WriteLine(SPlane(modal.Modes));
    Console.WriteLine();
    Console.WriteLine("Eigenvalues of A = [[0, ws I],[-M^-1 K_L, -M^-1 D]] (true asymmetric K_L; Francis-QR, biorthonormal participation).");
    if (syntheticXdp) Console.WriteLine("Provenance: X'd is a synthetic default - damping/participation are INDICATIVE, not validated.");
    // F stream: a dynamics file whose values are not all Recorded / DerivedFromRecorded leaves the result indicative too
    // (the RMS study's rule, MachineDynamicsSet.AllRecorded).
    if (dyn is not null && !syntheticXdp && !dyn.AllRecorded)
        Console.WriteLine("Provenance: the machine data file's values are not all Recorded / DerivedFromRecorded - the modes are INDICATIVE, not validated.");
    if (ssm.InverterStatesIncluded) Console.WriteLine("Inverter states are a documented archetype (COI-coupled; GFL PLL is an SRF-PLL substitution of the transport delay).");

    if (modalExit != 0) Environment.ExitCode = modalExit;   // N180: the same value the export and --json carry (1 = right-half-plane eigenvalue)
}

// A compact ASCII s-plane: sigma (damping) horizontal, omega (frequency) vertical, poles marked.
static string SPlane(IReadOnlyList<Mode> modes)
{
    const int w = 51, h = 21;
    var grid = new char[h, w];
    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) grid[i, j] = ' ';
    int cx = w / 2, cy = h / 2;
    for (int i = 0; i < h; i++) grid[i, cx] = '|';
    for (int j = 0; j < w; j++) grid[cy, j] = '-';
    grid[cy, cx] = '+';

    double maxSig = 1e-6, maxOmg = 1e-6;
    foreach (Mode m in modes)
    {
        maxSig = Math.Max(maxSig, Math.Abs(m.Eigenvalue.Real));
        maxOmg = Math.Max(maxOmg, Math.Abs(m.Eigenvalue.Imaginary));
    }
    foreach (Mode m in modes)
    {
        int px = cx + (int)Math.Round(m.Eigenvalue.Real / maxSig * (cx - 1));
        int py = cy - (int)Math.Round(m.Eigenvalue.Imaginary / maxOmg * (cy - 1));
        px = Math.Clamp(px, 0, w - 1); py = Math.Clamp(py, 0, h - 1);
        grid[py, px] = m.Eigenvalue.Real > 1e-9 ? 'X' : '*';   // X = right-half-plane (unstable)
    }
    var sb = new System.Text.StringBuilder();
    sb.AppendLine("s-plane (imag up, real right; '*' stable pole, 'X' RHP/unstable, left of axis = damped):");
    for (int i = 0; i < h; i++) { for (int j = 0; j < w; j++) sb.Append(grid[i, j]); sb.AppendLine(); }
    return sb.ToString().TrimEnd();
}

// Tranche A (October 2026): every --dyn-data load goes through here. A gridsim-dynamics/2 file is loaded as before; a PSS/E
// .dyr file is mapped onto the machines of this run's PSS/E .raw case and then checked and bound by the same loader
// (Gated.PsseDynamics). Each caller keeps its own error handling: both refusals are InvalidDataException or a missing file.
MachineDynamicsSet LoadMachineDynamics(string path, string schemasDir, GridModel model) =>
    path.EndsWith(".dyr", StringComparison.OrdinalIgnoreCase)
        ? Gated.PsseDynamics(path, schemasDir, model)
        : MachineDynamicsLoader.Load(path, schemasDir, model);

// F stream (October 2026, front doors): load and bind a --dyn-data file (gridsim-dynamics/2, F23) for a verb other than
// stability --rms, with that verb's rule: a missing schema folder, a missing file or one that fails the v2 schema, kind-spec
// or binding checks is an input error, exit 1, naming every problem (MachineDynamicsLoader lists them all), before any
// study runs. The same checks and messages as stability --rms (RunRmsStability), with the verb's name in front.
MachineDynamicsSet LoadDynDataOrExit(string verb, string path, GridModel model)
{
    string? schemasDir = FindV2Schemas(baseDir);
    if (schemasDir is null)
    {
        Console.Error.WriteLine($"error: {verb}: --dyn-data needs the v2 schemas (schemas/v2 beside the program or above it), and none was found.");
        Environment.Exit(CliExit.InputError);
    }
    try { return LoadMachineDynamics(path, schemasDir!, model); }
    catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or DirectoryNotFoundException)
    {
        Console.Error.WriteLine($"error: {verb}: --dyn-data: {ex.Message}");
        Environment.Exit(CliExit.InputError);
        return null!;   // unreachable: Exit does not return
    }
}

// F stream: the one line trip and transient print for a --dyn-data run. Those verbs integrate the lumped (or distributed)
// swing, whose only per-machine number is the inertia H, so that is what they take from the file; the file's GENROU
// reactances, exciters and governors belong to the RMS study and are said to be unused here, never silently dropped.
static string DynDataInertiaLine(GridModel original, MachineDynamicsSet dyn) =>
    $"Machine data:   '{dyn.Name}' ({Path.GetFileName(dyn.Path)}): inertia H of {dyn.Entries.Count} generator(s) from the file "
    + $"({DynDataCli.InertiaChangedCount(original, dyn)} differ from the case); its GENROU reactances, exciters and governors are not "
    + "used by this frequency swing (stability --rms --dyn-data uses them)";

// fit-frequency <trace.csv> --inertia <GVA.s> --demand <MW> --loss <MW> [--loss-at <s>] [--fit damping,responsive,governor]
//   [--max-iter N]
// R079 (October 2026 review, stream F front doors; Ruling R1: Mark delegated the EE / product calls 2026-10-04). The
// calibration tool for the lumped swing model's nadir / recovery constants (FrequencyConstantsFitter: load self-damping,
// responsive headroom fraction, governor time constant) was finished and tested but no verb reached it, so the shipped
// literature-typical defaults could never be checked against a measured loss of infeed. This verb is that check: it fits
// the constants to ONE measured trace by least squares over FrequencyDynamics.Simulate (Nelder-Mead), reports the fitted
// values beside the seed (the shipped defaults) and the fit quality, and changes nothing else: the defaults stay what
// they are until a fit is adopted on purpose (Fit's own doc: "This is the tool, not a fitted value").
//
// Inputs and the EE calls behind them:
//   * <trace.csv>: two numeric columns, seconds,Hz, the time on the simulation clock (0 s = the start of the window); an
//     optional header line. Not timestamps: a dated trace would also need the 169 h forward-inference guard, and the
//     loss instant has to be given on the same clock anyway. FrequencyTraceFile states every row rule; a bad row exits 1
//     naming the line. N314 (LF5, October 2026; Ruling R1): the swing runs at the trace's nominal frequency, which the
//     trace names itself (its first sample lies within 5 Hz of 50 or of 60 Hz) or --nominal-hz <Hz> declares (finite,
//     above 5 Hz); samples 5 Hz or more from that nominal are refused. It was fixed at 50 Hz, so a 60 Hz trace was refused
//     outright. A 50 Hz trace runs exactly as before (the config's default nominal is the same 50.0).
//   * --inertia (GVA.s), --demand (MW), --loss (MW, the infeed lost, a positive number): required, each above 0. The
//     fitter needs the concurrent loss and inertia KNOWN (its own doc); guessing them would fold their error into the
//     fitted damping. --loss-at (s, default FrequencyDynamics.DesignEventSeconds = 1.0) is the loss instant on the
//     trace's clock; it must lie before the last sample (exit 2), or there is no recovery to fit.
//   * The pre-event frequency: the last sample before the loss starts the model in equilibrium there
//     (DynamicsConfig.InitialFrequencyHz, the replay's rule): services respond to the ABSOLUTE frequency, so a trace that
//     was already low is not fitted from 50 Hz with the offset blamed on the damping. No sample before the loss: nominal.
//   * --fit: damping (the default, the best-identified constant), responsive, governor, as a comma list. Fitting all
//     three from one trace is weakly identified (they trade off), and the report says so.
// Exit codes: 0 a converged fit; 1 a missing or invalid trace file; 2 usage (a missing or bad flag value, no trace
// argument, --loss-at at or after the last sample, an unknown --fit word, a global switch this verb would ignore);
// 3 the optimiser did not converge within --max-iter (the last point is printed, labelled, for diagnosis: never as a fit).
void RunFitFrequency(List<string> a)
{
    var inv = System.Globalization.CultureInfo.InvariantCulture;

    // The global dynamics switches are parsed before any verb runs, so the per-verb flag check cannot see them. The fitter
    // runs the plain lumped swing: forming, the asset fleet and the distributed model would each be silently ignored.
    if (formingFlagsGiven || assetDynamicsFlagGiven || inertiaModel == InertiaModel.Distributed)
    {
        Console.Error.WriteLine("error: fit-frequency fits the plain lumped swing model; --forming / --forming-inertia / --forming-damping, "
            + "--asset-dynamics and --inertia-model distributed would be silently ignored, so they are refused.");
        Environment.Exit(CliExit.Usage);
    }

    // A required, strictly positive number. Absent: a usage error naming the flag (there is no honest default for the
    // inertia, demand or loss of a recorded event). Present with a bad value: FlagDouble's own refusal (exit 2).
    double RequiredPositive(string flag, string what)
    {
        if (!a.Contains(flag))
        {
            Console.Error.WriteLine($"error: fit-frequency needs {flag} ({what}); the fit is only meaningful with the event's own value.");
            Environment.Exit(CliExit.Usage);
        }
        double v = FlagDouble(a, flag, double.NaN);
        if (!(v > 0.0)) FailFlag<double>(flag, v.ToString("R", inv), what + " above 0");
        return v;
    }

    double inertiaGvaS = RequiredPositive("--inertia", "the system inertia at the event, GVA.s");
    double demandMw = RequiredPositive("--demand", "the system demand at the event, MW");
    double lossMw = RequiredPositive("--loss", "the infeed lost, MW");
    double lossAt = FlagDouble(a, "--loss-at", FrequencyDynamics.DesignEventSeconds);
    if (lossAt < 0.0) FailFlag<double>("--loss-at", lossAt.ToString("R", inv), "a loss instant of 0 s or more on the trace's clock");
    string fitSpec = FlagString(a, "--fit") ?? "damping";
    FrequencyFitParam[] which = FrequencyFitCli.ParseFit(fitSpec)
        ?? FailFlag<FrequencyFitParam[]>("--fit", fitSpec, "a comma list of damping, responsive, governor (each at most once)");
    // --max-iter: the optimiser's iteration cap. Absent: the optimiser's own default (null options, exactly Fit's default).
    GridSim.Core.Numerics.NelderMead.Options? optimiser = null;
    if (a.Contains("--max-iter"))
    {
        int maxIter = FlagInt(a, "--max-iter", 0);
        if (maxIter < 1) FailFlag<int>("--max-iter", maxIter.ToString(inv), "at least 1");
        optimiser = new GridSim.Core.Numerics.NelderMead.Options { MaxIterations = maxIter };
    }

    string? tracePath = SingleFilePositional("fit-frequency", a);
    if (tracePath is null)
    {
        Console.Error.WriteLine("error: fit-frequency needs a trace file: gridsim fit-frequency <trace.csv> --inertia <GVA.s> --demand <MW> --loss <MW>.");
        Environment.Exit(CliExit.Usage);
    }

    // N314 (LF5): --nominal-hz <Hz> declares the trace's nominal frequency; absent, the trace's first sample names it (50 or
    // 60 Hz, FrequencyTraceFile.StandardNominalsHz). The value must be finite and above 5 Hz (the accepted band nominal
    // +/- 5 Hz must stay above 0 Hz): a usage error otherwise (exit 2), before the trace is read.
    double? nominalGiven = null;
    if (a.Contains("--nominal-hz"))
    {
        double nominalFlag = FlagDouble(a, "--nominal-hz", double.NaN);
        if (!FrequencyTraceFile.IsAcceptableNominal(nominalFlag))
            FailFlag<double>("--nominal-hz", nominalFlag.ToString("R", inv), "a finite nominal frequency above 5 Hz (for example 50 or 60)");
        nominalGiven = nominalFlag;
    }

    IReadOnlyList<FrequencyTraceSample> trace;
    double traceNominalHz;
    try { trace = FrequencyTraceFile.Read(tracePath!, nominalGiven, out traceNominalHz); }
    catch (Exception ex) when (ex is InvalidDataException or FileNotFoundException or DirectoryNotFoundException or IOException or UnauthorizedAccessException)
    {
        Console.Error.WriteLine($"error: fit-frequency: {ex.Message}");
        Environment.Exit(CliExit.InputError);
        return;
    }
    if (!(lossAt < trace[^1].Seconds))
    {
        Console.Error.WriteLine($"error: fit-frequency: --loss-at {lossAt.ToString("R", inv)} s is not before the last sample "
            + $"({trace[^1].Seconds.ToString("R", inv)} s), so the trace holds no response to the loss to fit.");
        Environment.Exit(CliExit.Usage);
    }

    double? preEventHz = FrequencyFitCli.PreEventHz(trace, lossAt);
    // N314: the seed runs at the trace's nominal (at 50 Hz exactly the old seed: the default nominal is the same 50.0).
    DynamicsConfig seed = FrequencyFitCli.Seed(preEventHz, traceNominalHz);
    FrequencyFitResult fit = FrequencyConstantsFitter.Fit(
        inertiaGvaS * 1000.0, demandMw, new FrequencyEvent(lossAt, -lossMw), trace, seed, which, optimiser);

    double measuredNadir = trace.Min(s => s.Hz);
    Console.WriteLine($"GridSim  -  FREQUENCY CONSTANTS FIT (lumped swing model)  *  {Path.GetFileName(tracePath)}");
    Console.WriteLine(new string('=', 66));
    Console.WriteLine($"Event:   {lossMw.ToString("R", inv)} MW lost at {lossAt.ToString("R", inv)} s  *  inertia {inertiaGvaS.ToString("R", inv)} GVA.s  *  "
        + $"demand {demandMw.ToString("R", inv)} MW  *  nominal {seed.NominalHz.ToString("R", inv)} Hz");
    Console.WriteLine($"Trace:   {trace.Count} samples, {trace[0].Seconds.ToString("R", inv)} to {trace[^1].Seconds.ToString("R", inv)} s, "
        + $"measured nadir {measuredNadir.ToString("R", inv)} Hz");
    Console.WriteLine(preEventHz is double pre
        ? $"Start:   pre-event {pre.ToString("R", inv)} Hz (the last sample before the loss; the model starts in equilibrium there)"
        : $"Start:   nominal {seed.NominalHz.ToString("R", inv)} Hz (no sample before the loss)");
    Console.WriteLine();
    Console.WriteLine($"{"Constant",-30}{"seed",12}  {"result",-24}");
    void Row(string name, double seedValue, double value, FrequencyFitParam p) =>
        Console.WriteLine($"{name,-30}{seedValue.ToString("R", inv),12}  {value.ToString("R", inv),-24}{(which.Contains(p) ? "fitted" : "held")}");
    Row("damping (% of demand per Hz)", seed.DampingPctPerHz, fit.DampingPctPerHz, FrequencyFitParam.Damping);
    Row("responsive fraction", seed.ResponsiveFraction, fit.ResponsiveFraction, FrequencyFitParam.ResponsiveFraction);
    Row("governor time constant (s)", seed.GovernorTimeConstantS, fit.GovernorTimeConstantS, FrequencyFitParam.GovernorTimeConstant);
    Console.WriteLine();
    Console.WriteLine($"Fit:     RMS error {fit.RmsErrorHz.ToString("R", inv)} Hz over {trace.Count} samples  *  nadir error "
        + $"{fit.NadirErrorHz.ToString("R", inv)} Hz (simulated - measured)  *  {fit.Evaluations} evaluations");
    if (which.Length > 1)
        Console.WriteLine("Note:    fitting more than one constant from ONE trace is weakly identified (they trade off against each other); "
            + "take the responsive headroom and governor lag from the operational record where possible and fit damping alone.");
    Console.WriteLine("Provenance: a fit of the lumped swing model to this one trace. The shipped defaults are unchanged; adopting a "
        + "fitted value is a separate, deliberate step.");
    if (!fit.Converged)
    {
        // Fail loud: the optimiser's last point is shown for diagnosis, never reported as a fit.
        Console.Error.WriteLine($"fit-frequency: NOT CONVERGED after {fit.Evaluations} evaluations (iteration cap "
            + $"{(optimiser ?? new GridSim.Core.Numerics.NelderMead.Options()).MaxIterations}); the values above are the optimiser's last point, not a fit. "
            + "Raise --max-iter or fit fewer constants.");
        Environment.ExitCode = CliExit.Verdict;
    }
}

int DefaultFaultBus(GridModel model)
{
    var genBuses = new HashSet<int>();
    foreach (Generator gg in model.Generators) genBuses.Add(gg.Bus);
    foreach (Bus b in model.Buses) if (!genBuses.Contains(b.Id)) return b.Id;
    return model.Buses[0].Id;
}

void RunTrip(GridModel model, string? genName, string? exportPath)
{
    int slackBus = model.Buses.First(b => b.Type == BusType.Slack).Id;
    Generator gen;
    if (genName != null)
    {
        // A misspelled name must NOT silently fall back to the largest unit - that "succeeds" answering a
        // different question. Fail loud so the caller knows their contingency never ran.
        // GR-216: an exact (case-insensitive) name wins; otherwise the substring must pick ONE generator. It used to trip
        // the first of several matches ("Heysham" with "Heysham 1" and "Heysham 2" tripped Heysham 1, exit 0).
        List<Generator> exactNamed = model.Generators.Where(g => string.Equals(g.Name, genName, StringComparison.OrdinalIgnoreCase)).ToList();
        List<Generator> genMatches = exactNamed.Count > 0 ? exactNamed
            : model.Generators.Where(g => (g.Name ?? "").Contains(genName, StringComparison.OrdinalIgnoreCase)).ToList();
        if (genMatches.Count > 1)
        {
            Console.Error.WriteLine($"error: trip '{genName}' matches {genMatches.Count} generators in {model.Name}: " +
                string.Join(", ", genMatches.Select(g => g.Name).Take(20)) + (genMatches.Count > 20 ? ", ..." : "") +
                ". Give a name that picks one.");
            Environment.Exit(2);
        }
        Generator? match = genMatches.Count == 1 ? genMatches[0] : null;
        if (match is null)
        {
            Console.Error.WriteLine($"error: trip '{genName}' matched no generator in {model.Name}. Available: " +
                string.Join(", ", model.Generators.Select(g => g.Name).Where(nm => !string.IsNullOrWhiteSpace(nm)).Take(20)));
            Environment.Exit(2);
        }
        gen = match!;
    }
    else
    {
        // No eligible unit (only the slack, or an all-inverter/H=0 fleet - e.g. a GDA replica whose only
        // source is the grid infeed): fail loud like the misspelled-name path, don't throw a raw stack trace.
        Generator? auto = model.Generators.Where(g => g.Bus != slackBus && g.H > 0).OrderByDescending(g => g.Pg).FirstOrDefault();
        if (auto is null)
        {
            Console.Error.WriteLine($"error: trip found no eligible generator to trip in {model.Name} " +
                "(no non-slack synchronous unit). Name one explicitly, or trip a different model.");
            Environment.Exit(2);
        }
        gen = auto!;
    }

    // D-DOC-029 (October 2026, docs-session finding), part 1: --asset-dynamics on a case with no asset bundle (no
    // asset-classes.json / asset-bindings.json and no protections.json; data/uk, the built-in IEEE cases and the generated
    // 'gb-synthetic' name) was silently ignored and the run looked like an asset-dynamics run. Refused, exit 1.
    if (enableAssetDynamics && model.AssetDynamics is null && model.Protections is null)
    {
        Console.Error.WriteLine($"error: trip --asset-dynamics needs a case with an asset bundle (asset-classes.json and " +
            $"asset-bindings.json, or protections.json), and {model.Name} has none, so the flag would do nothing. " +
            "Use a case folder that ships one (for example --dir data/gb-synthetic or gb-full).");
        Environment.Exit(CliExit.InputError);
    }
    // D-DOC-029, part 2: with both --asset-dynamics and --inertia-model distributed, the asset path ran first and the
    // distributed model was dropped without a word (the multi-domain swing carries no asset fleet yet: that is the B1/B2
    // frequency streams' work). Refuse the combination, exit 2, rather than answer a different question.
    if (enableAssetDynamics && inertiaModel == InertiaModel.Distributed)
    {
        Console.Error.WriteLine("error: trip: --asset-dynamics and --inertia-model distributed cannot be combined yet: the distributed " +
            "multi-domain model carries no asset fleet, so one of the two would be silently dropped. Run them separately.");
        Environment.Exit(CliExit.Usage);
    }

    // R095 (stream F): --envelope is checked against THIS case's asset-dynamics class library before anything is printed: a
    // case whose bundle holds protections only has no class to sweep (exit 1, as for --asset-dynamics on a case without a
    // bundle); an item naming an unknown class or a parameter its kind is not simulated with, a bad range, a repeat or more
    // than 12 items is a usage error (exit 2), named.
    IReadOnlyList<AssetSweepParam>? envelope = null;
    if (tripEnvelopeSpec is not null)
    {
        if (model.AssetDynamics is null)
        {
            Console.Error.WriteLine($"error: trip --envelope sweeps the classes of asset-classes.json, and {model.Name} has protection devices only "
                + "(no asset-classes.json / asset-bindings.json), so there is nothing to sweep.");
            Environment.Exit(CliExit.InputError);
        }
        envelope = AssetEnvelopeSpec.Parse(tripEnvelopeSpec, model.AssetDynamics!.Library, out string? envelopeError);
        if (envelope is null)
        {
            Console.Error.WriteLine($"error: trip: {envelopeError}");
            Environment.Exit(CliExit.Usage);
        }
    }

    // N314 (LF5, October 2026; Ruling R1: Mark delegated EE calls 2026-10-04): the trip's system inertia is the N289 total
    // (GridModel.SystemInertiaMwS: only rotating mass counts; a unit whose type is a known converter technology adds
    // nothing, whatever H its data carries), the same total the lumped model, the distributed model and the asset fleet
    // already use. It used to be the sum of H x MBase over EVERY unit, so a converter-typed unit with H > 0 gave the trip
    // more inertia than every other engine. The tripped unit takes out only what it put in (RotatingInertiaMwS: 0 for a
    // converter). For every model with no converter-typed unit carrying H > 0 (every bundled case: data/gb-full and
    // data/gb-synthetic checked by type at R239 / N289; the MATPOWER cases have no types) both sums run over exactly the
    // same terms in the same order, so every printed number is bit-for-bit unchanged.
    double totalInertia = model.SystemInertiaMwS;  // MWs
    double remaining = Math.Max(1, totalInertia - GridModel.RotatingInertiaMwS(gen)); // tripped unit stops spinning
    double demand = model.Buses.Sum(b => b.Pd);
    double lost = gen.Pg;

    var cfg = new DynamicsConfig
    {
        // R196 remainder (D2 nominal frequency, October 2026; Ruling R1: Mark delegated EE calls 2026-10-04): the trip runs
        // at THIS model's nominal frequency. RoCoF = f0 * deltaP / (2E), so a 60 Hz case (the WSCC 9-bus, N017) run at the
        // config's GB default 50 Hz reported a RoCoF 1/1.2 of the true figure and a trajectory about 50 Hz. For every
        // 50 Hz model this is the default's own 50.0, so the run is bit-identical.
        NominalHz = model.FrequencyHz,
        InertiaModel = inertiaModel,
        EnableAssetDynamics = enableAssetDynamics,
        Forming = formingMode,
        VirtualInertiaMwS = formingInertiaMwS,
        FormingDampingMwPerHz = formingDampingMwPerHz,
    };
    // D-DOC-185 (October 2026, docs-session finding): GbResponseServices.Typical (the grounded GB DC / DM / DR arrest layer,
    // 950 / 520 / 490 MW) was applied by no verb. 'trip --gb-services[=<scale>]' now adds it, scaled, ON TOP OF the generic
    // governor term: the governor stands for the synchronous fleet's mandatory primary response, which a GB dispatch still
    // carries beside the procured EAC services (EE call, recorded in the DOC-5 notes; whether a modern GB dispatch should
    // drop the generic term is the B4 frequency stream's question). Off by default: without the flag the config is the
    // one above, bit for bit.
    if (gbServicesScale is { } gbScale)
        cfg = cfg with { SystemResponseServices = GbResponseServices.Typical(gbScale) };
    var ev = new[] { new FrequencyEvent(FrequencyDynamics.DesignEventSeconds, -lost) };   // trip at t = 1 s (R171: shared name)
    FrequencyResponse resp;
    // N158: the shared post-trip copy (keeps out-of-service units; same in-service list as the old hand-built copy). Built
    // once here, so the asset-fleet run below and the --envelope sweep (R095) solve exactly the same post-trip model.
    GridModel postTripModel = PostTripModel.Without(model, gen);
    if (enableAssetDynamics && (model.AssetDynamics is not null || model.Protections is not null))
    {
        // Authored per-asset fleet: run the lumped COI solve WITH the pAssetFleet term (inverter FFR +
        // Loss-of-Mains trips). The tripped synchronous unit's inertia/output are already reflected in
        // 'remaining'/'lost'; the fleet adds the inverter-fleet response and any RoCoF-trip cascade.
        AssetFrequencyResult ar = AssetFrequencyDynamics.Simulate(postTripModel, demand, ev, cfg);
        resp = ar.Response;
        if (enableAssetDynamics)
        {
            int classCount = postTripModel.AssetDynamics?.Library.Count ?? postTripModel.Protections?.Library.Count ?? 0;
            int protCount = postTripModel.Protections?.Instances.Count ?? 0;
            // D-DOC-161 (October 2026, docs-session finding): the label said "MW lost to LoM" for EVERY infeed trip, though
            // the total also holds protection-device operations (under-frequency, over-voltage, any stage of a placed
            // device) and inverter ride-through trips. The trips are now split by who tripped: the inverters bound to
            // generators (Loss-of-Mains RoCoF / vector shift, or under-voltage ride-through) and the placed protection
            // devices. The numbers are the same totals as before (count and MW), only attributed.
            Console.WriteLine($"Asset dynamics: on  ({classCount} class(es), {protCount} protection(s); " +
                $"{ar.TrippedCount} unit(s) tripped, {ar.TotalTrippedMw:F0} MW of infeed lost: " +
                $"{ar.InverterTrippedCount} inverter(s) {ar.InverterTrippedMw:F0} MW (Loss-of-Mains or ride-through), " +
                $"{ar.ProtectionTrippedCount} protection device(s) {ar.ProtectionTrippedMw:F0} MW)");
            // D-DOC-038: the lumped COI path solves no network, so a voltage or loading stage cannot be evaluated here.
            if (ar.NetworkStageAssetCount > 0)
                Console.WriteLine($"  note: {ar.NetworkStageAssetCount} asset(s) carry voltage or loading trip stages (LVRT, under- / over-" +
                    "voltage, overload); this lumped run solves no network, so those stages are not evaluated (transient and the " +
                    "live views evaluate them against the solved state).");
        }
    }
    else if (inertiaModel == InertiaModel.Distributed)
    {
        // Run the multi-domain model on the post-trip network (drop the tripped unit) and report the COI.
        // N158: the shared post-trip copy. It now also keeps out-of-service units and carries the asset bundle and the
        // protections (this hand-built copy dropped them); the distributed model reads neither, so the run is unchanged.
        GridModel postTrip = PostTripModel.Without(model, gen);
        var im = new DistributedInertiaModel();
        // R060 (October 2026, stream B1; Ruling R1): the loss is placed at the tripped unit's bus. Before, every loss landed on
        // the speed domain with the largest total MVA, whichever unit tripped; the multi-domain model now puts it on the
        // domain whose machines remain at that bus, or shares it by synchronising coupling when the tripped unit was the
        // bus's only machine (it no longer spins in the post-trip model). The centre-of-inertia numbers do not depend on it.
        FrequencyEvent[] evAtBus = ev.Select(x => x with { AtBus = gen.Bus }).ToArray();
        resp = im.Simulate(postTrip, demand, evAtBus, cfg);
        if (im.LastDistributedResult is { } dr)
        {
            Console.WriteLine($"Inertia model:  distributed  ({dr.Domains.Count} speed domain(s), dGVa {dr.Dominance.DeltaGVa:F2})");
            if (dr.EventPlacements is { Count: > 0 } placed)
                Console.WriteLine($"Loss placed:    {placed[0].Rule}");
            // R025 (October 2026, stream B1): printed only when the inter-domain coupling is the uniform heuristic, so a
            // network-derived run's output is unchanged and a heuristic one no longer looks network-derived.
            if (dr.Coupling is { IsHeuristic: true } heuristic)
                Console.WriteLine($"Coupling:       NOT network-derived: {heuristic.Reason}");
        }
    }
    else
    {
        resp = FrequencyDynamics.Simulate(remaining, demand, ev, cfg);
    }

    Console.WriteLine($"GridSim  -  contingency on {model.Name}");
    Console.WriteLine(new string('=', 64));
    if (tripMachineDataLine is not null) Console.WriteLine(tripMachineDataLine);   // F stream: --dyn-data only
    if (gbServicesScale is { } gbShown)
        Console.WriteLine($"Response:       GB DC / DM / DR at {gbShown:0.###} x the EAC volumes ({GbResponseServices.DynamicContainmentMw * gbShown:F0} / " +
            $"{GbResponseServices.DynamicModerationMw * gbShown:F0} / {GbResponseServices.DynamicRegulationMw * gbShown:F0} MW) on top of the generic governor (--gb-services)");
    Console.WriteLine($"Tripped:        {gen.Name ?? $"generator @ bus {gen.Bus}"}  ({lost:F0} MW lost, {gen.Type})");
    Console.WriteLine($"System inertia: {totalInertia / 1000:F1} -> {remaining / 1000:F1} GVAs after the trip");
    // FrequencyResponse.InitialRocofHzPerS is the largest-magnitude df/dt over the whole run (the integrator keeps
    // the peak), not a value read at t = 0+. For a single trip with no forming or asset fleet the two coincide (the
    // spike is the first post-trip step), but with --asset-dynamics or --forming a later step can be steeper. The
    // label used to say "Initial"; it now says what the number is.
    Console.WriteLine($"Peak RoCoF:     {resp.InitialRocofHzPerS:F3} Hz/s  (largest |df/dt| over the run)");
    Console.WriteLine($"Nadir:          {resp.NadirHz:F3} Hz  (t+{resp.NadirSeconds - FrequencyDynamics.DesignEventSeconds:F1} s)");   // GR-673: the trip instant by name
    Console.WriteLine($"Settling:       {resp.SettleHz:F3} Hz");
    Console.WriteLine();
    Console.WriteLine(Sparkline(resp.Points, cfg.NominalHz));
    Console.WriteLine();

    FrequencyResponse low = FrequencyDynamics.Simulate(remaining / 2, demand, ev, cfg);
    Console.WriteLine($"...at HALF the inertia ({remaining / 2000:F1} GVAs): RoCoF {low.InitialRocofHzPerS:F3} Hz/s, nadir {low.NadirHz:F3} Hz");

    // R079 (October 2026, stream F front doors; Ruling R1): --band, the uncertainty band of THIS trip's nadir over the swing
    // constants that are literature-typical and not fitted to GB data (DynamicsConfig: DampingPctPerHz, ResponsiveFraction,
    // GovernorTimeConstantS). FrequencySensitivitySweep runs the same lumped model with the same inertia, demand, loss and
    // config as the run above; its nominal run IS that run, and that is checked bit for bit (a mismatch would mean the band
    // describes another model: a defect, so it throws). Printed after the half-inertia line, so every line above is unchanged.
    if (tripBandFraction is double band)
    {
        FrequencySensitivityResult sr = FrequencySensitivitySweep.Sweep(remaining, demand, ev, cfg, band);
        if (!sr.Nominal.NadirHz.Equals(resp.NadirHz) || !sr.Nominal.InitialRocofHzPerS.Equals(resp.InitialRocofHzPerS))
            throw new InvalidOperationException("trip --band: the sweep's nominal run differs from the trip run "
                + $"(nadir {resp.NadirHz:R} vs {sr.Nominal.NadirHz:R} Hz); the band would describe another model.");
        Console.WriteLine();
        Console.WriteLine($"Uncertainty band (--band {band:0.###}): the unfitted swing constants each +/- {band * 100:0.#} % (literature-typical, not fitted to GB data):");
        Console.WriteLine($"  nadir over every corner:  {sr.NadirMinHz:F3} .. {sr.NadirMaxHz:F3} Hz (width {sr.NadirBandHz:F3} Hz); "
            + $"peak RoCoF band {sr.InitialRocofBandHzPerS:F3} Hz/s (inertia and the loss set the RoCoF, not these constants)");
        Console.WriteLine("  one at a time, most leverage first:");
        foreach (ParameterSensitivity ps in sr.PerParameter)
        {
            string name = ps.Parameter switch
            {
                FrequencyFitParam.Damping => "load damping (%/Hz)",
                FrequencyFitParam.ResponsiveFraction => "responsive fraction",
                _ => "governor time constant (s)",
            };
            Console.WriteLine($"    {name,-28}{ps.LowValue,8:0.####} -> {ps.HighValue,-8:0.####}  nadir {ps.NadirAtLow:F3} -> {ps.NadirAtHigh:F3} Hz  (swing {ps.NadirSwingHz:F3} Hz)");
        }
        Console.WriteLine("  (fit them to a measured trace with gridsim fit-frequency)");
    }

    // R095 (October 2026, stream F front doors; Ruling R1): --envelope, the parameter-sweep ENVELOPE of this trip over the
    // asset fleet's unmeasurable control parameters (AssetEnvelope.Sweep): every corner of the given ranges (2^k runs),
    // then a one-at-a-time tornado (each parameter low and high, the others at their midpoints). It runs the same lumped
    // asset-fleet solve as the run above (AssetFrequencyDynamics.Simulate on the post-trip model, the same demand, loss and
    // config). Printed after the half-inertia line, so every line above is unchanged. The result is tagged
    // UnvalidatedAtScale by Core, and said so.
    if (envelope is not null)
    {
        AssetEnvelopeResult env;
        try { env = AssetEnvelope.Sweep(postTripModel, demand, ev, cfg, envelope); }
        catch (InvalidDataException ex)
        {
            // A swept value the class checks refuse (R073 / N304: the library is re-checked for every corner).
            Console.Error.WriteLine($"error: trip --envelope: a swept value is refused by the asset-class checks: {ex.Message}");
            Environment.Exit(CliExit.Usage);
            return;
        }
        int k = envelope.Count;
        Console.WriteLine();
        Console.WriteLine($"Asset envelope (--envelope, {k} parameter(s): {env.Samples.Count} corner run(s) + {2 * k} tornado run(s); provenance {env.Provenance}):");
        Console.WriteLine($"  nadir:       {env.NadirMinHz:F3} .. {env.NadirMedianHz:F3} (median) .. {env.NadirMaxHz:F3} Hz");
        Console.WriteLine($"  peak RoCoF:  {env.RocofMinHzPerS:F3} .. {env.RocofMaxHzPerS:F3} Hz/s");
        int tripping = env.Samples.Count(s => s.TrippedCount > 0);
        Console.WriteLine("  cascade:     " + (env.CascadeIsPossible
            ? $"POSSIBLE: {tripping} of {env.Samples.Count} corners trip infeed and the rest do not; the data cannot resolve which (that is the finding)"
            : tripping == 0 ? "none: no corner trips any infeed" : "in every corner: infeed trips whatever the swept values"));
        Console.WriteLine("  tornado (each parameter low -> high, the others at their midpoints; most leverage first):");
        foreach (TornadoEntry te in env.Tornado)
        {
            AssetSweepParam sp = envelope.First(p => p.ClassName == te.ClassName && p.ParamName == te.ParamName);
            Console.WriteLine($"    {te.ClassName + ":" + te.ParamName,-44}{sp.Low,8:0.####} -> {sp.High,-8:0.####}  nadir {te.NadirAtLow:F3} -> {te.NadirAtHigh:F3} Hz  (swing {te.NadirSwingHz:F3} Hz)");
        }
    }

    // D-DOC-220 (October 2026): the system frequency elements (81U, 81O, 81R RoCoF, 78 vector shift) assessed on THIS
    // run's trajectory, with the generic / G99 settings protection-check uses. No code built a ProtectionTrajectory
    // before, so 81R and 78 were "not evaluated" on every run. 78 stays not checkable here: the run is a
    // centre-of-inertia frequency trajectory with no bus voltage angle. Informational: the exit code is unchanged.
    // D2 (N017): the trajectory ran about cfg.NominalHz (the model's frequency); the G99 81U / 81O pickups are for 50 Hz,
    // so on a 60 Hz case they are reported not-checkable rather than operating on the healthy 60 Hz start.
    GridSim.Core.Protection.ProtectionReport trajRep = GridSim.Core.Protection.ProtectionAssessment.AssessTrajectory(
        GridSim.Core.Protection.ProtectionTrajectory.FromFrequencyResponse(resp), settings: null, systemNominalHz: cfg.NominalHz);
    Console.WriteLine();
    Console.WriteLine("Frequency protection on this trajectory (G99 Issue 2 Table 10.1 settings; system-wide, not per site):");
    foreach (GridSim.Core.Protection.RelayVerdict v in trajRep.Verdicts)
        Console.WriteLine($"  {v.Device,-4} {v.Function,-20} "
            + (v.Confidence == GridSim.Core.Protection.ProtectionConfidence.NotCheckable ? "not evaluated: " : v.Operate ? "WOULD OPERATE: " : "holds: ")
            + v.Basis);

    if (!string.IsNullOrEmpty(exportPath))
    {
        // D-DOC-176: through the one output policy, which creates a missing parent folder (this write used to fail on one).
        using var w = new StreamWriter(CliFiles.Output(exportPath, "trip trajectory CSV"));
        w.WriteLine("dtm,f");
        foreach (FrequencyPoint p in resp.Points) w.WriteLine($"{p.Time:yyyy-MM-dd HH:mm:ss.fff},{p.Hz:F5}");
        Console.WriteLine($"Trajectory -> {Path.GetFullPath(exportPath)}  (watch it: GridSim.Cli replay \"{exportPath}\")");
    }
}

static string Sparkline(IReadOnlyList<FrequencyPoint> pts, double f0)
{
    const string ramp = " .,:-=+*#";   // 9-level ASCII ramp; a bare " " rendered the trace blank
    int cols = Math.Min(64, pts.Count);
    double min = pts.Min(p => p.Hz);
    double max = Math.Max(f0 + 0.05, pts.Max(p => p.Hz));
    double range = Math.Max(1e-3, max - min);
    var sb = new System.Text.StringBuilder();
    for (int c = 0; c < cols; c++)
    {
        int idx = (int)((double)c / (cols - 1) * (pts.Count - 1));
        int lvl = (int)((pts[idx].Hz - min) / range * (ramp.Length - 1));
        sb.Append(ramp[Math.Clamp(lvl, 0, ramp.Length - 1)]);
    }
    return $"{max:F2} Hz |{sb}| {min:F2} Hz (nadir)";
}

static string Trunc(string s, int n) => s.Length <= n ? s : s[..(n - 1)] + "...";

// R254 (October 2026 review): the TSGB sizer now says whether its size holds the nadir target. An empty suffix when it
// does (so those lines are unchanged); otherwise a plain warning, because the numbers are then the largest device the
// search tried, not a device that secures the loss.
static string TsgbSizingShortfall(TsgbSizing s) =>
    s.Feasible ? "" : "  (NOT ACHIEVED: the nadir target is not met even at the largest size searched)";

// D-DOC-157 (October 2026): a branch's name for a table, or its end buses "from-to" when it has none (every MATPOWER
// branch, the built-in IEEE cases, cigre). Tables used to print an empty name for such a branch.
static string BranchDisplayName(string? name, int from, int to) => string.IsNullOrWhiteSpace(name) ? $"{from}-{to}" : name;
